-- ============================================================================
-- 图书馆样书 seed:The Adventures of Tom Sawyer (tom-sawyer)
-- 生成自 scripts/library/books/tom-sawyer.json —— node scripts/library/build-seed.mjs tom-sawyer
-- ⚠️ 内容(英文改写 + 中文)须先过审(Aaron/网页版 Claude)再落库(content-review-gate + D9)。
-- 幂等:upsert 书 + 删该书旧句重灌。BEGIN/COMMIT + 前后计数。
-- 章号真实(D12);共 35 章 / 5066 句。
-- ============================================================================

BEGIN;

-- 0) 章标题列(方案 A:jsonb,幂等加列)。[{idx,title_en,title_zh}] + visibility(私享层已建,防御性再保一次)。
ALTER TABLE public.library_books
  ADD COLUMN IF NOT EXISTS chapters jsonb NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE public.library_books
  ADD COLUMN IF NOT EXISTS visibility text NOT NULL DEFAULT 'public';

SELECT 'before' AS phase,
       (SELECT count(*) FROM public.library_books WHERE book_key = 'tom-sawyer') AS book_exists,
       (SELECT count(*) FROM public.library_sentences s
          JOIN public.library_books b ON b.id = s.book_id
         WHERE b.book_key = 'tom-sawyer') AS sentence_rows;

-- 1) 书目(upsert)
INSERT INTO public.library_books
  (book_key, title, zh_title, author, age_band, age_range, cover,
   intro_en, intro_zh, sentence_count, copyright_note, chapters, is_published, visibility)
VALUES
  ('tom-sawyer', 'The Adventures of Tom Sawyer', '汤姆·索亚历险记', 'Mark Twain',
   '青少年', '12+', '{"c1":"#b45309","c2":"#78350f"}'::jsonb,
   'A boy in a sleepy Mississippi River town paints a fence, hunts for treasure, runs off to be a pirate, and stumbles into real danger. Mark Twain’s 1876 classic of mischief, friendship, and growing up.', '密西西比河边一个昏昏欲睡的小镇上,一个男孩刷篱笆、寻宝藏、离家去当“海盗”,还意外卷进真正的险境。马克·吐温 1876 年的经典,写顽皮、友情与长大。', 5066, '公有领域 · Mark Twain, 1876 · 文本来源 Project Gutenberg (#74)',
   '[{"idx":1,"title_en":"Chapter 1","title_zh":"第1章"},{"idx":2,"title_en":"Chapter 2","title_zh":"第2章"},{"idx":3,"title_en":"Chapter 3","title_zh":"第3章"},{"idx":4,"title_en":"Chapter 4","title_zh":"第4章"},{"idx":5,"title_en":"Chapter 5","title_zh":"第5章"},{"idx":6,"title_en":"Chapter 6","title_zh":"第6章"},{"idx":7,"title_en":"Chapter 7","title_zh":"第7章"},{"idx":8,"title_en":"Chapter 8","title_zh":"第8章"},{"idx":9,"title_en":"Chapter 9","title_zh":"第9章"},{"idx":10,"title_en":"Chapter 10","title_zh":"第10章"},{"idx":11,"title_en":"Chapter 11","title_zh":"第11章"},{"idx":12,"title_en":"Chapter 12","title_zh":"第12章"},{"idx":13,"title_en":"Chapter 13","title_zh":"第13章"},{"idx":14,"title_en":"Chapter 14","title_zh":"第14章"},{"idx":15,"title_en":"Chapter 15","title_zh":"第15章"},{"idx":16,"title_en":"Chapter 16","title_zh":"第16章"},{"idx":17,"title_en":"Chapter 17","title_zh":"第17章"},{"idx":18,"title_en":"Chapter 18","title_zh":"第18章"},{"idx":19,"title_en":"Chapter 19","title_zh":"第19章"},{"idx":20,"title_en":"Chapter 20","title_zh":"第20章"},{"idx":21,"title_en":"Chapter 21","title_zh":"第21章"},{"idx":22,"title_en":"Chapter 22","title_zh":"第22章"},{"idx":23,"title_en":"Chapter 23","title_zh":"第23章"},{"idx":24,"title_en":"Chapter 24","title_zh":"第24章"},{"idx":25,"title_en":"Chapter 25","title_zh":"第25章"},{"idx":26,"title_en":"Chapter 26","title_zh":"第26章"},{"idx":27,"title_en":"Chapter 27","title_zh":"第27章"},{"idx":28,"title_en":"Chapter 28","title_zh":"第28章"},{"idx":29,"title_en":"Chapter 29","title_zh":"第29章"},{"idx":30,"title_en":"Chapter 30","title_zh":"第30章"},{"idx":31,"title_en":"Chapter 31","title_zh":"第31章"},{"idx":32,"title_en":"Chapter 32","title_zh":"第32章"},{"idx":33,"title_en":"Chapter 33","title_zh":"第33章"},{"idx":34,"title_en":"Chapter 34","title_zh":"第34章"},{"idx":35,"title_en":"Chapter 35","title_zh":"第35章"}]'::jsonb, true, 'private')
ON CONFLICT (book_key) DO UPDATE SET
  title          = EXCLUDED.title,
  zh_title       = EXCLUDED.zh_title,
  author         = EXCLUDED.author,
  age_band       = EXCLUDED.age_band,
  age_range      = EXCLUDED.age_range,
  cover          = EXCLUDED.cover,
  intro_en       = EXCLUDED.intro_en,
  intro_zh       = EXCLUDED.intro_zh,
  sentence_count = EXCLUDED.sentence_count,
  copyright_note = EXCLUDED.copyright_note,
  chapters       = EXCLUDED.chapters;
  -- 注:不覆盖 is_published / visibility —— 审后手动置 true / 由 private 翻 public,重灌 seed 不会把它们打回。

-- 2) 句子(删旧重灌,幂等)。audio_url 留 NULL:默认前端实时合成,预生成脚本审后另回填。
DELETE FROM public.library_sentences
 WHERE book_id = (SELECT id FROM public.library_books WHERE book_key = 'tom-sawyer');

INSERT INTO public.library_sentences (book_id, chapter_idx, para_idx, seq, text_en, text_cn)
SELECT b.id, v.chapter_idx, v.para_idx, v.seq, v.text_en, v.text_cn
FROM public.library_books b
CROSS JOIN (VALUES
    (1, 1, 1, '“Tom!”', '“汤姆！”'),
    (1, 2, 2, 'No answer.', '没人应声。'),
    (1, 3, 3, '“TOM!”', '“汤姆！”'),
    (1, 4, 4, 'No answer.', '没人应声。'),
    (1, 5, 5, '“What’s gone with that boy, I wonder?', '“那孩子跑哪去了？汤姆，你快出来！”'),
    (1, 5, 6, 'You TOM!”', '你，汤姆！”'),
    (1, 6, 7, 'No answer.', '没人应声。'),
    (1, 7, 8, 'The old lady pulled her spectacles down and looked over them about the room; then she put them up and looked out under them.', '老奶奶把眼镜拉下来，从上面看屋子里。然后她又把眼镜推上去，从下面往外看。'),
    (1, 7, 9, 'She seldom or never looked _through_ them for so small a thing as a boy; they were her state pair, the pride of her heart, and were built for “style,” not service—she could have seen through a pair of stove-lids just as well.', '她从来不用这副眼镜看东西，尤其是找小男孩。因为这眼镜只是好看的，不是用来真看的。'),
    (1, 7, 10, 'She looked perplexed for a moment, and then said, not fiercely, but still loud enough for the furniture to hear:', '她愣了一下，有点儿没明白。然后她大声说，声音大得屋子里的家具都听得见：'),
    (1, 8, 11, '“Well, I lay if I get hold of you I’ll—”', '“哼，要是被我抓住，看我怎么收拾你——”'),
    (1, 9, 12, 'She did not finish, for by this time she was bending down and punching under the bed with the broom, and so she needed breath to punctuate the punches with.', '她话没说完，因为她弯腰用扫帚往床底下捅，捅一下就要喘口气。'),
    (1, 9, 13, 'She resurrected nothing but the cat.', '她什么也没捅出来，只有一只猫。'),
    (1, 10, 14, '“I never did see the beat of that boy!”', '“我从没见过这么调皮的孩子！”'),
    (1, 11, 15, 'She went to the open door and stood in it and looked out among the tomato vines and “jimpson” weeds that constituted the garden.', '她走到开着的门口，站在那儿往外看。外面是花园，有西红柿和一些杂草。'),
    (1, 11, 16, 'No Tom.', '没看到汤姆。'),
    (1, 11, 17, 'So she lifted up her voice at an angle calculated for distance and shouted:', '于是她大声喊起来，声音传得很远：'),
    (1, 12, 18, '“Y-o-u-u TOM!”', '“你——汤——姆——！”'),
    (1, 13, 19, 'There was a slight noise behind her and she turned just in time to seize a small boy by the slack of his roundabout and arrest his flight.', '她身后传来一点声音，她一转身，正好抓住一个小男孩的衣服，没让他跑掉。'),
    (1, 14, 20, '“There!', '“抓到你了！'),
    (1, 14, 21, 'I might ’a’ thought of that closet.', '我早该想到那个柜子了。'),
    (1, 14, 22, 'What you been doing in there?”', '你在里面干什么呢？”'),
    (1, 15, 23, '“Nothing.”', '“什么也没干。”'),
    (1, 16, 24, '“Nothing!', '“什么也没干？！看看你的手，再看看你的嘴。这到底是什么呀？”'),
    (1, 16, 25, 'Look at your hands.', '看看你的手。'),
    (1, 16, 26, 'And look at your mouth.', '再看看你的嘴巴。'),
    (1, 16, 27, 'What _is_ that truck?”', '那是什么卡车呀？'),
    (1, 17, 28, '“I don’t know, aunt.”', '“我不知道，阿姨。”'),
    (1, 18, 29, '“Well, I know.', '“哼，我知道。'),
    (1, 18, 30, 'It’s jam—that’s what it is.', '是果酱——就是它！”'),
    (1, 18, 31, 'Forty times I’ve said if you didn’t let that jam alone I’d skin you.', '我跟你说了好多次，不许动果酱，不然我就要惩罚你！'),
    (1, 18, 32, 'Hand me that switch.”', '把那根小棍子给我。'),
    (1, 19, 33, 'The switch hovered in the air—the peril was desperate—', '小棍子举在空中，情况非常危险。'),
    (1, 20, 34, '“My!', '哎呀！'),
    (1, 20, 35, 'Look behind you, aunt!”', '姨妈，快看你身后！'),
    (1, 21, 36, 'The old lady whirled round, and snatched her skirts out of danger.', '老太太猛地转过身，赶紧把裙子拉开。'),
    (1, 21, 37, 'The lad fled on the instant, scrambled up the high board-fence, and disappeared over it.', '小男孩立刻就跑了，他爬上高高的木板围墙，一下子就翻了过去，不见了。'),
    (1, 22, 38, 'His aunt Polly stood surprised a moment, and then broke into a gentle laugh.', '他的姨妈波莉姨妈愣了一下，然后轻轻地笑了出来。'),
    (1, 23, 39, '“Hang the boy, can’t I never learn anything?', '哎呀这孩子，我怎么就学不乖呢？'),
    (1, 23, 40, 'Ain’t he played me tricks enough like that for me to be looking out for him by this time?', '他不是已经这样骗了我很多次了吗？我早该提防他了才对呀！'),
    (1, 23, 41, 'But old fools is the biggest fools there is.', '可是年纪大的人，有时就是最笨的。'),
    (1, 23, 42, 'Can’t learn an old dog new tricks, as the saying is.', '俗话说，老狗学不会新把戏。'),
    (1, 23, 43, 'But my goodness, he never plays them alike, two days, and how is a body to know what’s coming?', '可是天哪，他每天的鬼点子都不一样，我怎么知道他又要搞什么鬼呢？'),
    (1, 23, 44, 'He ’pears to know just how long he can torment me before I get my dander up, and he knows if he can make out to put me off for a minute or make me laugh, it’s all down again and I can’t hit him a lick.', '他好像知道他能把我气多久，也知道只要他能拖延我一分钟，或者把我逗笑，我就又下不了手打他了。'),
    (1, 23, 45, 'I ain’t doing my duty by that boy, and that’s the Lord’s truth, goodness knows.', '我没有好好管教这个孩子，天知道这是真的。'),
    (1, 23, 46, 'Spare the rod and spile the child, as the Good Book says.', '俗话说，不打不成器。'),
    (1, 23, 47, 'I’m a laying up sin and suffering for us both, I know.', '我知道我这样做，是在给我们俩都埋下祸根啊。'),
    (1, 23, 48, 'He’s full of the Old Scratch, but laws-a-me! he’s my own dead sister’s boy, poor thing, and I ain’t got the heart to lash him, somehow.', '他简直就是个小恶魔，可是哎呀！他是我的亲姐姐留下的孩子，真可怜，我怎么也舍不得打他呀。'),
    (1, 23, 49, 'Every time I let him off, my conscience does hurt me so, and every time I hit him my old heart most breaks.', '每次我放过他，我的良心就觉得不安；每次我打他，我的心都快碎了。'),
    (1, 23, 50, 'Well-a-well, man that is born of woman is of few days and full of trouble, as the Scripture says, and I reckon it’s so.', '唉，算了，人生在世，烦恼可真多啊，书上也是这么说的，我想确实是这样。'),
    (1, 23, 51, 'He’ll play hookey this evening,[*] and I’ll just be obleeged to make him work, tomorrow, to punish him.', '他今天下午肯定又会逃学了，所以我明天只好让他干活，来惩罚他。'),
    (1, 23, 52, 'It’s mighty hard to make him work Saturdays, when all the boys is having holiday, but he hates work more than he hates anything else, and I’ve _got_ to do some of my duty by him, or I’ll be the ruination of the child.”', '星期六让他干活可真难，因为所有的小朋友都在放假，但他最讨厌的就是干活。我必须好好管教他，不然我就毁了这个孩子了。'),
    (1, 24, 53, '[*] Southwestern for “afternoon”', '（这里的意思是“下午”）'),
    (1, 25, 54, 'Tom did play hookey, and he had a very good time.', '汤姆确实逃学了，而且玩得很开心。'),
    (1, 25, 55, 'He got back home barely in season to help Jim, the small colored boy, saw next-day’s wood and split the kindlings before supper—at least he was there in time to tell his adventures to Jim while Jim did three-fourths of the work.', '他刚赶回家，正好能帮小黑人男孩吉姆锯第二天的柴火，劈好引火柴，赶在晚饭前做完。至少他赶上了，可以把自己的冒险故事讲给吉姆听，而吉姆呢，则干了四分之三的活儿。'),
    (1, 25, 56, 'Tom’s younger brother (or rather half-brother) Sid was already through with his part of the work (picking up chips), for he was a quiet boy, and had no adventurous, trouble-some ways.', '汤姆的弟弟（或者说是同父异母的弟弟）希德已经把他的那份活儿（捡木屑）干完了，因为他是个安静的孩子，从不喜欢冒险，也不惹麻烦。'),
    (1, 26, 57, 'While Tom was eating his supper, and stealing sugar as opportunity offered, Aunt Polly asked him questions that were full of guile, and very deep—for she wanted to trap him into damaging revealments.', '当汤姆吃晚饭的时候，他一有机会就偷吃糖。这时，波莉姨妈问他一些很有心机、很深奥的问题，因为她想让他说漏嘴，说出那些对他不利的秘密。'),
    (1, 26, 58, 'Like many other simple-hearted souls, it was her pet vanity to believe she was endowed with a talent for dark and mysterious diplomacy, and she loved to contemplate her most transparent devices as marvels of low cunning.', '像许多心思单纯的人一样，她最喜欢觉得自己很有计谋，很会玩心眼，甚至觉得她那些一眼就能看穿的小把戏，都是很了不起的聪明才智。'),
    (1, 26, 59, 'Said she:', '她说道：'),
    (1, 27, 60, '“Tom, it was middling warm in school, warn’t it?”', '“汤姆，学校里是不是有点热呀？”'),
    (1, 28, 61, '“Yes’m.”', '“是的。”'),
    (1, 29, 62, '“Powerful warm, warn’t it?”', '“天气很热，是吗？”'),
    (1, 30, 63, '“Yes’m.”', '“是的。”'),
    (1, 31, 64, '“Didn’t you want to go in a-swimming, Tom?”', '“你不想去游泳吗，汤姆？”'),
    (1, 32, 65, 'A bit of a scare shot through Tom—a touch of uncomfortable suspicion.', '汤姆心里有点害怕，感觉有点不对劲。'),
    (1, 32, 66, 'He searched Aunt Polly’s face, but it told him nothing.', '他看着波莉姨妈的脸，但什么也没看出来。'),
    (1, 32, 67, 'So he said:', '他就说：'),
    (1, 33, 68, '“No’m—well, not very much.”', '“不是的——嗯，不太想。”'),
    (1, 34, 69, 'The old lady reached out her hand and felt Tom’s shirt, and said:', '老奶奶伸手摸了摸汤姆的衬衫，然后说：'),
    (1, 35, 70, '“But you ain’t too warm now, though.”', '“不过你现在倒是不热了。”'),
    (1, 35, 71, 'And it flattered her to reflect that she had discovered that the shirt was dry without anybody knowing that that was what she had in her mind.', '她心里很高兴，因为她发现衬衫是干的，而且没人知道她为什么摸衬衫。'),
    (1, 35, 72, 'But in spite of her, Tom knew where the wind lay, now.', '但是，汤姆还是明白了她的意思。'),
    (1, 35, 73, 'So he forestalled what might be the next move:', '于是他抢先一步说：'),
    (1, 36, 74, '“Some of us pumped on our heads—mine’s damp yet.', '“我们有的人用水浇了头，我的头现在还湿着呢。'),
    (1, 36, 75, 'See?”', '你瞧？”'),
    (1, 37, 76, 'Aunt Polly was vexed to think she had overlooked that bit of circumstantial evidence, and missed a trick.', '波莉姨妈有点不高兴，因为她没想到这一点，也错过了一个机会。'),
    (1, 37, 77, 'Then she had a new inspiration:', '接着她又想到了一个好主意：'),
    (1, 38, 78, '“Tom, you didn’t have to undo your shirt collar where I sewed it, to pump on your head, did you?', '“汤姆，你往头上浇水的时候，不用解开我缝好的衣领吧？'),
    (1, 38, 79, 'Unbutton your jacket!”', '解开你的外套！”'),
    (1, 39, 80, 'The trouble vanished out of Tom’s face.', '汤姆脸上的担心不见了。'),
    (1, 39, 81, 'He opened his jacket.', '他打开了外套。'),
    (1, 39, 82, 'His shirt collar was securely sewed.', '他的衬衫衣领缝得好好的。'),
    (1, 40, 83, '“Bother!', '“哎呀！'),
    (1, 40, 84, 'Well, go ’long with you.', '去吧。'),
    (1, 40, 85, 'I’d made sure you’d played hookey and been a-swimming.', '我还以为你肯定逃学去游泳了呢。'),
    (1, 40, 86, 'But I forgive ye, Tom.', '但这次我原谅你，汤姆。'),
    (1, 40, 87, 'I reckon you’re a kind of a singed cat, as the saying is—better’n you look.', '我觉得你呀，就像俗话说的，是个“外表不怎么样，其实很棒”的孩子。'),
    (1, 40, 88, '_This_ time.”', '就这一次哦。”'),
    (1, 41, 89, 'She was half sorry her sagacity had miscarried, and half glad that Tom had stumbled into obedient conduct for once.', '她有点遗憾自己没猜对，又有点高兴汤姆这次竟然乖乖听话了。'),
    (1, 42, 90, 'But Sidney said:', '但是西德尼说：'),
    (1, 43, 91, '“Well, now, if I didn’t think you sewed his collar with white thread, but it’s black.”', '嗯，我明明记得你用的是白线，怎么衣领现在是黑的呢？'),
    (1, 44, 92, '“Why, I did sew it with white!', '哎呀，我确实是用白线缝的！'),
    (1, 44, 93, 'Tom!”', '汤姆！'),
    (1, 45, 94, 'But Tom did not wait for the rest.', '但汤姆没有等他说完。'),
    (1, 45, 95, 'As he went out at the door he said:', '他出门的时候说：'),
    (1, 46, 96, '“Siddy, I’ll lick you for that.”', '“西迪，我会好好教训你的！”'),
    (1, 47, 97, 'In a safe place Tom examined two large needles which were thrust into the lapels of his jacket, and had thread bound about them—one needle carried white thread and the other black.', '在一个没人看见的地方，汤姆看了看他外套领子上的两根大针。针上缠着线，一根是白线，一根是黑线。'),
    (1, 47, 98, 'He said:', '他说：'),
    (1, 48, 99, '“She’d never noticed if it hadn’t been for Sid.', '“要不是希德，她根本不会发现。'),
    (1, 48, 100, 'Confound it! sometimes she sews it with white, and sometimes she sews it with black.', '真是的！她有时用白线缝，有时用黑线缝。'),
    (1, 48, 101, 'I wish to gee-miny she’d stick to one or t’other—I can’t keep the run of ’em.', '我真希望她能一直用一种颜色——我都搞不清了。'),
    (1, 48, 102, 'But I bet you I’ll lam Sid for that.', '但我敢打赌，我会好好揍希德一顿。'),
    (1, 48, 103, 'I’ll learn him!”', '我会教训他的！”'),
    (1, 49, 104, 'He was not the Model Boy of the village.', '他不是村子里的模范男孩。'),
    (1, 49, 105, 'He knew the model boy very well though—and loathed him.', '他虽然认识那个模范男孩——但很讨厌他。'),
    (1, 50, 106, 'Within two minutes, or even less, he had forgotten all his troubles.', '不到两分钟，甚至更短的时间，他就把所有烦恼都忘了。'),
    (1, 50, 107, 'Not because his troubles were one whit less heavy and bitter to him than a man’s are to a man, but because a new and powerful interest bore them down and drove them out of his mind for the time—just as men’s misfortunes are forgotten in the excitement of new enterprises.', '不是因为他的烦恼变小了，而是因为他有了一个新的、很有意思的事情。这事让他一下子把烦恼都忘了。就像大人有了新工作，也会忘了不开心的事情一样。'),
    (1, 50, 108, 'This new interest was a valued novelty in whistling, which he had just acquired from a negro, and he was suffering to practise it undisturbed.', '这个新兴趣是学一种很特别的口哨。他刚从一个人那里学会，现在特别想安静地练习。'),
    (1, 50, 109, 'It consisted in a peculiar bird-like turn, a sort of liquid warble, produced by touching the tongue to the roof of the mouth at short intervals in the midst of the music—the reader probably remembers how to do it, if he has ever been a boy.', '这种口哨特别，听起来像小鸟唱歌。吹的时候，舌头要一直轻轻碰上牙膛。如果你也当过小男孩，可能也知道怎么吹吧。'),
    (1, 50, 110, 'Diligence and attention soon gave him the knack of it, and he strode down the street with his mouth full of harmony and his soul full of gratitude.', '他很认真地练习，很快就学会了。他嘴里吹着好听的曲子，心里美滋滋地走在街上。'),
    (1, 50, 111, 'He felt much as an astronomer feels who has discovered a new planet—no doubt, as far as strong, deep, unalloyed pleasure is concerned, the advantage was with the boy, not the astronomer.', '他开心极了，就像天文学家发现了一颗新星球一样。不过，要说最纯粹、最开心的快乐，这个小男孩肯定比天文学家还高兴。'),
    (1, 51, 112, 'The summer evenings were long.', '夏天的晚上很长。'),
    (1, 51, 113, 'It was not dark, yet.', '天还没黑呢。'),
    (1, 51, 114, 'Presently Tom checked his whistle.', '忽然，汤姆停下了口哨。'),
    (1, 51, 115, 'A stranger was before him—a boy a shade larger than himself.', '他面前站着一个陌生人——一个比他稍微高一点的男孩。'),
    (1, 51, 116, 'A new-comer of any age or either sex was an impressive curiosity in the poor little shabby village of St. Petersburg.', '在圣彼得斯堡这个又小又旧的村子里，不管是大人还是小孩，只要是新来的，大家都会觉得很好奇。'),
    (1, 51, 117, 'This boy was well dressed, too—well dressed on a week-day.', '这个男孩穿得很好，而且还是在平时穿这么好。'),
    (1, 51, 118, 'This was simply astounding.', '这简直太让人惊讶了。'),
    (1, 51, 119, 'His cap was a dainty thing, his close-buttoned blue cloth roundabout was new and natty, and so were his pantaloons.', '他的帽子很精致，紧扣的蓝色短上衣又新又漂亮，裤子也是一样。'),
    (1, 51, 120, 'He had shoes on—and it was only Friday.', '他穿着鞋——而且这天才星期五呢。'),
    (1, 51, 121, 'He even wore a necktie, a bright bit of ribbon.', '他甚至还戴了一条领带，一条亮亮的彩带。'),
    (1, 51, 122, 'He had a citified air about him that ate into Tom’s vitals.', '他一看就像是从城里来的，这让汤姆心里很不舒服。'),
    (1, 51, 123, 'The more Tom stared at the splendid marvel, the higher he turned up his nose at his finery and the shabbier and shabbier his own outfit seemed to him to grow.', '汤姆越看这个厉害的小孩，就越觉得他的衣服很漂亮，而自己的衣服却越来越旧。'),
    (1, 51, 124, 'Neither boy spoke.', '两个小孩都没说话。'),
    (1, 51, 125, 'If one moved, the other moved—but only sidewise, in a circle; they kept face to face and eye to eye all the time.', '一个动，另一个也跟着动——只是侧着身子，绕着圈子走；他们一直面对面，眼睛对着眼睛。'),
    (1, 51, 126, 'Finally Tom said:', '最后，汤姆说：'),
    (1, 52, 127, '“I can lick you!”', '“我能打败你！”'),
    (1, 53, 128, '“I’d like to see you try it.”', '“我倒想看看你怎么打。”'),
    (1, 54, 129, '“Well, I can do it.”', '“哼，我就是能！”'),
    (1, 55, 130, '“No you can’t, either.”', '“不，你不能。”'),
    (1, 56, 131, '“Yes I can.”', '“我能！”'),
    (1, 57, 132, '“No you can’t.”', '“你不能！”'),
    (1, 58, 133, '“I can.”', '“我能！”'),
    (1, 59, 134, '“You can’t.”', '“你不能！”'),
    (1, 60, 135, '“Can!”', '“能！”'),
    (1, 61, 136, '“Can’t!”', '“不能！”'),
    (1, 62, 137, 'An uncomfortable pause.', '气氛有点僵。'),
    (1, 62, 138, 'Then Tom said:', '然后，汤姆说：'),
    (1, 63, 139, '“What’s your name?”', '“你叫什么名字？”'),
    (1, 64, 140, '“’Tisn’t any of your business, maybe.”', '“这可能不关你的事。”'),
    (1, 65, 141, '“Well I ’low I’ll _make_ it my business.”', '“哼，我偏要管！”'),
    (1, 66, 142, '“Well why don’t you?”', '“那你怎么还不动手？”'),
    (1, 67, 143, '“If you say much, I will.”', '“你要是再说，我就真动手了。”'),
    (1, 68, 144, '“Much—much—_much_.', '“说——说——说！'),
    (1, 68, 145, 'There now.”', '怎么样？”'),
    (1, 69, 146, '“Oh, you think you’re mighty smart, _don’t_ you?', '“噢，你觉得自己很聪明，是不是？我一只手绑在后面都能打败你，只要我愿意。”'),
    (1, 69, 147, 'I could lick you with one hand tied behind me, if I wanted to.”', '我就算一只手绑在后面，也能赢你，只要我愿意。'),
    (1, 70, 148, '“Well why don’t you _do_ it?', '“那你怎么还不‘做’呢？你‘说’你能做。”'),
    (1, 70, 149, 'You _say_ you can do it.”', '你说你能做到。'),
    (1, 71, 150, '“Well I _will_, if you fool with me.”', '“哼，你要是再跟我捣乱，我就真‘做’了。”'),
    (1, 72, 151, '“Oh yes—I’ve seen whole families in the same fix.”', '“哦，是啊，我见过好多家都遇到过这种事。”'),
    (1, 73, 152, '“Smarty!', '“小聪明鬼！'),
    (1, 73, 153, 'You think you’re _some_, now, _don’t_ you?', '你现在觉得自己很厉害，对不对？'),
    (1, 73, 154, 'Oh, what a hat!”', '哦，这帽子真难看！”'),
    (1, 74, 155, '“You can lump that hat if you don’t like it.', '“你要是不喜欢那帽子，管它呢。'),
    (1, 74, 156, 'I dare you to knock it off—and anybody that’ll take a dare will suck eggs.”', '你敢把它打掉吗？谁要是敢，就是笨蛋！”'),
    (1, 75, 157, '“You’re a liar!”', '“你是个骗子！”'),
    (1, 76, 158, '“You’re another.”', '“你才是！”'),
    (1, 77, 159, '“You’re a fighting liar and dasn’t take it up.”', '“你这个爱打架的骗子，你不敢！”'),
    (1, 78, 160, '“Aw—take a walk!”', '“哎——走开啦！”'),
    (1, 79, 161, '“Say—if you give me much more of your sass I’ll take and bounce a rock off’n your head.”', '“喂，你要是再多嘴，我就拿石头砸你脑袋！”'),
    (1, 80, 162, '“Oh, of _course_ you will.”', '“哦，你当然会啦。”'),
    (1, 81, 163, '“Well I _will_.”', '“我就是会。”'),
    (1, 82, 164, '“Well why don’t you _do_ it then?', '“那你为什么不做呢？'),
    (1, 82, 165, 'What do you keep _saying_ you will for?', '你为什么老是说你会做？'),
    (1, 82, 166, 'Why don’t you _do_ it?', '你为什么不做？'),
    (1, 82, 167, 'It’s because you’re afraid.”', '那是因为你害怕！”'),
    (1, 83, 168, '“I _ain’t_ afraid.”', '“我才不怕！”'),
    (1, 84, 169, '“You are.”', '“你就是怕。”'),
    (1, 85, 170, '“I ain’t.”', '“我才不。”'),
    (1, 86, 171, '“You are.”', '“你就是。”'),
    (1, 87, 172, 'Another pause, and more eying and sidling around each other.', '又停了一会儿，他们继续你看看我，我看看你，还互相绕着走。'),
    (1, 87, 173, 'Presently they were shoulder to shoulder.', '很快，他们就肩并肩站着了。'),
    (1, 87, 174, 'Tom said:', '汤姆说：'),
    (1, 88, 175, '“Get away from here!”', '“走开！”'),
    (1, 89, 176, '“Go away yourself!”', '“你才走开呢！”'),
    (1, 90, 177, '“I won’t.”', '“我偏不。”'),
    (1, 91, 178, '“I won’t either.”', '“我也不。”'),
    (1, 92, 179, 'So they stood, each with a foot placed at an angle as a brace, and both shoving with might and main, and glowering at each other with hate.', '于是他们就那样站着，一只脚斜斜地撑着地，使劲地推着对方，互相瞪着眼睛，满是讨厌。'),
    (1, 92, 180, 'But neither could get an advantage.', '但是谁也赢不了谁。'),
    (1, 92, 181, 'After struggling till both were hot and flushed, each relaxed his strain with watchful caution, and Tom said:', '两人打得很用力，脸都红了。他们小心地松开，汤姆说：'),
    (1, 93, 182, '“You’re a coward and a pup.', '“你这个胆小鬼，小不点儿。'),
    (1, 93, 183, 'I’ll tell my big brother on you, and he can thrash you with his little finger, and I’ll make him do it, too.”', '我会告诉我哥哥，他用小手指头就能把你打趴下，我还要他真这么做！”'),
    (1, 94, 184, '“What do I care for your big brother?', '“我才不怕你哥哥呢！'),
    (1, 94, 185, 'I’ve got a brother that’s bigger than he is—and what’s more, he can throw him over that fence, too.”', '我也有个哥哥，比你哥哥还厉害——他能把你哥哥扔过那边的篱笆呢！”'),
    (1, 94, 186, '[Both brothers were imaginary.]', '（其实两个哥哥都是他们编出来的。）'),
    (1, 95, 187, '“That’s a lie.”', '“你骗人！”'),
    (1, 96, 188, '“_Your_ saying so don’t make it so.”', '“你说不算数！”'),
    (1, 97, 189, 'Tom drew a line in the dust with his big toe, and said:', '汤姆用大脚趾在土里画了一条线，然后说：'),
    (1, 98, 190, '“I dare you to step over that, and I’ll lick you till you can’t stand up.', '“你敢不敢跨过这条线？我打得你站不起来！'),
    (1, 98, 191, 'Anybody that’ll take a dare will steal sheep.”', '敢这么做的人，都是坏孩子！”'),
    (1, 99, 192, 'The new boy stepped over promptly, and said:', '新来的男孩立刻就跨了过去，他说：'),
    (1, 100, 193, '“Now you said you’d do it, now let’s see you do it.”', '“你刚才说要打我，快来啊，我等着呢！”'),
    (1, 101, 194, '“Don’t you crowd me now; you better look out.”', '“你别逼我！你最好小心点！”'),
    (1, 102, 195, '“Well, you _said_ you’d do it—why don’t you do it?”', '“哎呀，你不是说要打我吗？怎么不打呀？”'),
    (1, 103, 196, '“By jingo! for two cents I _will_ do it.”', '“哼！只要两分钱，我就打！”'),
    (1, 104, 197, 'The new boy took two broad coppers out of his pocket and held them out with derision.', '新来的男孩从口袋里拿出两枚大铜币，笑着伸了出来。'),
    (1, 104, 198, 'Tom struck them to the ground.', '汤姆把钱打到了地上。'),
    (1, 104, 199, 'In an instant both boys were rolling and tumbling in the dirt, gripped together like cats; and for the space of a minute they tugged and tore at each other’s hair and clothes, punched and scratched each other’s nose, and covered themselves with dust and glory.', '瞬间，两个男孩就在泥土里滚来滚去，像小猫一样扭打在一起。他们互相抓头发、扯衣服，还互相打鼻子、挠脸，身上沾满了灰尘。'),
    (1, 104, 200, 'Presently the confusion took form, and through the fog of battle Tom appeared, seated astride the new boy, and pounding him with his fists.', '很快，这场打斗就分出了胜负。从一片尘土中，汤姆出现了，他骑在新来的男孩身上，用拳头打他。'),
    (1, 104, 201, '“Holler ’nuff!” said he.', '“快喊‘我认输’！”他说。'),
    (1, 105, 202, 'The boy only struggled to free himself.', '男孩只是拼命挣扎，想把自己救出来。'),
    (1, 105, 203, 'He was crying—mainly from rage.', '他哭了——主要是气得。'),
    (1, 106, 204, '“Holler ’nuff!”', '“快喊‘我认输’！”'),
    (1, 106, 205, '—and the pounding went on.', '——拳头还在继续打。'),
    (1, 107, 206, 'At last the stranger got out a smothered “’Nuff!” and Tom let him up and said:', '最后，那个陌生男孩终于小声地喊了句：“我认输了！”汤姆这才让他站起来，说：'),
    (1, 108, 207, '“Now that’ll learn you.', '“这下你该懂了吧。'),
    (1, 108, 208, 'Better look out who you’re fooling with next time.”', '下次再惹我，你可要小心了。”'),
    (1, 109, 209, 'The new boy went off brushing the dust from his clothes, sobbing, snuffling, and occasionally looking back and shaking his head and threatening what he would do to Tom the “next time he caught him out.”', '新来的男孩拍打着身上的灰尘走了，他还在抽泣着，吸着鼻子。他时不时回头，摇着头，威胁说下次再碰到汤姆，一定要好好教训他。'),
    (1, 109, 210, 'To which Tom responded with jeers, and started off in high feather, and as soon as his back was turned the new boy snatched up a stone, threw it and hit him between the shoulders and then turned tail and ran like an antelope.', '汤姆嘲笑了他几句，然后得意洋洋地走了。汤姆刚一转身，新来的男孩就抓起一块石头，扔过去打中了汤姆的后背。然后他立马掉头，像羚羊一样跑走了。'),
    (1, 109, 211, 'Tom chased the traitor home, and thus found out where he lived.', '汤姆追着那个“坏蛋”回了家，知道了他的住处。'),
    (1, 109, 212, 'He then held a position at the gate for some time, daring the enemy to come outside, but the enemy only made faces at him through the window and declined.', '然后他在门口站了一会儿，挑衅那个“敌人”出来，但“敌人”只在窗户里朝他做鬼脸，不肯出来。'),
    (1, 109, 213, 'At last the enemy’s mother appeared, and called Tom a bad, vicious, vulgar child, and ordered him away.', '最后，“敌人”的妈妈出现了，说汤姆是个坏孩子、没礼貌的孩子，让他走开。'),
    (1, 109, 214, 'So he went away; but he said he “’lowed” to “lay” for that boy.', '所以他走了；但他心里想，他会“盯”上那个男孩的。'),
    (1, 110, 215, 'He got home pretty late that night, and when he climbed cautiously in at the window, he uncovered an ambuscade, in the person of his aunt; and when she saw the state his clothes were in her resolution to turn his Saturday holiday into captivity at hard labor became adamantine in its firmness.', '他那天晚上回家很晚，当他小心翼翼地从窗户爬进去时，发现他阿姨正守在那儿等着他；阿姨看到他衣服很脏，就决定让他周六干苦活，不让他玩了。'),
    (2, 111, 216, 'Saturday morning was come, and all the summer world was bright and fresh, and brimming with life.', '周六早上到了，整个夏天都阳光明媚，充满生机。'),
    (2, 111, 217, 'There was a song in every heart; and if the heart was young the music issued at the lips.', '每个人的心里都有歌声；如果是年轻的心，歌声就会从嘴里唱出来。'),
    (2, 111, 218, 'There was cheer in every face and a spring in every step.', '每个人的脸上都带着笑容，每一步都充满活力。'),
    (2, 111, 219, 'The locust-trees were in bloom and the fragrance of the blossoms filled the air.', '刺槐树开花了，花儿的香味弥漫在空气中。'),
    (2, 111, 220, 'Cardiff Hill, beyond the village and above it, was green with vegetation and it lay just far enough away to seem a Delectable Land, dreamy, reposeful, and inviting.', '卡迪夫山在村子外面，高高的地方，绿草如茵，离得刚刚好，看起来像一个美丽的地方，安静又诱人。'),
    (2, 112, 221, 'Tom appeared on the sidewalk with a bucket of whitewash and a long-handled brush.', '汤姆带着一桶石灰水和一把长柄刷子出现在人行道上。'),
    (2, 112, 222, 'He surveyed the fence, and all gladness left him and a deep melancholy settled down upon his spirit.', '他看着那道篱笆墙，所有的快乐都消失了，心里充满了深深的忧伤。'),
    (2, 112, 223, 'Thirty yards of board fence nine feet high.', '三十码长，九英尺高的木板篱笆。'),
    (2, 112, 224, 'Life to him seemed hollow, and existence but a burden.', '对他来说，生活是空虚的，活着就是一种负担。'),
    (2, 112, 225, 'Sighing, he dipped his brush and passed it along the topmost plank; repeated the operation; did it again; compared the insignificant whitewashed streak with the far-reaching continent of unwhitewashed fence, and sat down on a tree-box discouraged.', '他叹了口气，把刷子蘸了一下，刷过最上面那块木板；又刷了一次；再刷了一次；他把那一点点刷白的地方，和远处一大片没刷的篱笆对比了一下，然后沮丧地坐在树箱上。'),
    (2, 112, 226, 'Jim came skipping out at the gate with a tin pail, and singing Buffalo Gals.', '吉姆蹦蹦跳跳地从大门出来，手里提着一个锡桶，嘴里唱着《布法罗姑娘》。'),
    (2, 112, 227, 'Bringing water from the town pump had always been hateful work in Tom’s eyes, before, but now it did not strike him so.', '以前，在汤姆看来，从镇上的水泵打水总是很讨厌的活儿，但现在他却不这么觉得了。'),
    (2, 112, 228, 'He remembered that there was company at the pump.', '他想起来，水泵那里有人。'),
    (2, 112, 229, 'White, mulatto, and negro boys and girls were always there waiting their turns, resting, trading playthings, quarrelling, fighting, skylarking.', '白人、混血儿和黑人男孩女孩总是在那里等着轮流打水，休息，交换玩具，吵架，打架，玩闹。'),
    (2, 112, 230, 'And he remembered that although the pump was only a hundred and fifty yards off, Jim never got back with a bucket of water under an hour—and even then somebody generally had to go after him.', '他还记得，虽然水泵只有一百五十码远，但吉姆打一桶水回来总要一个多小时——而且就算那样，通常也得有人去叫他回来。'),
    (2, 112, 231, 'Tom said:', '汤姆说：'),
    (2, 113, 232, '“Say, Jim, I’ll fetch the water if you’ll whitewash some.”', '“喂，吉姆，如果你帮我刷墙，我就帮你打水。”'),
    (2, 114, 233, 'Jim shook his head and said:', '吉姆摇了摇头说：'),
    (2, 115, 234, '“Can’t, Mars Tom.', '“不行啊，汤姆少爷。'),
    (2, 115, 235, 'Ole missis, she tole me I got to go an’ git dis water an’ not stop foolin’ roun’ wid anybody.', '老夫人让我去打水，不能跟任何人玩。'),
    (2, 115, 236, 'She say she spec’ Mars Tom gwine to ax me to whitewash, an’ so she tole me go ’long an’ ’tend to my own business—she ’lowed _she’d_ ’tend to de whitewashin’.”', '她说她知道汤姆少爷你会让我刷墙，所以她让我去干自己的事——她说_她_会来刷墙的。”'),
    (2, 116, 237, '“Oh, never you mind what she said, Jim.', '“哦，别管她说什么了，吉姆。'),
    (2, 116, 238, 'That’s the way she always talks.', '她总是那么说。'),
    (2, 116, 239, 'Gimme the bucket—I won’t be gone only a a minute.', '把桶给我——我只去一会儿就回来。'),
    (2, 116, 240, '_She_ won’t ever know.”', '_她_永远不会知道的。”'),
    (2, 117, 241, '“Oh, I dasn’t, Mars Tom.', '“哦，我不敢，汤姆少爷。'),
    (2, 117, 242, 'Ole missis she’d take an’ tar de head off’n me.', '老太太会把我的头拧下来的。'),
    (2, 117, 243, '’Deed she would.”', '她真的会的。”'),
    (2, 118, 244, '“_She_!', '“她才不会呢！'),
    (2, 118, 245, 'She never licks anybody—whacks ’em over the head with her thimble—and who cares for that, I’d like to know.', '她从来不打人，就是用顶针敲敲头。那算什么呀，谁会在乎呢？'),
    (2, 118, 246, 'She talks awful, but talk don’t hurt—anyways it don’t if she don’t cry.', '她说话是有点凶，但说话又不会伤人——反正她不哭就没事。'),
    (2, 118, 247, 'Jim, I’ll give you a marvel.', '吉姆，我给你一个弹珠。'),
    (2, 118, 248, 'I’ll give you a white alley!”', '我给你一个白色的玻璃弹珠！”'),
    (2, 119, 249, 'Jim began to waver.', '吉姆开始犹豫了。'),
    (2, 120, 250, '“White alley, Jim!', '“白色的玻璃弹珠啊，吉姆！'),
    (2, 120, 251, 'And it’s a bully taw.”', '这可是一个很棒的弹珠哦。”'),
    (2, 121, 252, '“My!', '“哇！'),
    (2, 121, 253, 'Dat’s a mighty gay marvel, I tell you!', '那是一个非常漂亮的弹珠，我跟你说！'),
    (2, 121, 254, 'But Mars Tom I’s powerful ’fraid ole missis—”', '可是汤姆少爷，我真的很怕那个老太太——”'),
    (2, 122, 255, '“And besides, if you will I’ll show you my sore toe.”', '“而且，如果你愿意，我给你看我受伤的脚趾头。”'),
    (2, 123, 256, 'Jim was only human—this attraction was too much for him.', '吉姆也是个普通人——这个诱惑对他来说太大了。'),
    (2, 123, 257, 'He put down his pail, took the white alley, and bent over the toe with absorbing interest while the bandage was being unwound.', '他放下桶，拿起白色的玻璃弹珠，好奇地弯下腰看脚趾头，绷带正在慢慢解开。'),
    (2, 123, 258, 'In another moment he was flying down the street with his pail and a tingling rear, Tom was whitewashing with vigor, and Aunt Polly was retiring from the field with a slipper in her hand and triumph in her eye.', '不一会儿，他就提着桶，屁股刺痛地跑下街了。汤姆正在起劲地刷墙，波莉姨妈手里拿着拖鞋，眼睛里带着胜利的表情，离开了。'),
    (2, 124, 259, 'But Tom’s energy did not last.', '可是汤姆的力气没有持续很久。'),
    (2, 124, 260, 'He began to think of the fun he had planned for this day, and his sorrows multiplied.', '他开始想起今天本来要玩的那些好玩的事，他的烦恼越来越多。'),
    (2, 124, 261, 'Soon the free boys would come tripping along on all sorts of delicious expeditions, and they would make a world of fun of him for having to work—the very thought of it burnt him like fire.', '很快，那些不用干活的小伙伴就会开心地跑过来，去玩各种各样的有趣冒险。他们会嘲笑他还在干活——一想到这，他就气得像火烧一样。'),
    (2, 124, 262, 'He got out his worldly wealth and examined it—bits of toys, marbles, and trash; enough to buy an exchange of _work_, maybe, but not half enough to buy so much as half an hour of pure freedom.', '他拿出他所有的“宝贝”，看了看——一些小玩具、弹珠和垃圾；也许够买来一次“替工”的机会，但连半小时的自由都买不到。'),
    (2, 124, 263, 'So he returned his straitened means to his pocket, and gave up the idea of trying to buy the boys.', '于是他把这些不多的东西放回口袋，放弃了想用钱请小伙伴替他干活的念头。'),
    (2, 124, 264, 'At this dark and hopeless moment an inspiration burst upon him!', '就在这个又黑又没希望的时候，他突然有了一个好主意！'),
    (2, 124, 265, 'Nothing less than a great, magnificent inspiration.', '这可不是一般的好主意，而是一个非常棒的、了不起的主意！'),
    (2, 125, 266, 'He took up his brush and went tranquilly to work.', '他拿起刷子，平静地开始干活了。'),
    (2, 125, 267, 'Ben Rogers hove in sight presently—the very boy, of all boys, whose ridicule he had been dreading.', '本·罗杰斯很快就出现了——这正是他最害怕会嘲笑他的那个孩子。'),
    (2, 125, 268, 'Ben’s gait was the hop-skip-and-jump—proof enough that his heart was light and his anticipations high.', '本边走边跳，开心得不得了，看起来心情很好，对今天充满期待。'),
    (2, 125, 269, 'He was eating an apple, and giving a long, melodious whoop, at intervals, followed by a deep-toned ding-dong-dong, ding-dong-dong, for he was personating a steamboat.', '他一边吃着苹果，一边不时地发出长长的、好听的汽笛声，接着又是“叮咚咚，叮咚咚”的低沉响声，因为他正在假装自己是一艘蒸汽船。'),
    (2, 125, 270, 'As he drew near, he slackened speed, took the middle of the street, leaned far over to starboard and rounded to ponderously and with laborious pomp and circumstance—for he was personating the Big Missouri, and considered himself to be drawing nine feet of water.', '当他走近时，他放慢了速度，走到街中央，身体大大地向右边倾斜，笨重又费力地转了个弯，摆出一副很气派的样子——因为他正在扮演“大密苏里号”蒸汽船，觉得自己像船一样吃水很深。'),
    (2, 125, 271, 'He was boat and captain and engine-bells combined, so he had to imagine himself standing on his own hurricane-deck giving the orders and executing them:', '他既是船，又是船长，还是汽笛声，所以他得想象自己站在船顶上，自己发号施令，自己执行。'),
    (2, 126, 272, '“Stop her, sir!', '“停船，先生！”'),
    (2, 126, 273, 'Ting-a-ling-ling!”', '“叮铃铃！”'),
    (2, 126, 274, 'The headway ran almost out, and he drew up slowly toward the sidewalk.', '船慢慢停了下来，他缓缓地靠向了岸边。'),
    (2, 127, 275, '“Ship up to back!', '“倒船！”'),
    (2, 127, 276, 'Ting-a-ling-ling!”', '“叮铃铃！”'),
    (2, 127, 277, 'His arms straightened and stiffened down his sides.', '他的胳膊伸得直直的，贴在身体两边，一动不动。'),
    (2, 128, 278, '“Set her back on the stabboard!', '“向右倒船！”'),
    (2, 128, 279, 'Ting-a-ling-ling!', '“叮铃铃！”'),
    (2, 128, 280, 'Chow! ch-chow-wow!', '“嘟！嘟-嘟-呜！”'),
    (2, 128, 281, 'Chow!”', '“嘟！”'),
    (2, 128, 282, 'His right hand, mean-time, describing stately circles—for it was representing a forty-foot wheel.', '同时，他的右手画着大大的圈，那是在模仿一个四十英尺的大轮子。'),
    (2, 129, 283, '“Let her go back on the labboard!', '“向左倒船！”'),
    (2, 129, 284, 'Ting-a-ling-ling!', '“叮铃铃！”'),
    (2, 129, 285, 'Chow-ch-chow-chow!”', '“嘟-嘟-嘟-嘟！”'),
    (2, 129, 286, 'The left hand began to describe circles.', '他的左手也开始画圈了。'),
    (2, 130, 287, '“Stop the stabboard!', '“右舷停！”'),
    (2, 130, 288, 'Ting-a-ling-ling!', '“叮铃铃！”'),
    (2, 130, 289, 'Stop the labboard!', '“左舷停！”'),
    (2, 130, 290, 'Come ahead on the stabboard!', '“右舷前进！”'),
    (2, 130, 291, 'Stop her!', '“停船！”'),
    (2, 130, 292, 'Let your outside turn over slow!', '“让船慢慢转过去！”'),
    (2, 130, 293, 'Ting-a-ling-ling!', '“叮铃铃！”'),
    (2, 130, 294, 'Chow-ow-ow!', '“嘟——！”'),
    (2, 130, 295, 'Get out that head-line!', '“把船头缆绳拉出来！”'),
    (2, 130, 296, '_lively_ now!', '“快点！”'),
    (2, 130, 297, 'Come—out with your spring-line—what’re you about there!', '“快把你的缆绳也放出去！你在干什么呢！”'),
    (2, 130, 298, 'Take a turn round that stump with the bight of it!', '“用绳子在那个木桩上绕一圈！”'),
    (2, 130, 299, 'Stand by that stage, now—let her go!', '“准备好那个踏板，现在——放开！”'),
    (2, 130, 300, 'Done with the engines, sir!', '“引擎操作好了，先生！”'),
    (2, 130, 301, 'Ting-a-ling-ling!', '叮铃铃！'),
    (2, 130, 302, 'SH’T!', '嘶——！'),
    (2, 130, 303, 'S’H’T!', '嘶——！'),
    (2, 130, 304, 'SH’T!”', '嘶——！'),
    (2, 130, 305, '(trying the gauge-cocks).', '(试着去扳那些小把手)。'),
    (2, 131, 306, 'Tom went on whitewashing—paid no attention to the steamboat.', '汤姆继续刷白墙，没理那艘蒸汽船。'),
    (2, 131, 307, 'Ben stared a moment and then said: “_Hi-Yi!', '本盯着看了一会儿，然后说：“喂——！'),
    (2, 131, 308, 'You’re_ up a stump, ain’t you!”', '你可真被难住了，是吧！”'),
    (2, 132, 309, 'No answer.', '没有回答。'),
    (2, 132, 310, 'Tom surveyed his last touch with the eye of an artist, then he gave his brush another gentle sweep and surveyed the result, as before.', '汤姆像艺术家一样看看自己刚刷的地方，然后又轻轻刷了一下，再像之前那样看看效果。'),
    (2, 132, 311, 'Ben ranged up alongside of him.', '本走到他身边。'),
    (2, 132, 312, 'Tom’s mouth watered for the apple, but he stuck to his work.', '汤姆看到苹果口水都要流出来了，但他还是坚持工作。'),
    (2, 132, 313, 'Ben said:', '本说：'),
    (2, 133, 314, '“Hello, old chap, you got to work, hey?”', '“嘿，老朋友，你得干活儿了，是吗？”'),
    (2, 134, 315, 'Tom wheeled suddenly and said:', '汤姆突然转过身，说：'),
    (2, 135, 316, '“Why, it’s you, Ben!', '“哎呀，是本啊！'),
    (2, 135, 317, 'I warn’t noticing.”', '我都没注意到你。”'),
    (2, 136, 318, '“Say—I’m going in a-swimming, I am.', '“听着——我要去游泳了，我真要去。'),
    (2, 136, 319, 'Don’t you wish you could?', '你是不是也想去？'),
    (2, 136, 320, 'But of course you’d druther _work_—wouldn’t you?', '不过你当然更喜欢_干活儿_——不是吗？'),
    (2, 136, 321, 'Course you would!”', '你当然会！”'),
    (2, 137, 322, 'Tom contemplated the boy a bit, and said:', '汤姆看了看那个男孩，然后说：'),
    (2, 138, 323, '“What do you call work?”', '“你管这叫干活儿吗？”'),
    (2, 139, 324, '“Why, ain’t _that_ work?”', '“哎呀，_这_不是工作吗？”'),
    (2, 140, 325, 'Tom resumed his whitewashing, and answered carelessly:', '汤姆继续刷白墙，随便地回答说：'),
    (2, 141, 326, '“Well, maybe it is, and maybe it ain’t.', '“嗯，也许是吧，也许不是。'),
    (2, 141, 327, 'All I know, is, it suits Tom Sawyer.”', '我只知道，它很适合汤姆·索亚。”'),
    (2, 142, 328, '“Oh come, now, you don’t mean to let on that you _like_ it?”', '“哦，得了吧，你不会是想说你_喜欢_它吧？”'),
    (2, 143, 329, 'The brush continued to move.', '刷子继续动着。'),
    (2, 144, 330, '“Like it?', '“喜欢它？'),
    (2, 144, 331, 'Well, I don’t see why I oughtn’t to like it.', '嗯，我觉得挺好的呀。'),
    (2, 144, 332, 'Does a boy get a chance to whitewash a fence every day?”', '不是每天都能刷墙的，对不对？'),
    (2, 145, 333, 'That put the thing in a new light.', '这下本明白过来了。'),
    (2, 145, 334, 'Ben stopped nibbling his apple.', '本不啃苹果了。'),
    (2, 145, 335, 'Tom swept his brush daintily back and forth—stepped back to note the effect—added a touch here and there—criticised the effect again—Ben watching every move and getting more and more interested, more and more absorbed.', '汤姆轻轻地来回刷着，然后退后看看效果，这里补一点，那里加一笔，又看看。本盯着他，看得越来越入迷，越来越想试试。'),
    (2, 145, 336, 'Presently he said:', '过了一会儿，他说：'),
    (2, 146, 337, '“Say, Tom, let _me_ whitewash a little.”', '“喂，汤姆，让我刷一会儿好不好？”'),
    (2, 147, 338, 'Tom considered, was about to consent; but he altered his mind:', '汤姆想了想，本来想答应，但又改主意了：'),
    (2, 148, 339, '“No—no—I reckon it wouldn’t hardly do, Ben.', '“不行，不行，本，我觉得这不太好。'),
    (2, 148, 340, 'You see, Aunt Polly’s awful particular about this fence—right here on the street, you know—but if it was the back fence I wouldn’t mind and _she_ wouldn’t.', '你看，波莉姨妈对这面墙很讲究的，你知道，就在街边上。要是后面的墙，我就不介意，她也不会。'),
    (2, 148, 341, 'Yes, she’s awful particular about this fence; it’s got to be done very careful; I reckon there ain’t one boy in a thousand, maybe two thousand, that can do it the way it’s got to be done.”', '是啊，她对这面墙特别认真。得刷得很仔细才行。我想啊，一千个小孩里，可能两千个小孩里，都找不出一个能刷得像样子的。”'),
    (2, 149, 342, '“No—is that so?', '“啊？真的吗？'),
    (2, 149, 343, 'Oh come, now—lemme just try.', '哎呀，让我试试嘛。'),
    (2, 149, 344, 'Only just a little—I’d let _you_, if you was me, Tom.”', '就刷一点点。要是我是你，汤姆，我肯定让你刷的。”'),
    (2, 150, 345, '“Ben, I’d like to, honest injun; but Aunt Polly—well, Jim wanted to do it, but she wouldn’t let him; Sid wanted to do it, and she wouldn’t let Sid.', '“本，我真想让你刷。但是波莉姨妈——你看，吉姆想刷，她不让他刷；希德也想刷，她也不让希德刷。'),
    (2, 150, 346, 'Now don’t you see how I’m fixed?', '你看看我现在多难办啊？'),
    (2, 150, 347, 'If you was to tackle this fence and anything was to happen to it—”', '要是你刷这面墙，万一弄坏了—”'),
    (2, 151, 348, '“Oh, shucks, I’ll be just as careful.', '“哎呀，我肯定会很小心的！'),
    (2, 151, 349, 'Now lemme try.', '让我试试嘛。'),
    (2, 151, 350, 'Say—I’ll give you the core of my apple.”', '这样吧——我的苹果核给你！”'),
    (2, 152, 351, '“Well, here—No, Ben, now don’t.', '“嗯，这个嘛——不行，本，别这样。'),
    (2, 152, 352, 'I’m afeard—”', '我怕——”'),
    (2, 153, 353, '“I’ll give you _all_ of it!”', '“我把整个苹果都给你！”'),
    (2, 154, 354, 'Tom gave up the brush with reluctance in his face, but alacrity in his heart.', '汤姆脸上虽然不情愿，心里却很开心，把刷子给了本。'),
    (2, 154, 355, 'And while the late steamer Big Missouri worked and sweated in the sun, the retired artist sat on a barrel in the shade close by, dangled his legs, munched his apple, and planned the slaughter of more innocents.', '就在大密苏里号“努力工作”晒太阳的时候，这位“退休画家”坐在旁边阴凉处的桶上，晃着腿，吃着苹果，盘算着怎么让更多的小孩来刷墙。'),
    (2, 154, 356, 'There was no lack of material; boys happened along every little while; they came to jeer, but remained to whitewash.', '他一点也不缺“材料”；不一会儿就有小孩经过。他们本来是来看笑话的，结果都留下来刷墙了。'),
    (2, 154, 357, 'By the time Ben was fagged out, Tom had traded the next chance to Billy Fisher for a kite, in good repair; and when he played out, Johnny Miller bought in for a dead rat and a string to swing it with—and so on, and so on, hour after hour.', '等本累得不行了，汤姆又把下一个刷墙的机会，用一个完好的风筝换给了比利·费舍尔。比利刷累了，约翰尼·米勒又用一只死老鼠和一根绳子换到了刷墙的机会——就这样，一个小时又一个小时地过去了。'),
    (2, 154, 358, 'And when the middle of the afternoon came, from being a poor poverty-stricken boy in the morning, Tom was literally rolling in wealth.', '到了下午，早上还是个穷小子，汤姆这会儿已经“财源滚滚”了！'),
    (2, 154, 359, 'He had besides the things before mentioned, twelve marbles, part of a jews-harp, a piece of blue bottle-glass to look through, a spool cannon, a key that wouldn’t unlock anything, a fragment of chalk, a glass stopper of a decanter, a tin soldier, a couple of tadpoles, six fire-crackers, a kitten with only one eye, a brass door-knob, a dog-collar—but no dog—the handle of a knife, four pieces of orange-peel, and a dilapidated old window sash.', '除了刚才说的那些东西，他还得了十二颗弹珠，口琴的一部分，一块蓝色的玻璃片（可以透过它看东西），一个线轴大炮，一把打不开任何东西的钥匙，一小块粉笔，一个玻璃瓶塞，一个锡兵，两只小蝌蚪，六个鞭炮，一只独眼小猫，一个黄铜门把手，一个狗项圈（可没有狗），一个刀把，四片橘子皮，还有一个破旧的窗框。'),
    (2, 155, 360, 'He had had a nice, good, idle time all the while—plenty of company—and the fence had three coats of whitewash on it!', '他一直过得很开心，很悠闲，还有很多小伙伴陪着——而且墙上已经刷了三层白漆了！'),
    (2, 155, 361, 'If he hadn’t run out of whitewash he would have bankrupted every boy in the village.', '如果他的白石灰没用完，他就会让村里所有的小朋友都把自己的东西给他。'),
    (2, 156, 362, 'Tom said to himself that it was not such a hollow world, after all.', '汤姆心想，原来这个世界并没有那么糟嘛。'),
    (2, 156, 363, 'He had discovered a great law of human action, without knowing it—namely, that in order to make a man or a boy covet a thing, it is only necessary to make the thing difficult to attain.', '他发现了一个大秘密：要想让一个人或一个小朋友想要一件东西，只要让这东西不好得到就行了。'),
    (2, 156, 364, 'If he had been a great and wise philosopher, like the writer of this book, he would now have comprehended that Work consists of whatever a body is _obliged_ to do, and that Play consists of whatever a body is not obliged to do.', '如果他很聪明，像写这本书的人一样，他就会明白：_必须_做的事叫工作，_不用_做的事叫玩耍。'),
    (2, 156, 365, 'And this would help him to understand why constructing artificial flowers or performing on a tread-mill is work, while rolling ten-pins or climbing Mont Blanc is only amusement.', '这样他就能明白，为什么做假花或在跑步机上跑是工作，而打保龄球或爬勃朗峰却是玩。'),
    (2, 156, 366, 'There are wealthy gentlemen in England who drive four-horse passenger-coaches twenty or thirty miles on a daily line, in the summer, because the privilege costs them considerable money; but if they were offered wages for the service, that would turn it into work and then they would resign.', '在英国，有些有钱的先生夏天喜欢开四马马车，每天跑很远。因为这要花很多钱，所以他们觉得好玩。但如果别人给他们钱让他们做这个，这就会变成工作，他们就不干了。'),
    (2, 157, 367, 'The boy mused awhile over the substantial change which had taken place in his worldly circumstances, and then wended toward headquarters to report.', '小朋友想了想自己现在变厉害了，然后就往家走去报告。'),
    (3, 158, 368, 'Tom presented himself before Aunt Polly, who was sitting by an open window in a pleasant rearward apartment, which was bedroom, breakfast-room, dining-room, and library, combined.', '汤姆走到波莉姨妈面前。波莉姨妈正坐在一扇开着的窗户旁边，房间很舒服，在屋子后面。这个房间是卧室、早餐室、餐厅和书房的组合。'),
    (3, 158, 369, 'The balmy summer air, the restful quiet, the odor of the flowers, and the drowsing murmur of the bees had had their effect, and she was nodding over her knitting—for she had no company but the cat, and it was asleep in her lap.', '夏天暖暖的风吹着，周围很安静。花儿香香的，小蜜蜂嗡嗡叫。她织着毛衣，头一点一点的，快睡着了。只有猫咪陪着她，猫咪也在她腿上睡着了。'),
    (3, 158, 370, 'Her spectacles were propped up on her gray head for safety.', '她的眼镜安全地架在她的白头发上。'),
    (3, 158, 371, 'She had thought that of course Tom had deserted long ago, and she wondered at seeing him place himself in her power again in this intrepid way.', '她以为汤姆早就跑掉了，没想到他又这么大胆地自己回来了，让她很惊讶。'),
    (3, 158, 372, 'He said: “Mayn’t I go and play now, aunt?”', '他说：“我现在可以去玩了吗，姨妈？”'),
    (3, 159, 373, '“What, a’ready?', '“什么？这么快？”'),
    (3, 159, 374, 'How much have you done?”', '“你刷了多少呀？”'),
    (3, 160, 375, '“It’s all done, aunt.”', '“都刷完了，姨妈。”'),
    (3, 161, 376, '“Tom, don’t lie to me—I can’t bear it.”', '“汤姆，不要骗我——我可受不了。”'),
    (3, 162, 377, '“I ain’t, aunt; it _is_ all done.”', '“我没骗您，姨妈；真的都刷完了。”'),
    (3, 163, 378, 'Aunt Polly placed small trust in such evidence.', '波莉姨妈不太相信这些话。'),
    (3, 163, 379, 'She went out to see for herself; and she would have been content to find twenty per cent. of Tom’s statement true.', '她自己出去看了一下；她本来以为，就算汤姆说的话有百分之二十是真的，她都会很高兴了。'),
    (3, 163, 380, 'When she found the entire fence white-washed, and not only whitewashed but elaborately coated and recoated, and even a streak added to the ground, her astonishment was almost unspeakable.', '当她发现整面围墙都刷白了，而且不只刷了一层，还刷得又厚又仔细，甚至连地上都有一道白漆，她的惊讶简直无法形容。'),
    (3, 163, 381, 'She said:', '她说：'),
    (3, 164, 382, '“Well, I never!', '“哎呀，真没想到！”'),
    (3, 164, 383, 'There’s no getting round it, you can work when you’re a mind to, Tom.”', '“没法不承认，汤姆，你真想做的时候，还是能干活的。”'),
    (3, 164, 384, 'And then she diluted the compliment by adding, “But it’s powerful seldom you’re a mind to, I’m bound to say.', '然后她接着又说：“不过你很少这么想做，我得说实话。”'),
    (3, 164, 385, 'Well, go ’long and play; but mind you get back some time in a week, or I’ll tan you.”', '“好了，去玩吧；不过记住，一个星期内一定要回来，不然我就要打你的屁股了。”'),
    (3, 165, 386, 'She was so overcome by the splendor of his achievement that she took him into the closet and selected a choice apple and delivered it to him, along with an improving lecture upon the added value and flavor a treat took to itself when it came without sin through virtuous effort.', '她看他做得那么好，特别开心。她带他到柜子旁，挑了一个又大又甜的苹果给他。她还告诉他，不犯错，自己努力得到的奖励，吃起来才更甜更好吃。'),
    (3, 165, 387, 'And while she closed with a happy Scriptural flourish, he “hooked” a doughnut.', '就在她开心地引用《圣经》讲完话的时候，他悄悄地“偷”了一个甜甜圈。'),
    (3, 166, 388, 'Then he skipped out, and saw Sid just starting up the outside stairway that led to the back rooms on the second floor.', '然后他蹦蹦跳跳地跑了出去，看到希德正要走上通往二楼后屋的室外楼梯。'),
    (3, 166, 389, 'Clods were handy and the air was full of them in a twinkling.', '地上的土块正好在手边，眨眼间，空中就到处都是土块了。'),
    (3, 166, 390, 'They raged around Sid like a hail-storm; and before Aunt Polly could collect her surprised faculties and sally to the rescue, six or seven clods had taken personal effect, and Tom was over the fence and gone.', '土块像冰雹一样打在希德的周围；还没等波莉姨妈反应过来要去帮忙，六七块土块就已经打到了他，然后汤姆就翻过围墙跑走了。'),
    (3, 166, 391, 'There was a gate, but as a general thing he was too crowded for time to make use of it.', '有扇门，但他平时太忙了，没时间用它。'),
    (3, 166, 392, 'His soul was at peace, now that he had settled with Sid for calling attention to his black thread and getting him into trouble.', '他心里踏实了，因为他已经和希德说好了，之前希德提到了他的黑线，让他惹了麻烦。'),
    (3, 167, 393, 'Tom skirted the block, and came round into a muddy alley that led by the back of his aunt’s cow-stable.', '汤姆绕过街区，来到一条泥泞的小巷，这条小巷在他姨妈的牛棚后面。'),
    (3, 167, 394, 'He presently got safely beyond the reach of capture and punishment, and hastened toward the public square of the village, where two “military” companies of boys had met for conflict, according to previous appointment.', '他很快就安全了，没有人能抓住他或惩罚他。他赶紧去了村里的广场，那里有两队“小兵”男孩，他们之前约好了要打仗。'),
    (3, 167, 395, 'Tom was General of one of these armies, Joe Harper (a bosom friend) General of the other.', '汤姆是其中一队小兵的将军，乔·哈珀（他的好朋友）是另一队的将军。'),
    (3, 167, 396, 'These two great commanders did not condescend to fight in person—that being better suited to the still smaller fry—but sat together on an eminence and conducted the field operations by orders delivered through aides-de-camp.', '这两位大将军不自己上阵打仗——那是小小孩做的事。他们坐在一起，在高处指挥战斗，通过传令兵下达命令。'),
    (3, 167, 397, 'Tom’s army won a great victory, after a long and hard-fought battle.', '经过一场又长又难的战斗，汤姆的小兵们赢了大胜仗。'),
    (3, 167, 398, 'Then the dead were counted, prisoners exchanged, the terms of the next disagreement agreed upon, and the day for the necessary battle appointed; after which the armies fell into line and marched away, and Tom turned homeward alone.', '接着，他们数了“阵亡”的人，交换了“俘虏”，还约定了下次打仗的规矩和时间。然后，小兵们排好队走开了，汤姆一个人回家了。'),
    (3, 168, 399, 'As he was passing by the house where Jeff Thatcher lived, he saw a new girl in the garden—a lovely little blue-eyed creature with yellow hair plaited into two long-tails, white summer frock and embroidered pantalettes.', '他经过杰夫·撒切尔家的时候，看到花园里有个新来的小女孩。她有一双蓝眼睛，黄色的头发编成两条长辫子，穿着白色夏装和绣花裤子，非常可爱。'),
    (3, 168, 400, 'The fresh-crowned hero fell without firing a shot.', '那个刚当上英雄的小男孩，还没“开枪”呢，就“倒”了。'),
    (3, 168, 401, 'A certain Amy Lawrence vanished out of his heart and left not even a memory of herself behind.', '某个艾米·劳伦斯从他心里消失了，连一点回忆都没留下。'),
    (3, 168, 402, 'He had thought he loved her to distraction; he had regarded his passion as adoration; and behold it was only a poor little evanescent partiality.', '他以为自己爱她爱得很疯狂；他以为那份爱是崇拜。可没想到，那只是一点点很快就消失的小喜欢。'),
    (3, 168, 403, 'He had been months winning her; she had confessed hardly a week ago; he had been the happiest and the proudest boy in the world only seven short days, and here in one instant of time she had gone out of his heart like a casual stranger whose visit is done.', '他花了几个月才让她喜欢上自己；她才刚答应他不到一周。他才当了七天全世界最开心最骄傲的男孩，可就在这一瞬间，她就从他心里离开了，就像一个客人走了一样。'),
    (3, 169, 404, 'He worshipped this new angel with furtive eye, till he saw that she had discovered him; then he pretended he did not know she was present, and began to “show off” in all sorts of absurd boyish ways, in order to win her admiration.', '他偷偷地看着这位新来的“小天使”，直到发现她也看到了他。然后，他假装不知道她在，开始用各种好笑的男孩方式“炫耀”，想让她喜欢他。'),
    (3, 169, 405, 'He kept up this grotesque foolishness for some time; but by-and-by, while he was in the midst of some dangerous gymnastic performances, he glanced aside and saw that the little girl was wending her way toward the house.', '他这样傻傻地“炫耀”了一会儿。过了一阵子，当他正在做一些危险的“体操表演”时，他瞟了一眼，发现小女孩正往房子那边走去。'),
    (3, 169, 406, 'Tom came up to the fence and leaned on it, grieving, and hoping she would tarry yet awhile longer.', '汤姆走到篱笆边，靠在上面，心里很难过，希望她能再多呆一会儿。'),
    (3, 169, 407, 'She halted a moment on the steps and then moved toward the door.', '她在台阶上停了一会儿，然后走向门。'),
    (3, 169, 408, 'Tom heaved a great sigh as she put her foot on the threshold.', '当她把脚踏上门槛时，汤姆深深地叹了口气。'),
    (3, 169, 409, 'But his face lit up, right away, for she tossed a pansy over the fence a moment before she disappeared.', '可是，他的脸马上亮了起来！因为在她消失之前，她朝篱笆外面扔了一朵三色堇。'),
    (3, 170, 410, 'The boy ran around and stopped within a foot or two of the flower, and then shaded his eyes with his hand and began to look down street as if he had discovered something of interest going on in that direction.', '小男孩跑过去，在离花朵一两英尺的地方停下。然后他用手遮住眼睛，开始沿着街往下看，好像他发现那个方向有什么有趣的事情正在发生。'),
    (3, 170, 411, 'Presently he picked up a straw and began trying to balance it on his nose, with his head tilted far back; and as he moved from side to side, in his efforts, he edged nearer and nearer toward the pansy; finally his bare foot rested upon it, his pliant toes closed upon it, and he hopped away with the treasure and disappeared round the corner.', '很快，他捡起一根草，头往后仰，试着把它平衡在鼻子上。他一边左右晃动，一边努力地靠近三色堇；最后，他的光脚踩到了它，柔软的脚趾夹住了它，然后他带着这个“宝贝”跳着跑开了，在拐角处消失了。'),
    (3, 170, 412, 'But only for a minute—only while he could button the flower inside his jacket, next his heart—or next his stomach, possibly, for he was not much posted in anatomy, and not hypercritical, anyway.', '但只是一会儿——只是他把花扣在夹克里，靠近他的心——或者靠近他的肚子，也可能是这样，因为他对人体结构不太懂，反正他也不太讲究。'),
    (3, 171, 413, 'He returned, now, and hung about the fence till nightfall, “showing off,” as before; but the girl never exhibited herself again, though Tom comforted himself a little with the hope that she had been near some window, meantime, and been aware of his attentions.', '他现在又回来了，在篱笆边晃到天黑，像之前一样“炫耀”。但那个女孩再也没出现过，不过汤姆安慰自己说，她可能一直在某个窗户边，看到了他的举动。'),
    (3, 171, 414, 'Finally he strode home reluctantly, with his poor head full of visions.', '最后，他很不情愿地大步走回家，脑子里装满了各种幻想。'),
    (3, 172, 415, 'All through supper his spirits were so high that his aunt wondered “what had got into the child.”', '整个晚饭时间，他都特别高兴，他姨妈很奇怪“这孩子怎么了”。'),
    (3, 172, 416, 'He took a good scolding about clodding Sid, and did not seem to mind it in the least.', '他因为用土块砸希德被好好骂了一顿，但他一点都不介意。'),
    (3, 172, 417, 'He tried to steal sugar under his aunt’s very nose, and got his knuckles rapped for it.', '他当着姨妈的面，想偷糖吃，结果手背被打了。'),
    (3, 172, 418, 'He said:', '他说：'),
    (3, 173, 419, '“Aunt, you don’t whack Sid when he takes it.”', '“姨妈，希德拿糖的时候，你可没打他。”'),
    (3, 174, 420, '“Well, Sid don’t torment a body the way you do.', '“嗯，希德可不像你这样折腾人。”'),
    (3, 174, 421, 'You’d be always into that sugar if I warn’t watching you.”', '如果我不看着你，你肯定会一直偷吃糖。”'),
    (3, 175, 422, 'Presently she stepped into the kitchen, and Sid, happy in his immunity, reached for the sugar-bowl—a sort of glorying over Tom which was wellnigh unbearable.', '很快，她走进了厨房。希德 觉得自己没事了，高兴地去拿糖罐——他有点得意地看了一眼 汤姆，让 汤姆 几乎气坏了。'),
    (3, 175, 423, 'But Sid’s fingers slipped and the bowl dropped and broke.', '可是 希德 的手滑了一下，糖罐掉下去摔碎了。'),
    (3, 175, 424, 'Tom was in ecstasies.', '汤姆 高兴坏了。'),
    (3, 175, 425, 'In such ecstasies that he even controlled his tongue and was silent.', '他高兴得连话都不说了，一声不吭。'),
    (3, 175, 426, 'He said to himself that he would not speak a word, even when his aunt came in, but would sit perfectly still till she asked who did the mischief; and then he would tell, and there would be nothing so good in the world as to see that pet model “catch it.”', '他心里想，阿姨进来他也不说话。他会一动不动地坐着，直到阿姨问是谁弄坏的。然后他就会告诉阿姨，看到那个被宠坏的家伙被骂，那会是世界上最开心的事情。'),
    (3, 175, 427, 'He was so brimful of exultation that he could hardly hold himself when the old lady came back and stood above the wreck discharging lightnings of wrath from over her spectacles.', '他高兴得快要忍不住了。奶奶回来了，她站在摔碎的糖罐旁边，透过眼镜，气呼呼地瞪着。'),
    (3, 175, 428, 'He said to himself, “Now it’s coming!”', '他心想：“这下要来了！”'),
    (3, 175, 429, 'And the next instant he was sprawling on the floor!', '就在下一秒，他一下子摔倒在地！'),
    (3, 175, 430, 'The potent palm was uplifted to strike again when Tom cried out:', '那只厉害的手又要打下来了，这时 汤姆 大声喊道：'),
    (3, 176, 431, '“Hold on, now, what ’er you belting _me_ for?', '“等等！你为什么要打我？”'),
    (3, 176, 432, '—Sid broke it!”', '“——是 希德 弄坏的！”'),
    (3, 177, 433, 'Aunt Polly paused, perplexed, and Tom looked for healing pity.', '波莉姨妈 停住了，有点懵。汤姆 等着别人来安慰她。'),
    (3, 177, 434, 'But when she got her tongue again, she only said:', '但当她又能说话时，她只说了一句：'),
    (3, 178, 435, '“Umf!', '“嗯！'),
    (3, 178, 436, 'Well, you didn’t get a lick amiss, I reckon.', '我想你挨打一点都没错。'),
    (3, 178, 437, 'You been into some other audacious mischief when I wasn’t around, like enough.”', '你肯定在我不在的时候，还做了其他淘气的事情，大概就是这样！”'),
    (3, 179, 438, 'Then her conscience reproached her, and she yearned to say something kind and loving; but she judged that this would be construed into a confession that she had been in the wrong, and discipline forbade that.', '她的心里有点不舒服，很想说些温柔的话。但她又觉得，那样就好像承认自己错了，所以她不能说。'),
    (3, 179, 439, 'So she kept silence, and went about her affairs with a troubled heart.', '于是她什么也没说，心里带着一丝不安去忙自己的事了。'),
    (3, 179, 440, 'Tom sulked in a corner and exalted his woes.', '汤姆 独自在角落里生闷气，还觉得自己特别可怜。'),
    (3, 179, 441, 'He knew that in her heart his aunt was on her knees to him, and he was morosely gratified by the consciousness of it.', '他知道姑妈心里肯定觉得对不起他，他嘴上不说，心里却有点得意。'),
    (3, 179, 442, 'He would hang out no signals, he would take notice of none.', '他什么表示都没有，也假装没看到任何表示。'),
    (3, 179, 443, 'He knew that a yearning glance fell upon him, now and then, through a film of tears, but he refused recognition of it.', '他知道姑妈有时会带着泪水，用想和好的眼神看他，但他假装没看见。'),
    (3, 179, 444, 'He pictured himself lying sick unto death and his aunt bending over him beseeching one little forgiving word, but he would turn his face to the wall, and die with that word unsaid.', '他想象自己病得很重，快要死了。姑妈弯着腰求他，希望他说一句原谅的话，但他会把脸转向墙壁，一句话也不说就死了。'),
    (3, 179, 445, 'Ah, how would she feel then?', '唉，那时她会怎么样呢？'),
    (3, 179, 446, 'And he pictured himself brought home from the river, dead, with his curls all wet, and his sore heart at rest.', '他还想象自己从河里被抬回家，已经死了，卷发都湿透了，他那颗难过的心也终于平静下来了。'),
    (3, 179, 447, 'How she would throw herself upon him, and how her tears would fall like rain, and her lips pray God to give her back her boy and she would never, never abuse him any more!', '她会扑到他身上，眼泪像下雨一样，嘴里会求上帝把她的孩子还给她，说再也不会，再也不会欺负他了！'),
    (3, 179, 448, 'But he would lie there cold and white and make no sign—a poor little sufferer, whose griefs were at an end.', '但他会冰冰冷冷、白白的躺在那里，什么反应都没有——一个可怜的小家伙，所有的难过都结束了。'),
    (3, 179, 449, 'He so worked upon his feelings with the pathos of these dreams, that he had to keep swallowing, he was so like to choke; and his eyes swam in a blur of water, which overflowed when he winked, and ran down and trickled from the end of his nose.', '他被这些想象出来的难过故事感动得不行，一个劲儿地吞口水，感觉都要哭出来了；他的眼睛里模糊一片，都是泪水，他一眨眼，泪水就流出来，从鼻尖滴了下来。'),
    (3, 179, 450, 'And such a luxury to him was this petting of his sorrows, that he could not bear to have any worldly cheeriness or any grating delight intrude upon it; it was too sacred for such contact; and so, presently, when his cousin Mary danced in, all alive with the joy of seeing home again after an age-long visit of one week to the country, he got up and moved in clouds and darkness out at one door as she brought song and sunshine in at the other.', '他很喜欢沉浸在自己的悲伤里，不希望任何开心的事来打扰他；因为这对他来说太重要了。所以，当他的表妹 玛丽 蹦蹦跳跳地跑进来时，她因为在乡下玩了一周回家而高兴得不得了，他却闷闷不乐地从另一扇门走出去，而她把歌声和阳光带进了屋里。'),
    (3, 180, 451, 'He wandered far from the accustomed haunts of boys, and sought desolate places that were in harmony with his spirit.', '他没有去小朋友们常去玩的地方，而是跑到很远很安静的地方，感觉那里很适合他。'),
    (3, 180, 452, 'A log raft in the river invited him, and he seated himself on its outer edge and contemplated the dreary vastness of the stream, wishing, the while, that he could only be drowned, all at once and unconsciously, without undergoing the uncomfortable routine devised by nature.', '河里有个木筏，他坐到木筏边上，看着又大又冷的河水。他心里想，要是能一下子沉下去，什么都不知道就好了。'),
    (3, 180, 453, 'Then he thought of his flower.', '然后，他想起了他的那朵花。'),
    (3, 180, 454, 'He got it out, rumpled and wilted, and it mightily increased his dismal felicity.', '他把花拿出来，花已经皱巴巴的，也枯萎了。这让他心里更难过了。'),
    (3, 180, 455, 'He wondered if she would pity him if she knew?', '他想，如果她知道了，会可怜他吗？'),
    (3, 180, 456, 'Would she cry, and wish that she had a right to put her arms around his neck and comfort him?', '她会哭吗？会想抱抱他，安慰他吗？'),
    (3, 180, 457, 'Or would she turn coldly away like all the hollow world?', '还是会像其他人一样，冷冷地走开呢？'),
    (3, 180, 458, 'This picture brought such an agony of pleasurable suffering that he worked it over and over again in his mind and set it up in new and varied lights, till he wore it threadbare.', '想到这些，他又难过又有点开心。他一直在心里反复地想这个画面，想了又想，直到他想累了。'),
    (3, 180, 459, 'At last he rose up sighing and departed in the darkness.', '最后，他叹了口气，站起来，在夜色中离开了。'),
    (3, 181, 460, 'About half-past nine or ten o’clock he came along the deserted street to where the Adored Unknown lived; he paused a moment; no sound fell upon his listening ear; a candle was casting a dull glow upon the curtain of a second-story window.', '大概九点半或十点的时候，他走在空荡荡的街上，来到了他喜欢那个女孩的家。他停了一下，什么声音也没听到。二楼的窗帘后面，有一支蜡烛发着微弱的光。'),
    (3, 181, 461, 'Was the sacred presence there?', '她在里面吗？'),
    (3, 181, 462, 'He climbed the fence, threaded his stealthy way through the plants, till he stood under that window; he looked up at it long, and with emotion; then he laid him down on the ground under it, disposing himself upon his back, with his hands clasped upon his breast and holding his poor wilted flower.', '他爬过篱笆，悄悄地穿过植物，来到那扇窗户下面。他抬头看了很久，心里很难过。然后他躺在窗下的地上，双手抱在胸前，手里还握着那朵枯萎的花。'),
    (3, 181, 463, 'And thus he would die—out in the cold world, with no shelter over his homeless head, no friendly hand to wipe the death-damps from his brow, no loving face to bend pityingly over him when the great agony came.', '他就这样死了——在这个冰冷的世界里，没有家，没有可以遮风避雨的地方，也没有人来擦去他额头上的汗水，更没有人会在他最痛苦的时候，怜爱地看着他。'),
    (3, 181, 464, 'And thus _she_ would see him when she looked out upon the glad morning, and oh! would she drop one little tear upon his poor, lifeless form, would she heave one little sigh to see a bright young life so rudely blighted, so untimely cut down?', '当她早上开心地往外看的时候，就会看到他。哦！她会为他冰冷的身体流下一滴眼泪吗？会为他这么年轻就死去了，难过地叹一口气吗？'),
    (3, 182, 465, 'The window went up, a maid-servant’s discordant voice profaned the holy calm, and a deluge of water drenched the prone martyr’s remains!', '窗户开了，一个女仆刺耳的声音打破了安静。一大盆水泼了下来，把躺在地上的他淋了个透！'),
    (3, 183, 466, 'The strangling hero sprang up with a relieving snort.', '他喘着粗气，一下子跳了起来。'),
    (3, 183, 467, 'There was a whiz as of a missile in the air, mingled with the murmur of a curse, a sound as of shivering glass followed, and a small, vague form went over the fence and shot away in the gloom.', '只听见“嗖”的一声，好像有什么东西飞过来了，还夹杂着几句骂人的话，接着是玻璃碎裂的声音。一个模糊的小身影翻过篱笆，跑进了黑暗里。'),
    (3, 184, 468, 'Not long after, as Tom, all undressed for bed, was surveying his drenched garments by the light of a tallow dip, Sid woke up; but if he had any dim idea of making any “references to allusions,” he thought better of it and held his peace, for there was danger in Tom’s eye.', '不久之后，当汤姆脱了衣服准备睡觉，正借着蜡烛光看他湿透的衣服时，希德醒了。不过，希德就算心里隐约想说些什么，也还是没说，因为他觉得汤姆的眼神很吓人。'),
    (3, 185, 469, 'Tom turned in without the added vexation of prayers, and Sid made mental note of the omission.', '汤姆没有祷告就去睡觉了，希德在心里偷偷记下了他没祷告这件事。'),
    (4, 186, 470, 'The sun rose upon a tranquil world, and beamed down upon the peaceful village like a benediction.', '太阳升起来了，照亮了一个平静的世界，阳光像祝福一样洒满了宁静的村庄。'),
    (4, 186, 471, 'Breakfast over, Aunt Polly had family worship: it began with a prayer built from the ground up of solid courses of Scriptural quotations, welded together with a thin mortar of originality; and from the summit of this she delivered a grim chapter of the Mosaic Law, as from Sinai.', '吃完早饭，波莉姨妈带着全家人做礼拜。她先是做了一个很长的祷告，里面有很多圣经里的话。祷告完了，她又像从西奈山上传来一样，严肃地读了一章《摩西律法》。'),
    (4, 187, 472, 'Then Tom girded up his loins, so to speak, and went to work to “get his verses.”', '接着，汤姆就准备好，开始“背他的经文”了。'),
    (4, 187, 473, 'Sid had learned his lesson days before.', '希德几天前就学过这课了。'),
    (4, 187, 474, 'Tom bent all his energies to the memorizing of five verses, and he chose part of the Sermon on the Mount, because he could find no verses that were shorter.', '汤姆尽力去背那五节经文。他选了《山上宝训》的一部分，因为他找不到更短的经文了。'),
    (4, 187, 475, 'At the end of half an hour Tom had a vague general idea of his lesson, but no more, for his mind was traversing the whole field of human thought, and his hands were busy with distracting recreations.', '半小时后，汤姆对他的课文只有一点点模糊的印象。因为他的心思早就飞到别的地方去了，手也忙着玩各种分散注意力的东西。'),
    (4, 187, 476, 'Mary took his book to hear him recite, and he tried to find his way through the fog:', '玛丽拿着书听他背诵，他努力地想从这团迷雾中找到头绪：'),
    (4, 188, 477, '“Blessed are the—a—a—”', '“有福的是——啊——啊——”'),
    (4, 189, 478, '“Poor”—', '“贫穷的——”'),
    (4, 190, 479, '“Yes—poor; blessed are the poor—a—a—”', '“对——贫穷的；有福的是贫穷的——啊——啊——”'),
    (4, 191, 480, '“In spirit—”', '“在灵里——”'),
    (4, 192, 481, '“In spirit; blessed are the poor in spirit, for they—they—”', '“心里贫穷的人有福了，因为他们—他们—”'),
    (4, 193, 482, '“_Theirs_—”', '“_他们_—”'),
    (4, 194, 483, '“For _theirs_.', '“因为_他们_。'),
    (4, 194, 484, 'Blessed are the poor in spirit, for theirs is the kingdom of heaven.', '心里贫穷的人有福了，因为天国是他们的。'),
    (4, 194, 485, 'Blessed are they that mourn, for they—they—”', '哀恸的人有福了，因为他们—他们—”'),
    (4, 195, 486, '“Sh—”', '“嘘—”'),
    (4, 196, 487, '“For they—a—”', '“因为他们—啊—”'),
    (4, 197, 488, '“S, H, A—”', '“S，H，A—”'),
    (4, 198, 489, '“For they S, H—Oh, I don’t know what it is!”', '“因为他们S，H—哦，我不知道是什么了！”'),
    (4, 199, 490, '“_Shall_!”', '“_必_！”'),
    (4, 200, 491, '“Oh, _shall_! for they shall—for they shall—a—a—shall mourn—a—a—blessed are they that shall—they that—a—they that shall mourn, for they shall—a—shall _what_?', '“哦，_必_！因为他们必—因为他们必—啊—啊—必哀恸—啊—啊—有福的是那些必—那些—啊—那些必哀恸的，因为他们必—啊—必_什么_？'),
    (4, 200, 492, 'Why don’t you tell me, Mary?', '你为什么不告诉我呢，玛丽？'),
    (4, 200, 493, '—what do you want to be so mean for?”', '—你为什么要这么刻薄？”'),
    (4, 201, 494, '“Oh, Tom, you poor thick-headed thing, I’m not teasing you.', '“哦，汤姆，你这个可怜的笨脑袋，我不是在逗你玩。'),
    (4, 201, 495, 'I wouldn’t do that.', '我不会那样做的。'),
    (4, 201, 496, 'You must go and learn it again.', '你得再去学一遍。'),
    (4, 201, 497, 'Don’t you be discouraged, Tom, you’ll manage it—and if you do, I’ll give you something ever so nice.', '别灰心，汤姆，你会成功的—如果你做到了，我会给你一个非常好的东西。'),
    (4, 201, 498, 'There, now, that’s a good boy.”', '好了，你真是个好孩子。”'),
    (4, 202, 499, '“All right!', '“好的！'),
    (4, 202, 500, 'What is it, Mary, tell me what it is.”', '那是什么呢，玛丽，快告诉我那是什么。”'),
    (4, 203, 501, '“Never you mind, Tom.', '“别担心啦，汤姆。'),
    (4, 203, 502, 'You know if I say it’s nice, it is nice.”', '你知道我说它好，它就是好的。”'),
    (4, 204, 503, '“You bet you that’s so, Mary.', '“你说的肯定对，玛丽。'),
    (4, 204, 504, 'All right, I’ll tackle it again.”', '好的，我再去试试。”'),
    (4, 205, 505, 'And he did “tackle it again”—and under the double pressure of curiosity and prospective gain he did it with such spirit that he accomplished a shining success.', '于是他真的“再去试试”—在好奇心和期待获得奖励的双重作用下，他满怀热情地做这件事，最终获得了巨大的成功。'),
    (4, 205, 506, 'Mary gave him a brand-new “Barlow” knife worth twelve and a half cents; and the convulsion of delight that swept his system shook him to his foundations.', '玛丽给了他一把全新的“巴洛”小刀，值十二点五美分；他兴奋得全身颤抖，开心极了。'),
    (4, 205, 507, 'True, the knife would not cut anything, but it was a “sure-enough” Barlow, and there was inconceivable grandeur in that—though where the Western boys ever got the idea that such a weapon could possibly be counterfeited to its injury is an imposing mystery and will always remain so, perhaps.', '确实，这把刀什么都切不动，但它是一把“货真价实”的巴洛刀，这让它显得无比了不起—不过，西部孩子们是从哪里认为这种武器可能会被仿冒到损坏的地步，这真是一个巨大的谜团，也许永远都是个谜。'),
    (4, 205, 508, 'Tom contrived to scarify the cupboard with it, and was arranging to begin on the bureau, when he was called off to dress for Sunday-school.', '汤姆用它在碗柜上刻了几道，正准备开始刻梳妆台，这时他被叫去为主日学校打扮。'),
    (4, 206, 509, 'Mary gave him a tin basin of water and a piece of soap, and he went outside the door and set the basin on a little bench there; then he dipped the soap in the water and laid it down; turned up his sleeves; poured out the water on the ground, gently, and then entered the kitchen and began to wipe his face diligently on the towel behind the door.', '玛丽给了他一个锡盆，里面有水和一块肥皂，他走到门外，把盆放在一个小板凳上；然后他把肥皂蘸了水，又放下；卷起袖子；轻轻地把水倒在地上，然后走进厨房，开始认真地用门后面的毛巾擦脸。'),
    (4, 206, 510, 'But Mary removed the towel and said:', '但是玛丽拿走了毛巾，说：'),
    (4, 207, 511, '“Now ain’t you ashamed, Tom.', '“你难道不觉得不好意思吗，汤姆。'),
    (4, 207, 512, 'You mustn’t be so bad.', '你不能这么淘气了。'),
    (4, 207, 513, 'Water won’t hurt you.”', '水不会弄疼你的。”'),
    (4, 208, 514, 'Tom was a trifle disconcerted.', '汤姆有点慌乱。'),
    (4, 208, 515, 'The basin was refilled, and this time he stood over it a little while, gathering resolution; took in a big breath and began.', '盆里又装满了水。他站在旁边，鼓足了勇气；深吸一口气，然后就开始洗了。'),
    (4, 208, 516, 'When he entered the kitchen presently, with both eyes shut and groping for the towel with his hands, an honorable testimony of suds and water was dripping from his face.', '他走进厨房时，闭着眼睛，摸索着找毛巾。脸上还滴着肥皂泡和水。'),
    (4, 208, 517, 'But when he emerged from the towel, he was not yet satisfactory, for the clean territory stopped short at his chin and his jaws, like a mask; below and beyond this line there was a dark expanse of unirrigated soil that spread downward in front and backward around his neck.', '但是当他擦完脸时，还是不让人满意。干净的地方只到下巴和脸颊，就像戴着面具一样；这条线下面和外面，脖子前面和后面都还是脏的。'),
    (4, 208, 518, 'Mary took him in hand, and when she was done with him he was a man and a brother, without distinction of color, and his saturated hair was neatly brushed, and its short curls wrought into a dainty and symmetrical general effect.', '玛丽亲自来帮他弄。等她弄完，他变得干干净净的。湿漉漉的头发梳得整齐，短短的卷发看起来也很漂亮。'),
    (4, 208, 519, '[He privately smoothed out the curls, with labor and difficulty, and plastered his hair close down to his head; for he held curls to be effeminate, and his own filled his life with bitterness.]', '他偷偷地、费力地把卷发弄直，紧紧地贴在头皮上。因为他觉得卷发不好看，自己的卷发让他很不开心。'),
    (4, 208, 520, 'Then Mary got out a suit of his clothing that had been used only on Sundays during two years—they were simply called his “other clothes”—and so by that we know the size of his wardrobe.', '然后玛丽拿出了一套他的衣服，这衣服两年里只在星期天穿。大家就叫它们“另外一套衣服”。这样我们就知道他有多少衣服了。'),
    (4, 208, 521, 'The girl “put him to rights” after he had dressed himself; she buttoned his neat roundabout up to his chin, turned his vast shirt collar down over his shoulders, brushed him off and crowned him with his speckled straw hat.', '他穿好衣服后，女孩又帮他整理了一下。她把他的小夹克扣到下巴，把宽大的衬衫领子翻到肩膀上，给他掸了掸灰，还给他戴上花斑的草帽。'),
    (4, 208, 522, 'He now looked exceedingly improved and uncomfortable.', '他现在看起来好多了，但也很不舒服。'),
    (4, 208, 523, 'He was fully as uncomfortable as he looked; for there was a restraint about whole clothes and cleanliness that galled him.', '他真的和看起来一样不舒服。因为穿整齐的衣服和干干净净让他觉得很不自在。'),
    (4, 208, 524, 'He hoped that Mary would forget his shoes, but the hope was blighted; she coated them thoroughly with tallow, as was the custom, and brought them out.', '他希望玛丽能忘记他的鞋子，但这个希望落空了。她按照习惯，把鞋子仔细涂上牛油，然后拿了出来。'),
    (4, 208, 525, 'He lost his temper and said he was always being made to do everything he didn’t want to do.', '他发脾气说，他总是被逼着做所有他不想做的事情。'),
    (4, 208, 526, 'But Mary said, persuasively:', '但玛丽温柔地说：'),
    (4, 209, 527, '“Please, Tom—that’s a good boy.”', '“乖，汤姆——做个好孩子。”'),
    (4, 210, 528, 'So he got into the shoes snarling.', '于是他很不情愿地穿上了鞋子。'),
    (4, 210, 529, 'Mary was soon ready, and the three children set out for Sunday-school—a place that Tom hated with his whole heart; but Sid and Mary were fond of it.', '玛丽也很快准备好了，三个孩子出发去主日学校。那是汤姆非常讨厌的地方，但希德和玛丽都很喜欢那里。'),
    (4, 211, 530, 'Sabbath-school hours were from nine to half-past ten; and then church service.', '主日学校从九点上到十点半，然后是教堂礼拜。'),
    (4, 211, 531, 'Two of the children always remained for the sermon voluntarily, and the other always remained too—for stronger reasons.', '其中两个孩子总是自愿留下听布道，另一个孩子也总是留下——因为有其他原因。'),
    (4, 211, 532, 'The church’s high-backed, uncushioned pews would seat about three hundred persons; the edifice was but a small, plain affair, with a sort of pine board tree-box on top of it for a steeple.', '教堂里高高的、没有垫子的长椅可以坐大约三百人。这座教堂很小，也很普通，上面有个用松木板做的像烟囱一样的尖顶。'),
    (4, 211, 533, 'At the door Tom dropped back a step and accosted a Sunday-dressed comrade:', '在门口，汤姆慢了一步，叫住了他一个穿着礼拜日衣服的朋友。'),
    (4, 212, 534, '“Say, Billy, got a yaller ticket?”', '“嘿，比利，你有黄票吗？”'),
    (4, 213, 535, '“Yes.”', '“有。”'),
    (4, 214, 536, '“What’ll you take for her?”', '“你拿什么换它？”'),
    (4, 215, 537, '“What’ll you give?”', '“你给我什么？”'),
    (4, 216, 538, '“Piece of lickrish and a fish-hook.”', '“一块甘草糖和一个鱼钩。”'),
    (4, 217, 539, '“Less see ’em.”', '“给我看看。”'),
    (4, 218, 540, 'Tom exhibited.', '汤姆把东西拿了出来。'),
    (4, 218, 541, 'They were satisfactory, and the property changed hands.', '大家都很满意，东西也换了主人。'),
    (4, 218, 542, 'Then Tom traded a couple of white alleys for three red tickets, and some small trifle or other for a couple of blue ones.', '然后，汤姆 用几颗白色弹珠换了三张红色票，又用其他一些小东西换了两张蓝色票。'),
    (4, 218, 543, 'He waylaid other boys as they came, and went on buying tickets of various colors ten or fifteen minutes longer.', '他拦住其他来的小男生，又继续买了十到十五分钟的各种颜色的票。'),
    (4, 218, 544, 'He entered the church, now, with a swarm of clean and noisy boys and girls, proceeded to his seat and started a quarrel with the first boy that came handy.', '他现在走进教堂，那里有一大群干净又吵闹的小男生小女生。他走到自己的座位，就开始和第一个碰到的男生吵架。'),
    (4, 218, 545, 'The teacher, a grave, elderly man, interfered; then turned his back a moment and Tom pulled a boy’s hair in the next bench, and was absorbed in his book when the boy turned around; stuck a pin in another boy, presently, in order to hear him say “Ouch!” and got a new reprimand from his teacher.', '老师是个严肃的老爷爷，他过来制止了。然后他一转身，汤姆 就拔了旁边座位一个男生的头发。那个男生转过头来的时候，汤姆 又装作在认真看书。过了一会儿，他又用大头针扎另一个男生，就为了听他叫一声“哎哟！” 结果又被老师骂了。'),
    (4, 218, 546, 'Tom’s whole class were of a pattern—restless, noisy, and troublesome.', '汤姆 班上的同学都一个样——坐不住，很吵，还爱捣乱。'),
    (4, 218, 547, 'When they came to recite their lessons, not one of them knew his verses perfectly, but had to be prompted all along.', '轮到他们背课文时，没有一个人能背得很熟，每次都要别人提醒才行。'),
    (4, 218, 548, 'However, they worried through, and each got his reward—in small blue tickets, each with a passage of Scripture on it; each blue ticket was pay for two verses of the recitation.', '不过，他们总算挺过去了，每个人都得到了奖励——小小的蓝色票，每张票上都有一段圣经经文；每张蓝色票可以换背诵两句经文的奖励。'),
    (4, 218, 549, 'Ten blue tickets equalled a red one, and could be exchanged for it; ten red tickets equalled a yellow one; for ten yellow tickets the superintendent gave a very plainly bound Bible (worth forty cents in those easy times) to the pupil.', '十张蓝色票可以换一张红色票；十张红色票可以换一张黄色票；集齐十张黄色票，校长就会送给那个小朋友一本包装很普通的圣经（在那个时候只值四十美分）。'),
    (4, 218, 550, 'How many of my readers would have the industry and application to memorize two thousand verses, even for a Doré Bible?', '我的读者里，有多少人能这么努力用功，记住两千句经文，哪怕是为了得到一本精美的多雷圣经呢？'),
    (4, 218, 551, 'And yet Mary had acquired two Bibles in this way—it was the patient work of two years—and a boy of German parentage had won four or five.', '可是，玛丽 却用这个办法得到了两本圣经——这可是他两年努力的结果。一个德国血统的小男生甚至得到了四五本呢。'),
    (4, 218, 552, 'He once recited three thousand verses without stopping; but the strain upon his mental faculties was too great, and he was little better than an idiot from that day forth—a grievous misfortune for the school, for on great occasions, before company, the superintendent (as Tom expressed it) had always made this boy come out and “spread himself.”', '他曾经一口气背了三千句经文，但那对他来说太累了，从那天起他就像个傻子一样——这对学校来说真是个大麻烦，因为在重要的场合，有客人来的时候，校长（用汤姆的话说）总是让这个男生出来“好好表现一番”。'),
    (4, 218, 553, 'Only the older pupils managed to keep their tickets and stick to their tedious work long enough to get a Bible, and so the delivery of one of these prizes was a rare and noteworthy circumstance; the successful pupil was so great and conspicuous for that day that on the spot every scholar’s heart was fired with a fresh ambition that often lasted a couple of weeks.', '只有那些年纪大一点的学生才能一直把票留着，坚持做这些无聊的事情，直到换到一本圣经。所以，能得到这种奖品是件稀奇又特别的事；那个得奖的学生在那天会显得非常了不起，非常引人注目，一下子就让每个小朋友的心里都燃起了新的决心，这种决心通常能持续几个星期。'),
    (4, 218, 554, 'It is possible that Tom’s mental stomach had never really hungered for one of those prizes, but unquestionably his entire being had for many a day longed for the glory and the eclat that came with it.', '也许汤姆的心里从来没有真正渴望过这些奖品，但毫无疑问，他很久以前就一直盼望着得到奖品带来的荣耀和风光。'),
    (4, 219, 555, 'In due course the superintendent stood up in front of the pulpit, with a closed hymn-book in his hand and his forefinger inserted between its leaves, and commanded attention.', '过了一会儿，校长站在讲台前，手里拿着一本合上的赞美诗集，食指夹在书页中间，他让大家安静。'),
    (4, 219, 556, 'When a Sunday-school superintendent makes his customary little speech, a hymn-book in the hand is as necessary as is the inevitable sheet of music in the hand of a singer who stands forward on the platform and sings a solo at a concert—though why, is a mystery: for neither the hymn-book nor the sheet of music is ever referred to by the sufferer.', '当一位主日学校校长发表他习惯的小演讲时，手里拿着一本赞美诗集就像歌唱家站在舞台上独唱时手里那张必然的乐谱一样重要——虽然为什么会这样，是个谜：因为无论是赞美诗集还是乐谱，表演者都从来不会看一眼。'),
    (4, 219, 557, 'This superintendent was a slim creature of thirty-five, with a sandy goatee and short sandy hair; he wore a stiff standing-collar whose upper edge almost reached his ears and whose sharp points curved forward abreast the corners of his mouth—a fence that compelled a straight lookout ahead, and a turning of the whole body when a side view was required; his chin was propped on a spreading cravat which was as broad and as long as a bank-note, and had fringed ends; his boot toes were turned sharply up, in the fashion of the day, like sleigh-runners—an effect patiently and laboriously produced by the young men by sitting with their toes pressed against a wall for hours together.', '这位校长是个三十五岁，瘦瘦高高的人，留着山羊胡子，头发也是沙色的，短短的。他穿着硬挺的立领衬衫，领子边儿几乎碰到他的耳朵，尖尖的领角向前弯到嘴边——这就像一道围栏，让他只能直直地往前看，如果想看旁边就得整个身子都转过去；他的下巴靠在一块又宽又长的领带上，领带就像钞票一样大，还有流苏边；他的靴子尖也像那时流行的一样，向上翘得很高，就像雪橇的滑板——这是年轻男生们为了赶时髦，花了好几个小时把脚趾抵在墙上，辛苦弄出来的效果。'),
    (4, 219, 558, 'Mr. Walters was very earnest of mien, and very sincere and honest at heart; and he held sacred things and places in such reverence, and so separated them from worldly matters, that unconsciously to himself his Sunday-school voice had acquired a peculiar intonation which was wholly absent on week-days.', '沃尔特斯先生的样子很认真，心里也很真诚老实；他非常尊敬神圣的事物和地方，把它们和世俗的事情分得很开，以至于他自己都没有发现，他的主日学校声音变得很特别，那种腔调在平时是完全没有的。'),
    (4, 219, 559, 'He began after this fashion:', '他是这样开始说的：'),
    (4, 220, 560, '“Now, children, I want you all to sit up just as straight and pretty as you can and give me all your attention for a minute or two.', '“孩子们，现在请大家坐得直直的、漂亮亮的，把耳朵竖起来听我说一两分钟。'),
    (4, 220, 561, 'There—that is it.', '好——就是这样。'),
    (4, 220, 562, 'That is the way good little boys and girls should do.', '乖巧的小男生小女生就应该这样做。'),
    (4, 220, 563, 'I see one little girl who is looking out of the window—I am afraid she thinks I am out there somewhere—perhaps up in one of the trees making a speech to the little birds.', '我看到一个小女生正在看窗外——我猜她可能以为我跑出去了，也许是爬到树上给小鸟们演讲呢。'),
    (4, 220, 564, '[Applausive titter.]', '（掌声伴着窃笑声。）'),
    (4, 220, 565, 'I want to tell you how good it makes me feel to see so many bright, clean little faces assembled in a place like this, learning to do right and be good.”', '我想告诉大家，看到这么多聪明又干净的小脸蛋聚在这里，学习做对的事，做好孩子，我心里感到多高兴啊！'),
    (4, 220, 566, 'And so forth and so on.', '就这样，一直说着。'),
    (4, 220, 567, 'It is not necessary to set down the rest of the oration.', '没有必要把后面所有的演讲内容都写下来了。'),
    (4, 220, 568, 'It was of a pattern which does not vary, and so it is familiar to us all.', '这演讲的套路总是这样，一点儿也没变，所以我们大家都知道是怎么回事。'),
    (4, 221, 569, 'The latter third of the speech was marred by the resumption of fights and other recreations among certain of the bad boys, and by fidgetings and whisperings that extended far and wide, washing even to the bases of isolated and incorruptible rocks like Sid and Mary.', '演讲最后三分之一的时候，一些调皮的男生又开始打架和玩闹了，还有一些小动作和窃窃私语也传得很远很广，甚至影响到了像希德和玛丽这样平时很乖的小朋友。'),
    (4, 221, 570, 'But now every sound ceased suddenly, with the subsidence of Mr. Walters’ voice, and the conclusion of the speech was received with a burst of silent gratitude.', '但是，当沃尔特斯先生的声音渐渐变小，演讲结束的时候，所有的声音都突然停了下来，大家默默地，心里很感激。'),
    (4, 222, 571, 'A good part of the whispering had been occasioned by an event which was more or less rare—the entrance of visitors: lawyer Thatcher, accompanied by a very feeble and aged man; a fine, portly, middle-aged gentleman with iron-gray hair; and a dignified lady who was doubtless the latter’s wife.', '大家小声说话，是因为有客人来了。律师撒切尔来了，还有一位很老的爷爷、一位头发灰白的叔叔，和一位阿姨。阿姨应该是叔叔的妻子。'),
    (4, 222, 572, 'The lady was leading a child.', '阿姨牵着一个小朋友。'),
    (4, 222, 573, 'Tom had been restless and full of chafings and repinings; conscience-smitten, too—he could not meet Amy Lawrence’s eye, he could not brook her loving gaze.', '汤姆心里坐立不安，还有点内疚。他不敢看艾米·劳伦斯的眼睛，也受不了她那么温柔的眼神。'),
    (4, 222, 574, 'But when he saw this small newcomer his soul was all ablaze with bliss in a moment.', '但当他看到这个新来的小朋友时，他的心里立刻充满了快乐。'),
    (4, 222, 575, 'The next moment he was “showing off” with all his might—cuffing boys, pulling hair, making faces—in a word, using every art that seemed likely to fascinate a girl and win her applause.', '接下来，他使劲地“炫耀”自己——打男生、拉头发、做鬼脸。总之，他用尽了各种办法来吸引那个小女孩，想让她喜欢他。'),
    (4, 222, 576, 'His exaltation had but one alloy—the memory of his humiliation in this angel’s garden—and that record in sand was fast washing out, under the waves of happiness that were sweeping over it now.', '他虽然很高兴，但心里还有一点点不开心——他想起在那个“天使花园”里，他被羞辱的事。不过，现在快乐的浪潮涌过来，那不开心的事就像沙子上的字一样，很快就被冲走了。'),
    (4, 223, 577, 'The visitors were given the highest seat of honor, and as soon as Mr. Walters’ speech was finished, he introduced them to the school.', '客人们被安排坐在最好的位置。沃尔特先生一讲完话，就把他们介绍给大家。'),
    (4, 223, 578, 'The middle-aged man turned out to be a prodigious personage—no less a one than the county judge—altogether the most august creation these children had ever looked upon—and they wondered what kind of material he was made of—and they half wanted to hear him roar, and were half afraid he might, too.', '这位叔叔原来是个大人物——他竟然是县里的法官！这些小朋友们从来没见过这么威风的人。他们好奇他是什么做的，一半想听他大吼一声，一半又有点害怕他真的会吼出来。'),
    (4, 223, 579, 'He was from Constantinople, twelve miles away—so he had travelled, and seen the world—these very eyes had looked upon the county court-house—which was said to have a tin roof.', '他从十二英里外的君士坦丁堡来，去过很多地方，见过大世面。他的眼睛亲眼看过县法院，听说那里还是铁皮屋顶呢！'),
    (4, 223, 580, 'The awe which these reflections inspired was attested by the impressive silence and the ranks of staring eyes.', '大家被这些事吓到了，都安静下来，一排排的眼睛都盯着他看。'),
    (4, 223, 581, 'This was the great Judge Thatcher, brother of their own lawyer.', '这就是厉害的撒切尔法官，是他们自己律师的哥哥。'),
    (4, 223, 582, 'Jeff Thatcher immediately went forward, to be familiar with the great man and be envied by the school.', '杰夫撒切尔立刻走上前去认识这位大人物，好让学校里的人都羡慕他。'),
    (4, 223, 583, 'It would have been music to his soul to hear the whisperings:', '如果能听到这些悄悄话，他心里一定很高兴：'),
    (4, 224, 584, '“Look at him, Jim!', '“快看他，吉姆！'),
    (4, 224, 585, 'He’s a going up there.', '他要走过去了。'),
    (4, 224, 586, 'Say—look! he’s a going to shake hands with him—he _is_ shaking hands with him!', '快看啊！他要去跟他握手了——他真的在握手了！'),
    (4, 224, 587, 'By jings, don’t you wish you was Jeff?”', '天哪，你是不是也想当杰夫啊？”'),
    (4, 225, 588, 'Mr. Walters fell to “showing off,” with all sorts of official bustlings and activities, giving orders, delivering judgments, discharging directions here, there, everywhere that he could find a target.', '沃尔特先生也开始“炫耀”自己了。他忙着做各种重要的事，在能找到目标的地方，到处发号施令。'),
    (4, 225, 589, 'The librarian “showed off”—running hither and thither with his arms full of books and making a deal of the splutter and fuss that insect authority delights in.', '图书管理员也“炫耀”起来了，他抱着一堆书跑来跑去，像个小官僚一样，装作很忙很厉害的样子。'),
    (4, 225, 590, 'The young lady teachers “showed off”—bending sweetly over pupils that were lately being boxed, lifting pretty warning fingers at bad little boys and patting good ones lovingly.', '年轻的女老师们也“炫耀”起来了——她们温柔地弯下腰，去关心那些刚才才被惩罚过的学生；对着调皮的小男生竖起手指轻轻警告，对乖巧的小男生则爱抚地拍拍头。'),
    (4, 225, 591, 'The young gentlemen teachers “showed off” with small scoldings and other little displays of authority and fine attention to discipline—and most of the teachers, of both sexes, found business up at the library, by the pulpit; and it was business that frequently had to be done over again two or three times (with much seeming vexation).', '年轻的男老师们也“炫耀”起来了——他们轻轻地责骂几句，展示一下自己的权威，表示自己很注重纪律。大部分老师，不管男女，都在图书馆的讲台旁边找到事情做，而且这些事经常需要重复做两三次（还假装很烦恼的样子）。'),
    (4, 225, 592, 'The little girls “showed off” in various ways, and the little boys “showed off” with such diligence that the air was thick with paper wads and the murmur of scufflings.', '小女孩们也用各种方式“炫耀”自己，小男孩们也努力地“炫耀”，结果空气中都是纸团，还有打闹的吵闹声。'),
    (4, 225, 593, 'And above it all the great man sat and beamed a majestic judicial smile upon all the house, and warmed himself in the sun of his own grandeur—for he was “showing off,” too.', '在这一切之上，那个大人物坐在那里，威严地笑着，目光扫过整个屋子，陶醉在自己的威风里——因为他也在“炫耀”自己呢。'),
    (4, 226, 594, 'There was only one thing wanting to make Mr. Walters’ ecstasy complete, and that was a chance to deliver a Bible-prize and exhibit a prodigy.', '沃尔特先生还差一件事就更开心了，那就是能颁发一本圣经奖品，然后展示一个天才学生。'),
    (4, 226, 595, 'Several pupils had a few yellow tickets, but none had enough—he had been around among the star pupils inquiring.', '有几个学生有一些黄色的票，但都没有集齐足够的。他一直在优秀学生中打听。'),
    (4, 226, 596, 'He would have given worlds, now, to have that German lad back again with a sound mind.', '他现在愿意付出一切，只希望能让那个德国小男孩能恢复正常，回到这里。'),
    (4, 227, 597, 'And now at this moment, when hope was dead, Tom Sawyer came forward with nine yellow tickets, nine red tickets, and ten blue ones, and demanded a Bible.', '就在这时，当他已经不抱希望的时候，汤姆·索亚走了上前。他拿着九张黄票、九张红票和十张蓝票，要了一本圣经。'),
    (4, 227, 598, 'This was a thunderbolt out of a clear sky.', '这真是意想不到的事！'),
    (4, 227, 599, 'Walters was not expecting an application from this source for the next ten years.', '沃尔特先生根本没想到，这个人会在未来十年里来领圣经。'),
    (4, 227, 600, 'But there was no getting around it—here were the certified checks, and they were good for their face.', '但也没办法，这些票是真的，而且数量也够了。'),
    (4, 227, 601, 'Tom was therefore elevated to a place with the Judge and the other elect, and the great news was announced from headquarters.', '汤姆被大家推举到了法官和那些被选中的人身边，这个大好消息也从总部传开了。'),
    (4, 227, 602, 'It was the most stunning surprise of the decade, and so profound was the sensation that it lifted the new hero up to the judicial one’s altitude, and the school had two marvels to gaze upon in place of one.', '这是十年来最让人吃惊的事。这件事太轰动了，新来的小英雄一下子和那位法官一样高了。学校里也多了一个了不起的人，现在有两个了。'),
    (4, 227, 603, 'The boys were all eaten up with envy—but those that suffered the bitterest pangs were those who perceived too late that they themselves had contributed to this hated splendor by trading tickets to Tom for the wealth he had amassed in selling whitewashing privileges.', '男孩们都嫉妒死了。但那些最难过的人是后来才发现的，他们自己也帮了汤姆，让他这么风光。他们把奖票换给了汤姆，为了钱，让汤姆去卖粉刷的特权。'),
    (4, 227, 604, 'These despised themselves, as being the dupes of a wily fraud, a guileful snake in the grass.', '他们很讨厌自己，觉得自己被一个狡猾的坏蛋给骗了。'),
    (4, 228, 605, 'The prize was delivered to Tom with as much effusion as the superintendent could pump up under the circumstances; but it lacked somewhat of the true gush, for the poor fellow’s instinct taught him that there was a mystery here that could not well bear the light, perhaps; it was simply preposterous that this boy had warehoused two thousand sheaves of Scriptural wisdom on his premises—a dozen would strain his capacity, without a doubt.', '校长尽力热情地把奖品给了汤姆，但在那种情况下，他的热情有点假。校长心里觉得这件事有点奇怪，可能经不起推敲。这个小男孩怎么可能记住两千段圣经经文呢？记住十几段都很难了。'),
    (4, 229, 606, 'Amy Lawrence was proud and glad, and she tried to make Tom see it in her face—but he wouldn’t look.', '艾米·劳伦斯又高兴又骄傲，她想让汤姆看到她脸上的笑容，但汤姆却不看她。'),
    (4, 229, 607, 'She wondered; then she was just a grain troubled; next a dim suspicion came and went—came again; she watched; a furtive glance told her worlds—and then her heart broke, and she was jealous, and angry, and the tears came and she hated everybody.', '她想了想，有点不开心。接着，她开始有点怀疑。她一直看着。一个偷偷的眼神让她全明白了。她的心碎了，她很吃醋，很生气，眼泪也流了下来，她讨厌所有的人。'),
    (4, 229, 608, 'Tom most of all (she thought).', '(她想)她最恨汤姆了。'),
    (4, 230, 609, 'Tom was introduced to the Judge; but his tongue was tied, his breath would hardly come, his heart quaked—partly because of the awful greatness of the man, but mainly because he was her parent.', '汤姆被介绍给法官。他说不出话，几乎喘不过气，心里直打鼓。一部分是因为法官很了不起，主要是因为他是汤姆的爸爸。'),
    (4, 230, 610, 'He would have liked to fall down and worship him, if it were in the dark.', '如果天黑的话，他真想跪下来拜他。'),
    (4, 230, 611, 'The Judge put his hand on Tom’s head and called him a fine little man, and asked him what his name was.', '法官把手放在汤姆的头上，夸他是好孩子，还问他叫什么名字。'),
    (4, 230, 612, 'The boy stammered, gasped, and got it out:', '男孩结结巴巴地喘着气，终于说出来了：'),
    (4, 231, 613, '“Tom.”', '“汤姆。”'),
    (4, 232, 614, '“Oh, no, not Tom—it is—”', '“哦，不，不是汤姆——是——”'),
    (4, 233, 615, '“Thomas.”', '“托马斯。”'),
    (4, 234, 616, '“Ah, that’s it.', '“啊，对了。'),
    (4, 234, 617, 'I thought there was more to it, maybe.', '我想，也许还有别的名字。'),
    (4, 234, 618, 'That’s very well.', '非常好。'),
    (4, 234, 619, 'But you’ve another one I daresay, and you’ll tell it to me, won’t you?”', '但我猜你还有另一个名字，你会告诉我，对吗？”'),
    (4, 235, 620, '“Tell the gentleman your other name, Thomas,” said Walters, “and say sir.', '“托马斯，告诉这位先生你另一个名字，”沃尔特说，“还要说‘先生’。'),
    (4, 235, 621, 'You mustn’t forget your manners.”', '你不能忘记礼貌。”'),
    (4, 236, 622, '“Thomas Sawyer—sir.”', '“托马斯·索亚——先生。”'),
    (4, 237, 623, '“That’s it!', '“对了！'),
    (4, 237, 624, 'That’s a good boy.', '真是个好孩子。'),
    (4, 237, 625, 'Fine boy.', '好孩子。'),
    (4, 237, 626, 'Fine, manly little fellow.', '真棒，像个小男子汉。'),
    (4, 237, 627, 'Two thousand verses is a great many—very, very great many.', '两千段经文很多很多。'),
    (4, 237, 628, 'And you never can be sorry for the trouble you took to learn them; for knowledge is worth more than anything there is in the world; it’s what makes great men and good men; you’ll be a great man and a good man yourself, some day, Thomas, and then you’ll look back and say, It’s all owing to the precious Sunday-school privileges of my boyhood—it’s all owing to my dear teachers that taught me to learn—it’s all owing to the good superintendent, who encouraged me, and watched over me, and gave me a beautiful Bible—a splendid elegant Bible—to keep and have it all for my own, always—it’s all owing to right bringing up!', '你永远不会后悔花力气学习这些东西，因为知识比世界上任何东西都宝贵。它能让人变得很棒很好。总有一天，托马斯，你也会成为一个很棒很好的人。那时你会回头说：‘这都要感谢我小时候宝贵的主日学校特权！这都要感谢我亲爱的老师教我学习！这都要感谢好校长，他鼓励我，照顾我，还给了我一本漂亮的圣经，一本非常精美的圣经，让我永远拥有它！这都要感谢正确的教育！’'),
    (4, 237, 629, 'That is what you will say, Thomas—and you wouldn’t take any money for those two thousand verses—no indeed you wouldn’t.', '托马斯，你就会这么说。你不会为了这两千段经文收钱的，你肯定不会。'),
    (4, 237, 630, 'And now you wouldn’t mind telling me and this lady some of the things you’ve learned—no, I know you wouldn’t—for we are proud of little boys that learn.', '现在你不介意告诉我还有这位女士一些你学到的东西吧？不，我知道你不会介意的，因为我们为爱学习的小男孩感到骄傲。”'),
    (4, 237, 631, 'Now, no doubt you know the names of all the twelve disciples.', '现在，你一定知道那十二个门徒的名字了吧。'),
    (4, 237, 632, 'Won’t you tell us the names of the first two that were appointed?”', '你能告诉我们，最先被选的两个人叫什么名字吗？'),
    (4, 238, 633, 'Tom was tugging at a button-hole and looking sheepish.', '汤姆拉着衣扣，看起来有点不好意思。'),
    (4, 238, 634, 'He blushed, now, and his eyes fell.', '他脸红了，眼睛也向下看。'),
    (4, 238, 635, 'Mr. Walters’ heart sank within him.', '沃尔特斯先生心里很难过。'),
    (4, 238, 636, 'He said to himself, it is not possible that the boy can answer the simplest question—why _did_ the Judge ask him?', '他心想，这个孩子肯定答不出最简单的问题——法官为什么要问他呢？'),
    (4, 238, 637, 'Yet he felt obliged to speak up and say:', '可他还是觉得应该说点什么：'),
    (4, 239, 638, '“Answer the gentleman, Thomas—don’t be afraid.”', '“托马斯，回答这位叔叔——别害怕。”'),
    (4, 240, 639, 'Tom still hung fire.', '汤姆还是没有说话。'),
    (4, 241, 640, '“Now I know you’ll tell me,” said the lady.', '“我知道你现在会告诉我了，”那位阿姨说。'),
    (4, 241, 641, '“The names of the first two disciples were—”', '“最先的两个门徒，他们的名字是——”'),
    (4, 242, 642, '“_David and Goliah!', '“大卫和歌利亚！'),
    (4, 242, 643, '_”', '”'),
    (4, 243, 644, 'Let us draw the curtain of charity over the rest of the scene.', '剩下的事情，我们就不多说了。'),
    (5, 244, 645, 'About half-past ten the cracked bell of the small church began to ring, and presently the people began to gather for the morning sermon.', '大约十点半，小教堂的旧钟响了。很快，人们就来听早上的讲道了。'),
    (5, 244, 646, 'The Sunday-school children distributed themselves about the house and occupied pews with their parents, so as to be under supervision.', '主日学校家的孩子们分散在教堂里，和爸爸妈妈坐在一起，这样才有人看着他们。'),
    (5, 244, 647, 'Aunt Polly came, and Tom and Sid and Mary sat with her—Tom being placed next the aisle, in order that he might be as far away from the open window and the seductive outside summer scenes as possible.', '波莉姨妈来了，汤姆、希德和玛丽和她坐在一起——汤姆坐在靠过道的地方，这样他就离打开的窗户和外面好玩的夏天景色远一些。'),
    (5, 244, 648, 'The crowd filed up the aisles: the aged and needy postmaster, who had seen better days; the mayor and his wife—for they had a mayor there, among other unnecessaries; the justice of the peace; the widow Douglas, fair, smart, and forty, a generous, good-hearted soul and well-to-do, her hill mansion the only palace in the town, and the most hospitable and much the most lavish in the matter of festivities that St. Petersburg could boast; the bent and venerable Major and Mrs. Ward; lawyer Riverson, the new notable from a distance; next the belle of the village, followed by a troop of lawn-clad and ribbon-decked young heart-breakers; then all the young clerks in town in a body—for they had stood in the vestibule sucking their cane-heads, a circling wall of oiled and simpering admirers, till the last girl had run their gantlet; and last of all came the Model Boy, Willie Mufferson, taking as heedful care of his mother as if she were cut glass.', '人们排队走过过道：有老邮递员，他以前很风光；有市长和他的妻子；有法官；有道格拉斯寡妇，她四十岁，又漂亮又聪明，人很好，也很有钱。她家山上的大房子是镇上最好的，也是圣彼得斯堡最爱去玩、最热闹的地方。还有驼背的沃德少校夫妇；新来的里弗森律师；接着是村里最漂亮的女孩，后面跟着一群穿着漂亮衣服的年轻小伙子；然后是镇上所有年轻的店员们，他们之前一直在门口等女孩子。最后来的是模范男孩威利·马弗森，他非常小心地照顾他的妈妈，好像妈妈是玻璃做的。'),
    (5, 244, 649, 'He always brought his mother to church, and was the pride of all the matrons.', '他总是带妈妈去教堂，是所有阿姨妈妈们都夸奖的好孩子。'),
    (5, 244, 650, 'The boys all hated him, he was so good.', '男孩子们都讨厌他，因为他太好了。'),
    (5, 244, 651, 'And besides, he had been “thrown up to them” so much.', '而且，大家总是拿他来跟别的孩子比。'),
    (5, 244, 652, 'His white handkerchief was hanging out of his pocket behind, as usual on Sundays—accidentally.', '他的白色手帕，像每个星期天一样，“不小心”地从他后面的口袋里露出来。'),
    (5, 244, 653, 'Tom had no handkerchief, and he looked upon boys who had as snobs.', '汤姆没有手帕，他觉得有手帕的男孩都是爱炫耀的人。'),
    (5, 245, 654, 'The congregation being fully assembled, now, the bell rang once more, to warn laggards and stragglers, and then a solemn hush fell upon the church which was only broken by the tittering and whispering of the choir in the gallery.', '大家到齐后，钟又响了一声，提醒迟到的人。接着教堂里就安静下来了，只有楼上的唱诗班还在小声说话、笑。'),
    (5, 245, 655, 'The choir always tittered and whispered all through service.', '唱诗班在讲道的时候总是小声说话、笑。'),
    (5, 245, 656, 'There was once a church choir that was not ill-bred, but I have forgotten where it was, now.', '以前有一个唱诗班，他们很有礼貌，但我现在忘了是哪里的了。'),
    (5, 245, 657, 'It was a great many years ago, and I can scarcely remember anything about it, but I think it was in some foreign country.', '那是很久很久以前的事了，我几乎都不记得了，但我想是在一个很远的国家。'),
    (5, 246, 658, 'The minister gave out the hymn, and read it through with a relish, in a peculiar style which was much admired in that part of the country.', '牧师宣布了要唱的歌，他用一种特别的方式大声念出来，大家都觉得很好听。'),
    (5, 246, 659, 'His voice began on a medium key and climbed steadily up till it reached a certain point, where it bore with strong emphasis upon the topmost word and then plunged down as if from a spring-board:', '他的声音从不高不低开始，慢慢地升高，到一个地方会特别大声地念最上面的字，然后又像跳水一样，一下就降下去了：'),
    (5, 247, 660, 'Shall I be car-ri-ed toe the skies, on flow’ry _beds_ of ease,', '我能被带到天空，躺在舒服的花床上吗？'),
    (5, 248, 661, 'Whilst others fight to win the prize, and sail thro’ _blood_ -y seas?', '当别人争着要赢奖品，在血海里航行时，他又会怎样呢？'),
    (5, 249, 662, 'He was regarded as a wonderful reader.', '大家都觉得他书读得很好。'),
    (5, 249, 663, 'At church “sociables” he was always called upon to read poetry; and when he was through, the ladies would lift up their hands and let them fall helplessly in their laps, and “wall” their eyes, and shake their heads, as much as to say, “Words cannot express it; it is too beautiful, TOO beautiful for this mortal earth.”', '在教堂聚会时，大家总请他念诗。他念完后，女士们会把手抬起又放下，眼睛睁得大大的，还不停地摇头，好像在说：“哇，太美了！美得说不出来！这个世界根本配不上这么好的声音！”'),
    (5, 250, 664, 'After the hymn had been sung, the Rev.', '赞美诗唱完后，那位牧师。'),
    (5, 250, 665, 'Mr. Sprague turned himself into a bulletin-board, and read off “notices” of meetings and societies and things till it seemed that the list would stretch out to the crack of doom—a queer custom which is still kept up in America, even in cities, away here in this age of abundant newspapers.', '斯普拉格牧师就像一个布告栏，念着各种会议、社团的“通知”，念得没完没了，好像要念到世界末日一样。这真是一个奇怪的规矩，即使在现在报纸很多的美国城市里，也还是这样。'),
    (5, 250, 666, 'Often, the less there is to justify a traditional custom, the harder it is to get rid of it.', '很多时候，一个老规矩越是没道理，就越难改掉。'),
    (5, 251, 667, 'And now the minister prayed.', '现在，牧师开始祈祷了。'),
    (5, 251, 668, 'A good, generous prayer it was, and went into details: it pleaded for the church, and the little children of the church; for the other churches of the village; for the village itself; for the county; for the State; for the State officers; for the United States; for the churches of the United States; for Congress; for the President; for the officers of the Government; for poor sailors, tossed by stormy seas; for the oppressed millions groaning under the heel of European monarchies and Oriental despotisms; for such as have the light and the good tidings, and yet have not eyes to see nor ears to hear withal; for the heathen in the far islands of the sea; and closed with a supplication that the words he was about to speak might find grace and favor, and be as seed sown in fertile ground, yielding in time a grateful harvest of good.', '牧师做了个很棒的祈祷，说得特别详细：他为教堂和教堂里的小朋友们祈祷；为村里其他的教堂和村子祈祷；为县里、州里和州的官员们祈祷；为美国、美国的教堂、国会、总统和政府的官员们祈祷；他为那些在大海里遇到暴风雨的可怜水手祈祷；为那些被欧洲国王和东方暴君欺负的很多人祈祷；为那些知道好消息却看不见也听不见的人祈祷；为远方海岛上那些不信神的人祈祷；最后，他请求上帝，希望他接下来要说的话能像种子一样，种在肥沃的土地里，将来长出好多好的东西来。'),
    (5, 251, 669, 'Amen.', '阿门。'),
    (5, 252, 670, 'There was a rustling of dresses, and the standing congregation sat down.', '裙子发出沙沙的声音，站着的人们都坐了下来。'),
    (5, 252, 671, 'The boy whose history this book relates did not enjoy the prayer, he only endured it—if he even did that much.', '这个故事里的小男孩不喜欢祈祷，他只是在忍着，都不知道他有没有真的忍住。'),
    (5, 252, 672, 'He was restive all through it; he kept tally of the details of the prayer, unconsciously—for he was not listening, but he knew the ground of old, and the clergyman’s regular route over it—and when a little trifle of new matter was interlarded, his ear detected it and his whole nature resented it; he considered additions unfair, and scoundrelly.', '他整个祈祷过程都坐不住。他没有在听，却把祈祷的细节默默记下来，因为他对牧师那些老套的祈祷内容和顺序太熟悉了。每当牧师偷偷加进一点点新内容时，他耳朵一听就知道了，心里特别生气。他觉得这些多加的东西太不公平了，简直是坏透了。'),
    (5, 252, 673, 'In the midst of the prayer a fly had lit on the back of the pew in front of him and tortured his spirit by calmly rubbing its hands together, embracing its head with its arms, and polishing it so vigorously that it seemed to almost part company with the body, and the slender thread of a neck was exposed to view; scraping its wings with its hind legs and smoothing them to its body as if they had been coat-tails; going through its whole toilet as tranquilly as if it knew it was perfectly safe.', '祈祷的时候，一只苍蝇停在他前面长椅的椅背上。它不慌不忙地搓着前腿，抱着头，用力地擦呀擦，好像头都要跟身子分开了，细细的脖子都露出来了。它又用后腿刮刮翅膀，把翅膀理顺贴在身上，就像穿了件燕尾服。苍蝇慢悠悠地打扮着自己，好像知道这里很安全，一点也不害怕。小男孩看着它，心里烦透了。'),
    (5, 252, 674, 'As indeed it was; for as sorely as Tom’s hands itched to grab for it they did not dare—he believed his soul would be instantly destroyed if he did such a thing while the prayer was going on.', '苍蝇确实很安全。小男孩的手痒痒地想去抓它，却不敢动。他觉得如果在祈祷的时候去抓苍蝇，自己的灵魂会立刻完蛋的。'),
    (5, 252, 675, 'But with the closing sentence his hand began to curve and steal forward; and the instant the “Amen” was out the fly was a prisoner of war.', '可是，当牧师念完最后一句，他的手就开始弯曲着，悄悄地伸了出去。牧师刚一说“阿门”，苍蝇就被他抓住了。'),
    (5, 252, 676, 'His aunt detected the act and made him let it go.', '他阿姨看到了，让他把苍蝇放了。'),
    (5, 253, 677, 'The minister gave out his text and droned along monotonously through an argument that was so prosy that many a head by and by began to nod—and yet it was an argument that dealt in limitless fire and brimstone and thinned the predestined elect down to a company so small as to be hardly worth the saving.', '牧师讲起了他的道理，声音又单调又枯燥，很多人听着听着都打起了瞌睡。他讲的是关于地狱的熊熊烈火和硫磺，还说能得救的人太少了，少到几乎不值得去救了。'),
    (5, 253, 678, 'Tom counted the pages of the sermon; after church he always knew how many pages there had been, but he seldom knew anything else about the discourse.', '小男孩数着讲道稿的页数；每次礼拜结束后，他总是知道有几页，但其他内容他什么都不知道。'),
    (5, 253, 679, 'However, this time he was really interested for a little while.', '不过，这一次他真的有一小会儿很感兴趣。'),
    (5, 253, 680, 'The minister made a grand and moving picture of the assembling together of the world’s hosts at the millennium when the lion and the lamb should lie down together and a little child should lead them.', '牧师描绘了一幅又宏大又动人的画面：等到大家说的那个和平时代来临，狮子和羊会和平地躺在一起，一个小孩子来带领它们。'),
    (5, 253, 681, 'But the pathos, the lesson, the moral of the great spectacle were lost upon the boy; he only thought of the conspicuousness of the principal character before the on-looking nations; his face lit with the thought, and he said to himself that he wished he could be that child, if it was a tame lion.', '可是，小男孩没有理解这个大场面的悲伤、道理和意义。他只想着那个小孩子在所有国家面前是多么引人注目。他想到这里，脸上亮了起来，心想：如果那只狮子是温顺的，他真希望能是那个小孩子。'),
    (5, 254, 682, 'Now he lapsed into suffering again, as the dry argument was resumed.', '现在，随着枯燥的道理又开始讲起来，他又觉得难受了。'),
    (5, 254, 683, 'Presently he bethought him of a treasure he had and got it out.', '过了一会儿，他想起自己有个宝贝，就把它拿了出来。'),
    (5, 254, 684, 'It was a large black beetle with formidable jaws—a “pinchbug,” he called it.', '那是一只大大的黑甲虫，嘴巴很厉害，他管它叫“夹子虫”。'),
    (5, 254, 685, 'It was in a percussion-cap box.', '它装在一个火帽盒子里。'),
    (5, 254, 686, 'The first thing the beetle did was to take him by the finger.', '甲虫做的第一件事就是咬他的手指头。'),
    (5, 254, 687, 'A natural fillip followed, the beetle went floundering into the aisle and lit on its back, and the hurt finger went into the boy’s mouth.', '小男孩条件反射地一弹，甲虫就跌跌撞撞地掉到过道里，肚子朝上。他的手指头被咬疼了，就赶紧放进嘴里。'),
    (5, 254, 688, 'The beetle lay there working its helpless legs, unable to turn over.', '甲虫躺在那里，无助地挥舞着腿，翻不过身来。'),
    (5, 254, 689, 'Tom eyed it, and longed for it; but it was safe out of his reach.', '小男孩盯着它，很想要它；可是它已经远了，他抓不到了。'),
    (5, 254, 690, 'Other people uninterested in the sermon found relief in the beetle, and they eyed it too.', '其他对讲道不感兴趣的人也因为这只甲虫找到了乐趣，他们也盯着它看。'),
    (5, 254, 691, 'Presently a vagrant poodle dog came idling along, sad at heart, lazy with the summer softness and the quiet, weary of captivity, sighing for change.', '这时，一只流浪的贵宾犬溜达过来了。它心里有点难过，夏天懒洋洋的，它也不想被关起来，就想换个地方玩。'),
    (5, 254, 692, 'He spied the beetle; the drooping tail lifted and wagged.', '它看到了那只甲虫。耷拉着的尾巴一下子就竖起来，摇了摇。'),
    (5, 254, 693, 'He surveyed the prize; walked around it; smelt at it from a safe distance; walked around it again; grew bolder, and took a closer smell; then lifted his lip and made a gingerly snatch at it, just missing it; made another, and another; began to enjoy the diversion; subsided to his stomach with the beetle between his paws, and continued his experiments; grew weary at last, and then indifferent and absent-minded.', '它看看这个“奖品”。它绕着甲虫走了一圈，远远地闻了闻。又绕了一圈，胆子变大了，凑近闻了闻。然后，它抬起嘴唇，小心地去抓，没抓到。它又抓了一次，又抓了一次。它开始觉得很好玩。它趴下来，把甲虫放在爪子中间，继续玩。最后它玩累了，就变得不理它了，心里想着别的事。'),
    (5, 254, 694, 'His head nodded, and little by little his chin descended and touched the enemy, who seized it.', '它的头一点一点地往下点，下巴慢慢地碰到了“敌人”。甲虫一下子就咬住了它的下巴。'),
    (5, 254, 695, 'There was a sharp yelp, a flirt of the poodle’s head, and the beetle fell a couple of yards away, and lit on its back once more.', '贵宾犬“嗷”地大叫一声，猛地甩了甩头，甲虫就掉到好几米外，又四脚朝天地躺着了。'),
    (5, 254, 696, 'The neighboring spectators shook with a gentle inward joy, several faces went behind fans and hand-kerchiefs, and Tom was entirely happy.', '旁边看的人都偷偷地笑，好几个人用扇子或手帕挡住脸。汤姆 可真是太高兴了。'),
    (5, 254, 697, 'The dog looked foolish, and probably felt so; but there was resentment in his heart, too, and a craving for revenge.', '这只狗看起来傻乎乎的，可能它自己也觉得挺丢脸。但是它心里也挺不服气，想去报仇。'),
    (5, 254, 698, 'So he went to the beetle and began a wary attack on it again; jumping at it from every point of a circle, lighting with his fore-paws within an inch of the creature, making even closer snatches at it with his teeth, and jerking his head till his ears flapped again.', '于是它又走到甲虫那里，小心地又去攻击它。它从各个方向跳过去，前爪落在离甲虫很近的地方，用牙齿更近地去咬它。它还甩着头，耳朵又扇动起来了。'),
    (5, 254, 699, 'But he grew tired once more, after a while; tried to amuse himself with a fly but found no relief; followed an ant around, with his nose close to the floor, and quickly wearied of that; yawned, sighed, forgot the beetle entirely, and sat down on it.', '但过了一会儿，它又累了。它想和苍蝇玩，觉得没意思。它鼻子贴着地，跟着一只蚂蚁转，很快又玩腻了。它打了个哈欠，叹了口气，把甲虫忘得一干二净，然后一屁股坐了上去。'),
    (5, 254, 700, 'Then there was a wild yelp of agony and the poodle went sailing up the aisle; the yelps continued, and so did the dog; he crossed the house in front of the altar; he flew down the other aisle; he crossed before the doors; he clamored up the home-stretch; his anguish grew with his progress, till presently he was but a woolly comet moving in its orbit with the gleam and the speed of light.', '接着，贵宾犬痛苦地大叫一声，一下子就冲向过道。它一直叫着，也一直跑着。它跑过祭坛前面，穿过教堂；又飞快地跑下另一条过道；它跑过门前；它冲向终点。它跑得越快，就越痛苦。最后，它就像一颗毛茸茸的彗星，飞快地跑着，像一道光一样。'),
    (5, 254, 701, 'At last the frantic sufferer sheered from its course, and sprang into its master’s lap; he flung it out of the window, and the voice of distress quickly thinned away and died in the distance.', '最后，这只疼得乱跑的狗改了方向，一下子跳到主人的腿上。主人把它扔出了窗外，它难过的叫声很快就越来越小，然后听不见了。'),
    (5, 255, 702, 'By this time the whole church was red-faced and suffocating with suppressed laughter, and the sermon had come to a dead standstill.', '这时候，整个教堂里的人都憋着笑，脸涨得通红。布道也完全停了下来。'),
    (5, 255, 703, 'The discourse was resumed presently, but it went lame and halting, all possibility of impressiveness being at an end; for even the gravest sentiments were constantly being received with a smothered burst of unholy mirth, under cover of some remote pew-back, as if the poor parson had said a rarely facetious thing.', '讲道很快又开始了，但讲得很不顺，也一点都不严肃了。因为牧师说的再严肃的话，也会被后面座位上的人偷偷笑声打断，好像那个可怜的牧师说了很好笑的话一样。'),
    (5, 255, 704, 'It was a genuine relief to the whole congregation when the ordeal was over and the benediction pronounced.', '当这场“不容易”的事情终于结束，牧师说了祝福的话后，教堂里的人都真正松了一口气。'),
    (5, 256, 705, 'Tom Sawyer went home quite cheerful, thinking to himself that there was some satisfaction about divine service when there was a bit of variety in it.', '汤姆·索亚 高高兴兴地回家了，他心里想，礼拜仪式如果有点好玩的事，那还是挺不错的。'),
    (5, 256, 706, 'He had but one marring thought; he was willing that the dog should play with his pinchbug, but he did not think it was upright in him to carry it off.', '他就只有一个不太好的想法：他愿意让狗玩他的甲虫，但觉得狗把它叼走就不太好。'),
    (6, 257, 707, 'Monday morning found Tom Sawyer miserable.', '星期一早上，汤姆·索亚 觉得很难受。'),
    (6, 257, 708, 'Monday morning always found him so—because it began another week’s slow suffering in school.', '星期一早上他总是这样——因为又要开始在学校里慢慢“受苦”一周了。'),
    (6, 257, 709, 'He generally began that day with wishing he had had no intervening holiday, it made the going into captivity and fetters again so much more odious.', '他通常一到这天就希望没有假期，因为假期过后又要回学校（就像又被关起来一样），这让他觉得更讨厌。'),
    (6, 258, 710, 'Tom lay thinking.', '汤姆 躺着想事。'),
    (6, 258, 711, 'Presently it occurred to him that he wished he was sick; then he could stay home from school.', '过了一会儿，他想，要是自己生病了就好了；那样就可以不去上学了。'),
    (6, 258, 712, 'Here was a vague possibility.', '也许可以这样。'),
    (6, 258, 713, 'He canvassed his system.', '他检查了一下自己的身体有没有不舒服。'),
    (6, 258, 714, 'No ailment was found, and he investigated again.', '没发现哪里不舒服，他又检查了一遍。'),
    (6, 258, 715, 'This time he thought he could detect colicky symptoms, and he began to encourage them with considerable hope.', '这次他觉得好像有点肚子疼。他心里很高兴，就想着让肚子疼得更厉害一点。'),
    (6, 258, 716, 'But they soon grew feeble, and presently died wholly away.', '但是这些肚子疼的感觉很快就变弱了，然后完全消失了。'),
    (6, 258, 717, 'He reflected further.', '他又想了想。'),
    (6, 258, 718, 'Suddenly he discovered something.', '突然，他发现了一件事。'),
    (6, 258, 719, 'One of his upper front teeth was loose.', '他一颗上面的门牙松了。'),
    (6, 258, 720, 'This was lucky; he was about to begin to groan, as a “starter,” as he called it, when it occurred to him that if he came into court with that argument, his aunt would pull it out, and that would hurt.', '这可真幸运。他正想先哼哼几声，算是“开场白”，突然他想到，如果他用这个理由请假，姑妈会把牙拔掉，那可就太疼了。'),
    (6, 258, 721, 'So he thought he would hold the tooth in reserve for the present, and seek further.', '他想先把牙疼留着，再找找别的。'),
    (6, 258, 722, 'Nothing offered for some little time, and then he remembered hearing the doctor tell about a certain thing that laid up a patient for two or three weeks and threatened to make him lose a finger.', '一会儿都没想出啥。他突然想起医生说过一种病，会让人躺两三周，还可能让手指掉下来。'),
    (6, 258, 723, 'So the boy eagerly drew his sore toe from under the sheet and held it up for inspection.', '于是，他赶紧把疼的脚趾从被子里伸出来，举起来给大家看。'),
    (6, 258, 724, 'But now he did not know the necessary symptoms.', '可他不知道这种病会有什么样子。'),
    (6, 258, 725, 'However, it seemed well worth while to chance it, so he fell to groaning with considerable spirit.', '算了，试试吧！他就很有精神地开始哼哼起来。'),
    (6, 259, 726, 'But Sid slept on unconscious.', '可是希德还在睡，没醒。'),
    (6, 260, 727, 'Tom groaned louder, and fancied that he began to feel pain in the toe.', '汤姆哼得更大声了，还觉得脚趾真的有点疼。'),
    (6, 261, 728, 'No result from Sid.', '希德没有反应。'),
    (6, 262, 729, 'Tom was panting with his exertions by this time.', '这时，汤姆已经累得直喘气了。'),
    (6, 262, 730, 'He took a rest and then swelled himself up and fetched a succession of admirable groans.', '他休息了一下，然后鼓起肚子，又哼了几声好听的。'),
    (6, 263, 731, 'Sid snored on.', '希德还在打呼噜。'),
    (6, 264, 732, 'Tom was aggravated.', '汤姆有点生气了。'),
    (6, 264, 733, 'He said, “Sid, Sid!” and shook him.', '他说：“希德，希德！”然后摇了摇他。'),
    (6, 264, 734, 'This course worked well, and Tom began to groan again.', '这招很管用，汤姆又开始哼哼了。'),
    (6, 264, 735, 'Sid yawned, stretched, then brought himself up on his elbow with a snort, and began to stare at Tom.', '希德打了个哈欠，伸了伸懒腰，然后哼了一声，用手肘撑起身子，看着汤姆。'),
    (6, 264, 736, 'Tom went on groaning.', '汤姆还在哼哼。'),
    (6, 264, 737, 'Sid said:', '希德说：'),
    (6, 265, 738, '“Tom!', '“汤姆！'),
    (6, 265, 739, 'Say, Tom!”', '喂，汤姆！”'),
    (6, 265, 740, '[No response.]', '[没有回答。]'),
    (6, 265, 741, '“Here, Tom!', '“喂，汤姆！'),
    (6, 265, 742, 'TOM!', '汤姆！'),
    (6, 265, 743, 'What is the matter, Tom?”', '汤姆，你怎么了？”'),
    (6, 265, 744, 'And he shook him and looked in his face anxiously.', '他摇了摇他，着急地看着他的脸。'),
    (6, 266, 745, 'Tom moaned out:', '汤姆哼哼着说：'),
    (6, 267, 746, '“Oh, don’t, Sid.', '“哦，希德，别这样。'),
    (6, 267, 747, 'Don’t joggle me.”', '别晃我。”'),
    (6, 268, 748, '“Why, what’s the matter, Tom?', '“哎呀，汤姆，你怎么了？'),
    (6, 268, 749, 'I must call auntie.”', '我得去叫阿姨了。”'),
    (6, 269, 750, '“No—never mind.', '“不—没关系。'),
    (6, 269, 751, 'It’ll be over by and by, maybe.', '也许很快就会好了。'),
    (6, 269, 752, 'Don’t call anybody.”', '不要叫任何人来。”'),
    (6, 270, 753, '“But I must!', '“可是我一定要叫人来！'),
    (6, 270, 754, '_Don’t_ groan so, Tom, it’s awful.', '汤姆，别再哼哼了，太难受了。'),
    (6, 270, 755, 'How long you been this way?”', '你这样多久了？”'),
    (6, 271, 756, '“Hours.', '“好几个小时了。'),
    (6, 271, 757, 'Ouch!', '哎哟！'),
    (6, 271, 758, 'Oh, don’t stir so, Sid, you’ll kill me.”', '噢，希德，别动来动去了，你会把我弄死的。”'),
    (6, 272, 759, '“Tom, why didn’t you wake me sooner?', '“汤姆，你为什么不早点叫醒我？'),
    (6, 272, 760, 'Oh, Tom, _don’t!', '噢，汤姆，不要这样！'),
    (6, 272, 761, '_ It makes my flesh crawl to hear you.', '听你这么哼哼，我全身都起鸡皮疙瘩了。'),
    (6, 272, 762, 'Tom, what is the matter?”', '汤姆，你怎么了？”'),
    (6, 273, 763, '“I forgive you everything, Sid.', '“希德，我原谅你所有的事情。'),
    (6, 273, 764, '[Groan.]', '[哼哼声。]'),
    (6, 273, 765, 'Everything you’ve ever done to me.', '你对我做过的所有事。'),
    (6, 273, 766, 'When I’m gone—”', '等我走了以后——”'),
    (6, 274, 767, '“Oh, Tom, you ain’t dying, are you?', '“噢，汤姆，你不是快死了吧？'),
    (6, 274, 768, 'Don’t, Tom—oh, don’t.', '别这样，汤姆——噢，别这样。'),
    (6, 274, 769, 'Maybe—”', '也许——”'),
    (6, 275, 770, '“I forgive everybody, Sid.', '“我原谅每一个人，希德。'),
    (6, 275, 771, '[Groan.]', '[哼哼声。]'),
    (6, 275, 772, 'Tell ’em so, Sid.', '希德，告诉他们。'),
    (6, 275, 773, 'And Sid, you give my window-sash and my cat with one eye to that new girl that’s come to town, and tell her—”', '还有希德，你把我的窗框和我那只独眼猫送给刚来镇上的那个新女孩，告诉她——”'),
    (6, 276, 774, 'But Sid had snatched his clothes and gone.', '可是希德已经抓起他的衣服跑了。'),
    (6, 276, 775, 'Tom was suffering in reality, now, so handsomely was his imagination working, and so his groans had gathered quite a genuine tone.', '汤姆现在真的在受苦了，因为他的想象力太丰富了，所以他的哼哼声也变得非常真实了。'),
    (6, 277, 776, 'Sid flew downstairs and said:', '希德飞快地跑下楼，喊道：'),
    (6, 278, 777, '“Oh, Aunt Polly, come!', '“噢，波莉姨妈，快来！'),
    (6, 278, 778, 'Tom’s dying!”', '汤姆快死了！”'),
    (6, 279, 779, '“Dying!”', '“快死了？”'),
    (6, 280, 780, '“Yes’m.', '“是的，太太。”'),
    (6, 280, 781, 'Don’t wait—come quick!”', '“别等了—快来！”'),
    (6, 281, 782, '“Rubbage!', '“胡说！'),
    (6, 281, 783, 'I don’t believe it!”', '我不相信！”'),
    (6, 282, 784, 'But she fled upstairs, nevertheless, with Sid and Mary at her heels.', '但她还是跑上楼了，希德 和 玛丽 紧跟着她。'),
    (6, 282, 785, 'And her face grew white, too, and her lip trembled.', '她的脸也白了，嘴唇也在抖。'),
    (6, 282, 786, 'When she reached the bedside she gasped out:', '她走到床边时，喘着气说：'),
    (6, 283, 787, '“You, Tom!', '“你，汤姆！'),
    (6, 283, 788, 'Tom, what’s the matter with you?”', '汤姆，你怎么了？”'),
    (6, 284, 789, '“Oh, auntie, I’m—”', '“哦，姨妈，我—”'),
    (6, 285, 790, '“What’s the matter with you—what is the matter with you, child?”', '“你怎么了—孩子，你怎么了？”'),
    (6, 286, 791, '“Oh, auntie, my sore toe’s mortified!”', '“哦，姨妈，我的脚趾头疼死了！”'),
    (6, 287, 792, 'The old lady sank down into a chair and laughed a little, then cried a little, then did both together.', '老太太一屁股坐到椅子上，先是笑了笑，又哭了一会儿，然后又哭又笑。'),
    (6, 287, 793, 'This restored her and she said:', '这让她缓过来了，她说道：'),
    (6, 288, 794, '“Tom, what a turn you did give me.', '“汤姆，你真是吓了我一大跳。'),
    (6, 288, 795, 'Now you shut up that nonsense and climb out of this.”', '现在别胡闹了，快起来吧。”'),
    (6, 289, 796, 'The groans ceased and the pain vanished from the toe.', '哼哼声停了，脚趾头的疼痛也消失了。'),
    (6, 289, 797, 'The boy felt a little foolish, and he said:', '男孩觉得有点儿不好意思，他说：'),
    (6, 290, 798, '“Aunt Polly, it _seemed_ mortified, and it hurt so I never minded my tooth at all.”', '“波莉姨妈，它好像疼死了，疼得我连牙齿都忘了。”'),
    (6, 291, 799, '“Your tooth, indeed!', '“你的牙齿，真的吗！'),
    (6, 291, 800, 'What’s the matter with your tooth?”', '你的牙齿怎么了？”'),
    (6, 292, 801, '“One of them’s loose, and it aches perfectly awful.”', '“我有一颗牙松了，疼得厉害。”'),
    (6, 293, 802, '“There, there, now, don’t begin that groaning again.', '“好了好了，别再哼哼了。'),
    (6, 293, 803, 'Open your mouth.', '张开嘴巴。'),
    (6, 293, 804, 'Well—your tooth _is_ loose, but you’re not going to die about that.', '嗯—你的牙齿是松了，但你不会因此死掉的。'),
    (6, 293, 805, 'Mary, get me a silk thread, and a chunk of fire out of the kitchen.”', '玛丽，去给我拿一根丝线，再从厨房拿一块火炭来。”'),
    (6, 294, 806, 'Tom said:', '汤姆 说：'),
    (6, 295, 807, '“Oh, please, auntie, don’t pull it out.', '“哦，求求你，姨妈，别拔掉它。'),
    (6, 295, 808, 'It don’t hurt any more.', '它不疼了。'),
    (6, 295, 809, 'I wish I may never stir if it does.', '如果它还疼，我就再也不动了。'),
    (6, 295, 810, 'Please don’t, auntie.', '求你，姨妈，别拔。'),
    (6, 295, 811, 'I don’t want to stay home from school.”', '我不想在家待着，不去学校。”'),
    (6, 296, 812, '“Oh, you don’t, don’t you?', '“噢，你不想吗？'),
    (6, 296, 813, 'So all this row was because you thought you’d get to stay home from school and go a-fishing?', '你闹腾了半天，就因为你以为能不去上学，好去钓鱼吗？'),
    (6, 296, 814, 'Tom, Tom, I love you so, and you seem to try every way you can to break my old heart with your outrageousness.”', '汤姆，汤姆，我真爱你，可你总用调皮捣蛋让我伤透了心。”'),
    (6, 296, 815, 'By this time the dental instruments were ready.', '这时，拔牙的工具都准备好了。'),
    (6, 296, 816, 'The old lady made one end of the silk thread fast to Tom’s tooth with a loop and tied the other to the bedpost.', '老太太用线的一头把汤姆的牙齿套住，另一头系在床柱上。'),
    (6, 296, 817, 'Then she seized the chunk of fire and suddenly thrust it almost into the boy’s face.', '然后她拿起一团火，突然把它伸到男孩的脸前。'),
    (6, 296, 818, 'The tooth hung dangling by the bedpost, now.', '现在，那颗牙就挂在床柱边荡来荡去。'),
    (6, 297, 819, 'But all trials bring their compensations.', '不过，受了苦，总会有好事发生。'),
    (6, 297, 820, 'As Tom wended to school after breakfast, he was the envy of every boy he met because the gap in his upper row of teeth enabled him to expectorate in a new and admirable way.', '汤姆吃完早饭去上学，他遇到的每个男孩都羡慕他，因为他上排牙齿有个洞，让他能用一种很酷的方式吐口水。'),
    (6, 297, 821, 'He gathered quite a following of lads interested in the exhibition; and one that had cut his finger and had been a centre of fascination and homage up to this time, now found himself suddenly without an adherent, and shorn of his glory.', '他吸引了一群喜欢看他表演的男孩子；有个男孩以前手指头受伤，一直都是大家围着看的明星，现在突然没人理他了，他的风头也没了。'),
    (6, 297, 822, 'His heart was heavy, and he said with a disdain which he did not feel that it wasn’t anything to spit like Tom Sawyer; but another boy said, “Sour grapes!” and he wandered away a dismantled hero.', '他心里很难受，嘴上却假装不屑地说，像汤姆·索亚那样吐口水，有什么了不起的；可另一个男孩说：“吃不到葡萄说葡萄酸！”他就这样，不再是英雄，伤心地走开了。'),
    (6, 298, 823, 'Shortly Tom came upon the juvenile pariah of the village, Huckleberry Finn, son of the town drunkard.', '没多久，汤姆就遇到了村里那个大家不太喜欢的小孩哈克贝利·费恩，他是镇上爱喝酒叔叔的儿子。'),
    (6, 298, 824, 'Huckleberry was cordially hated and dreaded by all the mothers of the town, because he was idle and lawless and vulgar and bad—and because all their children admired him so, and delighted in his forbidden society, and wished they dared to be like him.', '镇上所有的妈妈们都非常讨厌和害怕哈克贝利，因为他很懒，不听话，又粗鲁又调皮——更因为她们的孩子都特别喜欢他，喜欢跟他玩那些不让玩的游戏，还希望自己也敢像他一样。'),
    (6, 298, 825, 'Tom was like the rest of the respectable boys, in that he envied Huckleberry his gaudy outcast condition, and was under strict orders not to play with him.', '汤姆和其他那些规矩的男孩一样，他羡慕哈克贝利那种被排斥却很酷的生活，而且他被严格命令不能和哈克贝利玩。'),
    (6, 298, 826, 'So he played with him every time he got a chance.', '所以，他一有机会就和他玩。'),
    (6, 298, 827, 'Huckleberry was always dressed in the cast-off clothes of full-grown men, and they were in perennial bloom and fluttering with rags.', '哈克贝利总是穿着大人穿旧的衣服，那些衣服总是破破烂烂的，飘着布条。'),
    (6, 298, 828, 'His hat was a vast ruin with a wide crescent lopped out of its brim; his coat, when he wore one, hung nearly to his heels and had the rearward buttons far down the back; but one suspender supported his trousers; the seat of the trousers bagged low and contained nothing, the fringed legs dragged in the dirt when not rolled up.', '他的帽子很大，破了一个大大的月牙形缺口；他穿的外套几乎拖到脚后跟，后面的扣子也都系得很低；只有一根背带吊着他的裤子；裤子屁股那儿松松垮垮的，里面空空的，裤腿边磨成了穗子，不卷起来就拖在地上。'),
    (6, 299, 829, 'Huckleberry came and went, at his own free will.', '哈克贝利来去自由，想怎么样就怎么样。'),
    (6, 299, 830, 'He slept on doorsteps in fine weather and in empty hogsheads in wet; he did not have to go to school or to church, or call any being master or obey anybody; he could go fishing or swimming when and where he chose, and stay as long as it suited him; nobody forbade him to fight; he could sit up as late as he pleased; he was always the first boy that went barefoot in the spring and the last to resume leather in the fall; he never had to wash, nor put on clean clothes; he could swear wonderfully.', '天气好的时候，哈克贝利睡在别人家门口；下雨的时候，就睡在空的酒桶里。他不用去上学，也不用去教堂。他不用听谁的命令，也不用服从任何人。他想去哪儿钓鱼或游泳，想待多久都行。没人不让他打架。他想熬夜到多晚都可以。他总是春天里第一个不穿鞋的男孩，也是秋天里最后一个穿鞋的男孩。他从来不用洗澡，也不用穿干净衣服。他骂人的话也说得可溜了。'),
    (6, 299, 831, 'In a word, everything that goes to make life precious that boy had.', '总之，所有让生活变得快乐的事情，那个男孩都有。'),
    (6, 299, 832, 'So thought every harassed, hampered, respectable boy in St. Petersburg.', '圣彼得斯堡镇上每个被管着、被约束的“好孩子”都这样想。'),
    (6, 300, 833, 'Tom hailed the romantic outcast:', '汤姆向这个自由自在的“野孩子”打招呼：'),
    (6, 301, 834, '“Hello, Huckleberry!”', '“你好，哈克贝利！”'),
    (6, 302, 835, '“Hello yourself, and see how you like it.”', '“你也好啊，你自己看看喜不喜欢。”'),
    (6, 303, 836, '“What’s that you got?”', '“你拿的是什么？”'),
    (6, 304, 837, '“Dead cat.”', '“死猫。”'),
    (6, 305, 838, '“Lemme see him, Huck.', '“让我看看他，哈克。'),
    (6, 305, 839, 'My, he’s pretty stiff.', '哎呀，他真硬。'),
    (6, 305, 840, 'Where’d you get him?”', '你在哪儿找到他的？”'),
    (6, 306, 841, '“Bought him off’n a boy.”', '从一个男孩那里买的。'),
    (6, 307, 842, '“What did you give?”', '你给了什么？'),
    (6, 308, 843, '“I give a blue ticket and a bladder that I got at the slaughter-house.”', '我给了一张蓝色的票，还有一个我在屠宰场拿到的气球。'),
    (6, 309, 844, '“Where’d you get the blue ticket?”', '你的蓝票是从哪里来的？'),
    (6, 310, 845, '“Bought it off’n Ben Rogers two weeks ago for a hoop-stick.”', '两周前，我用一个铁环棒，从 本·罗杰斯 那里买的。'),
    (6, 311, 846, '“Say—what is dead cats good for, Huck?”', '哎——死猫有什么用啊，哈克？'),
    (6, 312, 847, '“Good for?', '有什么用？'),
    (6, 312, 848, 'Cure warts with.”', '可以治疣子。'),
    (6, 313, 849, '“No!', '不是吧！'),
    (6, 313, 850, 'Is that so?', '真的吗？'),
    (6, 313, 851, 'I know something that’s better.”', '我知道一个更好的办法。'),
    (6, 314, 852, '“I bet you don’t.', '我才不信呢。'),
    (6, 314, 853, 'What is it?”', '是什么呀？'),
    (6, 315, 854, '“Why, spunk-water.”', '嘿，是树洞水。'),
    (6, 316, 855, '“Spunk-water!', '树洞水！'),
    (6, 316, 856, 'I wouldn’t give a dern for spunk-water.”', '树洞水一点用都没有。'),
    (6, 317, 857, '“You wouldn’t, wouldn’t you?', '你不信？'),
    (6, 317, 858, 'D’you ever try it?”', '你试过吗？'),
    (6, 318, 859, '“No, I hain’t.', '没有，我没试过。'),
    (6, 318, 860, 'But Bob Tanner did.”', '但是鲍勃·坦纳试过。'),
    (6, 319, 861, '“Who told you so!”', '谁告诉你的！'),
    (6, 320, 862, '“Why, he told Jeff Thatcher, and Jeff told Johnny Baker, and Johnny told Jim Hollis, and Jim told Ben Rogers, and Ben told a nigger, and the nigger told me.', '哎呀，他告诉了杰夫 撒切尔，杰夫告诉了约翰尼·贝克，约翰尼告诉了 吉姆 霍利斯，吉姆 告诉了 本·罗杰斯，本告诉了一个黑人，那个黑人又告诉了我。'),
    (6, 320, 863, 'There now!”', '这下你知道了吧！'),
    (6, 321, 864, '“Well, what of it?', '那又怎么样？'),
    (6, 321, 865, 'They’ll all lie.', '他们都会说谎。'),
    (6, 321, 866, 'Leastways all but the nigger.', '至少除了那个黑人。'),
    (6, 321, 867, 'I don’t know _him_.', '我不认识他。'),
    (6, 321, 868, 'But I never see a nigger that _wouldn’t_ lie.', '但我从没见过一个黑人不会说谎。'),
    (6, 321, 869, 'Shucks!', '呸！'),
    (6, 321, 870, 'Now you tell me how Bob Tanner done it, Huck.”', '现在你告诉我，鲍勃·坦纳是怎么做到的，哈克。'),
    (6, 322, 871, '“Why, he took and dipped his hand in a rotten stump where the rain-water was.”', '“哎呀，他把手伸进了一个有雨水的烂树桩里。”'),
    (6, 323, 872, '“In the daytime?”', '“白天吗？”'),
    (6, 324, 873, '“Certainly.”', '“当然啦！”'),
    (6, 325, 874, '“With his face to the stump?”', '“脸对着树桩吗？”'),
    (6, 326, 875, '“Yes.', '“是呀。'),
    (6, 326, 876, 'Least I reckon so.”', '我想是吧。”'),
    (6, 327, 877, '“Did he say anything?”', '“他说了什么吗？”'),
    (6, 328, 878, '“I don’t reckon he did.', '“我想他没有。'),
    (6, 328, 879, 'I don’t know.”', '我不知道。”'),
    (6, 329, 880, '“Aha!', '“啊哈！'),
    (6, 329, 881, 'Talk about trying to cure warts with spunk-water such a blame fool way as that!', '这种笨办法根本治不好疣子！'),
    (6, 329, 882, 'Why, that ain’t a-going to do any good.', '哎呀，那根本没用。'),
    (6, 329, 883, 'You got to go all by yourself, to the middle of the woods, where you know there’s a spunk-water stump, and just as it’s midnight you back up against the stump and jam your hand in and say:', '你得一个人走到森林深处，找到一个有雨水的烂树桩。等半夜的时候，你背对着树桩，把手伸进去，然后说：'),
    (6, 330, 884, '‘Barley-corn, barley-corn, injun-meal shorts, Spunk-water, spunk-water, swaller these warts,’', '‘大麦粒，大麦粒，玉米粉渣，臭水，臭水，把这些疣子吞掉吧，’'),
    (6, 331, 885, 'and then walk away quick, eleven steps, with your eyes shut, and then turn around three times and walk home without speaking to anybody.', '然后闭着眼睛快走开，走十一步。接着转三圈，然后不和任何人说话就回家。'),
    (6, 331, 886, 'Because if you speak the charm’s busted.”', '因为如果你说话了，咒语就没用了。”'),
    (6, 332, 887, '“Well, that sounds like a good way; but that ain’t the way Bob Tanner done.”', '“嗯，这个办法听起来不错；但这不是鲍勃·坦纳做的。”'),
    (6, 333, 888, '“No, sir, you can bet he didn’t, becuz he’s the wartiest boy in this town; and he wouldn’t have a wart on him if he’d knowed how to work spunk-water.', '“不，他肯定没那么做，因为他是镇上疣子最多的男孩；如果他知道怎么用臭水，他身上就不会有疣子了。'),
    (6, 333, 889, 'I’ve took off thousands of warts off of my hands that way, Huck.', '我用那种方法去掉了手上成千上万个疣子，哈克。'),
    (6, 333, 890, 'I play with frogs so much that I’ve always got considerable many warts.', '我总是和青蛙玩，所以手上总是有很多疣子。'),
    (6, 333, 891, 'Sometimes I take ’em off with a bean.”', '有时候我用豆子把它们去掉。”'),
    (6, 334, 892, '“Yes, bean’s good.', '“是呀，豆子很好用。'),
    (6, 334, 893, 'I’ve done that.”', '我也那样做过。”'),
    (6, 335, 894, '“Have you?', '“你做过吗？'),
    (6, 335, 895, 'What’s your way?”', '你的办法是什么？”'),
    (6, 336, 896, '“You take and split the bean, and cut the wart so as to get some blood, and then you put the blood on one piece of the bean and take and dig a hole and bury it ’bout midnight at the crossroads in the dark of the moon, and then you burn up the rest of the bean.', '“你把豆子掰开，把疣子弄破一点，让它流点血。然后把血滴在豆子的一半上，接着挖个洞，在半夜、在月亮看不见的时候，把它埋在十字路口。然后把剩下的豆子烧掉。'),
    (6, 336, 897, 'You see that piece that’s got the blood on it will keep drawing and drawing, trying to fetch the other piece to it, and so that helps the blood to draw the wart, and pretty soon off she comes.”', '你看，沾了血的那一半豆子会一直吸，一直吸，想要把另一半拉过来。这样呢，血就能把疣子吸走，很快疣子就掉了。”'),
    (6, 337, 898, '“Yes, that’s it, Huck—that’s it; though when you’re burying it if you say ‘Down bean; off wart; come no more to bother me!’ it’s better.', '“是呀，就是这样，哈克——就是这样；不过，如果你在埋的时候说‘豆子下去；疣子掉下；别再来烦我！’那就更好了。'),
    (6, 337, 899, 'That’s the way Joe Harper does, and he’s been nearly to Coonville and most everywheres.', '乔·哈珀就是这么做的，他去过浣熊镇，几乎所有地方都去过了。'),
    (6, 337, 900, 'But say—how do you cure ’em with dead cats?”', '不过你说——怎么用死猫来治呢？”'),
    (6, 338, 901, '“Why, you take your cat and go and get in the grave-yard ’long about midnight when somebody that was wicked has been buried; and when it’s midnight a devil will come, or maybe two or three, but you can’t see ’em, you can only hear something like the wind, or maybe hear ’em talk; and when they’re taking that feller away, you heave your cat after ’em and say, ‘Devil follow corpse, cat follow devil, warts follow cat, I’m done with ye!’', '“嘿，你带着猫，半夜去墓地。那里埋了一个坏人。到了半夜，魔鬼就会来。你看不见他们，只能听到风声，或者他们说话。当他们带走那个坏人的时候，你就把猫扔过去，然后说：‘魔鬼跟着死人跑，猫跟着魔鬼跑，瘊子跟着猫跑，我好了！’'),
    (6, 338, 902, 'That’ll fetch _any_ wart.”', '这样就能把瘊子弄掉！”'),
    (6, 339, 903, '“Sounds right.', '“听起来有道理。'),
    (6, 339, 904, 'D’you ever try it, Huck?”', '你试过吗，哈克？”'),
    (6, 340, 905, '“No, but old Mother Hopkins told me.”', '“没有，但是霍普金斯老奶奶告诉我的。”'),
    (6, 341, 906, '“Well, I reckon it’s so, then.', '“嗯，那我想是真的了。'),
    (6, 341, 907, 'Becuz they say she’s a witch.”', '因为他们都说她是个巫婆。”'),
    (6, 342, 908, '“Say!', '“哎呀！'),
    (6, 342, 909, 'Why, Tom, I _know_ she is.', '哎呀，汤姆，我就是知道她是。'),
    (6, 342, 910, 'She witched pap.', '她把爸爸施了巫术。'),
    (6, 342, 911, 'Pap says so his own self.', '爸爸自己说的。'),
    (6, 342, 912, 'He come along one day, and he see she was a-witching him, so he took up a rock, and if she hadn’t dodged, he’d a got her.', '有一天他看到她在施魔法，就拿起一块石头。如果她没躲开，爸爸就打到她了。'),
    (6, 342, 913, 'Well, that very night he rolled off’n a shed wher’ he was a layin drunk, and broke his arm.”', '那天晚上，爸爸喝醉了，从棚子上摔下来，把胳膊摔断了。”'),
    (6, 343, 914, '“Why, that’s awful.', '“哎呀，这太可怕了。'),
    (6, 343, 915, 'How did he know she was a-witching him?”', '他怎么知道她在对他施魔法呢？”'),
    (6, 344, 916, '“Lord, pap can tell, easy.', '“天哪，爸爸很容易就能看出来。'),
    (6, 344, 917, 'Pap says when they keep looking at you right stiddy, they’re a-witching you.', '爸爸说，如果他们一直盯着你看，就是在对你施魔法。'),
    (6, 344, 918, 'Specially if they mumble.', '特别是如果他们嘴里念念有词的话。'),
    (6, 344, 919, 'Becuz when they mumble they’re saying the Lord’s Prayer backards.”', '因为他们念念有词的时候，是在倒着念《主祷文》。”'),
    (6, 345, 920, '“Say, Hucky, when you going to try the cat?”', '“哎，哈克，你什么时候去试那个猫啊？”'),
    (6, 346, 921, '“To-night.', '“今晚。'),
    (6, 346, 922, 'I reckon they’ll come after old Hoss Williams to-night.”', '我想他们今晚会来找老霍斯·威廉姆斯。”'),
    (6, 347, 923, '“But they buried him Saturday.', '“可是他们周六就埋了他啊。'),
    (6, 347, 924, 'Didn’t they get him Saturday night?”', '他们周六晚上没带走他吗？”'),
    (6, 348, 925, '“Why, how you talk!', '“你说什么呢！'),
    (6, 348, 926, 'How could their charms work till midnight?', '他们的咒语怎么可能等到半夜才有用呢？'),
    (6, 348, 927, '—and _then_ it’s Sunday.', '——而且那时就是星期天了。'),
    (6, 348, 928, 'Devils don’t slosh around much of a Sunday, I don’t reckon.”', '我想，魔鬼星期天一般不会到处晃悠的。”'),
    (6, 349, 929, '“I never thought of that.', '“我从没想过这个。'),
    (6, 349, 930, 'That’s so.', '是这样啊。”'),
    (6, 349, 931, 'Lemme go with you?”', '我能跟你一起去吗？'),
    (6, 350, 932, '“Of course—if you ain’t afeard.”', '当然啦，如果你不怕的话。'),
    (6, 351, 933, '“Afeard!', '害怕！'),
    (6, 351, 934, '’Tain’t likely.', '才不会呢。'),
    (6, 351, 935, 'Will you meow?”', '你会喵喵叫吗？'),
    (6, 352, 936, '“Yes—and you meow back, if you get a chance.', '嗯，如果你有机会，你也喵喵叫。'),
    (6, 352, 937, 'Last time, you kep’ me a-meowing around till old Hays went to throwing rocks at me and says ‘Dern that cat!’ and so I hove a brick through his window—but don’t you tell.”', '上次你一直让我喵喵叫，直到老海斯开始扔石头打我，还说‘真是只讨厌的猫！’，所以我朝他窗户扔了块砖头——但你可别说出去哦。'),
    (6, 353, 938, '“I won’t.', '我不会的。'),
    (6, 353, 939, 'I couldn’t meow that night, becuz auntie was watching me, but I’ll meow this time.', '那天晚上我没法喵喵叫，因为阿姨在看着我，但这次我会喵喵叫的。'),
    (6, 353, 940, 'Say—what’s that?”', '哎——那是什么？'),
    (6, 354, 941, '“Nothing but a tick.”', '只是一只蜱虫。'),
    (6, 355, 942, '“Where’d you get him?”', '你从哪儿弄来的？'),
    (6, 356, 943, '“Out in the woods.”', '在树林里。'),
    (6, 357, 944, '“What’ll you take for him?”', '你用它换什么？'),
    (6, 358, 945, '“I don’t know.', '我不知道。'),
    (6, 358, 946, 'I don’t want to sell him.”', '我不想卖掉它。'),
    (6, 359, 947, '“All right.', '好吧。'),
    (6, 359, 948, 'It’s a mighty small tick, anyway.”', '反正它只是一只很小的蜱虫。'),
    (6, 360, 949, '“Oh, anybody can run a tick down that don’t belong to them.', '哦，谁都能抓到不属于自己的蜱虫。'),
    (6, 360, 950, 'I’m satisfied with it.', '我对它很满意。'),
    (6, 360, 951, 'It’s a good enough tick for me.”', '对我来说，它已经够好了。'),
    (6, 361, 952, '“Sho, there’s ticks a plenty.', '哼，蜱虫多的是呢。'),
    (6, 361, 953, 'I could have a thousand of ’em if I wanted to.”', '我想要的话，能有一千只呢。'),
    (6, 362, 954, '“Well, why don’t you?', '那你为什么不弄呢？'),
    (6, 362, 955, 'Becuz you know mighty well you can’t.', '因为你很清楚你做不到。'),
    (6, 362, 956, 'This is a pretty early tick, I reckon.', '我猜，这是一只很早出现的蜱虫。'),
    (6, 362, 957, 'It’s the first one I’ve seen this year.”', '这是我今年看到的第一只呢。'),
    (6, 363, 958, '“Say, Huck—I’ll give you my tooth for him.”', '哎，哈克——我把我的牙齿给你，来换它。'),
    (6, 364, 959, '“Less see it.”', '让我看看。'),
    (6, 365, 960, 'Tom got out a bit of paper and carefully unrolled it.', '汤姆拿出一张小纸片，然后小心翼翼地打开了它。'),
    (6, 365, 961, 'Huckleberry viewed it wistfully.', '哈克伯里看着它，心里很想要。'),
    (6, 365, 962, 'The temptation was very strong.', '他很想很想要。'),
    (6, 365, 963, 'At last he said:', '他终于说：'),
    (6, 366, 964, '“Is it genuwyne?”', '“这是真的吗？”'),
    (6, 367, 965, 'Tom lifted his lip and showed the vacancy.', '汤姆 抬起嘴唇，露出牙齿的空隙。'),
    (6, 368, 966, '“Well, all right,” said Huckleberry, “it’s a trade.”', '“好吧，”哈克伯里说，“我们换！”'),
    (6, 369, 967, 'Tom enclosed the tick in the percussion-cap box that had lately been the pinchbug’s prison, and the boys separated, each feeling wealthier than before.', '汤姆 把小虫子放进小盒子里，这个盒子之前关过甲虫。两个男孩分开了，都觉得比以前更开心了。'),
    (6, 370, 968, 'When Tom reached the little isolated frame school-house, he strode in briskly, with the manner of one who had come with all honest speed.', '汤姆 跑到小木头学校时，他快步走进去，好像自己一点也没迟到。'),
    (6, 370, 969, 'He hung his hat on a peg and flung himself into his seat with business-like alacrity.', '他把帽子挂好，一下子就坐下了。'),
    (6, 370, 970, 'The master, throned on high in his great splint-bottom arm-chair, was dozing, lulled by the drowsy hum of study.', '老师坐在大椅子上打瞌睡，被同学们小声读书的声音催眠了。'),
    (6, 370, 971, 'The interruption roused him.', '他被吵醒了。'),
    (6, 371, 972, '“Thomas Sawyer!”', '“汤姆·索亚！”'),
    (6, 372, 973, 'Tom knew that when his name was pronounced in full, it meant trouble.', '汤姆 知道，老师叫他全名，就是有麻烦了。'),
    (6, 373, 974, '“Sir!”', '“到！”'),
    (6, 374, 975, '“Come up here.', '“你过来。'),
    (6, 374, 976, 'Now, sir, why are you late again, as usual?”', '现在，你为什么又迟到了，老是这样？”'),
    (6, 375, 977, 'Tom was about to take refuge in a lie, when he saw two long tails of yellow hair hanging down a back that he recognized by the electric sympathy of love; and by that form was _the only vacant place_ on the girls’ side of the school-house.', '汤姆 正想撒谎，却看到一个他喜欢的女孩的背影，她长长的金发垂下来。在女生那边，_只有_她的旁边是空位。'),
    (6, 375, 978, 'He instantly said:', '他马上说：'),
    (6, 376, 979, '“_I stopped to talk with Huckleberry Finn!', '“_我停下来和 哈克贝利·费恩 说话了！_'),
    (6, 376, 980, '_”', '”'),
    (6, 377, 981, 'The master’s pulse stood still, and he stared helplessly.', '老师的心跳好像停了，他呆呆地看着。'),
    (6, 377, 982, 'The buzz of study ceased.', '大家都不读书了。'),
    (6, 377, 983, 'The pupils wondered if this foolhardy boy had lost his mind.', '同学们想，这个男孩是不是疯了？'),
    (6, 377, 984, 'The master said:', '老师说：'),
    (6, 378, 985, '“You—you did what?”', '“你——你做了什么？”'),
    (6, 379, 986, '“Stopped to talk with Huckleberry Finn.”', '“停下来和 哈克贝利·费恩 说话了。”'),
    (6, 380, 987, 'There was no mistaking the words.', '老师听得很清楚。'),
    (6, 381, 988, '“Thomas Sawyer, this is the most astounding confession I have ever listened to.', '“汤姆·索亚，这是我听过最最让人吃惊的话！'),
    (6, 381, 989, 'No mere ferule will answer for this offence.', '只是打手心，可不够惩罚你这次的错误。'),
    (6, 381, 990, 'Take off your jacket.”', '把你外套脱掉！”'),
    (6, 382, 991, 'The master’s arm performed until it was tired and the stock of switches notably diminished.', '老师的手都打累了，小树枝也用完了。'),
    (6, 382, 992, 'Then the order followed:', '接着，老师说：'),
    (6, 383, 993, '“Now, sir, go and sit with the girls!', '“好了，孩子，去跟女孩子们坐一起吧！'),
    (6, 383, 994, 'And let this be a warning to you.”', '记住这次教训哦。”'),
    (6, 384, 995, 'The titter that rippled around the room appeared to abash the boy, but in reality that result was caused rather more by his worshipful awe of his unknown idol and the dread pleasure that lay in his high good fortune.', '房间里有小声的笑声，男孩好像很不好意思。其实他脸红，是因为能跟那个他喜欢的女孩坐在一起，心里又高兴又有点害怕。'),
    (6, 384, 996, 'He sat down upon the end of the pine bench and the girl hitched herself away from him with a toss of her head.', '他坐在长凳的尽头，那个女孩把头一甩，挪开了身子，离他远一点。'),
    (6, 384, 997, 'Nudges and winks and whispers traversed the room, but Tom sat still, with his arms upon the long, low desk before him, and seemed to study his book.', '房间里有人互相推推，眨眨眼，小声说话。但是汤姆坐得很稳，他把胳膊放在身前的矮桌上，好像在认真看书。'),
    (6, 385, 998, 'By and by attention ceased from him, and the accustomed school murmur rose upon the dull air once more.', '慢慢地，大家不再注意他了，教室里又回到了以前那种吵吵闹闹的声音。'),
    (6, 385, 999, 'Presently the boy began to steal furtive glances at the girl.', '没多久，男孩开始偷偷看那个女孩。'),
    (6, 385, 1000, 'She observed it, “made a mouth” at him and gave him the back of her head for the space of a minute.', '她发现了，就朝他做了个鬼脸，然后转过头去，背对着他，有一分钟那么久。'),
    (6, 385, 1001, 'When she cautiously faced around again, a peach lay before her.', '等她小心翼翼地转过身来，发现面前放着一个桃子。'),
    (6, 385, 1002, 'She thrust it away.', '她把桃子推开了。'),
    (6, 385, 1003, 'Tom gently put it back.', '汤姆又轻轻地把它放了回去。'),
    (6, 385, 1004, 'She thrust it away again, but with less animosity.', '她又推开了一次，但这次没那么生气了。'),
    (6, 385, 1005, 'Tom patiently returned it to its place.', '汤姆耐心地把它放回原位。'),
    (6, 385, 1006, 'Then she let it remain.', '这次她没再动。'),
    (6, 385, 1007, 'Tom scrawled on his slate, “Please take it—I got more.”', '汤姆在石板上写道：“请收下吧——我还有很多。”'),
    (6, 385, 1008, 'The girl glanced at the words, but made no sign.', '女孩看了一眼那些字，但没有表示什么。'),
    (6, 385, 1009, 'Now the boy began to draw something on the slate, hiding his work with his left hand.', '现在，男孩开始在石板上画画，他用左手把画盖住。'),
    (6, 385, 1010, 'For a time the girl refused to notice; but her human curiosity presently began to manifest itself by hardly perceptible signs.', '一开始女孩假装没看见，但过了一会儿，她还是忍不住好奇，偷偷地看了起来。'),
    (6, 385, 1011, 'The boy worked on, apparently unconscious.', '男孩继续画画，假装没发现她在看。'),
    (6, 385, 1012, 'The girl made a sort of non-committal attempt to see, but the boy did not betray that he was aware of it.', '女孩又小心地想看一眼，但男孩没有露出他知道的表情。'),
    (6, 385, 1013, 'At last she gave in and hesitatingly whispered:', '最后，她放弃了，犹豫地小声说：'),
    (6, 386, 1014, '“Let me see it.”', '“给我看看。”'),
    (6, 387, 1015, 'Tom partly uncovered a dismal caricature of a house with two gable ends to it and a corkscrew of smoke issuing from the chimney.', '汤姆掀开了一点，露出了一幅画。画的是一栋奇怪的房子，房顶尖尖的，烟囱里冒着卷起来的烟。'),
    (6, 387, 1016, 'Then the girl’s interest began to fasten itself upon the work and she forgot everything else.', '女孩对这幅画越来越感兴趣，忘了其他所有事。'),
    (6, 387, 1017, 'When it was finished, she gazed a moment, then whispered:', '画画完了，她看了一会儿，然后小声说：'),
    (6, 388, 1018, '“It’s nice—make a man.”', '“画得真好，画个人吧。”'),
    (6, 389, 1019, 'The artist erected a man in the front yard, that resembled a derrick.', '画家（男孩）在房子前面画了一个人，那个人长得像个高高的吊车。'),
    (6, 389, 1020, 'He could have stepped over the house; but the girl was not hypercritical; she was satisfied with the monster, and whispered:', '那个人高得都能跨过房子了！但女孩没挑剔，她很满意这个“怪物”，小声说：'),
    (6, 390, 1021, '“It’s a beautiful man—now make me coming along.”', '“真是个帅哥——现在让我跟着你一起去吧。”'),
    (6, 391, 1022, 'Tom drew an hour-glass with a full moon and straw limbs to it and armed the spreading fingers with a portentous fan.', '汤姆 画了一个沙漏，上面有圆圆的月亮和稻草做的手脚。他还给张开的手指画了一把很特别的扇子。'),
    (6, 391, 1023, 'The girl said:', '女孩说：'),
    (6, 392, 1024, '“It’s ever so nice—I wish I could draw.”', '“画得真好啊！我真希望我也会画画。”'),
    (6, 393, 1025, '“It’s easy,” whispered Tom, “I’ll learn you.”', '“这很容易的，”汤姆 小声说，“我来教你。”'),
    (6, 394, 1026, '“Oh, will you?', '“哦，真的吗？'),
    (6, 394, 1027, 'When?”', '什么时候？”'),
    (6, 395, 1028, '“At noon.', '“中午的时候。'),
    (6, 395, 1029, 'Do you go home to dinner?”', '你回家吃午饭吗？”'),
    (6, 396, 1030, '“I’ll stay if you will.”', '“如果你留下，我就留下。”'),
    (6, 397, 1031, '“Good—that’s a whack.', '“好啊——就这样说定了。'),
    (6, 397, 1032, 'What’s your name?”', '你叫什么名字？”'),
    (6, 398, 1033, '“Becky Thatcher.', '“贝琪·撒切尔。'),
    (6, 398, 1034, 'What’s yours?', '你呢？'),
    (6, 398, 1035, 'Oh, I know.', '哦，我知道了。'),
    (6, 398, 1036, 'It’s Thomas Sawyer.”', '你是托马斯·索亚。”'),
    (6, 399, 1037, '“That’s the name they lick me by.', '“我挨打的时候他们会叫那个名字。'),
    (6, 399, 1038, 'I’m Tom when I’m good.', '我乖的时候，他们叫我 汤姆。'),
    (6, 399, 1039, 'You call me Tom, will you?”', '你叫我 汤姆，好吗？”'),
    (6, 400, 1040, '“Yes.”', '“好啊。”'),
    (6, 401, 1041, 'Now Tom began to scrawl something on the slate, hiding the words from the girl.', '现在，汤姆 开始在石板上乱写乱画，不让女孩看到他写了什么。'),
    (6, 401, 1042, 'But she was not backward this time.', '但这次她没有退缩。'),
    (6, 401, 1043, 'She begged to see.', '她央求着想看。'),
    (6, 401, 1044, 'Tom said:', '汤姆 说：'),
    (6, 402, 1045, '“Oh, it ain’t anything.”', '“哦，没什么的。”'),
    (6, 403, 1046, '“Yes it is.”', '“就是有呀！”'),
    (6, 404, 1047, '“No it ain’t.', '“不，真的没什么。'),
    (6, 404, 1048, 'You don’t want to see.”', '你不想看的。”'),
    (6, 405, 1049, '“Yes I do, indeed I do.', '“我想看，我真的想看。'),
    (6, 405, 1050, 'Please let me.”', '求求你让我看吧！”'),
    (6, 406, 1051, '“You’ll tell.”', '“你会说的。”'),
    (6, 407, 1052, '“No I won’t—deed and deed and double deed won’t.”', '“不，我不会说的——真的，真的，绝对不会说的。”'),
    (6, 408, 1053, '“You won’t tell anybody at all?', '“你真的不会告诉任何人吗？'),
    (6, 408, 1054, 'Ever, as long as you live?”', '一辈子都不会说吗？”'),
    (6, 409, 1055, '“No, I won’t ever tell _any_body.', '“不，我绝对不会告诉任何人的。'),
    (6, 409, 1056, 'Now let me.”', '现在让我看看。”'),
    (6, 410, 1057, '“Oh, _you_ don’t want to see!”', '“哦，你才不想看呢！”'),
    (6, 411, 1058, '“Now that you treat me so, I _will_ see.”', '“既然你这样对我，我偏要看！”'),
    (6, 411, 1059, 'And she put her small hand upon his and a little scuffle ensued, Tom pretending to resist in earnest but letting his hand slip by degrees till these words were revealed: “_I love you_.”', '她把小手放在他手上，两人轻轻推搡起来，汤姆假装很认真地抵抗，但慢慢地让他的手溜走，直到看到这些字：“我爱你。”'),
    (6, 412, 1060, '“Oh, you bad thing!”', '“哎呀，你这个小坏蛋！”'),
    (6, 412, 1061, 'And she hit his hand a smart rap, but reddened and looked pleased, nevertheless.', '她轻轻拍了一下他的手，脸红了，但看起来还是很高兴。'),
    (6, 413, 1062, 'Just at this juncture the boy felt a slow, fateful grip closing on his ear, and a steady lifting impulse.', '就在这时，男孩感到一只手慢慢地、牢牢地捏住了他的耳朵，并把他稳稳地提了起来。'),
    (6, 413, 1063, 'In that wise he was borne across the house and deposited in his own seat, under a peppering fire of giggles from the whole school.', '他就这样被提着穿过教室，放回了自己的座位上，全班同学都咯咯地笑个不停。'),
    (6, 413, 1064, 'Then the master stood over him during a few awful moments, and finally moved away to his throne without saying a word.', '老师在他身边站了几分钟，气氛很严肃，最后没说什么就走回了他的座位。'),
    (6, 413, 1065, 'But although Tom’s ear tingled, his heart was jubilant.', '虽然汤姆的耳朵火辣辣的，但他的心里却很高兴。'),
    (6, 414, 1066, 'As the school quieted down Tom made an honest effort to study, but the turmoil within him was too great.', '学校安静下来后，汤姆努力想学习，但他心里太激动了，静不下来。'),
    (6, 414, 1067, 'In turn he took his place in the reading class and made a botch of it; then in the geography class and turned lakes into mountains, mountains into rivers, and rivers into continents, till chaos was come again; then in the spelling class, and got “turned down,” by a succession of mere baby words, till he brought up at the foot and yielded up the pewter medal which he had worn with ostentation for months.', '轮到他读课文时，他读得一塌糊涂；然后上地理课时，他把湖泊说成山，把山说成河，把河说成大洲，真是乱七八糟；接着是拼写课，连一些非常简单的词都拼错了，结果他站到了队尾，还交出了他戴了几个月、一直很炫耀的锡奖章。'),
    (7, 415, 1068, 'The harder Tom tried to fasten his mind on his book, the more his ideas wandered.', '汤姆越努力想把心思放在书本上，他的想法就越是跑来跑去。'),
    (7, 415, 1069, 'So at last, with a sigh and a yawn, he gave it up.', '所以最后，他叹了口气，打了个哈欠，放弃了。'),
    (7, 415, 1070, 'It seemed to him that the noon recess would never come.', '他觉得中午的休息时间永远不会来。'),
    (7, 415, 1071, 'The air was utterly dead.', '空气一点都不流动。'),
    (7, 415, 1072, 'There was not a breath stirring.', '一点风都没有。'),
    (7, 415, 1073, 'It was the sleepiest of sleepy days.', '这是最让人犯困的一天。'),
    (7, 415, 1074, 'The drowsing murmur of the five and twenty studying scholars soothed the soul like the spell that is in the murmur of bees.', '二十五个学生们学习时发出的嗡嗡声，就像蜜蜂的声音一样，让人觉得很舒服，想睡觉。'),
    (7, 415, 1075, 'Away off in the flaming sunshine, Cardiff Hill lifted its soft green sides through a shimmering veil of heat, tinted with the purple of distance; a few birds floated on lazy wing high in the air; no other living thing was visible but some cows, and they were asleep.', '远处，在烈日下，卡迪夫山在热浪中，泛着远处的紫色，露出了它柔软的绿色山坡；几只鸟儿懒洋洋地在高空中飞翔；除了几头正在睡觉的牛，看不到其他活物。'),
    (7, 415, 1076, 'Tom’s heart ached to be free, or else to have something of interest to do to pass the dreary time.', '汤姆心里很渴望自由，或者能做点有趣的事来打发这无聊的时间。'),
    (7, 415, 1077, 'His hand wandered into his pocket and his face lit up with a glow of gratitude that was prayer, though he did not know it.', '他的手伸进了口袋，脸上露出了一丝感激的笑容，那就像在祈祷一样，虽然他自己并不知道。'),
    (7, 415, 1078, 'Then furtively the percussion-cap box came out.', '接着，他偷偷地拿出了那个火帽盒。'),
    (7, 415, 1079, 'He released the tick and put him on the long flat desk.', '他放出了那只蜱虫，把它放在长长的平桌上。'),
    (7, 415, 1080, 'The creature probably glowed with a gratitude that amounted to prayer, too, at this moment, but it was premature: for when he started thankfully to travel off, Tom turned him aside with a pin and made him take a new direction.', '这只小虫子此时可能也充满了感激，就像在祈祷一样，但这高兴得太早了：因为它刚想感激地走开，汤姆就用一根针把它拨到一边，让它换个方向走。'),
    (7, 416, 1081, 'Tom’s bosom friend sat next him, suffering just as Tom had been, and now he was deeply and gratefully interested in this entertainment in an instant.', '汤姆 的好朋友坐在他旁边，刚才也和 汤姆 一样不舒服。但很快，他一下子就被这个有趣的游戏吸引住了。'),
    (7, 416, 1082, 'This bosom friend was Joe Harper.', '这个好朋友就是 乔·哈珀。'),
    (7, 416, 1083, 'The two boys were sworn friends all the week, and embattled enemies on Saturdays.', '这两个小男孩，平时是一周的好朋友，可一到星期六就成了爱打闹的小敌人。'),
    (7, 416, 1084, 'Joe took a pin out of his lapel and began to assist in exercising the prisoner.', '乔从衣服上取下一枚别针，开始帮着逗弄那只小虫子。'),
    (7, 416, 1085, 'The sport grew in interest momently.', '这个游戏一下子变得更有趣了。'),
    (7, 416, 1086, 'Soon Tom said that they were interfering with each other, and neither getting the fullest benefit of the tick.', '很快，汤姆 说他们这样互相挤着，都没法好好玩那只小虫子。'),
    (7, 416, 1087, 'So he put Joe’s slate on the desk and drew a line down the middle of it from top to bottom.', '于是他把乔的小板子放到桌上，在板子中间从上到下画了一条线。'),
    (7, 417, 1088, '“Now,” said he, “as long as he is on your side you can stir him up and I’ll let him alone; but if you let him get away and get on my side, you’re to leave him alone as long as I can keep him from crossing over.”', '“听好了，”他说，“只要它在你这边，你就可以逗它，我不碰它；但如果你让它跑了，跑到我这边来，那我就要管它不让它跑过去。在这段时间里，你就不能碰它了。”'),
    (7, 418, 1089, '“All right, go ahead; start him up.”', '“好的，开始吧；去逗逗它！”'),
    (7, 419, 1090, 'The tick escaped from Tom, presently, and crossed the equator.', '那只小虫子很快就从汤姆那儿跑掉了，跑过了那条线。'),
    (7, 419, 1091, 'Joe harassed him awhile, and then he got away and crossed back again.', '乔逗了它一会儿，然后它又跑掉了，跑回了对面。'),
    (7, 419, 1092, 'This change of base occurred often.', '它就这样老是跑来跑去。'),
    (7, 419, 1093, 'While one boy was worrying the tick with absorbing interest, the other would look on with interest as strong, the two heads bowed together over the slate, and the two souls dead to all things else.', '一个男孩特别认真地逗着小虫子，另一个也一样认真地看着。两个小脑袋凑在一起，看着小板子，什么都忘了。'),
    (7, 419, 1094, 'At last luck seemed to settle and abide with Joe.', '最后，乔的运气好像越来越好。'),
    (7, 419, 1095, 'The tick tried this, that, and the other course, and got as excited and as anxious as the boys themselves, but time and again just as he would have victory in his very grasp, so to speak, and Tom’s fingers would be twitching to begin, Joe’s pin would deftly head him off, and keep possession.', '小虫子这边跑跑，那边跑跑，也像小男孩们一样，又激动又着急。每次眼看就要跑赢了，汤姆 的手指头都痒痒地想去碰它，乔的别针就会一下子把它挡回去，不让它跑掉。'),
    (7, 419, 1096, 'At last Tom could stand it no longer.', '最后，汤姆 再也忍不住了。'),
    (7, 419, 1097, 'The temptation was too strong.', '他太想去碰那只小虫子了。'),
    (7, 419, 1098, 'So he reached out and lent a hand with his pin.', '于是他伸出手，用自己的别针去帮了一下忙。'),
    (7, 419, 1099, 'Joe was angry in a moment.', '乔一下子就生气了。'),
    (7, 419, 1100, 'Said he:', '他说：'),
    (7, 420, 1101, '“Tom, you let him alone.”', '“汤姆，你别碰它！”'),
    (7, 421, 1102, '“I only just want to stir him up a little, Joe.”', '“乔，我只是想逗逗它嘛。”'),
    (7, 422, 1103, '“No, sir, it ain’t fair; you just let him alone.”', '“不行，这不公平；你别碰它！”'),
    (7, 423, 1104, '“Blame it, I ain’t going to stir him much.”', '“真是的，我又不会多碰它一下。”'),
    (7, 424, 1105, '“Let him alone, I tell you.”', '“我跟你说，你别碰它！”'),
    (7, 425, 1106, '“I won’t!”', '“我偏不！”'),
    (7, 426, 1107, '“You shall—he’s on my side of the line.”', '“你得！它在我这边呢！”'),
    (7, 427, 1108, '“Look here, Joe Harper, whose is that tick?”', '“喂，乔·哈珀，那只小虫子是谁的？”'),
    (7, 428, 1109, '“I don’t care whose tick he is—he’s on my side of the line, and you sha’n’t touch him.”', '“我才不管它是谁的呢——它在我这边，你不能碰它！”'),
    (7, 429, 1110, '“Well, I’ll just bet I will, though.', '“哼，我偏要碰。”'),
    (7, 429, 1111, 'He’s my tick and I’ll do what I blame please with him, or die!”', '“他是我的人，我想怎么对待他都行，不然我就去死！”'),
    (7, 430, 1112, 'A tremendous whack came down on Tom’s shoulders, and its duplicate on Joe’s; and for the space of two minutes the dust continued to fly from the two jackets and the whole school to enjoy it.', '“一个重重的巴掌打在汤姆的肩膀上，乔的肩膀上也挨了一下；接下来两分钟里，两件衣服上的灰尘一直往外飞，全校同学都看得可开心了。”'),
    (7, 430, 1113, 'The boys had been too absorbed to notice the hush that had stolen upon the school awhile before when the master came tiptoeing down the room and stood over them.', '“孩子们太专心了，没注意到之前学校里突然安静下来，因为老师踮着脚走到他们身边。”'),
    (7, 430, 1114, 'He had contemplated a good part of the performance before he contributed his bit of variety to it.', '“他先看了好一会儿，才加入了自己的‘表演’。”'),
    (7, 431, 1115, 'When school broke up at noon, Tom flew to Becky Thatcher, and whispered in her ear:', '“中午放学的时候，汤姆跑到贝琪·撒切尔身边，在她耳边悄悄说：”'),
    (7, 432, 1116, '“Put on your bonnet and let on you’re going home; and when you get to the corner, give the rest of ’em the slip, and turn down through the lane and come back.', '“‘戴上你的小帽子，假装要回家；等你走到拐角时，甩开他们，然后穿过小路回来。’”'),
    (7, 432, 1117, 'I’ll go the other way and come it over ’em the same way.”', '“‘我走另一条路，也用同样的方法甩开他们。’”'),
    (7, 433, 1118, 'So the one went off with one group of scholars, and the other with another.', '“于是，一个和一群同学走了，另一个和另一群同学走了。”'),
    (7, 433, 1119, 'In a little while the two met at the bottom of the lane, and when they reached the school they had it all to themselves.', '“不一会儿，他俩在小路的尽头碰面了；等他们回到学校的时候，学校里就只有他们两个人了。”'),
    (7, 433, 1120, 'Then they sat together, with a slate before them, and Tom gave Becky the pencil and held her hand in his, guiding it, and so created another surprising house.', '“然后他们坐在一起，面前放着一块写字板，汤姆把铅笔递给贝琪，牵着她的手教她画，就这样画出了一个令人惊喜的房子。”'),
    (7, 433, 1121, 'When the interest in art began to wane, the two fell to talking.', '“当画画的兴趣渐渐没了，他俩就开始聊天。”'),
    (7, 433, 1122, 'Tom was swimming in bliss.', '“汤姆觉得幸福极了。”'),
    (7, 433, 1123, 'He said:', '“他说：”'),
    (7, 434, 1124, '“Do you love rats?”', '“‘你喜欢老鼠吗？’”'),
    (7, 435, 1125, '“No!', '“‘不喜欢！’”'),
    (7, 435, 1126, 'I hate them!”', '“‘我讨厌它们！’”'),
    (7, 436, 1127, '“Well, I do, too—_live_ ones.', '“‘嗯，我也讨厌——活的。’”'),
    (7, 436, 1128, 'But I mean dead ones, to swing round your head with a string.”', '“‘但我说的是死老鼠，可以用绳子拴着，在你头顶上甩来甩去的那种。’”'),
    (7, 437, 1129, '“No, I don’t care for rats much, anyway.', '“‘不，反正我不太喜欢老鼠。’”'),
    (7, 437, 1130, 'What I like is chewing-gum.”', '“‘我喜欢的是口香糖。’”'),
    (7, 438, 1131, '“Oh, I should say so!', '“‘噢，我也喜欢！’”'),
    (7, 438, 1132, 'I wish I had some now.”', '“‘我现在真想有块啊。’”'),
    (7, 439, 1133, '“Do you?', '“‘是吗？’”'),
    (7, 439, 1134, 'I’ve got some.', '“‘我有一些。’”'),
    (7, 439, 1135, 'I’ll let you chew it awhile, but you must give it back to me.”', '“‘我可以让你嚼一会儿，但你嚼完必须还给我。’”'),
    (7, 440, 1136, 'That was agreeable, so they chewed it turn about, and dangled their legs against the bench in excess of contentment.', '“他们觉得这样很好，就轮流嚼着口香糖，开心得把腿悬在长凳外晃来晃去。”'),
    (7, 441, 1137, '“Was you ever at a circus?” said Tom.', '“汤姆说：‘你去过马戏团吗？’”'),
    (7, 442, 1138, '“Yes, and my pa’s going to take me again some time, if I’m good.”', '“‘去过，而且如果我乖的话，我爸爸还会再带我去。’”'),
    (7, 443, 1139, '“I been to the circus three or four times—lots of times.', '“‘我去过三四次马戏团了——去过好多次了。’”'),
    (7, 443, 1140, 'Church ain’t shucks to a circus.', '“‘教堂跟马戏团比起来简直太没意思了。’”'),
    (7, 443, 1141, 'There’s things going on at a circus all the time.', '马戏团里总是有好多好玩的事情。'),
    (7, 443, 1142, 'I’m going to be a clown in a circus when I grow up.”', '我长大了要当马戏团的小丑。'),
    (7, 444, 1143, '“Oh, are you!', '“哦，是吗！'),
    (7, 444, 1144, 'That will be nice.', '那会很好玩。'),
    (7, 444, 1145, 'They’re so lovely, all spotted up.”', '它们真可爱，身上都有斑点。”'),
    (7, 445, 1146, '“Yes, that’s so.', '“是的，就是那样。'),
    (7, 445, 1147, 'And they get slathers of money—most a dollar a day, Ben Rogers says.', '他们能赚好多钱呢——本·罗杰斯说，一天差不多能赚一美元。'),
    (7, 445, 1148, 'Say, Becky, was you ever engaged?”', '喂，贝琪，你订过婚吗？”'),
    (7, 446, 1149, '“What’s that?”', '“那是什么？”'),
    (7, 447, 1150, '“Why, engaged to be married.”', '“就是，要结婚了的意思。”'),
    (7, 448, 1151, '“No.”', '“没有。”'),
    (7, 449, 1152, '“Would you like to?”', '“你想吗？”'),
    (7, 450, 1153, '“I reckon so.', '“我猜想会的。'),
    (7, 450, 1154, 'I don’t know.', '我不知道。'),
    (7, 450, 1155, 'What is it like?”', '那是什么样的呀？”'),
    (7, 451, 1156, '“Like?', '“什么样？'),
    (7, 451, 1157, 'Why it ain’t like anything.', '嗨，它不像任何东西。'),
    (7, 451, 1158, 'You only just tell a boy you won’t ever have anybody but him, ever ever ever, and then you kiss and that’s all.', '你只要告诉一个男生，你永远永远永远只要他，然后亲一下，就那样。'),
    (7, 451, 1159, 'Anybody can do it.”', '谁都能做到。”'),
    (7, 452, 1160, '“Kiss?', '“亲亲？'),
    (7, 452, 1161, 'What do you kiss for?”', '为什么要亲亲呀？”'),
    (7, 453, 1162, '“Why, that, you know, is to—well, they always do that.”', '“哦，那个嘛，你知道，就是——嗯，他们总是那样做。”'),
    (7, 454, 1163, '“Everybody?”', '“所有人都会吗？”'),
    (7, 455, 1164, '“Why, yes, everybody that’s in love with each other.', '“嗯，是的，所有互相喜欢的人都会。'),
    (7, 455, 1165, 'Do you remember what I wrote on the slate?”', '你记得我写在石板上的是什么吗？”'),
    (7, 456, 1166, '“Ye—yes.”', '“嗯——嗯。”'),
    (7, 457, 1167, '“What was it?”', '“那是什么？”'),
    (7, 458, 1168, '“I sha’n’t tell you.”', '“我不会告诉你。”'),
    (7, 459, 1169, '“Shall I tell _you_?”', '“要我告诉你吗？”'),
    (7, 460, 1170, '“Ye—yes—but some other time.”', '“嗯——嗯——但是下次再说吧。”'),
    (7, 461, 1171, '“No, now.”', '“不，就现在。”'),
    (7, 462, 1172, '“No, not now—to-morrow.”', '“不，不是现在——是明天。”'),
    (7, 463, 1173, '“Oh, no, _now_.', '“哦，不，就现在。'),
    (7, 463, 1174, 'Please, Becky—I’ll whisper it, I’ll whisper it ever so easy.”', '求你了，贝琪——我小声说，我轻轻地小声说。”'),
    (7, 464, 1175, 'Becky hesitating, Tom took silence for consent, and passed his arm about her waist and whispered the tale ever so softly, with his mouth close to her ear.', '贝琪有点犹豫，汤姆就当她同意了，他搂着她的腰，嘴巴凑到她的耳朵边，轻轻地讲着这个故事。'),
    (7, 464, 1176, 'And then he added:', '然后他又说：'),
    (7, 465, 1177, '“Now you whisper it to me—just the same.”', '“现在你悄悄地跟我说——也这样说。”'),
    (7, 466, 1178, 'She resisted, for a while, and then said:', '她反抗了一会儿，然后说：'),
    (7, 467, 1179, '“You turn your face away so you can’t see, and then I will.', '“你把脸转过去，不许看，那样我就说。'),
    (7, 467, 1180, 'But you mustn’t ever tell anybody—_will_ you, Tom?', '但是你绝不能告诉任何人——好不好啊，汤姆？'),
    (7, 467, 1181, 'Now you won’t, _will_ you?”', '你肯定不会说，对不对？”'),
    (7, 468, 1182, '“No, indeed, indeed I won’t.', '“不，真的，我真的不会说。'),
    (7, 468, 1183, 'Now, Becky.”', '现在，贝琪。”'),
    (7, 469, 1184, 'He turned his face away.', '他把脸转过去了。'),
    (7, 469, 1185, 'She bent timidly around till her breath stirred his curls and whispered, “I—love—you!”', '她害羞地凑过去，直到她的气息吹动了他的卷发，她小声说：“我——爱——你！”'),
    (7, 470, 1186, 'Then she sprang away and ran around and around the desks and benches, with Tom after her, and took refuge in a corner at last, with her little white apron to her face.', '然后她跑开了，围着课桌和长凳跑了一圈又一圈，汤姆追在她后面。最后她躲在一个角落里，用她的小白围裙捂住了脸。'),
    (7, 470, 1187, 'Tom clasped her about her neck and pleaded:', '汤姆搂着她的脖子，请求道：'),
    (7, 471, 1188, '“Now, Becky, it’s all done—all over but the kiss.', '“现在，贝琪，都说完了——就差亲亲了。'),
    (7, 471, 1189, 'Don’t you be afraid of that—it ain’t anything at all.', '你别害怕——一点儿都不可怕。'),
    (7, 471, 1190, 'Please, Becky.”', '求你了，贝琪。”'),
    (7, 471, 1191, 'And he tugged at her apron and the hands.', '他拉了拉她的围裙和手。'),
    (7, 472, 1192, 'By and by she gave up, and let her hands drop; her face, all glowing with the struggle, came up and submitted.', '渐渐地她放弃了，把手放了下来；她的脸因为挣扎而红扑扑的，抬了起来，不再反抗了。'),
    (7, 472, 1193, 'Tom kissed the red lips and said:', '汤姆亲了亲那红红的嘴唇，说：'),
    (7, 473, 1194, '“Now it’s all done, Becky.', '“现在都做好了，贝琪。'),
    (7, 473, 1195, 'And always after this, you know, you ain’t ever to love anybody but me, and you ain’t ever to marry anybody but me, ever never and forever.', '从今以后，你要知道，你只能爱我一个人，也只能嫁给我一个人，永远永远都是这样。'),
    (7, 473, 1196, 'Will you?”', '好吗？”'),
    (7, 474, 1197, '“No, I’ll never love anybody but you, Tom, and I’ll never marry anybody but you—and you ain’t to ever marry anybody but me, either.”', '“不，我只会爱你一个人，汤姆，也只会嫁给你一个人——你也不能和除了我以外的任何人结婚。”'),
    (7, 475, 1198, '“Certainly.', '“当然。'),
    (7, 475, 1199, 'Of course.', '那当然。'),
    (7, 475, 1200, 'That’s _part_ of it.', '这是其中一部分。”'),
    (7, 475, 1201, 'And always coming to school or when we’re going home, you’re to walk with me, when there ain’t anybody looking—and you choose me and I choose you at parties, because that’s the way you do when you’re engaged.”', '每次来学校或者回家，你都要和我一起走，当没人看着的时候。在聚会上，你选我，我选你，因为订婚的人都这样。'),
    (7, 476, 1202, '“It’s so nice.', '“真好。'),
    (7, 476, 1203, 'I never heard of it before.”', '我以前没听说过这个。”'),
    (7, 477, 1204, '“Oh, it’s ever so gay!', '“哦，那可太开心了！'),
    (7, 477, 1205, 'Why, me and Amy Lawrence—”', '哎呀，我和艾米·劳伦斯——”'),
    (7, 478, 1206, 'The big eyes told Tom his blunder and he stopped, confused.', '大眼睛让汤姆知道他犯错了，他停了下来，有点懵。'),
    (7, 479, 1207, '“Oh, Tom!', '“哦，汤姆！'),
    (7, 479, 1208, 'Then I ain’t the first you’ve ever been engaged to!”', '那我不是第一个跟你订婚的人了！”'),
    (7, 480, 1209, 'The child began to cry.', '孩子开始哭了。'),
    (7, 480, 1210, 'Tom said:', '汤姆说：'),
    (7, 481, 1211, '“Oh, don’t cry, Becky, I don’t care for her any more.”', '“哦，别哭，贝琪，我不再喜欢她了。”'),
    (7, 482, 1212, '“Yes, you do, Tom—you know you do.”', '“才不是呢，汤姆——你知道你还喜欢她的。”'),
    (7, 483, 1213, 'Tom tried to put his arm about her neck, but she pushed him away and turned her face to the wall, and went on crying.', '汤姆想抱她的脖子，但她推开他，脸对着墙，继续哭。'),
    (7, 483, 1214, 'Tom tried again, with soothing words in his mouth, and was repulsed again.', '汤姆又试了一次，嘴里说着好听的话，但又被她推开了。'),
    (7, 483, 1215, 'Then his pride was up, and he strode away and went outside.', '他觉得有点生气了，就大步走开，出去了。'),
    (7, 483, 1216, 'He stood about, restless and uneasy, for a while, glancing at the door, every now and then, hoping she would repent and come to find him.', '他在外面站着，一会儿看看门，心里很不舒服，希望她能后悔出来找他。'),
    (7, 483, 1217, 'But she did not.', '但她没有。'),
    (7, 483, 1218, 'Then he began to feel badly and fear that he was in the wrong.', '然后他开始觉得难过，害怕自己做错了。'),
    (7, 483, 1219, 'It was a hard struggle with him to make new advances, now, but he nerved himself to it and entered.', '他很挣扎，不知道该不该再过去，但他鼓起勇气，走了进去。'),
    (7, 483, 1220, 'She was still standing back there in the corner, sobbing, with her face to the wall.', '她还在角落里，脸对着墙，小声哭着。'),
    (7, 483, 1221, 'Tom’s heart smote him.', '汤姆心里很难过。'),
    (7, 483, 1222, 'He went to her and stood a moment, not knowing exactly how to proceed.', '他走到她身边，站了一会儿，不知道该怎么办。'),
    (7, 483, 1223, 'Then he said hesitatingly:', '然后他有点犹豫地说：'),
    (7, 484, 1224, '“Becky, I—I don’t care for anybody but you.”', '“贝琪，我——我只喜欢你一个人。”'),
    (7, 485, 1225, 'No reply—but sobs.', '没有回答——只有抽泣声。'),
    (7, 486, 1226, '“Becky”—pleadingly.', '“贝琪”——他央求道。'),
    (7, 486, 1227, '“Becky, won’t you say something?”', '“贝琪，你能不能说句话？”'),
    (7, 487, 1228, 'More sobs.', '又是一阵抽泣声。'),
    (7, 488, 1229, 'Tom got out his chiefest jewel, a brass knob from the top of an andiron, and passed it around her so that she could see it, and said:', '汤姆拿出他最宝贝的东西，是一个壁炉架上的铜把手。他把它在她面前晃了晃，让她能看到，然后说：'),
    (7, 489, 1230, '“Please, Becky, won’t you take it?”', '“求你了，贝琪，你收下好不好？”'),
    (7, 490, 1231, 'She struck it to the floor.', '她把它摔到地上。'),
    (7, 490, 1232, 'Then Tom marched out of the house and over the hills and far away, to return to school no more that day.', '然后，汤姆 走出家门，翻过山，走得很远，那天再也不回学校了。'),
    (7, 490, 1233, 'Presently Becky began to suspect.', '过了一会儿，贝琪 开始觉得不对劲。'),
    (7, 490, 1234, 'She ran to the door; he was not in sight; she flew around to the play-yard; he was not there.', '她跑到门口，没看见他；她又跑去院子，他也不在那儿。'),
    (7, 490, 1235, 'Then she called:', '然后她喊道：'),
    (7, 491, 1236, '“Tom!', '“汤姆！'),
    (7, 491, 1237, 'Come back, Tom!”', '回来，汤姆！”'),
    (7, 492, 1238, 'She listened intently, but there was no answer.', '她仔细听着，但是没有回应。'),
    (7, 492, 1239, 'She had no companions but silence and loneliness.', '只有安静和孤单陪着她。'),
    (7, 492, 1240, 'So she sat down to cry again and upbraid herself; and by this time the scholars began to gather again, and she had to hide her griefs and still her broken heart and take up the cross of a long, dreary, aching afternoon, with none among the strangers about her to exchange sorrows with.', '她又坐下来哭了，还怪自己。这时，同学们又开始聚过来了，她只好藏起难过，假装不伤心。漫长又难过的下午，身边一个能分担的人都没有。'),
    (8, 493, 1241, 'Tom dodged hither and thither through lanes until he was well out of the track of returning scholars, and then fell into a moody jog.', '汤姆 在小路上东躲西藏，直到远离了回家的同学，然后闷闷不乐地小跑起来。'),
    (8, 493, 1242, 'He crossed a small “branch” two or three times, because of a prevailing juvenile superstition that to cross water baffled pursuit.', '他过了一条小溪两三次，因为小朋友们都觉得，只要过了水，别人就追不到了。'),
    (8, 493, 1243, 'Half an hour later he was disappearing behind the Douglas mansion on the summit of Cardiff Hill, and the school-house was hardly distinguishable away off in the valley behind him.', '半小时后，他消失在卡迪夫山山顶上的道格拉斯大房子后面。学校在他身后的山谷里，几乎都看不见了。'),
    (8, 493, 1244, 'He entered a dense wood, picked his pathless way to the centre of it, and sat down on a mossy spot under a spreading oak.', '他走进一片茂密的森林，在没有路的地方走到了森林中间，坐在一棵大橡树下长满苔藓的地方。'),
    (8, 493, 1245, 'There was not even a zephyr stirring; the dead noonday heat had even stilled the songs of the birds; nature lay in a trance that was broken by no sound but the occasional far-off hammering of a wood-pecker, and this seemed to render the pervading silence and sense of loneliness the more profound.', '一点风都没有。中午热得要命，连鸟都不唱歌了。整个大自然像睡着了一样，只有远处偶尔传来啄木鸟的声音。这让周围更安静，他感到更孤单了。'),
    (8, 493, 1246, 'The boy’s soul was steeped in melancholy; his feelings were in happy accord with his surroundings.', '男孩心里很忧伤，他的心情和周围的环境一样。'),
    (8, 493, 1247, 'He sat long with his elbows on his knees and his chin in his hands, meditating.', '他坐了很久，胳膊肘放在膝盖上，下巴托在手里，想着事情。'),
    (8, 493, 1248, 'It seemed to him that life was but a trouble, at best, and he more than half envied Jimmy Hodges, so lately released; it must be very peaceful, he thought, to lie and slumber and dream forever and ever, with the wind whispering through the trees and caressing the grass and the flowers over the grave, and nothing to bother and grieve about, ever any more.', '他觉得生活太麻烦了。他有点羡慕刚去世的吉米·霍奇斯。他想，永远躺着睡觉、做梦，一定很平静。风在树林里轻声吹过，轻轻抚摸着坟墓上的草和花，再也没有什么可烦恼和伤心的了。'),
    (8, 493, 1249, 'If he only had a clean Sunday-school record he could be willing to go, and be done with it all.', '要是他有一个清白的主日学校记录，他就能安心地走了，把这一切都结束掉。'),
    (8, 493, 1250, 'Now as to this girl.', '现在说说这个女孩。'),
    (8, 493, 1251, 'What had he done?', '他做了什么呢？'),
    (8, 493, 1252, 'Nothing.', '什么也没做。'),
    (8, 493, 1253, 'He had meant the best in the world, and been treated like a dog—like a very dog.', '他本来是好心好意，却像狗一样被对待。'),
    (8, 493, 1254, 'She would be sorry some day—maybe when it was too late.', '总有一天她会后悔的——也许到时候就太晚了。'),
    (8, 493, 1255, 'Ah, if he could only die _temporarily_!', '哎，要是他能暂时死掉就好了！'),
    (8, 494, 1256, 'But the elastic heart of youth cannot be compressed into one constrained shape long at a time.', '但是年轻人的心是很有弹性的，不会被一种情绪一直压着。'),
    (8, 494, 1257, 'Tom presently began to drift insensibly back into the concerns of this life again.', '过了一会儿，汤姆 又不知不觉地开始关心起生活里的事情了。'),
    (8, 494, 1258, 'What if he turned his back, now, and disappeared mysteriously?', '要是他现在转身，神秘地消失了呢？'),
    (8, 494, 1259, 'What if he went away—ever so far away, into unknown countries beyond the seas—and never came back any more!', '要是他走了——走得很远很远，去大海那边陌生的国家——再也不回来了呢！'),
    (8, 494, 1260, 'How would she feel then!', '那时她会怎么想呢！'),
    (8, 494, 1261, 'The idea of being a clown recurred to him now, only to fill him with disgust.', '他又想到当小丑，这让他觉得很恶心。'),
    (8, 494, 1262, 'For frivolity and jokes and spotted tights were an offense, when they intruded themselves upon a spirit that was exalted into the vague august realm of the romantic.', '因为那些好玩的事、笑话和带斑点的紧身衣，让他很不高兴，他心里正在想很厉害、很浪漫的事。'),
    (8, 494, 1263, 'No, he would be a soldier, and return after long years, all war-worn and illustrious.', '不，他要当个士兵，很多年后回来，又勇敢又有名。'),
    (8, 494, 1264, 'No—better still, he would join the Indians, and hunt buffaloes and go on the warpath in the mountain ranges and the trackless great plains of the Far West, and away in the future come back a great chief, bristling with feathers, hideous with paint, and prance into Sunday-school, some drowsy summer morning, with a blood-curdling war-whoop, and sear the eyeballs of all his companions with unappeasable envy.', '不——更好的是，他要加入印第安人，打野牛，在远西的山里和没路的大平原上打仗。以后他会变成一个戴着羽毛、脸上画着可怕图案的大酋长回来，在一个困困的夏日早晨，带着可怕的战吼，得意洋洋地走进主日学校，让所有小伙伴都羡慕得不得了。'),
    (8, 494, 1265, 'But no, there was something gaudier even than this.', '但不对，还有比这更酷的！'),
    (8, 494, 1266, 'He would be a pirate!', '他要当海盗！'),
    (8, 494, 1267, 'That was it!', '对，就是这样！'),
    (8, 494, 1268, '_now_ his future lay plain before him, and glowing with unimaginable splendor.', '现在他的未来就在眼前，闪着特别亮的光。'),
    (8, 494, 1269, 'How his name would fill the world, and make people shudder!', '他的名字会响遍世界，让人们害怕！'),
    (8, 494, 1270, 'How gloriously he would go plowing the dancing seas, in his long, low, black-hulled racer, the Spirit of the Storm, with his grisly flag flying at the fore!', '他会驾驶又长又矮的黑船“暴风之灵”，前面飘着他可怕的旗子，在波涛汹涌的海上航行，多威风啊！'),
    (8, 494, 1271, 'And at the zenith of his fame, how he would suddenly appear at the old village and stalk into church, brown and weather-beaten, in his black velvet doublet and trunks, his great jack-boots, his crimson sash, his belt bristling with horse-pistols, his crime-rusted cutlass at his side, his slouch hat with waving plumes, his black flag unfurled, with the skull and crossbones on it, and hear with swelling ecstasy the whisperings, “It’s Tom Sawyer the Pirate!', '在他最有名的时候，他会突然回到老村子，大步走进教堂！他晒得黑黑的，穿着黑色的天鹅绒上衣和短裤，大靴子，红腰带，腰带上插满了手枪，腰间挂着生锈的刀，头上戴着插羽毛的宽边帽，还展开他的黑旗，上面有骷髅和交叉骨。他会非常开心听到大家小声说：“是汤姆·索亚海盗！'),
    (8, 494, 1272, '—the Black Avenger of the Spanish Main!”', '——西班牙海域的黑色复仇者！”'),
    (8, 495, 1273, 'Yes, it was settled; his career was determined.', '对，他决定好了；他的未来就是这样了。'),
    (8, 495, 1274, 'He would run away from home and enter upon it.', '他要离家出走，开始这个计划。'),
    (8, 495, 1275, 'He would start the very next morning.', '他明天一早就开始。'),
    (8, 495, 1276, 'Therefore he must now begin to get ready.', '所以他现在必须开始准备。'),
    (8, 495, 1277, 'He would collect his resources together.', '他要把他的东西都找出来。'),
    (8, 495, 1278, 'He went to a rotten log near at hand and began to dig under one end of it with his Barlow knife.', '他走到旁边一根烂木头那儿，用他的巴洛刀开始挖木头的一头。'),
    (8, 495, 1279, 'He soon struck wood that sounded hollow.', '他很快就挖到一个听起来是空的木头。'),
    (8, 495, 1280, 'He put his hand there and uttered this incantation impressively:', '他把手伸进去，庄重地念起咒语：'),
    (8, 496, 1281, '“What hasn’t come here, come!', '“没来到这里的，快来！'),
    (8, 496, 1282, 'What’s here, stay here!”', '在这里的，留下！”'),
    (8, 497, 1283, 'Then he scraped away the dirt, and exposed a pine shingle.', '然后他把土刮掉，露出一块松木瓦片。'),
    (8, 497, 1284, 'He took it up and disclosed a shapely little treasure-house whose bottom and sides were of shingles.', '他拿起瓦片，露出了一个漂亮的小宝藏盒，盒子底和边都是用瓦片做的。'),
    (8, 497, 1285, 'In it lay a marble.', '里面躺着一颗弹珠。'),
    (8, 497, 1286, 'Tom’s astonishment was boundless!', '汤姆惊讶极了！'),
    (8, 497, 1287, 'He scratched his head with a perplexed air, and said:', '他很困惑地挠了挠头，说：'),
    (8, 498, 1288, '“Well, that beats anything!”', '“哇，这真是太奇怪了！”'),
    (8, 499, 1289, 'Then he tossed the marble away pettishly, and stood cogitating.', '然后他生气地把弹珠扔掉，站在那里想事情。'),
    (8, 499, 1290, 'The truth was, that a superstition of his had failed, here, which he and all his comrades had always looked upon as infallible.', '其实，他相信的一个迷信在这里没有灵验，他和他的小伙伴们一直都觉得这个迷信是从来不会错的。'),
    (8, 499, 1291, 'If you buried a marble with certain necessary incantations, and left it alone a fortnight, and then opened the place with the incantation he had just used, you would find that all the marbles you had ever lost had gathered themselves together there, meantime, no matter how widely they had been separated.', '如果你把一颗弹珠埋起来，念一些魔法咒语，然后放上两个星期。当你再念咒语打开时，你所有弄丢的弹珠都会跑到那里去，不管它们之前分得有多远。'),
    (8, 499, 1292, 'But now, this thing had actually and unquestionably failed.', '可是现在，这个办法真的不管用了。'),
    (8, 499, 1293, 'Tom’s whole structure of faith was shaken to its foundations.', '汤姆一下子什么都不信了。'),
    (8, 499, 1294, 'He had many a time heard of this thing succeeding but never of its failing before.', '他听过很多次这个办法成功了，可从来没听说过它会失败。'),
    (8, 499, 1295, 'It did not occur to him that he had tried it several times before, himself, but could never find the hiding-places afterward.', '他没有想起来，自己以前也试过好几次，可后来怎么也找不到藏弹珠的地方了。'),
    (8, 499, 1296, 'He puzzled over the matter some time, and finally decided that some witch had interfered and broken the charm.', '他想了半天，最后觉得一定是有个巫婆来捣乱，把魔法弄坏了。'),
    (8, 499, 1297, 'He thought he would satisfy himself on that point; so he searched around till he found a small sandy spot with a little funnel-shaped depression in it.', '他想弄清楚是不是这样，于是四处寻找，直到找到一小块沙地，上面有一个小小的漏斗形坑洞。'),
    (8, 499, 1298, 'He laid himself down and put his mouth close to this depression and called—', '他趴下来，嘴巴凑到这个小坑旁边，大声喊——'),
    (8, 500, 1299, '“Doodle-bug, doodle-bug, tell me what I want to know!', '“嘟嘟虫，嘟嘟虫，快告诉我我想知道的事！'),
    (8, 500, 1300, 'Doodle-bug, doodle-bug, tell me what I want to know!”', '嘟嘟虫，嘟嘟虫，快告诉我我想知道的事！”'),
    (8, 501, 1301, 'The sand began to work, and presently a small black bug appeared for a second and then darted under again in a fright.', '沙子动了起来，不一会儿，一只小黑虫子露了个头，然后吓得赶紧又钻了回去。'),
    (8, 502, 1302, '“He dasn’t tell!', '“它不敢说！'),
    (8, 502, 1303, 'So it _was_ a witch that done it.', '果然是巫婆搞的鬼。'),
    (8, 502, 1304, 'I just knowed it.”', '我就知道！”'),
    (8, 503, 1305, 'He well knew the futility of trying to contend against witches, so he gave up discouraged.', '他知道跟巫婆作对是没用的，所以很泄气，放弃了。'),
    (8, 503, 1306, 'But it occurred to him that he might as well have the marble he had just thrown away, and therefore he went and made a patient search for it.', '可是他突然想到，不如把自己刚刚扔掉的那颗弹珠找回来。于是他过去，很有耐心地找了起来。'),
    (8, 503, 1307, 'But he could not find it.', '可是他没有找到。'),
    (8, 503, 1308, 'Now he went back to his treasure-house and carefully placed himself just as he had been standing when he tossed the marble away; then he took another marble from his pocket and tossed it in the same way, saying:', '于是他回到那个“藏宝地”，小心地站好，就像刚才扔弹珠的时候一样。然后他从口袋里掏出另一颗弹珠，也用同样的方法扔了出去，嘴里还念着：'),
    (8, 504, 1309, '“Brother, go find your brother!”', '“兄弟，快去找你的兄弟吧！”'),
    (8, 505, 1310, 'He watched where it stopped, and went there and looked.', '他看着弹珠停在哪里，然后走过去看。'),
    (8, 505, 1311, 'But it must have fallen short or gone too far; so he tried twice more.', '可是弹珠不是扔近了就是扔远了；于是他又试了两次。'),
    (8, 505, 1312, 'The last repetition was successful.', '最后一次，他成功了。'),
    (8, 505, 1313, 'The two marbles lay within a foot of each other.', '两颗弹珠躺在一起，离得很近。'),
    (8, 506, 1314, 'Just here the blast of a toy tin trumpet came faintly down the green aisles of the forest.', '就在这时，森林里绿色的林间小道上传来一阵微弱的玩具锡喇叭声。'),
    (8, 506, 1315, 'Tom flung off his jacket and trousers, turned a suspender into a belt, raked away some brush behind the rotten log, disclosing a rude bow and arrow, a lath sword and a tin trumpet, and in a moment had seized these things and bounded away, barelegged, with fluttering shirt.', '汤姆脱掉夹克和裤子，把背带当腰带系上。他扒开烂木头后面的草丛，里面藏着一把粗糙的弓箭、一把木板剑和一个锡喇叭。他飞快地抓起这些东西，光着腿，衬衫随风飘舞，跑走了。'),
    (8, 506, 1316, 'He presently halted under a great elm, blew an answering blast, and then began to tiptoe and look warily out, this way and that.', '他很快在一棵大榆树下停了下来，也吹了一声喇叭来回应。接着他踮着脚，小心翼翼地向四周张望。'),
    (8, 506, 1317, 'He said cautiously—to an imaginary company:', '他小心地对想象中的同伴们说：'),
    (8, 507, 1318, '“Hold, my merry men!', '“停下，我的伙伴们！'),
    (8, 507, 1319, 'Keep hid till I blow.”', '藏好，等我吹号角。”'),
    (8, 508, 1320, 'Now appeared Joe Harper, as airily clad and elaborately armed as Tom.', '这时，乔·哈珀也出现了，他穿得轻便，武器也准备得很齐全，就像汤姆一样。'),
    (8, 508, 1321, 'Tom called:', '汤姆 喊道：'),
    (8, 509, 1322, '“Hold!', '“站住！'),
    (8, 509, 1323, 'Who comes here into Sherwood Forest without my pass?”', '谁没我的通行证就跑到谢伍德森林来了？”'),
    (8, 510, 1324, '“Guy of Guisborne wants no man’s pass.', '“吉斯伯恩的盖伊才不需要谁的通行证呢。'),
    (8, 510, 1325, 'Who art thou that—that—”', '你是谁，竟敢——竟敢——”'),
    (8, 511, 1326, '“Dares to hold such language,” said Tom, prompting—for they talked “by the book,” from memory.', '“竟敢说这样的话，”汤姆 提示道——他们可是“照着书”背台词呢。'),
    (8, 512, 1327, '“Who art thou that dares to hold such language?”', '“你是谁，竟敢说这样的话？”'),
    (8, 513, 1328, '“I, indeed!', '“就是我！'),
    (8, 513, 1329, 'I am Robin Hood, as thy caitiff carcase soon shall know.”', '我就是罗宾汉，你这坏蛋很快就会知道的！”'),
    (8, 514, 1330, '“Then art thou indeed that famous outlaw?', '“那么你真是那个有名的强盗吗？'),
    (8, 514, 1331, 'Right gladly will I dispute with thee the passes of the merry wood.', '我非常乐意在这片快乐树林和你比试一番。'),
    (8, 514, 1332, 'Have at thee!”', '放马过来！”'),
    (8, 515, 1333, 'They took their lath swords, dumped their other traps on the ground, struck a fencing attitude, foot to foot, and began a grave, careful combat, “two up and two down.”', '他们拿起木剑，把其他东西扔到地上，摆出击剑的架势，脚对脚，开始了一场认真又小心的打斗，一招一式“两上两下”。'),
    (8, 515, 1334, 'Presently Tom said:', '过了一会儿，汤姆 说道：'),
    (8, 516, 1335, '“Now, if you’ve got the hang, go it lively!”', '“好了，如果你学会了，那就打得再活泼点！”'),
    (8, 517, 1336, 'So they “went it lively,” panting and perspiring with the work.', '于是他们“活泼地打起来”，打得气喘吁吁，满头大汗。'),
    (8, 517, 1337, 'By and by Tom shouted:', '不一会儿，汤姆 喊道：'),
    (8, 518, 1338, '“Fall! fall!', '“倒下！倒下！'),
    (8, 518, 1339, 'Why don’t you fall?”', '你怎么不倒下呀？”'),
    (8, 519, 1340, '“I sha’n’t!', '“我才不！'),
    (8, 519, 1341, 'Why don’t you fall yourself?', '你自己怎么不倒下呀？'),
    (8, 519, 1342, 'You’re getting the worst of it.”', '你才是快要输了呢。”'),
    (8, 520, 1343, '“Why, that ain’t anything.', '“哎呀，那不算什么。'),
    (8, 520, 1344, 'I can’t fall; that ain’t the way it is in the book.', '我不能倒下；书上不是那样写的。'),
    (8, 520, 1345, 'The book says, ‘Then with one back-handed stroke he slew poor Guy of Guisborne.’', '书上说，‘然后他反手一击，杀死了可怜的吉斯伯恩的盖伊。’'),
    (8, 520, 1346, 'You’re to turn around and let me hit you in the back.”', '你要转过身去，让我在你背后打你一下。”'),
    (8, 521, 1347, 'There was no getting around the authorities, so Joe turned, received the whack and fell.', '没办法，乔只好转过身，挨了一下，然后倒下了。'),
    (8, 522, 1348, '“Now,” said Joe, getting up, “you got to let me kill _you_.', '“现在，”乔站起来说，“你得让我杀死你。'),
    (8, 522, 1349, 'That’s fair.”', '这很公平。”'),
    (8, 523, 1350, '“Why, I can’t do that, it ain’t in the book.”', '“哎呀，我不能那样做，书上没有那样写。”'),
    (8, 524, 1351, '“Well, it’s blamed mean—that’s all.”', '“哎呀，这太坏了——就是这样。”'),
    (8, 525, 1352, '“Well, say, Joe, you can be Friar Tuck or Much the miller’s son, and lam me with a quarter-staff; or I’ll be the Sheriff of Nottingham and you be Robin Hood a little while and kill me.”', '“嗯，乔，你可以演塔克修士或磨坊主的儿子马奇，然后用棍子打我；或者我当诺丁汉的郡长，你当罗宾汉一会儿，把我杀死。”'),
    (8, 526, 1353, 'This was satisfactory, and so these adventures were carried out.', '这让他们很满意，于是他们玩起了这些冒险游戏。'),
    (8, 526, 1354, 'Then Tom became Robin Hood again, and was allowed by the treacherous nun to bleed his strength away through his neglected wound.', '后来汤姆又当了罗宾汉。那个坏心的修女让他流血不止，伤口一直没包扎，力气都没了。'),
    (8, 526, 1355, 'And at last Joe, representing a whole tribe of weeping outlaws, dragged him sadly forth, gave his bow into his feeble hands, and Tom said, “Where this arrow falls, there bury poor Robin Hood under the greenwood tree.”', '最后，乔扮成一群哭泣的绿林好汉，他难过地把汤姆拖出来，把弓放在他没力气的手里。汤姆说：“这支箭落在哪里，就把可怜的罗宾汉埋在哪里，就在绿树林下面。”'),
    (8, 526, 1356, 'Then he shot the arrow and fell back and would have died, but he lit on a nettle and sprang up too gaily for a corpse.', '然后他射出箭，倒了下去，本来会死的。但他碰到了荨麻，又很开心地跳起来，一点也不像个死人。'),
    (8, 527, 1357, 'The boys dressed themselves, hid their accoutrements, and went off grieving that there were no outlaws any more, and wondering what modern civilization could claim to have done to compensate for their loss.', '男孩们穿好衣服，藏好玩的道具，然后伤心地走了。他们难过，因为再也没有绿林好汉了。他们想，现代社会有什么能比得上绿林好汉的乐趣呢？'),
    (8, 527, 1358, 'They said they would rather be outlaws a year in Sherwood Forest than President of the United States forever.', '他们说，他们宁愿在舍伍德森林里当一年的绿林好汉，也不想永远当美国的总统。'),
    (9, 528, 1359, 'At half-past nine, that night, Tom and Sid were sent to bed, as usual.', '那天晚上九点半，汤姆和希德像平时一样被送上床睡觉。'),
    (9, 528, 1360, 'They said their prayers, and Sid was soon asleep.', '他们做了祷告，希德很快就睡着了。'),
    (9, 528, 1361, 'Tom lay awake and waited, in restless impatience.', '汤姆醒着躺在床上，又急又不安地等着。'),
    (9, 528, 1362, 'When it seemed to him that it must be nearly daylight, he heard the clock strike ten!', '他觉得天都快亮了，却听到钟敲了十下！'),
    (9, 528, 1363, 'This was despair.', '这让他很绝望。'),
    (9, 528, 1364, 'He would have tossed and fidgeted, as his nerves demanded, but he was afraid he might wake Sid.', '他本来想翻来覆去，动来动去，因为他很紧张。但他怕吵醒希德。'),
    (9, 528, 1365, 'So he lay still, and stared up into the dark.', '所以他一动不动地躺着，看着黑黑的天花板。'),
    (9, 528, 1366, 'Everything was dismally still.', '周围安静得可怕。'),
    (9, 528, 1367, 'By and by, out of the stillness, little, scarcely perceptible noises began to emphasize themselves.', '慢慢地，在这安静里，一些很小很小的声音开始变得能听见了。'),
    (9, 528, 1368, 'The ticking of the clock began to bring itself into notice.', '钟表滴答滴答的声音，也开始能听见了。'),
    (9, 528, 1369, 'Old beams began to crack mysteriously.', '老旧的横梁开始发出奇怪的吱呀声。'),
    (9, 528, 1370, 'The stairs creaked faintly.', '楼梯也轻轻地吱呀响。'),
    (9, 528, 1371, 'Evidently spirits were abroad.', '肯定有小精灵在外面。'),
    (9, 528, 1372, 'A measured, muffled snore issued from Aunt Polly’s chamber.', '波莉姨妈的房间里传来均匀又闷闷的打鼾声。'),
    (9, 528, 1373, 'And now the tiresome chirping of a cricket that no human ingenuity could locate, began.', '现在，一只蟋蟀又开始烦人地叫了，没有人能找到它在哪里。'),
    (9, 528, 1374, 'Next the ghastly ticking of a death-watch in the wall at the bed’s head made Tom shudder—it meant that somebody’s days were numbered.', '接着，床头墙壁里传来一种“报死虫”可怕的滴答声，让汤姆吓得发抖——这意味着有人快要死了。'),
    (9, 528, 1375, 'Then the howl of a far-off dog rose on the night air, and was answered by a fainter howl from a remoter distance.', '接着，远处传来一声狗叫，更远的地方又传来一声更小的狗叫回应。'),
    (9, 528, 1376, 'Tom was in an agony.', '汤姆非常痛苦。'),
    (9, 528, 1377, 'At last he was satisfied that time had ceased and eternity begun; he began to doze, in spite of himself; the clock chimed eleven, but he did not hear it.', '最后他觉得时间停了，好像永远不会过去了。他忍不住开始打瞌睡。钟敲了十一点，但他没听到。'),
    (9, 528, 1378, 'And then there came, mingling with his half-formed dreams, a most melancholy caterwauling.', '接着，在他的半梦半醒中，传来一阵非常难过的猫叫声。'),
    (9, 528, 1379, 'The raising of a neighboring window disturbed him.', '旁边一扇窗户被打开，把他吵醒了。'),
    (9, 528, 1380, 'A cry of “Scat! you devil!” and the crash of an empty bottle against the back of his aunt’s woodshed brought him wide awake, and a single minute later he was dressed and out of the window and creeping along the roof of the “ell” on all fours.', '一声“滚开！你这坏蛋！”的喊叫，和一个空瓶子砸到他姨妈家柴房后面的声音，把他彻底吵醒了。只过了一分钟，他就穿好衣服，从窗户爬了出去，四肢着地沿着“L形”屋顶爬。'),
    (9, 528, 1381, 'He “meow’d” with caution once or twice, as he went; then jumped to the roof of the woodshed and thence to the ground.', '他边走边小心地“喵”了几声，然后跳上柴房顶，再跳到地上。'),
    (9, 528, 1382, 'Huckleberry Finn was there, with his dead cat.', '哈克贝利·费恩 也在那里，他带着他的死猫。'),
    (9, 528, 1383, 'The boys moved off and disappeared in the gloom.', '男孩们走开了，消失在黑暗中。'),
    (9, 528, 1384, 'At the end of half an hour they were wading through the tall grass of the graveyard.', '半小时后，他们走进了墓地，穿过高高的草丛。'),
    (9, 529, 1385, 'It was a graveyard of the old-fashioned Western kind.', '那是一个老式的西方墓地。'),
    (9, 529, 1386, 'It was on a hill, about a mile and a half from the village.', '它在一个小山上，离村子大约一英里半远。'),
    (9, 529, 1387, 'It had a crazy board fence around it, which leaned inward in places, and outward the rest of the time, but stood upright nowhere.', '墓地周围有一圈摇摇晃晃的木板围栏，有的地方往里歪，有的地方往外歪，没有一处是直立的。'),
    (9, 529, 1388, 'Grass and weeds grew rank over the whole cemetery.', '整个墓地都长满了杂草。'),
    (9, 529, 1389, 'All the old graves were sunken in, there was not a tombstone on the place; round-topped, worm-eaten boards staggered over the graves, leaning for support and finding none.', '所有旧坟都塌陷了，那里没有一块墓碑；只有些圆顶的、被虫蛀的木板歪斜地立在坟头，它们想找个支撑，却什么也找不到。'),
    (9, 529, 1390, '“Sacred to the memory of” So-and-So had been painted on them once, but it could no longer have been read, on the most of them, now, even if there had been light.', '以前上面写着“纪念某某某”，但现在大部分都看不清了，就算有光也看不清。'),
    (9, 530, 1391, 'A faint wind moaned through the trees, and Tom feared it might be the spirits of the dead, complaining at being disturbed.', '一阵微风在树林里呜咽，汤姆 害怕那是死者的魂魄在抱怨他们被打扰了。'),
    (9, 530, 1392, 'The boys talked little, and only under their breath, for the time and the place and the pervading solemnity and silence oppressed their spirits.', '男孩们很少说话，只是低声细语，因为时间和地点，还有周围庄严的寂静，都让他们觉得很压抑。'),
    (9, 530, 1393, 'They found the sharp new heap they were seeking, and ensconced themselves within the protection of three great elms that grew in a bunch within a few feet of the grave.', '他们找到了要找的新坟堆，然后躲进了离坟几英尺远的三棵大榆树的下面。'),
    (9, 531, 1394, 'Then they waited in silence for what seemed a long time.', '然后他们安静地等着，好像过了很久。'),
    (9, 531, 1395, 'The hooting of a distant owl was all the sound that troubled the dead stillness.', '只有远处猫头鹰的叫声，打破了这死一般的寂静。'),
    (9, 531, 1396, 'Tom’s reflections grew oppressive.', '汤姆 心里的想法让他觉得很难受。'),
    (9, 531, 1397, 'He must force some talk.', '他必须说点什么。'),
    (9, 531, 1398, 'So he said in a whisper:', '于是他小声说：'),
    (9, 532, 1399, '“Hucky, do you believe the dead people like it for us to be here?”', '“哈克，你觉得死人喜欢我们来这里吗？”'),
    (9, 533, 1400, 'Huckleberry whispered:', '哈克贝利小声说：'),
    (9, 534, 1401, '“I wisht I knowed.', '“我希望我知道。'),
    (9, 534, 1402, 'It’s awful solemn like, _ain’t_ it?”', '感觉好严肃啊，是不是？”'),
    (9, 535, 1403, '“I bet it is.”', '“我打赌是的。”'),
    (9, 536, 1404, 'There was a considerable pause, while the boys canvassed this matter inwardly.', '他们沉默了一会儿，男孩们在心里琢磨这件事。'),
    (9, 536, 1405, 'Then Tom whispered:', '接着 汤姆 小声说：'),
    (9, 537, 1406, '“Say, Hucky—do you reckon Hoss Williams hears us talking?”', '“嘿，哈克——你觉得霍斯·威廉姆斯听得到我们说话吗？”'),
    (9, 538, 1407, '“O’ course he does.', '“他当然听得到。'),
    (9, 538, 1408, 'Least his sperrit does.”', '至少他的魂魄听得到。”'),
    (9, 539, 1409, 'Tom, after a pause:', '汤姆 停顿了一下，说：'),
    (9, 540, 1410, '“I wish I’d said Mister Williams.', '“我真希望我说了威廉姆斯先生。”'),
    (9, 540, 1411, 'But I never meant any harm.', '我可没想害人。'),
    (9, 540, 1412, 'Everybody calls him Hoss.”', '大家都叫他霍斯。”'),
    (9, 541, 1413, '“A body can’t be too partic’lar how they talk ’bout these-yer dead people, Tom.”', '“说这些死掉的人，可不能太不小心了，汤姆。”'),
    (9, 542, 1414, 'This was a damper, and conversation died again.', '这事让人扫兴，大家又没话说了。'),
    (9, 543, 1415, 'Presently Tom seized his comrade’s arm and said:', '没多久，汤姆抓住他朋友的胳膊说：'),
    (9, 544, 1416, '“Sh!”', '“嘘！”'),
    (9, 545, 1417, '“What is it, Tom?”', '“怎么了，汤姆？”'),
    (9, 545, 1418, 'And the two clung together with beating hearts.', '两人心怦怦跳着，紧紧靠在一起。'),
    (9, 546, 1419, '“Sh!', '“嘘！'),
    (9, 546, 1420, 'There ’tis again!', '又来了！'),
    (9, 546, 1421, 'Didn’t you hear it?”', '你没听到吗？”'),
    (9, 547, 1422, '“I—”', '“我—”'),
    (9, 548, 1423, '“There!', '“听！'),
    (9, 548, 1424, 'Now you hear it.”', '现在你听到了吧。”'),
    (9, 549, 1425, '“Lord, Tom, they’re coming!', '“天哪，汤姆，他们来了！'),
    (9, 549, 1426, 'They’re coming, sure.', '他们真的来了。'),
    (9, 549, 1427, 'What’ll we do?”', '我们该怎么办？”'),
    (9, 550, 1428, '“I dono.', '“我不知道。'),
    (9, 550, 1429, 'Think they’ll see us?”', '你觉得他们会看到我们吗？”'),
    (9, 551, 1430, '“Oh, Tom, they can see in the dark, same as cats.', '“哦，汤姆，他们能像猫一样在黑夜里看东西。'),
    (9, 551, 1431, 'I wisht I hadn’t come.”', '我真希望我没来。”'),
    (9, 552, 1432, '“Oh, don’t be afeard.', '“哦，别害怕。'),
    (9, 552, 1433, 'I don’t believe they’ll bother us.', '我不相信他们会来烦我们。'),
    (9, 552, 1434, 'We ain’t doing any harm.', '我们没有做坏事。'),
    (9, 552, 1435, 'If we keep perfectly still, maybe they won’t notice us at all.”', '如果我们一动不动，他们也许根本不会发现我们。”'),
    (9, 553, 1436, '“I’ll try to, Tom, but, Lord, I’m all of a shiver.”', '“我会尽量做到，汤姆，可是，天哪，我全身都在抖。”'),
    (9, 554, 1437, '“Listen!”', '“听！”'),
    (9, 555, 1438, 'The boys bent their heads together and scarcely breathed.', '男孩们凑在一起，几乎屏住了呼吸。'),
    (9, 555, 1439, 'A muffled sound of voices floated up from the far end of the graveyard.', '模糊的声音从墓地的远处飘了过来。'),
    (9, 556, 1440, '“Look!', '“看！'),
    (9, 556, 1441, 'See there!” whispered Tom. “What is it?”', '“快看！” 汤姆 小声说。“那是什么？”'),
    (9, 557, 1442, '“It’s devil-fire.', '“那是鬼火。'),
    (9, 557, 1443, 'Oh, Tom, this is awful.”', '哦，汤姆，这太可怕了。”'),
    (9, 558, 1444, 'Some vague figures approached through the gloom, swinging an old-fashioned tin lantern that freckled the ground with innumerable little spangles of light.', '几个模糊的身影在黑暗中走过来，他们手里拿着一个旧灯笼，地上有好多小亮光。'),
    (9, 558, 1445, 'Presently Huckleberry whispered with a shudder:', '接着，哈克贝利哆嗦着小声说：'),
    (9, 559, 1446, '“It’s the devils sure enough.', '“真的是魔鬼。'),
    (9, 559, 1447, 'Three of ’em!', '有三个！'),
    (9, 559, 1448, 'Lordy, Tom, we’re goners!', '天哪，汤姆，我们死定了！'),
    (9, 559, 1449, 'Can you pray?”', '你会祈祷吗？”'),
    (9, 560, 1450, '“I’ll try, but don’t you be afeard.', '“我试试看，但你别害怕。'),
    (9, 560, 1451, 'They ain’t going to hurt us.', '他们不会伤害我们的。'),
    (9, 560, 1452, '‘Now I lay me down to sleep, I—’”', '“我现在要睡觉了，我——”'),
    (9, 561, 1453, '“Sh!”', '“嘘！”'),
    (9, 562, 1454, '“What is it, Huck?”', '“那是什么，哈克？”'),
    (9, 563, 1455, '“They’re _humans_!', '“他们是人！'),
    (9, 563, 1456, 'One of ’em is, anyway.', '至少有一个是。'),
    (9, 563, 1457, 'One of ’em’s old Muff Potter’s voice.”', '其中一个声音是老莫夫·波特的。”'),
    (9, 564, 1458, '“No—’tain’t so, is it?”', '“不——不是吧？”'),
    (9, 565, 1459, '“I bet I know it.', '“我敢打赌我知道。'),
    (9, 565, 1460, 'Don’t you stir nor budge.', '你别动，也别挪。'),
    (9, 565, 1461, 'He ain’t sharp enough to notice us.', '他不够机灵，不会发现我们。'),
    (9, 565, 1462, 'Drunk, the same as usual, likely—blamed old rip!”', '他可能又喝醉了，和以前一样——那个该死的老家伙！”'),
    (9, 566, 1463, '“All right, I’ll keep still.', '“好的，我安静待着。'),
    (9, 566, 1464, 'Now they’re stuck.', '现在他们不动了。'),
    (9, 566, 1465, 'Can’t find it.', '找不到。'),
    (9, 566, 1466, 'Here they come again.', '他们又来了。'),
    (9, 566, 1467, 'Now they’re hot.', '现在他们热了。'),
    (9, 566, 1468, 'Cold again.', '又冷了。'),
    (9, 566, 1469, 'Hot again.', '又热了。'),
    (9, 566, 1470, 'Red hot!', '烫手了！'),
    (9, 566, 1471, 'They’re p’inted right, this time.', '这次他们指对地方了。'),
    (9, 566, 1472, 'Say, Huck, I know another o’ them voices; it’s Injun Joe.”', '喂，哈克，我认出另一个声音了；是印第安·乔。”'),
    (9, 567, 1473, '“That’s so—that murderin’ half-breed!', '“是真的——那个杀人的混血儿！'),
    (9, 567, 1474, 'I’d druther they was devils a dern sight.', '我宁愿他们是魔鬼呢。'),
    (9, 567, 1475, 'What kin they be up to?”', '他们想干什么呢？”'),
    (9, 568, 1476, 'The whisper died wholly out, now, for the three men had reached the grave and stood within a few feet of the boys’ hiding-place.', '小声说话的声音完全消失了，因为那三个人已经走到坟墓边，离孩子们藏身的地方只有几步远了。'),
    (9, 569, 1477, '“Here it is,” said the third voice; and the owner of it held the lantern up and revealed the face of young Doctor Robinson.', '“在这儿呢，”第三个声音说；那个人把灯笼举起来，露出了年轻的罗宾逊医生。'),
    (9, 570, 1478, 'Potter and Injun Joe were carrying a handbarrow with a rope and a couple of shovels on it.', '波特和印第安·乔抬着一个手推车，上面有绳子和两把铁锹。'),
    (9, 570, 1479, 'They cast down their load and began to open the grave.', '他们放下东西，开始挖坟墓。'),
    (9, 570, 1480, 'The doctor put the lantern at the head of the grave and came and sat down with his back against one of the elm trees.', '医生把灯笼放在坟墓前面，然后走到一棵榆树旁，背靠着树坐了下来。'),
    (9, 570, 1481, 'He was so close the boys could have touched him.', '他离得那么近，孩子们都快能碰到他了。'),
    (9, 571, 1482, '“Hurry, men!” he said, in a low voice; “the moon might come out at any moment.”', '“快点，伙计们！”他小声说，“月亮随时都可能出来。”'),
    (9, 572, 1483, 'They growled a response and went on digging.', '他们哼了一声作为回应，继续挖土。'),
    (9, 572, 1484, 'For some time there was no noise but the grating sound of the spades discharging their freight of mould and gravel.', '有一阵子，除了铁锹刮着土石的声音，没有别的响动。'),
    (9, 572, 1485, 'It was very monotonous.', '真是太单调了。'),
    (9, 572, 1486, 'Finally a spade struck upon the coffin with a dull woody accent, and within another minute or two the men had hoisted it out on the ground.', '终于，一把铁锹砰地一声碰到了棺材，又过了一两分钟，人们就把棺材抬了出来，放在地上。'),
    (9, 572, 1487, 'They pried off the lid with their shovels, got out the body and dumped it rudely on the ground.', '他们用铁锹撬开棺材盖，把尸体抬出来，粗鲁地扔在地上。'),
    (9, 572, 1488, 'The moon drifted from behind the clouds and exposed the pallid face.', '月亮从云后面慢慢出来，照亮了那张苍白的脸。'),
    (9, 572, 1489, 'The barrow was got ready and the corpse placed on it, covered with a blanket, and bound to its place with the rope.', '手推车准备好了，尸体被放在上面，盖上毯子，然后用绳子绑好。'),
    (9, 572, 1490, 'Potter took out a large spring-knife and cut off the dangling end of the rope and then said:', '波特拿出一把大弹簧刀，割断了垂下来的绳子末端，然后说：'),
    (9, 573, 1491, '“Now the cussed thing’s ready, Sawbones, and you’ll just out with another five, or here she stays.”', '“现在这鬼东西准备好了，医生，你再拿出五块钱来，不然它就留在这儿了。”'),
    (9, 574, 1492, '“That’s the talk!” said Injun Joe.', '“说得好！”印第安·乔说。'),
    (9, 575, 1493, '“Look here, what does this mean?” said the doctor. “You required your pay in advance, and I’ve paid you.”', '“听着，这是什么意思？”医生说，“你要求提前付款，我已经付给你了。”'),
    (9, 576, 1494, '“Yes, and you done more than that,” said Injun Joe, approaching the doctor, who was now standing.', '“是的，而且你做得更多，”印第安·乔说，他走近了医生，医生现在正站着。'),
    (9, 576, 1495, '“Five years ago you drove me away from your father’s kitchen one night, when I come to ask for something to eat, and you said I warn’t there for any good; and when I swore I’d get even with you if it took a hundred years, your father had me jailed for a vagrant.', '“五年前的一个晚上，我去找你父亲要吃的，你把我赶出了厨房，还说我没安好心；等我发誓说就算等一百年也要报复你的时候，你父亲就把我当作流浪汉抓去坐牢了。'),
    (9, 576, 1496, 'Did you think I’d forget?', '你以为我会忘记吗？'),
    (9, 576, 1497, 'The Injun blood ain’t in me for nothing.', '我可不是白白有印第安人的血统。'),
    (9, 576, 1498, 'And now I’ve _got_ you, and you got to _settle_, you know!”', '“现在我抓住你了，你得给我个交代，你懂的！”'),
    (9, 577, 1499, 'He was threatening the doctor, with his fist in his face, by this time.', '这时，他把拳头伸到医生面前，威胁着他。'),
    (9, 577, 1500, 'The doctor struck out suddenly and stretched the ruffian on the ground.', '医生突然出手，一拳就把那个恶棍打倒在地。'),
    (9, 577, 1501, 'Potter dropped his knife, and exclaimed:', '波特的刀掉了，他大喊：'),
    (9, 578, 1502, '“Here, now, don’t you hit my pard!” and the next moment he had grappled with the doctor and the two were struggling with might and main, trampling the grass and tearing the ground with their heels.', '“喂，别打我的伙伴！” 接着，他一把抓住医生，两人就拼命打起来。他们踩坏了草地，脚后跟把泥土都踢了起来。'),
    (9, 578, 1503, 'Injun Joe sprang to his feet, his eyes flaming with passion, snatched up Potter’s knife, and went creeping, catlike and stooping, round and round about the combatants, seeking an opportunity.', '印第安·乔跳起来，眼睛里冒着火。他拿起波特的刀，像猫一样弯着腰，悄悄地绕着打架的两个人转来转去，想找个机会。'),
    (9, 578, 1504, 'All at once the doctor flung himself free, seized the heavy headboard of Williams’ grave and felled Potter to the earth with it—and in the same instant the half-breed saw his chance and drove the knife to the hilt in the young man’s breast.', '突然，医生挣脱了，拿起威廉姆斯墓碑那块重重的石板，把波特打倒在地。就在那一刻，那个混血儿抓住了机会，把刀深深地刺进了那个年轻人的胸口。'),
    (9, 578, 1505, 'He reeled and fell partly upon Potter, flooding him with his blood, and in the same moment the clouds blotted out the dreadful spectacle and the two frightened boys went speeding away in the dark.', '他摇摇晃晃地倒下，一部分身子压在波特身上，血流了他一身。就在这时，乌云遮住了可怕的景象，两个吓坏了的男孩赶紧跑进了黑暗里。'),
    (9, 579, 1506, 'Presently, when the moon emerged again, Injun Joe was standing over the two forms, contemplating them.', '很快，月亮又出来了。印第安·乔站在那两具尸体旁边，看着它们。'),
    (9, 579, 1507, 'The doctor murmured inarticulately, gave a long gasp or two and was still.', '医生哼了几声，喘了几口气，就没动静了。'),
    (9, 579, 1508, 'The half-breed muttered:', '那个混血儿小声说：'),
    (9, 580, 1509, '“_That_ score is settled—damn you.”', '“这笔账算清了——去你的。”'),
    (9, 581, 1510, 'Then he robbed the body.', '然后他搜刮了那具尸体。'),
    (9, 581, 1511, 'After which he put the fatal knife in Potter’s open right hand, and sat down on the dismantled coffin.', '接着，他把那把要命的刀放在波特张开的右手里，然后坐在那个散架的棺材上。'),
    (9, 581, 1512, 'Three—four—five minutes passed, and then Potter began to stir and moan.', '三分钟、四分钟、五分钟过去了，然后波特开始动了动，还哼了几声。'),
    (9, 581, 1513, 'His hand closed upon the knife; he raised it, glanced at it, and let it fall, with a shudder.', '他的手抓住了刀；他把刀举起来，看了看，然后发抖着把刀扔了。'),
    (9, 581, 1514, 'Then he sat up, pushing the body from him, and gazed at it, and then around him, confusedly.', '然后他坐起来，把尸体推开，看着它，接着又迷迷糊糊地看了看周围。'),
    (9, 581, 1515, 'His eyes met Joe’s.', '他的眼睛碰到了乔的目光。'),
    (9, 582, 1516, '“Lord, how is this, Joe?” he said.', '“天哪，乔，这是怎么回事？”他问。'),
    (9, 583, 1517, '“It’s a dirty business,” said Joe, without moving.', '“这事儿太糟了，”乔没动，说。'),
    (9, 583, 1518, '“What did you do it for?”', '“你为什么要这么做？”'),
    (9, 584, 1519, '“I!', '“我！'),
    (9, 584, 1520, 'I never done it!”', '我从来没做过！”'),
    (9, 585, 1521, '“Look here!', '“听着！'),
    (9, 585, 1522, 'That kind of talk won’t wash.”', '这种话可没人信。”'),
    (9, 586, 1523, 'Potter trembled and grew white.', '波特全身发抖，脸也白了。'),
    (9, 587, 1524, '“I thought I’d got sober.', '“我以为我清醒了。'),
    (9, 587, 1525, 'I’d no business to drink to-night.', '今晚我不该喝酒的。'),
    (9, 587, 1526, 'But it’s in my head yet—worse’n when we started here.', '但我的头还是晕晕的——比我们刚来的时候还糟。'),
    (9, 587, 1527, 'I’m all in a muddle; can’t recollect anything of it, hardly.', '我脑子里乱糟糟的；几乎什么也记不起来了。'),
    (9, 587, 1528, 'Tell me, Joe—_honest_, now, old feller—did I do it?', '乔，告诉我——说实话，老朋友——是我做的吗？'),
    (9, 587, 1529, 'Joe, I never meant to—’pon my soul and honor, I never meant to, Joe.', '乔，我不是故意的——我发誓，我真的不是故意的，乔。'),
    (9, 587, 1530, 'Tell me how it was, Joe.', '乔，告诉我到底是怎么回事。'),
    (9, 587, 1531, 'Oh, it’s awful—and him so young and promising.”', '哦，太惨了，他还那么年轻，多好的一个人啊。'),
    (9, 588, 1532, '“Why, you two was scuffling, and he fetched you one with the headboard and you fell flat; and then up you come, all reeling and staggering like, and snatched the knife and jammed it into him, just as he fetched you another awful clip—and here you’ve laid, as dead as a wedge til now.”', '哎呀，你们俩打架了。他用床头板打了你一下，你倒了。你又晃晃悠悠爬起来，拿起刀子捅了他。他正好又狠狠打了你一下。你就就像死了一样躺在这儿，到现在才醒。'),
    (9, 589, 1533, '“Oh, I didn’t know what I was a-doing.', '哦，我不知道我在做什么。'),
    (9, 589, 1534, 'I wish I may die this minute if I did.', '如果我知道，就让我现在死掉吧。'),
    (9, 589, 1535, 'It was all on account of the whiskey and the excitement, I reckon.', '我猜，都是因为喝了酒，太激动了。'),
    (9, 589, 1536, 'I never used a weepon in my life before, Joe.', '乔，我以前从来没用过武器。'),
    (9, 589, 1537, 'I’ve fought, but never with weepons.', '我打过架，但从没用过武器。'),
    (9, 589, 1538, 'They’ll all say that.', '他们都会那么说的。'),
    (9, 589, 1539, 'Joe, don’t tell!', '乔，别告诉别人！'),
    (9, 589, 1540, 'Say you won’t tell, Joe—that’s a good feller.', '乔，你说你不会说的，你是个好人。'),
    (9, 589, 1541, 'I always liked you, Joe, and stood up for you, too.', '乔，我一直都喜欢你，也一直帮着你。'),
    (9, 589, 1542, 'Don’t you remember?', '你不记得了吗？'),
    (9, 589, 1543, 'You _won’t_ tell, _will_ you, Joe?”', '乔，你不会说的，是吗？'),
    (9, 589, 1544, 'And the poor creature dropped on his knees before the stolid murderer, and clasped his appealing hands.', '这个可怜的人跪在那个冷酷的杀人犯面前，双手合十地恳求着。'),
    (9, 590, 1545, '“No, you’ve always been fair and square with me, Muff Potter, and I won’t go back on you.', '不，你一直对我很好，莫夫·波特，我不会出卖你的。'),
    (9, 590, 1546, 'There, now, that’s as fair as a man can say.”', '好了，我能说的也就这些了。'),
    (9, 591, 1547, '“Oh, Joe, you’re an angel.', '哦，乔，你真是个天使。'),
    (9, 591, 1548, 'I’ll bless you for this the longest day I live.”', '我这辈子都会感谢你的。'),
    (9, 591, 1549, 'And Potter began to cry.', '然后波特开始哭了。'),
    (9, 592, 1550, '“Come, now, that’s enough of that.', '好了，够了。'),
    (9, 592, 1551, 'This ain’t any time for blubbering.', '现在不是哭的时候。'),
    (9, 592, 1552, 'You be off yonder way and I’ll go this.', '你走那边，我走这边。'),
    (9, 592, 1553, 'Move, now, and don’t leave any tracks behind you.”', '快走吧，别留下脚印。'),
    (9, 593, 1554, 'Potter started on a trot that quickly increased to a run.', '波特开始小跑，接着就跑了起来。'),
    (9, 593, 1555, 'The half-breed stood looking after him.', '那个混血儿站在原地看着他。'),
    (9, 593, 1556, 'He muttered:', '他嘟囔着说：'),
    (9, 594, 1557, '“If he’s as much stunned with the lick and fuddled with the rum as he had the look of being, he won’t think of the knife till he’s gone so far he’ll be afraid to come back after it to such a place by himself—chicken-heart!”', '要是他真像看着那样，被揍晕了，又喝醉了酒，就不会想到那把刀。等他跑远了，就不敢一个人回来拿刀了——真是个胆小鬼！'),
    (9, 595, 1558, 'Two or three minutes later the murdered man, the blanketed corpse, the lidless coffin, and the open grave were under no inspection but the moon’s.', '两三分钟后，那个死去的人，盖着毯子的尸体，没盖子的棺材，还有那个敞开的坟墓，就只有月亮看着了。'),
    (9, 595, 1559, 'The stillness was complete again, too.', '一切又变得完全安静了。'),
    (10, 596, 1560, 'The two boys flew on and on, toward the village, speechless with horror.', '两个男孩吓坏了，一句话也说不出来，一直朝着村子跑啊跑。'),
    (10, 596, 1561, 'They glanced backward over their shoulders from time to time, apprehensively, as if they feared they might be followed.', '他们时不时回头看，心里有点怕，好像有人跟着他们。'),
    (10, 596, 1562, 'Every stump that started up in their path seemed a man and an enemy, and made them catch their breath; and as they sped by some outlying cottages that lay near the village, the barking of the aroused watch-dogs seemed to give wings to their feet.', '路上每个树桩都像一个人、一个坏蛋，让他们吓得喘不过气。当他们跑过村子旁的小房子时，狗狗的叫声好像给他们插上了翅膀，跑得更快了。'),
    (10, 597, 1563, '“If we can only get to the old tannery before we break down!” whispered Tom, in short catches between breaths. “I can’t stand it much longer.”', '“要是我们能在撑不住之前，跑到那个旧皮革厂就好了！” 汤姆喘着气小声说，“我真的快撑不住了。”'),
    (10, 598, 1564, 'Huckleberry’s hard pantings were his only reply, and the boys fixed their eyes on the goal of their hopes and bent to their work to win it.', '哈克贝利只是拼命喘气，没有说话。孩子们盯着他们想去的地方，努力跑向那里。'),
    (10, 598, 1565, 'They gained steadily on it, and at last, breast to breast, they burst through the open door and fell grateful and exhausted in the sheltering shadows beyond.', '他们一点点靠近，最后，一起冲进敞开的门，又累又庆幸地倒在屋里的阴影里。'),
    (10, 598, 1566, 'By and by their pulses slowed down, and Tom whispered:', '慢慢地，他们的心跳慢了下来，汤姆小声说：'),
    (10, 599, 1567, '“Huckleberry, what do you reckon’ll come of this?”', '“哈克贝利，你觉得这件事会怎么样啊？”'),
    (10, 600, 1568, '“If Doctor Robinson dies, I reckon hanging’ll come of it.”', '“要是罗宾逊医生死了，我猜他们会把我们吊起来。”'),
    (10, 601, 1569, '“Do you though?”', '“真的吗？”'),
    (10, 602, 1570, '“Why, I _know_ it, Tom.”', '“当然是真的，汤姆。”'),
    (10, 603, 1571, 'Tom thought a while, then he said:', '汤姆想了一会儿，然后说：'),
    (10, 604, 1572, '“Who’ll tell?', '“谁会去说呢？'),
    (10, 604, 1573, 'We?”', '我们吗？”'),
    (10, 605, 1574, '“What are you talking about?', '“你在说什么呀？'),
    (10, 605, 1575, 'S’pose something happened and Injun Joe _didn’t_ hang?', '要是万一 印第安·乔 没被吊死呢？'),
    (10, 605, 1576, 'Why, he’d kill us some time or other, just as dead sure as we’re a laying here.”', '那他迟早会杀了我们的，就像我们现在躺在这里一样确定。”'),
    (10, 606, 1577, '“That’s just what I was thinking to myself, Huck.”', '“哈克，我刚才也是这么想的。”'),
    (10, 607, 1578, '“If anybody tells, let Muff Potter do it, if he’s fool enough.', '“要是有人要说，就让 莫夫·波特 去说吧，如果他那么傻的话。'),
    (10, 607, 1579, 'He’s generally drunk enough.”', '他一般都喝得醉醺醺的。”'),
    (10, 608, 1580, 'Tom said nothing—went on thinking.', '汤姆没说话，继续想着。'),
    (10, 608, 1581, 'Presently he whispered:', '过了一会儿，他小声说：'),
    (10, 609, 1582, '“Huck, Muff Potter don’t know it.', '“哈克，莫夫·波特不知道这件事。'),
    (10, 609, 1583, 'How can he tell?”', '他怎么会说出去呢？”'),
    (10, 610, 1584, '“What’s the reason he don’t know it?”', '“他怎么会不知道呢？”'),
    (10, 611, 1585, '“Because he’d just got that whack when Injun Joe done it.', '“因为 印第安·乔 做这件事的时候，他刚被打了那一下。'),
    (10, 611, 1586, 'D’you reckon he could see anything?', '你觉得他能看到什么吗？'),
    (10, 611, 1587, 'D’you reckon he knowed anything?”', '你觉得他知道什么吗？”'),
    (10, 612, 1588, '“By hokey, that’s so, Tom!”', '“哎呀，是这样啊，汤姆！”'),
    (10, 613, 1589, '“And besides, look-a-here—maybe that whack done for _him_!”', '“而且你看——说不定那一打，把他给打死了呢！”'),
    (10, 614, 1590, '“No, ’taint likely, Tom.', '“不，不可能的，汤姆。'),
    (10, 614, 1591, 'He had liquor in him; I could see that; and besides, he always has.', '他喝了酒，我看得出来。他一直都这样。'),
    (10, 614, 1592, 'Well, when pap’s full, you might take and belt him over the head with a church and you couldn’t phase him.', '爸爸喝醉了，你用教堂砸他头，他也不会有感觉。'),
    (10, 614, 1593, 'He says so, his own self.', '他自己就是这么说的。'),
    (10, 614, 1594, 'So it’s the same with Muff Potter, of course.', '那么对 莫夫·波特 来说，当然也是一样。'),
    (10, 614, 1595, 'But if a man was dead sober, I reckon maybe that whack might fetch him; I dono.”', '但如果一个人没喝酒，我猜那一打可能让他清醒过来。我不知道。”'),
    (10, 615, 1596, 'After another reflective silence, Tom said:', '又安静了一会儿，汤姆 说：'),
    (10, 616, 1597, '“Hucky, you sure you can keep mum?”', '“哈克，你确定能保守秘密吗？”'),
    (10, 617, 1598, '“Tom, we _got_ to keep mum.', '“汤姆，我们_一定_要保守秘密。'),
    (10, 617, 1599, 'You know that.', '你知道的。'),
    (10, 617, 1600, 'That Injun devil wouldn’t make any more of drownding us than a couple of cats, if we was to squeak ’bout this and they didn’t hang him.', '如果我们把这事说出去，那个坏蛋没被抓，他就会像淹死两只猫一样，把我们淹死。'),
    (10, 617, 1601, 'Now, look-a-here, Tom, less take and swear to one another—that’s what we got to do—swear to keep mum.”', '喂，汤姆，我们互相发个誓吧。我们得这么做，发誓保守秘密。”'),
    (10, 618, 1602, '“I’m agreed.', '“我同意。'),
    (10, 618, 1603, 'It’s the best thing.', '这是最好的办法。'),
    (10, 618, 1604, 'Would you just hold hands and swear that we—”', '你能牵着手发誓说我们——”'),
    (10, 619, 1605, '“Oh no, that wouldn’t do for this.', '“哦不，这事不能这样。'),
    (10, 619, 1606, 'That’s good enough for little rubbishy common things—specially with gals, cuz _they_ go back on you anyway, and blab if they get in a huff—but there orter be writing ’bout a big thing like this.', '那只对小事有用，特别是对女孩子。她们总是说话不算数，一生气就说出去。但是像这样的大事，就得写下来。'),
    (10, 619, 1607, 'And blood.”', '还要有血。”'),
    (10, 620, 1608, 'Tom’s whole being applauded this idea.', '汤姆 特别喜欢这个主意。'),
    (10, 620, 1609, 'It was deep, and dark, and awful; the hour, the circumstances, the surroundings, were in keeping with it.', '这主意又深奥又吓人。当时的时间、事情、周围的一切都很符合。'),
    (10, 620, 1610, 'He picked up a clean pine shingle that lay in the moon-light, took a little fragment of “red keel” out of his pocket, got the moon on his work, and painfully scrawled these lines, emphasizing each slow down-stroke by clamping his tongue between his teeth, and letting up the pressure on the up-strokes.', '他捡起一块干净的松木板，它在月光下。他从口袋里拿出一小块“红石头笔”。借着月光，他很吃力地写下这些字。每写一个慢笔画，他就把舌头夹在牙齿间。向上提笔时，他就放松。'),
    (10, 621, 1611, '“Huck Finn and Tom Sawyer swears they will keep mum about This and They wish They may Drop down dead in Their Tracks if They ever Tell and Rot.”', '“哈克 芬恩和 汤姆·索亚 发誓会保守这个秘密。如果他们说出去，他们希望自己立刻死掉，身体腐烂。”'),
    (10, 622, 1612, 'Huckleberry was filled with admiration of Tom’s facility in writing, and the sublimity of his language.', '哈克伯利很佩服 汤姆 写字写得好，话也说得棒。'),
    (10, 622, 1613, 'He at once took a pin from his lapel and was going to prick his flesh, but Tom said:', '他马上从衣服上拿下一根别针，想扎自己的肉。但 汤姆 说：'),
    (10, 623, 1614, '“Hold on!', '“等等！'),
    (10, 623, 1615, 'Don’t do that.', '别这样做。'),
    (10, 623, 1616, 'A pin’s brass.', '别针是黄铜做的。'),
    (10, 623, 1617, 'It might have verdigrease on it.”', '它上面可能有铜绿。”'),
    (10, 624, 1618, '“What’s verdigrease?”', '“铜绿是什么？”'),
    (10, 625, 1619, '“It’s p’ison.', '“那是毒药。'),
    (10, 625, 1620, 'That’s what it is.', '就是那个东西。'),
    (10, 625, 1621, 'You just swaller some of it once—you’ll see.”', '你尝一点点，就知道了。'),
    (10, 626, 1622, 'So Tom unwound the thread from one of his needles, and each boy pricked the ball of his thumb and squeezed out a drop of blood.', '于是汤姆把针上的线解开，两个男孩都用针扎了一下大拇指头，挤出了一滴血。'),
    (10, 626, 1623, 'In time, after many squeezes, Tom managed to sign his initials, using the ball of his little finger for a pen.', '过了好一会儿，挤了好几次后，汤姆终于用他的小指头当笔，写下了自己的名字缩写。'),
    (10, 626, 1624, 'Then he showed Huckleberry how to make an H and an F, and the oath was complete.', '然后他教哈克贝利写H和F，这个誓言就完成了。'),
    (10, 626, 1625, 'They buried the shingle close to the wall, with some dismal ceremonies and incantations, and the fetters that bound their tongues were considered to be locked and the key thrown away.', '他们把木板埋在墙边，举行了一些很神秘的仪式，念了一些咒语。他们觉得自己的秘密被锁住了，钥匙也被扔掉了，再也不能说出去了。'),
    (10, 627, 1626, 'A figure crept stealthily through a break in the other end of the ruined building, now, but they did not notice it.', '这时，一个人影悄悄地从破房子另一边的缺口爬了进来，但他们没有发现。'),
    (10, 628, 1627, '“Tom,” whispered Huckleberry, “does this keep us from _ever_ telling—_always_?”', '“汤姆，”哈克贝利小声说，“这能让我们永远不说出去吗？”'),
    (10, 629, 1628, '“Of course it does.', '“当然可以。”'),
    (10, 629, 1629, 'It don’t make any difference _what_ happens, we got to keep mum.', '“不管发生什么事，我们都不能说出去。”'),
    (10, 629, 1630, 'We’d drop down dead—don’t _you_ know that?”', '“我们会突然死掉的，难道你不知道吗？”'),
    (10, 630, 1631, '“Yes, I reckon that’s so.”', '“嗯，我想是这样。”'),
    (10, 631, 1632, 'They continued to whisper for some little time.', '他们又小声说了好一会儿话。'),
    (10, 631, 1633, 'Presently a dog set up a long, lugubrious howl just outside—within ten feet of them.', '突然，外面传来一阵长长的、悲伤的狗叫声，就在他们外面，离他们不到三米远的地方。'),
    (10, 631, 1634, 'The boys clasped each other suddenly, in an agony of fright.', '两个男孩吓得要命，一下子紧紧抱在一起。'),
    (10, 632, 1635, '“Which of us does he mean?” gasped Huckleberry.', '“它是在说我们中的谁？”哈克贝利喘着气问。'),
    (10, 633, 1636, '“I dono—peep through the crack.', '“我不知道——从缝隙里往外看。'),
    (10, 633, 1637, 'Quick!”', '快点！”'),
    (10, 634, 1638, '“No, _you_, Tom!”', '“不，你去看，汤姆！”'),
    (10, 635, 1639, '“I can’t—I can’t _do_ it, Huck!”', '“我不能——我做不到，哈克！”'),
    (10, 636, 1640, '“Please, Tom.', '“求你了，汤姆。'),
    (10, 636, 1641, 'There ’tis again!”', '又来了！”'),
    (10, 637, 1642, '“Oh, lordy, I’m thankful!” whispered Tom.', '“哦，天啊，太好了！”汤姆小声说。'),
    (10, 637, 1643, '“I know his voice.', '“我认识这个声音。'),
    (10, 637, 1644, 'It’s Bull Harbison.”', '是布尔·哈比森。”'),
    (10, 637, 1645, '*', '*'),
    (10, 638, 1646, '[* If Mr. Harbison owned a slave named Bull, Tom would have spoken of him as “Harbison’s Bull,” but a son or a dog of that name was “Bull Harbison.”', '[* 如果哈比森先生有个叫布尔的奴隶，汤姆会说他是“哈比森家的布尔”，但如果是他叫布尔的儿子或狗，就会说“布尔·哈比森”。'),
    (10, 638, 1647, ']', ']'),
    (10, 639, 1648, '“Oh, that’s good—I tell you, Tom, I was most scared to death; I’d a bet anything it was a _stray_ dog.”', '“哦，太好了——我跟你说，汤姆，我刚才快吓死了；我敢打赌那是一条流浪狗。”'),
    (10, 640, 1649, 'The dog howled again.', '狗又叫了一声。'),
    (10, 640, 1650, 'The boys’ hearts sank once more.', '两个男孩的心又沉了下去。'),
    (10, 641, 1651, '“Oh, my! that ain’t no Bull Harbison!” whispered Huckleberry. “_Do_, Tom!”', '“哎呀！那不是布尔·哈比森！”哈克小声说。“快，汤姆！”'),
    (10, 642, 1652, 'Tom, quaking with fear, yielded, and put his eye to the crack.', '汤姆吓得发抖，听话地把眼睛凑到缝隙上。'),
    (10, 642, 1653, 'His whisper was hardly audible when he said:', '他的声音很小，几乎听不见，他说：'),
    (10, 643, 1654, '“Oh, Huck, _it’s a stray dog_!”', '“哦，哈克，那是一只流浪狗！”'),
    (10, 644, 1655, '“Quick, Tom, quick!', '“快，汤姆，快！'),
    (10, 644, 1656, 'Who does he mean?”', '他指的是谁？”'),
    (10, 645, 1657, '“Huck, he must mean us both—we’re right together.”', '“哈克，他肯定是指我们俩——我们就在一起。”'),
    (10, 646, 1658, '“Oh, Tom, I reckon we’re goners.', '“哦，汤姆，我想我们完了。'),
    (10, 646, 1659, 'I reckon there ain’t no mistake ’bout where _I’ll_ go to.', '我想我肯定知道我将要去哪里了。'),
    (10, 646, 1660, 'I been so wicked.”', '我太坏了。”'),
    (10, 647, 1661, '“Dad fetch it!', '“真是的！'),
    (10, 647, 1662, 'This comes of playing hookey and doing everything a feller’s told _not_ to do.', '这都是因为逃学，还做了所有不让做的事。'),
    (10, 647, 1663, 'I might a been good, like Sid, if I’d a tried—but no, I wouldn’t, of course.', '我本来可以像希德一样乖的，如果我努力过——可是不，我当然不会那样做。'),
    (10, 647, 1664, 'But if ever I get off this time, I lay I’ll just _waller_ in Sunday-schools!”', '但如果这次我能逃过一劫，我发誓我一定会好好去上主日学的！”'),
    (10, 647, 1665, 'And Tom began to snuffle a little.', '汤姆开始轻轻地抽泣起来。'),
    (10, 648, 1666, '“_You_ bad!” and Huckleberry began to snuffle too.', '“你坏！”哈克也开始抽泣了。'),
    (10, 648, 1667, '“Consound it, Tom Sawyer, you’re just old pie, ’long-side o’ what I am.', '“真是的，汤姆·索亚，你根本就不坏，比我好多了。'),
    (10, 648, 1668, 'Oh, _lordy_, lordy, lordy, I wisht I only had half your chance.”', '哦，天哪，天哪，天哪，我真希望我能像你一样好。”'),
    (10, 649, 1669, 'Tom choked off and whispered:', '汤姆停住了抽泣，小声说：'),
    (10, 650, 1670, '“Look, Hucky, look!', '“看，哈克，看！'),
    (10, 650, 1671, 'He’s got his _back_ to us!”', '他背对着我们！”'),
    (10, 651, 1672, 'Hucky looked, with joy in his heart.', '哈克看了看，心里很高兴。'),
    (10, 652, 1673, '“Well, he has, by jingoes!', '“真的，他确实是这样！'),
    (10, 652, 1674, 'Did he before?”', '他之前也是吗？”'),
    (10, 653, 1675, '“Yes, he did.', '“是的，他之前是。'),
    (10, 653, 1676, 'But I, like a fool, never thought.', '可我真傻，从来没想过。'),
    (10, 653, 1677, 'Oh, this is bully, you know.', '哦，这太棒了，你知道吗。'),
    (10, 653, 1678, '_Now_ who can he mean?”', '那么现在，他能指的是谁呢？”'),
    (10, 654, 1679, 'The howling stopped.', '嚎叫声停了。'),
    (10, 654, 1680, 'Tom pricked up his ears.', '汤姆竖起了耳朵。'),
    (10, 655, 1681, '“Sh!', '“嘘！'),
    (10, 655, 1682, 'What’s that?” he whispered.', '那是什么声音？”他小声问。'),
    (10, 656, 1683, '“Sounds like—like hogs grunting.', '“听起来像——像猪在哼哼。'),
    (10, 656, 1684, 'No—it’s somebody snoring, Tom.”', '不对——是有人在打呼噜，汤姆。”'),
    (10, 657, 1685, '“That _is_ it!', '“就是这个声音！'),
    (10, 657, 1686, 'Where ’bouts is it, Huck?”', '声音在哪儿，哈克？”'),
    (10, 658, 1687, '“I bleeve it’s down at ’tother end.', '“我觉得声音在那边。'),
    (10, 658, 1688, 'Sounds so, anyway.', '反正听起来是那样。'),
    (10, 658, 1689, 'Pap used to sleep there, sometimes, ’long with the hogs, but laws bless you, he just lifts things when _he_ snores.', '爸爸以前有时和猪一起睡在那儿，但他打呼噜的时候，声音可大了，像把东西都震起来了一样。'),
    (10, 658, 1690, 'Besides, I reckon he ain’t ever coming back to this town any more.”', '再说，我想他再也不会回这个镇子了。”'),
    (10, 659, 1691, 'The spirit of adventure rose in the boys’ souls once more.', '两个小男孩心里又充满了冒险精神。'),
    (10, 660, 1692, '“Hucky, do you das’t to go if I lead?”', '“哈克，我带头的话，你敢不敢去？”'),
    (10, 661, 1693, '“I don’t like to, much.', '“我不太想去。'),
    (10, 661, 1694, 'Tom, s’pose it’s Injun Joe!”', '汤姆，万一那是印第安·乔呢！”'),
    (10, 662, 1695, 'Tom quailed.', '汤姆害怕了。'),
    (10, 662, 1696, 'But presently the temptation rose up strong again and the boys agreed to try, with the understanding that they would take to their heels if the snoring stopped.', '但很快，好奇心又变得很强，两个男孩决定去看看，他们说好了，要是打呼噜的声音停了，他们就赶紧跑。'),
    (10, 662, 1697, 'So they went tiptoeing stealthily down, the one behind the other.', '于是他们一个跟着一个，踮着脚悄悄地走下去。'),
    (10, 662, 1698, 'When they had got to within five steps of the snorer, Tom stepped on a stick, and it broke with a sharp snap.', '当他们离打呼噜的人只有五步远的时候，汤姆踩到了一根小树枝，树枝“啪”的一声断了。'),
    (10, 662, 1699, 'The man moaned, writhed a little, and his face came into the moonlight.', '那个人哼了一声，扭动了一下，他的脸露在了月光下。'),
    (10, 662, 1700, 'It was Muff Potter.', '原来是莫夫·波特。'),
    (10, 662, 1701, 'The boys’ hearts had stood still, and their hopes too, when the man moved, but their fears passed away now.', '那个人动的时候，两个男孩的心都快要停止跳动了，他们的希望也快没了，但现在他们的害怕都消失了。'),
    (10, 662, 1702, 'They tip-toed out, through the broken weather-boarding, and stopped at a little distance to exchange a parting word.', '他们踮着脚从破烂的木板缝里走出去，在不远处停下来，小声说了几句告别的话。'),
    (10, 662, 1703, 'That long, lugubrious howl rose on the night air again!', '那又长又悲伤的狗叫声，再次在夜空中响起！'),
    (10, 662, 1704, 'They turned and saw the strange dog standing within a few feet of where Potter was lying, and _facing_ Potter, with his nose pointing heavenward.', '他们转过身，看到那只陌生的狗站在离波特躺着的地方几英尺远的地方，鼻子朝上，正对着波特。'),
    (10, 663, 1705, '“Oh, geeminy, it’s _him_!” exclaimed both boys, in a breath.', '“哦，天哪，是_他_！”两个男孩异口同声地喊道。'),
    (10, 664, 1706, '“Say, Tom—they say a stray dog come howling around Johnny Miller’s house, ’bout midnight, as much as two weeks ago; and a whippoorwill come in and lit on the banisters and sung, the very same evening; and there ain’t anybody dead there yet.”', '“喂，汤姆——他们说，大约两周前，有一只流浪狗半夜在约翰尼·米勒家附近嚎叫；同一天晚上，一只北美夜鹰飞进来，落在扶手上唱歌；但他们家到现在还没人死。”'),
    (10, 665, 1707, '“Well, I know that.', '“嗯，我知道。'),
    (10, 665, 1708, 'And suppose there ain’t.', '就算没有呢？'),
    (10, 665, 1709, 'Didn’t Gracie Miller fall in the kitchen fire and burn herself terrible the very next Saturday?”', '下一个星期六，格蕾西·米勒不是掉进厨房的火里，烧伤得很厉害吗？”'),
    (10, 666, 1710, '“Yes, but she ain’t _dead_.', '“是的，但她还没_死_。”'),
    (10, 666, 1711, 'And what’s more, she’s getting better, too.”', '而且啊，她现在也越来越好了。'),
    (10, 667, 1712, '“All right, you wait and see.', '“好吧，你等着瞧吧。'),
    (10, 667, 1713, 'She’s a goner, just as dead sure as Muff Potter’s a goner.', '她肯定活不成了，就像莫夫·波特肯定活不成了一样。'),
    (10, 667, 1714, 'That’s what the niggers say, and they know all about these kind of things, Huck.”', '他们就是这么说的，而且他们对这些事情很了解，哈克。”'),
    (10, 668, 1715, 'Then they separated, cogitating.', '之后他们分开了，各自想着心事。'),
    (10, 668, 1716, 'When Tom crept in at his bedroom window the night was almost spent.', '当汤姆从他卧室的窗户爬进去的时候，天快亮了。'),
    (10, 668, 1717, 'He undressed with excessive caution, and fell asleep congratulating himself that nobody knew of his escapade.', '他非常小心地脱了衣服，然后睡着了，心里还庆幸着没人知道他偷偷溜出去的事。'),
    (10, 668, 1718, 'He was not aware that the gently-snoring Sid was awake, and had been so for an hour.', '他不知道，正在轻轻打鼾的希德其实醒着，而且已经醒了一个小时了。'),
    (10, 669, 1719, 'When Tom awoke, Sid was dressed and gone.', '当汤姆醒来时，希德已经穿好衣服走了。'),
    (10, 669, 1720, 'There was a late look in the light, a late sense in the atmosphere.', '光线看起来很迟钝，周围的气氛也很沉闷。'),
    (10, 669, 1721, 'He was startled.', '他吓了一跳。'),
    (10, 669, 1722, 'Why had he not been called—persecuted till he was up, as usual?', '为什么没人叫他起床呢？以前可总是催着他，直到他起来为止啊！'),
    (10, 669, 1723, 'The thought filled him with bodings.', '这个想法让他心里充满了不好的预感。'),
    (10, 669, 1724, 'Within five minutes he was dressed and down-stairs, feeling sore and drowsy.', '不到五分钟，他就穿好衣服下楼了，感觉浑身酸痛又犯困。'),
    (10, 669, 1725, 'The family were still at table, but they had finished breakfast.', '家里人还在桌边，不过他们已经吃完早饭了。'),
    (10, 669, 1726, 'There was no voice of rebuke; but there were averted eyes; there was a silence and an air of solemnity that struck a chill to the culprit’s heart.', '没有人责骂他；但大家都不看他，气氛很安静也很严肃，这让这个犯错的孩子心里凉凉的。'),
    (10, 669, 1727, 'He sat down and tried to seem gay, but it was up-hill work; it roused no smile, no response, and he lapsed into silence and let his heart sink down to the depths.', '他坐下来，想表现得很开心，但这太难了；没人对他笑，也没人回应他，于是他又沉默了，心里也越来越难过。'),
    (10, 670, 1728, 'After breakfast his aunt took him aside, and Tom almost brightened in the hope that he was going to be flogged; but it was not so.', '吃完早饭，阿姨把他拉到一边，汤姆心里甚至有点高兴，以为自己要挨打了；但结果并不是这样。'),
    (10, 670, 1729, 'His aunt wept over him and asked him how he could go and break her old heart so; and finally told him to go on, and ruin himself and bring her gray hairs with sorrow to the grave, for it was no use for her to try any more.', '阿姨哭着抱住他，问他怎么能这么伤她的心；最后告诉他，随便他去闯祸吧，把她的白头发都气得伤心带到坟墓里去，她再也不管了。'),
    (10, 670, 1730, 'This was worse than a thousand whippings, and Tom’s heart was sorer now than his body.', '这比打他一千次还难受，汤姆的心比身体更痛了。'),
    (10, 670, 1731, 'He cried, he pleaded for forgiveness, promised to reform over and over again, and then received his dismissal, feeling that he had won but an imperfect forgiveness and established but a feeble confidence.', '他哭了，不停地求大家原谅他，一遍又一遍地保证会改好，最后他被放走了，感觉自己得到的原谅不太完全，大家对他的信任也很少。'),
    (10, 671, 1732, 'He left the presence too miserable to even feel revengeful toward Sid; and so the latter’s prompt retreat through the back gate was unnecessary.', '他离开的时候太难过了，甚至都顾不上生希德的气了；所以希德赶紧从后门溜走其实是没必要的。'),
    (10, 671, 1733, 'He moped to school gloomy and sad, and took his flogging, along with Joe Harper, for playing hookey the day before, with the air of one whose heart was busy with heavier woes and wholly dead to trifles.', '他闷闷不乐、愁眉苦脸地去了学校，和乔·哈珀一起因为前一天逃学而挨了打，但他心里只想着更沉重的事情，对这些小事一点都不在乎。'),
    (10, 671, 1734, 'Then he betook himself to his seat, rested his elbows on his desk and his jaws in his hands, and stared at the wall with the stony stare of suffering that has reached the limit and can no further go.', '然后他回到座位上，把手肘放在桌上，两只手托着下巴，呆呆地看着墙，那种痛苦的眼神好像已经到了极限，再也承受不住了。'),
    (10, 671, 1735, 'His elbow was pressing against some hard substance.', '他的手肘碰到一个硬硬的东西。'),
    (10, 671, 1736, 'After a long time he slowly and sadly changed his position, and took up this object with a sigh.', '过了很久，他才慢慢地、伤心地换了个姿势，叹了口气，拿起那个东西。'),
    (10, 671, 1737, 'It was in a paper.', '它包在纸里。'),
    (10, 671, 1738, 'He unrolled it.', '他把它打开了。'),
    (10, 671, 1739, 'A long, lingering, colossal sigh followed, and his heart broke.', '接着他长长地、久久地、大大地叹了口气，然后他的心都碎了。'),
    (10, 671, 1740, 'It was his brass andiron knob!', '那是他的黄铜火炉架装饰球！'),
    (10, 672, 1741, 'This final feather broke the camel’s back.', '这最后一根羽毛，把骆驼压垮了。'),
    (11, 673, 1742, 'Close upon the hour of noon the whole village was suddenly electrified with the ghastly news.', '快到中午的时候，整个村子突然被一个可怕的消息吓到了。'),
    (11, 673, 1743, 'No need of the as yet un-dreamed-of telegraph; the tale flew from man to man, from group to group, from house to house, with little less than telegraphic speed.', '那时还没有电报，消息却传得飞快。一个人告诉另一个人，一家人告诉另一家人，比电报还快呢！'),
    (11, 673, 1744, 'Of course the schoolmaster gave holiday for that afternoon; the town would have thought strangely of him if he had not.', '当然，那天下午老师就给大家放假了。要是他不放假，村里人都会觉得他很奇怪呢。'),
    (11, 674, 1745, 'A gory knife had been found close to the murdered man, and it had been recognized by somebody as belonging to Muff Potter—so the story ran.', '被杀的人旁边，发现了一把沾血的刀。有人说，这把刀是莫夫·波特的——大家都这么传。'),
    (11, 674, 1746, 'And it was said that a belated citizen had come upon Potter washing himself in the “branch” about one or two o’clock in the morning, and that Potter had at once sneaked off—suspicious circumstances, especially the washing which was not a habit with Potter.', '还有人说，一个回家晚了的人，在凌晨一两点的时候，看见波特在小河里洗澡。然后，波特就马上偷偷溜走了——这事很可疑，特别是洗澡这件事，因为波特平时可不爱洗澡呢。'),
    (11, 674, 1747, 'It was also said that the town had been ransacked for this “murderer” (the public are not slow in the matter of sifting evidence and arriving at a verdict), but that he could not be found.', '大家还说，整个镇子都在找这个“杀人犯”，可是找不到他。'),
    (11, 674, 1748, 'Horsemen had departed down all the roads in every direction, and the Sheriff “was confident” that he would be captured before night.', '骑马的人已经往四面八方的路上出发了。警长说，他“很有信心”，一定能在天黑前抓住凶手。'),
    (11, 675, 1749, 'All the town was drifting toward the graveyard.', '整个镇子的人都慢慢走向墓地。'),
    (11, 675, 1750, 'Tom’s heartbreak vanished and he joined the procession, not because he would not a thousand times rather go anywhere else, but because an awful, unaccountable fascination drew him on.', '汤姆不再那么伤心了，他也跟着人群走去。不是因为他更想去那里，而是因为一种可怕又说不清的吸引力把他拉了过去。'),
    (11, 675, 1751, 'Arrived at the dreadful place, he wormed his small body through the crowd and saw the dismal spectacle.', '到了那个可怕的地方，他挤过人群，看到了那悲惨的一幕。'),
    (11, 675, 1752, 'It seemed to him an age since he was there before.', '他觉得，上次来这里到现在，好像过了好久好久。'),
    (11, 675, 1753, 'Somebody pinched his arm.', '有人捏了一下他的胳膊。'),
    (11, 675, 1754, 'He turned, and his eyes met Huckleberry’s.', '他转过头，看到了哈克贝利。'),
    (11, 675, 1755, 'Then both looked elsewhere at once, and wondered if anybody had noticed anything in their mutual glance.', '然后，两人立刻看向别处，心想有没有人发现他们刚才互相看了一眼。'),
    (11, 675, 1756, 'But everybody was talking, and intent upon the grisly spectacle before them.', '但是大家都在说话，全神贯注地看着眼前那个可怕的景象。'),
    (11, 676, 1757, '“Poor fellow!”', '“可怜的家伙！”'),
    (11, 676, 1758, '“Poor young fellow!”', '“可怜的年轻人啊！”'),
    (11, 676, 1759, '“This ought to be a lesson to grave robbers!”', '“这下，盗墓贼可要得到教训了！”'),
    (11, 676, 1760, '“Muff Potter’ll hang for this if they catch him!”', '“如果他们抓住莫夫·波特，他就要被吊死了！”'),
    (11, 676, 1761, 'This was the drift of remark; and the minister said, “It was a judgment; His hand is here.”', '大家都是这么说的；牧师说：“这是老天爷的惩罚，老天爷在管这件事呢。”'),
    (11, 677, 1762, 'Now Tom shivered from head to heel; for his eye fell upon the stolid face of Injun Joe.', '现在，汤姆从头到脚都颤抖起来；因为他的目光落在了印第安·乔那没有表情的脸上。'),
    (11, 677, 1763, 'At this moment the crowd began to sway and struggle, and voices shouted, “It’s him! it’s him! he’s coming himself!”', '就在这时，人群开始晃动和推搡，有人喊起来：“是他！是他！他自己来了！”'),
    (11, 678, 1764, '“Who?', '“谁？'),
    (11, 678, 1765, 'Who?” from twenty voices.', '二十多个人都在问：“是谁？”'),
    (11, 679, 1766, '“Muff Potter!”', '“莫夫·波特！”'),
    (11, 680, 1767, '“Hallo, he’s stopped!', '“嘿，他停下来了！'),
    (11, 680, 1768, '—Look out, he’s turning!', '—快看，他在转身！'),
    (11, 680, 1769, 'Don’t let him get away!”', '别让他跑了！”'),
    (11, 681, 1770, 'People in the branches of the trees over Tom’s head said he wasn’t trying to get away—he only looked doubtful and perplexed.', '在汤姆头顶上方树枝上的人说，他没有想跑——他只是看起来有点犹豫，不知道该怎么办。'),
    (11, 682, 1771, '“Infernal impudence!” said a bystander; “wanted to come and take a quiet look at his work, I reckon—didn’t expect any company.”', '“真是太不像话了！”一个围观的人说，“他肯定是想偷偷来看看他做的事，没想到有人在这。”'),
    (11, 683, 1772, 'The crowd fell apart, now, and the Sheriff came through, ostentatiously leading Potter by the arm.', '人群散开了，警长走了过来，故意拉着波特的胳膊。'),
    (11, 683, 1773, 'The poor fellow’s face was haggard, and his eyes showed the fear that was upon him.', '这个可怜人脸色苍白，眼睛里全是害怕。'),
    (11, 683, 1774, 'When he stood before the murdered man, he shook as with a palsy, and he put his face in his hands and burst into tears.', '当他站在被杀的人面前时，他抖得厉害，他把脸埋在手里，大哭起来。'),
    (11, 684, 1775, '“I didn’t do it, friends,” he sobbed; “’pon my word and honor I never done it.”', '“朋友们，不是我干的！”他抽泣着说，“我发誓，真的不是我干的。”'),
    (11, 685, 1776, '“Who’s accused you?” shouted a voice.', '“谁说你干的？”一个声音喊道。'),
    (11, 686, 1777, 'This shot seemed to carry home.', '这句话好像让他听进去了。'),
    (11, 686, 1778, 'Potter lifted his face and looked around him with a pathetic hopelessness in his eyes.', '波特抬起脸，看了看四周，他的眼睛里带着绝望。'),
    (11, 686, 1779, 'He saw Injun Joe, and exclaimed:', '他看到了印第安·乔，大声说：'),
    (11, 687, 1780, '“Oh, Injun Joe, you promised me you’d never—”', '“哦，印第安·乔，你答应过我你不会——”'),
    (11, 688, 1781, '“Is that your knife?” and it was thrust before him by the Sheriff.', '“这是你的刀吗？”警长把刀推到他面前。'),
    (11, 689, 1782, 'Potter would have fallen if they had not caught him and eased him to the ground.', '波特差点摔倒，幸好大家扶住了他，让他坐在地上。'),
    (11, 689, 1783, 'Then he said:', '然后他说：'),
    (11, 690, 1784, '“Something told me ’t if I didn’t come back and get—” He shuddered; then waved his nerveless hand with a vanquished gesture and said, “Tell ’em, Joe, tell ’em—it ain’t any use any more.”', '“我心里好像有个声音告诉我，如果我不回来拿——”他发抖了；然后他无力地挥了挥手，像认输一样说，“告诉他们吧，乔，告诉他们吧——现在说什么都没用了。”'),
    (11, 691, 1785, 'Then Huckleberry and Tom stood dumb and staring, and heard the stony-hearted liar reel off his serene statement, they expecting every moment that the clear sky would deliver God’s lightnings upon his head, and wondering to see how long the stroke was delayed.', '然后哈克贝利和汤姆呆呆地站在那儿，一动不动，听着那个狠心的骗子平静地说着谎话，他们每时每刻都以为老天爷会打雷劈他，想知道为什么雷还没劈下来。'),
    (11, 691, 1786, 'And when he had finished and still stood alive and whole, their wavering impulse to break their oath and save the poor betrayed prisoner’s life faded and vanished away, for plainly this miscreant had sold himself to Satan and it would be fatal to meddle with the property of such a power as that.', '等他说完，还好好地活着，他们想打破誓言，救那个可怜的被冤枉的人的念头就消失了，因为很明显，这个坏蛋把自己卖给了魔鬼，和魔鬼的东西作对，会很危险的。'),
    (11, 692, 1787, '“Why didn’t you leave?', '“你为什么不走？'),
    (11, 692, 1788, 'What did you want to come here for?” somebody said.', '你来这里干什么？”有人说。'),
    (11, 693, 1789, '“I couldn’t help it—I couldn’t help it,” Potter moaned.', '“我没办法——我没办法！”波特痛苦地呻吟着。'),
    (11, 693, 1790, '“I wanted to run away, but I couldn’t seem to come anywhere but here.”', '“我想跑掉，但我好像只能来这里。”'),
    (11, 693, 1791, 'And he fell to sobbing again.', '然后他又开始抽泣起来。'),
    (11, 694, 1792, 'Injun Joe repeated his statement, just as calmly, a few minutes afterward on the inquest, under oath; and the boys, seeing that the lightnings were still withheld, were confirmed in their belief that Joe had sold himself to the devil.', '几分钟后，印第安·乔在法庭上发誓，还是那么平静地重复了他的话；男孩们看到雷电还是没有劈下来，就更相信乔把自己卖给了魔鬼。'),
    (11, 694, 1793, 'He was now become, to them, the most balefully interesting object they had ever looked upon, and they could not take their fascinated eyes from his face.', '现在，他成了他们见过最吓人、最有意思的人，他们被他的脸迷住了，眼睛都移不开。'),
    (11, 695, 1794, 'They inwardly resolved to watch him nights, when opportunity should offer, in the hope of getting a glimpse of his dread master.', '他们心里决定晚上要盯着他，等有机会的时候，希望能看到那个可怕的魔鬼主人。'),
    (11, 696, 1795, 'Injun Joe helped to raise the body of the murdered man and put it in a wagon for removal; and it was whispered through the shuddering crowd that the wound bled a little!', '印第安·乔帮忙抬起了被杀的人的尸体，放进马车里运走；颤抖的人群中，有人小声说伤口竟然流了一点血！'),
    (11, 696, 1796, 'The boys thought that this happy circumstance would turn suspicion in the right direction; but they were disappointed, for more than one villager remarked:', '男孩们以为这个“好兆头”会让大家怀疑对的人；但他们失望了，因为不止一个村民说：'),
    (11, 697, 1797, '“It was within three feet of Muff Potter when it done it.”', '“这件事发生的时候，就在莫夫·波特身边三英尺的地方。”'),
    (11, 698, 1798, 'Tom’s fearful secret and gnawing conscience disturbed his sleep for as much as a week after this; and at breakfast one morning Sid said:', '汤姆的可怕秘密和内心不安让他一个多星期都睡不好觉；有一天早上吃早饭时，希德说：'),
    (11, 699, 1799, '“Tom, you pitch around and talk in your sleep so much that you keep me awake half the time.”', '“汤姆，你睡觉的时候老是翻来翻去，还说梦话，害得我一半时间都睡不着。”'),
    (11, 700, 1800, 'Tom blanched and dropped his eyes.', '汤姆脸色发白，低下了头。'),
    (11, 701, 1801, '“It’s a bad sign,” said Aunt Polly, gravely.', '“这是个不好的兆头，” 波莉姨妈认真地说。'),
    (11, 701, 1802, '“What you got on your mind, Tom?”', '“你心里在想什么，汤姆？”'),
    (11, 702, 1803, '“Nothing.', '“没什么。'),
    (11, 702, 1804, 'Nothing ’t I know of.”', '我不知道有什么事。”'),
    (11, 702, 1805, 'But the boy’s hand shook so that he spilled his coffee.', '但是男孩的手抖得厉害，把咖啡都洒了。'),
    (11, 703, 1806, '“And you do talk such stuff,” Sid said.', '“你确实说了一些奇怪的话，” 希德说。'),
    (11, 703, 1807, '“Last night you said, ‘It’s blood, it’s blood, that’s what it is!’', '“昨晚你说，‘是血，是血，就是血！’'),
    (11, 703, 1808, 'You said that over and over.', '你一遍又一遍地说。'),
    (11, 703, 1809, 'And you said, ‘Don’t torment me so—I’ll tell!’', '你还说，‘别再折磨我了——我会说出来的！’'),
    (11, 703, 1810, 'Tell _what_?', '说什么呢？'),
    (11, 703, 1811, 'What is it you’ll tell?”', '你要说什么？”'),
    (11, 704, 1812, 'Everything was swimming before Tom.', '汤姆觉得眼前的东西都在转。'),
    (11, 704, 1813, 'There is no telling what might have happened, now, but luckily the concern passed out of Aunt Polly’s face and she came to Tom’s relief without knowing it.', '现在不知道会发生什么，但幸好，波莉姨妈脸上的担心不见了。她自己都没发现，就帮了汤姆的忙。'),
    (11, 704, 1814, 'She said:', '她说：'),
    (11, 705, 1815, '“Sho!', '“哎呀！'),
    (11, 705, 1816, 'It’s that dreadful murder.', '是那件可怕的杀人案。'),
    (11, 705, 1817, 'I dream about it most every night myself.', '我自己几乎每晚都梦到它。'),
    (11, 705, 1818, 'Sometimes I dream it’s me that done it.”', '有时我梦到是我干的。”'),
    (11, 706, 1819, 'Mary said she had been affected much the same way.', '玛丽说她也和她一样，心里很难受。'),
    (11, 706, 1820, 'Sid seemed satisfied.', '希德看起来很满意。'),
    (11, 706, 1821, 'Tom got out of the presence as quick as he plausibly could, and after that he complained of toothache for a week, and tied up his jaws every night.', '汤姆赶紧离开了。那以后，他抱怨牙疼了一周，每天晚上都把嘴巴包起来。'),
    (11, 706, 1822, 'He never knew that Sid lay nightly watching, and frequently slipped the bandage free and then leaned on his elbow listening a good while at a time, and afterward slipped the bandage back to its place again.', '他从不知道，希德每晚都会躺着悄悄看他。她常常把绷带解开，然后靠着胳膊，静静地听好久。听完后，又把绷带绑回去。'),
    (11, 706, 1823, 'Tom’s distress of mind wore off gradually and the toothache grew irksome and was discarded.', '汤姆心里难受的感觉慢慢淡了，牙疼也变得很烦人，后来就不再管它了。'),
    (11, 706, 1824, 'If Sid really managed to make anything out of Tom’s disjointed mutterings, he kept it to himself.', '如果希德真的从汤姆说的话里听懂了什么，他也没告诉别人。'),
    (11, 707, 1825, 'It seemed to Tom that his schoolmates never would get done holding inquests on dead cats, and thus keeping his trouble present to his mind.', '汤姆觉得他的同学们好像永远也查不完死猫的事，这让他的烦恼总在心里。'),
    (11, 707, 1826, 'Sid noticed that Tom never was coroner at one of these inquiries, though it had been his habit to take the lead in all new enterprises; he noticed, too, that Tom never acted as a witness—and that was strange; and Sid did not overlook the fact that Tom even showed a marked aversion to these inquests, and always avoided them when he could.', '希德发现，汤姆从来没有在这些调查中做过“验尸官”，虽然他以前总是喜欢带头做新事。他还发现，汤姆也从来没有做过证人——这很奇怪。希德也没有忽略一点，那就是汤姆好像特别不喜欢这些调查，能躲开就躲开。'),
    (11, 707, 1827, 'Sid marvelled, but said nothing.', '希德很惊讶，但什么也没说。'),
    (11, 707, 1828, 'However, even inquests went out of vogue at last, and ceased to torture Tom’s conscience.', '不过，这些调查最后也不流行了，汤姆的良心也不再受折磨了。'),
    (11, 708, 1829, 'Every day or two, during this time of sorrow, Tom watched his opportunity and went to the little grated jail-window and smuggled such small comforts through to the “murderer” as he could get hold of.', '在这段难过的日子里，每隔一两天，汤姆就会找机会去小小的监狱窗户那里，把能弄到的小零食什么的偷偷塞给那个“凶手”。'),
    (11, 708, 1830, 'The jail was a trifling little brick den that stood in a marsh at the edge of the village, and no guards were afforded for it; indeed, it was seldom occupied.', '那个监狱是个小小的砖房，孤零零地立在村子边上的沼泽地里。那里没有守卫看管，而且也很少有人住。'),
    (11, 708, 1831, 'These offerings greatly helped to ease Tom’s conscience.', '这些东西让汤姆心里好受了很多。'),
    (11, 709, 1832, 'The villagers had a strong desire to tar-and-feather Injun Joe and ride him on a rail, for body-snatching, but so formidable was his character that nobody could be found who was willing to take the lead in the matter, so it was dropped.', '村民们很想惩罚印第安·乔，因为他挖坟偷尸体。但是他太厉害了，没人敢带头，所以这件事就放下了。'),
    (11, 709, 1833, 'He had been careful to begin both of his inquest-statements with the fight, without confessing the grave-robbery that preceded it; therefore it was deemed wisest not to try the case in the courts at present.', '他很小心，两次说起这件事，都只从打架开始，没有说之前他偷尸体的事。所以，大家觉得现在不要去法庭上审理这个案子最聪明。'),
    (12, 710, 1834, 'One of the reasons why Tom’s mind had drifted away from its secret troubles was, that it had found a new and weighty matter to interest itself about.', '汤姆不再为自己的秘密烦恼了，因为他发现了一件新的、更重要的事情，让他很感兴趣。'),
    (12, 710, 1835, 'Becky Thatcher had stopped coming to school.', '贝琪·撒切尔不来学校了。'),
    (12, 710, 1836, 'Tom had struggled with his pride a few days, and tried to “whistle her down the wind,” but failed.', '汤姆挣扎了好几天，想放下他的骄傲，假装不在乎她，但没有成功。'),
    (12, 710, 1837, 'He began to find himself hanging around her father’s house, nights, and feeling very miserable.', '他开始在晚上跑到她爸爸家附近转悠，心里很难过。'),
    (12, 710, 1838, 'She was ill.', '她生病了。'),
    (12, 710, 1839, 'What if she should die!', '万一她死了怎么办！'),
    (12, 710, 1840, 'There was distraction in the thought.', '这个想法让他很不安。'),
    (12, 710, 1841, 'He no longer took an interest in war, nor even in piracy.', '他不再对打仗感兴趣了，甚至连海盗游戏也不喜欢了。'),
    (12, 710, 1842, 'The charm of life was gone; there was nothing but dreariness left.', '生活的乐趣没有了；只剩下无聊。'),
    (12, 710, 1843, 'He put his hoop away, and his bat; there was no joy in them any more.', '他把呼啦圈和球棒收起来了；玩它们再也没有乐趣了。'),
    (12, 710, 1844, 'His aunt was concerned.', '他的姨妈很担心。'),
    (12, 710, 1845, 'She began to try all manner of remedies on him.', '她开始在他身上试各种各样的药方。'),
    (12, 710, 1846, 'She was one of those people who are infatuated with patent medicines and all new-fangled methods of producing health or mending it.', '她就是那种特别喜欢偏方和各种新奇保健方法的人。'),
    (12, 710, 1847, 'She was an inveterate experimenter in these things.', '她总是喜欢尝试这些东西。'),
    (12, 710, 1848, 'When something fresh in this line came out she was in a fever, right away, to try it; not on herself, for she was never ailing, but on anybody else that came handy.', '只要有新的东西出来，她就会立刻兴奋地想去试；不是在她自己身上试，因为她从不生病，而是找身边的人试。'),
    (12, 710, 1849, 'She was a subscriber for all the “Health” periodicals and phrenological frauds; and the solemn ignorance they were inflated with was breath to her nostrils.', '她订阅了所有“健康”杂志和那些假装看相识人的刊物；这些东西里那些一本正经的无知内容，她却深信不疑。'),
    (12, 710, 1850, 'All the “rot” they contained about ventilation, and how to go to bed, and how to get up, and what to eat, and what to drink, and how much exercise to take, and what frame of mind to keep one’s self in, and what sort of clothing to wear, was all gospel to her, and she never observed that her health-journals of the current month customarily upset everything they had recommended the month before.', '杂志里说的那些关于通风、睡觉、起床、吃什么、喝什么、做多少运动、保持什么心情、穿什么衣服的“废话”，在她看来都是真理。她从来没发现，这个月的健康杂志总是推翻上个月推荐的东西。'),
    (12, 710, 1851, 'She was as simple-hearted and honest as the day was long, and so she was an easy victim.', '她心很单纯，很诚实，所以很容易上当受骗。'),
    (12, 710, 1852, 'She gathered together her quack periodicals and her quack medicines, and thus armed with death, went about on her pale horse, metaphorically speaking, with “hell following after.”', '她把那些骗人的杂志和假药都收集起来。她就像一个带着“死亡”武器的人，到处乱跑，用这些不好的东西去“害人”。'),
    (12, 710, 1853, 'But she never suspected that she was not an angel of healing and the balm of Gilead in disguise, to the suffering neighbors.', '但她从没怀疑过自己不是一个治病救人的天使，没怀疑过自己不是给受苦的邻居带来安慰的良药。'),
    (12, 711, 1854, 'The water treatment was new, now, and Tom’s low condition was a windfall to her.', '水疗法现在很流行，汤姆生病了，这可让她逮着机会了。'),
    (12, 711, 1855, 'She had him out at daylight every morning, stood him up in the wood-shed and drowned him with a deluge of cold water; then she scrubbed him down with a towel like a file, and so brought him to; then she rolled him up in a wet sheet and put him away under blankets till she sweated his soul clean and “the yellow stains of it came through his pores”—as Tom said.', '她每天早上天一亮就把他叫起来，让他站在柴棚里，然后用一大盆一大盆的冷水往他身上泼。接着，她用粗糙的毛巾像搓衣服一样擦他，直到他清醒过来。然后，她把他裹在湿床单里，盖上毯子，让他一直出汗，直到他全身的“脏东西都从毛孔里流出来”——就像汤姆自己说的那样。'),
    (12, 712, 1856, 'Yet notwithstanding all this, the boy grew more and more melancholy and pale and dejected.', '但尽管这样，这个男孩还是越来越伤心、脸色苍白、无精打采。'),
    (12, 712, 1857, 'She added hot baths, sitz baths, shower baths, and plunges.', '她又给他加上了热水浴、坐浴、淋浴和浸泡浴。'),
    (12, 712, 1858, 'The boy remained as dismal as a hearse.', '男孩仍然闷闷不乐，一点都不开心。'),
    (12, 712, 1859, 'She began to assist the water with a slim oatmeal diet and blister-plasters.', '她开始在水疗法之外，给他吃很少的燕麦片，还给他贴上起泡膏药。'),
    (12, 712, 1860, 'She calculated his capacity as she would a jug’s, and filled him up every day with quack cure-alls.', '她像量杯子一样估算他的胃口，每天都给他灌满那些假药。'),
    (12, 713, 1861, 'Tom had become indifferent to persecution by this time.', '汤姆 这时候已经对受罚不当回事了。'),
    (12, 713, 1862, 'This phase filled the old lady’s heart with consternation.', '老奶奶看到这样，心里很着急。'),
    (12, 713, 1863, 'This indifference must be broken up at any cost.', '这种不当回事的态度，一定要改掉。'),
    (12, 713, 1864, 'Now she heard of Pain-killer for the first time.', '她现在第一次听说了“止痛药”。'),
    (12, 713, 1865, 'She ordered a lot at once.', '她立刻买了很多。'),
    (12, 713, 1866, 'She tasted it and was filled with gratitude.', '她尝了尝，非常感激。'),
    (12, 713, 1867, 'It was simply fire in a liquid form.', '这就像是液体的火。'),
    (12, 713, 1868, 'She dropped the water treatment and everything else, and pinned her faith to Pain-killer.', '她不再用水和其他方法了，只信止痛药。'),
    (12, 713, 1869, 'She gave Tom a teaspoonful and watched with the deepest anxiety for the result.', '她给汤姆喂了一小勺，非常担心地等着看效果。'),
    (12, 713, 1870, 'Her troubles were instantly at rest, her soul at peace again; for the “indifference” was broken up.', '她的烦恼一下子就没了，心里又平静了。因为那种“不理不睬”没有了。'),
    (12, 713, 1871, 'The boy could not have shown a wilder, heartier interest, if she had built a fire under him.', '要是老奶奶在他屁股下点火，他也不会表现得更野、更来劲了。'),
    (12, 714, 1872, 'Tom felt that it was time to wake up; this sort of life might be romantic enough, in his blighted condition, but it was getting to have too little sentiment and too much distracting variety about it.', '汤姆 觉得是时候清醒了。他这样受罪的日子，也许有点意思，但少了感情，让人分心的事情却太多了。'),
    (12, 714, 1873, 'So he thought over various plans for relief, and finally hit upon that of professing to be fond of Pain-killer.', '所以他想了很多办法来解脱，最后想到了假装自己喜欢“止痛药”。'),
    (12, 714, 1874, 'He asked for it so often that he became a nuisance, and his aunt ended by telling him to help himself and quit bothering her.', '他老是缠着姑妈要止痛药，姑妈烦透了，就让他自己去拿，别再烦她了。'),
    (12, 714, 1875, 'If it had been Sid, she would have had no misgivings to alloy her delight; but since it was Tom, she watched the bottle clandestinely.', '要是希德拿药，她不会有什么不放心，会很高兴；但因为是汤姆，她就偷偷地看着药瓶。'),
    (12, 714, 1876, 'She found that the medicine did really diminish, but it did not occur to her that the boy was mending the health of a crack in the sitting-room floor with it.', '她发现药确实少了，但她没想到男孩在用它修补客厅地板的裂缝。'),
    (12, 715, 1877, 'One day Tom was in the act of dosing the crack when his aunt’s yellow cat came along, purring, eyeing the teaspoon avariciously, and begging for a taste.', '有一天，汤姆正在往裂缝里倒药，姑妈的黄猫走了过来。它一边发出咕噜咕噜的声音，一边贪婪地盯着小勺子，还想尝尝。'),
    (12, 715, 1878, 'Tom said:', '汤姆 说：'),
    (12, 716, 1879, '“Don’t ask for it unless you want it, Peter.”', '“彼得，你不想吃就别要。”'),
    (12, 717, 1880, 'But Peter signified that he did want it.', '但彼得表示他确实想吃。'),
    (12, 718, 1881, '“You better make sure.”', '“你最好确定一下。”'),
    (12, 719, 1882, 'Peter was sure.', '彼得很确定。'),
    (12, 720, 1883, '“Now you’ve asked for it, and I’ll give it to you, because there ain’t anything mean about me; but if you find you don’t like it, you mustn’t blame anybody but your own self.”', '“既然你都开口了，那我就给你，因为我可不小气；不过如果你发现不喜欢，可不能怪别人，只能怪你自己。”'),
    (12, 721, 1884, 'Peter was agreeable.', '彼得同意了。'),
    (12, 721, 1885, 'So Tom pried his mouth open and poured down the Pain-killer.', '于是汤姆撬开它的嘴巴，把止痛药倒了进去。'),
    (12, 721, 1886, 'Peter sprang a couple of yards in the air, and then delivered a war-whoop and set off round and round the room, banging against furniture, upsetting flower-pots, and making general havoc.', '彼得一下子跳到半空中几码高，然后大叫一声，在屋子里跑来跑去，撞到家具，打翻花盆，把房间弄得一团糟。'),
    (12, 721, 1887, 'Next he rose on his hind feet and pranced around, in a frenzy of enjoyment, with his head over his shoulder and his voice proclaiming his unappeasable happiness.', '接着它用后腿站起来，又跳又舞，开心得发疯，头扭过肩，大声叫着它止不住的快乐。'),
    (12, 721, 1888, 'Then he went tearing around the house again spreading chaos and destruction in his path.', '然后它又在屋子里到处跑，一路制造混乱和破坏。'),
    (12, 721, 1889, 'Aunt Polly entered in time to see him throw a few double summersets, deliver a final mighty hurrah, and sail through the open window, carrying the rest of the flower-pots with him.', '波莉姨妈 及时走了进来，看到它做了几个空中翻转，最后用力大喊一声，然后从开着的窗户飞了出去，还把剩下的花盆也带走了。'),
    (12, 721, 1890, 'The old lady stood petrified with astonishment, peering over her glasses; Tom lay on the floor expiring with laughter.', '老奶奶惊讶得呆住了，她透过眼镜看着；汤姆则躺在地板上笑得喘不过气来。'),
    (12, 722, 1891, '“Tom, what on earth ails that cat?”', '“汤姆，那猫到底怎么了？”'),
    (12, 723, 1892, '“I don’t know, aunt,” gasped the boy.', '“我不知道，阿姨。”'),
    (12, 724, 1893, '“Why, I never see anything like it.', '“哎呀，我从没见过这样的事。'),
    (12, 724, 1894, 'What did make him act so?”', '它怎么会这样啊？”'),
    (12, 725, 1895, '“Deed I don’t know, Aunt Polly; cats always act so when they’re having a good time.”', '“我不知道，波莉姨妈；猫玩得开心的时候，总是这样。”'),
    (12, 726, 1896, '“They do, do they?”', '“它们是这样吗？”'),
    (12, 726, 1897, 'There was something in the tone that made Tom apprehensive.', '她的语气让汤姆有点害怕。'),
    (12, 727, 1898, '“Yes’m.', '“是的，阿姨。'),
    (12, 727, 1899, 'That is, I believe they do.”', '我是说，我觉得是这样。”'),
    (12, 728, 1900, '“You _do_?”', '“你真的觉得是这样吗？”'),
    (12, 729, 1901, '“Yes’m.”', '“是的，阿姨。”'),
    (12, 730, 1902, 'The old lady was bending down, Tom watching, with interest emphasized by anxiety.', '老妇人弯下腰，汤姆看着，又好奇又担心。'),
    (12, 730, 1903, 'Too late he divined her “drift.”', '太晚了，他才明白她的意思。'),
    (12, 730, 1904, 'The handle of the telltale tea-spoon was visible under the bed-valance.', '那把勺子的把手从床罩下面露出来了。'),
    (12, 730, 1905, 'Aunt Polly took it, held it up.', '波莉姨妈把它拿起来，举着。'),
    (12, 730, 1906, 'Tom winced, and dropped his eyes.', '汤姆吓得一哆嗦，并低下了头。'),
    (12, 730, 1907, 'Aunt Polly raised him by the usual handle—his ear—and cracked his head soundly with her thimble.', '波莉姨妈像平时一样揪住他的耳朵，用顶针狠狠敲了一下他的头。'),
    (12, 731, 1908, '“Now, sir, what did you want to treat that poor dumb beast so, for?”', '“喂，你啊，你为什么要这样对待那只可怜的小动物呢？”'),
    (12, 732, 1909, '“I done it out of pity for him—because he hadn’t any aunt.”', '“我可怜它才这么做的——因为它没有阿姨。”'),
    (12, 733, 1910, '“Hadn’t any aunt!', '“没有阿姨！'),
    (12, 733, 1911, '—you numskull.', '——你这个笨蛋。'),
    (12, 733, 1912, 'What has that got to do with it?”', '这有什么关系？”'),
    (12, 734, 1913, '“Heaps.', '“关系可大了。'),
    (12, 734, 1914, 'Because if he’d had one she’d a burnt him out herself!', '因为如果它有阿姨，她会自己把它烧死的！'),
    (12, 734, 1915, 'She’d a roasted his bowels out of him ’thout any more feeling than if he was a human!”', '她会毫不留情地把它烤焦，一点都不会心疼，就好像它不是活物一样！”'),
    (12, 735, 1916, 'Aunt Polly felt a sudden pang of remorse.', '波莉姨妈突然觉得很后悔。'),
    (12, 735, 1917, 'This was putting the thing in a new light; what was cruelty to a cat _might_ be cruelty to a boy, too.', '这件事让她有了新的想法；虐待猫咪，也许也算是虐待小男孩吧。'),
    (12, 735, 1918, 'She began to soften; she felt sorry.', '她开始心软了；她感到很抱歉。'),
    (12, 735, 1919, 'Her eyes watered a little, and she put her hand on Tom’s head and said gently:', '她的眼睛有点湿润了，她把手放在汤姆的头上，温柔地说：'),
    (12, 736, 1920, '“I was meaning for the best, Tom.', '“我是为了你好，汤姆。'),
    (12, 736, 1921, 'And, Tom, it _did_ do you good.”', '而且，汤姆，那对你真的有好处。'),
    (12, 737, 1922, 'Tom looked up in her face with just a perceptible twinkle peeping through his gravity.', '汤姆抬头看着她的脸。他虽然很认真，但眼睛里还是藏着一点点小顽皮。'),
    (12, 738, 1923, '“I know you was meaning for the best, aunty, and so was I with Peter.', '“阿姨，我知道你是为我好，我对彼得也是这样想的。'),
    (12, 738, 1924, 'It done _him_ good, too.', '那对他也有好处呢。'),
    (12, 738, 1925, 'I never see him get around so since—”', '我从没见过他这么开心，自从——”'),
    (12, 739, 1926, '“Oh, go ’long with you, Tom, before you aggravate me again.', '“哎呀，汤姆，快走开，别再惹我生气了。'),
    (12, 739, 1927, 'And you try and see if you can’t be a good boy, for once, and you needn’t take any more medicine.”', '你试着乖一次，这样就不用再吃药了。”'),
    (12, 740, 1928, 'Tom reached school ahead of time.', '汤姆早早就到了学校。'),
    (12, 740, 1929, 'It was noticed that this strange thing had been occurring every day latterly.', '大家发现，最近他每天都这样，真奇怪。'),
    (12, 740, 1930, 'And now, as usual of late, he hung about the gate of the schoolyard instead of playing with his comrades.', '现在，和最近一样，他没跟小朋友们玩，而是站在学校门口。'),
    (12, 740, 1931, 'He was sick, he said, and he looked it.', '他说他生病了，看起来也真的不舒服。'),
    (12, 740, 1932, 'He tried to seem to be looking everywhere but whither he really was looking—down the road.', '他假装看别的地方，其实眼睛一直盯着路那边。'),
    (12, 740, 1933, 'Presently Jeff Thatcher hove in sight, and Tom’s face lighted; he gazed a moment, and then turned sorrowfully away.', '很快，杰夫撒切尔出现了，汤姆的脸一下子亮了；他看了一会儿，又伤心地转过头。'),
    (12, 740, 1934, 'When Jeff arrived, Tom accosted him; and “led up” warily to opportunities for remark about Becky, but the giddy lad never could see the bait.', '杰夫来了，汤姆走过去跟他说话。她想偷偷问问关于贝琪的事，可那个傻乎乎的男孩根本没明白。'),
    (12, 740, 1935, 'Tom watched and watched, hoping whenever a frisking frock came in sight, and hating the owner of it as soon as he saw she was not the right one.', '汤姆一直看着，只要看到有小裙子出现，就希望能是她。但一发现不是，他就又不喜欢那个人了。'),
    (12, 740, 1936, 'At last frocks ceased to appear, and he dropped hopelessly into the dumps; he entered the empty schoolhouse and sat down to suffer.', '最后，再也没看到小裙子了。他很伤心，一点力气都没有了。他走进空空的教室，坐下来，感觉好难受。'),
    (12, 740, 1937, 'Then one more frock passed in at the gate, and Tom’s heart gave a great bound.', '就在这时，又一件小裙子从门口进来了，汤姆的心一下子跳得好快。'),
    (12, 740, 1938, 'The next instant he was out, and “going on” like an Indian; yelling, laughing, chasing boys, jumping over the fence at risk of life and limb, throwing handsprings, standing on his head—doing all the heroic things he could conceive of, and keeping a furtive eye out, all the while, to see if Becky Thatcher was noticing.', '下一秒，他就冲了出去，像个印第安人一样“疯”起来！他大喊大叫，哈哈大笑，追着小男孩跑，还冒着危险跳过围栏，又翻跟头，又倒立——做了所有他觉得很酷的事情。不过，他一直偷偷地看，看贝琪·撒切尔有没有注意到他。'),
    (12, 740, 1939, 'But she seemed to be unconscious of it all; she never looked.', '可是，她好像什么都不知道，一眼都没看他。'),
    (12, 740, 1940, 'Could it be possible that she was not aware that he was there?', '难道她不知道他在这里吗？'),
    (12, 740, 1941, 'He carried his exploits to her immediate vicinity; came war-whooping around, snatched a boy’s cap, hurled it to the roof of the schoolhouse, broke through a group of boys, tumbling them in every direction, and fell sprawling, himself, under Becky’s nose, almost upsetting her—and she turned, with her nose in the air, and he heard her say: “Mf! some people think they’re mighty smart—always showing off!”', '他把自己的“表演”弄到了她旁边；他大叫着跑过来，抢了一个小男孩的帽子，扔到学校屋顶上。他又冲进一群男孩里，把他们都撞倒了，自己也摔倒在贝琪的鼻子前面，差点撞到她。她转过身，抬着头，鼻子翘得高高的，他听到她说：“哼！有些人觉得自己可厉害了——老是喜欢表现！”'),
    (12, 741, 1942, 'Tom’s cheeks burned.', '汤姆的脸一下子红了。'),
    (12, 741, 1943, 'He gathered himself up and sneaked off, crushed and crestfallen.', '他站起来，偷偷地走了，心里又难过又失望。'),
    (13, 742, 1944, 'Tom’s mind was made up now.', '汤姆现在决定了。'),
    (13, 742, 1945, 'He was gloomy and desperate.', '他很沮丧，心里也很绝望。'),
    (13, 742, 1946, 'He was a forsaken, friendless boy, he said; nobody loved him; when they found out what they had driven him to, perhaps they would be sorry; he had tried to do right and get along, but they would not let him; since nothing would do them but to be rid of him, let it be so; and let them blame _him_ for the consequences—why shouldn’t they?', '他说他是个被大家抛弃、没有朋友的小男孩；没有人喜欢他。等他们知道把他逼成什么样了，也许会后悔吧。他努力想做好孩子，好好跟人相处，可他们不让他这样。既然他们只想赶走他，那就随他们吧。让他们怪他做错事好了——为什么不呢？'),
    (13, 742, 1947, 'What right had the friendless to complain?', '没有朋友的人，有什么好抱怨的呢？'),
    (13, 742, 1948, 'Yes, they had forced him to it at last: he would lead a life of crime.', '是啊，他们最后还是把他逼到了这一步：他要去做坏事了。'),
    (13, 742, 1949, 'There was no choice.', '没办法了。'),
    (13, 743, 1950, 'By this time he was far down Meadow Lane, and the bell for school to “take up” tinkled faintly upon his ear.', '这时候，他已经走到草地巷很远的地方了。上课的铃声，轻轻地传到他的耳朵里。'),
    (13, 743, 1951, 'He sobbed, now, to think he should never, never hear that old familiar sound any more—it was very hard, but it was forced on him; since he was driven out into the cold world, he must submit—but he forgave them.', '他哭着想，再也听不到那个熟悉的声音了。这太难了，但他没办法。他被赶了出来，只能认命。不过，他还是原谅了他们。'),
    (13, 743, 1952, 'Then the sobs came thick and fast.', '他哭得更厉害了，一声接一声。'),
    (13, 744, 1953, 'Just at this point he met his soul’s sworn comrade, Joe Harper—hard-eyed, and with evidently a great and dismal purpose in his heart.', '就在这时，他遇到了最好的朋友 乔·哈珀。乔·哈珀 眼神亮亮的，心里好像藏着一个大大的、有点伤心的计划。'),
    (13, 744, 1954, 'Plainly here were “two souls with but a single thought.”', '看来他们两个人的想法一样。'),
    (13, 744, 1955, 'Tom, wiping his eyes with his sleeve, began to blubber out something about a resolution to escape from hard usage and lack of sympathy at home by roaming abroad into the great world never to return; and ended by hoping that Joe would not forget him.', '汤姆 用袖子擦着眼睛，哭着说他决定要离家出走。因为家里对他不好，也没人关心他。他要去外面的大世界闯荡，再也不回来了。最后，他希望乔不要忘记他。'),
    (13, 745, 1956, 'But it transpired that this was a request which Joe had just been going to make of Tom, and had come to hunt him up for that purpose.', '但原来，乔也正想对 汤姆 说同样的话。他就是来找 汤姆 说这件事的。'),
    (13, 745, 1957, 'His mother had whipped him for drinking some cream which he had never tasted and knew nothing about; it was plain that she was tired of him and wished him to go; if she felt that way, there was nothing for him to do but succumb; he hoped she would be happy, and never regret having driven her poor boy out into the unfeeling world to suffer and die.', '他妈妈打了他，因为他喝了奶油。可他根本没喝过，也不知道这回事。看来妈妈是烦他了，想让他走。既然她这样想，他只能认命了。他希望妈妈会开心，永远不要后悔把她可怜的孩子赶出去受苦。'),
    (13, 746, 1958, 'As the two boys walked sorrowing along, they made a new compact to stand by each other and be brothers and never separate till death relieved them of their troubles.', '两个小男孩伤心地走着，他们定了一个新约定。他们要互相帮助，像亲兄弟一样，永远不分开，直到他们的烦恼都消失。'),
    (13, 746, 1959, 'Then they began to lay their plans.', '然后他们开始商量计划。'),
    (13, 746, 1960, 'Joe was for being a hermit, and living on crusts in a remote cave, and dying, some time, of cold and want and grief; but after listening to Tom, he conceded that there were some conspicuous advantages about a life of crime, and so he consented to be a pirate.', '乔想当一个隐士，住在很远的洞穴里，吃着硬面包，最后因为又冷又饿又伤心而死掉。但听了 汤姆 的话后，他觉得当坏蛋也有很多好处。所以他同意当一个海盗。'),
    (13, 747, 1961, 'Three miles below St. Petersburg, at a point where the Mississippi River was a trifle over a mile wide, there was a long, narrow, wooded island, with a shallow bar at the head of it, and this offered well as a rendezvous.', '离 圣彼得斯堡 三英里远，在 密西西比 河宽一点点超过一英里的地方，有一个又长又窄、长满了树的小岛。岛的一头有片很浅的沙滩。这个地方很适合作为他们的碰头地点。'),
    (13, 747, 1962, 'It was not inhabited; it lay far over toward the further shore, abreast a dense and almost wholly unpeopled forest.', '岛上没有人住。它靠近河的对岸，对岸是一片茂密、几乎没人住的森林。'),
    (13, 747, 1963, 'So Jackson’s Island was chosen.', '所以，他们就选了杰克逊岛。'),
    (13, 747, 1964, 'Who were to be the subjects of their piracies was a matter that did not occur to them.', '至于他们要去打劫谁，他们根本没想过这个问题。'),
    (13, 747, 1965, 'Then they hunted up Huckleberry Finn, and he joined them promptly, for all careers were one to him; he was indifferent.', '然后他们去找 哈克贝利·费恩，哈克贝利·费恩 立刻就加入了他们。因为对他来说，做什么都一样，他一点也不在乎。'),
    (13, 747, 1966, 'They presently separated to meet at a lonely spot on the river-bank two miles above the village at the favorite hour—which was midnight.', '他们分开了，约定在村子上面两英里远的一个河边小角落见面，在他们最喜欢的时间——半夜。'),
    (13, 747, 1967, 'There was a small log raft there which they meant to capture.', '那里有一个小小的木头筏子，他们想把它弄到手。'),
    (13, 747, 1968, 'Each would bring hooks and lines, and such provision as he could steal in the most dark and mysterious way—as became outlaws.', '每个人都要带上鱼钩和鱼线，还要用最神秘的方式，偷来一些吃的东西，就像那些亡命之徒一样。'),
    (13, 747, 1969, 'And before the afternoon was done, they had all managed to enjoy the sweet glory of spreading the fact that pretty soon the town would “hear something.”', '傍晚还没到，他们就开心地到处说，很快镇上就会“听到什么大消息了”。'),
    (13, 747, 1970, 'All who got this vague hint were cautioned to “be mum and wait.”', '那些听到一点点消息的人，都被提醒要“保密，等着看”。'),
    (13, 748, 1971, 'About midnight Tom arrived with a boiled ham and a few trifles, and stopped in a dense undergrowth on a small bluff overlooking the meeting-place.', '大概半夜的时候，汤姆 带着一个煮熟的火腿和一些小东西来了。他在一个小山坡上，一片茂密的灌木丛里停了下来，那里能看到他们约定的地方。'),
    (13, 748, 1972, 'It was starlight, and very still.', '天上都是星星，四周非常安静。'),
    (13, 748, 1973, 'The mighty river lay like an ocean at rest.', '宽阔的河水像睡着了的大海一样。'),
    (13, 748, 1974, 'Tom listened a moment, but no sound disturbed the quiet.', '汤姆 听了一会儿，没有声音打破这份安静。'),
    (13, 748, 1975, 'Then he gave a low, distinct whistle.', '然后他轻轻地、清楚地吹了一声口哨。'),
    (13, 748, 1976, 'It was answered from under the bluff.', '小山坡下面有人回应了他。'),
    (13, 748, 1977, 'Tom whistled twice more; these signals were answered in the same way.', '汤姆 又吹了两声口哨，对方也同样回应了他。'),
    (13, 748, 1978, 'Then a guarded voice said:', '然后，一个小心翼翼的声音说：'),
    (13, 749, 1979, '“Who goes there?”', '“谁在那里？”'),
    (13, 750, 1980, '“Tom Sawyer, the Black Avenger of the Spanish Main.', '“我是 汤姆·索亚，加勒比海的黑衣复仇者。”'),
    (13, 750, 1981, 'Name your names.”', '说出你们的名字。'),
    (13, 751, 1982, '“Huck Finn the Red-Handed, and Joe Harper the Terror of the Seas.”', '“哈克 红手芬恩，还有 乔·哈珀 海上大魔王。”'),
    (13, 751, 1983, 'Tom had furnished these titles, from his favorite literature.', '汤姆 从他最喜欢的故事书里，给他们起了这些名字。'),
    (13, 752, 1984, '“’Tis well.', '“好极了。'),
    (13, 752, 1985, 'Give the countersign.”', '说出暗号吧。”'),
    (13, 753, 1986, 'Two hoarse whispers delivered the same awful word simultaneously to the brooding night:', '两个沙哑的声音，同时在黑夜里悄悄说出了那个可怕的词：'),
    (13, 754, 1987, '“_Blood_!”', '“血！”'),
    (13, 755, 1988, 'Then Tom tumbled his ham over the bluff and let himself down after it, tearing both skin and clothes to some extent in the effort.', '然后 汤姆 把他的火腿推下悬崖，自己也跟着滑了下去，他把皮肤和衣服都蹭破了一些。'),
    (13, 755, 1989, 'There was an easy, comfortable path along the shore under the bluff, but it lacked the advantages of difficulty and danger so valued by a pirate.', '悬崖下面有条小路，走起来很方便，也很舒服。可是海盗们喜欢冒险，那条路一点也不难，也不危险。'),
    (13, 756, 1990, 'The Terror of the Seas had brought a side of bacon, and had about worn himself out with getting it there.', '海上大魔王带了一大块培根肉，为了把它弄过来，他都快累坏了。'),
    (13, 756, 1991, 'Finn the Red-Handed had stolen a skillet and a quantity of half-cured leaf tobacco, and had also brought a few corn-cobs to make pipes with.', '红手芬恩偷了一个平底锅和一些半干的烟叶，还带了几个玉米棒子做烟斗。'),
    (13, 756, 1992, 'But none of the pirates smoked or “chewed” but himself.', '不过，除了他自己，别的海盗都不抽烟，也不“嚼烟叶”。'),
    (13, 756, 1993, 'The Black Avenger of the Spanish Main said it would never do to start without some fire.', '加勒比海黑侠说，没有火可不行，没法开始。'),
    (13, 756, 1994, 'That was a wise thought; matches were hardly known there in that day.', '这个主意真聪明！那时候，火柴可不常见呢。'),
    (13, 756, 1995, 'They saw a fire smouldering upon a great raft a hundred yards above, and they went stealthily thither and helped themselves to a chunk.', '他们看到上面一百码远的大木筏上，有一堆火正在慢慢烧着。他们偷偷摸摸地走过去，拿了一块火炭。'),
    (13, 756, 1996, 'They made an imposing adventure of it, saying, “Hist!” every now and then, and suddenly halting with finger on lip; moving with hands on imaginary dagger-hilts; and giving orders in dismal whispers that if “the foe” stirred, to “let him have it to the hilt,” because “dead men tell no tales.”', '他们把这件事变成了一场很棒的冒险。他们时不时地“嘘！”一声，突然停下来，把手指放在嘴唇上；手放在想象中的匕首柄上；用低沉的耳语下命令说，如果“敌人”动了，就“捅他个透心凉”，因为“死人不会说话”。'),
    (13, 756, 1997, 'They knew well enough that the raftsmen were all down at the village laying in stores or having a spree, but still that was no excuse for their conducting this thing in an unpiratical way.', '他们很清楚，那些木筏工人都在村子里买东西或者玩乐呢。但是，这也不能成为他们不按海盗方式做事的理由。'),
    (13, 757, 1998, 'They shoved off, presently, Tom in command, Huck at the after oar and Joe at the forward.', '过了一会儿，他们把木筏推离岸边，汤姆 来指挥，哈克 在船尾划桨，乔在船头划桨。'),
    (13, 757, 1999, 'Tom stood amidships, gloomy-browed, and with folded arms, and gave his orders in a low, stern whisper:', '汤姆 站在船中间，皱着眉头，抱着手臂，用低沉、严肃的声音下命令：'),
    (13, 758, 2000, '“Luff, and bring her to the wind!”', '“迎风转向，把船头对着风！”'),
    (13, 759, 2001, '“Aye-aye, sir!”', '“遵命，长官！”'),
    (13, 760, 2002, '“Steady, steady-y-y-y!”', '“稳住，稳住-住-住-住！”'),
    (13, 761, 2003, '“Steady it is, sir!”', '“已经稳住了，长官！”'),
    (13, 762, 2004, '“Let her go off a point!”', '“让船偏离一点方向！”'),
    (13, 763, 2005, '“Point it is, sir!”', '“已经偏了，长官！”'),
    (13, 764, 2006, 'As the boys steadily and monotonously drove the raft toward mid-stream it was no doubt understood that these orders were given only for “style,” and were not intended to mean anything in particular.', '男孩们稳定又单调地把木筏划向河中央。大家肯定都明白，这些命令只是为了“耍酷”，并没有特别的意思。'),
    (13, 765, 2007, '“What sail’s she carrying?”', '“船上挂着什么帆？”'),
    (13, 766, 2008, '“Courses, tops’ls, and flying-jib, sir.”', '“主帆、上桅帆和飞前帆，长官。”'),
    (13, 767, 2009, '“Send the r’yals up!', '“把顶桅帆升起来！'),
    (13, 767, 2010, 'Lay out aloft, there, half a dozen of ye—foretopmaststuns’l!', '上去几个人——挂前顶桅副帆！”'),
    (13, 767, 2011, 'Lively, now!”', '大家动起来！'),
    (13, 768, 2012, '“Aye-aye, sir!”', '“是，长官！”'),
    (13, 769, 2013, '“Shake out that maintogalans’l!', '“把主桅顶帆张开！'),
    (13, 769, 2014, 'Sheets and braces!', '拉好帆索！'),
    (13, 769, 2015, '_now_ my hearties!”', '现在，伙计们！”'),
    (13, 770, 2016, '“Aye-aye, sir!”', '“是，长官！”'),
    (13, 771, 2017, '“Hellum-a-lee—hard a port!', '“船舵向左，打到底！'),
    (13, 771, 2018, 'Stand by to meet her when she comes!', '准备好，等船转过来！'),
    (13, 771, 2019, 'Port, port!', '左边，左边！'),
    (13, 771, 2020, '_Now_, men!', '现在，伙计们！'),
    (13, 771, 2021, 'With a will!', '要快，要用力！'),
    (13, 771, 2022, 'Stead-y-y-y!”', '稳住——！”'),
    (13, 772, 2023, '“Steady it is, sir!”', '“稳住了，长官！”'),
    (13, 773, 2024, 'The raft drew beyond the middle of the river; the boys pointed her head right, and then lay on their oars.', '木筏过了河中间；男孩们把筏头朝右边，然后就休息了，不划桨了。'),
    (13, 773, 2025, 'The river was not high, so there was not more than a two or three mile current.', '河水不深，所以水流不快，只有两三英里的速度。'),
    (13, 773, 2026, 'Hardly a word was said during the next three-quarters of an hour.', '接下来的四十五分钟里，他们几乎没说话。'),
    (13, 773, 2027, 'Now the raft was passing before the distant town.', '现在木筏正从远处的镇子前经过。'),
    (13, 773, 2028, 'Two or three glimmering lights showed where it lay, peacefully sleeping, beyond the vague vast sweep of star-gemmed water, unconscious of the tremendous event that was happening.', '只有两三点闪烁的灯光，表明那里是一个小镇，正在安静地睡觉。它不知道，在星光点点的广阔水面上，正发生着一件大事。'),
    (13, 773, 2029, 'The Black Avenger stood still with folded arms, “looking his last” upon the scene of his former joys and his later sufferings, and wishing “she” could see him now, abroad on the wild sea, facing peril and death with dauntless heart, going to his doom with a grim smile on his lips.', '黑侠客抱着胳膊，一动不动地站着，最后看了一眼他曾经开心和痛苦的地方。他多希望‘她’能看到他现在在大海上，勇敢面对危险和死亡，脸上带着坚定的笑容。'),
    (13, 773, 2030, 'It was but a small strain on his imagination to remove Jackson’s Island beyond eye-shot of the village, and so he “looked his last” with a broken and satisfied heart.', '他想象杰克逊岛已经离村子很远了，心里有点难过，又有点满意，这样就“最后看了一眼”。'),
    (13, 773, 2031, 'The other pirates were looking their last, too; and they all looked so long that they came near letting the current drift them out of the range of the island.', '其他的海盗也在最后看一眼。他们看了很久，差点就被水流带到离岛很远的地方去了。'),
    (13, 773, 2032, 'But they discovered the danger in time, and made shift to avert it.', '但他们很快发现了危险，并及时把它化解了。'),
    (13, 773, 2033, 'About two o’clock in the morning the raft grounded on the bar two hundred yards above the head of the island, and they waded back and forth until they had landed their freight.', '凌晨两点左右，木筏在小岛上游两百码处的一个沙滩上停住了。他们来回趟水，把所有的东西都搬到了岸上。'),
    (13, 773, 2034, 'Part of the little raft’s belongings consisted of an old sail, and this they spread over a nook in the bushes for a tent to shelter their provisions; but they themselves would sleep in the open air in good weather, as became outlaws.', '小木筏上有些东西，其中一块旧帆被他们铺在灌木丛里，搭成一个小帐篷，用来放食物。但他们自己，天气好的时候，就像野外的人一样，直接睡在外面。'),
    (13, 774, 2035, 'They built a fire against the side of a great log twenty or thirty steps within the sombre depths of the forest, and then cooked some bacon in the frying-pan for supper, and used up half of the corn “pone” stock they had brought.', '他们在森林深处，离一个大木头二三十步远的地方生了一堆火。然后用平底锅煎了些培根当晚餐，还吃掉了一半带来的玉米面包。'),
    (13, 774, 2036, 'It seemed glorious sport to be feasting in that wild, free way in the virgin forest of an unexplored and uninhabited island, far from the haunts of men, and they said they never would return to civilization.', '在这个没有人去过的岛上，原始森林里，离人群很远，这样自由自在地大吃一顿，真是太好玩了！他们说再也不回城市生活了。'),
    (13, 774, 2037, 'The climbing fire lit up their faces and threw its ruddy glare upon the pillared tree-trunks of their forest temple, and upon the varnished foliage and festooning vines.', '跳动的火光照亮了他们的脸。火光还把红色的光芒投向了森林里那些像柱子一样高大的树干上，也照亮了闪亮的树叶和垂下来的藤蔓。'),
    (13, 775, 2038, 'When the last crisp slice of bacon was gone, and the last allowance of corn pone devoured, the boys stretched themselves out on the grass, filled with contentment.', '最后一片脆培根和最后一块玉米饼都吃光后，男孩们心满意足地躺在草地上，伸了个懒腰。'),
    (13, 775, 2039, 'They could have found a cooler place, but they would not deny themselves such a romantic feature as the roasting campfire.', '他们本来可以找一个更凉快的地方，但他们不想错过围着篝火取暖这种浪漫的感觉。'),
    (13, 776, 2040, '“_Ain’t_ it gay?” said Joe.', '“是不是很棒？”乔说。'),
    (13, 777, 2041, '“It’s _nuts_!” said Tom. “What would the boys say if they could see us?”', '“这太棒了！”汤姆说。“要是男孩们看到我们，他们会说什么呢？”'),
    (13, 778, 2042, '“Say?', '“说什么？'),
    (13, 778, 2043, 'Well, they’d just die to be here—hey, Hucky!”', '他们肯定会特别想来这儿——嘿，哈克！”'),
    (13, 779, 2044, '“I reckon so,” said Huckleberry; “anyways, I’m suited.', '“我想也是。”哈克贝利说；“反正，我很满意。'),
    (13, 779, 2045, 'I don’t want nothing better’n this.', '我觉得现在这样最好了。'),
    (13, 779, 2046, 'I don’t ever get enough to eat, gen’ally—and here they can’t come and pick at a feller and bullyrag him so.”', '我平时总吃不饱——在这儿，没人能来挑剔我，欺负我了。”'),
    (13, 780, 2047, '“It’s just the life for me,” said Tom.', '“这正是我想要的生活，”汤姆说。'),
    (13, 780, 2048, '“You don’t have to get up, mornings, and you don’t have to go to school, and wash, and all that blame foolishness.', '“你不用早上起床，也不用去上学，不用洗漱，那些烦人的事儿都不用做。'),
    (13, 780, 2049, 'You see a pirate don’t have to do _anything_, Joe, when he’s ashore, but a hermit _he_ has to be praying considerable, and then he don’t have any fun, anyway, all by himself that way.”', '你看，乔，海盗上岸后什么都不用做，但是隐士呢，他得不停地祷告，而且一个人在那儿，一点儿也不好玩。”'),
    (13, 781, 2050, '“Oh yes, that’s so,” said Joe, “but I hadn’t thought much about it, you know.', '“哦，对，是这样。”乔说，“不过我之前没怎么想过这事儿，你知道的。'),
    (13, 781, 2051, 'I’d a good deal rather be a pirate, now that I’ve tried it.”', '既然我都试过了，我现在宁愿当个海盗。”'),
    (13, 782, 2052, '“You see,” said Tom, “people don’t go much on hermits, nowadays, like they used to in old times, but a pirate’s always respected.', '“你看，”汤姆说，“像以前那样，现在的人不怎么喜欢隐士了，但是海盗总是受人尊敬的。'),
    (13, 782, 2053, 'And a hermit’s got to sleep on the hardest place he can find, and put sackcloth and ashes on his head, and stand out in the rain, and—”', '而且隐士还得睡在能找到的最硬的地方，把粗麻布和灰尘放在头上，还要站在雨里，然后——”'),
    (13, 783, 2054, '“What does he put sackcloth and ashes on his head for?” inquired Huck.', '“他为什么要戴粗麻布和灰尘在头上？”哈克问。'),
    (13, 784, 2055, '“I dono.', '“我不知道。'),
    (13, 784, 2056, 'But they’ve _got_ to do it.', '但他们就是必须这么做。'),
    (13, 784, 2057, 'Hermits always do.', '隐士总是这样。'),
    (13, 784, 2058, 'You’d have to do that if you was a hermit.”', '如果你是隐士，你也得这么做。”'),
    (13, 785, 2059, '“Dern’d if I would,” said Huck.', '“我才不呢！”哈克说。'),
    (13, 786, 2060, '“Well, what would you do?”', '“那，你会怎么做呢？”'),
    (13, 787, 2061, '“I dono.', '“我不知道。'),
    (13, 787, 2062, 'But I wouldn’t do that.”', '但我不会那么做。”'),
    (13, 788, 2063, '“Why, Huck, you’d _have_ to.', '“哎呀，哈克，你必须这么做啊。'),
    (13, 788, 2064, 'How’d you get around it?”', '你怎么能躲开呢？”'),
    (13, 789, 2065, '“Why, I just wouldn’t stand it.', '“哼，我才不受那份罪呢。'),
    (13, 789, 2066, 'I’d run away.”', '我会跑掉的。”'),
    (13, 790, 2067, '“Run away!', '“跑掉！'),
    (13, 790, 2068, 'Well, you _would_ be a nice old slouch of a hermit.', '哼，那你可就不是个合格的隐士了。'),
    (13, 790, 2069, 'You’d be a disgrace.”', '你会让人瞧不起的。”'),
    (13, 791, 2070, 'The Red-Handed made no response, being better employed.', '“红手”没有回答，他正忙着更重要的事。'),
    (13, 791, 2071, 'He had finished gouging out a cob, and now he fitted a weed stem to it, loaded it with tobacco, and was pressing a coal to the charge and blowing a cloud of fragrant smoke—he was in the full bloom of luxurious contentment.', '他做好了烟斗，装上烟草。他点着烟，喷出香喷喷的烟雾。他非常非常开心。'),
    (13, 791, 2072, 'The other pirates envied him this majestic vice, and secretly resolved to acquire it shortly.', '其他海盗好羡慕他这样。他们都偷偷决定，很快也要学会抽烟。'),
    (13, 791, 2073, 'Presently Huck said:', '过了一会儿，哈克说：'),
    (13, 792, 2074, '“What does pirates have to do?”', '“海盗都要做什么呀？”'),
    (13, 793, 2075, 'Tom said:', '汤姆说：'),
    (13, 794, 2076, '“Oh, they have just a bully time—take ships and burn them, and get the money and bury it in awful places in their island where there’s ghosts and things to watch it, and kill everybody in the ships—make ’em walk a plank.”', '“哦，他们可开心了！他们抢船，把船烧掉。他们拿走钱，埋在岛上可怕的地方。那里有鬼看着钱。他们还会杀死船上所有的人，让他们走跳板。”'),
    (13, 795, 2077, '“And they carry the women to the island,” said Joe; “they don’t kill the women.”', '“他们还会把女人带到岛上，”乔说，“他们不杀女人。”'),
    (13, 796, 2078, '“No,” assented Tom, “they don’t kill the women—they’re too noble.', '“对，”汤姆同意说，“他们不杀女人。他们太善良了。'),
    (13, 796, 2079, 'And the women’s always beautiful, too.”', '而且女人都特别漂亮。”'),
    (13, 797, 2080, '“And don’t they wear the bulliest clothes!', '“他们穿的衣服可真棒！'),
    (13, 797, 2081, 'Oh no!', '哦，不是！'),
    (13, 797, 2082, 'All gold and silver and di’monds,” said Joe, with enthusiasm.', '都是金子、银子和钻石！”乔很兴奋地说。'),
    (13, 798, 2083, '“Who?” said Huck.', '“谁？”哈克问。'),
    (13, 799, 2084, '“Why, the pirates.”', '“就是海盗啊。”'),
    (13, 800, 2085, 'Huck scanned his own clothing forlornly.', '哈克伤心地看了看自己的衣服。'),
    (13, 801, 2086, '“I reckon I ain’t dressed fitten for a pirate,” said he, with a regretful pathos in his voice; “but I ain’t got none but these.”', '“我想我这身衣服不像海盗穿的，”他有点难过地说，“可是我只有这些衣服了。”'),
    (13, 802, 2087, 'But the other boys told him the fine clothes would come fast enough, after they should have begun their adventures.', '但其他男孩告诉他，等他们开始冒险后，很快就会有好看的衣服了。'),
    (13, 802, 2088, 'They made him understand that his poor rags would do to begin with, though it was customary for wealthy pirates to start with a proper wardrobe.', '他们让他明白，虽然有钱的海盗一开始就有漂亮的衣服，但他这些破烂衣服也够用了。'),
    (13, 803, 2089, 'Gradually their talk died out and drowsiness began to steal upon the eyelids of the little waifs.', '他们的话渐渐少了，困意慢慢爬上了这些小流浪儿的眼皮。'),
    (13, 803, 2090, 'The pipe dropped from the fingers of the Red-Handed, and he slept the sleep of the conscience-free and the weary.', '烟斗从“红手”的手里滑落，他睡着了。他睡得又安心又累。'),
    (13, 803, 2091, 'The Terror of the Seas and the Black Avenger of the Spanish Main had more difficulty in getting to sleep.', '“海上恶魔”和“西班牙海的黑色复仇者”更难入睡。'),
    (13, 803, 2092, 'They said their prayers inwardly, and lying down, since there was nobody there with authority to make them kneel and recite aloud; in truth, they had a mind not to say them at all, but they were afraid to proceed to such lengths as that, lest they might call down a sudden and special thunderbolt from heaven.', '他们躺着默默地祈祷。因为没人让他们跪着大声念。其实他们不想祈祷，但又怕不说的话，老天爷会突然打雷劈他们。'),
    (13, 803, 2093, 'Then at once they reached and hovered upon the imminent verge of sleep—but an intruder came, now, that would not “down.”', '他们快要睡着了，但一个东西突然出现了，怎么也赶不走。'),
    (13, 803, 2094, 'It was conscience.', '那是他们的良心。'),
    (13, 803, 2095, 'They began to feel a vague fear that they had been doing wrong to run away; and next they thought of the stolen meat, and then the real torture came.', '他们开始有点害怕，觉得跑出来是不对的。接着他们想起了偷来的肉，真正的痛苦就来了。'),
    (13, 803, 2096, 'They tried to argue it away by reminding conscience that they had purloined sweetmeats and apples scores of times; but conscience was not to be appeased by such thin plausibilities; it seemed to them, in the end, that there was no getting around the stubborn fact that taking sweetmeats was only “hooking,” while taking bacon and hams and such valuables was plain simple stealing—and there was a command against that in the Bible.', '他们想对良心说，他们以前偷过很多次糖果和苹果。但良心不听他们的话。他们觉得，偷糖果只是“拿”，而偷培根、火腿这些贵重东西就是“偷”。圣经里说了不能偷东西。'),
    (13, 803, 2097, 'So they inwardly resolved that so long as they remained in the business, their piracies should not again be sullied with the crime of stealing.', '所以他们心里决定，只要他们还做海盗，就再也不偷东西了。'),
    (13, 803, 2098, 'Then conscience granted a truce, and these curiously inconsistent pirates fell peacefully to sleep.', '这时，良心终于放过了他们，这两个有点奇怪的海盗就安心地睡着了。'),
    (14, 804, 2099, 'When Tom awoke in the morning, he wondered where he was.', '早上汤姆醒来时，他想：这是哪里呀？'),
    (14, 804, 2100, 'He sat up and rubbed his eyes and looked around.', '他坐起来，揉揉眼睛，看了看四周。'),
    (14, 804, 2101, 'Then he comprehended.', '然后，他明白了。'),
    (14, 804, 2102, 'It was the cool gray dawn, and there was a delicious sense of repose and peace in the deep pervading calm and silence of the woods.', '天亮了，凉凉的，有点灰。森林里很安静，让他觉得很舒服、很平静。'),
    (14, 804, 2103, 'Not a leaf stirred; not a sound obtruded upon great Nature’s meditation.', '一片叶子都没动，没有一点声音打扰大自然。'),
    (14, 804, 2104, 'Beaded dewdrops stood upon the leaves and grasses.', '晶莹的露珠挂在叶子和草上。'),
    (14, 804, 2105, 'A white layer of ashes covered the fire, and a thin blue breath of smoke rose straight into the air.', '火上盖了一层白白的灰，一缕细细的蓝色烟雾笔直地飘向天空。'),
    (14, 804, 2106, 'Joe and Huck still slept.', '乔和 哈克 还在睡觉。'),
    (14, 805, 2107, 'Now, far away in the woods a bird called; another answered; presently the hammering of a woodpecker was heard.', '这时，森林深处一只鸟叫了一声，另一只回应了。很快，又听到了啄木鸟敲打树干的声音。'),
    (14, 805, 2108, 'Gradually the cool dim gray of the morning whitened, and as gradually sounds multiplied and life manifested itself.', '凉凉的灰色清晨慢慢变亮了，声音越来越多，万物都活了过来。'),
    (14, 805, 2109, 'The marvel of Nature shaking off sleep and going to work unfolded itself to the musing boy.', '大自然从睡梦中醒来，开始活动了，男孩看着，觉得很神奇。'),
    (14, 805, 2110, 'A little green worm came crawling over a dewy leaf, lifting two-thirds of his body into the air from time to time and “sniffing around,” then proceeding again—for he was measuring, Tom said; and when the worm approached him, of its own accord, he sat as still as a stone, with his hopes rising and falling, by turns, as the creature still came toward him or seemed inclined to go elsewhere; and when at last it considered a painful moment with its curved body in the air and then came decisively down upon Tom’s leg and began a journey over him, his whole heart was glad—for that meant that he was going to have a new suit of clothes—without the shadow of a doubt a gaudy piratical uniform.', '一条绿色的小虫子爬过一片带露水的叶子。它时不时抬起身体，好像在“闻来闻去”，然后又继续爬。汤姆说，它在量尺寸呢。当小虫子自己爬向他时，他像石头一样一动不动。小虫子有时朝他爬来，有时又好像要爬去别的地方，他的心情也一会儿高兴，一会儿紧张。最后，小虫子弯着身子在空中想了一会儿，然后坚定地爬到了 汤姆 的腿上，开始在他身上旅行。他心里可高兴了——因为这意味着他会有一套新衣服，肯定是一套很帅的海盗服！'),
    (14, 805, 2111, 'Now a procession of ants appeared, from nowhere in particular, and went about their labors; one struggled manfully by with a dead spider five times as big as itself in its arms, and lugged it straight up a tree-trunk.', '这时，一队蚂蚁不知道从哪里冒出来，开始干活了。有一只蚂蚁抱着一只比自己大五倍的死蜘蛛，很用力地把它拖上树干。'),
    (14, 805, 2112, 'A brown spotted lady-bug climbed the dizzy height of a grass blade, and Tom bent down close to it and said, “Lady-bug, lady-bug, fly away home, your house is on fire, your children’s alone,” and she took wing and went off to see about it—which did not surprise the boy, for he knew of old that this insect was credulous about conflagrations, and he had practised upon its simplicity more than once.', '一只棕色斑点的瓢虫爬到高高的草叶上。汤姆 弯下身子，凑近它说：“瓢虫瓢虫飞回家，你的房子着火了，你的孩子孤单了。” 瓢虫真的飞走了，去看个究竟。男孩一点也不惊讶，因为他早就知道这种小虫子很容易相信着火的事，他以前就用这招骗过它好几次了。'),
    (14, 805, 2113, 'A tumblebug came next, heaving sturdily at its ball, and Tom touched the creature, to see it shut its legs against its body and pretend to be dead.', '接着，一只屎壳郎来了，它很用力地推着它的粪球。汤姆 碰了碰它，它就把腿缩起来，假装死了。'),
    (14, 805, 2114, 'The birds were fairly rioting by this time.', '这时，鸟儿们已经叽叽喳喳地叫个不停了。'),
    (14, 805, 2115, 'A catbird, the Northern mocker, lit in a tree over Tom’s head, and trilled out her imitations of her neighbors in a rapture of enjoyment; then a shrill jay swept down, a flash of blue flame, and stopped on a twig almost within the boy’s reach, cocked his head to one side and eyed the strangers with a consuming curiosity; a gray squirrel and a big fellow of the “fox” kind came skurrying along, sitting up at intervals to inspect and chatter at the boys, for the wild things had probably never seen a human being before and scarcely knew whether to be afraid or not.', '一只反舌鸟（它会学别的鸟叫）飞到 汤姆 头顶的树上，高兴地学着邻居们的叫声，唱起歌来。接着，一只蓝色的松鸦像一道蓝光一样飞下来，停在男孩几乎能碰到的树枝上。它歪着头，好奇地看着这些陌生人。一只灰松鼠和一只像狐狸一样的大动物跑了过来，时不时停下来，看看男孩们，还吱吱喳喳地叫。这些小动物可能从来没见过人，都不知道该害怕还是不害怕呢。'),
    (14, 805, 2116, 'All Nature was wide awake and stirring, now; long lances of sunlight pierced down through the dense foliage far and near, and a few butterflies came fluttering upon the scene.', '这时，大自然的所有生物都醒了，都动起来了。远近的阳光像长矛一样，穿过茂密的树叶照下来。几只蝴蝶飞舞着出现了。'),
    (14, 806, 2117, 'Tom stirred up the other pirates and they all clattered away with a shout, and in a minute or two were stripped and chasing after and tumbling over each other in the shallow limpid water of the white sandbar.', '汤姆 叫醒了其他的小海盗们，他们大叫一声跑开了。一两分钟后，他们就脱光了衣服，在白色沙洲上清澈的浅水里互相追逐打闹。'),
    (14, 806, 2118, 'They felt no longing for the little village sleeping in the distance beyond the majestic waste of water.', '他们一点也不想念远处那片宽广水面后，正在睡觉的小村庄。'),
    (14, 806, 2119, 'A vagrant current or a slight rise in the river had carried off their raft, but this only gratified them, since its going was something like burning the bridge between them and civilization.', '不知道是河水变急了，还是水位升高了，把他们的木筏冲走了。但他们却很高兴，因为木筏冲走了，就像烧掉了他们和文明世界的桥梁一样。'),
    (14, 807, 2120, 'They came back to camp wonderfully refreshed, glad-hearted, and ravenous; and they soon had the camp-fire blazing up again.', '他们回到营地，感觉舒服极了，心里很高兴，肚子也饿扁了。很快，他们又让篝火熊熊燃烧起来。'),
    (14, 807, 2121, 'Huck found a spring of clear cold water close by, and the boys made cups of broad oak or hickory leaves, and felt that water, sweetened with such a wildwood charm as that, would be a good enough substitute for coffee.', '哈克 在附近找到了一股清澈冰凉的山泉水。男孩们用宽大的橡树叶或山核桃叶做了杯子。他们觉得，有这样特别的野外风味，这水喝起来比咖啡还要好喝。'),
    (14, 807, 2122, 'While Joe was slicing bacon for breakfast, Tom and Huck asked him to hold on a minute; they stepped to a promising nook in the river-bank and threw in their lines; almost immediately they had reward.', '乔正在切培根准备早餐时，汤姆 和 哈克 叫他等一下。他们走到河岸边一个看起来不错的小角落，把鱼线抛了下去。几乎立刻就有了收获。'),
    (14, 807, 2123, 'Joe had not had time to get impatient before they were back again with some handsome bass, a couple of sun-perch and a small catfish—provisions enough for quite a family.', '乔还没来得及不耐烦，他们就带着几条漂亮的鲈鱼、两条太阳鱼和一条小鲶鱼回来了——这些鱼足够一家人吃了。'),
    (14, 807, 2124, 'They fried the fish with the bacon, and were astonished; for no fish had ever seemed so delicious before.', '他们把鱼和培根一起煎，吃惊极了，因为从来没有鱼这么好吃过。'),
    (14, 807, 2125, 'They did not know that the quicker a fresh-water fish is on the fire after he is caught the better he is; and they reflected little upon what a sauce open-air sleeping, open-air exercise, bathing, and a large ingredient of hunger make, too.', '他们不知道，淡水鱼抓上来后越快煮就越好吃。他们也没想到，在野外睡觉、玩耍、洗澡，再加上肚子很饿，这些都是最好的调味料呢。'),
    (14, 808, 2126, 'They lay around in the shade, after breakfast, while Huck had a smoke, and then went off through the woods on an exploring expedition.', '早餐后，他们躺在树荫下休息了一会儿，然后就穿过森林去探险了。'),
    (14, 808, 2127, 'They tramped gayly along, over decaying logs, through tangled underbrush, among solemn monarchs of the forest, hung from their crowns to the ground with a drooping regalia of grape-vines.', '他们高兴地走着，跨过腐烂的木头，穿过缠绕在一起的灌木丛，走在森林里高大的老树中间，那些树上挂满了像藤蔓一样垂下来的葡萄。'),
    (14, 808, 2128, 'Now and then they came upon snug nooks carpeted with grass and jeweled with flowers.', '他们不时会遇到一些舒服的小角落，那里铺着草地，点缀着花朵。'),
    (14, 809, 2129, 'They found plenty of things to be delighted with, but nothing to be astonished at.', '他们发现了许多让他们高兴的东西，但没有让他们特别吃惊的东西。'),
    (14, 809, 2130, 'They discovered that the island was about three miles long and a quarter of a mile wide, and that the shore it lay closest to was only separated from it by a narrow channel hardly two hundred yards wide.', '他们发现这个岛大约有三英里长，四分之一英里宽。离岛最近的岸边，中间只隔着一条不到两百码宽的狭窄水道。'),
    (14, 809, 2131, 'They took a swim about every hour, so it was close upon the middle of the afternoon when they got back to camp.', '他们差不多每个小时都去游一次泳，所以快到下午才回到营地。'),
    (14, 809, 2132, 'They were too hungry to stop to fish, but they fared sumptuously upon cold ham, and then threw themselves down in the shade to talk.', '他们太饿了，没去钓鱼，而是大口吃着冷火腿，然后就躺在树荫下聊天。'),
    (14, 809, 2133, 'But the talk soon began to drag, and then died.', '可是，他们很快就聊不下去了，变得很安静。'),
    (14, 809, 2134, 'The stillness, the solemnity that brooded in the woods, and the sense of loneliness, began to tell upon the spirits of the boys.', '树林里很安静，感觉很严肃，也很孤独，这些让小男孩们的心情变差了。'),
    (14, 809, 2135, 'They fell to thinking.', '他们开始想事情。'),
    (14, 809, 2136, 'A sort of undefined longing crept upon them.', '他们心里慢慢生出一种说不清的思念。'),
    (14, 809, 2137, 'This took dim shape, presently—it was budding homesickness.', '很快，这种感觉变得有点清楚了——原来是想家了。'),
    (14, 809, 2138, 'Even Finn the Red-Handed was dreaming of his doorsteps and empty hogsheads.', '连红手芬恩都开始想念他家的台阶和空木桶了。'),
    (14, 809, 2139, 'But they were all ashamed of their weakness, and none was brave enough to speak his thought.', '可是，他们都觉得想家是件很弱的事，没有人敢说出自己心里的想法。'),
    (14, 810, 2140, 'For some time, now, the boys had been dully conscious of a peculiar sound in the distance, just as one sometimes is of the ticking of a clock which he takes no distinct note of.', '有段时间了，小男孩们隐约觉得远处有奇怪的声音，就像平时听到时钟“嘀嗒”响，却没特别注意一样。'),
    (14, 810, 2141, 'But now this mysterious sound became more pronounced, and forced a recognition.', '但现在，这个奇怪的声音更响了，让他们不得不去听清楚。'),
    (14, 810, 2142, 'The boys started, glanced at each other, and then each assumed a listening attitude.', '小男孩们吓了一跳，互相看了看，然后都竖起耳朵仔细听。'),
    (14, 810, 2143, 'There was a long silence, profound and unbroken; then a deep, sullen boom came floating down out of the distance.', '接着是很长时间的安静，很深很沉。然后，远处传来一声低沉、闷闷的“轰”声。'),
    (14, 811, 2144, '“What is it!” exclaimed Joe, under his breath.', '“那是什么？”乔小声地喊道。'),
    (14, 812, 2145, '“I wonder,” said Tom in a whisper.', '“我想知道，”汤姆小声地说。'),
    (14, 813, 2146, '“’Tain’t thunder,” said Huckleberry, in an awed tone, “becuz thunder—”', '“这不是打雷，”哈克贝利敬畏地说，“因为打雷的话——”'),
    (14, 814, 2147, '“Hark!” said Tom. “Listen—don’t talk.”', '“听！”汤姆说，“仔细听——别说话。”'),
    (14, 815, 2148, 'They waited a time that seemed an age, and then the same muffled boom troubled the solemn hush.', '他们等了好久，感觉像等了一辈子。然后，那一声闷响又打破了安静。'),
    (14, 816, 2149, '“Let’s go and see.”', '“我们去看看吧。”'),
    (14, 817, 2150, 'They sprang to their feet and hurried to the shore toward the town.', '他们跳起来，快步跑到岸边，朝小镇那边走。'),
    (14, 817, 2151, 'They parted the bushes on the bank and peered out over the water.', '他们拨开岸边的树丛，朝水面上看。'),
    (14, 817, 2152, 'The little steam ferry-boat was about a mile below the village, drifting with the current.', '那艘小小的蒸汽渡船，在村子下面一英里左右的地方，正跟着水流漂。'),
    (14, 817, 2153, 'Her broad deck seemed crowded with people.', '船上宽宽的甲板上，好像挤满了人。'),
    (14, 817, 2154, 'There were a great many skiffs rowing about or floating with the stream in the neighborhood of the ferryboat, but the boys could not determine what the men in them were doing.', '渡船周围有很多小船，有的在划，有的跟着水漂。但小男孩们看不清船上的人在做什么。'),
    (14, 817, 2155, 'Presently a great jet of white smoke burst from the ferryboat’s side, and as it expanded and rose in a lazy cloud, that same dull throb of sound was borne to the listeners again.', '突然，渡船旁边冒出一大股白烟，它慢慢散开，变成一朵懒洋洋的云。接着，那闷闷的声音又传到了他们耳边。'),
    (14, 818, 2156, '“I know now!” exclaimed Tom; “somebody’s drownded!”', '“我现在知道了！”汤姆喊道，“有人掉到水里了！”'),
    (14, 819, 2157, '“That’s it!” said Huck; “they done that last summer, when Bill Turner got drownded; they shoot a cannon over the water, and that makes him come up to the top.', '“没错！”哈克说，“去年夏天比尔·特纳掉到水里时，他们就是这样做的。他们在水上开炮，那样他就会浮上来。'),
    (14, 819, 2158, 'Yes, and they take loaves of bread and put quicksilver in ’em and set ’em afloat, and wherever there’s anybody that’s drownded, they’ll float right there and stop.”', '是啊，他们还会拿面包，把水银放进去，再把面包放到水里。哪里有人掉到水里，面包就会漂到哪里停下来。”'),
    (14, 820, 2159, '“Yes, I’ve heard about that,” said Joe.', '“嗯，我听说过这事。”乔说。'),
    (14, 820, 2160, '“I wonder what makes the bread do that.”', '“我想知道面包为什么会那样。”'),
    (14, 821, 2161, '“Oh, it ain’t the bread, so much,” said Tom; “I reckon it’s mostly what they _say_ over it before they start it out.”', '“哦，重要的不是面包本身，”汤姆说，“我觉得主要是他们在使用面包前，对着它说了些什么。”'),
    (14, 822, 2162, '“But they don’t say anything over it,” said Huck.', '“可是他们什么也没说呀，”哈克说。'),
    (14, 822, 2163, '“I’ve seen ’em and they don’t.”', '“我看到过，他们没说。”'),
    (14, 823, 2164, '“Well, that’s funny,” said Tom.', '“嗯，真奇怪，”汤姆说。'),
    (14, 823, 2165, '“But maybe they say it to themselves.', '“也许他们是对自己说的吧。'),
    (14, 823, 2166, 'Of _course_ they do.', '当然是啦。'),
    (14, 823, 2167, 'Anybody might know that.”', '谁都知道的呀。”'),
    (14, 824, 2168, 'The other boys agreed that there was reason in what Tom said, because an ignorant lump of bread, uninstructed by an incantation, could not be expected to act very intelligently when set upon an errand of such gravity.', '其他的男孩都同意汤姆的话，因为一块没念过咒语的“笨面包”，在办这么重要的事情时，肯定不会很聪明。'),
    (14, 825, 2169, '“By jings, I wish I was over there, now,” said Joe.', '“天哪，我真希望现在就在那儿，”乔说。'),
    (14, 826, 2170, '“I do too,” said Huck.', '“我也是，”哈克说。'),
    (14, 826, 2171, '“I’d give heaps to know who it is.”', '“我真想知道那是谁。”'),
    (14, 827, 2172, 'The boys still listened and watched.', '男孩们继续听着，看着。'),
    (14, 827, 2173, 'Presently a revealing thought flashed through Tom’s mind, and he exclaimed:', '忽然，一个想法闪过汤姆的脑海，他大声喊道：'),
    (14, 828, 2174, '“Boys, I know who’s drownded—it’s us!”', '“伙计们，我知道谁淹死了——是我们！”'),
    (14, 829, 2175, 'They felt like heroes in an instant.', '他们立刻觉得自己像英雄一样。'),
    (14, 829, 2176, 'Here was a gorgeous triumph; they were missed; they were mourned; hearts were breaking on their account; tears were being shed; accusing memories of unkindness to these poor lost lads were rising up, and unavailing regrets and remorse were being indulged; and best of all, the departed were the talk of the whole town, and the envy of all the boys, as far as this dazzling notoriety was concerned.', '这真是一场了不起的胜利！大家都想念他们，为他们难过；好多人的心都碎了；眼泪哗哗地流；大家都在后悔对这些可怜的失踪男孩不够好；无尽的遗憾和悔恨也涌了上来；最棒的是，这些“死去”的男孩成了全镇的话题，所有男孩子都羡慕他们，因为他们太出名了。'),
    (14, 829, 2177, 'This was fine.', '这太棒了。'),
    (14, 829, 2178, 'It was worth while to be a pirate, after all.', '看来当海盗还是值得的。'),
    (14, 830, 2179, 'As twilight drew on, the ferryboat went back to her accustomed business and the skiffs disappeared.', '天色渐渐暗下来，渡船回到它平时工作的地方，小船也不见了。'),
    (14, 830, 2180, 'The pirates returned to camp.', '海盗们回到了营地。'),
    (14, 830, 2181, 'They were jubilant with vanity over their new grandeur and the illustrious trouble they were making.', '他们因为自己的“新身份”和制造的“大麻烦”而洋洋得意。'),
    (14, 830, 2182, 'They caught fish, cooked supper and ate it, and then fell to guessing at what the village was thinking and saying about them; and the pictures they drew of the public distress on their account were gratifying to look upon—from their point of view.', '他们抓了鱼，做了晚饭，吃完后就开始猜镇上的人会怎么说他们。他们想象着镇上的人为他们难过的样子，觉得真开心。'),
    (14, 830, 2183, 'But when the shadows of night closed them in, they gradually ceased to talk, and sat gazing into the fire, with their minds evidently wandering elsewhere.', '但是当夜幕降临，他们渐渐不说话了，坐着盯着火堆，心里显然在想别的事情。'),
    (14, 830, 2184, 'The excitement was gone, now, and Tom and Joe could not keep back thoughts of certain persons at home who were not enjoying this fine frolic as much as they were.', '兴奋劲儿不见了，汤姆和乔忍不住想起家里的一些人，他们可没有像自己这样享受这场“精彩的游戏”。'),
    (14, 830, 2185, 'Misgivings came; they grew troubled and unhappy; a sigh or two escaped, unawares.', '他们开始担心，变得心神不宁，不开心；不经意间叹了几口气。'),
    (14, 830, 2186, 'By and by Joe timidly ventured upon a roundabout “feeler” as to how the others might look upon a return to civilization—not right now, but—', '过了会儿，乔小心翼翼地，拐弯抹角地问大家，如果回到原来的生活，其他人会怎么看——不是现在回去，而是——'),
    (14, 831, 2187, 'Tom withered him with derision!', '汤姆嘲笑了他，让他没了精神！'),
    (14, 831, 2188, 'Huck, being uncommitted as yet, joined in with Tom, and the waverer quickly “explained,” and was glad to get out of the scrape with as little taint of chicken-hearted home-sickness clinging to his garments as he could.', '哈克还没有表态，也跟着汤姆一起嘲笑，那个犹豫不决的男孩赶紧“解释”起来，他很高兴能摆脱这个困境，身上没有沾染一点“胆小鬼想家”的痕迹。'),
    (14, 831, 2189, 'Mutiny was effectually laid to rest for the moment.', '叛逆的想法暂时被压制住了。'),
    (14, 832, 2190, 'As the night deepened, Huck began to nod, and presently to snore.', '夜深了，哈克开始打瞌睡，没一会儿就打起了呼噜。'),
    (14, 832, 2191, 'Joe followed next.', '乔也跟着过来了。'),
    (14, 832, 2192, 'Tom lay upon his elbow motionless, for some time, watching the two intently.', '汤姆 趴在胳膊上，一动不动地看了他俩好一会儿。'),
    (14, 832, 2193, 'At last he got up cautiously, on his knees, and went searching among the grass and the flickering reflections flung by the campfire.', '最后，他小心地跪起来，在草地和篝火的亮光里找东西。'),
    (14, 832, 2194, 'He picked up and inspected several large semi-cylinders of the thin white bark of a sycamore, and finally chose two which seemed to suit him.', '他捡起几块又大又圆的梧桐树皮，看了看，最后选了两块觉得合适的。'),
    (14, 832, 2195, 'Then he knelt by the fire and painfully wrote something upon each of these with his “red keel”; one he rolled up and put in his jacket pocket, and the other he put in Joe’s hat and removed it to a little distance from the owner.', '然后，他跪在火边，用他的“红铅笔”艰难地在每块树皮上写了点东西。一块他卷起来放进口袋，另一块放在乔的帽子里，再把帽子移到离乔远一点的地方。'),
    (14, 832, 2196, 'And he also put into the hat certain schoolboy treasures of almost inestimable value—among them a lump of chalk, an India-rubber ball, three fishhooks, and one of that kind of marbles known as a “sure ’nough crystal.”', '他还在帽子里放了一些小男孩非常宝贝的东西——比如一块粉笔、一个橡皮球、三根鱼钩，还有一颗叫“真水晶”的弹珠。'),
    (14, 832, 2197, 'Then he tiptoed his way cautiously among the trees till he felt that he was out of hearing, and straightway broke into a keen run in the direction of the sandbar.', '然后他小心翼翼地在树林里踮着脚走，直到听不到声音了，就立刻朝着沙洲的方向跑去。'),
    (15, 833, 2198, 'A few minutes later Tom was in the shoal water of the bar, wading toward the Illinois shore.', '几分钟后，汤姆 到了沙洲的浅水区，往伊利诺伊岸边走去。'),
    (15, 833, 2199, 'Before the depth reached his middle he was halfway over; the current would permit no more wading, now, so he struck out confidently to swim the remaining hundred yards.', '水还没到他腰部，他就已经走到一半了。现在水流太急，不能再走了，他就自信地游向剩下的百米路程。'),
    (15, 833, 2200, 'He swam quartering upstream, but still was swept downward rather faster than he had expected.', '他逆着水流斜着游，但还是被冲得比他想的快一些。'),
    (15, 833, 2201, 'However, he reached the shore finally, and drifted along till he found a low place and drew himself out.', '不过，他终于游到了岸边，沿着岸漂了一会儿，找到一个低洼的地方爬了上去。'),
    (15, 833, 2202, 'He put his hand on his jacket pocket, found his piece of bark safe, and then struck through the woods, following the shore, with streaming garments.', '他把手放进上衣口袋，发现那块树皮还在，然后就穿着湿衣服，沿着岸边穿过树林。'),
    (15, 833, 2203, 'Shortly before ten o’clock he came out into an open place opposite the village, and saw the ferryboat lying in the shadow of the trees and the high bank.', '快到十点的时候，他来到村子对面的一片空地，看到了停在树荫下和高岸边的大渡船。'),
    (15, 833, 2204, 'Everything was quiet under the blinking stars.', '眨眼的星星下，一切都很安静。'),
    (15, 833, 2205, 'He crept down the bank, watching with all his eyes, slipped into the water, swam three or four strokes and climbed into the skiff that did “yawl” duty at the boat’s stern.', '他小心地爬下岸边，瞪大眼睛看着，悄悄滑进水里，游了三四下，爬进了那艘停在大船船尾的小船。'),
    (15, 833, 2206, 'He laid himself down under the thwarts and waited, panting.', '他躺在船板下面，喘着气等待着。'),
    (15, 834, 2207, 'Presently the cracked bell tapped and a voice gave the order to “cast off.”', '很快，破铃铛响了一下，一个声音喊道：“开船！”'),
    (15, 834, 2208, 'A minute or two later the skiff’s head was standing high up, against the boat’s swell, and the voyage was begun.', '一两分钟后，小船的船头高高翘起，迎着大船的水波，航行开始了。'),
    (15, 834, 2209, 'Tom felt happy in his success, for he knew it was the boat’s last trip for the night.', '汤姆 为自己的成功感到高兴，因为他知道这是大船今晚最后一趟了。'),
    (15, 834, 2210, 'At the end of a long twelve or fifteen minutes the wheels stopped, and Tom slipped overboard and swam ashore in the dusk, landing fifty yards downstream, out of danger of possible stragglers.', '大概过了漫长的十二到十五分钟，轮子停了。汤姆 悄悄跳下船，在黄昏中游上岸，在下游五十码的地方上岸，这样就不会被可能路过的人发现。'),
    (15, 835, 2211, 'He flew along unfrequented alleys, and shortly found himself at his aunt’s back fence.', '他沿着没人的小巷飞快地跑着，很快就到了他姨妈家的后院围栏。'),
    (15, 835, 2212, 'He climbed over, approached the “ell,” and looked in at the sitting-room window, for a light was burning there.', '他翻过去，走到“L形”屋子旁边，朝客厅的窗户里看去，因为里面亮着灯。'),
    (15, 835, 2213, 'There sat Aunt Polly, Sid, Mary, and Joe Harper’s mother, grouped together, talking.', '波莉姨妈、希德、玛丽 和 乔·哈珀 的妈妈坐在一起，正在聊天。'),
    (15, 835, 2214, 'They were by the bed, and the bed was between them and the door.', '他们在床边，床在他们和门中间。'),
    (15, 835, 2215, 'Tom went to the door and began to softly lift the latch; then he pressed gently and the door yielded a crack; he continued pushing cautiously, and quaking every time it creaked, till he judged he might squeeze through on his knees; so he put his head through and began, warily.', '汤姆 走到门边，轻轻地抬起门闩；然后他轻轻一推，门就开了一道缝；他继续小心地推着，门每次嘎吱响，他都吓得发抖，直到他觉得可以跪着挤进去了；于是他把头探进去，小心翼翼地进去了。'),
    (15, 836, 2216, '“What makes the candle blow so?” said Aunt Polly.', '“蜡烛怎么吹得这么厉害？”波莉姨妈 说。'),
    (15, 836, 2217, 'Tom hurried up.', '汤姆 赶紧走上前。'),
    (15, 836, 2218, '“Why, that door’s open, I believe.', '“哎呀，我相信那扇门是开着的。”'),
    (15, 836, 2219, 'Why, of course it is.', '“哎呀，当然是了。”'),
    (15, 836, 2220, 'No end of strange things now.', '“现在真是奇怪事儿太多了。”'),
    (15, 836, 2221, 'Go ’long and shut it, Sid.”', '“去把它关上，希德。”'),
    (15, 837, 2222, 'Tom disappeared under the bed just in time.', '汤姆 及时地钻到了床底下。'),
    (15, 837, 2223, 'He lay and “breathed” himself for a time, and then crept to where he could almost touch his aunt’s foot.', '他躺着，“喘”了一会儿气，然后悄悄地爬过去，离他阿姨的脚很近，几乎能碰到。'),
    (15, 838, 2224, '“But as I was saying,” said Aunt Polly, “he warn’t _bad_, so to say—only misch_ee_vous.', '“我刚才说啊，” 波莉姨妈 说，“他其实不坏，就是有点调皮。”'),
    (15, 838, 2225, 'Only just giddy, and harum-scarum, you know.', '他只是有点淘气，爱闹腾，你知道的。'),
    (15, 838, 2226, 'He warn’t any more responsible than a colt.', '他就像个小马驹，一点也不懂事。'),
    (15, 838, 2227, '_He_ never meant any harm, and he was the best-hearted boy that ever was”—and she began to cry.', '他从来没想过要捣乱，他是个心地最好的孩子了！”——说着，她哭了起来。'),
    (15, 839, 2228, '“It was just so with my Joe—always full of his devilment, and up to every kind of mischief, but he was just as unselfish and kind as he could be—and laws bless me, to think I went and whipped him for taking that cream, never once recollecting that I throwed it out myself because it was sour, and I never to see him again in this world, never, never, never, poor abused boy!”', '“我的乔就是这样——总是那么淘气，喜欢搞各种恶作剧，但他心地善良，一点也不自私——天哪，我竟然因为他拿了奶油而打了他，我完全忘了那奶油是我自己倒掉的，因为它坏了。现在我再也见不到他了，永远，永远，永远都见不到了，我可怜的孩子啊！”'),
    (15, 839, 2229, 'And Mrs. Harper sobbed as if her heart would break.', '哈珀太太哭得非常伤心，好像心都要碎了。'),
    (15, 840, 2230, '“I hope Tom’s better off where he is,” said Sid, “but if he’d been better in some ways—”', '“我希望 汤姆 在那边过得更好，” 希德 说，“可他要是能更好一点就好了——”'),
    (15, 841, 2231, '“_Sid!', '“_席德_！'),
    (15, 841, 2232, '_” Tom felt the glare of the old lady’s eye, though he could not see it.', '汤姆 感觉到了老奶奶锐利的目光，虽然他没看见。'),
    (15, 841, 2233, '“Not a word against my Tom, now that he’s gone!', '“我的 汤姆 都走了，谁也不许说他坏话！”'),
    (15, 841, 2234, 'God’ll take care of _him_—never you trouble _your_self, sir!', '上帝会照顾他的——你不用为自己担心，先生！'),
    (15, 841, 2235, 'Oh, Mrs. Harper, I don’t know how to give him up!', '哦，哈珀太太，我真的舍不得他！'),
    (15, 841, 2236, 'I don’t know how to give him up!', '我真的舍不得他！'),
    (15, 841, 2237, 'He was such a comfort to me, although he tormented my old heart out of me, ’most.”', '他给了我很多安慰，虽然他有时也让我这颗老心操碎了。”'),
    (15, 842, 2238, '“The Lord giveth and the Lord hath taken away—Blessed be the name of the Lord!', '“上帝赐予生命，上帝也带走生命——愿上帝的名字得到赞美！'),
    (15, 842, 2239, 'But it’s so hard—Oh, it’s so hard!', '可是，这真的太难了——哦，太难了！'),
    (15, 842, 2240, 'Only last Saturday my Joe busted a firecracker right under my nose and I knocked him sprawling.', '就在上周六，我的乔在我鼻子底下放了个鞭炮，我气得把他推倒在地。'),
    (15, 842, 2241, 'Little did I know then, how soon—Oh, if it was to do over again I’d hug him and bless him for it.”', '我那时哪知道，他会这么快就——哦，如果能再来一次，我一定会抱抱他，感谢他。”'),
    (15, 843, 2242, '“Yes, yes, yes, I know just how you feel, Mrs. Harper, I know just exactly how you feel.', '“是的，是的，是的，哈珀太太，我非常明白你的感受，我完全明白你的感受。'),
    (15, 843, 2243, 'No longer ago than yesterday noon, my Tom took and filled the cat full of Pain-killer, and I did think the cretur would tear the house down.', '就在昨天中午，我的 汤姆 把止痛药灌给了猫，我当时真以为那小东西要把房子给拆了。'),
    (15, 843, 2244, 'And God forgive me, I cracked Tom’s head with my thimble, poor boy, poor dead boy.', '愿上帝原谅我，我用顶针敲了 汤姆 的头，可怜的孩子，可怜的去世的孩子。'),
    (15, 843, 2245, 'But he’s out of all his troubles now.', '不过，他现在已经没有烦恼了。'),
    (15, 843, 2246, 'And the last words I ever heard him say was to reproach—”', '我最后一次听到他说的话，是他在责怪——”'),
    (15, 844, 2247, 'But this memory was too much for the old lady, and she broke entirely down.', '但这段回忆让老太太受不了了，她彻底崩溃了。'),
    (15, 844, 2248, 'Tom was snuffling, now, himself—and more in pity of himself than anybody else.', '汤姆 自己也抽泣起来，他更可怜的是自己，而不是别人。'),
    (15, 844, 2249, 'He could hear Mary crying, and putting in a kindly word for him from time to time.', '他能听到 玛丽 在哭，还不时地替他说好话。'),
    (15, 844, 2250, 'He began to have a nobler opinion of himself than ever before.', '他开始觉得自己比以前更了不起了。'),
    (15, 844, 2251, 'Still, he was sufficiently touched by his aunt’s grief to long to rush out from under the bed and overwhelm her with joy—and the theatrical gorgeousness of the thing appealed strongly to his nature, too, but he resisted and lay still.', '不过，他还是被阿姨的伤心感动了，很想从床底下冲出去，给她一个大大的惊喜——这种像演戏一样的事情也特别吸引他，但他还是忍住了，一动不动地躺着。'),
    (15, 845, 2252, 'He went on listening, and gathered by odds and ends that it was conjectured at first that the boys had got drowned while taking a swim; then the small raft had been missed; next, certain boys said the missing lads had promised that the village should “hear something” soon; the wise-heads had “put this and that together” and decided that the lads had gone off on that raft and would turn up at the next town below, presently; but toward noon the raft had been found, lodged against the Missouri shore some five or six miles below the village—and then hope perished; they must be drowned, else hunger would have driven them home by nightfall if not sooner.', '他继续听着，零零散散地了解到：大家一开始猜，孩子们可能是在游泳时淹死的；接着，小木筏不见了；然后，有几个孩子说，失踪的孩子们说过要让村子里“听到点什么”；聪明的大人们把这些线索“串起来一想”，就觉得孩子们是坐木筏走了，很快会在下游的下一个小镇出现；可是，到了中午，木筏被找到了，它卡在村子下游五六英里处的密苏里河岸边——这时，所有希望都破灭了；他们一定是淹死了，不然，即使不早点回家，到晚上也会因为饿了而回家。'),
    (15, 845, 2253, 'It was believed that the search for the bodies had been a fruitless effort merely because the drowning must have occurred in mid-channel, since the boys, being good swimmers, would otherwise have escaped to shore.', '大家觉得，找他们身体的努力是白费力气，因为他们可能是在河中央淹死的，要是他们在岸边，那么会游泳的孩子们肯定能游到岸边。'),
    (15, 845, 2254, 'This was Wednesday night.', '这是星期三晚上。'),
    (15, 845, 2255, 'If the bodies continued missing until Sunday, all hope would be given over, and the funerals would be preached on that morning.', '如果他们的身体到星期天还没找到，大家就会放弃所有希望，然后那天早上就会举行葬礼。'),
    (15, 845, 2256, 'Tom shuddered.', '汤姆 shuddered.'),
    (15, 846, 2257, 'Mrs. Harper gave a sobbing goodnight and turned to go.', '哈珀太太哭着说了声晚安，然后转身准备离开。'),
    (15, 846, 2258, 'Then with a mutual impulse the two bereaved women flung themselves into each other’s arms and had a good, consoling cry, and then parted.', '接着，两个失去亲人的女人不约而同地抱在一起，好好地哭了一场，互相安慰，然后才分开。'),
    (15, 846, 2259, 'Aunt Polly was tender far beyond her wont, in her goodnight to Sid and Mary.', '波莉姨妈 破天荒地温柔，对 希德 和 玛丽 说了晚安。'),
    (15, 846, 2260, 'Sid snuffled a bit and Mary went off crying with all her heart.', '希德 抽泣了几声，玛丽 也伤心地哭着离开了。'),
    (15, 847, 2261, 'Aunt Polly knelt down and prayed for Tom so touchingly, so appealingly, and with such measureless love in her words and her old trembling voice, that he was weltering in tears again, long before she was through.', '波莉姨妈 跪下来为 汤姆 祈祷。她的祈祷是那么感人，那么恳切，话语里和她颤抖的嗓音里充满了无限的爱，以至于她还没说完，他又早已泪流满面了。'),
    (15, 848, 2262, 'He had to keep still long after she went to bed, for she kept making broken-hearted ejaculations from time to time, tossing unrestfully, and turning over.', '她睡着后很久，他都必须保持安静，因为她不时地发出伤心的声音，翻来覆去，睡不安稳。'),
    (15, 848, 2263, 'But at last she was still, only moaning a little in her sleep.', '不过最后她还是安静了，只是在睡梦中轻轻地哼了几声。'),
    (15, 848, 2264, 'Now the boy stole out, rose gradually by the bedside, shaded the candle-light with his hand, and stood regarding her.', '小男孩悄悄地走出来，慢慢走到床边，用手遮住烛光，站着看她。'),
    (15, 848, 2265, 'His heart was full of pity for her.', '他心里很同情她。'),
    (15, 848, 2266, 'He took out his sycamore scroll and placed it by the candle.', '他拿出他的梧桐树皮卷，把它放在蜡烛旁边。'),
    (15, 848, 2267, 'But something occurred to him, and he lingered considering.', '但他突然想到一件事，他停下来想了想。'),
    (15, 848, 2268, 'His face lighted with a happy solution of his thought; he put the bark hastily in his pocket.', '他想到了一个好办法，脸上亮了起来；他赶紧把树皮放进口袋。'),
    (15, 848, 2269, 'Then he bent over and kissed the faded lips, and straightway made his stealthy exit, latching the door behind him.', '然后他弯下腰，亲了亲她苍白的嘴唇，悄悄地走了出去，关上了身后的门。'),
    (15, 849, 2270, 'He threaded his way back to the ferry landing, found nobody at large there, and walked boldly on board the boat, for he knew she was tenantless except that there was a watchman, who always turned in and slept like a graven image.', '他摸索着回到渡船码头，没看到什么人，就大胆地走上了船。他知道船上没人，只有一个看守，看守总是睡得很香，像个木头人。'),
    (15, 849, 2271, 'He untied the skiff at the stern, slipped into it, and was soon rowing cautiously upstream.', '他解开船尾的小船，滑进去，很快就小心地向上游划去。'),
    (15, 849, 2272, 'When he had pulled a mile above the village, he started quartering across and bent himself stoutly to his work.', '当他划到村庄上方一英里时，他开始横着划过去，用力地划着。'),
    (15, 849, 2273, 'He hit the landing on the other side neatly, for this was a familiar bit of work to him.', '他稳稳地靠上了对岸的码头，因为他很熟悉这个活。'),
    (15, 849, 2274, 'He was moved to capture the skiff, arguing that it might be considered a ship and therefore legitimate prey for a pirate, but he knew a thorough search would be made for it and that might end in revelations.', '他想把小船带走，心想这可以算是一艘船，海盗可以抢它。但他知道大家会仔细找船，那样他的秘密就会被发现。'),
    (15, 849, 2275, 'So he stepped ashore and entered the woods.', '于是他上了岸，走进了树林。'),
    (15, 850, 2276, 'He sat down and took a long rest, torturing himself meanwhile to keep awake, and then started warily down the home-stretch.', '他坐下来好好休息，努力不让自己睡着，然后小心翼翼地往回走。'),
    (15, 850, 2277, 'The night was far spent.', '夜已经很深了。'),
    (15, 850, 2278, 'It was broad daylight before he found himself fairly abreast the island bar.', '天大亮时，他才走到岛边的沙洲旁边。'),
    (15, 850, 2279, 'He rested again until the sun was well up and gilding the great river with its splendor, and then he plunged into the stream.', '他又休息了一会儿，直到太阳高高升起，把大河照得金光闪闪，然后他跳进了河里。'),
    (15, 850, 2280, 'A little later he paused, dripping, upon the threshold of the camp, and heard Joe say:', '不久后，他浑身湿淋淋地停在营地门口，听到乔说：'),
    (15, 851, 2281, '“No, Tom’s true-blue, Huck, and he’ll come back.', '“不，汤姆 是个忠实的朋友，哈克，他会回来的。”'),
    (15, 851, 2282, 'He won’t desert.', '他不会抛弃我们的。'),
    (15, 851, 2283, 'He knows that would be a disgrace to a pirate, and Tom’s too proud for that sort of thing.', '他知道那对海盗来说是丢脸的事，而 汤姆 太骄傲了，不会做那种事。'),
    (15, 851, 2284, 'He’s up to something or other.', '他肯定在搞什么名堂。'),
    (15, 851, 2285, 'Now I wonder what?”', '“现在我想知道是什么？”'),
    (15, 852, 2286, '“Well, the things is ours, anyway, ain’t they?”', '“嗯，反正这些东西是我们的，对吧？”'),
    (15, 853, 2287, '“Pretty near, but not yet, Huck.', '“差不多了，但还没到，哈克。”'),
    (15, 853, 2288, 'The writing says they are if he ain’t back here to breakfast.”', '纸上写着，如果他早餐没回来，这些东西就是我们的了。”'),
    (15, 854, 2289, '“Which he is!” exclaimed Tom, with fine dramatic effect, stepping grandly into camp.', '“他就是！” 汤姆 大声喊道，带着很有趣的表演效果，大摇大摆地走进了营地。'),
    (15, 855, 2290, 'A sumptuous breakfast of bacon and fish was shortly provided, and as the boys set to work upon it, Tom recounted (and adorned) his adventures.', '很快，一份丰盛的培根鱼肉早餐就准备好了。孩子们开始吃的时候，汤姆 讲起了（还添油加醋地美化了）他的冒险故事。'),
    (15, 855, 2291, 'They were a vain and boastful company of heroes when the tale was done.', '故事讲完后，他们都成了爱炫耀的英雄。'),
    (15, 855, 2292, 'Then Tom hid himself away in a shady nook to sleep till noon, and the other pirates got ready to fish and explore.', '于是 汤姆 躲到一个阴凉的角落里睡到中午，其他海盗则准备去钓鱼和探险。'),
    (16, 856, 2293, 'After dinner all the gang turned out to hunt for turtle eggs on the bar.', '晚饭后，所有人都出去在沙洲上找海龟蛋。'),
    (16, 856, 2294, 'They went about poking sticks into the sand, and when they found a soft place they went down on their knees and dug with their hands.', '他们拿着棍子在沙子里戳，当他们找到一个软的地方时，就跪下来用手挖。'),
    (16, 856, 2295, 'Sometimes they would take fifty or sixty eggs out of one hole.', '有时候他们能从一个洞里挖出五六十个蛋。'),
    (16, 856, 2296, 'They were perfectly round white things a trifle smaller than an English walnut.', '它们是圆圆的白色小东西，比核桃稍微小一点。'),
    (16, 856, 2297, 'They had a famous fried-egg feast that night, and another on Friday morning.', '那天晚上，他们吃了一顿丰盛的煎蛋大餐，星期五早上又吃了一顿。'),
    (16, 857, 2298, 'After breakfast they went whooping and prancing out on the bar, and chased each other round and round, shedding clothes as they went, until they were naked, and then continued the frolic far away up the shoal water of the bar, against the stiff current, which latter tripped their legs from under them from time to time and greatly increased the fun.', '早餐后，他们欢呼雀跃地跑到沙洲上，互相追逐打闹，跑着跑着就把衣服脱光了。然后继续在沙洲的浅水区玩耍，逆着水流。水流有时会把他们的腿绊倒，这让游戏更加有趣。'),
    (16, 857, 2299, 'And now and then they stooped in a group and splashed water in each other’s faces with their palms, gradually approaching each other, with averted faces to avoid the strangling sprays, and finally gripping and struggling till the best man ducked his neighbor, and then they all went under in a tangle of white legs and arms and came up blowing, sputtering, laughing, and gasping for breath at one and the same time.', '他们有时会蹲下来，用手掌互相泼水到脸上，慢慢靠近对方。他们脸扭向一边，避开呛人的水花。最后扭打起来，直到最厉害的人把旁边的人按到水里。接着，他们白花花的胳膊和腿缠在一起，全都沉入了水下，然后浮上来，呼气、吐水、大笑，同时大口喘气。'),
    (16, 858, 2300, 'When they were well exhausted, they would run out and sprawl on the dry, hot sand, and lie there and cover themselves up with it, and by and by break for the water again and go through the original performance once more.', '他们玩累了，就跑到沙滩上。沙滩又干又热，他们躺下，用沙子盖住自己。过一会儿，又跑去玩水，再玩一遍。'),
    (16, 858, 2301, 'Finally it occurred to them that their naked skin represented flesh-colored “tights” very fairly; so they drew a ring in the sand and had a circus—with three clowns in it, for none would yield this proudest post to his neighbor.', '最后，他们觉得光着身子就像穿了肉色的“紧身衣”。于是他们在沙滩上画了个圈，玩起了马戏。里面有三个小丑，谁也不想把这个最厉害的角色让给别人。'),
    (16, 859, 2302, 'Next they got their marbles and played “knucks” and “ringtaw” and “keeps” till that amusement grew stale.', '接着，他们拿出弹珠，玩了好几种弹珠游戏，直到玩腻了。'),
    (16, 859, 2303, 'Then Joe and Huck had another swim, but Tom would not venture, because he found that in kicking off his trousers he had kicked his string of rattlesnake rattles off his ankle, and he wondered how he had escaped cramp so long without the protection of this mysterious charm.', '接着，乔和 哈克 又游了一次。但 汤姆 不敢下水，因为他发现自己脱裤子的时候，把系在脚踝上的响尾蛇响环给踢掉了。他很奇怪，没有这个神秘护身符的保护，他怎么这么久都没抽筋。'),
    (16, 859, 2304, 'He did not venture again until he had found it, and by that time the other boys were tired and ready to rest.', '他没找到就不敢再玩。等他找到时，别的小伙伴都累了，想休息了。'),
    (16, 859, 2305, 'They gradually wandered apart, dropped into the “dumps,” and fell to gazing longingly across the wide river to where the village lay drowsing in the sun.', '他们慢慢地分开了，心情不太好，开始看着宽阔的河对面。那里的小村庄正在阳光下睡懒觉。'),
    (16, 859, 2306, 'Tom found himself writing “BECKY” in the sand with his big toe; he scratched it out, and was angry with himself for his weakness.', '汤姆 发现自己用大脚趾在沙子上写“BECKY”；他赶紧抹掉了，气自己怎么这么没用。'),
    (16, 859, 2307, 'But he wrote it again, nevertheless; he could not help it.', '但是他还是又写了一遍，他忍不住啊。'),
    (16, 859, 2308, 'He erased it once more and then took himself out of temptation by driving the other boys together and joining them.', '他又擦了一次。然后他叫上其他男孩一起玩，不让自己再想那个了。'),
    (16, 860, 2309, 'But Joe’s spirits had gone down almost beyond resurrection.', '但是乔的心情已经很糟很糟了，好像好不起来了。'),
    (16, 860, 2310, 'He was so homesick that he could hardly endure the misery of it.', '他太想家了，难受得受不了了。'),
    (16, 860, 2311, 'The tears lay very near the surface.', '眼泪都快要流出来了。'),
    (16, 860, 2312, 'Huck was melancholy, too.', '哈克 也很难过。'),
    (16, 860, 2313, 'Tom was downhearted, but tried hard not to show it.', '汤姆 心情很不好，但他努力不表现出来。'),
    (16, 860, 2314, 'He had a secret which he was not ready to tell, yet, but if this mutinous depression was not broken up soon, he would have to bring it out.', '他有个秘密还没准备好说，但如果他再不开心，他就得说出来了。'),
    (16, 860, 2315, 'He said, with a great show of cheerfulness:', '他装作很开心地说：'),
    (16, 861, 2316, '“I bet there’s been pirates on this island before, boys.', '“我打赌，这岛上以前肯定有海盗，孩子们。'),
    (16, 861, 2317, 'We’ll explore it again.', '我们再来找找看。'),
    (16, 861, 2318, 'They’ve hid treasures here somewhere.', '他们肯定把宝贝藏在这儿了。'),
    (16, 861, 2319, 'How’d you feel to light on a rotten chest full of gold and silver—hey?”', '找到一个装满金子和银子的旧箱子，你们高不高兴啊？”'),
    (16, 862, 2320, 'But it roused only faint enthusiasm, which faded out, with no reply.', '但大家没什么兴趣，也没人回答。'),
    (16, 862, 2321, 'Tom tried one or two other seductions; but they failed, too.', '汤姆 又试着说了别的好玩的事，可也没用。'),
    (16, 862, 2322, 'It was discouraging work.', '这让他有点泄气。'),
    (16, 862, 2323, 'Joe sat poking up the sand with a stick and looking very gloomy.', '乔用小棍子戳着沙子，看起来很不开心。'),
    (16, 862, 2324, 'Finally he said:', '最后他说：'),
    (16, 863, 2325, '“Oh, boys, let’s give it up.', '“哎，孩子们，我们别玩了。'),
    (16, 863, 2326, 'I want to go home.', '我想回家。'),
    (16, 863, 2327, 'It’s so lonesome.”', '这儿太孤单了。”'),
    (16, 864, 2328, '“Oh no, Joe, you’ll feel better by and by,” said Tom.', '“哎呀，乔，等会儿你就会好起来的，” 汤姆 说。'),
    (16, 864, 2329, '“Just think of the fishing that’s here.”', '“想想这儿可以钓鱼啊。”'),
    (16, 865, 2330, '“I don’t care for fishing.', '“我不想钓鱼。'),
    (16, 865, 2331, 'I want to go home.”', '我想回家。”'),
    (16, 866, 2332, '“But, Joe, there ain’t such another swimming-place anywhere.”', '“可是，乔，没有比这儿更好的游泳地方了。”'),
    (16, 867, 2333, '“Swimming’s no good.', '“游泳一点也不好玩。'),
    (16, 867, 2334, 'I don’t seem to care for it, somehow, when there ain’t anybody to say I sha’n’t go in.', '没人管我，我就不想游了。'),
    (16, 867, 2335, 'I mean to go home.”', '我就是要回家。”'),
    (16, 868, 2336, '“Oh, shucks!', '“哎呀！'),
    (16, 868, 2337, 'Baby!', '你真是个小孩子！'),
    (16, 868, 2338, 'You want to see your mother, I reckon.”', '我想，你是想妈妈了吧。”'),
    (16, 869, 2339, '“Yes, I _do_ want to see my mother—and you would, too, if you had one.', '“对，我就是想妈妈了——你要是有妈妈，你也会想的。'),
    (16, 869, 2340, 'I ain’t any more baby than you are.”', '我才不像你说的那样是小孩子呢！”'),
    (16, 869, 2341, 'And Joe snuffled a little.', '乔轻轻地抽了抽鼻子。'),
    (16, 870, 2342, '“Well, we’ll let the crybaby go home to his mother, won’t we, Huck?', '“好吧，我们让那个爱哭鬼回家找妈妈，好不好啊，哈克？”'),
    (16, 870, 2343, 'Poor thing—does it want to see its mother?', '可怜的，你想妈妈了吗？'),
    (16, 870, 2344, 'And so it shall.', '那就可以去啊。'),
    (16, 870, 2345, 'You like it here, don’t you, Huck?', '你喜欢这里，对吧，哈克？'),
    (16, 870, 2346, 'We’ll stay, won’t we?”', '我们会留下，对吗？'),
    (16, 871, 2347, 'Huck said, “Y-e-s”—without any heart in it.', '哈克 没精打采地说：“是——的。”'),
    (16, 872, 2348, '“I’ll never speak to you again as long as I live,” said Joe, rising.', '“我一辈子都不会再跟你说话了！”乔站起来说。'),
    (16, 872, 2349, '“There now!”', '“哼！”'),
    (16, 872, 2350, 'And he moved moodily away and began to dress himself.', '他不高兴地走开，开始穿衣服。'),
    (16, 873, 2351, '“Who cares!” said Tom.', '“Who cares!” said 汤姆.'),
    (16, 873, 2352, '“Nobody wants you to.', '“没人想你留下。'),
    (16, 873, 2353, 'Go ’long home and get laughed at.', '回家去吧，让别人笑话你。'),
    (16, 873, 2354, 'Oh, you’re a nice pirate.', '你可真是个‘好’海盗啊。'),
    (16, 873, 2355, 'Huck and me ain’t crybabies.', '哈克 和我才不是爱哭鬼。'),
    (16, 873, 2356, 'We’ll stay, won’t we, Huck?', '我们会留下来，对不对，哈克？'),
    (16, 873, 2357, 'Let him go if he wants to.', '他想走就让他走吧。'),
    (16, 873, 2358, 'I reckon we can get along without him, per’aps.”', '我想，我们没有他也能玩得好，也许吧。”'),
    (16, 874, 2359, 'But Tom was uneasy, nevertheless, and was alarmed to see Joe go sullenly on with his dressing.', '不过，汤姆 心里还是不安，他看到乔不高兴地继续穿衣服，吓了一跳。'),
    (16, 874, 2360, 'And then it was discomforting to see Huck eying Joe’s preparations so wistfully, and keeping up such an ominous silence.', '接着，他看到 哈克 那么渴望地看着乔准备，还一直保持着不祥的沉默，这让他感到很不舒服。'),
    (16, 874, 2361, 'Presently, without a parting word, Joe began to wade off toward the Illinois shore.', '很快，乔什么也没说，就开始趟水走向伊利诺伊州的岸边。'),
    (16, 874, 2362, 'Tom’s heart began to sink.', '汤姆 的心开始往下沉。'),
    (16, 874, 2363, 'He glanced at Huck.', '他看了一眼 哈克。'),
    (16, 874, 2364, 'Huck could not bear the look, and dropped his eyes.', '哈克 不敢看，就低下了头。'),
    (16, 874, 2365, 'Then he said:', '然后他说：'),
    (16, 875, 2366, '“I want to go, too, Tom.', '“我也想去，汤姆。”'),
    (16, 875, 2367, 'It was getting so lonesome anyway, and now it’ll be worse.', '反正已经很孤单了，现在会更糟。'),
    (16, 875, 2368, 'Let’s us go, too, Tom.”', '“我们也一起去吧，汤姆。”'),
    (16, 876, 2369, '“I won’t!', '“我才不呢！'),
    (16, 876, 2370, 'You can all go, if you want to.', '你们想走就都走吧。'),
    (16, 876, 2371, 'I mean to stay.”', '我要留下来。”'),
    (16, 877, 2372, '“Tom, I better go.”', '“汤姆, I better go.”'),
    (16, 878, 2373, '“Well, go ’long—who’s hendering you.”', '“好吧，走吧——谁拦着你了呀。”'),
    (16, 879, 2374, 'Huck began to pick up his scattered clothes.', '哈克 开始捡他散落的衣服。'),
    (16, 879, 2375, 'He said:', '他说：'),
    (16, 880, 2376, '“Tom, I wisht you’d come, too.', '“汤姆, I wisht you’d come, too.'),
    (16, 880, 2377, 'Now you think it over.', '现在你好好想想吧。'),
    (16, 880, 2378, 'We’ll wait for you when we get to shore.”', '我们到了岸边就等你。”'),
    (16, 881, 2379, '“Well, you’ll wait a blame long time, that’s all.”', '“哼，那你们可得等好久好久，就这样。”'),
    (16, 882, 2380, 'Huck started sorrowfully away, and Tom stood looking after him, with a strong desire tugging at his heart to yield his pride and go along too.', '哈克 难过地走了。汤姆 看着他走远，心里好想也放下脸面，跟着一起去。'),
    (16, 882, 2381, 'He hoped the boys would stop, but they still waded slowly on.', '他希望大家停下来，但他们还是慢慢地往前走。'),
    (16, 882, 2382, 'It suddenly dawned on Tom that it was become very lonely and still.', '汤姆 突然觉得，这里变得很安静，也很孤单。'),
    (16, 882, 2383, 'He made one final struggle with his pride, and then darted after his comrades, yelling:', '他最后跟自己挣扎了一下，然后就冲向伙伴们，大声喊：'),
    (16, 883, 2384, '“Wait!', '“等等！'),
    (16, 883, 2385, 'Wait!', '等等！'),
    (16, 883, 2386, 'I want to tell you something!”', '我想告诉你们一件事！”'),
    (16, 884, 2387, 'They presently stopped and turned around.', '他们立刻停了下来，转过身。'),
    (16, 884, 2388, 'When he got to where they were, he began unfolding his secret, and they listened moodily till at last they saw the “point” he was driving at, and then they set up a warwhoop of applause and said it was “splendid!” and said if he had told them at first, they wouldn’t have started away.', '他走到他们身边，就开始说出他的秘密。大家一开始不开心，但是后来终于明白了他说的是什么“重点”，然后就大声欢呼起来，说“太棒了！” 还说，要是他早点告诉他们，他们就不会走了。'),
    (16, 884, 2389, 'He made a plausible excuse; but his real reason had been the fear that not even the secret would keep them with him any very great length of time, and so he had meant to hold it in reserve as a last seduction.', '他找了个好听的借口；但真正的原因是他担心，就算说了秘密，他们也留不了多久，所以他想把秘密留着，等到最后才说，好让他们不走。'),
    (16, 885, 2390, 'The lads came gayly back and went at their sports again with a will, chattering all the time about Tom’s stupendous plan and admiring the genius of it.', '小伙子们开心地回来了，又开始尽情玩耍，他们一直聊着汤姆的那个很棒的计划，都觉得他很聪明。'),
    (16, 885, 2391, 'After a dainty egg and fish dinner, Tom said he wanted to learn to smoke, now.', '吃了一顿美味的鸡蛋鱼肉晚餐后，汤姆 说他现在想学抽烟。'),
    (16, 885, 2392, 'Joe caught at the idea and said he would like to try, too.', '乔一听到这个主意，就说他也想试试看。'),
    (16, 885, 2393, 'So Huck made pipes and filled them.', '于是哈克做了烟斗，还把烟草装了进去。'),
    (16, 885, 2394, 'These novices had never smoked anything before but cigars made of grapevine, and they “bit” the tongue, and were not considered manly anyway.', '这些新手以前从来没抽过烟，只抽过葡萄藤做的“雪茄”，那种东西会“咬”舌头，而且一点也不觉得很男子汉。'),
    (16, 886, 2395, 'Now they stretched themselves out on their elbows and began to puff, charily, and with slender confidence.', '现在他们趴着用胳膊肘撑着，小心翼翼地，有点没信心地开始抽烟。'),
    (16, 886, 2396, 'The smoke had an unpleasant taste, and they gagged a little, but Tom said:', '烟的味道不好闻，他们有点想吐，但汤姆说：'),
    (16, 887, 2397, '“Why, it’s just as easy!', '“哎呀，这太容易了！'),
    (16, 887, 2398, 'If I’d a knowed this was all, I’d a learnt long ago.”', '要是早知道这么简单，我早就学会了。”'),
    (16, 888, 2399, '“So would I,” said Joe.', '“我也是！”乔说。'),
    (16, 888, 2400, '“It’s just nothing.”', '“一点都不难。”'),
    (16, 889, 2401, '“Why, many a time I’ve looked at people smoking, and thought well I wish I could do that; but I never thought I could,” said Tom.', '“哎呀，我看了好多人抽烟，心想我也能抽就好了；但我从没想过我真的能做到。”汤姆说。'),
    (16, 890, 2402, '“That’s just the way with me, hain’t it, Huck?', '“我也是这样想的，不是吗，哈克？'),
    (16, 890, 2403, 'You’ve heard me talk just that way—haven’t you, Huck?', '你听我这么说过吧，哈克？'),
    (16, 890, 2404, 'I’ll leave it to Huck if I haven’t.”', '如果我没说过，就让哈克来说。”'),
    (16, 891, 2405, '“Yes—heaps of times,” said Huck.', '“是的——好多好多次了。”哈克说。'),
    (16, 892, 2406, '“Well, I have too,” said Tom; “oh, hundreds of times.', '“嗯，我也说过。”汤姆说，“哦，几百次了。'),
    (16, 892, 2407, 'Once down by the slaughter-house.', '有一次在屠宰场旁边。'),
    (16, 892, 2408, 'Don’t you remember, Huck?', 'Don’t you remember, 哈克?'),
    (16, 892, 2409, 'Bob Tanner was there, and Johnny Miller, and Jeff Thatcher, when I said it.', '我说的时候，鲍勃·坦纳、约翰尼·米勒和杰夫·撒切尔都在场。'),
    (16, 892, 2410, 'Don’t you remember, Huck, ’bout me saying that?”', '你不记得了吗，哈克，我说了那些话？”'),
    (16, 893, 2411, '“Yes, that’s so,” said Huck.', '“Yes, that’s so,” said 哈克.'),
    (16, 893, 2412, '“That was the day after I lost a white alley.', '“那是我弄丢了一个白色弹珠的第二天。'),
    (16, 893, 2413, 'No, ’twas the day before.”', '不对，是前一天。”'),
    (16, 894, 2414, '“There—I told you so,” said Tom.', '“看吧——我早就告诉你了。”汤姆说。'),
    (16, 894, 2415, '“Huck recollects it.”', '“哈克 recollects it.”'),
    (16, 895, 2416, '“I bleeve I could smoke this pipe all day,” said Joe.', '“我觉得我能抽这个烟斗一整天，”乔说。'),
    (16, 895, 2417, '“I don’t feel sick.”', '“我一点也不觉得恶心。”'),
    (16, 896, 2418, '“Neither do I,” said Tom.', '“Neither do I,” said 汤姆.'),
    (16, 896, 2419, '“I could smoke it all day.', '“我能抽一整天。'),
    (16, 896, 2420, 'But I bet you Jeff Thatcher couldn’t.”', '“但我敢打赌，杰夫·撒切尔肯定不行。”'),
    (16, 897, 2421, '“Jeff Thatcher!', '“Jeff 撒切尔!'),
    (16, 897, 2422, 'Why, he’d keel over just with two draws.', '哼，他只要抽两口就会倒下。'),
    (16, 897, 2423, 'Just let him try it once.', '让他试试看就知道了。'),
    (16, 897, 2424, '_He’d_ see!”', '他会看到的！”'),
    (16, 898, 2425, '“I bet he would.', '“我敢打赌他会的。'),
    (16, 898, 2426, 'And Johnny Miller—I wish could see Johnny Miller tackle it once.”', '还有约翰尼·米勒——我真希望约翰尼·米勒能来试一次。”'),
    (16, 899, 2427, '“Oh, don’t I!” said Joe.', '“哦，可不是嘛！”乔说。'),
    (16, 899, 2428, '“Why, I bet you Johnny Miller couldn’t any more do this than nothing.', '“哎呀，我敢说约翰尼·米勒根本做不到这个。'),
    (16, 899, 2429, 'Just one little snifter would fetch _him_.”', '只要喝一小口，就能把他叫来。'),
    (16, 900, 2430, '“’Deed it would, Joe.', '是啊，乔，他肯定会来的。'),
    (16, 900, 2431, 'Say—I wish the boys could see us now.”', '哎——真希望那些小伙伴能看到我们现在这样！'),
    (16, 901, 2432, '“So do I.”', '我也是。'),
    (16, 902, 2433, '“Say—boys, don’t say anything about it, and some time when they’re around, I’ll come up to you and say, ‘Joe, got a pipe?', '哎——伙计们，这事咱们谁也别说出去。等他们都在的时候，我就走过去对你说，‘乔，你有烟斗吗？'),
    (16, 902, 2434, 'I want a smoke.’', '我想抽一口。’'),
    (16, 902, 2435, 'And you’ll say, kind of careless like, as if it warn’t anything, you’ll say, ‘Yes, I got my _old_ pipe, and another one, but my tobacker ain’t very good.’', '然后你就会装作不在乎的样子，好像这没什么大不了的，你会说，‘有啊，我有我的老烟斗，还有一个备用的，不过我的烟叶不怎么样。’'),
    (16, 902, 2436, 'And I’ll say, ‘Oh, that’s all right, if it’s _strong_ enough.’', '我就会说，‘哦，没关系，只要味道够浓就行。’'),
    (16, 902, 2437, 'And then you’ll out with the pipes, and we’ll light up just as ca’m, and then just see ’em look!”', '然后你就会拿出烟斗，我们俩就安安静静地点上烟，然后就看他们惊讶的样子！'),
    (16, 903, 2438, '“By jings, that’ll be gay, Tom!', '“天哪，那一定会很好玩，汤姆！'),
    (16, 903, 2439, 'I wish it was _now_!”', '真希望是现在！'),
    (16, 904, 2440, '“So do I!', '我也是！'),
    (16, 904, 2441, 'And when we tell ’em we learned when we was off pirating, won’t they wish they’d been along?”', '等我们告诉他们，这是我们当海盗的时候学会的，他们会不会后悔没跟我们一起来？'),
    (16, 905, 2442, '“Oh, I reckon not!', '哦，我觉得不会！'),
    (16, 905, 2443, 'I’ll just _bet_ they will!”', '我敢打赌他们会的！'),
    (16, 906, 2444, 'So the talk ran on.', '他们就一直这样聊啊聊。'),
    (16, 906, 2445, 'But presently it began to flag a trifle, and grow disjointed.', '但是没过多久，他们的话题就有点说不动了，变得断断续续的。'),
    (16, 906, 2446, 'The silences widened; the expectoration marvellously increased.', '他们安静的时间越来越长；吐口水的次数也变多了。'),
    (16, 906, 2447, 'Every pore inside the boys’ cheeks became a spouting fountain; they could scarcely bail out the cellars under their tongues fast enough to prevent an inundation; little overflowings down their throats occurred in spite of all they could do, and sudden retchings followed every time.', '男孩们的嘴巴里不停地冒着口水，怎么也咽不完，即使努力忍着，口水还是会流到喉咙里，每次都让他们想吐。'),
    (16, 906, 2448, 'Both boys were looking very pale and miserable, now.', '两个男孩现在脸色都很难看，非常不舒服。'),
    (16, 906, 2449, 'Joe’s pipe dropped from his nerveless fingers.', '乔的烟斗从他没力气的手指缝里掉了下来。'),
    (16, 906, 2450, 'Tom’s followed.', '汤姆’s followed.'),
    (16, 906, 2451, 'Both fountains were going furiously and both pumps bailing with might and main.', '他们两个都吐得厉害，嘴巴里也拼命地往外冒水。'),
    (16, 906, 2452, 'Joe said feebly:', '乔有气无力地说：'),
    (16, 907, 2453, '“I’ve lost my knife.', '“我的小刀不见了。'),
    (16, 907, 2454, 'I reckon I better go and find it.”', '我想我最好去把它找回来。”'),
    (16, 908, 2455, 'Tom said, with quivering lips and halting utterance:', '汤姆嘴唇颤抖着，说话结结巴巴地说：'),
    (16, 909, 2456, '“I’ll help you.', '“我帮你。'),
    (16, 909, 2457, 'You go over that way and I’ll hunt around by the spring.', '你往那边走，我到泉水边上去找找看。'),
    (16, 909, 2458, 'No, you needn’t come, Huck—we can find it.”', '“不，你不用来了，哈克——我们能找到的。”'),
    (16, 910, 2459, 'So Huck sat down again, and waited an hour.', '于是哈克又坐了下来，等了一个小时。'),
    (16, 910, 2460, 'Then he found it lonesome, and went to find his comrades.', '后来他觉得一个人很孤单，就去R找他的小伙伴了。'),
    (16, 910, 2461, 'They were wide apart in the woods, both very pale, both fast asleep.', '他们两个在树林里离得很远，脸色都很白，都睡着了。'),
    (16, 910, 2462, 'But something informed him that if they had had any trouble they had got rid of it.', '但是他心里明白，如果他们之前有什么不舒服，现在也都好了。'),
    (16, 911, 2463, 'They were not talkative at supper that night.', '那天晚上吃晚饭的时候，他们都不怎么说话了。'),
    (16, 911, 2464, 'They had a humble look, and when Huck prepared his pipe after the meal and was going to prepare theirs, they said no, they were not feeling very well—something they ate at dinner had disagreed with them.', '他们看起来很没精神。哈克吃完饭后准备好自己的烟斗，正要帮他们准备时，他们却说不，他们感觉不太舒服——晚餐吃的东西让他们不舒服。'),
    (16, 912, 2465, 'About midnight Joe awoke, and called the boys.', '大约半夜，乔醒了，叫醒了孩子们。'),
    (16, 912, 2466, 'There was a brooding oppressiveness in the air that seemed to bode something.', '空气里有种闷闷的感觉，好像要发生什么事。'),
    (16, 912, 2467, 'The boys huddled themselves together and sought the friendly companionship of the fire, though the dull dead heat of the breathless atmosphere was stifling.', '孩子们挤在一起，想靠近火堆取暖，虽然空气又闷又热，让人喘不过气。'),
    (16, 912, 2468, 'They sat still, intent and waiting.', '他们安静地坐着，认真地等待。'),
    (16, 912, 2469, 'The solemn hush continued.', '周围还是静悄悄的。'),
    (16, 912, 2470, 'Beyond the light of the fire everything was swallowed up in the blackness of darkness.', '火光外面一片漆黑，什么都看不见。'),
    (16, 912, 2471, 'Presently there came a quivering glow that vaguely revealed the foliage for a moment and then vanished.', '突然，一道微弱的光亮闪了一下，树叶模模糊糊地出现，又很快不见了。'),
    (16, 912, 2472, 'By and by another came, a little stronger.', '过了一会儿，又来了一道，亮了一些。'),
    (16, 912, 2473, 'Then another.', '然后又一道。'),
    (16, 912, 2474, 'Then a faint moan came sighing through the branches of the forest and the boys felt a fleeting breath upon their cheeks, and shuddered with the fancy that the Spirit of the Night had gone by.', '接着，一阵微风穿过树林，发出轻轻的叹息声。孩子们脸上感到一丝凉意，他们抖了一下，心想是不是黑夜精灵路过了。'),
    (16, 912, 2475, 'There was a pause.', '停了一会儿。'),
    (16, 912, 2476, 'Now a weird flash turned night into day and showed every little grassblade, separate and distinct, that grew about their feet.', '突然一道奇怪的闪电，把黑夜照得像白天一样亮，连他们脚边每一根小草都看得清清楚楚。'),
    (16, 912, 2477, 'And it showed three white, startled faces, too.', '它还照亮了三张发白、受惊的脸。'),
    (16, 912, 2478, 'A deep peal of thunder went rolling and tumbling down the heavens and lost itself in sullen rumblings in the distance.', '一声很响的雷声，轰隆隆地从天上滚下来，最后在远处变成了沉闷的低吼。'),
    (16, 912, 2479, 'A sweep of chilly air passed by, rustling all the leaves and snowing the flaky ashes broadcast about the fire.', '一阵冷风吹过，树叶沙沙作响，火堆里的灰烬像雪花一样四处飞散。'),
    (16, 912, 2480, 'Another fierce glare lit up the forest and an instant crash followed that seemed to rend the treetops right over the boys’ heads.', '又一道耀眼的闪电照亮了森林，紧接着一声巨响，好像要把孩子们头顶上的树梢都劈开一样。'),
    (16, 912, 2481, 'They clung together in terror, in the thick gloom that followed.', '接着，四周变得一片漆黑，他们害怕地紧紧抱在一起。'),
    (16, 912, 2482, 'A few big raindrops fell pattering upon the leaves.', '几滴大雨点噼里啪啦地落在树叶上。'),
    (16, 913, 2483, '“Quick! boys, go for the tent!” exclaimed Tom.', '“快！孩子们，去拿帐篷！”汤姆大声喊道。'),
    (16, 914, 2484, 'They sprang away, stumbling over roots and among vines in the dark, no two plunging in the same direction.', '他们跳起来就跑，在黑暗中被树根和藤蔓绊倒，每个人跑的方向都不一样。'),
    (16, 914, 2485, 'A furious blast roared through the trees, making everything sing as it went.', '一阵狂风怒吼着穿过树林，把所有东西都吹得呼呼作响。'),
    (16, 914, 2486, 'One blinding flash after another came, and peal on peal of deafening thunder.', '一道又一道刺眼的闪电接连出现，震耳欲聋的雷声一声连着一声。'),
    (16, 914, 2487, 'And now a drenching rain poured down and the rising hurricane drove it in sheets along the ground.', '接着，倾盆大雨哗哗地下，越来越大的暴风把它像水帘一样扫向地面。'),
    (16, 914, 2488, 'The boys cried out to each other, but the roaring wind and the booming thunderblasts drowned their voices utterly.', '孩子们互相大喊，可狂风呼啸，雷声轰鸣，完全盖住了他们的声音。'),
    (16, 914, 2489, 'However, one by one they straggled in at last and took shelter under the tent, cold, scared, and streaming with water; but to have company in misery seemed something to be grateful for.', '终于，他们一个接一个地跑回帐篷，又冷又怕，全身湿透；但能有伙伴在一起，就算再糟糕也觉得好一些。'),
    (16, 914, 2490, 'They could not talk, the old sail flapped so furiously, even if the other noises would have allowed them.', '他们没法说话，因为旧帐篷布被风吹得噼啪作响，即使没有其他噪音也听不清。'),
    (16, 914, 2491, 'The tempest rose higher and higher, and presently the sail tore loose from its fastenings and went winging away on the blast.', '暴风越来越大，不一会儿，帐篷布就被刮得脱离了固定绳，随风飞走了。'),
    (16, 914, 2492, 'The boys seized each others’ hands and fled, with many tumblings and bruises, to the shelter of a great oak that stood upon the riverbank.', '孩子们拉着手跑了，跌跌撞撞，身上青一块紫一块，跑到河边一棵大橡树下躲起来。'),
    (16, 914, 2493, 'Now the battle was at its highest.', '这时候，暴风雨达到了最猛烈的时候。'),
    (16, 914, 2494, 'Under the ceaseless conflagration of lightning that flamed in the skies, everything below stood out in cleancut and shadowless distinctness: the bending trees, the billowy river, white with foam, the driving spray of spumeflakes, the dim outlines of the high bluffs on the other side, glimpsed through the drifting cloudrack and the slanting veil of rain.', '闪电不停地在天上亮着，把下面的东西都照得清清楚楚，没有影子：弯曲的树，翻滚着白色浪花的河水，飞溅的水沫，还有远处高高的悬崖，在飘动的乌云和斜下的雨帘中隐约可见。'),
    (16, 914, 2495, 'Every little while some giant tree yielded the fight and fell crashing through the younger growth; and the unflagging thunderpeals came now in ear-splitting explosive bursts, keen and sharp, and unspeakably appalling.', '不一会儿，就有大树被风吹倒，轰隆一声砸向小树林；雷声也变得又尖又响，震耳欲聋，让人感到非常非常可怕。'),
    (16, 914, 2496, 'The storm culminated in one matchless effort that seemed likely to tear the island to pieces, burn it up, drown it to the treetops, blow it away, and deafen every creature in it, all at one and the same moment.', '暴风雨变得很大很大，好像要把小岛撕碎，烧掉，淹到树顶，吹跑，还要震聋小动物们，这些都好像同时发生。'),
    (16, 914, 2497, 'It was a wild night for homeless young heads to be out in.', '对那些没家的小脑袋瓜来说，那个晚上很可怕。'),
    (16, 915, 2498, 'But at last the battle was done, and the forces retired with weaker and weaker threatenings and grumblings, and peace resumed her sway.', '不过，大风雨终于停了，声音越来越小，世界又安静下来了。'),
    (16, 915, 2499, 'The boys went back to camp, a good deal awed; but they found there was still something to be thankful for, because the great sycamore, the shelter of their beds, was a ruin, now, blasted by the lightnings, and they were not under it when the catastrophe happened.', '男孩们回到营地，心里很害怕，但又觉得很幸运。因为那棵大大的梧桐树，平时他们睡在下面，现在被闪电劈坏了。还好，出事的时候他们没在树下。'),
    (16, 916, 2500, 'Everything in camp was drenched, the campfire as well; for they were but heedless lads, like their generation, and had made no provision against rain.', '营地里什么都湿透了，篝火也灭了。因为他们是粗心的小男孩，根本没准备怎么防雨。'),
    (16, 916, 2501, 'Here was matter for dismay, for they were soaked through and chilled.', '这下他们可惨了，全身湿冷湿冷的。'),
    (16, 916, 2502, 'They were eloquent in their distress; but they presently discovered that the fire had eaten so far up under the great log it had been built against (where it curved upward and separated itself from the ground), that a handbreadth or so of it had escaped wetting; so they patiently wrought until, with shreds and bark gathered from the under sides of sheltered logs, they coaxed the fire to burn again.', '他们很难过地抱怨着。不过，他们发现大木头底下有一点点没湿。于是，他们耐心找来一些干树皮和木屑，终于又把火点着了。'),
    (16, 916, 2503, 'Then they piled on great dead boughs till they had a roaring furnace, and were gladhearted once more.', '他们往火里加了很多大干树枝，火就烧得旺旺的，他们又高兴起来了。'),
    (16, 916, 2504, 'They dried their boiled ham and had a feast, and after that they sat by the fire and expanded and glorified their midnight adventure until morning, for there was not a dry spot to sleep on, anywhere around.', '他们烤干了煮好的火腿，饱饱地吃了一顿。然后，他们坐在火边，把夜里的冒险故事讲得好精彩，一直讲到天亮。因为周围根本没有一块干地方能睡觉。'),
    (16, 917, 2505, 'As the sun began to steal in upon the boys, drowsiness came over them, and they went out on the sandbar and lay down to sleep.', '太阳出来了，照在男孩们身上，他们就困了。他们走到沙滩上躺下睡着了。'),
    (16, 917, 2506, 'They got scorched out by and by, and drearily set about getting breakfast.', '没多久，他们就被晒热了，只好没精打采地起来做早饭。'),
    (16, 917, 2507, 'After the meal they felt rusty, and stiff-jointed, and a little homesick once more.', '吃完饭，他们觉得全身不舒服，关节也硬硬的，又有点想家了。'),
    (16, 917, 2508, 'Tom saw the signs, and fell to cheering up the pirates as well as he could.', '汤姆看到了这些迹象，就开始尽力安慰那些海盗们。'),
    (16, 917, 2509, 'But they cared nothing for marbles, or circus, or swimming, or anything.', '但他们对玩弹珠、看马戏、游泳什么的，都没兴趣了。'),
    (16, 917, 2510, 'He reminded them of the imposing secret, and raised a ray of cheer.', '他提起了那个很重要的秘密，让大家开心了一点。'),
    (16, 917, 2511, 'While it lasted, he got them interested in a new device.', '趁着大家心情好，他又让他们对一个新玩法有了兴趣。'),
    (16, 917, 2512, 'This was to knock off being pirates, for a while, and be Indians for a change.', '这个新玩法就是，暂时不当海盗了，改成玩印第安人。'),
    (16, 917, 2513, 'They were attracted by this idea; so it was not long before they were stripped, and striped from head to heel with black mud, like so many zebras—all of them chiefs, of course—and then they went tearing through the woods to attack an English settlement.', '他们觉得这个主意很好玩！很快，他们就脱了衣服，从头到脚涂满了黑泥，像一只只斑马——当然，他们都是大首领！然后，他们就冲进树林，去“攻击”一个英国村子。'),
    (16, 918, 2514, 'By and by they separated into three hostile tribes, and darted upon each other from ambush with dreadful warwhoops, and killed and scalped each other by thousands.', '后来，他们分成了三个“敌人部落”，从藏身的地方冲出来，大声喊着“战斗口号”，互相“杀死”对方，还“割下”了好多头皮。'),
    (16, 918, 2515, 'It was a gory day.', '那真是“血淋淋”的一天。'),
    (16, 918, 2516, 'Consequently it was an extremely satisfactory one.', '所以，他们玩得非常开心。'),
    (16, 919, 2517, 'They assembled in camp toward suppertime, hungry and happy; but now a difficulty arose—hostile Indians could not break the bread of hospitality together without first making peace, and this was a simple impossibility without smoking a pipe of peace.', '吃晚饭的时候，他们又饿又开心地回到营地。可是，一个难题来了——“敌人部落”的印第安人，不先“和好”，就不能一起吃饭。而要“和好”，就得一起抽“和平烟斗”。'),
    (16, 919, 2518, 'There was no other process that ever they had heard of.', '他们只知道这一个办法。'),
    (16, 919, 2519, 'Two of the savages almost wished they had remained pirates.', '其中两个“小野人”差点希望自己还是当海盗算了。'),
    (16, 919, 2520, 'However, there was no other way; so with such show of cheerfulness as they could muster they called for the pipe and took their whiff as it passed, in due form.', '没办法，没有别的办法了。于是，他们假装开心地要来了烟斗，按照规矩，一人抽了一口。'),
    (16, 920, 2521, 'And behold, they were glad they had gone into savagery, for they had gained something; they found that they could now smoke a little without having to go and hunt for a lost knife; they did not get sick enough to be seriously uncomfortable.', '瞧，他们很高兴自己成了“野人”，因为他们学会了一件事：现在他们可以抽一点烟，而不用担心会不舒服。他们一点也没觉得难受。'),
    (16, 920, 2522, 'They were not likely to fool away this high promise for lack of effort.', '他们可不会轻易放过这个好机会。'),
    (16, 920, 2523, 'No, they practised cautiously, after supper, with right fair success, and so they spent a jubilant evening.', '才不呢！晚饭后，他们小心地练习抽烟，还挺成功的。所以他们度过了一个非常开心的夜晚。'),
    (16, 920, 2524, 'They were prouder and happier in their new acquirement than they would have been in the scalping and skinning of the Six Nations.', '他们为自己学会的新本领感到非常骄傲和开心，比“剥掉六个民族的头皮”还要高兴。'),
    (16, 920, 2525, 'We will leave them to smoke and chatter and brag, since we have no further use for them at present.', '我们就让他们去抽烟、聊天、吹牛吧，我们现在不需要他们了。'),
    (17, 921, 2526, 'But there was no hilarity in the little town that same tranquil Saturday afternoon.', '不过，在那个安静的星期六下午，小镇里可一点也不热闹。'),
    (17, 921, 2527, 'The Harpers, and Aunt Polly’s family, were being put into mourning, with great grief and many tears.', '哈珀家和波莉姨妈的家人都在为他们哀悼，非常伤心，流了很多眼泪。'),
    (17, 921, 2528, 'An unusual quiet possessed the village, although it was ordinarily quiet enough, in all conscience.', '整个村子都非常安静，比平时还要安静。'),
    (17, 921, 2529, 'The villagers conducted their concerns with an absent air, and talked little; but they sighed often.', '村里的人们心不在焉，很少说话，却总是叹气。'),
    (17, 921, 2530, 'The Saturday holiday seemed a burden to the children.', '星期六的假期，孩子们觉得一点也不开心。'),
    (17, 921, 2531, 'They had no heart in their sports, and gradually gave them up.', '他们玩游戏都提不起精神，慢慢地就不玩了。'),
    (17, 922, 2532, 'In the afternoon Becky Thatcher found herself moping about the deserted schoolhouse yard, and feeling very melancholy.', '下午，贝琪·撒切尔发现自己独自在空荡荡的学校操场上闲逛，感觉非常难过。'),
    (17, 922, 2533, 'But she found nothing there to comfort her.', '可是，她什么也没找到来安慰自己。'),
    (17, 922, 2534, 'She soliloquized:', '她自言自语地说：'),
    (17, 923, 2535, '“Oh, if I only had a brass andiron-knob again!', '“唉，要是我还能找到一个黄铜火钳把手就好了！”'),
    (17, 923, 2536, 'But I haven’t got anything now to remember him by.”', '“可是我现在什么都没有，没法想起他了。”'),
    (17, 923, 2537, 'And she choked back a little sob.', '她努力忍住，没有哭出来。'),
    (17, 924, 2538, 'Presently she stopped, and said to herself:', '很快，她停下来，对自己说：'),
    (17, 925, 2539, '“It was right here.', '“就是在这里。'),
    (17, 925, 2540, 'Oh, if it was to do over again, I wouldn’t say that—I wouldn’t say it for the whole world.', '唉，如果能重新来过，我绝不会说那样的话——给我全世界我也不说。”'),
    (17, 925, 2541, 'But he’s gone now; I’ll never, never, never see him any more.”', '“可是他现在走了；我再也，再也，再也见不到他了。”'),
    (17, 926, 2542, 'This thought broke her down, and she wandered away, with tears rolling down her cheeks.', '想到这里，她伤心地哭起来，眼泪流下脸颊，然后就走开了。'),
    (17, 926, 2543, 'Then quite a group of boys and girls—playmates of Tom’s and Joe’s—came by, and stood looking over the paling fence and talking in reverent tones of how Tom did so-and-so the last time they saw him, and how Joe said this and that small trifle (pregnant with awful prophecy, as they could easily see now!)', '接着，一群男孩女孩——汤姆和乔的朋友们——走了过来。他们站在木栅栏边，用很尊敬的语气说着：上次见到汤姆时，汤姆做了什么事；乔又说了哪些小事（他们现在才明白，这些小事里藏着可怕的预言啊！）。'),
    (17, 926, 2544, '—and each speaker pointed out the exact spot where the lost lads stood at the time, and then added something like “and I was a-standing just so—just as I am now, and as if you was him—I was as close as that—and he smiled, just this way—and then something seemed to go all over me, like—awful, you know—and I never thought what it meant, of course, but I can see now!”', '——每个人都指着孩子们当时站的地方说：“我就站在这里，离他那么近。他就这样笑了一下，然后我全身都感觉怪怪的，很可怕。我那时不明白，但现在我懂了！”'),
    (17, 927, 2545, 'Then there was a dispute about who saw the dead boys last in life, and many claimed that dismal distinction, and offered evidences, more or less tampered with by the witness; and when it was ultimately decided who _did_ see the departed last, and exchanged the last words with them, the lucky parties took upon themselves a sort of sacred importance, and were gaped at and envied by all the rest.', '大家开始争论，谁是最后一个见到那些去世孩子的。很多人都说自己是，还拿出证据。最后大家决定了是谁，那些“幸运”的人就觉得自己很特别，大家都羡慕他们。'),
    (17, 927, 2546, 'One poor chap, who had no other grandeur to offer, said with tolerably manifest pride in the remembrance:', '有个可怜的小伙子，没什么可炫耀的，但他很自豪地回忆说：'),
    (17, 928, 2547, '“Well, Tom Sawyer he licked me once.”', '哎呀，汤姆·索亚他打过我一次。'),
    (17, 929, 2548, 'But that bid for glory was a failure.', '可是，他想得到这种荣耀的愿望失败了。'),
    (17, 929, 2549, 'Most of the boys could say that, and so that cheapened the distinction too much.', '因为很多孩子都能说出同样的话，所以这个“特别”就不那么特别了。'),
    (17, 929, 2550, 'The group loitered away, still recalling memories of the lost heroes, in awed voices.', '人们慢慢地散开了，他们还在小声地、很敬佩地回忆着那些离开的孩子们。'),
    (17, 930, 2551, 'When the Sunday-school hour was finished, the next morning, the bell began to toll, instead of ringing in the usual way.', '当主日学校小时过去了，第二天早上，钟敲响了，不是平时那种响法。'),
    (17, 930, 2552, 'It was a very still Sabbath, and the mournful sound seemed in keeping with the musing hush that lay upon nature.', '那天是安息日，很安静。这种悲伤的声音，就像大自然一样，让人安静地思考。'),
    (17, 930, 2553, 'The villagers began to gather, loitering a moment in the vestibule to converse in whispers about the sad event.', '村民们开始聚拢过来，他们在教堂入口处停了一会儿，小声地谈论着这件伤心事。'),
    (17, 930, 2554, 'But there was no whispering in the house; only the funereal rustling of dresses as the women gathered to their seats disturbed the silence there.', '但教堂里没有人说话；只有女人们坐下时，衣服发出的沙沙声打破了那里的安静。'),
    (17, 930, 2555, 'None could remember when the little church had been so full before.', '没有人记得这座小教堂以前什么时候坐过这么多人。'),
    (17, 930, 2556, 'There was finally a waiting pause, an expectant dumbness, and then Aunt Polly entered, followed by Sid and Mary, and they by the Harper family, all in deep black, and the whole congregation, the old minister as well, rose reverently and stood until the mourners were seated in the front pew.', '大家静静等了一会儿，没人说话。然后，波莉姨妈进来了，跟着是希德和玛丽，再是哈珀一家，他们都穿黑衣服。所有的人，连老牧师都恭敬地站着，直到那些伤心的人在第一排坐好。'),
    (17, 930, 2557, 'There was another communing silence, broken at intervals by muffled sobs, and then the minister spread his hands abroad and prayed.', '大家又安静下来，时不时传来低低的哭泣声。然后牧师伸开双手，开始祈祷。'),
    (17, 930, 2558, 'A moving hymn was sung, and the text followed: “I am the Resurrection and the Life.”', '接着，大家唱了一首感人的赞美诗，然后牧师念道：“我就是复活，我就是生命。”'),
    (17, 931, 2559, 'As the service proceeded, the clergyman drew such pictures of the graces, the winning ways, and the rare promise of the lost lads that every soul there, thinking he recognized these pictures, felt a pang in remembering that he had persistently blinded himself to them always before, and had as persistently seen only faults and flaws in the poor boys.', '仪式上，牧师讲起那些去世的孩子们有多好、多可爱、多有本事。在场的人都觉得自己认识这样的孩子，心里很痛，因为他们以前老是只看到这些孩子的缺点，没看到他们的好。'),
    (17, 931, 2560, 'The minister related many a touching incident in the lives of the departed, too, which illustrated their sweet, generous natures, and the people could easily see, now, how noble and beautiful those episodes were, and remembered with grief that at the time they occurred they had seemed rank rascalities, well deserving of the cowhide.', '牧师还讲了很多去世孩子感人的小故事，这些故事都说明他们很善良，很大方。现在大家才明白，这些事原来很美好，但伤心的是，他们当时却觉得这些都是坏事，觉得要狠狠地打一顿才行。'),
    (17, 931, 2561, 'The congregation became more and more moved, as the pathetic tale went on, till at last the whole company broke down and joined the weeping mourners in a chorus of anguished sobs, the preacher himself giving way to his feelings, and crying in the pulpit.', '随着这些感人故事的讲述，教徒们越来越感动，最后所有人都忍不住了，和哭泣的人们一起放声大哭起来。连牧师也控制不住自己的感情，在讲台上哭了起来。'),
    (17, 932, 2562, 'There was a rustle in the gallery, which nobody noticed; a moment later the church door creaked; the minister raised his streaming eyes above his handkerchief, and stood transfixed!', '阁楼上传来一阵沙沙声，没有人注意到；过了一会儿，教堂的门“吱呀”一声开了；牧师从手帕上方抬起他流着泪的眼睛，惊讶地呆住了！'),
    (17, 932, 2563, 'First one and then another pair of eyes followed the minister’s, and then almost with one impulse the congregation rose and stared while the three dead boys came marching up the aisle, Tom in the lead, Joe next, and Huck, a ruin of drooping rags, sneaking sheepishly in the rear!', '大家先是一个人，然后是另一个人，跟着牧师的目光看。然后，所有人都一起站起来，惊讶地盯着看。只见三个“死掉”的男孩大步走过走道，汤姆走在最前面，乔在中间，而哈克衣服破破烂烂地，不好意思地跟在最后面！'),
    (17, 932, 2564, 'They had been hid in the unused gallery listening to their own funeral sermon!', '他们一直躲在没人的楼上看台，听着大家给他们办的葬礼！'),
    (17, 933, 2565, 'Aunt Polly, Mary, and the Harpers threw themselves upon their restored ones, smothered them with kisses and poured out thanksgivings, while poor Huck stood abashed and uncomfortable, not knowing exactly what to do or where to hide from so many unwelcoming eyes.', '波莉姨妈、玛丽和哈珀一家冲向了他们找回来的亲人，抱着他们亲个不停，说了很多感谢的话。可怜的哈克却很不好意思，站在那里很不舒服。他不知道该做什么，也不知道怎么躲开那些不欢迎他的目光。'),
    (17, 933, 2566, 'He wavered, and started to slink away, but Tom seized him and said:', '他犹豫了一下，想溜走，但是汤姆抓住了他，说：'),
    (17, 934, 2567, '“Aunt Polly, it ain’t fair.', '“波莉姨妈, it ain’t fair.'),
    (17, 934, 2568, 'Somebody’s got to be glad to see Huck.”', '总得有人高兴见到哈克吧。'),
    (17, 935, 2569, '“And so they shall.', '他们会的。'),
    (17, 935, 2570, 'I’m glad to see him, poor motherless thing!”', '我真高兴见到他，这个没妈妈的孩子真可怜！'),
    (17, 935, 2571, 'And the loving attentions Aunt Polly lavished upon him were the one thing capable of making him more uncomfortable than he was before.', '而波莉姨妈对他那么多的爱和关心，反而让他比以前更不舒服了。'),
    (17, 936, 2572, 'Suddenly the minister shouted at the top of his voice: “Praise God from whom all blessings flow—_sing_!', '牧师突然大声喊：“感谢上帝，他给了我们所有的好东西——快唱啊！'),
    (17, 936, 2573, '—and put your hearts in it!”', '——要用心唱哦！”'),
    (17, 937, 2574, 'And they did.', '他们真的唱了。'),
    (17, 937, 2575, 'Old Hundred swelled up with a triumphant burst, and while it shook the rafters Tom Sawyer the Pirate looked around upon the envying juveniles about him and confessed in his heart that this was the proudest moment of his life.', '《古老百岁歌》雄壮地响起来，震得屋顶都抖了。海盗汤姆·索亚看着身边那些羡慕他的孩子们，心里觉得这是他一生中最骄傲的时刻。'),
    (17, 938, 2576, 'As the “sold” congregation trooped out they said they would almost be willing to be made ridiculous again to hear Old Hundred sung like that once more.', '大家被“骗”了，走出教堂时都说，就算再被笑一次，也想再听一次那样的歌。'),
    (17, 939, 2577, 'Tom got more cuffs and kisses that day—according to Aunt Polly’s varying moods—than he had earned before in a year; and he hardly knew which expressed the most gratefulness to God and affection for himself.', '那天，汤姆挨的打和得到的吻，随着波莉姨妈的心情变化，比他过去一年里得到的都多。他都不知道哪种方式表达了更多对上帝的感谢和对他的爱。'),
    (18, 940, 2578, 'That was Tom’s great secret—the scheme to return home with his brother pirates and attend their own funerals.', '那是汤姆的大秘密——他计划和他的海盗兄弟们一起回家，去参加他们自己的葬礼。'),
    (18, 940, 2579, 'They had paddled over to the Missouri shore on a log, at dusk on Saturday, landing five or six miles below the village; they had slept in the woods at the edge of the town till nearly daylight, and had then crept through back lanes and alleys and finished their sleep in the gallery of the church among a chaos of invalided benches.', '他们周六晚上，划着木头过河到密苏里岸边，在离村子很远的地方上了岸。他们在镇子边上的小树林里睡了一觉，天快亮才醒。然后，他们偷偷地穿过小路，到教堂楼上，在一堆坏椅子中间，继续睡觉。'),
    (18, 941, 2580, 'At breakfast, Monday morning, Aunt Polly and Mary were very loving to Tom, and very attentive to his wants.', '周一早上吃早饭的时候，波莉姨妈和玛丽对汤姆特别好，也很关心他想要什么。'),
    (18, 941, 2581, 'There was an unusual amount of talk.', '大家说了很多话。'),
    (18, 941, 2582, 'In the course of it Aunt Polly said:', '说着说着，波莉姨妈说：'),
    (18, 942, 2583, '“Well, I don’t say it wasn’t a fine joke, Tom, to keep everybody suffering ’most a week so you boys had a good time, but it is a pity you could be so hard-hearted as to let me suffer so.', '嗯，汤姆，我不是说这不是个好玩儿的玩笑。但你们为了玩，让大家难过了快一个星期，还那么狠心让我这么伤心，真是不应该。'),
    (18, 942, 2584, 'If you could come over on a log to go to your funeral, you could have come over and give me a hint some way that you warn’t dead, but only run off.”', '既然你能划着木头来看自己的葬礼，那你就应该过来告诉我，你没死，只是跑掉了！'),
    (18, 943, 2585, '“Yes, you could have done that, Tom,” said Mary; “and I believe you would if you had thought of it.”', '“是啊,你本可以那么做的,汤姆,”玛丽说,“我相信,只要你想到了,你就会那么做的。”'),
    (18, 944, 2586, '“Would you, Tom?” said Aunt Polly, her face lighting wistfully. “Say, now, would you, if you’d thought of it?”', '“你真会吗,汤姆?”波莉姨妈说,脸上露出渴望的神色,“说呀,要是你当时想到了,你真会那么做吗?”'),
    (18, 945, 2587, '“I—well, I don’t know.', '我——嗯，我不知道。'),
    (18, 945, 2588, '’Twould ’a’ spoiled everything.”', '那样会把所有事都弄糟的。'),
    (18, 946, 2589, '“Tom, I hoped you loved me that much,” said Aunt Polly, with a grieved tone that discomforted the boy.', '“汤姆,我原本盼着你有那么爱我呢,”波莉姨妈说,语气里的伤心让这孩子很不好受。'),
    (18, 946, 2590, '“It would have been something if you’d cared enough to _think_ of it, even if you didn’t _do_ it.”', '如果你能多想想，就算没做，那也算你关心啊。'),
    (18, 947, 2591, '“Now, auntie, that ain’t any harm,” pleaded Mary; “it’s only Tom’s giddy way—he is always in such a rush that he never thinks of anything.”', '“姑妈,这没什么不好啦,”玛丽劝道,“这只是汤姆冒冒失失的性子——他总是急急忙忙,什么都想不到。”'),
    (18, 948, 2592, '“More’s the pity.', '真可惜啊。'),
    (18, 948, 2593, 'Sid would have thought.', '希德会想到的。'),
    (18, 948, 2594, 'And Sid would have come and _done_ it, too.', '而且希德也会来做这件事的。'),
    (18, 948, 2595, 'Tom, you’ll look back, some day, when it’s too late, and wish you’d cared a little more for me when it would have cost you so little.”', '汤姆，总有一天你会后悔的，等太晚了，你会希望当时能多关心我一点点，那时候做起来多容易啊。”'),
    (18, 949, 2596, '“Now, auntie, you know I do care for you,” said Tom.', '“姑妈,你知道我是关心你的呀,”汤姆说。'),
    (18, 950, 2597, '“I’d know it better if you acted more like it.”', '如果你表现得更好一点，我就知道了。'),
    (18, 951, 2598, '“I wish now I’d thought,” said Tom, with a repentant tone; “but I dreamt about you, anyway.', '“我现在真希望我当时想到了,”汤姆懊悔地说,“不过,我到底还是梦见你了呀。'),
    (18, 951, 2599, 'That’s something, ain’t it?”', '那也算做了点事，对吧？'),
    (18, 952, 2600, '“It ain’t much—a cat does that much—but it’s better than nothing.', '那不算多——猫都能做到——但总比没有好。'),
    (18, 952, 2601, 'What did you dream?”', '你梦到什么了？'),
    (18, 953, 2602, '“Why, Wednesday night I dreamt that you was sitting over there by the bed, and Sid was sitting by the woodbox, and Mary next to him.”', '哎呀，星期三晚上我梦到你坐在床边，希德坐在柴火箱旁边，玛丽坐在他旁边。'),
    (18, 954, 2603, '“Well, so we did.', '嗯，我们确实梦到了。'),
    (18, 954, 2604, 'So we always do.', '我们总是这样。'),
    (18, 954, 2605, 'I’m glad your dreams could take even that much trouble about us.”', '真高兴你的梦还能想着我们。'),
    (18, 955, 2606, '“And I dreamt that Joe Harper’s mother was here.”', '我还梦到乔·哈珀的妈妈在这里。'),
    (18, 956, 2607, '“Why, she was here!', '哎呀，她在这儿呢！'),
    (18, 956, 2608, 'Did you dream any more?”', '你还梦到别的了吗？'),
    (18, 957, 2609, '“Oh, lots.', '哦，很多。'),
    (18, 957, 2610, 'But it’s so dim, now.”', '但是现在都记不清了。'),
    (18, 958, 2611, '“Well, try to recollect—can’t you?”', '“嗯，你再想想看，好不好？”'),
    (18, 959, 2612, '“Somehow it seems to me that the wind—the wind blowed the—the—”', '“好像是风——风吹灭了——那个——”'),
    (18, 960, 2613, '“Try harder, Tom!', '“再努力想想，汤姆!'),
    (18, 960, 2614, 'The wind did blow something.', '风确实吹动了什么东西。'),
    (18, 960, 2615, 'Come!”', '快说！”'),
    (18, 961, 2616, 'Tom pressed his fingers on his forehead an anxious minute, and then said:', '汤姆紧张地用手指按着额头想了一会儿，然后说：'),
    (18, 962, 2617, '“I’ve got it now!', '“我想起来了！'),
    (18, 962, 2618, 'I’ve got it now!', '我想起来了！'),
    (18, 962, 2619, 'It blowed the candle!”', '是风把蜡烛吹灭了！”'),
    (18, 963, 2620, '“Mercy on us!', '“天哪！'),
    (18, 963, 2621, 'Go on, Tom—go on!”', '继续说，汤姆——继续说！”'),
    (18, 964, 2622, '“And it seems to me that you said, ‘Why, I believe that that door—’”', '“好像你说过，‘哎呀，我相信那扇门——’”'),
    (18, 965, 2623, '“Go _on_, Tom!”', '“继续说，汤姆！”'),
    (18, 966, 2624, '“Just let me study a moment—just a moment.', '“让我再想想——就一小会儿。'),
    (18, 966, 2625, 'Oh, yes—you said you believed the door was open.”', '哦，对了——你说你相信门是开着的。”'),
    (18, 967, 2626, '“As I’m sitting here, I did!', '“我坐在这里，我确实说过了！'),
    (18, 967, 2627, 'Didn’t I, Mary!', '是不是，玛丽！'),
    (18, 967, 2628, 'Go on!”', '继续说！”'),
    (18, 968, 2629, '“And then—and then—well I won’t be certain, but it seems like as if you made Sid go and—and—”', '“然后——然后——我不是很确定，但好像你让希德去——去——”'),
    (18, 969, 2630, '“Well?', '“嗯？'),
    (18, 969, 2631, 'Well?', '嗯？'),
    (18, 969, 2632, 'What did I make him do, Tom?', '我让他做了什么，汤姆？'),
    (18, 969, 2633, 'What did I make him do?”', '我让他做了什么？”'),
    (18, 970, 2634, '“You made him—you—Oh, you made him shut it.”', '“你让他——你——哦，你让他把它关上。”'),
    (18, 971, 2635, '“Well, for the land’s sake!', '“天哪！'),
    (18, 971, 2636, 'I never heard the beat of that in all my days!', '我这辈子都没听过这么稀奇的事！'),
    (18, 971, 2637, 'Don’t tell _me_ there ain’t anything in dreams, any more.', '别再跟我说梦都是假的了。'),
    (18, 971, 2638, 'Sereny Harper shall know of this before I’m an hour older.', '我要马上去告诉塞伦尼·哈珀这件事。'),
    (18, 971, 2639, 'I’d like to see her get around _this_ with her rubbage ’bout superstition.', '我倒要看看她怎么用她那些迷信的说法来解释这个。'),
    (18, 971, 2640, 'Go on, Tom!”', '继续说，汤姆！”'),
    (18, 972, 2641, '“Oh, it’s all getting just as bright as day, now.', '“哦，现在天都亮了。'),
    (18, 972, 2642, 'Next you said I warn’t _bad_, only mischeevous and harum-scarum, and not any more responsible than—than—I think it was a colt, or something.”', '接着你说我不是坏孩子，只是淘气，还很野，跟小马驹一样不让人省心。”'),
    (18, 973, 2643, '“And so it was!', '“是啊，就是这样！'),
    (18, 973, 2644, 'Well, goodness gracious!', '哎呀，天哪！'),
    (18, 973, 2645, 'Go on, Tom!”', '快说啊，汤姆！”'),
    (18, 974, 2646, '“And then you began to cry.”', '“然后你就哭了。”'),
    (18, 975, 2647, '“So I did.', '“是啊，我哭了。'),
    (18, 975, 2648, 'So I did.', '是啊，我哭了。'),
    (18, 975, 2649, 'Not the first time, neither.', '也不是第一次了。'),
    (18, 975, 2650, 'And then—”', '然后—”'),
    (18, 976, 2651, '“Then Mrs. Harper she began to cry, and said Joe was just the same, and she wished she hadn’t whipped him for taking cream when she’d throwed it out her own self—”', '“然后哈珀太太也哭了，她说乔也是这样，还说她不该因为乔偷吃奶油就打他，因为她自己把奶油倒掉了—”'),
    (18, 977, 2652, '“Tom!', '“汤姆！'),
    (18, 977, 2653, 'The sperrit was upon you!', '你像被神灵附体一样！'),
    (18, 977, 2654, 'You was a prophesying—that’s what you was doing!', '你简直就是在预言—你就是在预言！'),
    (18, 977, 2655, 'Land alive, go on, Tom!”', '天哪，快说啊，汤姆！”'),
    (18, 978, 2656, '“Then Sid he said—he said—”', '“然后希德他说—他说—”'),
    (18, 979, 2657, '“I don’t think I said anything,” said Sid.', '“我想我什么也没说。”希德说。'),
    (18, 980, 2658, '“Yes you did, Sid,” said Mary.', '“不，你说了，希德。”玛丽说。'),
    (18, 981, 2659, '“Shut your heads and let Tom go on!', '“都闭嘴，让汤姆继续说！'),
    (18, 981, 2660, 'What did he say, Tom?”', '他说什么了，汤姆？”'),
    (18, 982, 2661, '“He said—I _think_ he said he hoped I was better off where I was gone to, but if I’d been better sometimes—”', '“他说—我想他说他希望我去了那个地方会过得更好，但如果我平时能表现得好一点—”'),
    (18, 983, 2662, '“_There_, d’you hear that!', '“听，你们听到了吗！'),
    (18, 983, 2663, 'It was his very words!”', '他就是这么说的！”'),
    (18, 984, 2664, '“And you shut him up sharp.”', '“然后你立刻让他闭嘴了。”'),
    (18, 985, 2665, '“I lay I did!', '“我肯定做了！'),
    (18, 985, 2666, 'There must ’a’ been an angel there.', '那里一定有天使。'),
    (18, 985, 2667, 'There _was_ an angel there, somewheres!”', '那里真的有天使，就在某个地方！”'),
    (18, 986, 2668, '“And Mrs. Harper told about Joe scaring her with a firecracker, and you told about Peter and the Pain-killer—”', '“然后哈珀太太说乔用鞭炮吓唬她的事，你说了彼得和止痛药的事—”'),
    (18, 987, 2669, '“Just as true as I live!”', '“千真万确！”'),
    (18, 988, 2670, '“And then there was a whole lot of talk ’bout dragging the river for us, and ’bout having the funeral Sunday, and then you and old Miss Harper hugged and cried, and she went.”', '“然后大家说了很多，说要去河里打捞我们，说周日要为我们举行葬礼，然后你和老哈珀太太抱在一起哭了，她就走了。”'),
    (18, 989, 2671, '“It happened just so!', '“就是这样！'),
    (18, 989, 2672, 'It happened just so, as sure as I’m a-sitting in these very tracks.', '就是这样，我坐在这儿，是真的！'),
    (18, 989, 2673, 'Tom, you couldn’t told it more like if you’d ’a’ seen it!', '“汤姆，你说的真像，就像你亲眼看到了！'),
    (18, 989, 2674, 'And then what?', '然后呢？'),
    (18, 989, 2675, 'Go on, Tom!”', '继续说，汤姆！”'),
    (18, 990, 2676, '“Then I thought you prayed for me—and I could see you and hear every word you said.', '“然后我想，你为我祷告了——我能看见你，听到你说的每一句话。'),
    (18, 990, 2677, 'And you went to bed, and I was so sorry that I took and wrote on a piece of sycamore bark, ‘We ain’t dead—we are only off being pirates,’ and put it on the table by the candle; and then you looked so good, laying there asleep, that I thought I went and leaned over and kissed you on the lips.”', '你睡觉了，我很难过。我就在一块树皮上写：‘我们没死，只是去当海盗了。’把它放在蜡烛旁的桌上。你睡着了，看起来真好，我好像走过去，弯下腰亲了亲你的嘴。”'),
    (18, 991, 2678, '“Did you, Tom, _did_ you!', '“你亲了，汤姆，你真的亲了！'),
    (18, 991, 2679, 'I just forgive you everything for that!”', '就冲这个，我什么都原谅你了！”'),
    (18, 991, 2680, 'And she seized the boy in a crushing embrace that made him feel like the guiltiest of villains.', '她紧紧抱住男孩，让他觉得自己是世界上最坏的坏蛋。'),
    (18, 992, 2681, '“It was very kind, even though it was only a—dream,” Sid soliloquized just audibly.', '“这很善良，即使只是一个——梦，”希德轻轻地自言自语。'),
    (18, 993, 2682, '“Shut up, Sid!', '“闭嘴，希德！'),
    (18, 993, 2683, 'A body does just the same in a dream as he’d do if he was awake.', '人在梦里做的事，和醒着做的事是一样的。'),
    (18, 993, 2684, 'Here’s a big Milum apple I’ve been saving for you, Tom, if you was ever found again—now go ’long to school.', '汤姆，这是我一直为你留着的大米勒姆苹果，如果你能再被找到的话——现在去学校吧。'),
    (18, 993, 2685, 'I’m thankful to the good God and Father of us all I’ve got you back, that’s long-suffering and merciful to them that believe on Him and keep His word, though goodness knows I’m unworthy of it, but if only the worthy ones got His blessings and had His hand to help them over the rough places, there’s few enough would smile here or ever enter into His rest when the long night comes.', '我感谢好上帝，把我找回来了。他对相信他的人一直很耐心，很仁慈。虽然我知道自己不配，但是如果只有很好的人才能得到他的帮助，那很少人能在这里开心笑了。'),
    (18, 993, 2686, 'Go ’long Sid, Mary, Tom—take yourselves off—you’ve hendered me long enough.”', '去吧，希德，玛丽，汤姆——你们走吧——你们耽误我够久了。”'),
    (18, 994, 2687, 'The children left for school, and the old lady to call on Mrs. Harper and vanquish her realism with Tom’s marvellous dream.', '孩子们去上学了，老太太去拜访哈珀太太，想用汤姆的奇妙梦想让她相信。'),
    (18, 994, 2688, 'Sid had better judgment than to utter the thought that was in his mind as he left the house.', '希德很聪明，他没有把离开家时心里的想法说出来。'),
    (18, 994, 2689, 'It was this: “Pretty thin—as long a dream as that, without any mistakes in it!”', '他的想法是：“太假了——那么长的梦，竟然一点错都没有！”'),
    (18, 995, 2690, 'What a hero Tom was become, now!', '汤姆现在真是个大英雄啊！'),
    (18, 995, 2691, 'He did not go skipping and prancing, but moved with a dignified swagger as became a pirate who felt that the public eye was on him.', '他没有蹦蹦跳跳，而是迈着神气的步子，就像一个觉得自己被大家盯着的海盗。'),
    (18, 995, 2692, 'And indeed it was; he tried not to seem to see the looks or hear the remarks as he passed along, but they were food and drink to him.', '确实如此；他假装没看到那些眼神，也没听到那些议论，但这些都让他很高兴。'),
    (18, 995, 2693, 'Smaller boys than himself flocked at his heels, as proud to be seen with him, and tolerated by him, as if he had been the drummer at the head of a procession or the elephant leading a menagerie into town.', '比他小的男孩们都跟在他后面，能和他一起出现，被他“允许”，他们都觉得很骄傲，就像他是游行队伍的鼓手，或者带领马戏团大象进城的人。'),
    (18, 995, 2694, 'Boys of his own size pretended not to know he had been away at all; but they were consuming with envy, nevertheless.', '和他一样大的男孩假装根本不知道他之前离开了；但他们心里仍然嫉妒得不得了。'),
    (18, 995, 2695, 'They would have given anything to have that swarthy sun-tanned skin of his, and his glittering notoriety; and Tom would not have parted with either for a circus.', '他们愿意付出任何代价，只为了拥有他那晒黑的皮肤，和他的英雄名声；而汤姆呢，就算用一个马戏团来换，他也不会放弃这些。'),
    (18, 996, 2696, 'At school the children made so much of him and of Joe, and delivered such eloquent admiration from their eyes, that the two heroes were not long in becoming insufferably “stuck-up.”', '在学校，孩子们非常看重他和乔，用眼睛表达了那么多的赞美，结果没多久，这两个英雄就变得非常“骄傲自大”了。'),
    (18, 996, 2697, 'They began to tell their adventures to hungry listeners—but they only began; it was not a thing likely to have an end, with imaginations like theirs to furnish material.', '他们开始把自己的冒险故事讲给那些很想听的孩子们——但他们才刚开始；这故事根本不可能讲完，因为他们的想象力太丰富了，总有新的内容。'),
    (18, 996, 2698, 'And finally, when they got out their pipes and went serenely puffing around, the very summit of glory was reached.', '最后，当他们拿出烟斗，悠闲地吸着烟四处走动时，他们的荣耀达到了最高点。'),
    (18, 997, 2699, 'Tom decided that he could be independent of Becky Thatcher now.', '汤姆觉得他现在可以不用靠贝琪·撒切尔了。'),
    (18, 997, 2700, 'Glory was sufficient.', '荣耀就足够了。'),
    (18, 997, 2701, 'He would live for glory.', '他想变得很了不起。'),
    (18, 997, 2702, 'Now that he was distinguished, maybe she would be wanting to “make up.”', '现在他变得很厉害了，也许她会想跟他和好。'),
    (18, 997, 2703, 'Well, let her—she should see that he could be as indifferent as some other people.', '嗯，让她来吧——她应该知道，他也能像别人一样，装作不在乎。'),
    (18, 997, 2704, 'Presently she arrived.', '她很快就来了。'),
    (18, 997, 2705, 'Tom pretended not to see her.', '汤姆假装没看到她。'),
    (18, 997, 2706, 'He moved away and joined a group of boys and girls and began to talk.', '他走开了，走到一群小朋友中间，开始和他们说话。'),
    (18, 997, 2707, 'Soon he observed that she was tripping gayly back and forth with flushed face and dancing eyes, pretending to be busy chasing schoolmates, and screaming with laughter when she made a capture; but he noticed that she always made her captures in his vicinity, and that she seemed to cast a conscious eye in his direction at such times, too.', '很快他就看到她开心地跑来跑去，脸红扑扑的，眼睛亮亮的。她假装在追着同学玩，抓到人就大声笑。但他发现她总是在他旁边抓人，而且每次抓到人，好像都会偷偷看他一眼。'),
    (18, 997, 2708, 'It gratified all the vicious vanity that was in him; and so, instead of winning him, it only “set him up” the more and made him the more diligent to avoid betraying that he knew she was about.', '这让他心里暗暗得意。这不但没有让她打动他，反而让他更骄傲，更努力地假装不知道她在身边。'),
    (18, 997, 2709, 'Presently she gave over skylarking, and moved irresolutely about, sighing once or twice and glancing furtively and wistfully toward Tom.', '不一会儿，她不玩了，没精打采地走来走去，叹了两口气，偷偷地、很希望地看向汤姆。'),
    (18, 997, 2710, 'Then she observed that now Tom was talking more particularly to Amy Lawrence than to any one else.', '然后她看到，现在汤姆只跟艾米·劳伦斯说话，不跟别人说。'),
    (18, 997, 2711, 'She felt a sharp pang and grew disturbed and uneasy at once.', '她心里很难受，马上就觉得不开心、不舒服。'),
    (18, 997, 2712, 'She tried to go away, but her feet were treacherous, and carried her to the group instead.', '她想走开，可是脚不听话，反而把她带到了那个小组旁边。'),
    (18, 997, 2713, 'She said to a girl almost at Tom’s elbow—with sham vivacity:', '她对一个就在汤姆旁边的女孩子说，假装自己很有精神：'),
    (18, 998, 2714, '“Why, Mary Austin! you bad girl, why didn’t you come to Sunday-school?”', '“哎呀，玛丽奥斯汀！你这个小坏蛋，怎么没来找主日学校呢？”'),
    (18, 999, 2715, '“I did come—didn’t you see me?”', '“我来了呀——你没看到我吗？”'),
    (18, 1000, 2716, '“Why, no!', '“哎呀，没有啊！'),
    (18, 1000, 2717, 'Did you?', '你来了吗？'),
    (18, 1000, 2718, 'Where did you sit?”', '你坐在哪里呀？”'),
    (18, 1001, 2719, '“I was in Miss Peters’ class, where I always go.', '“我在彼得斯老师的班上，我总是在那里上课的呀。'),
    (18, 1001, 2720, 'I saw _you_.”', '我看到了你！”'),
    (18, 1002, 2721, '“Did you?', '“是吗？'),
    (18, 1002, 2722, 'Why, it’s funny I didn’t see you.', '真奇怪我没看到你。'),
    (18, 1002, 2723, 'I wanted to tell you about the picnic.”', '我想跟你说野餐的事儿。”'),
    (18, 1003, 2724, '“Oh, that’s jolly.', '“哦，那太好了！'),
    (18, 1003, 2725, 'Who’s going to give it?”', '谁来办呢？”'),
    (18, 1004, 2726, '“My ma’s going to let me have one.”', '“我妈妈要给我办一个野餐。”'),
    (18, 1005, 2727, '“Oh, goody; I hope she’ll let _me_ come.”', '“哦，太好了！我希望她能让我去。”'),
    (18, 1006, 2728, '“Well, she will.', '“她会让你来的。'),
    (18, 1006, 2729, 'The picnic’s for me.', '这个野餐是为我办的。'),
    (18, 1006, 2730, 'She’ll let anybody come that I want, and I want you.”', '我想要谁来，她就让谁来，我希望你来。”'),
    (18, 1007, 2731, '“That’s ever so nice.', '“那可真好。'),
    (18, 1007, 2732, 'When is it going to be?”', '什么时候去呢？”'),
    (18, 1008, 2733, '“By and by.', '“过一阵子吧。'),
    (18, 1008, 2734, 'Maybe about vacation.”', '也许是放假的时候。”'),
    (18, 1009, 2735, '“Oh, won’t it be fun!', '“噢，那一定很好玩！'),
    (18, 1009, 2736, 'You going to have all the girls and boys?”', '你要把所有的男孩和女孩都叫上吗？”'),
    (18, 1010, 2737, '“Yes, every one that’s friends to me—or wants to be”; and she glanced ever so furtively at Tom, but he talked right along to Amy Lawrence about the terrible storm on the island, and how the lightning tore the great sycamore tree “all to flinders” while he was “standing within three feet of it.”', '“是的，所有是我的朋友，或者想成为我朋友的人都来。”她偷偷地看了汤姆一眼，但他还是不停地和艾米·劳伦斯说岛上可怕的暴风雨，说闪电怎么把那棵大梧桐树劈得粉碎，当时他离树只有三英尺远。”'),
    (18, 1011, 2738, '“Oh, may I come?” said Grace Miller.', '“噢，我能来吗？”格蕾丝·米勒说。'),
    (18, 1012, 2739, '“Yes.”', '“能。”'),
    (18, 1013, 2740, '“And me?” said Sally Rogers.', '“还有我呢？”莎莉·罗杰斯说。'),
    (18, 1014, 2741, '“Yes.”', '“能。”'),
    (18, 1015, 2742, '“And me, too?” said Susy Harper. “And Joe?”', '“还有我吗？”苏西·哈珀说。“乔呢？”'),
    (18, 1016, 2743, '“Yes.”', '“能。”'),
    (18, 1017, 2744, 'And so on, with clapping of joyful hands till all the group had begged for invitations but Tom and Amy.', '就这样，大家开心地拍着手，除了汤姆和艾米，所有人都求着要来参加。'),
    (18, 1017, 2745, 'Then Tom turned coolly away, still talking, and took Amy with him.', '然后汤姆冷冷地转过身，还在说着话，带着艾米走了。'),
    (18, 1017, 2746, 'Becky’s lips trembled and the tears came to her eyes; she hid these signs with a forced gayety and went on chattering, but the life had gone out of the picnic, now, and out of everything else; she got away as soon as she could and hid herself and had what her sex call “a good cry.”', '贝琪的嘴唇颤抖了，眼泪涌了出来；她强装开心，继续说笑，来掩饰这些。但野餐的乐趣，还有其他所有的乐趣，一下子都没有了。她赶紧跑开，找个地方躲起来，好好地哭了一场。'),
    (18, 1017, 2747, 'Then she sat moody, with wounded pride, till the bell rang.', '接着，她心里很受伤，闷闷不乐地坐着，直到铃声响起。'),
    (18, 1017, 2748, 'She roused up, now, with a vindictive cast in her eye, and gave her plaited tails a shake and said she knew what _she’d_ do.', '她一下子振作起来，眼里闪着不服气的光芒，甩了甩她的辫子，说她知道自己要怎么做了。'),
    (18, 1018, 2749, 'At recess Tom continued his flirtation with Amy with jubilant self-satisfaction.', '课间休息时，汤姆继续和艾米亲近，心里得意洋洋。'),
    (18, 1018, 2750, 'And he kept drifting about to find Becky and lacerate her with the performance.', '他一直在附近转悠，想找到贝琪，用这样的举动去伤害她。'),
    (18, 1018, 2751, 'At last he spied her, but there was a sudden falling of his mercury.', '他终于看见了她，但他突然不高兴了。'),
    (18, 1018, 2752, 'She was sitting cosily on a little bench behind the schoolhouse looking at a picture-book with Alfred Temple—and so absorbed were they, and their heads so close together over the book, that they did not seem to be conscious of anything in the world besides.', '她舒服地坐在学校后面的一张小板凳上，正和阿尔弗雷德·坦普尔一起看一本图画书。他们看得那么入迷，头靠得那么近，好像世界上除了他们，什么都没有了。'),
    (18, 1018, 2753, 'Jealousy ran red-hot through Tom’s veins.', '汤姆心里嫉妒得厉害。'),
    (18, 1018, 2754, 'He began to hate himself for throwing away the chance Becky had offered for a reconciliation.', '他开始讨厌自己，因为他错过了贝琪本来给了他和好的机会。'),
    (18, 1018, 2755, 'He called himself a fool, and all the hard names he could think of.', '他骂自己是个笨蛋，还想出了所有能想到的坏词骂自己。'),
    (18, 1018, 2756, 'He wanted to cry with vexation.', '他气得想哭。'),
    (18, 1018, 2757, 'Amy chatted happily along, as they walked, for her heart was singing, but Tom’s tongue had lost its function.', '艾米开心地一路走一路聊着天，因为她心里很高兴，但汤姆却一句话也说不出来了。'),
    (18, 1018, 2758, 'He did not hear what Amy was saying, and whenever she paused expectantly he could only stammer an awkward assent, which was as often misplaced as otherwise.', '他根本没听艾米在说什么，每当艾米停下来等着他回答的时候，他只会结结巴巴地胡乱答应一声，而且常常答非所问。'),
    (18, 1018, 2759, 'He kept drifting to the rear of the schoolhouse, again and again, to sear his eyeballs with the hateful spectacle there.', '他一次又一次地往学校后面走去，去看看那里让他生气的一幕。'),
    (18, 1018, 2760, 'He could not help it.', '他忍不住。'),
    (18, 1018, 2761, 'And it maddened him to see, as he thought he saw, that Becky Thatcher never once suspected that he was even in the land of the living.', '他气坏了，因为他觉得贝琪·撒切尔根本没发现他还活着呢。'),
    (18, 1018, 2762, 'But she did see, nevertheless; and she knew she was winning her fight, too, and was glad to see him suffer as she had suffered.', '但她其实看见了。她知道自己要赢了，看到他也像她一样难受，她心里很高兴。'),
    (18, 1019, 2763, 'Amy’s happy prattle became intolerable.', '艾米开心地说个不停，让他觉得实在受不了了。'),
    (18, 1019, 2764, 'Tom hinted at things he had to attend to; things that must be done; and time was fleeting.', '汤姆暗示自己有好多事要忙，时间过得真快。'),
    (18, 1019, 2765, 'But in vain—the girl chirped on.', '可是没用——那个女孩还是叽叽喳喳地说着。'),
    (18, 1019, 2766, 'Tom thought, “Oh, hang her, ain’t I ever going to get rid of her?”', '汤姆心想：“哎呀，真烦她！我什么时候才能摆脱她啊？”'),
    (18, 1019, 2767, 'At last he must be attending to those things—and she said artlessly that she would be “around” when school let out.', '最后他只好说他真的有事要忙了——她却天真地说，放学时还会回来找他呢。'),
    (18, 1019, 2768, 'And he hastened away, hating her for it.', '他赶紧跑走了，心里很讨厌她。'),
    (18, 1020, 2769, '“Any other boy!”', '“换成别的男孩都行！”'),
    (18, 1020, 2770, 'Tom thought, grating his teeth.', '汤姆咬着牙想。'),
    (18, 1020, 2771, '“Any boy in the whole town but that Saint Louis smarty that thinks he dresses so fine and is aristocracy!', '“整个镇上谁都行，就是不能是那个圣路易斯来的小聪明蛋！他觉得自己穿得那么好看，是了不起的人！'),
    (18, 1020, 2772, 'Oh, all right, I licked you the first day you ever saw this town, mister, and I’ll lick you again!', '哼，好吧，你第一天到这镇上的时候，我就打赢过你了，小子，我还会再打赢你一次！'),
    (18, 1020, 2773, 'You just wait till I catch you out!', '你等着瞧吧，等我抓到你！'),
    (18, 1020, 2774, 'I’ll just take and—”', '我一定会好好教训你——”'),
    (18, 1021, 2775, 'And he went through the motions of thrashing an imaginary boy—pummelling the air, and kicking and gouging.', '他假装在揍一个不存在的男孩——对着空气拳打脚踢。'),
    (18, 1021, 2776, '“Oh, you do, do you?', '“哦，你真的要这样吗？'),
    (18, 1021, 2777, 'You holler ’nough, do you?', '你喊‘够了’，是吗？'),
    (18, 1021, 2778, 'Now, then, let that learn you!”', '现在，好了，让你学个乖！”'),
    (18, 1021, 2779, 'And so the imaginary flogging was finished to his satisfaction.', '就这样，这场假装的痛打让他觉得很满意地结束了。'),
    (18, 1022, 2780, 'Tom fled home at noon.', '中午，汤姆跑回家了。'),
    (18, 1022, 2781, 'His conscience could not endure any more of Amy’s grateful happiness, and his jealousy could bear no more of the other distress.', '他心里受不了艾米那种开心的样子了，也受不了别人再难过了。'),
    (18, 1022, 2782, 'Becky resumed her picture inspections with Alfred, but as the minutes dragged along and no Tom came to suffer, her triumph began to cloud and she lost interest; gravity and absentmindedness followed, and then melancholy; two or three times she pricked up her ear at a footstep, but it was a false hope; no Tom came.', '贝琪又和阿尔弗雷德一起看画了。但时间一分一秒过去，汤姆还是没有来难过。她的得意劲儿就没了，也失去了兴趣。接着她变得严肃，心不在焉，然后又很伤心。她两三次听到脚步声都竖起耳朵，但都是白高兴一场；汤姆没有来。'),
    (18, 1022, 2783, 'At last she grew entirely miserable and wished she hadn’t carried it so far.', '最后她变得非常难过，希望自己没有做得太过分。'),
    (18, 1022, 2784, 'When poor Alfred, seeing that he was losing her, he did not know how, kept exclaiming: “Oh, here’s a jolly one! look at this!” she lost patience at last, and said, “Oh, don’t bother me!', '可怜的阿尔弗雷德发现自己快要失去她了，却不知道为什么，他不停地叫着：“哦，这个真好玩！快看这个！”她终于没了耐心，说：“哦，别烦我了！'),
    (18, 1022, 2785, 'I don’t care for them!” and burst into tears, and got up and walked away.', '我才不喜欢这些呢！”说着就大哭起来，然后站起来走开了。'),
    (18, 1023, 2786, 'Alfred dropped alongside and was going to try to comfort her, but she said:', '阿尔弗雷德走到她身边，想安慰她，但她说：'),
    (18, 1024, 2787, '“Go away and leave me alone, can’t you!', '“你走开，别管我，好不好啊！'),
    (18, 1024, 2788, 'I hate you!”', '我讨厌你！”'),
    (18, 1025, 2789, 'So the boy halted, wondering what he could have done—for she had said she would look at pictures all through the nooning—and she walked on, crying.', '于是男孩停住了，他不知道自己做错了什么——因为她之前还说整个中午都要看画呢——她却继续走着，哭个不停。'),
    (18, 1025, 2790, 'Then Alfred went musing into the deserted schoolhouse.', '然后阿尔弗雷德心事重重地走进了空荡荡的校舍。'),
    (18, 1025, 2791, 'He was humiliated and angry.', '他感到又羞又气。'),
    (18, 1025, 2792, 'He easily guessed his way to the truth—the girl had simply made a convenience of him to vent her spite upon Tom Sawyer.', '他很快就猜到真相了——那个女孩只是利用他，把气撒在 汤姆·索亚 身上。'),
    (18, 1025, 2793, 'He was far from hating Tom the less when this thought occurred to him.', '当他想到这个时，对 汤姆 的恨一点也没少。'),
    (18, 1025, 2794, 'He wished there was some way to get that boy into trouble without much risk to himself.', '他希望有个办法能让那个男孩惹麻烦，又不会给自己带来太多风险。'),
    (18, 1025, 2795, 'Tom’s spelling-book fell under his eye.', '他看到了 汤姆 的拼写书。'),
    (18, 1025, 2796, 'Here was his opportunity.', '机会来了。'),
    (18, 1025, 2797, 'He gratefully opened to the lesson for the afternoon and poured ink upon the page.', '他很高兴地翻到下午的课文，然后把墨水倒在书页上。'),
    (18, 1026, 2798, 'Becky, glancing in at a window behind him at the moment, saw the act, and moved on, without discovering herself.', '贝琪 当时正好从他身后的窗户往里看，看到了这一切，然后就走开了，没有让他发现。'),
    (18, 1026, 2799, 'She started homeward, now, intending to find Tom and tell him; Tom would be thankful and their troubles would be healed.', '她现在开始回家，想去找 汤姆 告诉他这件事； 汤姆 会很感激，他们的麻烦也会解决。'),
    (18, 1026, 2800, 'Before she was half way home, however, she had changed her mind.', '不过，她还没走到一半，就改变主意了。'),
    (18, 1026, 2801, 'The thought of Tom’s treatment of her when she was talking about her picnic came scorching back and filled her with shame.', '想到 汤姆 之前在她讲野餐时对她的态度，她又感到羞耻。'),
    (18, 1026, 2802, 'She resolved to let him get whipped on the damaged spelling-book’s account, and to hate him forever, into the bargain.', '她决定让他因为那本弄坏的拼写书挨打，而且永远恨他。'),
    (19, 1027, 2803, 'Tom arrived at home in a dreary mood, and the first thing his aunt said to him showed him that he had brought his sorrows to an unpromising market:', '汤姆 心情很不好地回到家，他阿姨说的第一句话就让他知道，他的烦恼在这里不会有好结果：'),
    (19, 1028, 2804, '“Tom, I’ve a notion to skin you alive!”', '“汤姆，我真想好好教训你！”'),
    (19, 1029, 2805, '“Auntie, what have I done?”', '“阿姨，我做了什么？”'),
    (19, 1030, 2806, '“Well, you’ve done enough.', '“你做的事情够多了。'),
    (19, 1030, 2807, 'Here I go over to Sereny Harper, like an old softy, expecting I’m going to make her believe all that rubbage about that dream, when lo and behold you she’d found out from Joe that you was over here and heard all the talk we had that night.', '我像个老好人一样跑到 塞伦尼·哈珀 那里去，以为能让她相信所有关于那个梦的废话，结果她已经从乔那里知道你在这里，而且听到了我们那天晚上所有的谈话。'),
    (19, 1030, 2808, 'Tom, I don’t know what is to become of a boy that will act like that.', '汤姆，我真不知道像你这样的孩子以后会怎么样。'),
    (19, 1030, 2809, 'It makes me feel so bad to think you could let me go to Sereny Harper and make such a fool of myself and never say a word.”', '想到你让我去 塞伦尼·哈珀 那里出丑，却一句话也不说，我心里就很难过。”'),
    (19, 1031, 2810, 'This was a new aspect of the thing.', '事情有了新的变化。'),
    (19, 1031, 2811, 'His smartness of the morning had seemed to Tom a good joke before, and very ingenious.', '他早上耍的小聪明，之前他还觉得是个很棒的玩笑，也很巧妙。'),
    (19, 1031, 2812, 'It merely looked mean and shabby now.', '现在看来，这事就显得又卑鄙又丢人。'),
    (19, 1031, 2813, 'He hung his head and could not think of anything to say for a moment.', '他低着头，一时想不出说什么。'),
    (19, 1031, 2814, 'Then he said:', '然后他说：'),
    (19, 1032, 2815, '“Auntie, I wish I hadn’t done it—but I didn’t think.”', '“阿姨，我真希望我没做那件事——可是我没想那么多。”'),
    (19, 1033, 2816, '“Oh, child, you never think.', '“哎，孩子，你从来都不想事儿。'),
    (19, 1033, 2817, 'You never think of anything but your own selfishness.', '你心里只想着你自己。'),
    (19, 1033, 2818, 'You could think to come all the way over here from Jackson’s Island in the night to laugh at our troubles, and you could think to fool me with a lie about a dream; but you couldn’t ever think to pity us and save us from sorrow.”', '你能想到晚上从杰克逊岛跑过来嘲笑我们的烦恼，你也能想到用一个关于梦的谎话来骗我；但你却从来没想过可怜我们，救我们摆脱痛苦。”'),
    (19, 1034, 2819, '“Auntie, I know now it was mean, but I didn’t mean to be mean.', '“阿姨，我现在知道那样做很坏，但我不是故意要那么坏的。'),
    (19, 1034, 2820, 'I didn’t, honest.', '我真的没有。'),
    (19, 1034, 2821, 'And besides, I didn’t come over here to laugh at you that night.”', '而且，那天晚上我来也不是为了笑你。”'),
    (19, 1035, 2822, '“What did you come for, then?”', '“那你来干什么呢？”'),
    (19, 1036, 2823, '“It was to tell you not to be uneasy about us, because we hadn’t got drownded.”', '“我是来告诉你，别为我们担心，因为我们没有淹死。”'),
    (19, 1037, 2824, '“Tom, Tom, I would be the thankfullest soul in this world if I could believe you ever had as good a thought as that, but you know you never did—and I know it, Tom.”', '“汤姆, 汤姆，如果你真的有过这样的好想法，我就是世界上最感激的人了。可是你知道你从来没有过——我知道的，汤姆。”'),
    (19, 1038, 2825, '“Indeed and ’deed I did, auntie—I wish I may never stir if I didn’t.”', '“我真的有啊，姨妈——要是我没有，我就不活了。”'),
    (19, 1039, 2826, '“Oh, Tom, don’t lie—don’t do it.', '“哦，汤姆，别撒谎——不要这样。'),
    (19, 1039, 2827, 'It only makes things a hundred times worse.”', '那样只会让事情变得糟一百倍。”'),
    (19, 1040, 2828, '“It ain’t a lie, auntie; it’s the truth.', '“这不是谎话，姨妈；这是真的。'),
    (19, 1040, 2829, 'I wanted to keep you from grieving—that was all that made me come.”', '我只是想让你不要难过——我来就是为了这个。”'),
    (19, 1041, 2830, '“I’d give the whole world to believe that—it would cover up a power of sins, Tom.', '“我真想相信那是真的——那样就能抵消好多不好的事了，汤姆。'),
    (19, 1041, 2831, 'I’d ’most be glad you’d run off and acted so bad.', '我几乎都会为你跑掉还做了坏事而高兴了。'),
    (19, 1041, 2832, 'But it ain’t reasonable; because, why didn’t you tell me, child?”', '可是这不合情理；因为，你为什么不告诉我呢，孩子？”'),
    (19, 1042, 2833, '“Why, you see, when you got to talking about the funeral, I just got all full of the idea of our coming and hiding in the church, and I couldn’t somehow bear to spoil it.', '“你看，当你开始说葬礼的时候，我就满脑子想着我们来教堂躲起来，我真舍不得把它毁掉。'),
    (19, 1042, 2834, 'So I just put the bark back in my pocket and kept mum.”', '所以我把那块树皮又放回口袋里，没有说话。”'),
    (19, 1043, 2835, '“What bark?”', '“什么树皮？”'),
    (19, 1044, 2836, '“The bark I had wrote on to tell you we’d gone pirating.', '“就是我写字告诉你我们去当海盗的那块树皮。'),
    (19, 1044, 2837, 'I wish, now, you’d waked up when I kissed you—I do, honest.”', '我现在真希望你当时被我亲醒了——真的，我发誓。”'),
    (19, 1045, 2838, 'The hard lines in his aunt’s face relaxed and a sudden tenderness dawned in her eyes.', '他姨妈脸上的严肃表情变柔和了，眼睛里也突然充满了温柔。”'),
    (19, 1046, 2839, '“_Did_ you kiss me, Tom?”', '“你真的亲了我吗，汤姆？”'),
    (19, 1047, 2840, '“Why, yes, I did.”', '“嗯，是啊，我亲了。”'),
    (19, 1048, 2841, '“Are you sure you did, Tom?”', '“你确定你亲了吗，汤姆？”'),
    (19, 1049, 2842, '“Why, yes, I did, auntie—certain sure.”', '“嗯，是的，姨妈——千真万确。”'),
    (19, 1050, 2843, '“What did you kiss me for, Tom?”', '“你为什么要亲我呢，汤姆？”'),
    (19, 1051, 2844, '“Because I loved you so, and you laid there moaning and I was so sorry.”', '“因为我太爱你了，你躺在那里哼哼着，我很心疼。”'),
    (19, 1052, 2845, 'The words sounded like truth.', '那些话听起来是真的。”'),
    (19, 1052, 2846, 'The old lady could not hide a tremor in her voice when she said:', '老太太说话的时候，声音都有点颤抖，藏不住了：'),
    (19, 1053, 2847, '“Kiss me again, Tom!', '“再亲我一下，汤姆！'),
    (19, 1053, 2848, '—and be off with you to school, now, and don’t bother me any more.”', '——现在快去上学，别再烦我了。”'),
    (19, 1054, 2849, 'The moment he was gone, she ran to a closet and got out the ruin of a jacket which Tom had gone pirating in.', '他一走，她就跑到柜子前，拿出汤姆穿去当海盗的旧夹克。'),
    (19, 1054, 2850, 'Then she stopped, with it in her hand, and said to herself:', '她拿着夹克停了下来，自言自语道：”'),
    (19, 1055, 2851, '“No, I don’t dare.', '“不，我不敢。'),
    (19, 1055, 2852, 'Poor boy, I reckon he’s lied about it—but it’s a blessed, blessed lie, there’s such a comfort come from it.', '可怜的孩子，我想他说了谎——但这个谎太棒了，太棒了，让人心里很舒服。'),
    (19, 1055, 2853, 'I hope the Lord—I _know_ the Lord will forgive him, because it was such good-heartedness in him to tell it.', '我希望上帝——我知道上帝会原谅他，因为他心地善良，才说了这个谎。'),
    (19, 1055, 2854, 'But I don’t want to find out it’s a lie.', '但我不想知道这是个谎言。'),
    (19, 1055, 2855, 'I won’t look.”', '我不看了。”'),
    (19, 1056, 2856, 'She put the jacket away, and stood by musing a minute.', '她把外套收起来，站着想了一会儿。'),
    (19, 1056, 2857, 'Twice she put out her hand to take the garment again, and twice she refrained.', '她两次伸手想再拿那件衣服，两次都停住了。'),
    (19, 1056, 2858, 'Once more she ventured, and this time she fortified herself with the thought: “It’s a good lie—it’s a good lie—I won’t let it grieve me.”', '她又试了一次，这次她告诉自己：“这是个好谎言——是个好谎言——我不会因此难过。”'),
    (19, 1056, 2859, 'So she sought the jacket pocket.', '于是她找外套的口袋。'),
    (19, 1056, 2860, 'A moment later she was reading Tom’s piece of bark through flowing tears and saying: “I could forgive the boy, now, if he’d committed a million sins!”', '不一会儿，她流着泪读着汤姆的那块树皮，说：“就算他犯了一百万个错，我现在也能原谅他！”'),
    (20, 1057, 2861, 'There was something about Aunt Polly’s manner, when she kissed Tom, that swept away his low spirits and made him lighthearted and happy again.', '波莉姨妈亲吻汤姆时，她的样子让他的坏心情一扫而空，他又变得轻松快乐了。'),
    (20, 1057, 2862, 'He started to school and had the luck of coming upon Becky Thatcher at the head of Meadow Lane.', '他去上学，正好在草地小巷的尽头遇到了贝琪·撒切尔。'),
    (20, 1057, 2863, 'His mood always determined his manner.', '他的心情总是决定他的举止。'),
    (20, 1057, 2864, 'Without a moment’s hesitation he ran to her and said:', '他毫不犹豫地跑到她身边说：'),
    (20, 1058, 2865, '“I acted mighty mean today, Becky, and I’m so sorry.', '“我今天表现得很坏，贝琪，我真抱歉。'),
    (20, 1058, 2866, 'I won’t ever, ever do that way again, as long as ever I live—please make up, won’t you?”', '我再也不会那样做了，永远不会了——请你原谅我，好吗？”'),
    (20, 1059, 2867, 'The girl stopped and looked him scornfully in the face:', '女孩停下来，轻蔑地看了他一眼：'),
    (20, 1060, 2868, '“I’ll thank you to keep yourself _to_ yourself, Mr. Thomas Sawyer.', '“谢谢你管好你自己，托马斯·索亚先生。'),
    (20, 1060, 2869, 'I’ll never speak to you again.”', '我再也不会跟你说话了。”'),
    (20, 1061, 2870, 'She tossed her head and passed on.', '她一甩头，走开了。'),
    (20, 1061, 2871, 'Tom was so stunned that he had not even presence of mind enough to say “Who cares, Miss Smarty?” until the right time to say it had gone by.', '汤姆惊呆了，甚至没想到说“谁在乎啊，小聪明小姐？”，直到说这句话的好时机过去了。'),
    (20, 1061, 2872, 'So he said nothing.', '所以他什么也没说。'),
    (20, 1061, 2873, 'But he was in a fine rage, nevertheless.', '但他还是很生气。'),
    (20, 1061, 2874, 'He moped into the schoolyard wishing she were a boy, and imagining how he would trounce her if she were.', '他闷闷不乐地走进校园，希望她是个男孩，想着如果她是个男孩，他会怎么揍她。'),
    (20, 1061, 2875, 'He presently encountered her and delivered a stinging remark as he passed.', '他很快又遇到了她，经过时说了一句很刺耳的话。'),
    (20, 1061, 2876, 'She hurled one in return, and the angry breach was complete.', '她也回敬了一句，两人彻底吵翻了。'),
    (20, 1061, 2877, 'It seemed to Becky, in her hot resentment, that she could hardly wait for school to “take in,” she was so impatient to see Tom flogged for the injured spelling-book.', '贝琪心里很气，她觉得她简直等不及学校开课了，她太想看到汤姆因为弄坏了拼写书而被打屁股了。'),
    (20, 1061, 2878, 'If she had had any lingering notion of exposing Alfred Temple, Tom’s offensive fling had driven it entirely away.', '如果她还有一点点想揭穿阿尔弗雷德·坦普尔的念头，汤姆那句伤人的话也把它完全打消了。'),
    (20, 1062, 2879, 'Poor girl, she did not know how fast she was nearing trouble herself.', '可怜的女孩，她不知道自己很快也要惹麻烦了。'),
    (20, 1062, 2880, 'The master, Mr. Dobbins, had reached middle age with an unsatisfied ambition.', '老师多宾斯先生已经到了中年，但他有一个没有实现的愿望。'),
    (20, 1062, 2881, 'The darling of his desires was, to be a doctor, but poverty had decreed that he should be nothing higher than a village schoolmaster.', '他好想当医生，可是家里穷，就只能当村里的小学老师。'),
    (20, 1062, 2882, 'Every day he took a mysterious book out of his desk and absorbed himself in it at times when no classes were reciting.', '每天，他都会从抽屉里拿出一本很神秘的书，没上课的时候就看。'),
    (20, 1062, 2883, 'He kept that book under lock and key.', '他把那本书锁得紧紧的。'),
    (20, 1062, 2884, 'There was not an urchin in school but was perishing to have a glimpse of it, but the chance never came.', '学校里的小朋友都特别想看一眼那本书，可就是没机会。'),
    (20, 1062, 2885, 'Every boy and girl had a theory about the nature of that book; but no two theories were alike, and there was no way of getting at the facts in the case.', '每个小朋友都猜那本书里写了什么，可大家猜的都不一样，也没人知道到底是什么。'),
    (20, 1062, 2886, 'Now, as Becky was passing by the desk, which stood near the door, she noticed that the key was in the lock!', '贝琪 经过桌子旁边时，桌子就在门边，她发现钥匙还在锁里！'),
    (20, 1062, 2887, 'It was a precious moment.', '这是一个很棒的机会。'),
    (20, 1062, 2888, 'She glanced around; found herself alone, and the next instant she had the book in her hands.', '她四处看了看，发现没人，下一秒书就在她手上了。'),
    (20, 1062, 2889, 'The titlepage—Professor Somebody’s _Anatomy_—carried no information to her mind; so she began to turn the leaves.', '封面写着“某某教授的《人体解剖学》”，她看不懂，就一页一页地翻起来。'),
    (20, 1062, 2890, 'She came at once upon a handsomely engraved and colored frontispiece—a human figure, stark naked.', '她一下子就看到了一张印得很漂亮、涂了颜色的画——画着一个光着身子的人。'),
    (20, 1062, 2891, 'At that moment a shadow fell on the page and Tom Sawyer stepped in at the door and caught a glimpse of the picture.', '就在这时，一个影子遮住了书页，汤姆·索亚 从门口走了进来，也看到了那幅画。'),
    (20, 1062, 2892, 'Becky snatched at the book to close it, and had the hard luck to tear the pictured page half down the middle.', '贝琪 赶紧抓起书想把它合上，却不小心把那张画撕成了两半。'),
    (20, 1062, 2893, 'She thrust the volume into the desk, turned the key, and burst out crying with shame and vexation.', '她把书塞进抽屉里，转了转钥匙，然后又羞又气地大哭起来。'),
    (20, 1063, 2894, '“Tom Sawyer, you are just as mean as you can be, to sneak up on a person and look at what they’re looking at.”', '“汤姆·索亚，你真是太坏了，竟然偷偷摸摸地过来，看人家在看什么。”'),
    (20, 1064, 2895, '“How could I know you was looking at anything?”', '“我怎么知道你在看东西呀？”'),
    (20, 1065, 2896, '“You ought to be ashamed of yourself, Tom Sawyer; you know you’re going to tell on me, and oh, what shall I do, what shall I do!', '“汤姆·索亚，你真应该感到不好意思！你知道你会去告状的，哎呀，我该怎么办，我该怎么办！'),
    (20, 1065, 2897, 'I’ll be whipped, and I never was whipped in school.”', '我会被打屁股的，我在学校从来没被打过呀！”'),
    (20, 1066, 2898, 'Then she stamped her little foot and said:', '然后她跺了跺小脚，说：'),
    (20, 1067, 2899, '“_Be_ so mean if you want to!', '“你想多坏就多坏吧！'),
    (20, 1067, 2900, 'I know something that’s going to happen.', '我知道会有什么事发生！'),
    (20, 1067, 2901, 'You just wait and you’ll see!', '你等着瞧吧！'),
    (20, 1067, 2902, 'Hateful, hateful, hateful!”', '讨厌，讨厌，讨厌！”'),
    (20, 1067, 2903, '—and she flung out of the house with a new explosion of crying.', '——她又大哭起来，冲出了屋子。'),
    (20, 1068, 2904, 'Tom stood still, rather flustered by this onslaught.', '汤姆 呆呆地站着，被她这样一说，有点慌张。'),
    (20, 1068, 2905, 'Presently he said to himself:', '过了一会儿，他自言自语地说：'),
    (20, 1069, 2906, '“What a curious kind of a fool a girl is!', '“女孩真是奇怪的傻瓜！'),
    (20, 1069, 2907, 'Never been licked in school!', '没在学校被打过屁股！'),
    (20, 1069, 2908, 'Shucks!', '哼！'),
    (20, 1069, 2909, 'What’s a licking!', '打屁股算什么呀！'),
    (20, 1069, 2910, 'That’s just like a girl—they’re so thin-skinned and chicken-hearted.', '这就是女孩的样子——她们太娇气，太胆小了。'),
    (20, 1069, 2911, 'Well, of course I ain’t going to tell old Dobbins on this little fool, because there’s other ways of getting even on her, that ain’t so mean; but what of it?', '嗯，我当然不会把这小笨蛋的事告诉老 多宾斯。因为有别的方法可以跟她扯平，没那么坏。但这又怎样呢？'),
    (20, 1069, 2912, 'Old Dobbins will ask who it was tore his book.', '老 多宾斯 会问是谁撕了他的书。'),
    (20, 1069, 2913, 'Nobody’ll answer.', '没人会回答。'),
    (20, 1069, 2914, 'Then he’ll do just the way he always does—ask first one and then t’other, and when he comes to the right girl he’ll know it, without any telling.', '然后他就会像往常一样，先问一个，再问另一个。当他问到那个女孩时，他不用问也会知道。'),
    (20, 1069, 2915, 'Girls’ faces always tell on them.', '女孩的脸上总会露出秘密。'),
    (20, 1069, 2916, 'They ain’t got any backbone.', '她们没有勇气。'),
    (20, 1069, 2917, 'She’ll get licked.', '她会被打的。'),
    (20, 1069, 2918, 'Well, it’s a kind of a tight place for Becky Thatcher, because there ain’t any way out of it.”', '嗯，这对 贝琪·撒切尔 来说是个麻烦，因为没法脱身。'),
    (20, 1069, 2919, 'Tom conned the thing a moment longer, and then added: “All right, though; she’d like to see me in just such a fix—let her sweat it out!”', '汤姆 又想了一会儿，然后说：“好吧，她也想看到我这样为难——让她自己尝尝滋味吧！”'),
    (20, 1070, 2920, 'Tom joined the mob of skylarking scholars outside.', '汤姆 加入了外面一群爱玩闹的同学。'),
    (20, 1070, 2921, 'In a few moments the master arrived and school “took in.”', '没多久，老师来了，上课了。'),
    (20, 1070, 2922, 'Tom did not feel a strong interest in his studies.', '汤姆 对学习不太感兴趣。'),
    (20, 1070, 2923, 'Every time he stole a glance at the girls’ side of the room Becky’s face troubled him.', '每次他偷偷看教室里女孩那边，贝琪 的脸都让他有点担心。'),
    (20, 1070, 2924, 'Considering all things, he did not want to pity her, and yet it was all he could do to help it.', '想来想去，他不想可怜她，但又忍不住。'),
    (20, 1070, 2925, 'He could get up no exultation that was really worthy the name.', '他一点也高兴不起来。'),
    (20, 1070, 2926, 'Presently the spelling-book discovery was made, and Tom’s mind was entirely full of his own matters for a while after that.', '不久，拼写书被发现了。之后 汤姆 的心思就全放在自己的事情上了。'),
    (20, 1070, 2927, 'Becky roused up from her lethargy of distress and showed good interest in the proceedings.', '贝琪 从难过中清醒过来，对发生的事情很感兴趣。'),
    (20, 1070, 2928, 'She did not expect that Tom could get out of his trouble by denying that he spilt the ink on the book himself; and she was right.', '她不觉得 汤姆 否认是自己把墨水洒在书上就能摆脱麻烦，她猜对了。'),
    (20, 1070, 2929, 'The denial only seemed to make the thing worse for Tom.', '否认只会让 汤姆 的情况变得更糟。'),
    (20, 1070, 2930, 'Becky supposed she would be glad of that, and she tried to believe she was glad of it, but she found she was not certain.', '贝琪 觉得她应该会为此感到高兴，她也试着相信自己是高兴的，但她发现自己其实不确定。'),
    (20, 1070, 2931, 'When the worst came to the worst, she had an impulse to get up and tell on Alfred Temple, but she made an effort and forced herself to keep still—because, said she to herself, “he’ll tell about me tearing the picture sure.', '到了最糟糕的时候，她想站起来告发 阿尔弗雷德·坦普尔，但她努力控制自己，保持安静。她心想：“他一定会说我撕了画。'),
    (20, 1070, 2932, 'I wouldn’t say a word, not to save his life!”', '我一个字都不会说，就算救他的命也不说！”'),
    (20, 1071, 2933, 'Tom took his whipping and went back to his seat not at all broken-hearted, for he thought it was possible that he had unknowingly upset the ink on the spelling-book himself, in some skylarking bout—he had denied it for form’s sake and because it was custom, and had stuck to the denial from principle.', '汤姆 挨了打，回到座位上，一点也没伤心。因为他觉得可能是自己玩闹时不小心把墨水洒到拼写书上的。他否认只是因为面子和习惯，而且他觉得那样做是对的，所以一直不承认。'),
    (20, 1072, 2934, 'A whole hour drifted by, the master sat nodding in his throne, the air was drowsy with the hum of study.', '一个小时过去了，老师在座位上打瞌睡。教室里是读书的嗡嗡声，让人想睡觉。'),
    (20, 1072, 2935, 'By and by, Mr. Dobbins straightened himself up, yawned, then unlocked his desk, and reached for his book, but seemed undecided whether to take it out or leave it.', '过了一会儿，多宾斯先生 坐直了身子，打了个哈欠。然后打开抽屉，伸手去拿书，但他好像在犹豫是拿出来还是不拿。'),
    (20, 1072, 2936, 'Most of the pupils glanced up languidly, but there were two among them that watched his movements with intent eyes.', '大多数同学都懒洋洋地抬起头看了一眼，但其中有两个人，眼睛一眨不眨地盯着他。'),
    (20, 1072, 2937, 'Mr. Dobbins fingered his book absently for a while, then took it out and settled himself in his chair to read!', '多宾斯先生 漫不经心地摸了摸书一会儿，然后拿出来，在椅子上坐好，开始读起来！'),
    (20, 1072, 2938, 'Tom shot a glance at Becky.', '汤姆 朝 贝琪 看了一眼。'),
    (20, 1072, 2939, 'He had seen a hunted and helpless rabbit look as she did, with a gun levelled at its head.', '他看到过一只被追赶的、无助的兔子，眼神跟她一样，枪正对着它的头。'),
    (20, 1072, 2940, 'Instantly he forgot his quarrel with her.', '他立刻就忘了和她的争吵。'),
    (20, 1072, 2941, 'Quick—something must be done! done in a flash, too!', '快！得赶紧做点事！得马上做完！'),
    (20, 1072, 2942, 'But the very imminence of the emergency paralyzed his invention.', '可是，事情太急了，他一时想不出好办法。'),
    (20, 1072, 2943, 'Good!', '好！'),
    (20, 1072, 2944, '—he had an inspiration!', '—他突然想到了一个好主意！'),
    (20, 1072, 2945, 'He would run and snatch the book, spring through the door and fly.', '他要跑过去抢走书，然后冲出门，快点跑掉。'),
    (20, 1072, 2946, 'But his resolution shook for one little instant, and the chance was lost—the master opened the volume.', '可是他只犹豫了一小下，机会就没了——老师已经把书打开了。'),
    (20, 1072, 2947, 'If Tom only had the wasted opportunity back again!', '要是 汤姆 能让错过的机会再回来就好了！'),
    (20, 1072, 2948, 'Too late.', '太晚了。'),
    (20, 1072, 2949, 'There was no help for Becky now, he said.', '他说，现在 贝琪 已经没办法了。'),
    (20, 1072, 2950, 'The next moment the master faced the school.', '下一刻，老师面向了全校同学。'),
    (20, 1072, 2951, 'Every eye sank under his gaze.', '所有人都被他的目光看得低下了头。'),
    (20, 1072, 2952, 'There was that in it which smote even the innocent with fear.', '老师的目光里带着一种东西，让没做错事的人也感到害怕。'),
    (20, 1072, 2953, 'There was silence while one might count ten—the master was gathering his wrath.', '安静得能数到十——老师正在憋着火气。'),
    (20, 1072, 2954, 'Then he spoke: “Who tore this book?”', '然后他开口说：“是谁撕了这本书？”'),
    (20, 1073, 2955, 'There was not a sound.', '一点声音都没有。'),
    (20, 1073, 2956, 'One could have heard a pin drop.', '连一根针掉到地上都能听见。'),
    (20, 1073, 2957, 'The stillness continued; the master searched face after face for signs of guilt.', '教室里还是静悄悄的；老师一个一个地看大家的脸，想找出是谁做的。'),
    (20, 1074, 2958, '“Benjamin Rogers, did you tear this book?”', '“本杰明·罗杰斯，是你撕的这本书吗？”'),
    (20, 1075, 2959, 'A denial.', '他否认了。'),
    (20, 1075, 2960, 'Another pause.', '又停了一下。'),
    (20, 1076, 2961, '“Joseph Harper, did you?”', '“约瑟夫·哈珀，是你吗？”'),
    (20, 1077, 2962, 'Another denial.', '他也否认了。'),
    (20, 1077, 2963, 'Tom’s uneasiness grew more and more intense under the slow torture of these proceedings.', '在这样慢慢的追问下，汤姆 越来越不安了。'),
    (20, 1077, 2964, 'The master scanned the ranks of boys—considered a while, then turned to the girls:', '老师扫视了一排排男生——想了一会儿，然后转向女生们说：'),
    (20, 1078, 2965, '“Amy Lawrence?”', '“艾米·劳伦斯？”'),
    (20, 1079, 2966, 'A shake of the head.', '她摇了摇头。'),
    (20, 1080, 2967, '“Gracie Miller?”', '“格蕾丝·米勒？”'),
    (20, 1081, 2968, 'The same sign.', '也是一样的动作。'),
    (20, 1082, 2969, '“Susan Harper, did you do this?”', '“苏珊·哈珀，是你做的吗？”'),
    (20, 1083, 2970, 'Another negative.', '她也说不是。'),
    (20, 1083, 2971, 'The next girl was Becky Thatcher.', '下一个女孩是贝琪·撒切尔。'),
    (20, 1083, 2972, 'Tom was trembling from head to foot with excitement and a sense of the hopelessness of the situation.', '汤姆兴奋又绝望，全身都在发抖。'),
    (20, 1084, 2973, '“Rebecca Thatcher” [Tom glanced at her face—it was white with terror]—“did you tear—no, look me in the face” [her hands rose in appeal]—“did you tear this book?”', '“丽贝卡撒切尔，” [汤姆看了看她的脸——吓得惨白] “是你撕的吗——不，看着我的脸” [她举起手，好像在求] “是你撕坏了这本书吗？”'),
    (20, 1085, 2974, 'A thought shot like lightning through Tom’s brain.', '一个念头像闪电一样，飞快地划过汤姆的脑海。'),
    (20, 1085, 2975, 'He sprang to his feet and shouted—“I done it!”', '他一下站起来，大喊：“是我做的！”'),
    (20, 1086, 2976, 'The school stared in perplexity at this incredible folly.', '学校里的人都很困惑，盯着这个不可思议的傻事。'),
    (20, 1086, 2977, 'Tom stood a moment, to gather his dismembered faculties; and when he stepped forward to go to his punishment the surprise, the gratitude, the adoration that shone upon him out of poor Becky’s eyes seemed pay enough for a hundred floggings.', '汤姆站了一会儿，努力让自己清醒过来；当他走上前去领罚时，可怜的贝琪眼里闪烁着惊讶、感激和崇拜，这似乎比挨一百次打都值得。'),
    (20, 1086, 2978, 'Inspired by the splendor of his own act, he took without an outcry the most merciless flaying that even Mr. Dobbins had ever administered; and also received with indifference the added cruelty of a command to remain two hours after school should be dismissed—for he knew who would wait for him outside till his captivity was done, and not count the tedious time as loss, either.', '他被自己行为的光辉感染了，默默地承受了最狠的鞭打，连多宾斯先生都从未挨过这样的打；他还毫不在意地接受了额外的惩罚：放学后多留两小时——因为他知道谁会在外面等他，直到他被关禁闭结束，并且不觉得那无聊的等待是浪费时间。'),
    (20, 1087, 2979, 'Tom went to bed that night planning vengeance against Alfred Temple; for with shame and repentance Becky had told him all, not forgetting her own treachery; but even the longing for vengeance had to give way, soon, to pleasanter musings, and he fell asleep at last with Becky’s latest words lingering dreamily in his ear—', '那天晚上，汤姆上床睡觉时，心里还在想着要报复阿尔弗雷德·坦普尔；因为贝琪又羞又悔地把一切都告诉了他，也没忘了自己的背叛；但很快，报复的念头就让位给了更开心的想法，他最后伴着贝琪最近说的话在耳边回荡，迷迷糊糊地睡着了——'),
    (20, 1088, 2980, '“Tom, how _could_ you be so noble!”', '“汤姆，你怎么能这么高尚呢！”'),
    (21, 1089, 2981, 'Vacation was approaching.', '假期快到了。'),
    (21, 1089, 2982, 'The schoolmaster, always severe, grew severer and more exacting than ever, for he wanted the school to make a good showing on “Examination” day.', '校长一直都很严厉，现在变得比以前更凶、要求更多了，因为他希望学校在“考试”那天表现得好。'),
    (21, 1089, 2983, 'His rod and his ferule were seldom idle now—at least among the smaller pupils.', '他的教鞭和戒尺现在很少闲着——至少对那些小一点的学生来说是这样。'),
    (21, 1089, 2984, 'Only the biggest boys, and young ladies of eighteen and twenty, escaped lashing.', '只有最大的男生，还有十八九岁的年轻女孩，才没有挨鞭打。'),
    (21, 1089, 2985, 'Mr. Dobbins’ lashings were very vigorous ones, too; for although he carried, under his wig, a perfectly bald and shiny head, he had only reached middle age, and there was no sign of feebleness in his muscle.', '多宾斯先生打人也非常有力；虽然他戴着假发，假发下面是个光秃秃亮堂堂的脑袋，但他才中年，肌肉一点也不松弛。'),
    (21, 1089, 2986, 'As the great day approached, all the tyranny that was in him came to the surface; he seemed to take a vindictive pleasure in punishing the least shortcomings.', '随着那个重要日子的临近，他所有的暴虐都显露了出来；他似乎很喜欢惩罚学生一点点的小错误，好像在报复一样。'),
    (21, 1089, 2987, 'The consequence was, that the smaller boys spent their days in terror and suffering and their nights in plotting revenge.', '结果就是，小男生们白天都在恐惧和痛苦中度过，晚上则在琢磨着怎么报仇。'),
    (21, 1089, 2988, 'They threw away no opportunity to do the master a mischief.', '他们不错过任何一个能恶作剧校长的机会。'),
    (21, 1089, 2989, 'But he kept ahead all the time.', '但他总是能抢先一步。'),
    (21, 1089, 2990, 'The retribution that followed every vengeful success was so sweeping and majestic that the boys always retired from the field badly worsted.', '每次他们成功报复后，接着而来的惩罚都那么厉害，那么有气势，结果男生们总是输得很惨，只好收手。'),
    (21, 1089, 2991, 'At last they conspired together and hit upon a plan that promised a dazzling victory.', '最后，他们一起商量，想出了一个主意，这个主意看起来能让他们大获全胜。'),
    (21, 1089, 2992, 'They swore in the signpainter’s boy, told him the scheme, and asked his help.', '他们找来了画招牌的男孩，告诉他这个计划，请他帮忙。'),
    (21, 1089, 2993, 'He had his own reasons for being delighted, for the master boarded in his father’s family and had given the boy ample cause to hate him.', '男孩有自己的理由很高兴，因为校长住在他父亲家里，校长给了这男孩很多恨他的理由。'),
    (21, 1089, 2994, 'The master’s wife would go on a visit to the country in a few days, and there would be nothing to interfere with the plan; the master always prepared himself for great occasions by getting pretty well fuddled, and the signpainter’s boy said that when the dominie had reached the proper condition on Examination Evening he would “manage the thing” while he napped in his chair; then he would have him awakened at the right time and hurried away to school.', '校长的妻子几天后会去乡下探亲，这样就不会有人干扰他们的计划了；校长总是在重要场合前喝得醉醺醺的，画招牌的男孩说，在考试之夜，等校长在椅子上睡着，喝到适当程度时，他会“处理好这件事”；然后他会在合适的时候叫醒校长，并催他赶紧去学校。'),
    (21, 1090, 2995, 'In the fulness of time the interesting occasion arrived.', '终于，那个有趣的日子到来了。'),
    (21, 1090, 2996, 'At eight in the evening the schoolhouse was brilliantly lighted, and adorned with wreaths and festoons of foliage and flowers.', '晚上八点，学校里灯火通明，还装饰着树叶和花朵做的花环和彩带。'),
    (21, 1090, 2997, 'The master sat throned in his great chair upon a raised platform, with his blackboard behind him.', '校长坐在高高的讲台上，大椅子就像个宝座，黑板在他身后。'),
    (21, 1090, 2998, 'He was looking tolerably mellow.', '他看起来心情还不错，有点和蔼。'),
    (21, 1090, 2999, 'Three rows of benches on each side and six rows in front of him were occupied by the dignitaries of the town and by the parents of the pupils.', '校长两边各三排，前面六排的座位，都坐满了镇上的大人物和学生们的爸爸妈妈。'),
    (21, 1090, 3000, 'To his left, back of the rows of citizens, was a spacious temporary platform upon which were seated the scholars who were to take part in the exercises of the evening; rows of small boys, washed and dressed to an intolerable state of discomfort; rows of gawky big boys; snowbanks of girls and young ladies clad in lawn and muslin and conspicuously conscious of their bare arms, their grandmothers’ ancient trinkets, their bits of pink and blue ribbon and the flowers in their hair.', '在校长的左边，公民席后面，搭了一个很大的临时台子，上面坐着今晚要表演的学生们；一排排的小男生，洗得干干净净，穿得却很不舒服；一排排笨拙的大男生；还有一大群女孩和年轻女士，她们穿着薄纱和细棉布的衣服，很在意自己露出的胳膊、奶奶给的旧首饰、粉色和蓝色的小丝带，以及头上的花。'),
    (21, 1090, 3001, 'All the rest of the house was filled with non-participating scholars.', '房子里其他的地方都坐满了没有参加表演的同学。'),
    (21, 1091, 3002, 'The exercises began.', '表演开始了。'),
    (21, 1091, 3003, 'A very little boy stood up and sheepishly recited, “You’d scarce expect one of my age to speak in public on the stage,” etc.—accompanying himself with the painfully exact and spasmodic gestures which a machine might have used—supposing the machine to be a trifle out of order.', '一个很小的小男孩站起来，有点害羞地背诵道：“你们大概不会想到，我这么小的孩子也会在台上讲话吧。”等等。他一边背诵，一边做着非常僵硬又奇怪的动作，就像一个坏掉的机器人在动一样。'),
    (21, 1091, 3004, 'But he got through safely, though cruelly scared, and got a fine round of applause when he made his manufactured bow and retired.', '不过他还是顺利地演完了，虽然他很紧张。他鞠了个躬，就下台了，大家为他热烈鼓掌。'),
    (21, 1092, 3005, 'A little shamefaced girl lisped, “Mary had a little lamb,” etc., performed a compassion-inspiring curtsy, got her meed of applause, and sat down flushed and happy.', '一个小女孩害羞地低声念道：“玛丽有只小羊羔。”等等。她还做了个可爱的屈膝礼，大家也为她鼓掌。她脸红红的，开心地坐下了。'),
    (21, 1093, 3006, 'Tom Sawyer stepped forward with conceited confidence and soared into the unquenchable and indestructible “Give me liberty or give me death” speech, with fine fury and frantic gesticulation, and broke down in the middle of it.', '另一个孩子汤姆·索亚很自信地走上前，开始激动地演讲：“不自由，毋宁死！”他声音很大，手舞足蹈，可讲到一半就停下来了。'),
    (21, 1093, 3007, 'A ghastly stage-fright seized him, his legs quaked under him and he was like to choke.', '他突然很害怕，腿都抖了起来，感觉要喘不过气了。'),
    (21, 1093, 3008, 'True, he had the manifest sympathy of the house but he had the house’s silence, too, which was even worse than its sympathy.', '虽然大家都很同情他，但全场鸦雀无声，这比同情更让他难受。'),
    (21, 1093, 3009, 'The master frowned, and this completed the disaster.', '老师也皱起了眉头，这下更糟糕了。'),
    (21, 1093, 3010, 'Tom struggled awhile and then retired, utterly defeated.', '汤姆努力了一下，但还是放弃了，非常沮丧地走下台。'),
    (21, 1093, 3011, 'There was a weak attempt at applause, but it died early.', '大家稍微鼓了鼓掌，但很快就停了。'),
    (21, 1094, 3012, '“The Boy Stood on the Burning Deck” followed; also “The Assyrian Came Down,” and other declamatory gems.', '接着是《男孩站在燃烧的甲板上》和《亚述人来了》等诗歌朗诵。'),
    (21, 1094, 3013, 'Then there were reading exercises, and a spelling fight.', '然后是朗读练习和拼写比赛。'),
    (21, 1094, 3014, 'The meagre Latin class recited with honor.', '拉丁语班的学生人数很少，但他们表演得很棒。'),
    (21, 1094, 3015, 'The prime feature of the evening was in order, now—original “compositions” by the young ladies.', '晚上最重要的环节来了——是小女生们自己写的“作文”。'),
    (21, 1094, 3016, 'Each in her turn stepped forward to the edge of the platform, cleared her throat, held up her manuscript (tied with dainty ribbon), and proceeded to read, with labored attention to “expression” and punctuation.', '每个小女生都轮流走到台前，清了清嗓子，拿起她用漂亮丝带绑好的稿子，开始大声地读起来。她们读得很用心，还注意了语气和标点符号。'),
    (21, 1094, 3017, 'The themes were the same that had been illuminated upon similar occasions by their mothers before them, their grandmothers, and doubtless all their ancestors in the female line clear back to the Crusades.', '她们作文的主题都一样，都是以前妈妈们、奶奶们，甚至更早的祖先们讲过的老故事。'),
    (21, 1094, 3018, '“Friendship” was one; “Memories of Other Days”; “Religion in History”; “Dream Land”; “The Advantages of Culture”; “Forms of Political Government Compared and Contrasted”; “Melancholy”; “Filial Love”; “Heart Longings,” etc., etc.', '比如有《友情》、《旧日回忆》、《历史中的宗教》、《梦幻之地》、《文化的好处》、《各种政府的比较》、《忧郁》、《孝顺的爱》、《心中的渴望》等等。'),
    (21, 1095, 3019, 'A prevalent feature in these compositions was a nursed and petted melancholy; another was a wasteful and opulent gush of “fine language”; another was a tendency to lug in by the ears particularly prized words and phrases until they were worn entirely out; and a peculiarity that conspicuously marked and marred them was the inveterate and intolerable sermon that wagged its crippled tail at the end of each and every one of them.', '这些作文里，常常有一些矫情的忧伤；还有很多华丽却没用的大词；她们也喜欢把一些时髦的词语和句子用很多次，用到都听腻了；最特别的是，每篇作文的结尾，都会有一个长长的、让人觉得不舒服的“说教”。'),
    (21, 1095, 3020, 'No matter what the subject might be, a brainracking effort was made to squirm it into some aspect or other that the moral and religious mind could contemplate with edification.', '不管主题是什么，她们总是想方设法把它扯到道德和宗教上去，让大家觉得受到了教育。'),
    (21, 1095, 3021, 'The glaring insincerity of these sermons was not sufficient to compass the banishment of the fashion from the schools, and it is not sufficient today; it never will be sufficient while the world stands, perhaps.', '这些说教虽然很不真诚，但大家还是照样写，学校里也没有禁止。可能永远都不会禁止吧。'),
    (21, 1095, 3022, 'There is no school in all our land where the young ladies do not feel obliged to close their compositions with a sermon; and you will find that the sermon of the most frivolous and the least religious girl in the school is always the longest and the most relentlessly pious.', '在我们这里，每个学校的小女生都觉得写作文一定要加说教。而且，你会发现，那些最爱玩、最不信教的女生的说教，反而是最长、最虔诚的。'),
    (21, 1095, 3023, 'But enough of this.', '好了，这些就说到这里。'),
    (21, 1095, 3024, 'Homely truth is unpalatable.', '有时候，实话听起来不太好听。'),
    (21, 1096, 3025, 'Let us return to the “Examination.”', '我们还是回到“考试”上吧。'),
    (21, 1096, 3026, 'The first composition that was read was one entitled “Is this, then, Life?”', '第一个读的作文题目是《这就是人生吗？》'),
    (21, 1096, 3027, 'Perhaps the reader can endure an extract from it:', '也许你可以听听其中的一小段：'),
    (21, 1097, 3028, '“In the common walks of life, with what delightful emotions does the youthful mind look forward to some anticipated scene of festivity!', '“在普通的生活中，年轻人的心是多么愉快地期待着未来的节日场景啊！'),
    (21, 1097, 3029, 'Imagination is busy sketching rose-tinted pictures of joy.', '想象力正在忙着描绘粉红色的欢乐画面。'),
    (21, 1097, 3030, 'In fancy, the voluptuous votary of fashion sees herself amid the festive throng, ‘the observed of all observers.’', '在幻想中，那个追求时尚的漂亮女生看到自己置身于热闹的人群中，‘吸引了所有人的目光’。'),
    (21, 1097, 3031, 'Her graceful form, arrayed in snowy robes, is whirling through the mazes of the joyous dance; her eye is brightest, her step is lightest in the gay assembly.', '她穿着雪白的衣服，跳着舞，转来转去。她的眼睛亮亮的，脚步也最轻快。'),
    (21, 1098, 3032, '“In such delicious fancies time quickly glides by, and the welcome hour arrives for her entrance into the Elysian world, of which she has had such bright dreams.', '她想着这些美好的事，时间过得飞快。很快就到了她要去那个梦中世界的时候了。'),
    (21, 1098, 3033, 'How fairy-like does everything appear to her enchanted vision!', '在她眼里，一切都像童话一样美妙！'),
    (21, 1098, 3034, 'Each new scene is more charming than the last.', '每个地方都比上一个更好看。'),
    (21, 1098, 3035, 'But after a while she finds that beneath this goodly exterior, all is vanity, the flattery which once charmed her soul, now grates harshly upon her ear; the ballroom has lost its charms; and with wasted health and imbittered heart, she turns away with the conviction that earthly pleasures cannot satisfy the longings of the soul!”', '但过了一会儿，她发现，外面看着好，其实都是空的。以前爱听的好话，现在听着很烦；舞厅也没意思了。她身体不好，心里也苦，就离开了。她知道，这些玩乐并不能让她真正高兴！'),
    (21, 1099, 3036, 'And so forth and so on.', '就这样，一直说着。'),
    (21, 1099, 3037, 'There was a buzz of gratification from time to time during the reading, accompanied by whispered ejaculations of “How sweet!”', '大家听着听着，有时会很高兴地小声说：“真好听啊！”'),
    (21, 1099, 3038, '“How eloquent!”', '“说得真好！”'),
    (21, 1099, 3039, '“So true!” etc., and after the thing had closed with a peculiarly afflicting sermon the applause was enthusiastic.', '“说得太对了！”等等。等到读完一个伤心的故事后，大家开心地鼓掌。'),
    (21, 1100, 3040, 'Then arose a slim, melancholy girl, whose face had the “interesting” paleness that comes of pills and indigestion, and read a “poem.”', '接着，一个又瘦又有点不开心的女孩站起来。她的脸因为吃药和消化不好，显得有点白。她开始读一首“诗”。'),
    (21, 1100, 3041, 'Two stanzas of it will do:', '读两小段就行了：'),
    (21, 1101, 3042, '“A MISSOURI MAIDEN’S FAREWELL TO ALABAMA', '密苏里少女告别阿拉巴马'),
    (21, 1102, 3043, '“Alabama, goodbye!', '阿拉巴马，再见！'),
    (21, 1102, 3044, 'I love thee well!', '我非常爱你！'),
    (21, 1102, 3045, 'But yet for a while do I leave thee now!', '但我现在要暂时离开你了！'),
    (21, 1102, 3046, 'Sad, yes, sad thoughts of thee my heart doth swell, And burning recollections throng my brow!', '想到你，我心里就很难过，很多回忆涌上来。'),
    (21, 1102, 3047, 'For I have wandered through thy flowery woods; Have roamed and read near Tallapoosa’s stream; Have listened to Tallassee’s warring floods, And wooed on Coosa’s side Aurora’s beam.', '我在你开满花的树林里走过；在塔拉普萨河边散步、看书；听过塔拉西河水的轰鸣；在库萨河边看过清晨的阳光。'),
    (21, 1103, 3048, '“Yet shame I not to bear an o’erfull heart, Nor blush to turn behind my tearful eyes; ’Tis from no stranger land I now must part, ’Tis to no strangers left I yield these sighs.', '我心里满满的，就算流泪也不觉得害羞。我不是离开陌生的地方，也不是把我的难过留给陌生人。'),
    (21, 1103, 3049, 'Welcome and home were mine within this State, Whose vales I leave—whose spires fade fast from me And cold must be mine eyes, and heart, and tête, When, dear Alabama! they turn cold on thee!”', '在这个州，我感到很受欢迎，就像在家一样。现在我要离开这里的山谷，那些高高的尖顶也很快在我眼前消失了。亲爱的阿拉巴马！如果我的眼睛、我的心、我的头都对你变得冷冷的，那它们一定很冷很冷了！'),
    (21, 1104, 3050, 'There were very few there who knew what “_tête_” meant, but the poem was very satisfactory, nevertheless.', '在场的人很少有知道“_tête_”是什么意思的，但这首诗大家还是很喜欢。'),
    (21, 1105, 3051, 'Next appeared a dark-complexioned, black-eyed, black-haired young lady, who paused an impressive moment, assumed a tragic expression, and began to read in a measured, solemn tone:', '接着，走上来一位皮肤有点黑，眼睛和头发都是黑色的年轻女孩。她停了一会儿，做出很伤心的样子，然后用慢悠悠、很认真的声音开始读起来：'),
    (21, 1106, 3052, 'A VISION', '一个景象'),
    (21, 1107, 3053, 'Dark and tempestuous was night.', '夜晚又黑又狂风暴雨。'),
    (21, 1107, 3054, 'Around the throne on high not a single star quivered; but the deep intonations of the heavy thunder constantly vibrated upon the ear; whilst the terrific lightning revelled in angry mood through the cloudy chambers of heaven, seeming to scorn the power exerted over its terror by the illustrious Franklin!', '天上没有一颗星星在闪。只有很响的雷声不停地轰隆隆响着。可怕的闪电在乌云里亮来亮去，好像在嘲笑富兰克林控制闪电的本事！'),
    (21, 1107, 3055, 'Even the boisterous winds unanimously came forth from their mystic homes, and blustered about as if to enhance by their aid the wildness of the scene.', '连狂风也一起从它们藏身的地方冲出来，呼呼地吹着，好像要让这个夜晚变得更可怕。'),
    (21, 1108, 3056, 'At such a time, so dark, so dreary, for human sympathy my very spirit sighed; but instead thereof,', '在这样又黑又闷的晚上，我的心里很想得到别人的关心；可是没有，'),
    (21, 1109, 3057, '‘My dearest friend, my counsellor, my comforter and guide— My joy in grief, my second bliss in joy,’ came to my side.', '“我最好的朋友，我的好帮手，在我伤心时安慰我，在我开心时让我更开心的人，”来到了我身边。'),
    (21, 1110, 3058, 'She moved like one of those bright beings pictured in the sunny walks of fancy’s Eden by the romantic and young, a queen of beauty unadorned save by her own transcendent loveliness.', '她走起路来，就像那些年轻人在美丽图画里看到的小仙子。她不用打扮就很美，像个皇后一样。'),
    (21, 1110, 3059, 'So soft was her step, it failed to make even a sound, and but for the magical thrill imparted by her genial touch, as other unobtrusive beauties, she would have glided away unperceived—unsought.', '她的脚步轻轻的，一点声音也没有。要不是她轻轻碰了我一下，让我感觉很奇妙，她就会像其他不被人注意的美女一样，悄悄地走开，谁也发现不了她。'),
    (21, 1110, 3060, 'A strange sadness rested upon her features, like icy tears upon the robe of December, as she pointed to the contending elements without, and bade me contemplate the two beings presented.', '她脸上带着一点奇怪的伤心，就像十二月的冰冷雨滴。她指着外面刮风下雨的天气，让我仔细看看她给我看的两个人。'),
    (21, 1111, 3061, 'This nightmare occupied some ten pages of manuscript and wound up with a sermon so destructive of all hope to non-Presbyterians that it took the first prize.', '这个故事像一场可怕的梦，写了好多页。它讲得太吓人了，结果得了第一名。'),
    (21, 1111, 3062, 'This composition was considered to be the very finest effort of the evening.', '大家觉得这是那天晚上最棒的作品。'),
    (21, 1111, 3063, 'The mayor of the village, in delivering the prize to the author of it, made a warm speech in which he said that it was by far the most “eloquent” thing he had ever listened to, and that Daniel Webster himself might well be proud of it.', '村长把奖品给写故事的人时，说了好多夸奖的话。他说这是他听过的最“动听”的故事，连丹尼尔·韦伯斯特都会为它骄傲。'),
    (21, 1112, 3064, 'It may be remarked, in passing, that the number of compositions in which the word “beauteous” was over-fondled, and human experience referred to as “life’s page,” was up to the usual average.', '顺便说一句，很多作文里都太喜欢用“美丽极了”这个词，还把生活叫做“人生的书页”，这跟平时一样多。'),
    (21, 1113, 3065, 'Now the master, mellow almost to the verge of geniality, put his chair aside, turned his back to the audience, and began to draw a map of America on the blackboard, to exercise the geography class upon.', '老师现在心情很好，他把椅子推开，背对着大家，开始在黑板上画美国地图，要给地理课用。'),
    (21, 1113, 3066, 'But he made a sad business of it with his unsteady hand, and a smothered titter rippled over the house.', '可是他手不稳，画得不好看，大家就偷偷地笑了。'),
    (21, 1113, 3067, 'He knew what the matter was, and set himself to right it.', '他知道大家为什么笑，就想把它改好。'),
    (21, 1113, 3068, 'He sponged out lines and remade them; but he only distorted them more than ever, and the tittering was more pronounced.', '他擦掉线重新画，可画得更不像了，大家的笑声也更大了。'),
    (21, 1113, 3069, 'He threw his entire attention upon his work, now, as if determined not to be put down by the mirth.', '他现在特别认真地画，好像下决心不让大家的笑声影响他。'),
    (21, 1113, 3070, 'He felt that all eyes were fastened upon him; he imagined he was succeeding, and yet the tittering continued; it even manifestly increased.', '他觉得所有人都盯着他看，他以为自己画得不错了，可大家的笑声还在，而且更响了。'),
    (21, 1113, 3071, 'And well it might.', '这笑声是有原因的。'),
    (21, 1113, 3072, 'There was a garret above, pierced with a scuttle over his head; and down through this scuttle came a cat, suspended around the haunches by a string; she had a rag tied about her head and jaws to keep her from mewing; as she slowly descended she curved upward and clawed at the string, she swung downward and clawed at the intangible air.', '老师头顶上面有个阁楼，阁楼上有个小洞。一只猫被绳子绑着屁股，从那个洞里慢慢下来。它的头和嘴上还系着一块布，不让它叫。猫咪一边下来，一边弓着身子抓绳子，又荡下来抓空气。'),
    (21, 1113, 3073, 'The tittering rose higher and higher—the cat was within six inches of the absorbed teacher’s head—down, down, a little lower, and she grabbed his wig with her desperate claws, clung to it, and was snatched up into the garret in an instant with her trophy still in her possession!', '大家笑得越来越大声——猫离专心画画的老师的头只有一点点远了——再往下，再往下一点点，它就用爪子抓住了老师的假发！猫紧紧地抓住假发，一下子就被拉回了阁楼，假发还在它手里呢！'),
    (21, 1113, 3074, 'And how the light did blaze abroad from the master’s bald pate—for the signpainter’s boy had _gilded_ it!', '老师的光头亮闪闪的——原来是招牌店的男孩把它“涂成了金色”！'),
    (21, 1114, 3075, 'That broke up the meeting.', '这样一来，聚会就散了。'),
    (21, 1114, 3076, 'The boys were avenged.', '男孩们总算报了仇。'),
    (21, 1114, 3077, 'Vacation had come.', '假期到了。'),
    (21, 1115, 3078, '[*] NOTE:—The pretended “compositions” quoted in this chapter are taken without alteration from a volume entitled “Prose and Poetry, by a Western Lady”—but they are exactly and precisely after the schoolgirl pattern, and hence are much happier than any mere imitations could be.', '[*] 注意：这一章里引用的“作文”都是真的，直接从一本叫做《一位西方女士的散文与诗歌》的书里拿来的。它们完全是女学生写作文的样子，比随便模仿的要好得多。'),
    (22, 1116, 3079, 'Tom joined the new order of Cadets of Temperance, being attracted by the showy character of their “regalia.”', '汤姆加入了新成立的“戒酒少年团”，因为他喜欢他们那些“漂亮制服”。'),
    (22, 1116, 3080, 'He promised to abstain from smoking, chewing, and profanity as long as he remained a member.', '他答应只要是这个团里的人，就不抽烟、不嚼东西、不说脏话。'),
    (22, 1116, 3081, 'Now he found out a new thing—namely, that to promise not to do a thing is the surest way in the world to make a body want to go and do that very thing.', '现在他发现了一件事——原来，答应不做某件事，反而会让你特别想去做那件事。'),
    (22, 1116, 3082, 'Tom soon found himself tormented with a desire to drink and swear; the desire grew to be so intense that nothing but the hope of a chance to display himself in his red sash kept him from withdrawing from the order.', '汤姆很快就特别想喝酒、想骂人；这种想法越来越强烈，只有想着有机会能穿上他的红腰带炫耀一下，才没让他退出这个团。'),
    (22, 1116, 3083, 'Fourth of July was coming; but he soon gave that up—gave it up before he had worn his shackles over forty-eight hours—and fixed his hopes upon old Judge Frazer, justice of the peace, who was apparently on his deathbed and would have a big public funeral, since he was so high an official.', '独立日快到了；但他很快就放弃了——还没坚持两天呢就放弃了——然后把希望寄托在老法官弗雷泽身上。这个老法官好像快要死了，因为他是个大人物，所以肯定会有一个盛大的公开葬礼。'),
    (22, 1116, 3084, 'During three days Tom was deeply concerned about the Judge’s condition and hungry for news of it.', '整整三天，汤姆都非常关心法官的身体状况，一直想知道他的消息。'),
    (22, 1116, 3085, 'Sometimes his hopes ran high—so high that he would venture to get out his regalia and practise before the looking-glass.', '有时候，他抱的希望特别大——大到他会拿出制服，在镜子前练习。'),
    (22, 1116, 3086, 'But the Judge had a most discouraging way of fluctuating.', '可是法官的病情总是不停地变好变坏，真是让人灰心。'),
    (22, 1116, 3087, 'At last he was pronounced upon the mend—and then convalescent.', '最后，大家说他病情好转了——然后又说他康复了。'),
    (22, 1116, 3088, 'Tom was disgusted; and felt a sense of injury, too.', '汤姆觉得很生气；他还觉得受到了伤害。'),
    (22, 1116, 3089, 'He handed in his resignation at once—and that night the Judge suffered a relapse and died.', '他马上递交了辞职信——那天晚上，法官却病情复发，去世了。'),
    (22, 1116, 3090, 'Tom resolved that he would never trust a man like that again.', '汤姆下定决心，以后再也不相信那样的人了。'),
    (22, 1117, 3091, 'The funeral was a fine thing.', '这场葬礼很不错。'),
    (22, 1117, 3092, 'The Cadets paraded in a style calculated to kill the late member with envy.', '少年兵们游行得特别棒，去世的人看了都会羡慕。'),
    (22, 1117, 3093, 'Tom was a free boy again, however—there was something in that.', '汤姆又变回自由的男孩了，这感觉真不错。'),
    (22, 1117, 3094, 'He could drink and swear, now—but found to his surprise that he did not want to.', '他现在能喝酒骂人了，可他发现自己并不想那样。'),
    (22, 1117, 3095, 'The simple fact that he could, took the desire away, and the charm of it.', '只要他能做，那种想做的心情和乐趣就没了。'),
    (22, 1118, 3096, 'Tom presently wondered to find that his coveted vacation was beginning to hang a little heavily on his hands.', '汤姆现在发现，他盼望已久的假期开始有点无聊了。'),
    (22, 1119, 3097, 'He attempted a diary—but nothing happened during three days, and so he abandoned it.', '他想写日记，可三天都没事发生，于是他就放弃了。'),
    (22, 1120, 3098, 'The first of all the negro minstrel shows came to town, and made a sensation.', '镇上来了第一个歌舞表演团，引起了轰动。'),
    (22, 1120, 3099, 'Tom and Joe Harper got up a band of performers and were happy for two days.', '汤姆和乔·哈珀组织了一个表演队，开心了足足两天。'),
    (22, 1121, 3100, 'Even the Glorious Fourth was in some sense a failure, for it rained hard, there was no procession in consequence, and the greatest man in the world (as Tom supposed), Mr. Benton, an actual United States Senator, proved an overwhelming disappointment—for he was not twenty-five feet high, nor even anywhere in the neighborhood of it.', '甚至连光荣的七月四日都有些不顺心。那天下大雨，所以没有游行。汤姆以为世界上最了不起的人是本顿先生（他可是美国参议员呢），可他来了却让汤姆非常失望，因为本顿先生根本就没有二十五英尺那么高！'),
    (22, 1122, 3101, 'A circus came.', '一个马戏团来了。'),
    (22, 1122, 3102, 'The boys played circus for three days afterward in tents made of rag carpeting—admission, three pins for boys, two for girls—and then circusing was abandoned.', '之后三天，男孩子们用碎布地毯搭帐篷玩马戏。门票是：男孩三根大头针，女孩两根。然后，他们就不再玩马戏了。'),
    (22, 1123, 3103, 'A phrenologist and a mesmerizer came—and went again and left the village duller and drearier than ever.', '一个测骨相的和会催眠的人来了又走了，村子比以前更无聊、更冷清了。'),
    (22, 1124, 3104, 'There were some boys-and-girls’ parties, but they were so few and so delightful that they only made the aching voids between ache the harder.', '有些男女孩子一起的派对，可太少了，又太好玩了，让大家过后更觉空虚。'),
    (22, 1125, 3105, 'Becky Thatcher was gone to her Constantinople home to stay with her parents during vacation—so there was no bright side to life anywhere.', '贝琪·撒切尔去她君士坦丁堡的家和爸爸妈妈过暑假了，所以生活里到处都没有亮光了。'),
    (22, 1126, 3106, 'The dreadful secret of the murder was a chronic misery.', '那个可怕的谋杀秘密，一直让他很痛苦。'),
    (22, 1126, 3107, 'It was a very cancer for permanency and pain.', '这个秘密就像一个永远都好不了的痛。'),
    (22, 1127, 3108, 'Then came the measles.', '接着，他得了麻疹。'),
    (22, 1128, 3109, 'During two long weeks Tom lay a prisoner, dead to the world and its happenings.', '整整两周，汤姆躺在那里，对外面的世界什么都不知道。'),
    (22, 1128, 3110, 'He was very ill, he was interested in nothing.', '他病得很重，对什么都不感兴趣。'),
    (22, 1128, 3111, 'When he got upon his feet at last and moved feebly downtown, a melancholy change had come over everything and every creature.', '当他终于能站起来，虚弱地走到镇中心时，发现一切都变了，变得让人有点难过。'),
    (22, 1128, 3112, 'There had been a “revival,” and everybody had “got religion,” not only the adults, but even the boys and girls.', '镇上举行了一场“布道会”，每个人都“信教”了，不只是大人，连男孩和女孩们也是。'),
    (22, 1128, 3113, 'Tom went about, hoping against hope for the sight of one blessed sinful face, but disappointment crossed him everywhere.', '汤姆到处转悠，多希望能看到一张没信教的脸，可去哪儿都让他失望。'),
    (22, 1128, 3114, 'He found Joe Harper studying a Testament, and turned sadly away from the depressing spectacle.', '他发现乔·哈珀正在读《圣经》，就伤心地走开了，因为这景象太让他难过了。'),
    (22, 1128, 3115, 'He sought Ben Rogers, and found him visiting the poor with a basket of tracts.', '他去找本·罗杰斯，发现本·罗杰斯正提着一篮子传教小册子去探望穷人。'),
    (22, 1128, 3116, 'He hunted up Jim Hollis, who called his attention to the precious blessing of his late measles as a warning.', '他找到了吉姆·霍利斯，霍利斯提醒他，他最近得了麻疹，这是个重要的警告。'),
    (22, 1128, 3117, 'Every boy he encountered added another ton to his depression; and when, in desperation, he flew for refuge at last to the bosom of Huckleberry Finn and was received with a Scriptural quotation, his heart broke and he crept home and to bed realizing that he alone of all the town was lost, forever and forever.', '他遇到的每个男孩都让他更沮丧；绝望中，他终于跑到哈克贝利·费恩身边寻求安慰，没想到哈克贝利·费恩却用了一句《圣经》里的话来对他。他心都碎了，悄悄地爬回了家，躺到床上，他觉得整个镇上只有自己是迷失的，永远地迷失了。'),
    (22, 1129, 3118, 'And that night there came on a terrific storm, with driving rain, awful claps of thunder and blinding sheets of lightning.', '那天晚上，外面下起了可怕的暴风雨，瓢泼大雨，雷声阵阵，闪电耀眼。'),
    (22, 1129, 3119, 'He covered his head with the bedclothes and waited in a horror of suspense for his doom; for he had not the shadow of a doubt that all this hubbub was about him.', '他用被子蒙住头，非常害怕地等待着，觉得惩罚要来了。因为他一点儿也不怀疑，外面所有的吵闹都是因为他。'),
    (22, 1129, 3120, 'He believed he had taxed the forbearance of the powers above to the extremity of endurance and that this was the result.', '他觉得他惹恼了上天，上天已经忍无可忍了，而这暴风雨就是上天给他的惩罚。'),
    (22, 1129, 3121, 'It might have seemed to him a waste of pomp and ammunition to kill a bug with a battery of artillery, but there seemed nothing incongruous about the getting up such an expensive thunderstorm as this to knock the turf from under an insect like himself.', '他觉得用大炮打一只小虫子有点浪费。可是，如果一场大雷雨把他这样的小虫子冲走，他倒觉得一点也不奇怪。'),
    (22, 1130, 3122, 'By and by the tempest spent itself and died without accomplishing its object.', '慢慢地，大风大雨自己停了。它想做的事情，一件也没做成。'),
    (22, 1130, 3123, 'The boy’s first impulse was to be grateful, and reform.', '小男孩最先想的是：要谢谢老天，以后要变好。'),
    (22, 1130, 3124, 'His second was to wait—for there might not be any more storms.', '他第二个想法是等等看——也许不会再有大风大雨了。'),
    (22, 1131, 3125, 'The next day the doctors were back; Tom had relapsed.', '第二天，医生们又来了。汤姆的病又犯了。'),
    (22, 1131, 3126, 'The three weeks he spent on his back this time seemed an entire age.', '这次他躺在床上三星期，感觉就像过了一个世纪那么久。'),
    (22, 1131, 3127, 'When he got abroad at last he was hardly grateful that he had been spared, remembering how lonely was his estate, how companionless and forlorn he was.', '当他终于能出门时，他一点也不开心自己还活着。他想到自己是多么孤单，一个朋友也没有。'),
    (22, 1131, 3128, 'He drifted listlessly down the street and found Jim Hollis acting as judge in a juvenile court that was trying a cat for murder, in the presence of her victim, a bird.', '他没精打采地走在街上，看到吉姆霍利斯正在“小朋友的法庭”里当法官。他们在审一只猫，因为那只猫杀了一只小鸟，小鸟就在旁边。'),
    (22, 1131, 3129, 'He found Joe Harper and Huck Finn up an alley eating a stolen melon.', '他看到乔·哈珀和哈克芬在小巷子里，吃着偷来的甜瓜。'),
    (22, 1131, 3130, 'Poor lads! they—like Tom—had suffered a relapse.', '可怜的孩子们！他们——也像汤姆一样——又犯病了。'),
    (23, 1132, 3131, 'At last the sleepy atmosphere was stirred—and vigorously: the murder trial came on in the court.', '终于，这里安静的气氛被打破了——而且是很热闹地打破了：法庭要审理那件杀人案了。'),
    (23, 1132, 3132, 'It became the absorbing topic of village talk immediately.', '这事马上就成了村子里大家都在说的话题。'),
    (23, 1132, 3133, 'Tom could not get away from it.', '汤姆根本就躲不开这事。'),
    (23, 1132, 3134, 'Every reference to the murder sent a shudder to his heart, for his troubled conscience and fears almost persuaded him that these remarks were put forth in his hearing as “feelers”; he did not see how he could be suspected of knowing anything about the murder, but still he could not be comfortable in the midst of this gossip.', '每次听到大家说杀人案，他心里就发抖。他做了亏心事，心里害怕，总觉得大家是故意说给他听，想试探他。他不知道大家怎么会怀疑他知道杀人案的事，可他听到这些话，就是不舒服。'),
    (23, 1132, 3135, 'It kept him in a cold shiver all the time.', '这让他一直不停地发抖。'),
    (23, 1132, 3136, 'He took Huck to a lonely place to have a talk with him.', '他把哈克带到一个没人的地方，想和他说说话。'),
    (23, 1132, 3137, 'It would be some relief to unseal his tongue for a little while; to divide his burden of distress with another sufferer.', '说出来会让他心里好受一点；把心里难受的事情，分给另一个一样难受的朋友一点。'),
    (23, 1132, 3138, 'Moreover, he wanted to assure himself that Huck had remained discreet.', '而且，他还想确定哈克一直都保守着秘密，没跟别人说。'),
    (23, 1133, 3139, '“Huck, have you ever told anybody about—that?”', '“哈克，你有没有跟别人说过——那件事？”'),
    (23, 1134, 3140, '“’Bout what?”', '“说什么啊？”'),
    (23, 1135, 3141, '“You know what.”', '“你知道是什么事。”'),
    (23, 1136, 3142, '“Oh—’course I haven’t.”', '“哦——我当然没有说啊。”'),
    (23, 1137, 3143, '“Never a word?”', '“一个字都没说吗？”'),
    (23, 1138, 3144, '“Never a solitary word, so help me.', '“一个字都没说，我发誓。'),
    (23, 1138, 3145, 'What makes you ask?”', '你为什么问这个呢？”'),
    (23, 1139, 3146, '“Well, I was afeard.”', '“嗯，我有点害怕。”'),
    (23, 1140, 3147, '“Why, Tom Sawyer, we wouldn’t be alive two days if that got found out.', '“哎呀，汤姆·索亚，要是那件事被发现了，我们两天都活不了的。'),
    (23, 1140, 3148, '_You_ know that.”', '你_知道_的。”'),
    (23, 1141, 3149, 'Tom felt more comfortable.', '汤姆心里舒服多了。'),
    (23, 1141, 3150, 'After a pause:', '停顿了一下：'),
    (23, 1142, 3151, '“Huck, they couldn’t anybody get you to tell, could they?”', '“哈克，他们没法让你说出来，是吗？”'),
    (23, 1143, 3152, '“Get me to tell?', '“让我说出来？'),
    (23, 1143, 3153, 'Why, if I wanted that halfbreed devil to drownd me they could get me to tell.', '要是我想让那个坏蛋把我淹死，他们就能让我说出来。'),
    (23, 1143, 3154, 'They ain’t no different way.”', '没有别的办法了。”'),
    (23, 1144, 3155, '“Well, that’s all right, then.', '“嗯，那好吧。'),
    (23, 1144, 3156, 'I reckon we’re safe as long as we keep mum.', '我想只要我们不说，我们就安全了。'),
    (23, 1144, 3157, 'But let’s swear again, anyway.', '不过我们还是再发一次誓吧。'),
    (23, 1144, 3158, 'It’s more surer.”', '这样更保险一些。”'),
    (23, 1145, 3159, '“I’m agreed.”', '“我同意。”'),
    (23, 1146, 3160, 'So they swore again with dread solemnities.', '于是他们又严肃地发了一次誓。'),
    (23, 1147, 3161, '“What is the talk around, Huck?', '“外面都在说什么，哈克？'),
    (23, 1147, 3162, 'I’ve heard a power of it.”', '我听到了很多。”'),
    (23, 1148, 3163, '“Talk?', '“说什么？'),
    (23, 1148, 3164, 'Well, it’s just Muff Potter, Muff Potter, Muff Potter all the time.', '嗯，就是一直在说莫夫·波特、莫夫·波特、莫夫·波特。'),
    (23, 1148, 3165, 'It keeps me in a sweat, constant, so’s I want to hide som’ers.”', '我一直很紧张，想找个地方躲起来。”'),
    (23, 1149, 3166, '“That’s just the same way they go on round me.', '“他们在我身边也是那样说。'),
    (23, 1149, 3167, 'I reckon he’s a goner.', '我想他这次肯定完了。'),
    (23, 1149, 3168, 'Don’t you feel sorry for him, sometimes?”', '你有时不替他难过吗？”'),
    (23, 1150, 3169, '“Most always—most always.', '“差不多总是这样——差不多总是这样。'),
    (23, 1150, 3170, 'He ain’t no account; but then he hain’t ever done anything to hurt anybody.', '他没什么用；但他从没做过什么坏事伤害别人。'),
    (23, 1150, 3171, 'Just fishes a little, to get money to get drunk on—and loafs around considerable; but lord, we all do that—leastways most of us—preachers and such like.', '他只是钓鱼赚点钱去喝酒——然后到处闲逛；但是天哪，我们大家——至少我们大多数人——牧师什么的，都那样做。'),
    (23, 1150, 3172, 'But he’s kind of good—he give me half a fish, once, when there warn’t enough for two; and lots of times he’s kind of stood by me when I was out of luck.”', '但他还挺好的——有一次鱼不够两个人吃，他给了我一半；还有好多次，我倒霉的时候他都帮我。”'),
    (23, 1151, 3173, '“Well, he’s mended kites for me, Huck, and knitted hooks on to my line.', '“嗯，他给我修过风筝，哈克，还在我的鱼线上系过鱼钩。'),
    (23, 1151, 3174, 'I wish we could get him out of there.”', '我真希望我们能把他救出来。”'),
    (23, 1152, 3175, '“My! we couldn’t get him out, Tom.', '“哎呀！我们救不了他，汤姆。'),
    (23, 1152, 3176, 'And besides, ’twouldn’t do any good; they’d ketch him again.”', '而且，就算救出来也没用；他们还会再把他抓回去的。”'),
    (23, 1153, 3177, '“Yes—so they would.', '“是啊——他们会的。'),
    (23, 1153, 3178, 'But I hate to hear ’em abuse him so like the dickens when he never done—that.”', '但我讨厌听到他们那样骂他，他从没做过——那样的事。”'),
    (23, 1154, 3179, '“I do too, Tom.', '“我也是，汤姆。'),
    (23, 1154, 3180, 'Lord, I hear ’em say he’s the bloodiest looking villain in this country, and they wonder he wasn’t ever hung before.”', '天哪，我听到他们说他是这个国家最坏的坏蛋，他们还奇怪他怎么没被吊死过。”'),
    (23, 1155, 3181, '“Yes, they talk like that, all the time.', '“对，他们总是这样说。'),
    (23, 1155, 3182, 'I’ve heard ’em say that if he was to get free they’d lynch him.”', '我听他们说，如果他跑了，他们就会把他吊起来。”'),
    (23, 1156, 3183, '“And they’d do it, too.”', '“他们真的会这么做。”'),
    (23, 1157, 3184, 'The boys had a long talk, but it brought them little comfort.', '两个男孩聊了很久，但心里还是很难过。'),
    (23, 1157, 3185, 'As the twilight drew on, they found themselves hanging about the neighborhood of the little isolated jail, perhaps with an undefined hope that something would happen that might clear away their difficulties.', '傍晚时分，他们来到那座小监狱附近，心里隐隐希望有什么事情发生，能解决他们的难题。'),
    (23, 1157, 3186, 'But nothing happened; there seemed to be no angels or fairies interested in this luckless captive.', '可是什么也没发生；好像没有天使或小仙女来帮助这个可怜的人。'),
    (23, 1158, 3187, 'The boys did as they had often done before—went to the cell grating and gave Potter some tobacco and matches.', '两个男孩像以前一样，来到牢房的铁栏杆那里，给了 波特 一些烟草和火柴。'),
    (23, 1158, 3188, 'He was on the ground floor and there were no guards.', '他在底楼，旁边没有看守。'),
    (23, 1159, 3189, 'His gratitude for their gifts had always smote their consciences before—it cut deeper than ever, this time.', '以前，他感谢他们的礼物时，他们心里就有点过意不去——这次，他们更觉得难受了。'),
    (23, 1159, 3190, 'They felt cowardly and treacherous to the last degree when Potter said:', '当 波特 说这些话时，他们觉得自己非常胆小和背叛。'),
    (23, 1160, 3191, '“You’ve been mighty good to me, boys—better’n anybody else in this town.', '“你们对我真好，孩子们——比城里任何人都好。'),
    (23, 1160, 3192, 'And I don’t forget it, I don’t.', '我不会忘记的，真的不会。'),
    (23, 1160, 3193, 'Often I says to myself, says I, ‘I used to mend all the boys’ kites and things, and show ’em where the good fishin’ places was, and befriend ’em what I could, and now they’ve all forgot old Muff when he’s in trouble; but Tom don’t, and Huck don’t—_they_ don’t forget him,’ says I, ‘and I don’t forget them.’', '我常常对自己说，‘我以前帮所有的孩子们修风筝，告诉他们哪里有好的钓鱼地方，尽力帮助他们。可现在，当老穆夫有麻烦时，他们都忘了。但 汤姆 没有忘， 哈克 也没有忘——他们没有忘记他，’我说，‘我也不会忘记他们。’'),
    (23, 1160, 3194, 'Well, boys, I done an awful thing—drunk and crazy at the time—that’s the only way I account for it—and now I got to swing for it, and it’s right.', '哎，孩子们，我做了一件很糟糕的事——当时喝醉了，也疯了——我只能这样解释——现在我得为此付出代价了，这是对的。'),
    (23, 1160, 3195, 'Right, and _best_, too, I reckon—hope so, anyway.', '对，而且也许是最好的，我猜——反正我是这么希望的。'),
    (23, 1160, 3196, 'Well, we won’t talk about that.', '好了，我们别说这个了。'),
    (23, 1160, 3197, 'I don’t want to make _you_ feel bad; you’ve befriended me.', '我不想让你们难过；你们一直对我很好。'),
    (23, 1160, 3198, 'But what I want to say, is, don’t _you_ ever get drunk—then you won’t ever get here.', '但我想说的是，你们千万不要喝醉——这样就不会来到这里。'),
    (23, 1160, 3199, 'Stand a litter furder west—so—that’s it; it’s a prime comfort to see faces that’s friendly when a body’s in such a muck of trouble, and there don’t none come here but yourn.', '站远一点，往西边一点——对——就是这样；一个人遇到这么多麻烦时，能看到友善的脸，真是很大的安慰，除了你们，没人来看我。'),
    (23, 1160, 3200, 'Good friendly faces—good friendly faces.', '友善的脸——友善的脸。'),
    (23, 1160, 3201, 'Git up on one another’s backs and let me touch ’em.', '你们爬到对方背上，让我摸摸你们。'),
    (23, 1160, 3202, 'That’s it.', '就是这样。'),
    (23, 1160, 3203, 'Shake hands—yourn’ll come through the bars, but mine’s too big.', '握握手——你们的手能伸过铁栏，但我的手太大了。'),
    (23, 1160, 3204, 'Little hands, and weak—but they’ve helped Muff Potter a power, and they’d help him more if they could.”', '小小的手，弱弱的——但它们帮了 莫夫·波特 大忙，如果可以，它们还会帮他更多。”'),
    (23, 1161, 3205, 'Tom went home miserable, and his dreams that night were full of horrors.', '汤姆 难过地回家了，那天晚上他做的梦都是可怕的。'),
    (23, 1161, 3206, 'The next day and the day after, he hung about the courtroom, drawn by an almost irresistible impulse to go in, but forcing himself to stay out.', '接下来的一天又一天，他一直在法庭外面徘徊，心里非常想进去，但又强迫自己留在外面。'),
    (23, 1161, 3207, 'Huck was having the same experience.', '哈克 也有着同样的感受。'),
    (23, 1161, 3208, 'They studiously avoided each other.', '他们很小心地避开对方。'),
    (23, 1161, 3209, 'Each wandered away, from time to time, but the same dismal fascination always brought them back presently.', '两人时常会走开，但那种悲伤的吸引力总是很快又把他们带回来。'),
    (23, 1161, 3210, 'Tom kept his ears open when idlers sauntered out of the courtroom, but invariably heard distressing news—the toils were closing more and more relentlessly around poor Potter.', '汤姆 仔细听着那些从法庭里闲逛出来的人说话，但总是听到不好的消息——困境正一步步地紧逼着可怜的 波特。'),
    (23, 1161, 3211, 'At the end of the second day the village talk was to the effect that Injun Joe’s evidence stood firm and unshaken, and that there was not the slightest question as to what the jury’s verdict would be.', '第二天快结束时，村里人都在说印第安·乔的证据很牢固。大家觉得，陪审团会怎么判，已经很清楚了。'),
    (23, 1162, 3212, 'Tom was out late, that night, and came to bed through the window.', '那个晚上，汤姆很晚才回来。他是从窗户爬进屋的，然后去睡觉了。'),
    (23, 1162, 3213, 'He was in a tremendous state of excitement.', '他非常非常兴奋。'),
    (23, 1162, 3214, 'It was hours before he got to sleep.', '过了好几个小时他才睡着。'),
    (23, 1162, 3215, 'All the village flocked to the courthouse the next morning, for this was to be the great day.', '第二天早上，全村人都跑去法院了。因为这一天会发生大事。'),
    (23, 1162, 3216, 'Both sexes were about equally represented in the packed audience.', '挤满了人的旁听席上，男人女人差不多一样多。'),
    (23, 1162, 3217, 'After a long wait the jury filed in and took their places; shortly afterward, Potter, pale and haggard, timid and hopeless, was brought in, with chains upon him, and seated where all the curious eyes could stare at him; no less conspicuous was Injun Joe, stolid as ever.', '等了很久，陪审团的人才走进来坐好。没多久，波特被带了进来。他脸色苍白，瘦瘦的，很害怕，也没了希望。他身上带着链子，被安排坐在那里，所有人都盯着他看。印第安·乔也一样显眼，他还是那么平静。'),
    (23, 1162, 3218, 'There was another pause, and then the judge arrived and the sheriff proclaimed the opening of the court.', '又安静了一会儿，法官来了。警长宣布，现在开庭！'),
    (23, 1162, 3219, 'The usual whisperings among the lawyers and gathering together of papers followed.', '律师们像平时一样小声地交谈，整理着文件。'),
    (23, 1162, 3220, 'These details and accompanying delays worked up an atmosphere of preparation that was as impressive as it was fascinating.', '这些小细节和等待的时间，让气氛变得很庄重，也很吸引人。'),
    (23, 1163, 3221, 'Now a witness was called who testified that he found Muff Potter washing in the brook, at an early hour of the morning that the murder was discovered, and that he immediately sneaked away.', '这时，有人被叫来作证。他说，在发现凶案的那天早上很早的时候，他看到莫夫·波特在小溪边洗东西。莫夫·波特一看到他，就赶紧溜走了。'),
    (23, 1163, 3222, 'After some further questioning, counsel for the prosecution said:', '又问了几句，控方律师说：'),
    (23, 1164, 3223, '“Take the witness.”', '“请问证人吧。”'),
    (23, 1165, 3224, 'The prisoner raised his eyes for a moment, but dropped them again when his own counsel said:', '犯人抬了一下头，但听到自己的律师说话，又把头低了下去。'),
    (23, 1166, 3225, '“I have no questions to ask him.”', '“我没什么要问他的。”'),
    (23, 1167, 3226, 'The next witness proved the finding of the knife near the corpse.', '下一个证人证明，那把刀是在尸体旁边找到的。'),
    (23, 1167, 3227, 'Counsel for the prosecution said:', '控方律师说：'),
    (23, 1168, 3228, '“Take the witness.”', '“请问证人吧。”'),
    (23, 1169, 3229, '“I have no questions to ask him,” Potter’s lawyer replied.', '“我没什么要问他的，”波特的律师说。'),
    (23, 1170, 3230, 'A third witness swore he had often seen the knife in Potter’s possession.', '第三个证人发誓说，他经常看到波特带着那把刀。'),
    (23, 1171, 3231, '“Take the witness.”', '“请问证人吧。”'),
    (23, 1172, 3232, 'Counsel for Potter declined to question him.', '波特的律师还是没有问他问题。'),
    (23, 1172, 3233, 'The faces of the audience began to betray annoyance.', '旁听的人脸上开始露出不高兴的样子。'),
    (23, 1172, 3234, 'Did this attorney mean to throw away his client’s life without an effort?', '这个律师难道要不努力就让当事人白白送命吗？'),
    (23, 1173, 3235, 'Several witnesses deposed concerning Potter’s guilty behavior when brought to the scene of the murder.', '好几个证人都说，当波特被带到案发现场时，他表现得就像是个罪犯。'),
    (23, 1173, 3236, 'They were allowed to leave the stand without being cross-questioned.', '他们可以离开了，没有人反过来问他们问题。'),
    (23, 1174, 3237, 'Every detail of the damaging circumstances that occurred in the graveyard upon that morning which all present remembered so well was brought out by credible witnesses, but none of them were cross-examined by Potter’s lawyer.', '那天早上，墓地里发生了很多对波特不利的事。在场的人都记得很清楚。可靠的证人把每个细节都说了出来，但波特的律师一个也没反问。'),
    (23, 1174, 3238, 'The perplexity and dissatisfaction of the house expressed itself in murmurs and provoked a reproof from the bench.', '旁听的人又困惑又不满，大家都小声议论起来，法官只好批评了他们。'),
    (23, 1174, 3239, 'Counsel for the prosecution now said:', '控方律师现在说：'),
    (23, 1175, 3240, '“By the oaths of citizens whose simple word is above suspicion, we have fastened this awful crime, beyond all possibility of question, upon the unhappy prisoner at the bar.', '“那些公民都发誓了，他们说的话谁都相信。我们已经把这件可怕的罪行，毫无疑问地，认定就是这个不幸的犯人做的。”'),
    (23, 1175, 3241, 'We rest our case here.”', '我们的案子讲完了。'),
    (23, 1176, 3242, 'A groan escaped from poor Potter, and he put his face in his hands and rocked his body softly to and fro, while a painful silence reigned in the courtroom.', '可怜的波特哼了一声，他把脸埋在手里，轻轻地摇晃身体。法庭里非常安静，让人觉得心里很难过。'),
    (23, 1176, 3243, 'Many men were moved, and many women’s compassion testified itself in tears.', '很多叔叔伯伯都很难过，很多阿姨奶奶都哭了，眼泪哗哗地流下来。'),
    (23, 1176, 3244, 'Counsel for the defence rose and said:', '律师叔叔站起来说：'),
    (23, 1177, 3245, '“Your honor, in our remarks at the opening of this trial, we foreshadowed our purpose to prove that our client did this fearful deed while under the influence of a blind and irresponsible delirium produced by drink.', '“法官爷爷，我们最开始说，要证明他做这件可怕的事，是因为喝醉了，喝得迷迷糊糊，什么都不知道了。'),
    (23, 1177, 3246, 'We have changed our mind.', '我们现在改变想法了。'),
    (23, 1177, 3247, 'We shall not offer that plea.”', '我们不打算那么说了。”'),
    (23, 1177, 3248, '[Then to the clerk:] “Call Thomas Sawyer!”', '[然后对旁边的人说：]“叫托马斯·索亚来！”'),
    (23, 1178, 3249, 'A puzzled amazement awoke in every face in the house, not even excepting Potter’s.', '屋子里所有人的脸上都露出了吃惊又疑惑的表情，连波特也是一样。'),
    (23, 1178, 3250, 'Every eye fastened itself with wondering interest upon Tom as he rose and took his place upon the stand.', '大家好奇的眼睛都盯着汤姆。他站起来，走到前面站着。'),
    (23, 1178, 3251, 'The boy looked wild enough, for he was badly scared.', '这个小男孩看起来很害怕，他吓得不轻。'),
    (23, 1178, 3252, 'The oath was administered.', '他进行了宣誓。'),
    (23, 1179, 3253, '“Thomas Sawyer, where were you on the seventeenth of June, about the hour of midnight?”', '“托马斯·索亚，六月十七号半夜的时候，你在哪里呀？”'),
    (23, 1180, 3254, 'Tom glanced at Injun Joe’s iron face and his tongue failed him.', '汤姆看了一眼印第安·乔那张没有表情的脸，吓得说不出话来了。'),
    (23, 1180, 3255, 'The audience listened breathless, but the words refused to come.', '大家都在屏住呼吸听着，可是他就是说不出话。'),
    (23, 1180, 3256, 'After a few moments, however, the boy got a little of his strength back, and managed to put enough of it into his voice to make part of the house hear:', '过了一会儿，小男孩才稍微有了点力气，他努力让自己的声音大一点，好让屋子里的一些人能听到：'),
    (23, 1181, 3257, '“In the graveyard!”', '“在墓地里！”'),
    (23, 1182, 3258, '“A little bit louder, please.', '“请再大声一点。'),
    (23, 1182, 3259, 'Don’t be afraid.', '别害怕哦。'),
    (23, 1182, 3260, 'You were—”', '你当时在——”'),
    (23, 1183, 3261, '“In the graveyard.”', '“在墓地里。”'),
    (23, 1184, 3262, 'A contemptuous smile flitted across Injun Joe’s face.', '印第安·乔的脸上闪过一丝不屑的笑。'),
    (23, 1185, 3263, '“Were you anywhere near Horse Williams’ grave?”', '“你当时在马·威廉姆斯的坟墓旁边吗？”'),
    (23, 1186, 3264, '“Yes, sir.”', '“是的，先生。”'),
    (23, 1187, 3265, '“Speak up—just a trifle louder.', '“大声点——再大声一点点。'),
    (23, 1187, 3266, 'How near were you?”', '你离得有多近？”'),
    (23, 1188, 3267, '“Near as I am to you.”', '“就像我现在离你这么近。”'),
    (23, 1189, 3268, '“Were you hidden, or not?”', '“你是藏起来了，还是没有？”'),
    (23, 1190, 3269, '“I was hid.”', '“我藏起来了。”'),
    (23, 1191, 3270, '“Where?”', '“藏在哪里？”'),
    (23, 1192, 3271, '“Behind the elms that’s on the edge of the grave.”', '在墓地边上的榆树后面。'),
    (23, 1193, 3272, 'Injun Joe gave a barely perceptible start.', '印第安·乔 轻轻地抖了一下。'),
    (23, 1194, 3273, '“Any one with you?”', '有谁和你一起吗？'),
    (23, 1195, 3274, '“Yes, sir.', '是的，先生。'),
    (23, 1195, 3275, 'I went there with—”', '我跟—'),
    (23, 1196, 3276, '“Wait—wait a moment.', '等等—等等一下。'),
    (23, 1196, 3277, 'Never mind mentioning your companion’s name.', '不用说你朋友的名字。'),
    (23, 1196, 3278, 'We will produce him at the proper time.', '我们会在合适的时候让他出现。'),
    (23, 1196, 3279, 'Did you carry anything there with you.”', '你有没有带什么东西去那里？'),
    (23, 1197, 3280, 'Tom hesitated and looked confused.', '汤姆 犹豫了一下，看起来很困惑。'),
    (23, 1198, 3281, '“Speak out, my boy—don’t be diffident.', '大胆地说出来，孩子—不要害羞。'),
    (23, 1198, 3282, 'The truth is always respectable.', '说实话总是好的。'),
    (23, 1198, 3283, 'What did you take there?”', '你带了什么去那里？'),
    (23, 1199, 3284, '“Only a—a—dead cat.”', '只是一只—一只—死猫。'),
    (23, 1200, 3285, 'There was a ripple of mirth, which the court checked.', '大家有点想笑，但法庭制止了。'),
    (23, 1201, 3286, '“We will produce the skeleton of that cat.', '我们会找到那只猫的骨头。'),
    (23, 1201, 3287, 'Now, my boy, tell us everything that occurred—tell it in your own way—don’t skip anything, and don’t be afraid.”', '现在，孩子，把发生的一切都告诉我们—用你自己的方式说—不要跳过任何事，也不要害怕。'),
    (23, 1202, 3288, 'Tom began—hesitatingly at first, but as he warmed to his subject his words flowed more and more easily; in a little while every sound ceased but his own voice; every eye fixed itself upon him; with parted lips and bated breath the audience hung upon his words, taking no note of time, rapt in the ghastly fascinations of the tale.', '汤姆 开始说了—一开始有些犹豫，但当他越说越起劲，话也越来越顺畅；不一会儿，除了他自己的声音，周围一片安静；所有人的眼睛都盯着他；大家张着嘴巴，屏住呼吸，紧紧地听着他的话，完全忘了时间，被这个可怕故事的魅力深深吸引住了。'),
    (23, 1202, 3289, 'The strain upon pent emotion reached its climax when the boy said:', '当孩子说到这里时，大家紧张的心情达到了顶点：'),
    (23, 1203, 3290, '“—and as the doctor fetched the board around and Muff Potter fell, Injun Joe jumped with the knife and—”', '—当医生把木板拿过来，莫夫·波特 倒下时，印第安·乔 拿着刀跳了过去，然后—'),
    (23, 1204, 3291, 'Crash!', '砰！'),
    (23, 1204, 3292, 'Quick as lightning the halfbreed sprang for a window, tore his way through all opposers, and was gone!', '那个混血儿像闪电一样冲向窗户，推开所有挡路的人，逃走了！'),
    (24, 1205, 3293, 'Tom was a glittering hero once more—the pet of the old, the envy of the young.', '汤姆 又一次成了闪亮的英雄—老人们喜欢他，年轻人都羡慕他。'),
    (24, 1205, 3294, 'His name even went into immortal print, for the village paper magnified him.', '他的名字甚至登上了报纸，因为村里的报纸把他夸大了。'),
    (24, 1205, 3295, 'There were some that believed he would be President, yet, if he escaped hanging.', '有些人甚至觉得他将来会当总统，只要他能躲过绞刑。'),
    (24, 1206, 3296, 'As usual, the fickle, unreasoning world took Muff Potter to its bosom and fondled him as lavishly as it had abused him before.', '和往常一样，这个喜怒无常、不讲道理的世界，现在又把 莫夫·波特 捧在手心里疼爱，就像以前狠狠骂他一样。'),
    (24, 1206, 3297, 'But that sort of conduct is to the world’s credit; therefore it is not well to find fault with it.', '但这种做法是对世界有好处的；所以不应该去挑剔它。'),
    (24, 1207, 3298, 'Tom’s days were days of splendor and exultation to him, but his nights were seasons of horror.', '对 汤姆 来说，白天是光彩夺目、充满喜悦的，但夜晚却是可怕的。'),
    (24, 1207, 3299, 'Injun Joe infested all his dreams, and always with doom in his eye.', '印第安·乔 出现在他所有的梦里，眼睛里总是带着不祥的预兆。'),
    (24, 1207, 3300, 'Hardly any temptation could persuade the boy to stir abroad after nightfall.', '几乎没有任何诱惑能让这个孩子在天黑后出门。'),
    (24, 1207, 3301, 'Poor Huck was in the same state of wretchedness and terror, for Tom had told the whole story to the lawyer the night before the great day of the trial, and Huck was sore afraid that his share in the business might leak out, yet, notwithstanding Injun Joe’s flight had saved him the suffering of testifying in court.', '可怜的 哈克 也吓坏了，很难过。因为 汤姆 在开庭前一晚，把所有的事情都告诉了律师。哈克 很担心自己的秘密也会被别人知道。幸好 印第安·乔 逃走了，他才不用去法庭说那些事。'),
    (24, 1207, 3302, 'The poor fellow had got the attorney to promise secrecy, but what of that?', '那个可怜的人，让律师答应会保密，可是这有用吗？'),
    (24, 1207, 3303, 'Since Tom’s harassed conscience had managed to drive him to the lawyer’s house by night and wring a dread tale from lips that had been sealed with the dismalest and most formidable of oaths, Huck’s confidence in the human race was wellnigh obliterated.', '汤姆 心里很难受，半夜跑到律师家，把秘密都说了出来。那些秘密原本是被最可怕的誓言藏着的。这让 哈克 觉得，他再也不能相信人类了。'),
    (24, 1208, 3304, 'Daily Muff Potter’s gratitude made Tom glad he had spoken; but nightly he wished he had sealed up his tongue.', '白天的时候，莫夫·波特 很感谢 汤姆 说了实话，这让 汤姆 很高兴。可到了晚上，他又希望自己没说那些话。'),
    (24, 1209, 3305, 'Half the time Tom was afraid Injun Joe would never be captured; the other half he was afraid he would be.', '汤姆 有时候担心 印第安·乔 永远也抓不到；有时候又担心 印第安·乔 会被抓到。'),
    (24, 1209, 3306, 'He felt sure he never could draw a safe breath again until that man was dead and he had seen the corpse.', '他觉得，除非那个人死了，他亲眼看到那具尸体，不然他永远都不能安心地呼吸。'),
    (24, 1210, 3307, 'Rewards had been offered, the country had been scoured, but no Injun Joe was found.', '大家悬赏找人，把全国都搜了一遍，可还是没有找到 印第安·乔。'),
    (24, 1210, 3308, 'One of those omniscient and awe-inspiring marvels, a detective, came up from St. Louis, moused around, shook his head, looked wise, and made that sort of astounding success which members of that craft usually achieve.', '有一位很厉害的侦探，他是从圣路易斯来的。他什么都知道，很让人佩服。他四处转转，摇摇头，看起来很聪明，然后就和别的侦探一样，有了一个了不起的发现。'),
    (24, 1210, 3309, 'That is to say, he “found a clew.”', '也就是说，他“找到了一个线索”。'),
    (24, 1210, 3310, 'But you can’t hang a “clew” for murder, and so after that detective had got through and gone home, Tom felt just as insecure as he was before.', '可是，你不能把一个“线索”给吊死啊！所以，等那个侦探忙完了回家以后，汤姆 还是觉得一点也不安全，和以前一样。'),
    (24, 1211, 3311, 'The slow days drifted on, and each left behind it a slightly lightened weight of apprehension.', '那些日子过得很慢，可每天过去，人们的担心就少了一点点。'),
    (25, 1212, 3312, 'There comes a time in every rightly-constructed boy’s life when he has a raging desire to go somewhere and dig for hidden treasure.', '每个小男孩，总会有一段时间，非常非常想去一个地方挖宝藏。'),
    (25, 1212, 3313, 'This desire suddenly came upon Tom one day.', '有一天，汤姆 突然也想去挖宝藏了。'),
    (25, 1212, 3314, 'He sallied out to find Joe Harper, but failed of success.', '他出去找 乔·哈珀，可是没找到。'),
    (25, 1212, 3315, 'Next he sought Ben Rogers; he had gone fishing.', '接着，他又去找 本·罗杰斯；结果 本·罗杰斯 去钓鱼了。'),
    (25, 1212, 3316, 'Presently he stumbled upon Huck Finn the Red-Handed.', '很快，他碰到了“红手” 哈克 芬恩。'),
    (25, 1212, 3317, 'Huck would answer.', '哈克 会答应的。'),
    (25, 1212, 3318, 'Tom took him to a private place and opened the matter to him confidentially.', '汤姆 带他到一个没人的地方，悄悄地把事情告诉了他。'),
    (25, 1212, 3319, 'Huck was willing.', '哈克 也很愿意。'),
    (25, 1212, 3320, 'Huck was always willing to take a hand in any enterprise that offered entertainment and required no capital, for he had a troublesome superabundance of that sort of time which is not money.', '哈克 总是很乐意参加那些好玩又不用花钱的事。因为他有好多好多时间，这些时间又不能当钱用，让他有点烦恼。'),
    (25, 1212, 3321, '“Where’ll we dig?” said Huck.', '“我们去哪里挖呢？”哈克 说。'),
    (25, 1213, 3322, '“Oh, most anywhere.”', '“哦，差不多哪里都可以。”'),
    (25, 1214, 3323, '“Why, is it hid all around?”', '“为什么，到处都藏着宝藏吗？”'),
    (25, 1215, 3324, '“No, indeed it ain’t.', '“不，不是这样的。'),
    (25, 1215, 3325, 'It’s hid in mighty particular places, Huck—sometimes on islands, sometimes in rotten chests under the end of a limb of an old dead tree, just where the shadow falls at midnight; but mostly under the floor in ha’nted houses.”', '宝藏藏在很特别的地方，哈克。有时候在小岛上，有时候在老树枝下面腐烂的箱子里，就是半夜影子落下来的地方。不过，大部分宝藏都藏在有鬼的房子的地板下面。”'),
    (25, 1216, 3326, '“Who hides it?”', '“是谁把宝藏藏起来的呢？”'),
    (25, 1217, 3327, '“Why, robbers, of course—who’d you reckon?', '“当然是坏蛋强盗啦——你觉得还会是谁？'),
    (25, 1217, 3328, 'Sunday-school sup’rintendents?”', '主日学校 局长吗？”'),
    (25, 1218, 3329, '“I don’t know.', '“我不知道。'),
    (25, 1218, 3330, 'If ’twas mine I wouldn’t hide it; I’d spend it and have a good time.”', '如果是我的，我就不会藏起来。我会把它花掉，然后好好玩一玩。”'),
    (25, 1219, 3331, '“So would I.', '“我也是。'),
    (25, 1219, 3332, 'But robbers don’t do that way.', '但强盗不会那样做。'),
    (25, 1219, 3333, 'They always hide it and leave it there.”', '他们总是把它藏起来，放在那里。”'),
    (25, 1220, 3334, '“Don’t they come after it any more?”', '“他们不会再来拿了吗？”'),
    (25, 1221, 3335, '“No, they think they will, but they generally forget the marks, or else they die.', '“不会，他们以为会回来，但常常会忘记记号，或者死掉了。'),
    (25, 1221, 3336, 'Anyway, it lays there a long time and gets rusty; and by and by somebody finds an old yellow paper that tells how to find the marks—a paper that’s got to be ciphered over about a week because it’s mostly signs and hy’roglyphics.”', '反正，它就在那儿放很久，都生锈了。然后，会有人找到一张旧旧的黄纸，上面写着怎么找那些记号——那张纸要花一个星期才能看懂，因为它上面有很多符号和奇怪的画。”'),
    (25, 1222, 3337, '“Hyro—which?”', '“画——什么？”'),
    (25, 1223, 3338, '“Hy’roglyphics—pictures and things, you know, that don’t seem to mean anything.”', '“就是那种奇怪的画，还有一些图案，你懂吗？看起来没什么意思。”'),
    (25, 1224, 3339, '“Have you got one of them papers, Tom?”', '“你有没有那种纸啊，汤姆？”'),
    (25, 1225, 3340, '“No.”', '“没有。”'),
    (25, 1226, 3341, '“Well then, how you going to find the marks?”', '“那你要怎么找到那些记号呢？”'),
    (25, 1227, 3342, '“I don’t want any marks.', '“我才不要什么记号呢。'),
    (25, 1227, 3343, 'They always bury it under a ha’nted house or on an island, or under a dead tree that’s got one limb sticking out.', '他们总是把它埋在鬼屋下面，或是在岛上，或是埋在一棵枯树下面，那棵树有一根树枝伸出来。'),
    (25, 1227, 3344, 'Well, we’ve tried Jackson’s Island a little, and we can try it again some time; and there’s the old ha’nted house up the Still-House branch, and there’s lots of dead-limb trees—dead loads of ’em.”', '嗯，我们已经在杰克逊岛找了一点，以后还可以再去。还有酿酒厂那边有座老鬼屋，还有好多好多枯树呢。”'),
    (25, 1228, 3345, '“Is it under all of them?”', '“在所有这些地方下面吗？”'),
    (25, 1229, 3346, '“How you talk!', '“你胡说什么呢！'),
    (25, 1229, 3347, 'No!”', '才不是！”'),
    (25, 1230, 3348, '“Then how you going to know which one to go for?”', '“那你怎么知道要去哪个地方找呢？”'),
    (25, 1231, 3349, '“Go for all of ’em!”', '“都去！”'),
    (25, 1232, 3350, '“Why, Tom, it’ll take all summer.”', '“哎呀，汤姆，那会花掉我们整个夏天的时间呢！”'),
    (25, 1233, 3351, '“Well, what of that?', '“那又怎么样嘛？'),
    (25, 1233, 3352, 'Suppose you find a brass pot with a hundred dollars in it, all rusty and gray, or rotten chest full of di’monds.', '要是你找到一个生锈又旧的黄铜罐子，里面有一百块钱，或者一个烂烂的箱子，里面装满了钻石呢？'),
    (25, 1233, 3353, 'How’s that?”', '怎么样？”'),
    (25, 1234, 3354, 'Huck’s eyes glowed.', '哈克的眼睛发光了。'),
    (25, 1235, 3355, '“That’s bully.', '“那真棒。'),
    (25, 1235, 3356, 'Plenty bully enough for me.', '对我来说已经够好了。'),
    (25, 1235, 3357, 'Just you gimme the hundred dollars and I don’t want no di’monds.”', '你只要给我一百块钱就行，我才不要什么钻石呢。”'),
    (25, 1236, 3358, '“All right.', '“好吧。'),
    (25, 1236, 3359, 'But I bet you I ain’t going to throw off on di’monds.', '但我跟你打赌，我可不会放过钻石的。'),
    (25, 1236, 3360, 'Some of ’em’s worth twenty dollars apiece—there ain’t any, hardly, but’s worth six bits or a dollar.”', '有些钻石一颗就值二十块钱——几乎没有一颗是不值点钱的，最少也要几块钱呢。”'),
    (25, 1237, 3361, '“No!', '“不！'),
    (25, 1237, 3362, 'Is that so?”', '是这样吗？”'),
    (25, 1238, 3363, '“Cert’nly—anybody’ll tell you so.', '“当然啦——谁都会告诉你。'),
    (25, 1238, 3364, 'Hain’t you ever seen one, Huck?”', '你没见过吗，哈克？”'),
    (25, 1239, 3365, '“Not as I remember.”', '“我不记得了。”'),
    (25, 1240, 3366, '“Oh, kings have slathers of them.”', '“哦，国王有很多很多。”'),
    (25, 1241, 3367, '“Well, I don’ know no kings, Tom.”', '“嗯，我一个国王也不认识，汤姆。”'),
    (25, 1242, 3368, '“I reckon you don’t.', '“我想你是没见过。'),
    (25, 1242, 3369, 'But if you was to go to Europe you’d see a raft of ’em hopping around.”', '但你要是去欧洲，就能看到一大堆在跳来跳去。”'),
    (25, 1243, 3370, '“Do they hop?”', '“他们会跳吗？”'),
    (25, 1244, 3371, '“Hop?', '“跳？'),
    (25, 1244, 3372, '—your granny!', '——才不会呢！'),
    (25, 1244, 3373, 'No!”', '不！”'),
    (25, 1245, 3374, '“Well, what did you say they did, for?”', '“那你刚才说他们会干嘛？”'),
    (25, 1246, 3375, '“Shucks, I only meant you’d _see_ ’em—not hopping, of course—what do they want to hop for?', '“哎呀，我只是说你会_看见_他们——当然不是跳来跳去啦——他们为什么要跳呢？'),
    (25, 1246, 3376, '—but I mean you’d just see ’em—scattered around, you know, in a kind of a general way.', '——我只是说你会看到他们——到处都是，你知道，就是那种到处都能看到的样子。'),
    (25, 1246, 3377, 'Like that old humpbacked Richard.”', '就像那个驼背的老理查。”'),
    (25, 1247, 3378, '“Richard?', '“理查？'),
    (25, 1247, 3379, 'What’s his other name?”', '他还有别的名字吗？”'),
    (25, 1248, 3380, '“He didn’t have any other name.', '“他没有别的名字了。'),
    (25, 1248, 3381, 'Kings don’t have any but a given name.”', '国王都只有一个名字。”'),
    (25, 1249, 3382, '“No?”', '“没有吗？”'),
    (25, 1250, 3383, '“But they don’t.”', '“就是没有啊。”'),
    (25, 1251, 3384, '“Well, if they like it, Tom, all right; but I don’t want to be a king and have only just a given name, like a nigger.', '“嗯，要是他们喜欢那样，汤姆，那好吧；但我不想当国王，只有一个名字，像个黑人。'),
    (25, 1251, 3385, 'But say—where you going to dig first?”', '不过，你说——我们先去哪里挖呢？”'),
    (25, 1252, 3386, '“Well, I don’t know.', '“嗯，我不知道。'),
    (25, 1252, 3387, 'S’pose we tackle that old dead-limb tree on the hill t’other side of Still-House branch?”', '要不我们去小溪对面的山上，那棵枯树旁边看看？”'),
    (25, 1253, 3388, '“I’m agreed.”', '“我同意。”'),
    (25, 1254, 3389, 'So they got a crippled pick and a shovel, and set out on their three-mile tramp.', '于是他们拿了一把坏了的镐和一把铁锹，就开始了三英里的徒步旅行。'),
    (25, 1254, 3390, 'They arrived hot and panting, and threw themselves down in the shade of a neighboring elm to rest and have a smoke.', '他们又热又喘地到了，一头栽进旁边榆树的树荫下休息，还抽了根烟。'),
    (25, 1255, 3391, '“I like this,” said Tom.', '“我喜欢这个，”汤姆 说。'),
    (25, 1256, 3392, '“So do I.”', '“我也喜欢。”'),
    (25, 1257, 3393, '“Say, Huck, if we find a treasure here, what you going to do with your share?”', '“哎，哈克，要是我们在这儿找到宝藏，你的那份要怎么用啊？”'),
    (25, 1258, 3394, '“Well, I’ll have pie and a glass of soda every day, and I’ll go to every circus that comes along.', '“嗯，我要每天都吃派，喝一杯汽水，还要去看所有的马戏表演。'),
    (25, 1258, 3395, 'I bet I’ll have a gay time.”', '我敢说我会玩得很开心。”'),
    (25, 1259, 3396, '“Well, ain’t you going to save any of it?”', '“哎，你就不打算存一点吗？”'),
    (25, 1260, 3397, '“Save it?', '“存起来？'),
    (25, 1260, 3398, 'What for?”', '为什么呀？”'),
    (25, 1261, 3399, '“Why, so as to have something to live on, by and by.”', '“哎呀，以后好有钱用啊。”'),
    (25, 1262, 3400, '“Oh, that ain’t any use.', '“哦，那没用。'),
    (25, 1262, 3401, 'Pap would come back to thish-yer town some day and get his claws on it if I didn’t hurry up, and I tell you he’d clean it out pretty quick.', '我爸爸哪天会回来这镇上，要是我不快点花掉，他会把钱都拿走的，我跟你说，他会很快花光的。'),
    (25, 1262, 3402, 'What you going to do with yourn, Tom?”', '汤姆，你的那份打算怎么用啊？”'),
    (25, 1263, 3403, '“I’m going to buy a new drum, and a sure’nough sword, and a red necktie and a bull pup, and get married.”', '“我要买个新鼓，一把真剑，一条红领带，一只小牛头犬，还要结婚。”'),
    (25, 1264, 3404, '“Married!”', '“结婚？！”'),
    (25, 1265, 3405, '“That’s it.”', '“就是这样。”'),
    (25, 1266, 3406, '“Tom, you—why, you ain’t in your right mind.”', '“汤姆，你——哎呀，你脑子不清楚了吧。”'),
    (25, 1267, 3407, '“Wait—you’ll see.”', '“等等——你会看到的。”'),
    (25, 1268, 3408, '“Well, that’s the foolishest thing you could do.', '“嗯，那可是你做的最傻的事了。'),
    (25, 1268, 3409, 'Look at pap and my mother.', '看看我爸爸和我妈妈。'),
    (25, 1268, 3410, 'Fight!', '他们吵架！'),
    (25, 1268, 3411, 'Why, they used to fight all the time.', '哎呀，他们以前总是吵架。'),
    (25, 1268, 3412, 'I remember, mighty well.”', '我记得可清楚了。”'),
    (25, 1269, 3413, '“That ain’t anything.', '“那不算什么。'),
    (25, 1269, 3414, 'The girl I’m going to marry won’t fight.”', '我要娶的女孩才不会吵架呢。”'),
    (25, 1270, 3415, '“Tom, I reckon they’re all alike.', '“汤姆，我看她们都一样。'),
    (25, 1270, 3416, 'They’ll all comb a body.', '她们都会管着别人的。'),
    (25, 1270, 3417, 'Now you better think ’bout this awhile.', '你最好好好想想这事儿。'),
    (25, 1270, 3418, 'I tell you you better.', '我跟你说，你真的该好好想想。'),
    (25, 1270, 3419, 'What’s the name of the gal?”', '那个姑娘叫什么名字啊？”'),
    (25, 1271, 3420, '“It ain’t a gal at all—it’s a girl.”', '“不是什么姑娘——是个女孩。”'),
    (25, 1272, 3421, '“It’s all the same, I reckon; some says gal, some says girl—both’s right, like enough.', '“都一样啦，我觉得；有人说“gal”，有人说“girl”——可能都对吧。'),
    (25, 1272, 3422, 'Anyway, what’s her name, Tom?”', '话说回来，她叫什么名字啊，汤姆？”'),
    (25, 1273, 3423, '“I’ll tell you some time—not now.”', '“我以后再告诉你——现在不行。”'),
    (25, 1274, 3424, '“All right—that’ll do.', '“好吧——那也行。'),
    (25, 1274, 3425, 'Only if you get married I’ll be more lonesomer than ever.”', '只是如果你结婚了，我就会比现在更孤单了。”'),
    (25, 1275, 3426, '“No you won’t.', '“不会啦。'),
    (25, 1275, 3427, 'You’ll come and live with me.', '你会来和我一起住的。'),
    (25, 1275, 3428, 'Now stir out of this and we’ll go to digging.”', '现在快点起来，我们去挖东西吧。”'),
    (25, 1276, 3429, 'They worked and sweated for half an hour.', '他们又挖又出汗，干了半小时。'),
    (25, 1276, 3430, 'No result.', '什么也没挖到。'),
    (25, 1276, 3431, 'They toiled another halfhour.', '他们又辛苦了半小时。'),
    (25, 1276, 3432, 'Still no result.', '还是什么都没挖到。'),
    (25, 1276, 3433, 'Huck said:', '哈克说：'),
    (25, 1277, 3434, '“Do they always bury it as deep as this?”', '“他们总是埋这么深吗？”'),
    (25, 1278, 3435, '“Sometimes—not always.', '“有时候是——不总是。'),
    (25, 1278, 3436, 'Not generally.', '通常不会。'),
    (25, 1278, 3437, 'I reckon we haven’t got the right place.”', '我觉得我们没找到对的地方。”'),
    (25, 1279, 3438, 'So they chose a new spot and began again.', '于是他们选了个新地方，又开始挖。'),
    (25, 1279, 3439, 'The labor dragged a little, but still they made progress.', '挖起来有点慢，但他们还在努力。'),
    (25, 1279, 3440, 'They pegged away in silence for some time.', '他们默默地挖了一会儿。'),
    (25, 1279, 3441, 'Finally Huck leaned on his shovel, swabbed the beaded drops from his brow with his sleeve, and said:', '最后，哈克靠在铲子上，用袖子擦掉额头上的汗珠，然后说：'),
    (25, 1280, 3442, '“Where you going to dig next, after we get this one?”', '“我们挖完这里，接下来要去哪儿挖啊？”'),
    (25, 1281, 3443, '“I reckon maybe we’ll tackle the old tree that’s over yonder on Cardiff Hill back of the widow’s.”', '“我觉得我们也许会去挖那个老树，就在那边寡妇家后面卡迪夫山。”'),
    (25, 1282, 3444, '“I reckon that’ll be a good one.', '“我觉得那会是个好地方。'),
    (25, 1282, 3445, 'But won’t the widow take it away from us, Tom?', '但是那个寡妇不会把它从我们手里拿走吗，汤姆？'),
    (25, 1282, 3446, 'It’s on her land.”', '那是她的地啊。”'),
    (25, 1283, 3447, '“_She_ take it away!', '“她把它拿走？'),
    (25, 1283, 3448, 'Maybe she’d like to try it once.', '也许她想试试看吧。'),
    (25, 1283, 3449, 'Whoever finds one of these hid treasures, it belongs to him.', '谁找到这些藏起来的宝贝，谁就能拥有它。'),
    (25, 1283, 3450, 'It don’t make any difference whose land it’s on.”', '这和它在哪块地上没关系。”'),
    (25, 1284, 3451, 'That was satisfactory.', '那还不错。'),
    (25, 1284, 3452, 'The work went on.', '活儿继续干。'),
    (25, 1284, 3453, 'By and by Huck said:', '过了一会儿，哈克说：'),
    (25, 1285, 3454, '“Blame it, we must be in the wrong place again.', '“哎呀，我们肯定又找错地方了。'),
    (25, 1285, 3455, 'What do you think?”', '你觉得呢？”'),
    (25, 1286, 3456, '“It is mighty curious, Huck.', '“这真奇怪，哈克。'),
    (25, 1286, 3457, 'I don’t understand it.', '我不明白。'),
    (25, 1286, 3458, 'Sometimes witches interfere.', '有时候是巫婆捣乱。'),
    (25, 1286, 3459, 'I reckon maybe that’s what’s the trouble now.”', '我想，可能现在就是这样。”'),
    (25, 1287, 3460, '“Shucks!', '“切！'),
    (25, 1287, 3461, 'Witches ain’t got no power in the daytime.”', '巫婆白天可没法力。”'),
    (25, 1288, 3462, '“Well, that’s so.', '“嗯，没错。'),
    (25, 1288, 3463, 'I didn’t think of that.', '我没想到那个。'),
    (25, 1288, 3464, 'Oh, I know what the matter is!', '哦，我知道问题出在哪儿了！'),
    (25, 1288, 3465, 'What a blamed lot of fools we are!', '我们真是太笨了！'),
    (25, 1288, 3466, 'You got to find out where the shadow of the limb falls at midnight, and that’s where you dig!”', '你得找到半夜时树枝的影子落在哪里，就在那里挖！”'),
    (25, 1289, 3467, '“Then consound it, we’ve fooled away all this work for nothing.', '“那可恶，我们白费力气了。'),
    (25, 1289, 3468, 'Now hang it all, we got to come back in the night.', '哎呀，我们晚上还得回来。'),
    (25, 1289, 3469, 'It’s an awful long way.', '路好远啊。'),
    (25, 1289, 3470, 'Can you get out?”', '你能出来吗？”'),
    (25, 1290, 3471, '“I bet I will.', '“我肯定能。'),
    (25, 1290, 3472, 'We’ve got to do it tonight, too, because if somebody sees these holes they’ll know in a minute what’s here and they’ll go for it.”', '我们今晚就得去，要是别人看到这些洞，一下子就懂了，会把东西拿走的。”'),
    (25, 1291, 3473, '“Well, I’ll come around and maow tonight.”', '“嗯，我晚上会过来喵喵叫的。”'),
    (25, 1292, 3474, '“All right.', '“好的。'),
    (25, 1292, 3475, 'Let’s hide the tools in the bushes.”', '我们把工具藏到灌木丛里吧。”'),
    (25, 1293, 3476, 'The boys were there that night, about the appointed time.', '那天晚上，孩子们在约好的时间去了那里。'),
    (25, 1293, 3477, 'They sat in the shadow waiting.', '他们躲在影子里等着。'),
    (25, 1293, 3478, 'It was a lonely place, and an hour made solemn by old traditions.', '那地方很安静，老故事让这个时间变得有点吓人。'),
    (25, 1293, 3479, 'Spirits whispered in the rustling leaves, ghosts lurked in the murky nooks, the deep baying of a hound floated up out of the distance, an owl answered with his sepulchral note.', '树叶沙沙响，好像有小鬼在说话。黑漆漆的角落藏着幽灵。远处传来狗的叫声，猫头鹰也叫得很吓人。'),
    (25, 1293, 3480, 'The boys were subdued by these solemnities, and talked little.', '这些事让孩子们很安静，他们几乎没说话。'),
    (25, 1293, 3481, 'By and by they judged that twelve had come; they marked where the shadow fell, and began to dig.', '过了会儿，他们觉得十二点到了。他们记下影子的位置，就开始挖。'),
    (25, 1293, 3482, 'Their hopes commenced to rise.', '他们的希望开始变大。'),
    (25, 1293, 3483, 'Their interest grew stronger, and their industry kept pace with it.', '他们更感兴趣了，也挖得更起劲了。'),
    (25, 1293, 3484, 'The hole deepened and still deepened, but every time their hearts jumped to hear the pick strike upon something, they only suffered a new disappointment.', '洞挖得越来越深。每次听到锄头碰到东西，他们心里就一跳，可每次都是失望。'),
    (25, 1293, 3485, 'It was only a stone or a chunk.', '都只是一块石头或土块。'),
    (25, 1293, 3486, 'At last Tom said:', '最后 汤姆 说：'),
    (25, 1294, 3487, '“It ain’t any use, Huck, we’re wrong again.”', '“没用了，哈克，我们又错了。”'),
    (25, 1295, 3488, '“Well, but we _can’t_ be wrong.', '“嗯，可我们不_会_错啊。”'),
    (25, 1295, 3489, 'We spotted the shadder to a dot.”', '我们把影子看得清清楚楚。”'),
    (25, 1296, 3490, '“I know it, but then there’s another thing.”', '“我知道，但还有一件事。”'),
    (25, 1297, 3491, '“What’s that?”', '“什么事？”'),
    (25, 1298, 3492, '“Why, we only guessed at the time.', '“我们只是猜的时间呀。'),
    (25, 1298, 3493, 'Like enough it was too late or too early.”', '说不定太晚了，或者太早了。”'),
    (25, 1299, 3494, 'Huck dropped his shovel.', '哈克 放下了铲子。'),
    (25, 1300, 3495, '“That’s it,” said he.', '“就是这样，”他说。'),
    (25, 1300, 3496, '“That’s the very trouble.', '“问题就在这儿。'),
    (25, 1300, 3497, 'We got to give this one up.', '我们得放弃了。'),
    (25, 1300, 3498, 'We can’t ever tell the right time, and besides this kind of thing’s too awful, here this time of night with witches and ghosts a-fluttering around so.', '我们永远不知道确切时间。而且这事太吓人了，晚上有女巫和鬼魂在身边飞来飞去。'),
    (25, 1300, 3499, 'I feel as if something’s behind me all the time; and I’m afeard to turn around, becuz maybe there’s others in front a-waiting for a chance.', '我老觉得背后有东西，不敢转身，因为前面可能还有别的东西等着。'),
    (25, 1300, 3500, 'I been creeping all over, ever since I got here.”', '我来了之后就一直小心翼翼的。”'),
    (25, 1301, 3501, '“Well, I’ve been pretty much so, too, Huck.', '“嗯，我也差不多，哈克。'),
    (25, 1301, 3502, 'They most always put in a dead man when they bury a treasure under a tree, to look out for it.”', '他们在树下埋宝藏时，通常会放一个死人来看守它。”'),
    (25, 1302, 3503, '“Lordy!”', '“天哪！”'),
    (25, 1303, 3504, '“Yes, they do.', '“是的，他们会。'),
    (25, 1303, 3505, 'I’ve always heard that.”', '我一直都听说是这样。”'),
    (25, 1304, 3506, '“Tom, I don’t like to fool around much where there’s dead people.', '“汤姆，我不喜欢在有死人的地方玩。'),
    (25, 1304, 3507, 'A body’s bound to get into trouble with ’em, sure.”', '肯定会跟他们惹麻烦的。”'),
    (25, 1305, 3508, '“I don’t like to stir ’em up, either.', '“我也不喜欢去吵醒他们。'),
    (25, 1305, 3509, 'S’pose this one here was to stick his skull out and say something!”', '万一这个死人把头伸出来，还说句话呢！”'),
    (25, 1306, 3510, '“Don’t Tom!', '“别 汤姆！”'),
    (25, 1306, 3511, 'It’s awful.”', '太可怕了。'),
    (25, 1307, 3512, '“Well, it just is.', '嗯，就是这样。'),
    (25, 1307, 3513, 'Huck, I don’t feel comfortable a bit.”', '哈克，我一点都不舒服。'),
    (25, 1308, 3514, '“Say, Tom, let’s give this place up, and try somewheres else.”', '喂，汤姆，我们放弃这里吧，去别的地方试试。'),
    (25, 1309, 3515, '“All right, I reckon we better.”', '好吧，我想我们最好还是那样。'),
    (25, 1310, 3516, '“What’ll it be?”', '那会是什么？'),
    (25, 1311, 3517, 'Tom considered awhile; and then said:', '汤姆想了一会儿，然后说：'),
    (25, 1312, 3518, '“The ha’nted house.', '鬼屋。'),
    (25, 1312, 3519, 'That’s it!”', '就是那里！'),
    (25, 1313, 3520, '“Blame it, I don’t like ha’nted houses, Tom.', '哎呀，我不喜欢鬼屋，汤姆。'),
    (25, 1313, 3521, 'Why, they’re a dern sight worse’n dead people.', '哎呀，它们比死人可怕多了。'),
    (25, 1313, 3522, 'Dead people might talk, maybe, but they don’t come sliding around in a shroud, when you ain’t noticing, and peep over your shoulder all of a sudden and grit their teeth, the way a ghost does.', '死人也许会说话，但它们不会在你没注意时，穿着白布滑来滑去，突然从你肩后偷看，还像鬼一样咬牙切齿。'),
    (25, 1313, 3523, 'I couldn’t stand such a thing as that, Tom—nobody could.”', '我受不了那样的事，汤姆——没人能受得了。'),
    (25, 1314, 3524, '“Yes, but, Huck, ghosts don’t travel around only at night.', '是的，但是，哈克，鬼只在晚上出来。'),
    (25, 1314, 3525, 'They won’t hender us from digging there in the daytime.”', '它们白天不会妨碍我们挖东西。'),
    (25, 1315, 3526, '“Well, that’s so.', '嗯，是这样。'),
    (25, 1315, 3527, 'But you know mighty well people don’t go about that ha’nted house in the day nor the night.”', '但是你很清楚，白天晚上都没人去那个鬼屋。'),
    (25, 1316, 3528, '“Well, that’s mostly because they don’t like to go where a man’s been murdered, anyway—but nothing’s ever been seen around that house except in the night—just some blue lights slipping by the windows—no regular ghosts.”', '嗯，那大多是因为人们不喜欢去有人被杀的地方——不过那房子周围除了晚上，就没见过别的什么了——只有一些蓝光从窗户边飘过——没有真正的鬼。'),
    (25, 1317, 3529, '“Well, where you see one of them blue lights flickering around, Tom, you can bet there’s a ghost mighty close behind it.', '嗯，汤姆，只要你看到那些蓝光在闪烁，你就可以肯定，附近一定有鬼。'),
    (25, 1317, 3530, 'It stands to reason.', '这是很自然的。'),
    (25, 1317, 3531, 'Becuz you know that they don’t anybody but ghosts use ’em.”', '因为你知道，除了鬼，没人会用它们。'),
    (25, 1318, 3532, '“Yes, that’s so.', '是的，是这样。'),
    (25, 1318, 3533, 'But anyway they don’t come around in the daytime, so what’s the use of our being afeard?”', '但反正它们白天不出来，我们有什么好怕的呢？'),
    (25, 1319, 3534, '“Well, all right.', '好吧。'),
    (25, 1319, 3535, 'We’ll tackle the ha’nted house if you say so—but I reckon it’s taking chances.”', '如果你坚持，我们就去鬼屋——但我认为这很冒险。'),
    (25, 1320, 3536, 'They had started down the hill by this time.', '这时候，他们已经开始下山了。'),
    (25, 1320, 3537, 'There in the middle of the moonlit valley below them stood the “ha’nted” house, utterly isolated, its fences gone long ago, rank weeds smothering the very doorsteps, the chimney crumbled to ruin, the window-sashes vacant, a corner of the roof caved in.', '在他们下面月光照耀的山谷中央，矗立着那座“鬼”屋。它完全孤立，围栏早就没了，杂草把门前台阶都盖住了，烟囱也塌了，窗框空空荡荡，屋顶一角也塌陷了。'),
    (25, 1320, 3538, 'The boys gazed awhile, half expecting to see a blue light flit past a window; then talking in a low tone, as befitted the time and the circumstances, they struck far off to the right, to give the haunted house a wide berth, and took their way homeward through the woods that adorned the rearward side of Cardiff Hill.', '男孩们看了一会儿，心里有点期待能看到蓝光从窗户飘过；然后他们小声说话，因为那时那景就该这样。他们远远地绕到右边，避开鬼屋，穿过卡迪夫山后面的树林回家了。'),
    (26, 1321, 3539, 'About noon the next day the boys arrived at the dead tree; they had come for their tools.', '第二天中午左右，男孩们来到那棵枯树旁；他们是来拿工具的。'),
    (26, 1321, 3540, 'Tom was impatient to go to the haunted house; Huck was measurably so, also—but suddenly said:', '汤姆很想去鬼屋；哈克也差不多——但他突然说：'),
    (26, 1322, 3541, '“Lookyhere, Tom, do you know what day it is?”', '“你看，汤姆，你知道今天星期几吗？”'),
    (26, 1323, 3542, 'Tom mentally ran over the days of the week, and then quickly lifted his eyes with a startled look in them—', '汤姆 在心里想了想是星期几，然后吓了一跳，赶紧抬起头——'),
    (26, 1324, 3543, '“My!', '“哎呀！'),
    (26, 1324, 3544, 'I never once thought of it, Huck!”', '我一点儿也没想到，哈克！”'),
    (26, 1325, 3545, '“Well, I didn’t neither, but all at once it popped onto me that it was Friday.”', '“嗯，我也没想起来。不过我突然想起来今天是星期五。”'),
    (26, 1326, 3546, '“Blame it, a body can’t be too careful, Huck.', '“哎呀，哈克，我们可要小心点儿。'),
    (26, 1326, 3547, 'We might ’a’ got into an awful scrape, tackling such a thing on a Friday.”', '要是星期五做这种事，可能会有大麻烦。”'),
    (26, 1327, 3548, '“_Might_!', '“可能！'),
    (26, 1327, 3549, 'Better say we _would_!', '不如说我们一定会的！'),
    (26, 1327, 3550, 'There’s some lucky days, maybe, but Friday ain’t.”', '也许有些日子会走运，但星期五可不是。”'),
    (26, 1328, 3551, '“Any fool knows that.', '“傻瓜都知道。'),
    (26, 1328, 3552, 'I don’t reckon _you_ was the first that found it out, Huck.”', '我可不觉得你是第一个发现的，哈克。”'),
    (26, 1329, 3553, '“Well, I never said I was, did I?', '“嗯，我没说过我是，对吧？'),
    (26, 1329, 3554, 'And Friday ain’t all, neither.', '而且也不只是星期五。'),
    (26, 1329, 3555, 'I had a rotten bad dream last night—dreampt about rats.”', '我昨晚做了个特别糟糕的梦——梦见老鼠了。”'),
    (26, 1330, 3556, '“No!', '“不！'),
    (26, 1330, 3557, 'Sure sign of trouble.', '这肯定是麻烦的预兆。'),
    (26, 1330, 3558, 'Did they fight?”', '它们打架了吗？”'),
    (26, 1331, 3559, '“No.”', '“没有。”'),
    (26, 1332, 3560, '“Well, that’s good, Huck.', '“嗯，那太好了，哈克。'),
    (26, 1332, 3561, 'When they don’t fight it’s only a sign that there’s trouble around, you know.', '你知道，它们不打架就只是说明附近有麻烦。'),
    (26, 1332, 3562, 'All we got to do is to look mighty sharp and keep out of it.', '我们只要非常小心，躲开就行了。'),
    (26, 1332, 3563, 'We’ll drop this thing for today, and play.', '我们今天不弄这个了，去玩吧。'),
    (26, 1332, 3564, 'Do you know Robin Hood, Huck?”', '你认识罗宾汉吗，哈克？”'),
    (26, 1333, 3565, '“No. Who’s Robin Hood?”', '“不认识。罗宾汉是谁呀？”'),
    (26, 1334, 3566, '“Why, he was one of the greatest men that was ever in England—and the best.', '“哎呀，他是英国最厉害的人之一，也是最好的人。'),
    (26, 1334, 3567, 'He was a robber.”', '他是个强盗。”'),
    (26, 1335, 3568, '“Cracky, I wisht I was.', '“哇，我真希望我是。'),
    (26, 1335, 3569, 'Who did he rob?”', '他抢劫谁呀？”'),
    (26, 1336, 3570, '“Only sheriffs and bishops and rich people and kings, and such like.', '“只抢治安官、主教、有钱人和国王，还有类似的人。'),
    (26, 1336, 3571, 'But he never bothered the poor.', '但他从不欺负穷人。'),
    (26, 1336, 3572, 'He loved ’em.', '他爱他们。'),
    (26, 1336, 3573, 'He always divided up with ’em perfectly square.”', '他总是公平地把东西分给他们。”'),
    (26, 1337, 3574, '“Well, he must ’a’ been a brick.”', '“嗯，他一定是个好人。”'),
    (26, 1338, 3575, '“I bet you he was, Huck.', '“我敢打赌他就是，哈克。'),
    (26, 1338, 3576, 'Oh, he was the noblest man that ever was.', '哦，他是有史以来最好的人。'),
    (26, 1338, 3577, 'They ain’t any such men now, I can tell you.', '我跟你说，现在可没有那样的人了。'),
    (26, 1338, 3578, 'He could lick any man in England, with one hand tied behind him; and he could take his yew bow and plug a ten-cent piece every time, a mile and a half.”', '他能把英格兰的任何一个人打倒，就算他一只手被绑在身后；他还能用他的紫杉弓，每次都能射中一英里半远的一枚十美分硬币。”'),
    (26, 1339, 3579, '“What’s a _yew_ bow?”', '“什么是紫杉弓？”'),
    (26, 1340, 3580, '“I don’t know.', '“我不知道。'),
    (26, 1340, 3581, 'It’s some kind of a bow, of course.', '当然，那是一种弓。'),
    (26, 1340, 3582, 'And if he hit that dime only on the edge he would set down and cry—and curse.', '如果他只射中那枚硬币的边边，他就会坐下来哭——还会骂人。'),
    (26, 1340, 3583, 'But we’ll play Robin Hood—it’s nobby fun.', '但我们来玩罗宾汉吧——那很有趣。'),
    (26, 1340, 3584, 'I’ll learn you.”', '我来教你。”'),
    (26, 1341, 3585, '“I’m agreed.”', '“我同意。”'),
    (26, 1342, 3586, 'So they played Robin Hood all the afternoon, now and then casting a yearning eye down upon the haunted house and passing a remark about the morrow’s prospects and possibilities there.', '于是他们整个下午都在玩罗宾汉，不时地把渴望的目光投向那座鬼屋，还讨论着明天在那里可能有什么发现。'),
    (26, 1342, 3587, 'As the sun began to sink into the west they took their way homeward athwart the long shadows of the trees and soon were buried from sight in the forests of Cardiff Hill.', '太阳开始西沉的时候，他们沿着树木长长的影子回家，很快就在卡迪夫山的森林里消失不见了。'),
    (26, 1343, 3588, 'On Saturday, shortly after noon, the boys were at the dead tree again.', '星期六，刚过中午，男孩子们又来到了那棵枯树旁。'),
    (26, 1343, 3589, 'They had a smoke and a chat in the shade, and then dug a little in their last hole, not with great hope, but merely because Tom said there were so many cases where people had given up a treasure after getting down within six inches of it, and then somebody else had come along and turned it up with a single thrust of a shovel.', '他们在树荫下抽了会儿烟，聊了会儿天，然后又在他们上次挖的那个洞里挖了挖，虽然没抱太大希望，只是因为汤姆说过，有好多人挖到离宝藏只有六英寸远的时候就放弃了，然后别人一来，一铲子就把宝藏挖出来了。'),
    (26, 1343, 3590, 'The thing failed this time, however, so the boys shouldered their tools and went away feeling that they had not trifled with fortune, but had fulfilled all the requirements that belong to the business of treasure-hunting.', '不过这次还是没找到，所以男孩子们扛起工具走了，他们觉得他们没有辜负运气，已经把寻宝该做的事都做完了。'),
    (26, 1344, 3591, 'When they reached the haunted house there was something so weird and grisly about the dead silence that reigned there under the baking sun, and something so depressing about the loneliness and desolation of the place, that they were afraid, for a moment, to venture in.', '他们走到鬼屋时，在烈日下，那里的死寂让人觉得很奇怪又有点吓人，这个地方又很孤单很荒凉，让人心里难过，所以他们有一会儿都不敢进去。'),
    (26, 1344, 3592, 'Then they crept to the door and took a trembling peep.', '接着他们悄悄地走到门口，抖着身子往里看了一眼。'),
    (26, 1344, 3593, 'They saw a weedgrown, floorless room, unplastered, an ancient fireplace, vacant windows, a ruinous staircase; and here, there, and everywhere hung ragged and abandoned cobwebs.', '他们看到一个长满野草、没有地板的房间，墙壁也没刷，还有一个老旧的壁炉，空空的窗户，摇摇欲坠的楼梯；到处都挂着破烂的、没人管的蜘蛛网。'),
    (26, 1344, 3594, 'They presently entered, softly, with quickened pulses, talking in whispers, ears alert to catch the slightest sound, and muscles tense and ready for instant retreat.', '他们小心地走了进去，心跳得很快，小声说话，耳朵竖起来听着一点点声音，肌肉也绷紧了，随时准备马上跑出去。'),
    (26, 1345, 3595, 'In a little while familiarity modified their fears and they gave the place a critical and interested examination, rather admiring their own boldness, and wondering at it, too.', '过了一会儿，他们熟悉了这里，害怕的心情就没那么重了，他们开始仔细又好奇地检查这个地方，还挺佩服自己的胆量，也觉得有点奇怪。'),
    (26, 1345, 3596, 'Next they wanted to look upstairs.', '接着他们想去楼上看看。'),
    (26, 1345, 3597, 'This was something like cutting off retreat, but they got to daring each other, and of course there could be but one result—they threw their tools into a corner and made the ascent.', '上楼就像是切断了后路，但他们互相壮胆，结果当然只有一个——他们把工具扔到角落里，就上去了。'),
    (26, 1345, 3598, 'Up there were the same signs of decay.', '楼上也是一样，到处都是破旧的样子。'),
    (26, 1345, 3599, 'In one corner they found a closet that promised mystery, but the promise was a fraud—there was nothing in it.', '在一个角落里，他们发现一个壁橱，看起来好像藏着什么秘密，但根本不是，里面什么都没有。'),
    (26, 1345, 3600, 'Their courage was up now and well in hand.', '这时候，他们的胆量更大了，也更能控制自己了。'),
    (26, 1345, 3601, 'They were about to go down and begin work when—', '他们正要下去干活，突然——'),
    (26, 1346, 3602, '“Sh!” said Tom.', '“嘘！”汤姆说。'),
    (26, 1347, 3603, '“What is it?” whispered Huck, blanching with fright.', '“怎么了？”哈克吓得脸都白了，小声问。'),
    (26, 1348, 3604, '“Sh!...', '“嘘！...'),
    (26, 1348, 3605, 'There!...', '在那里！...'),
    (26, 1348, 3606, 'Hear it?”', '听到了吗？”'),
    (26, 1349, 3607, '“Yes!...', '“听到了！...'),
    (26, 1349, 3608, 'Oh, my!', '天哪！'),
    (26, 1349, 3609, 'Let’s run!”', '快跑吧！”'),
    (26, 1350, 3610, '“Keep still!', '“别动！'),
    (26, 1350, 3611, 'Don’t you budge!', '一点都别动！'),
    (26, 1350, 3612, 'They’re coming right toward the door.”', '他们正往门这边来。”'),
    (26, 1351, 3613, 'The boys stretched themselves upon the floor with their eyes to knotholes in the planking, and lay waiting, in a misery of fear.', '孩子们趴在地上，眼睛对着木板上的小洞看，心里很害怕地等着。'),
    (26, 1352, 3614, '“They’ve stopped....', '“他们停下来了....'),
    (26, 1352, 3615, 'No—coming....', '不——又过来了....'),
    (26, 1352, 3616, 'Here they are.', '他们来了。'),
    (26, 1352, 3617, 'Don’t whisper another word, Huck.', '别再小声说话了，哈克。'),
    (26, 1352, 3618, 'My goodness, I wish I was out of this!”', '天哪，我真希望能离开这里！”'),
    (26, 1353, 3619, 'Two men entered.', '两个人走了进来。'),
    (26, 1353, 3620, 'Each boy said to himself: “There’s the old deaf and dumb Spaniard that’s been about town once or twice lately—never saw t’other man before.”', '每个孩子心里都想：“那是镇上最近出现过几次的，又聋又哑的老西班牙人——另一个人，我以前没见过。”'),
    (26, 1354, 3621, '“T’other” was a ragged, unkempt creature, with nothing very pleasant in his face.', '“另一个人”穿着破旧的衣服，头发乱糟糟的，脸上也没什么好看的表情。'),
    (26, 1354, 3622, 'The Spaniard was wrapped in a serape; he had bushy white whiskers; long white hair flowed from under his sombrero, and he wore green goggles.', '那个西班牙人身上裹着一条毯子；他有浓密的白胡子；长长的白头发从他的大帽子下面露出来，他还戴着绿色的眼镜。'),
    (26, 1354, 3623, 'When they came in, “t’other” was talking in a low voice; they sat down on the ground, facing the door, with their backs to the wall, and the speaker continued his remarks.', '他们进来时，“另一个人”正小声说着话；他们坐在地上，面对着门，背靠着墙，那个说话的人继续说。'),
    (26, 1354, 3624, 'His manner became less guarded and his words more distinct as he proceeded:', '他说话越来越不小心，声音也越来越清楚：'),
    (26, 1355, 3625, '“No,” said he, “I’ve thought it all over, and I don’t like it.', '“不，”他说，“我想过了，我不喜欢这样。'),
    (26, 1355, 3626, 'It’s dangerous.”', '这很危险。”'),
    (26, 1356, 3627, '“Dangerous!” grunted the “deaf and dumb” Spaniard—to the vast surprise of the boys. “Milksop!”', '“危险！”“又聋又哑”的西班牙人哼了一声——孩子们都吓了一跳。“胆小鬼！”'),
    (26, 1357, 3628, 'This voice made the boys gasp and quake.', '这个声音让孩子们吓得喘不过气，浑身发抖。'),
    (26, 1357, 3629, 'It was Injun Joe’s!', '是印第安·乔的声音！'),
    (26, 1357, 3630, 'There was silence for some time.', '一下子安静了下来。'),
    (26, 1357, 3631, 'Then Joe said:', '接着乔说：'),
    (26, 1358, 3632, '“What’s any more dangerous than that job up yonder—but nothing’s come of it.”', '“有什么比那里的活儿更危险的吗？——可是什么也没发生啊。”'),
    (26, 1359, 3633, '“That’s different.', '“那可不一样。'),
    (26, 1359, 3634, 'Away up the river so, and not another house about.', '在河边那么远的地方，旁边连一栋房子都没有。'),
    (26, 1359, 3635, '’Twon’t ever be known that we tried, anyway, long as we didn’t succeed.”', '反正只要我们没成功，就不会有人知道我们试过了。”'),
    (26, 1360, 3636, '“Well, what’s more dangerous than coming here in the daytime!', '“哎呀，白天来这儿有什么更危险的吗！'),
    (26, 1360, 3637, '—anybody would suspicion us that saw us.”', '任何看到我们的人都会怀疑我们。”'),
    (26, 1361, 3638, '“I know that.', '“我知道。'),
    (26, 1361, 3639, 'But there warn’t any other place as handy after that fool of a job.', '可是那件傻事以后，就没有别的地方这么方便了。'),
    (26, 1361, 3640, 'I want to quit this shanty.', '我想离开这个破棚子。'),
    (26, 1361, 3641, 'I wanted to yesterday, only it warn’t any use trying to stir out of here, with those infernal boys playing over there on the hill right in full view.”', '我昨天就想走了，可是那些烦人的男孩就在山上玩，能看到这儿，所以根本没法儿动。”'),
    (26, 1362, 3642, '“Those infernal boys” quaked again under the inspiration of this remark, and thought how lucky it was that they had remembered it was Friday and concluded to wait a day.', '“那些烦人的男孩”听到这话又吓得发抖，心想幸亏他们记住了今天是星期五，决定再等一天。'),
    (26, 1362, 3643, 'They wished in their hearts they had waited a year.', '他们心里恨不得等上一年呢。'),
    (26, 1363, 3644, 'The two men got out some food and made a luncheon.', '两个人拿出一些吃的，做了顿午饭。'),
    (26, 1363, 3645, 'After a long and thoughtful silence, Injun Joe said:', '经过一段长时间的安静思考后，印第安·乔说：'),
    (26, 1364, 3646, '“Look here, lad—you go back up the river where you belong.', '“听着，小子——你回到河上你的地方去。'),
    (26, 1364, 3647, 'Wait there till you hear from me.', '在那儿等我的消息。'),
    (26, 1364, 3648, 'I’ll take the chances on dropping into this town just once more, for a look.', '我会冒这个险，再进城一次看看。'),
    (26, 1364, 3649, 'We’ll do that ‘dangerous’ job after I’ve spied around a little and think things look well for it.', '等我侦察一下，觉得情况不错了，我们再去干那件‘危险’的活儿。'),
    (26, 1364, 3650, 'Then for Texas!', '然后去得克萨斯！'),
    (26, 1364, 3651, 'We’ll leg it together!”', '我们一起跑路！”'),
    (26, 1365, 3652, 'This was satisfactory.', '这样就行了。'),
    (26, 1365, 3653, 'Both men presently fell to yawning, and Injun Joe said:', '两个人很快都打起了哈欠，然后印第安·乔说：'),
    (26, 1366, 3654, '“I’m dead for sleep!', '“我困死了！'),
    (26, 1366, 3655, 'It’s your turn to watch.”', '该你放哨了。”'),
    (26, 1367, 3656, 'He curled down in the weeds and soon began to snore.', '他蜷缩在草丛里，很快就打起了呼噜。'),
    (26, 1367, 3657, 'His comrade stirred him once or twice and he became quiet.', '他的同伴捅了他一两下，他就安静下来了。'),
    (26, 1367, 3658, 'Presently the watcher began to nod; his head drooped lower and lower, both men began to snore now.', '很快，放哨的人也开始打瞌睡了；他的头越垂越低，两个人现在都打起了呼噜。'),
    (26, 1368, 3659, 'The boys drew a long, grateful breath.', '男孩们长长地松了口气，心里很感激。'),
    (26, 1368, 3660, 'Tom whispered:', '汤姆小声说：'),
    (26, 1369, 3661, '“Now’s our chance—come!”', '“现在是我们的机会，快来！”'),
    (26, 1370, 3662, 'Huck said:', '哈克说：'),
    (26, 1371, 3663, '“I can’t—I’d die if they was to wake.”', '“我不能去，要是他们醒了，我会没命的。”'),
    (26, 1372, 3664, 'Tom urged—Huck held back.', '汤姆催他，但哈克还是没动。'),
    (26, 1372, 3665, 'At last Tom rose slowly and softly, and started alone.', '最后，汤姆慢慢地、轻轻地站起来，一个人走了。'),
    (26, 1372, 3666, 'But the first step he made wrung such a hideous creak from the crazy floor that he sank down almost dead with fright.', '可他才走第一步，那破地板就发出可怕的吱呀声，吓得他差点倒下。'),
    (26, 1372, 3667, 'He never made a second attempt.', '他再也不敢尝试第二次了。'),
    (26, 1372, 3668, 'The boys lay there counting the dragging moments till it seemed to them that time must be done and eternity growing gray; and then they were grateful to note that at last the sun was setting.', '男孩们躺在那里，一分一秒地数着时间，感觉时间过得好慢，天都要老了；直到太阳终于落山，他们才松了口气。'),
    (26, 1373, 3669, 'Now one snore ceased.', '这时，一声鼾声停了。'),
    (26, 1373, 3670, 'Injun Joe sat up, stared around—smiled grimly upon his comrade, whose head was drooping upon his knees—stirred him up with his foot and said:', '印第安·乔坐起来，看了看四周，对着他把头靠在膝盖上的同伴，冷冷地笑了笑，然后用脚踢了踢他，说：'),
    (26, 1374, 3671, '“Here!', '“喂！'),
    (26, 1374, 3672, '_You’re_ a watchman, ain’t you!', '你是个看守，对不对！'),
    (26, 1374, 3673, 'All right, though—nothing’s happened.”', '不过没关系，什么也没发生。”'),
    (26, 1375, 3674, '“My! have I been asleep?”', '“啊！我睡着了吗？”'),
    (26, 1376, 3675, '“Oh, partly, partly.', '“嗯，睡了一会儿，一点点。'),
    (26, 1376, 3676, 'Nearly time for us to be moving, pard.', '搭档，我们差不多该走了。'),
    (26, 1376, 3677, 'What’ll we do with what little swag we’ve got left?”', '我们剩下这点东西怎么办呢？”'),
    (26, 1377, 3678, '“I don’t know—leave it here as we’ve always done, I reckon.', '“我不知道，我想还是像以前一样，放这儿吧。'),
    (26, 1377, 3679, 'No use to take it away till we start south.', '等我们往南走的时候再带走也不迟。'),
    (26, 1377, 3680, 'Six hundred and fifty in silver’s something to carry.”', '六百五十块银子可不好拿。”'),
    (26, 1378, 3681, '“Well—all right—it won’t matter to come here once more.”', '“嗯，好吧，再来一次也没关系。”'),
    (26, 1379, 3682, '“No—but I’d say come in the night as we used to do—it’s better.”', '“不，我觉得还是像以前一样晚上来，那样更好。”'),
    (26, 1380, 3683, '“Yes: but look here; it may be a good while before I get the right chance at that job; accidents might happen; ’tain’t in such a very good place; we’ll just regularly bury it—and bury it deep.”', '“是啊，可是听我说；我可能很久才能有机会去办那件事；可能会出意外；这地方也不是很好；我们还是把它好好埋起来吧，埋得深一点。”'),
    (26, 1381, 3684, '“Good idea,” said the comrade, who walked across the room, knelt down, raised one of the rearward hearth-stones and took out a bag that jingled pleasantly.', '“好主意，”那个同伴说。他走到屋子那边，跪下来，掀开一块后面的炉石，拿出一个叮当作响的袋子。'),
    (26, 1381, 3685, 'He subtracted from it twenty or thirty dollars for himself and as much for Injun Joe, and passed the bag to the latter, who was on his knees in the corner, now, digging with his bowie-knife.', '他从袋子里拿出二三十块钱给自己，又给印第安·乔同样多的钱，然后把袋子递给印第安·乔。印第安·乔正跪在角落里，用他的博伊刀挖着。'),
    (26, 1382, 3686, 'The boys forgot all their fears, all their miseries in an instant.', '孩子们一下子忘了所有的害怕和不开心。'),
    (26, 1382, 3687, 'With gloating eyes they watched every movement.', '他们眼睛发亮地看着每一个动作。'),
    (26, 1382, 3688, 'Luck!', '太走运了！'),
    (26, 1382, 3689, '—the splendor of it was beyond all imagination!', '这太棒了，简直无法想象！'),
    (26, 1382, 3690, 'Six hundred dollars was money enough to make half a dozen boys rich!', '六百块钱，足够让六个孩子都变富有了！'),
    (26, 1382, 3691, 'Here was treasure-hunting under the happiest auspices—there would not be any bothersome uncertainty as to where to dig.', '这是一个非常棒的寻宝！不用担心去哪里挖。'),
    (26, 1382, 3692, 'They nudged each other every moment—eloquent nudges and easily understood, for they simply meant—“Oh, but ain’t you glad _now_ we’re here!”', '他们不停地互相推搡，好像在说：“哦，我们真高兴现在在这里啊！”'),
    (26, 1383, 3693, 'Joe’s knife struck upon something.', '乔的刀碰到了什么东西。'),
    (26, 1384, 3694, '“Hello!” said he.', '“哈喽！”他说。'),
    (26, 1385, 3695, '“What is it?” said his comrade.', '“那是什么？”他的伙伴问。'),
    (26, 1386, 3696, '“Half-rotten plank—no, it’s a box, I believe.', '“一块烂木板——不，我觉得它是个盒子。'),
    (26, 1386, 3697, 'Here—bear a hand and we’ll see what it’s here for.', '来——搭把手，我们看看这是干嘛的。'),
    (26, 1386, 3698, 'Never mind, I’ve broke a hole.”', '没关系，我已经弄了个洞。”'),
    (26, 1387, 3699, 'He reached his hand in and drew it out—', '他把手伸进去，然后拿了出来——'),
    (26, 1388, 3700, '“Man, it’s money!”', '“天哪，是钱！”'),
    (26, 1389, 3701, 'The two men examined the handful of coins.', '两个人仔细看了看手里的硬币。'),
    (26, 1389, 3702, 'They were gold.', '它们是金子。'),
    (26, 1389, 3703, 'The boys above were as excited as themselves, and as delighted.', '上面的孩子们也和他们一样兴奋，一样开心。'),
    (26, 1390, 3704, 'Joe’s comrade said:', '乔的伙伴说：'),
    (26, 1391, 3705, '“We’ll make quick work of this.', '“我们快点把它弄出来。'),
    (26, 1391, 3706, 'There’s an old rusty pick over amongst the weeds in the corner the other side of the fireplace—I saw it a minute ago.”', '壁炉另一边的角落里，杂草中有个旧生锈的镐子——我刚才看到了。”'),
    (26, 1392, 3707, 'He ran and brought the boys’ pick and shovel.', '他跑过去拿来了孩子们的镐子和铲子。'),
    (26, 1392, 3708, 'Injun Joe took the pick, looked it over critically, shook his head, muttered something to himself, and then began to use it.', '印第安·乔拿起镐子，仔细看了看，摇了摇头，小声说了些什么，然后就开始用了。'),
    (26, 1392, 3709, 'The box was soon unearthed.', '那个盒子很快就被挖出来了。'),
    (26, 1392, 3710, 'It was not very large; it was iron bound and had been very strong before the slow years had injured it.', '它不大；外面有铁箍，在被岁月损坏之前，它非常结实。'),
    (26, 1392, 3711, 'The men contemplated the treasure awhile in blissful silence.', '两个人开心地默默看着那些宝藏。'),
    (26, 1393, 3712, '“Pard, there’s thousands of dollars here,” said Injun Joe.', '“伙计，这里有好多钱啊，”印第安·乔说。'),
    (26, 1394, 3713, '“’Twas always said that Murrel’s gang used to be around here one summer,” the stranger observed.', '“人们总说，有个叫默雷尔的坏蛋团伙，有一年夏天就在这附近，”那个陌生人说。'),
    (26, 1395, 3714, '“I know it,” said Injun Joe; “and this looks like it, I should say.”', '“我知道，”印第安·乔说；“我觉得这很像他们做的。”'),
    (26, 1396, 3715, '“Now you won’t need to do that job.”', '“现在你不用做那件事了。”'),
    (26, 1397, 3716, 'The halfbreed frowned.', '那个混血儿皱起了眉头。'),
    (26, 1397, 3717, 'Said he:', '他说：'),
    (26, 1398, 3718, '“You don’t know me.', '“你不了解我。'),
    (26, 1398, 3719, 'Least you don’t know all about that thing.', '至少你不知道那件事的全部。'),
    (26, 1398, 3720, '’Tain’t robbery altogether—it’s _revenge_!” and a wicked light flamed in his eyes.', '这不全是抢劫——这是_报仇_！”他的眼睛里闪烁着邪恶的光芒。'),
    (26, 1398, 3721, '“I’ll need your help in it.', '“我需要你的帮忙。'),
    (26, 1398, 3722, 'When it’s finished—then Texas.', '事情做完后，就去得克萨斯。'),
    (26, 1398, 3723, 'Go home to your Nance and your kids, and stand by till you hear from me.”', '回家陪南茜和孩子们吧，等我通知你。”'),
    (26, 1399, 3724, '“Well—if you say so; what’ll we do with this—bury it again?”', '“好吧，你说了算；那这个怎么办？再埋起来吗？”'),
    (26, 1400, 3725, '“Yes.', '“对。'),
    (26, 1400, 3726, '[Ravishing delight overhead.]', '头顶传来惊喜的声音。'),
    (26, 1400, 3727, '_No_! by the great Sachem, no!', '不！绝不！'),
    (26, 1400, 3728, '[Profound distress overhead.]', '头顶传来非常痛苦的声音。'),
    (26, 1400, 3729, 'I’d nearly forgot.', '我差点忘了。'),
    (26, 1400, 3730, 'That pick had fresh earth on it!', '那个镐头上面有新土！'),
    (26, 1400, 3731, '[The boys were sick with terror in a moment.]', '孩子们立刻吓坏了。'),
    (26, 1400, 3732, 'What business has a pick and a shovel here?', '镐头和铲子怎么会在这里？'),
    (26, 1400, 3733, 'What business with fresh earth on them?', '上面怎么会有新土呢？'),
    (26, 1400, 3734, 'Who brought them here—and where are they gone?', '谁把它们带来这里的——他们又去了哪里？'),
    (26, 1400, 3735, 'Have you heard anybody?', '你听到有人来了吗？'),
    (26, 1400, 3736, '—seen anybody?', '—看到有人了吗？'),
    (26, 1400, 3737, 'What! bury it again and leave them to come and see the ground disturbed?', '什么！再埋起来，让他们过来看到地被动过了吗？'),
    (26, 1400, 3738, 'Not exactly—not exactly.', '不完全是——不完全是。'),
    (26, 1400, 3739, 'We’ll take it to my den.”', '我们把它带到我的藏身处去。”'),
    (26, 1401, 3740, '“Why, of course!', '“哎呀，当然了！'),
    (26, 1401, 3741, 'Might have thought of that before.', '我们早该想到。'),
    (26, 1401, 3742, 'You mean Number One?”', '你是说第一个吗？”'),
    (26, 1402, 3743, '“No—Number Two—under the cross.', '“不——是第二个——在十字架下面。'),
    (26, 1402, 3744, 'The other place is bad—too common.”', '另一个地方不好——太普通了。”'),
    (26, 1403, 3745, '“All right.', '“好的。'),
    (26, 1403, 3746, 'It’s nearly dark enough to start.”', '天快黑了，可以开始动身了。”'),
    (26, 1404, 3747, 'Injun Joe got up and went about from window to window cautiously peeping out.', '他起身，悄悄地走到每个窗户边，往外看。'),
    (26, 1404, 3748, 'Presently he said:', '过了一会儿，他说：'),
    (26, 1405, 3749, '“Who could have brought those tools here?', '“谁把这些工具带到这里来的？'),
    (26, 1405, 3750, 'Do you reckon they can be upstairs?”', '你觉得它们会在楼上吗？”'),
    (26, 1406, 3751, 'The boys’ breath forsook them.', '孩子们吓得屏住了呼吸。'),
    (26, 1406, 3752, 'Injun Joe put his hand on his knife, halted a moment, undecided, and then turned toward the stairway.', '印第安·乔 把手放在刀上，犹豫了一下，然后转身走向楼梯。'),
    (26, 1406, 3753, 'The boys thought of the closet, but their strength was gone.', '孩子们想到了柜子，可他们已经没力气了。'),
    (26, 1406, 3754, 'The steps came creaking up the stairs—the intolerable distress of the situation woke the stricken resolution of the lads—they were about to spring for the closet, when there was a crash of rotten timbers and Injun Joe landed on the ground amid the debris of the ruined stairway.', '脚步声咯吱咯吱地从楼梯上传来，孩子们吓坏了。他们正想冲向柜子，突然烂木头哗啦一声塌了，印第安·乔 摔到地上，被毁坏的楼梯碎片围住。'),
    (26, 1406, 3755, 'He gathered himself up cursing, and his comrade said:', '他骂骂咧咧地爬起来，他的同伴说：'),
    (26, 1407, 3756, '“Now what’s the use of all that?', '“现在这样有什么用呢？'),
    (26, 1407, 3757, 'If it’s anybody, and they’re up there, let them _stay_ there—who cares?', '如果楼上有人，就让他们待在那儿好了——谁管他们呢？'),
    (26, 1407, 3758, 'If they want to jump down, now, and get into trouble, who objects?', '如果他们想跳下来惹麻烦，谁会反对呢？'),
    (26, 1407, 3759, 'It will be dark in fifteen minutes—and then let them follow us if they want to.', '十五分钟后天就黑了——到时候他们想跟着我们就跟着吧。'),
    (26, 1407, 3760, 'I’m willing.', '我没意见。'),
    (26, 1407, 3761, 'In my opinion, whoever hove those things in here caught a sight of us and took us for ghosts or devils or something.', '我觉得，往这里扔东西的人肯定看到了我们，把我们当成鬼或魔鬼什么的了。'),
    (26, 1407, 3762, 'I’ll bet they’re running yet.”', '我敢打赌他们还在跑呢。”'),
    (26, 1408, 3763, 'Joe grumbled awhile; then he agreed with his friend that what daylight was left ought to be economized in getting things ready for leaving.', '乔抱怨了一会儿，然后同意朋友的看法：剩下的这点亮光应该用来准备离开。'),
    (26, 1408, 3764, 'Shortly afterward they slipped out of the house in the deepening twilight, and moved toward the river with their precious box.', '没过多久，天色越来越暗，他们带着珍贵的箱子悄悄溜出房子，走向河边。'),
    (26, 1409, 3765, 'Tom and Huck rose up, weak but vastly relieved, and stared after them through the chinks between the logs of the house.', '汤姆 和 哈克 站起来，虽然有点虚弱，但心里轻松多了。他们透过房子的木头缝隙，盯着他们离开。'),
    (26, 1409, 3766, 'Follow?', '跟着去？'),
    (26, 1409, 3767, 'Not they.', '他们才不呢。'),
    (26, 1409, 3768, 'They were content to reach ground again without broken necks, and take the townward track over the hill.', '他们能安全落地就已经很开心了，然后就沿着通往小镇的小路翻过山。'),
    (26, 1409, 3769, 'They did not talk much.', '他们没怎么说话。'),
    (26, 1409, 3770, 'They were too much absorbed in hating themselves—hating the ill luck that made them take the spade and the pick there.', '他们心里很讨厌自己——讨厌他们倒霉，偏偏要把铲子和镐带到那里。'),
    (26, 1409, 3771, 'But for that, Injun Joe never would have suspected.', '要不是这样，印第安·乔 根本不会怀疑。'),
    (26, 1409, 3772, 'He would have hidden the silver with the gold to wait there till his “revenge” was satisfied, and then he would have had the misfortune to find that money turn up missing.', '他会把银子和金子藏起来，等到他“报复”完。那时候他就会发现钱不见了，那可就倒霉了。'),
    (26, 1409, 3773, 'Bitter, bitter luck that the tools were ever brought there!', '真是倒霉透了，竟然把工具带到了那里！'),
    (26, 1410, 3774, 'They resolved to keep a lookout for that Spaniard when he should come to town spying out for chances to do his revengeful job, and follow him to “Number Two,” wherever that might be.', '他们决定留意那个西班牙人，等他到镇上来找机会报仇时，就跟着他去“二号地点”，不管那是在哪里。'),
    (26, 1410, 3775, 'Then a ghastly thought occurred to Tom.', '突然，一个可怕的想法在 汤姆 的脑子里出现了。'),
    (26, 1411, 3776, '“Revenge?', '“报复？'),
    (26, 1411, 3777, 'What if he means _us_, Huck!”', '万一他指的是我们呢，哈克！”'),
    (26, 1412, 3778, '“Oh, don’t!” said Huck, nearly fainting.', '“哦，别说了！”哈克 说，他差点晕过去了。'),
    (26, 1413, 3779, 'They talked it all over, and as they entered town they agreed to believe that he might possibly mean somebody else—at least that he might at least mean nobody but Tom, since only Tom had testified.', '他们把这事儿聊了一遍。进城时，他们觉得他可能说的是别人——至少可能只说的是 汤姆，因为只有 汤姆 作证了。'),
    (26, 1414, 3780, 'Very, very small comfort it was to Tom to be alone in danger!', '这对 汤姆 来说，独自面对危险，一点安慰都没有！'),
    (26, 1414, 3781, 'Company would be a palpable improvement, he thought.', '他想，有个人陪着会好很多。'),
    (27, 1415, 3782, 'The adventure of the day mightily tormented Tom’s dreams that night.', '那天发生的事，让汤姆晚上做了很多噩梦。'),
    (27, 1415, 3783, 'Four times he had his hands on that rich treasure and four times it wasted to nothingness in his fingers as sleep forsook him and wakefulness brought back the hard reality of his misfortune.', '他梦到自己四次摸到了宝藏，可每次都从他手里溜走了。他一醒来，伤心的事就又回到他脑海里。'),
    (27, 1415, 3784, 'As he lay in the early morning recalling the incidents of his great adventure, he noticed that they seemed curiously subdued and far away—somewhat as if they had happened in another world, or in a time long gone by.', '他清早躺在床上，回想着昨天的冒险。他觉得那些事好像变得很模糊，离他很远，就像发生在另一个世界，或者很久很久以前一样。'),
    (27, 1415, 3785, 'Then it occurred to him that the great adventure itself must be a dream!', '接着他想到，昨天的冒险也许只是一个梦！'),
    (27, 1415, 3786, 'There was one very strong argument in favor of this idea—namely, that the quantity of coin he had seen was too vast to be real.', '有一个很重要的理由让他觉得是梦，那就是他看到的钱实在太多了，不可能是真的。'),
    (27, 1415, 3787, 'He had never seen as much as fifty dollars in one mass before, and he was like all boys of his age and station in life, in that he imagined that all references to “hundreds” and “thousands” were mere fanciful forms of speech, and that no such sums really existed in the world.', '他从没见过这么多钱，连五十块钱都没见过。他跟其他同龄的孩子一样，觉得“几百块”或“几千块”都是随便说说而已，世界上根本没有那么多钱。'),
    (27, 1415, 3788, 'He never had supposed for a moment that so large a sum as a hundred dollars was to be found in actual money in any one’s possession.', '他从没想过，谁能真的有一百块钱那么多。'),
    (27, 1415, 3789, 'If his notions of hidden treasure had been analyzed, they would have been found to consist of a handful of real dimes and a bushel of vague, splendid, ungraspable dollars.', '如果去看看他心里想的宝藏是什么样的，那里面可能只有一把真的小硬币，还有一大堆说不清道不明、很漂亮却抓不住的钱。'),
    (27, 1416, 3790, 'But the incidents of his adventure grew sensibly sharper and clearer under the attrition of thinking them over, and so he presently found himself leaning to the impression that the thing might not have been a dream, after all.', '但他越想，昨天的冒险就越清楚真实。于是他觉得，也许那并不是一个梦。'),
    (27, 1416, 3791, 'This uncertainty must be swept away.', '他得弄清楚，不能再这样不确定了。'),
    (27, 1416, 3792, 'He would snatch a hurried breakfast and go and find Huck.', '他决定赶紧吃完早饭，去找哈克。'),
    (27, 1417, 3793, 'Huck was sitting on the gunwale of a flatboat, listlessly dangling his feet in the water and looking very melancholy.', '哈克正坐在平底船的边上，他懒洋洋地把脚放在水里晃荡，看起来很伤心。'),
    (27, 1417, 3794, 'Tom concluded to let Huck lead up to the subject.', '汤姆决定让哈克先开口说这件事。'),
    (27, 1417, 3795, 'If he did not do it, then the adventure would be proved to have been only a dream.', '如果他没做，那这次冒险就只是一个梦。'),
    (27, 1418, 3796, '“Hello, Huck!”', '“你好，哈克！”'),
    (27, 1419, 3797, '“Hello, yourself.”', '“你也好啊。”'),
    (27, 1420, 3798, 'Silence, for a minute.', '一分钟里，他们都没有说话。'),
    (27, 1421, 3799, '“Tom, if we’d ’a’ left the blame tools at the dead tree, we’d ’a’ got the money.', '“汤姆，要是我们把那些该死的工具留在枯树那里，我们就能拿到钱了。哎呀，太糟糕了！”'),
    (27, 1421, 3800, 'Oh, ain’t it awful!”', '哦，真糟糕呀！'),
    (27, 1422, 3801, '“’Tain’t a dream, then, ’tain’t a dream!', '“那不是梦，不是梦！'),
    (27, 1422, 3802, 'Somehow I most wish it was.', '我真希望那是个梦。'),
    (27, 1422, 3803, 'Dog’d if I don’t, Huck.”', '我真是这么希望的，哈克。”'),
    (27, 1423, 3804, '“What ain’t a dream?”', '“什么不是梦？”'),
    (27, 1424, 3805, '“Oh, that thing yesterday.', '“哦，就是昨天的事。'),
    (27, 1424, 3806, 'I been half thinking it was.”', '我一直以为那是个梦呢。”'),
    (27, 1425, 3807, '“Dream!', '“梦！'),
    (27, 1425, 3808, 'If them stairs hadn’t broke down you’d ’a’ seen how much dream it was!', '要是那些楼梯没坏，你就能看到那是不是梦了！'),
    (27, 1425, 3809, 'I’ve had dreams enough all night—with that patch-eyed Spanish devil going for me all through ’em—rot him!”', '我一整晚都在做梦——梦里那个戴眼罩的西班牙坏蛋一直追着我——气死我了！”'),
    (27, 1426, 3810, '“No, not rot him.', '“不，别气他。”'),
    (27, 1426, 3811, '_Find_ him!', '找到他！'),
    (27, 1426, 3812, 'Track the money!”', '跟着钱走！”'),
    (27, 1427, 3813, '“Tom, we’ll never find him.', '“汤姆，我们永远也找不到他了。'),
    (27, 1427, 3814, 'A feller don’t have only one chance for such a pile—and that one’s lost.', '这么大一笔钱，一个人只有一次机会。现在机会没了。'),
    (27, 1427, 3815, 'I’d feel mighty shaky if I was to see him, anyway.”', '要是真见到他，我肯定会吓坏的。”'),
    (27, 1428, 3816, '“Well, so’d I; but I’d like to see him, anyway—and track him out—to his Number Two.”', '“嗯，我也是。但我还是想见到他—跟着他找到他的‘二号’。”'),
    (27, 1429, 3817, '“Number Two—yes, that’s it.', '“二号—对，就是它。'),
    (27, 1429, 3818, 'I been thinking ’bout that.', '我一直在想这个事。'),
    (27, 1429, 3819, 'But I can’t make nothing out of it.', '但我搞不懂那是什么。'),
    (27, 1429, 3820, 'What do you reckon it is?”', '你觉得它是什么？”'),
    (27, 1430, 3821, '“I dono.', '“我不知道。'),
    (27, 1430, 3822, 'It’s too deep.', '这个太难了。'),
    (27, 1430, 3823, 'Say, Huck—maybe it’s the number of a house!”', '喂，哈克—也许是房子的号码！”'),
    (27, 1431, 3824, '“Goody!...', '“太好了！...'),
    (27, 1431, 3825, 'No, Tom, that ain’t it.', '不，汤姆，不是那个。'),
    (27, 1431, 3826, 'If it is, it ain’t in this one-horse town.', '如果真是，那也不是在这个小镇上。'),
    (27, 1431, 3827, 'They ain’t no numbers here.”', '这里可没有门牌号。”'),
    (27, 1432, 3828, '“Well, that’s so.', '“嗯，是这样。'),
    (27, 1432, 3829, 'Lemme think a minute.', '让我好好想想。'),
    (27, 1432, 3830, 'Here—it’s the number of a room—in a tavern, you know!”', '有了—它是一间屋子的号码—是酒馆里的房间，你懂的！”'),
    (27, 1433, 3831, '“Oh, that’s the trick!', '“哦，原来是这样！'),
    (27, 1433, 3832, 'They ain’t only two taverns.', '这里只有两家酒馆。'),
    (27, 1433, 3833, 'We can find out quick.”', '我们很快就能查出来。”'),
    (27, 1434, 3834, '“You stay here, Huck, till I come.”', '“哈克，你留在这儿，等我回来。”'),
    (27, 1435, 3835, 'Tom was off at once.', '汤姆立刻就走了。'),
    (27, 1435, 3836, 'He did not care to have Huck’s company in public places.', '他不想在外面公共场合和哈克待在一起。'),
    (27, 1435, 3837, 'He was gone half an hour.', '他走了半个小时。'),
    (27, 1435, 3838, 'He found that in the best tavern, No. 2 had long been occupied by a young lawyer, and was still so occupied.', '他发现，最好的酒馆里，2号房间早就住了一个年轻律师，现在也还在住。'),
    (27, 1435, 3839, 'In the less ostentatious house, No. 2 was a mystery.', '在另一家没那么豪华的酒馆，2号房间却很神秘。'),
    (27, 1435, 3840, 'The tavern-keeper’s young son said it was kept locked all the time, and he never saw anybody go into it or come out of it except at night; he did not know any particular reason for this state of things; had had some little curiosity, but it was rather feeble; had made the most of the mystery by entertaining himself with the idea that that room was “ha’nted”; had noticed that there was a light in there the night before.', '酒馆老板的小儿子说，那个房间一直锁着。他从没见过有人进去或出来，只有晚上例外。他也不知道为什么会这样。他有点好奇，但也没太在意。他喜欢自己编个故事，说这房间是‘鬼屋’，觉得这样很有趣。他还发现，前一天晚上房间里亮着灯。'),
    (27, 1436, 3841, '“That’s what I’ve found out, Huck.', '“这是我发现的，哈克。'),
    (27, 1436, 3842, 'I reckon that’s the very No. 2 we’re after.”', '我觉得那就是我们要找的二号。”'),
    (27, 1437, 3843, '“I reckon it is, Tom.', '“我觉得是，汤姆。'),
    (27, 1437, 3844, 'Now what you going to do?”', '你现在打算怎么做？”'),
    (27, 1438, 3845, '“Lemme think.”', '“让我想想。”'),
    (27, 1439, 3846, 'Tom thought a long time.', '汤姆想了很久。'),
    (27, 1439, 3847, 'Then he said:', '然后他说：'),
    (27, 1440, 3848, '“I’ll tell you.', '“我告诉你。'),
    (27, 1440, 3849, 'The back door of that No. 2 is the door that comes out into that little close alley between the tavern and the old rattle trap of a brick store.', '那个二号的后门，就通向酒馆和那个破旧砖头店之间的小巷子。'),
    (27, 1440, 3850, 'Now you get hold of all the doorkeys you can find, and I’ll nip all of auntie’s, and the first dark night we’ll go there and try ’em.', '你去把能找到的门钥匙都拿来，我去偷阿姨的钥匙，等第一个很黑的晚上，我们就去那里试试。'),
    (27, 1440, 3851, 'And mind you, keep a lookout for Injun Joe, because he said he was going to drop into town and spy around once more for a chance to get his revenge.', '记住，你要留意印第安·乔，因为他说他要回城里再偷偷看看，找机会报仇。'),
    (27, 1440, 3852, 'If you see him, you just follow him; and if he don’t go to that No. 2, that ain’t the place.”', '如果你看到他，就跟着他；要是他没去那个二号，那地方就不是。”'),
    (27, 1441, 3853, '“Lordy, I don’t want to foller him by myself!”', '“天哪，我不想一个人跟着他！”'),
    (27, 1442, 3854, '“Why, it’ll be night, sure.', '“哎，肯定是在晚上。'),
    (27, 1442, 3855, 'He mightn’t ever see you—and if he did, maybe he’d never think anything.”', '他可能根本看不到你——就算看到了，他也许也不会多想什么。”'),
    (27, 1443, 3856, '“Well, if it’s pretty dark I reckon I’ll track him.', '“嗯，要是天很黑，我觉得我会跟着他。'),
    (27, 1443, 3857, 'I dono—I dono.', '我不知道——我不知道。'),
    (27, 1443, 3858, 'I’ll try.”', '我会试试的。”'),
    (27, 1444, 3859, '“You bet I’ll follow him, if it’s dark, Huck.', '“你放心，要是天黑，我肯定会跟着他，哈克。'),
    (27, 1444, 3860, 'Why, he might ’a’ found out he couldn’t get his revenge, and be going right after that money.”', '哎呀，他可能已经发现他报不了仇了，然后就直接去拿钱了呢。”'),
    (27, 1445, 3861, '“It’s so, Tom, it’s so.', '“是啊，汤姆，是啊。'),
    (27, 1445, 3862, 'I’ll foller him; I will, by jingoes!”', '我会跟着他；我一定会跟着的，真的！”'),
    (27, 1446, 3863, '“Now you’re _talking_!', '“这才对嘛！'),
    (27, 1446, 3864, 'Don’t you ever weaken, Huck, and I won’t.”', '你可别泄气啊，哈克，我也不会的。”'),
    (28, 1447, 3865, 'That night Tom and Huck were ready for their adventure.', '那天晚上，汤姆和哈克准备好去冒险了。'),
    (28, 1447, 3866, 'They hung about the neighborhood of the tavern until after nine, one watching the alley at a distance and the other the tavern door.', '他们待在酒馆附近，一直到九点以后，一个人远远地看着小巷，另一个人看着酒馆的门。'),
    (28, 1447, 3867, 'Nobody entered the alley or left it; nobody resembling the Spaniard entered or left the tavern door.', '没有人进出小巷；也没有像那个西班牙人的人进出酒馆的门。'),
    (28, 1447, 3868, 'The night promised to be a fair one; so Tom went home with the understanding that if a considerable degree of darkness came on, Huck was to come and “maow,” whereupon he would slip out and try the keys.', '那个晚上看起来不会很黑；所以汤姆回家了，他们说好要是天变得很黑，哈克就来“喵”一声，然后他就会溜出来试钥匙。'),
    (28, 1447, 3869, 'But the night remained clear, and Huck closed his watch and retired to bed in an empty sugar hogshead about twelve.', '但是那个晚上一直很亮，哈克就结束了守候，大约十二点的时候，他睡在一个空的糖桶里了。'),
    (28, 1448, 3870, 'Tuesday the boys had the same ill luck.', '星期二，这些孩子们还是运气不好。'),
    (28, 1448, 3871, 'Also Wednesday.', '也是周三。'),
    (28, 1448, 3872, 'But Thursday night promised better.', '可是周四晚上，情况会好转。'),
    (28, 1448, 3873, 'Tom slipped out in good season with his aunt’s old tin lantern, and a large towel to blindfold it with.', '汤姆悄悄溜出来了，带着姑妈的旧灯笼，还有条大毛巾，用来把灯笼蒙住。'),
    (28, 1448, 3874, 'He hid the lantern in Huck’s sugar hogshead and the watch began.', '他把灯笼藏在哈克的糖桶里，就开始守着。'),
    (28, 1448, 3875, 'An hour before midnight the tavern closed up and its lights (the only ones thereabouts) were put out.', '午夜前一小时，酒馆关门了，灯也灭了（那是附近唯一的亮光）。'),
    (28, 1448, 3876, 'No Spaniard had been seen.', '没看到西班牙人。'),
    (28, 1448, 3877, 'Nobody had entered or left the alley.', '没人进出小巷。'),
    (28, 1448, 3878, 'Everything was auspicious.', '一切都很顺利。'),
    (28, 1448, 3879, 'The blackness of darkness reigned, the perfect stillness was interrupted only by occasional mutterings of distant thunder.', '周围一片漆黑，非常安静，只有远处偶尔传来几声雷鸣。'),
    (28, 1449, 3880, 'Tom got his lantern, lit it in the hogshead, wrapped it closely in the towel, and the two adventurers crept in the gloom toward the tavern.', '汤姆拿出灯笼，在桶里点亮，用毛巾紧紧包好。两个小朋友就悄悄地，在黑漆漆中走向酒馆。'),
    (28, 1449, 3881, 'Huck stood sentry and Tom felt his way into the alley.', '哈克负责放哨，汤姆摸黑走进了小巷。'),
    (28, 1449, 3882, 'Then there was a season of waiting anxiety that weighed upon Huck’s spirits like a mountain.', '接着是一阵焦急的等待，像一座大山一样，压得哈克心里喘不过气来。'),
    (28, 1449, 3883, 'He began to wish he could see a flash from the lantern—it would frighten him, but it would at least tell him that Tom was alive yet.', '他开始希望看到灯笼闪一下——那会吓到他，但至少会告诉他，汤姆还活着呢。'),
    (28, 1449, 3884, 'It seemed hours since Tom had disappeared.', '汤姆消失了，感觉好像好几个小时过去了。'),
    (28, 1449, 3885, 'Surely he must have fainted; maybe he was dead; maybe his heart had burst under terror and excitement.', '他肯定晕倒了；也许死了；也许是吓得、兴奋得，心都快跳出来了。'),
    (28, 1449, 3886, 'In his uneasiness Huck found himself drawing closer and closer to the alley; fearing all sorts of dreadful things, and momentarily expecting some catastrophe to happen that would take away his breath.', '他心里很不安，发现自己离小巷越来越近。他害怕各种可怕的事，随时觉得会有什么灾难发生，吓得他不敢呼吸。'),
    (28, 1449, 3887, 'There was not much to take away, for he seemed only able to inhale it by thimblefuls, and his heart would soon wear itself out, the way it was beating.', '他本来就没多少气可以吓掉，好像只能一点点地吸气。他的心跳得那么快，再这样下去，很快就会累坏的。'),
    (28, 1449, 3888, 'Suddenly there was a flash of light and Tom came tearing by him: “Run!” said he; “run, for your life!”', '突然，一道亮光闪过，汤姆飞快地从他身边跑过：“快跑！”他说；“快跑，快逃命呀！”'),
    (28, 1450, 3889, 'He needn’t have repeated it; once was enough; Huck was making thirty or forty miles an hour before the repetition was uttered.', '他不用重复第二遍，一遍就够了。哈克在他重复之前，就已经跑得飞快了。'),
    (28, 1450, 3890, 'The boys never stopped till they reached the shed of a deserted slaughter-house at the lower end of the village.', '孩子们一直没停，跑到村子尽头一个废弃的屠宰场棚子才停下。'),
    (28, 1450, 3891, 'Just as they got within its shelter the storm burst and the rain poured down.', '他们刚躲进棚子里，暴风雨就来了，大雨哗哗地往下倒。'),
    (28, 1450, 3892, 'As soon as Tom got his breath he said:', '汤姆刚喘过气来，就说：'),
    (28, 1451, 3893, '“Huck, it was awful!', '“哈克，太吓人了！'),
    (28, 1451, 3894, 'I tried two of the keys, just as soft as I could; but they seemed to make such a power of racket that I couldn’t hardly get my breath I was so scared.', '我试了两把钥匙，动作已经很轻很轻了；可是它们弄出的声音太大了，我吓得都快喘不过气了。'),
    (28, 1451, 3895, 'They wouldn’t turn in the lock, either.', '钥匙也拧不动锁。'),
    (28, 1451, 3896, 'Well, without noticing what I was doing, I took hold of the knob, and open comes the door!', '哎呀，我没注意到自己在做什么，就去握门把手，结果门一下就开了！'),
    (28, 1451, 3897, 'It warn’t locked!', '门根本没锁！'),
    (28, 1451, 3898, 'I hopped in, and shook off the towel, and, _Great Caesar’s Ghost!', '我跳了进去，抖掉了毛巾，然后，_天哪！_'),
    (28, 1451, 3899, '_”', '“。”'),
    (28, 1452, 3900, '“What!', '“什么呀！”'),
    (28, 1452, 3901, '—what’d you see, Tom?”', '——你看到了什么，汤姆？”'),
    (28, 1453, 3902, '“Huck, I most stepped onto Injun Joe’s hand!”', '“哈克，我差点踩到印第安·乔的手了！”'),
    (28, 1454, 3903, '“No!”', '“不！”'),
    (28, 1455, 3904, '“Yes!', '“是啊！'),
    (28, 1455, 3905, 'He was lying there, sound asleep on the floor, with his old patch on his eye and his arms spread out.”', '他躺在那里，在地板上睡得可熟了，眼睛上还蒙着旧眼罩，胳膊也张开了。”'),
    (28, 1456, 3906, '“Lordy, what did you do?', '“天哪，你做了什么？'),
    (28, 1456, 3907, 'Did he wake up?”', '他醒了吗？”'),
    (28, 1457, 3908, '“No, never budged.', '“没有，他一动也没动。'),
    (28, 1457, 3909, 'Drunk, I reckon.', '我看他是喝醉了。'),
    (28, 1457, 3910, 'I just grabbed that towel and started!”', '我就拿起那条毛巾，开始动手了！”'),
    (28, 1458, 3911, '“I’d never ’a’ thought of the towel, I bet!”', '“我可从来没想过用毛巾，真的！”'),
    (28, 1459, 3912, '“Well, I would.', '“嗯，我就会。'),
    (28, 1459, 3913, 'My aunt would make me mighty sick if I lost it.”', '要是我弄丢了它，我阿姨会气得要命。”'),
    (28, 1460, 3914, '“Say, Tom, did you see that box?”', '“喂，汤姆，你看到那个盒子了吗？”'),
    (28, 1461, 3915, '“Huck, I didn’t wait to look around.', '“哈克，我没来得及四处看。'),
    (28, 1461, 3916, 'I didn’t see the box, I didn’t see the cross.', '我没看到盒子，也没看到十字架。'),
    (28, 1461, 3917, 'I didn’t see anything but a bottle and a tin cup on the floor by Injun Joe; yes, I saw two barrels and lots more bottles in the room.', '我什么都没看到，除了印第安·乔旁边地板上的一个瓶子和一个锡杯；是啊，我还看到屋里有两个桶和很多瓶子。'),
    (28, 1461, 3918, 'Don’t you see, now, what’s the matter with that ha’nted room?”', '你现在还不明白吗，那个闹鬼的房间是怎么回事？”'),
    (28, 1462, 3919, '“How?”', '“怎么会？”'),
    (28, 1463, 3920, '“Why, it’s ha’nted with whiskey!', '“哎呀，那里面全是威士忌在‘闹鬼’呢！'),
    (28, 1463, 3921, 'Maybe _all_ the Temperance Taverns have got a ha’nted room, hey, Huck?”', '也许所有的禁酒小酒馆都有个‘闹鬼’的房间，你说呢，哈克？”'),
    (28, 1464, 3922, '“Well, I reckon maybe that’s so.', '“嗯，我猜也许真是这样。'),
    (28, 1464, 3923, 'Who’d ’a’ thought such a thing?', '谁会想到这种事呢？'),
    (28, 1464, 3924, 'But say, Tom, now’s a mighty good time to get that box, if Injun Joe’s drunk.”', '不过喂，汤姆，要是印第安·乔喝醉了，现在可是拿那个盒子的好时候。”'),
    (28, 1465, 3925, '“It is, that!', '“没错，就是这样！'),
    (28, 1465, 3926, 'You try it!”', '你去试试看！”'),
    (28, 1466, 3927, 'Huck shuddered.', '哈克打了个寒颤。'),
    (28, 1467, 3928, '“Well, no—I reckon not.”', '“嗯，不行——我看还是算了。”'),
    (28, 1468, 3929, '“And I reckon not, Huck.', '“我看也不行，哈克。'),
    (28, 1468, 3930, 'Only one bottle alongside of Injun Joe ain’t enough.', '印第安·乔旁边只有一瓶酒，这可不够。”'),
    (28, 1468, 3931, 'If there’d been three, he’d be drunk enough and I’d do it.”', '要是喝了三杯，他肯定醉了，我就可以去做了。'),
    (28, 1469, 3932, 'There was a long pause for reflection, and then Tom said:', '他们想了很久，然后汤姆说：'),
    (28, 1470, 3933, '“Lookyhere, Huck, less not try that thing any more till we know Injun Joe’s not in there.', '“听着，哈克，我们别再试那个了，直到我们知道印第安·乔不在里面。'),
    (28, 1470, 3934, 'It’s too scary.', '那太吓人了。'),
    (28, 1470, 3935, 'Now, if we watch every night, we’ll be dead sure to see him go out, some time or other, and then we’ll snatch that box quicker’n lightning.”', '现在，如果我们每天晚上都看着，就一定能看到他出去，到时候，我们就能像闪电一样快地把盒子拿走！”'),
    (28, 1471, 3936, '“Well, I’m agreed.', '“好吧，我同意。'),
    (28, 1471, 3937, 'I’ll watch the whole night long, and I’ll do it every night, too, if you’ll do the other part of the job.”', '我会看一整晚，每天晚上都看，如果你能做另一部分的话。”'),
    (28, 1472, 3938, '“All right, I will.', '“好，我做。'),
    (28, 1472, 3939, 'All you got to do is to trot up Hooper Street a block and maow—and if I’m asleep, you throw some gravel at the window and that’ll fetch me.”', '你只要走到胡珀街一个街区远的地方，喵喵叫几声就行——要是我睡着了，你就往窗户上扔些小石子，我就会醒的。”'),
    (28, 1473, 3940, '“Agreed, and good as wheat!”', '“同意，一言为定！”'),
    (28, 1474, 3941, '“Now, Huck, the storm’s over, and I’ll go home.', '“好了，哈克，暴风雨停了，我要回家了。'),
    (28, 1474, 3942, 'It’ll begin to be daylight in a couple of hours.', '再过一两个小时天就亮了。'),
    (28, 1474, 3943, 'You go back and watch that long, will you?”', '你回去再看一会儿，好吗？”'),
    (28, 1475, 3944, '“I said I would, Tom, and I will.', '“我说我会的，汤姆，我一定会的。'),
    (28, 1475, 3945, 'I’ll ha’nt that tavern every night for a year!', '我会每天晚上都在那个小酒馆附近守着，守一年！'),
    (28, 1475, 3946, 'I’ll sleep all day and I’ll stand watch all night.”', '我白天睡觉，晚上守着。”'),
    (28, 1476, 3947, '“That’s all right.', '“那好吧。'),
    (28, 1476, 3948, 'Now, where you going to sleep?”', '你打算睡哪儿呢？”'),
    (28, 1477, 3949, '“In Ben Rogers’ hayloft.', '“在本·罗杰斯家的干草棚里。'),
    (28, 1477, 3950, 'He lets me, and so does his pap’s nigger man, Uncle Jake.', '他让我睡，他爸爸那儿的杰克叔叔也让我睡。'),
    (28, 1477, 3951, 'I tote water for Uncle Jake whenever he wants me to, and any time I ask him he gives me a little something to eat if he can spare it.', '杰克叔叔要我帮忙挑水时我就去，我什么时候问他要吃的，他有的话就会给我一点。'),
    (28, 1477, 3952, 'That’s a mighty good nigger, Tom.', '他真是个好人，汤姆。'),
    (28, 1477, 3953, 'He likes me, becuz I don’t ever act as if I was above him.', '他喜欢我，因为我从来不觉得自己比他厉害。'),
    (28, 1477, 3954, 'Sometime I’ve set right down and eat _with_ him.', '有时候我还和他一起坐下来吃饭呢。'),
    (28, 1477, 3955, 'But you needn’t tell that.', '不过你不用告诉别人。'),
    (28, 1477, 3956, 'A body’s got to do things when he’s awful hungry he wouldn’t want to do as a steady thing.”', '一个人饿得不行的时候，会做一些平时不想做的事情。”'),
    (28, 1478, 3957, '“Well, if I don’t want you in the daytime, I’ll let you sleep.', '“好，如果我白天不需要你帮忙，就让你睡觉。'),
    (28, 1478, 3958, 'I won’t come bothering around.', '我不会去打扰你的。'),
    (28, 1478, 3959, 'Any time you see something’s up, in the night, just skip right around and maow.”', '晚上你什么时候看到有什么情况，就马上跑过来喵喵叫。”'),
    (29, 1479, 3960, 'The first thing Tom heard on Friday morning was a glad piece of news—Judge Thatcher’s family had come back to town the night before.', '星期五早上，汤姆听到的第一个好消息是——撒切尔法官一家人在前一天晚上回城了。'),
    (29, 1479, 3961, 'Both Injun Joe and the treasure sunk into secondary importance for a moment, and Becky took the chief place in the boy’s interest.', '暂时，印第安·乔和宝藏都不那么重要了。小男孩最感兴趣的是贝琪。'),
    (29, 1479, 3962, 'He saw her and they had an exhausting good time playing “hispy” and “gully-keeper” with a crowd of their schoolmates.', '他看到了她，然后他们和一群同学玩“hispy”和“gully-keeper”，玩得筋疲力尽，但很开心。'),
    (29, 1479, 3963, 'The day was completed and crowned in a peculiarly satisfactory way: Becky teased her mother to appoint the next day for the long-promised and long-delayed picnic, and she consented.', '这天过得特别让人满意：贝琪缠着妈妈，让她把早就答应好的野餐定在第二天，妈妈同意了。'),
    (29, 1479, 3964, 'The child’s delight was boundless; and Tom’s not more moderate.', '小孩们开心极了；汤姆也一样高兴。'),
    (29, 1479, 3965, 'The invitations were sent out before sunset, and straightway the young folks of the village were thrown into a fever of preparation and pleasurable anticipation.', '太阳下山前，请帖就发出去了。村里的小伙伴们立刻兴奋起来，开始准备，满心期待。'),
    (29, 1479, 3966, 'Tom’s excitement enabled him to keep awake until a pretty late hour, and he had good hopes of hearing Huck’s “maow,” and of having his treasure to astonish Becky and the picnickers with, next day; but he was disappointed.', '汤姆太兴奋了，一直醒到很晚。他很希望能听到哈克的“喵呜”声，还想着第二天可以用他的宝贝吓唬吓唬贝琪和去野餐的人；但他失望了。'),
    (29, 1479, 3967, 'No signal came that night.', '那晚，没有信号传来。'),
    (29, 1480, 3968, 'Morning came, eventually, and by ten or eleven o’clock a giddy and rollicking company were gathered at Judge Thatcher’s, and everything was ready for a start.', '终于到了早上，十点或十一点的时候，一群又开心又闹腾的小伙伴们都聚集在撒切尔法官家，一切都准备好出发了。'),
    (29, 1480, 3969, 'It was not the custom for elderly people to mar the picnics with their presence.', '老年人一般不会来野餐，免得扫了大家的兴。'),
    (29, 1480, 3970, 'The children were considered safe enough under the wings of a few young ladies of eighteen and a few young gentlemen of twenty-three or thereabouts.', '有几个十八岁的年轻阿姨和二十三岁左右的年轻叔叔们看着，孩子们就被认为足够安全了。'),
    (29, 1480, 3971, 'The old steam ferry-boat was chartered for the occasion; presently the gay throng filed up the main street laden with provision-baskets.', '那艘旧蒸汽渡船被租下来了；很快，开心的队伍就带着装满食物的篮子，排着队走上了主街。'),
    (29, 1480, 3972, 'Sid was sick and had to miss the fun; Mary remained at home to entertain him.', '希德生病了，不能去玩；玛丽留在家里陪他。'),
    (29, 1480, 3973, 'The last thing Mrs. Thatcher said to Becky, was:', '撒切尔太太对贝琪说的最后一句话是：'),
    (29, 1481, 3974, '“You’ll not get back till late.', '“你会玩到很晚才回来。'),
    (29, 1481, 3975, 'Perhaps you’d better stay all night with some of the girls that live near the ferry-landing, child.”', '孩子，也许你最好跟住在渡口附近的几个女孩子住一晚吧。”'),
    (29, 1482, 3976, '“Then I’ll stay with Susy Harper, mamma.”', '“那我跟苏西·哈珀住，妈妈。”'),
    (29, 1483, 3977, '“Very well.', '“好的。'),
    (29, 1483, 3978, 'And mind and behave yourself and don’t be any trouble.”', '记得要听话，别惹麻烦哦。”'),
    (29, 1484, 3979, 'Presently, as they tripped along, Tom said to Becky:', '走着走着，汤姆对贝琪说：'),
    (29, 1485, 3980, '“Say—I’ll tell you what we’ll do.', '“听着——我告诉你我们怎么做。'),
    (29, 1485, 3981, '’Stead of going to Joe Harper’s we’ll climb right up the hill and stop at the Widow Douglas’.', '我们不去乔·哈珀家了，我们直接爬上山，去道格拉斯寡妇家。'),
    (29, 1485, 3982, 'She’ll have ice-cream!', '她家会有冰淇淋！'),
    (29, 1485, 3983, 'She has it most every day—dead loads of it.', '她几乎每天都有冰淇淋——超级多。'),
    (29, 1485, 3984, 'And she’ll be awful glad to have us.”', '而且她会非常高兴我们去。”'),
    (29, 1486, 3985, '“Oh, that will be fun!”', '“哦，那太好玩了！”'),
    (29, 1487, 3986, 'Then Becky reflected a moment and said:', '贝琪想了想，然后说：'),
    (29, 1488, 3987, '“But what will mamma say?”', '“可是妈妈会怎么说呢？”'),
    (29, 1489, 3988, '“How’ll she ever know?”', '“她怎么会知道呢？”'),
    (29, 1490, 3989, 'The girl turned the idea over in her mind, and said reluctantly:', '女孩在心里琢磨了一下，不情愿地说：'),
    (29, 1491, 3990, '“I reckon it’s wrong—but—”', '“我觉得这不对——可是——”'),
    (29, 1492, 3991, '“But shucks!', '哎呀！'),
    (29, 1492, 3992, 'Your mother won’t know, and so what’s the harm?', '你妈妈不会知道的，有什么关系呢？'),
    (29, 1492, 3993, 'All she wants is that you’ll be safe; and I bet you she’d ’a’ said go there if she’d ’a’ thought of it.', '她只希望你平安。我敢说，如果她想到这个地方，她肯定会让你去的。'),
    (29, 1492, 3994, 'I know she would!”', '我知道她会的！'),
    (29, 1493, 3995, 'The Widow Douglas’ splendid hospitality was a tempting bait.', '道格拉斯寡妇家里真好玩，太吸引人了。'),
    (29, 1493, 3996, 'It and Tom’s persuasions presently carried the day.', '他被汤姆的好玩和劝说打动了。'),
    (29, 1493, 3997, 'So it was decided to say nothing to anybody about the night’s programme.', '所以他们决定不告诉任何人今晚要做什么。'),
    (29, 1493, 3998, 'Presently it occurred to Tom that maybe Huck might come this very night and give the signal.', '很快，汤姆想到，也许哈克今晚就会来发信号。'),
    (29, 1493, 3999, 'The thought took a deal of the spirit out of his anticipations.', '这个想法让他没那么开心了。'),
    (29, 1493, 4000, 'Still he could not bear to give up the fun at Widow Douglas’.', '但他还是舍不得放弃去道格拉斯寡妇家玩。'),
    (29, 1493, 4001, 'And why should he give it up, he reasoned—the signal did not come the night before, so why should it be any more likely to come tonight?', '他想，为什么要放弃呢？昨晚暗号没来，今晚也不一定来啊？'),
    (29, 1493, 4002, 'The sure fun of the evening outweighed the uncertain treasure; and, boy-like, he determined to yield to the stronger inclination and not allow himself to think of the box of money another time that day.', '晚上肯定能玩得很开心，这比不确定的宝藏更吸引人。他像个孩子一样，决定跟着自己的心走，那天再也不去想那箱钱了。'),
    (29, 1494, 4003, 'Three miles below town the ferryboat stopped at the mouth of a woody hollow and tied up.', '在离小镇三英里远的地方，渡船在一个长满树木的山谷口停了下来。'),
    (29, 1494, 4004, 'The crowd swarmed ashore and soon the forest distances and craggy heights echoed far and near with shoutings and laughter.', '大家涌上岸，很快，远处森林和高高的山崖，到处都回荡着叫喊声和笑声。'),
    (29, 1494, 4005, 'All the different ways of getting hot and tired were gone through with, and by-and-by the rovers straggled back to camp fortified with responsible appetites, and then the destruction of the good things began.', '大家玩得又热又累。过了一会儿，这群孩子们才三三两两地回到营地。他们肚子饿得咕咕叫，然后就开始大吃特吃美味的食物了。'),
    (29, 1494, 4006, 'After the feast there was a refreshing season of rest and chat in the shade of spreading oaks.', '吃完大餐，大家在枝繁叶茂的橡树荫下休息聊天，感觉很舒服。'),
    (29, 1494, 4007, 'By-and-by somebody shouted:', '过了一会儿，有人喊道：'),
    (29, 1495, 4008, '“Who’s ready for the cave?”', '“谁准备好去山洞了？”'),
    (29, 1496, 4009, 'Everybody was.', '大家都准备好了。'),
    (29, 1496, 4010, 'Bundles of candles were procured, and straightway there was a general scamper up the hill.', '大家拿来很多蜡烛，然后立刻冲上山坡。'),
    (29, 1496, 4011, 'The mouth of the cave was up the hillside—an opening shaped like a letter A.', '山洞口在山坡上，形状像字母A。'),
    (29, 1496, 4012, 'Its massive oaken door stood unbarred.', '它厚重的橡木门开着。'),
    (29, 1496, 4013, 'Within was a small chamber, chilly as an icehouse, and walled by Nature with solid limestone that was dewy with a cold sweat.', '里面是个小房间，像冰窖一样冷。墙壁是天然的坚硬石灰岩，上面湿漉漉的，像出了冷汗。'),
    (29, 1496, 4014, 'It was romantic and mysterious to stand here in the deep gloom and look out upon the green valley shining in the sun.', '站在这里黑漆漆的山洞里，看着外面阳光下绿色的山谷，感觉既浪漫又神秘。'),
    (29, 1496, 4015, 'But the impressiveness of the situation quickly wore off, and the romping began again.', '但这种特别的感觉很快就没了，大家又开始打闹起来。'),
    (29, 1496, 4016, 'The moment a candle was lighted there was a general rush upon the owner of it; a struggle and a gallant defence followed, but the candle was soon knocked down or blown out, and then there was a glad clamor of laughter and a new chase.', '蜡烛一点亮，大家就冲上去抢拿蜡烛的人。虽然蜡烛主人努力保护，但很快蜡烛就被打翻或吹灭了。然后又是一阵开心的笑声，大家又开始了新的追逐。'),
    (29, 1496, 4017, 'But all things have an end.', '但所有事情都会结束。'),
    (29, 1496, 4018, 'By-and-by the procession went filing down the steep descent of the main avenue, the flickering rank of lights dimly revealing the lofty walls of rock almost to their point of junction sixty feet overhead.', '过了一会儿，队伍沿着主通道陡峭的下坡排队往前走。摇曳的烛光模模糊糊地照亮了高高的石壁，几乎能看到上方六十英尺高，石壁交接的地方。'),
    (29, 1496, 4019, 'This main avenue was not more than eight or ten feet wide.', '这条主通道只有八到十英尺宽。'),
    (29, 1496, 4020, 'Every few steps other lofty and still narrower crevices branched from it on either hand—for McDougal’s cave was but a vast labyrinth of crooked aisles that ran into each other and out again and led nowhere.', '每走几步，两边就会有其他更高更窄的裂缝分岔出来。因为麦克杜格尔的山洞就像一个大迷宫，里面弯弯曲曲的小路互相连着，又通向没有尽头的地方。'),
    (29, 1496, 4021, 'It was said that one might wander days and nights together through its intricate tangle of rifts and chasms, and never find the end of the cave; and that he might go down, and down, and still down, into the earth, and it was just the same—labyrinth under labyrinth, and no end to any of them.', '大家都说，这个山洞很大很大。你走啊走，白天走到晚上都走不完。它下面还有好多好多的路，就像迷宫一样，根本没有尽头。'),
    (29, 1496, 4022, 'No man “knew” the cave.', '没有人能完全知道这个山洞。'),
    (29, 1496, 4023, 'That was an impossible thing.', '这根本做不到。'),
    (29, 1496, 4024, 'Most of the young men knew a portion of it, and it was not customary to venture much beyond this known portion.', '大部分年轻人只知道山洞的一部分，他们一般不会走太远。'),
    (29, 1496, 4025, 'Tom Sawyer knew as much of the cave as any one.', '汤姆·索亚 对山洞的了解和别人一样多。'),
    (29, 1497, 4026, 'The procession moved along the main avenue some three-quarters of a mile, and then groups and couples began to slip aside into branch avenues, fly along the dismal corridors, and take each other by surprise at points where the corridors joined again.', '大家沿着主路走了很远。接着，一些人就拐进旁边的小路，在黑黑的通道里跑来跑去，在路口互相吓一跳。'),
    (29, 1497, 4027, 'Parties were able to elude each other for the space of half an hour without going beyond the “known” ground.', '他们可以在“认识”的地方玩半个小时捉迷藏，而且不会走出太远。'),
    (29, 1498, 4028, 'By-and-by, one group after another came straggling back to the mouth of the cave, panting, hilarious, smeared from head to foot with tallow drippings, daubed with clay, and entirely delighted with the success of the day.', '后来，一队队的人陆陆续续回到山洞口。他们喘着气，开开心心的，身上沾满了蜡油和泥巴，对今天玩得开心极了。'),
    (29, 1498, 4029, 'Then they were astonished to find that they had been taking no note of time and that night was about at hand.', '他们惊讶地发现，自己竟然没注意到时间，天快黑了。'),
    (29, 1498, 4030, 'The clanging bell had been calling for half an hour.', '大钟已经叮当响了半个小时。'),
    (29, 1498, 4031, 'However, this sort of close to the day’s adventures was romantic and therefore satisfactory.', '但是，用这种方式结束一天的探险，感觉又刺激又好玩。'),
    (29, 1498, 4032, 'When the ferryboat with her wild freight pushed into the stream, nobody cared sixpence for the wasted time but the captain of the craft.', '当渡船载着吵吵闹闹的人开走时，除了船长，没人觉得时间浪费了。'),
    (29, 1499, 4033, 'Huck was already upon his watch when the ferryboat’s lights went glinting past the wharf.', '当渡船的灯光闪过码头时，哈克 已经在值班了。'),
    (29, 1499, 4034, 'He heard no noise on board, for the young people were as subdued and still as people usually are who are nearly tired to death.', '船上一点声音也没有，因为那些年轻人累坏了，都变得很安静。'),
    (29, 1499, 4035, 'He wondered what boat it was, and why she did not stop at the wharf—and then he dropped her out of his mind and put his attention upon his business.', '他想这是什么船？它为什么不停靠码头呢？不过他很快就不想了，开始专心工作。'),
    (29, 1499, 4036, 'The night was growing cloudy and dark.', '晚上天色越来越阴暗了。'),
    (29, 1499, 4037, 'Ten o’clock came, and the noise of vehicles ceased, scattered lights began to wink out, all straggling foot-passengers disappeared, the village betook itself to its slumbers and left the small watcher alone with the silence and the ghosts.', '十点到了，车子声音没有了，零星的灯光也一个个熄灭。路上的人都走光了。整个村子都睡着了，只剩下小小的守夜人，周围很安静，感觉空荡荡的。'),
    (29, 1499, 4038, 'Eleven o’clock came, and the tavern lights were put out; darkness everywhere, now.', '十一点到了，酒馆的灯也灭了；现在到处都是一片漆黑。'),
    (29, 1499, 4039, 'Huck waited what seemed a weary long time, but nothing happened.', '哈克 等了好久好久，可什么事也没发生。'),
    (29, 1499, 4040, 'His faith was weakening.', '他开始有点没信心了。'),
    (29, 1499, 4041, 'Was there any use?', '还有用吗？'),
    (29, 1499, 4042, 'Was there really any use?', '真的还有用吗？'),
    (29, 1499, 4043, 'Why not give it up and turn in?', '为什么不放弃，去睡觉算了？'),
    (29, 1500, 4044, 'A noise fell upon his ear.', '他听到了一点声音。'),
    (29, 1500, 4045, 'He was all attention in an instant.', '他一下子就竖起耳朵仔细听。'),
    (29, 1500, 4046, 'The alley door closed softly.', '小巷的门轻轻地关上了。'),
    (29, 1500, 4047, 'He sprang to the corner of the brick store.', '他嗖地一下躲到砖头商店的墙角。'),
    (29, 1500, 4048, 'The next moment two men brushed by him, and one seemed to have something under his arm.', '接着，两个男人从他身边走过，其中一个人胳膊下面好像夹着什么东西。'),
    (29, 1500, 4049, 'It must be that box!', '一定是那个箱子！'),
    (29, 1500, 4050, 'So they were going to remove the treasure.', '那么他们是要把宝藏搬走。'),
    (29, 1500, 4051, 'Why call Tom now?', '现在为什么要叫汤姆呢？'),
    (29, 1500, 4052, 'It would be absurd—the men would get away with the box and never be found again.', '那样太傻了。那些人会带着箱子跑掉，就再也找不到了。'),
    (29, 1500, 4053, 'No, he would stick to their wake and follow them; he would trust to the darkness for security from discovery.', '不，他要悄悄跟着他们。他相信黑夜能帮他藏好，不被发现。'),
    (29, 1500, 4054, 'So communing with himself, Huck stepped out and glided along behind the men, cat-like, with bare feet, allowing them to keep just far enough ahead not to be invisible.', '哈克心里这么想着，就走了出来。他光着脚，像猫一样，悄悄跟在那些人后面。他让那些人走在前面，但不能离得太远，不然就看不见了。'),
    (29, 1501, 4055, 'They moved up the river street three blocks, then turned to the left up a crossstreet.', '他们沿着河边的路走了三个街区，然后左转，拐进一条小街。'),
    (29, 1501, 4056, 'They went straight ahead, then, until they came to the path that led up Cardiff Hill; this they took.', '他们一直往前走，直到看到一条通往卡迪夫山的小路。他们就走上了那条路。'),
    (29, 1501, 4057, 'They passed by the old Welshman’s house, halfway up the hill, without hesitating, and still climbed upward.', '他们经过了半山腰上老威尔士人的房子，没有停，还在往上爬。'),
    (29, 1501, 4058, 'Good, thought Huck, they will bury it in the old quarry.', '“太好了，”哈克想，“他们会把它埋在那个老采石场。”'),
    (29, 1501, 4059, 'But they never stopped at the quarry.', '但是他们没有在采石场停下来。'),
    (29, 1501, 4060, 'They passed on, up the summit.', '他们继续往前走，一直走到山顶。'),
    (29, 1501, 4061, 'They plunged into the narrow path between the tall sumach bushes, and were at once hidden in the gloom.', '他们钻进了高高的盐肤木丛之间的小路，一下子就消失在黑暗中了。'),
    (29, 1501, 4062, 'Huck closed up and shortened his distance, now, for they would never be able to see him.', '哈克现在走近了一些，因为那些人再也看不见他了。'),
    (29, 1501, 4063, 'He trotted along awhile; then slackened his pace, fearing he was gaining too fast; moved on a piece, then stopped altogether; listened; no sound; none, save that he seemed to hear the beating of his own heart.', '他走了一会儿，然后放慢了脚步，怕自己走得太快了。他又走了一小段，就完全停住了。他听了听，没有声音，什么声音都没有，只有他自己的心跳声。'),
    (29, 1501, 4064, 'The hooting of an owl came over the hill—ominous sound!', '猫头鹰的叫声从山上飘过来——这声音真不吉利！'),
    (29, 1501, 4065, 'But no footsteps.', '但是没有脚步声。'),
    (29, 1501, 4066, 'Heavens, was everything lost!', '天哪，一切都完了吗！'),
    (29, 1501, 4067, 'He was about to spring with winged feet, when a man cleared his throat not four feet from him!', '他正要飞奔起来，突然，一个男人在他身边清了清嗓子，离他不到四英尺远！'),
    (29, 1501, 4068, 'Huck’s heart shot into his throat, but he swallowed it again; and then he stood there shaking as if a dozen agues had taken charge of him at once, and so weak that he thought he must surely fall to the ground.', '哈克的心都跳到嗓子眼了，但他又把它咽了回去。他站在那里发抖，好像突然生了好几场大病，虚弱得觉得自己一定会倒在地上。'),
    (29, 1501, 4069, 'He knew where he was.', '他知道自己在哪儿。'),
    (29, 1501, 4070, 'He knew he was within five steps of the stile leading into Widow Douglas’ grounds.', '他知道自己离进入道格拉斯寡妇家院子的台阶，只有五步远了。'),
    (29, 1501, 4071, 'Very well, he thought, let them bury it there; it won’t be hard to find.', '“好吧，”他想，“让他们把它埋在那里吧，这样就不难找到了。”'),
    (29, 1502, 4072, 'Now there was a voice—a very low voice—Injun Joe’s:', '这时，传来了一个声音——很低很低的声音——是印第安·乔的声音：'),
    (29, 1503, 4073, '“Damn her, maybe she’s got company—there’s lights, late as it is.”', '“哼，这个女人，也许她家里有人——都这么晚了，还有灯光亮着。”'),
    (29, 1504, 4074, '“I can’t see any.”', '“我没看到灯光。”'),
    (29, 1505, 4075, 'This was that stranger’s voice—the stranger of the haunted house.', '这是那个陌生人的声音——就是那个闹鬼房子里的陌生人。'),
    (29, 1505, 4076, 'A deadly chill went to Huck’s heart—this, then, was the “revenge” job!', '哈克的心里一阵冰凉——原来，这就是他们说的“报仇”的事！'),
    (29, 1505, 4077, 'His thought was, to fly.', '他心里想，快跑！'),
    (29, 1505, 4078, 'Then he remembered that the Widow Douglas had been kind to him more than once, and maybe these men were going to murder her.', '他又想起，道格拉斯寡妇对他很好，不止一次帮助过他。也许这些人是要去杀她呢。'),
    (29, 1505, 4079, 'He wished he dared venture to warn her; but he knew he didn’t dare—they might come and catch him.', '他真希望自己敢去告诉她，让她小心；但他知道自己不敢——那些人可能会过来抓他。'),
    (29, 1505, 4080, 'He thought all this and more in the moment that elapsed between the stranger’s remark and Injun Joe’s next—which was—', '在那个陌生人说完话和印第安·乔说下一句话之间，他想了这么多，甚至更多——接着，印第安·乔又说——'),
    (29, 1506, 4081, '“Because the bush is in your way.', '“因为那片灌木挡住了你的路。'),
    (29, 1506, 4082, 'Now—this way—now you see, don’t you?”', '现在——这边——你看到了，对不对？”'),
    (29, 1507, 4083, '“Yes.', '“是的。'),
    (29, 1507, 4084, 'Well, there _is_ company there, I reckon.', '嗯，我觉得那里有人。'),
    (29, 1507, 4085, 'Better give it up.”', '还是放弃吧。”'),
    (29, 1508, 4086, '“Give it up, and I just leaving this country forever!', '“放弃？那我永远离开这个地方了！'),
    (29, 1508, 4087, 'Give it up and maybe never have another chance.', '放弃了，也许就再也没机会了。'),
    (29, 1508, 4088, 'I tell you again, as I’ve told you before, I don’t care for her swag—you may have it.', '我再说一遍，我以前也说过，我不在乎她的财物——你可以拿走。'),
    (29, 1508, 4089, 'But her husband was rough on me—many times he was rough on me—and mainly he was the justice of the peace that jugged me for a vagrant.', '但她丈夫对我不好——他对我很多次都很粗暴——而且他就是那个把我当成流浪汉关起来的太平绅士。'),
    (29, 1508, 4090, 'And that ain’t all.', '这还不算完。'),
    (29, 1508, 4091, 'It ain’t a millionth part of it!', '这只是很少很少的一部分！'),
    (29, 1508, 4092, 'He had me _horsewhipped_!', '他让人用马鞭抽我！'),
    (29, 1508, 4093, '—horsewhipped in front of the jail, like a nigger!', '——在监狱前面，像对待下贱人一样被马鞭抽打！'),
    (29, 1508, 4094, '—with all the town looking on!', '——全镇的人都看着！'),
    (29, 1508, 4095, '_Horsewhipped_!', '被马鞭抽打！'),
    (29, 1508, 4096, '—do you understand?', '——你明白吗？'),
    (29, 1508, 4097, 'He took advantage of me and died.', '他欺负了我，然后死了。'),
    (29, 1508, 4098, 'But I’ll take it out of _her_.”', '但我要在她身上报仇。”'),
    (29, 1509, 4099, '“Oh, don’t kill her!', '“哦，别杀她！'),
    (29, 1509, 4100, 'Don’t do that!”', '别那样做！”'),
    (29, 1510, 4101, '“Kill?', '“杀人？'),
    (29, 1510, 4102, 'Who said anything about killing?', '谁说过要杀人？'),
    (29, 1510, 4103, 'I would kill _him_ if he was here; but not her.', '如果他在这里，我会杀了他；但不是她。'),
    (29, 1510, 4104, 'When you want to get revenge on a woman you don’t kill her—bosh! you go for her looks.', '如果你想报复一个女人，你不会杀了她——胡说！你要毁掉她的容貌。'),
    (29, 1510, 4105, 'You slit her nostrils—you notch her ears like a sow!”', '你割开她的鼻孔——你像给母猪做记号一样剪她的耳朵！”'),
    (29, 1511, 4106, '“By God, that’s—”', '“天啊，那真是——”'),
    (29, 1512, 4107, '“Keep your opinion to yourself!', '“把你的想法藏起来！'),
    (29, 1512, 4108, 'It will be safest for you.', '这样你最安全。'),
    (29, 1512, 4109, 'I’ll tie her to the bed.', '我会把她绑在床上。'),
    (29, 1512, 4110, 'If she bleeds to death, is that my fault?', '如果她流血死了，那是我的错吗？”'),
    (29, 1512, 4111, 'I’ll not cry, if she does.', '她哭了，我也不会哭。'),
    (29, 1512, 4112, 'My friend, you’ll help me in this thing—for _my_ sake—that’s why you’re here—I mightn’t be able alone.', '朋友，你要帮我这件事——为了我——你在这儿就是为了帮我——我一个人可能不行。'),
    (29, 1512, 4113, 'If you flinch, I’ll kill you.', '你要是退缩，我就杀了你。'),
    (29, 1512, 4114, 'Do you understand that?', '你明白了吗？'),
    (29, 1512, 4115, 'And if I have to kill you, I’ll kill her—and then I reckon nobody’ll ever know much about who done this business.”', '要是我必须杀了你，我也会杀了她——然后，我想没人会知道是谁做的这件事。'),
    (29, 1513, 4116, '“Well, if it’s got to be done, let’s get at it.', '“好吧，要是非做不可，那就动手吧。'),
    (29, 1513, 4117, 'The quicker the better—I’m all in a shiver.”', '越快越好——我全身都在发抖。”'),
    (29, 1514, 4118, '“Do it _now_?', '“现在就做吗？'),
    (29, 1514, 4119, 'And company there?', '那里还有人吗？'),
    (29, 1514, 4120, 'Look here—I’ll get suspicious of you, first thing you know.', '听着——你要是不听话，我就会开始怀疑你。'),
    (29, 1514, 4121, 'No—we’ll wait till the lights are out—there’s no hurry.”', '不——我们等灯都灭了再说——不着急。”'),
    (29, 1515, 4122, 'Huck felt that a silence was going to ensue—a thing still more awful than any amount of murderous talk; so he held his breath and stepped gingerly back; planted his foot carefully and firmly, after balancing, one-legged, in a precarious way and almost toppling over, first on one side and then on the other.', '哈克 觉得要安静下来了——这比那些杀人的话更可怕。于是他屏住呼吸，小心地往后退。他先单腿站着，摇摇晃晃，差点摔倒，一会儿往这边倒，一会儿往那边倒，然后才小心地、稳稳地把脚放好。'),
    (29, 1515, 4123, 'He took another step back, with the same elaboration and the same risks; then another and another, and—a twig snapped under his foot!', '他又小心地往后退了一步，同样那么费劲，同样有危险；然后又一步，又一步——突然，一根小树枝在他脚下“啪”地断了！'),
    (29, 1515, 4124, 'His breath stopped and he listened.', '他屏住了呼吸，仔细听着。'),
    (29, 1515, 4125, 'There was no sound—the stillness was perfect.', '什么声音也没有——一片寂静。'),
    (29, 1515, 4126, 'His gratitude was measureless.', '他心里非常感激。'),
    (29, 1515, 4127, 'Now he turned in his tracks, between the walls of sumach bushes—turned himself as carefully as if he were a ship—and then stepped quickly but cautiously along.', '他现在原地转身，在野漆树丛的墙壁之间——他转得很小心，就像一艘大船一样——然后他快步但又很谨慎地往前走。'),
    (29, 1515, 4128, 'When he emerged at the quarry he felt secure, and so he picked up his nimble heels and flew.', '当他走到采石场时，他觉得安全了，于是他赶紧跑起来，飞快地走了。'),
    (29, 1515, 4129, 'Down, down he sped, till he reached the Welshman’s.', '他跑啊跑，一直跑到威尔士人那里。'),
    (29, 1515, 4130, 'He banged at the door, and presently the heads of the old man and his two stalwart sons were thrust from windows.', '他使劲敲门，很快，那个老人和他两个强壮的儿子的头从窗户伸了出来。'),
    (29, 1516, 4131, '“What’s the row there?', '“那里怎么回事？'),
    (29, 1516, 4132, 'Who’s banging?', '谁在敲门？'),
    (29, 1516, 4133, 'What do you want?”', '你想干什么？”'),
    (29, 1517, 4134, '“Let me in—quick!', '“快让我进去！'),
    (29, 1517, 4135, 'I’ll tell everything.”', '我会把所有的事情都告诉你们的。”'),
    (29, 1518, 4136, '“Why, who are you?”', '“哎呀，你是谁啊？”'),
    (29, 1519, 4137, '“Huckleberry Finn—quick, let me in!”', '“我是 哈克贝利·费恩——快，让我进去！”'),
    (29, 1520, 4138, '“Huckleberry Finn, indeed!', '“原来是 哈克贝利·费恩 啊！'),
    (29, 1520, 4139, 'It ain’t a name to open many doors, I judge!', '这个名字可开不了多少扇门，我想！'),
    (29, 1520, 4140, 'But let him in, lads, and let’s see what’s the trouble.”', '不过，孩子们，让他进来吧，看看出了什么事。”'),
    (29, 1521, 4141, '“Please don’t ever tell I told you,” were Huck’s first words when he got in.', '“请你千万别说是我告诉你的，”哈克一进来就这么说。'),
    (29, 1521, 4142, '“Please don’t—I’d be killed, sure—but the widow’s been good friends to me sometimes, and I want to tell—I _will_ tell if you’ll promise you won’t ever say it was me.”', '“求求你别说出去——我肯定会被杀死的——不过那个寡妇有时候对我很好，我想告诉你——如果你答应不说是我说的，我_就_告诉你。”'),
    (29, 1522, 4143, '“By George, he _has_ got something to tell, or he wouldn’t act so!” exclaimed the old man; “out with it and nobody here’ll ever tell, lad.”', '“天啊，他_真_有事情要说，不然他不会是这个样子！”老人叫道，“快说吧，这里没人会说出去的，孩子。”'),
    (29, 1523, 4144, 'Three minutes later the old man and his sons, well armed, were up the hill, and just entering the sumach path on tiptoe, their weapons in their hands.', '三分钟后，老人和他的儿子们拿着武器，上了山。他们小心翼翼地走进漆树小路。'),
    (29, 1523, 4145, 'Huck accompanied them no further.', '哈克没再跟着他们了。'),
    (29, 1523, 4146, 'He hid behind a great bowlder and fell to listening.', '他躲在一块大石头后面，竖起耳朵听着。'),
    (29, 1523, 4147, 'There was a lagging, anxious silence, and then all of a sudden there was an explosion of firearms and a cry.', '先是一阵很长的安静，让人有点紧张，然后突然传来枪声和叫喊声。'),
    (29, 1524, 4148, 'Huck waited for no particulars.', '哈克没等他们讲清发生了什么。'),
    (29, 1524, 4149, 'He sprang away and sped down the hill as fast as his legs could carry him.', '他跳起来，用最快的速度跑下山。'),
    (30, 1525, 4150, 'As the earliest suspicion of dawn appeared on Sunday morning, Huck came groping up the hill and rapped gently at the old Welshman’s door.', '星期天早上，天刚蒙蒙亮，哈克摸黑爬上山，轻轻敲了敲老威尔士人的门。'),
    (30, 1525, 4151, 'The inmates were asleep, but it was a sleep that was set on a hair-trigger, on account of the exciting episode of the night.', '里面的人都睡着了，但是因为昨晚太刺激了，他们睡得很警醒，一点声音就能把他们吵醒。'),
    (30, 1525, 4152, 'A call came from a window:', '窗户里传来一个声音：'),
    (30, 1526, 4153, '“Who’s there!”', '“谁在外面？”'),
    (30, 1527, 4154, 'Huck’s scared voice answered in a low tone:', '哈克有点害怕，小声回答：'),
    (30, 1528, 4155, '“Please let me in!', '“请让我进去！'),
    (30, 1528, 4156, 'It’s only Huck Finn!”', '我是哈克芬！”'),
    (30, 1529, 4157, '“It’s a name that can open this door night or day, lad!', '“孩子，这个名字能让这扇门无论白天黑夜都为你打开！'),
    (30, 1529, 4158, '—and welcome!”', '——欢迎你！”'),
    (30, 1530, 4159, 'These were strange words to the vagabond boy’s ears, and the pleasantest he had ever heard.', '这些话对这个流浪男孩来说很特别，也是他听过最开心的话。'),
    (30, 1530, 4160, 'He could not recollect that the closing word had ever been applied in his case before.', '他想不起来以前有人对他说过“欢迎”这个词。'),
    (30, 1530, 4161, 'The door was quickly unlocked, and he entered.', '门很快就开了，他走了进去。'),
    (30, 1530, 4162, 'Huck was given a seat and the old man and his brace of tall sons speedily dressed themselves.', '哈克坐了下来，老人和他的两个高个子儿子很快穿好了衣服。'),
    (30, 1531, 4163, '“Now, my boy, I hope you’re good and hungry, because breakfast will be ready as soon as the sun’s up, and we’ll have a piping hot one, too—make yourself easy about that!', '“好了，孩子，我希望你很饿，因为太阳一出来早餐就做好了，而且会是热腾腾的——别担心！'),
    (30, 1531, 4164, 'I and the boys hoped you’d turn up and stop here last night.”', '我和孩子们昨晚还希望你能来这里过夜呢。”'),
    (30, 1532, 4165, '“I was awful scared,” said Huck, “and I run.', '“我吓坏了，”哈克说，“我就跑了。'),
    (30, 1532, 4166, 'I took out when the pistols went off, and I didn’t stop for three mile.', '手枪一响，我就跑了，跑了三英里都没停。'),
    (30, 1532, 4167, 'I’ve come now becuz I wanted to know about it, you know; and I come before daylight becuz I didn’t want to run across them devils, even if they was dead.”', '我现在来是因为我想知道发生了什么，你知道的；我天亮前就来了，因为我不想碰上那些坏人，就算他们已经死了。”'),
    (30, 1533, 4168, '“Well, poor chap, you do look as if you’d had a hard night of it—but there’s a bed here for you when you’ve had your breakfast.', '“哎，可怜的孩子，你看起来昨晚过得很辛苦——不过你吃完早饭，这里有床给你睡。'),
    (30, 1533, 4169, 'No, they ain’t dead, lad—we are sorry enough for that.', '不，他们没死，孩子——我们为此感到很遗憾。'),
    (30, 1533, 4170, 'You see we knew right where to put our hands on them, by your description; so we crept along on tiptoe till we got within fifteen feet of them—dark as a cellar that sumach path was—and just then I found I was going to sneeze.', '你看，根据你说的，我们知道在哪里能找到他们；所以我们踮着脚尖悄悄走过去，直到离他们只有十五英尺远——那条漆树小路黑得像地窖一样——就在那时，我发现自己要打喷嚏了。'),
    (30, 1533, 4171, 'It was the meanest kind of luck!', '真是太倒霉了！'),
    (30, 1533, 4172, 'I tried to keep it back, but no use—’twas bound to come, and it did come!', '我想忍住，可是没用，它还是出来了！'),
    (30, 1533, 4173, 'I was in the lead with my pistol raised, and when the sneeze started those scoundrels a-rustling to get out of the path, I sung out, ‘Fire boys!’ and blazed away at the place where the rustling was.', '我举着手枪走在最前面。当我打喷嚏的时候，那些坏蛋就想偷偷溜走。我大喊一声“开火，孩子们！”然后就对着他们动静的地方开枪了。'),
    (30, 1533, 4174, 'So did the boys.', '孩子们也跟着开枪了。'),
    (30, 1533, 4175, 'But they were off in a jiffy, those villains, and we after them, down through the woods.', '可是那些坏蛋跑得可快了，我们跟着他们，穿过树林一直追。'),
    (30, 1533, 4176, 'I judge we never touched them.', '我想我们根本没打中他们。'),
    (30, 1533, 4177, 'They fired a shot apiece as they started, but their bullets whizzed by and didn’t do us any harm.', '他们跑的时候也开了几枪，但是子弹从我们身边飞过，一点也没伤到我们。'),
    (30, 1533, 4178, 'As soon as we lost the sound of their feet we quit chasing, and went down and stirred up the constables.', '听不到他们的脚步声后，我们就没再追了。我们去叫来了警察。'),
    (30, 1533, 4179, 'They got a posse together, and went off to guard the river bank, and as soon as it is light the sheriff and a gang are going to beat up the woods.', '他们召集了一帮人，去守住河边。天一亮，警长和他的手下就会去搜查树林。'),
    (30, 1533, 4180, 'My boys will be with them presently.', '我的孩子们很快也会跟他们一起去。'),
    (30, 1533, 4181, 'I wish we had some sort of description of those rascals—’twould help a good deal.', '要是我们知道那些坏蛋长什么样就好了——那样会帮大忙的。'),
    (30, 1533, 4182, 'But you couldn’t see what they were like, in the dark, lad, I suppose?”', '但是在黑夜里，孩子，你肯定也看不清他们长什么样吧？'),
    (30, 1534, 4183, '“Oh yes; I saw them downtown and follered them.”', '“哦，看清了！我在城里见过他们，还跟着他们呢。”'),
    (30, 1535, 4184, '“Splendid!', '“太棒了！'),
    (30, 1535, 4185, 'Describe them—describe them, my boy!”', '快说说他们长什么样——快说，孩子！”'),
    (30, 1536, 4186, '“One’s the old deaf and dumb Spaniard that’s ben around here once or twice, and t’other’s a mean-looking, ragged—”', '“一个是那个又聋又哑的老西班牙人，他以前在这里出现过一两次，另一个看起来很凶，衣服破破烂烂的——”'),
    (30, 1537, 4187, '“That’s enough, lad, we know the men!', '“够了，孩子，我们知道是哪些人了！'),
    (30, 1537, 4188, 'Happened on them in the woods back of the widow’s one day, and they slunk away.', '有一天我们在寡妇家后面的树林里碰见过他们，他们就偷偷溜走了。'),
    (30, 1537, 4189, 'Off with you, boys, and tell the sheriff—get your breakfast tomorrow morning!”', '你们快去吧，孩子们，把这事告诉警长——明天早上再吃早饭！”'),
    (30, 1538, 4190, 'The Welshman’s sons departed at once.', '威尔士人的儿子们立刻就走了。'),
    (30, 1538, 4191, 'As they were leaving the room Huck sprang up and exclaimed:', '他们刚走出房间，哈克就跳起来大喊：'),
    (30, 1539, 4192, '“Oh, please don’t tell _any_body it was me that blowed on them!', '“哦，求求你们，千万不要告诉任何人是我告发了他们！'),
    (30, 1539, 4193, 'Oh, please!”', '哦，求求你们了！”'),
    (30, 1540, 4194, '“All right if you say it, Huck, but you ought to have the credit of what you did.”', '“好吧，如果你这么说，哈克。但你做了好事，应该得到表扬的。”'),
    (30, 1541, 4195, '“Oh no, no!', '“哦不，不！'),
    (30, 1541, 4196, 'Please don’t tell!”', '求求你们不要说！”'),
    (30, 1542, 4197, 'When the young men were gone, the old Welshman said:', '等那几个年轻人走了以后，老威尔士人说：'),
    (30, 1543, 4198, '“They won’t tell—and I won’t.', '“他们不会说的——我也不会说。'),
    (30, 1543, 4199, 'But why don’t you want it known?”', '可是你为什么不想让人知道呢？”'),
    (30, 1544, 4200, 'Huck would not explain, further than to say that he already knew too much about one of those men and would not have the man know that he knew anything against him for the whole world—he would be killed for knowing it, sure.', '哈克没有多说，只是说他已经对其中一个坏蛋知道得太多了。他绝不能让那个坏蛋知道他知道那些秘密，不然他肯定会被杀死的。'),
    (30, 1545, 4201, 'The old man promised secrecy once more, and said:', '老人又答应保密，然后说：'),
    (30, 1546, 4202, '“How did you come to follow these fellows, lad?', '“你为什么跟着这些人呢，孩子？'),
    (30, 1546, 4203, 'Were they looking suspicious?”', '他们看起来很可疑吗？”'),
    (30, 1547, 4204, 'Huck was silent while he framed a duly cautious reply.', '哈克 安静地想着该怎么小心回答。'),
    (30, 1547, 4205, 'Then he said:', '然后他说：'),
    (30, 1548, 4206, '“Well, you see, I’m a kind of a hard lot,—least everybody says so, and I don’t see nothing agin it—and sometimes I can’t sleep much, on account of thinking about it and sort of trying to strike out a new way of doing.', '“嗯，你看，我这个人有点皮，——反正大家都这么说，我也不觉得有什么不好——有时候，我睡不着，因为总在想事情，想找个新办法来做。'),
    (30, 1548, 4207, 'That was the way of it last night.', '昨晚就是这样。'),
    (30, 1548, 4208, 'I couldn’t sleep, and so I come along upstreet ’bout midnight, a-turning it all over, and when I got to that old shackly brick store by the Temperance Tavern, I backed up agin the wall to have another think.', '我睡不着，所以半夜我就走到街上，一直想着事儿。到了禁酒旅馆旁边那个摇摇晃晃的旧砖房商店时，我靠着墙又想了会儿。'),
    (30, 1548, 4209, 'Well, just then along comes these two chaps slipping along close by me, with something under their arm, and I reckoned they’d stole it.', '就在这时，那两个人从我身边偷偷溜过，胳膊下好像藏着东西，我猜他们是偷来的。'),
    (30, 1548, 4210, 'One was a-smoking, and t’other one wanted a light; so they stopped right before me and the cigars lit up their faces and I see that the big one was the deaf and dumb Spaniard, by his white whiskers and the patch on his eye, and t’other one was a rusty, ragged-looking devil.”', '一个人在抽烟，另一个人想借火。他们就在我面前停了下来，雪茄的火光照亮了他们的脸。我看到高个子的是那个又聋又哑的西班牙人，因为他有白胡子和一只眼睛上蒙着眼罩。另一个人看起来又脏又破。”'),
    (30, 1549, 4211, '“Could you see the rags by the light of the cigars?”', '“你能看到雪茄的亮光照出了那些破衣服吗？”'),
    (30, 1550, 4212, 'This staggered Huck for a moment.', '哈克 听了这话愣了一下。'),
    (30, 1550, 4213, 'Then he said:', '然后他说：'),
    (30, 1551, 4214, '“Well, I don’t know—but somehow it seems as if I did.”', '“嗯，我不知道——但不知怎么的，好像是看到了。”'),
    (30, 1552, 4215, '“Then they went on, and you—”', '“然后他们走了，你呢—”'),
    (30, 1553, 4216, '“Follered ’em—yes.', '“跟着他们—对。'),
    (30, 1553, 4217, 'That was it.', '就是这样。'),
    (30, 1553, 4218, 'I wanted to see what was up—they sneaked along so.', '我想看看他们想做什么——他们走得那么鬼鬼祟祟。'),
    (30, 1553, 4219, 'I dogged ’em to the widder’s stile, and stood in the dark and heard the ragged one beg for the widder, and the Spaniard swear he’d spile her looks just as I told you and your two—”', '我一路跟着他们到了寡妇家的栅栏那里，站在黑暗中，听到那个穿破烂衣服的人求寡妇，西班牙人发誓说要毁了她的容貌，就像我告诉你的，还有你的两个—”'),
    (30, 1554, 4220, '“What!', '“什么！'),
    (30, 1554, 4221, 'The _deaf and dumb_ man said all that!”', '那个又聋又哑的人说了所有这些话！”'),
    (30, 1555, 4222, 'Huck had made another terrible mistake!', '哈克 又犯了个大错！'),
    (30, 1555, 4223, 'He was trying his best to keep the old man from getting the faintest hint of who the Spaniard might be, and yet his tongue seemed determined to get him into trouble in spite of all he could do.', '他已经尽力不让老人知道西班牙人是谁，可是他的嘴巴好像偏要给他惹麻烦。'),
    (30, 1555, 4224, 'He made several efforts to creep out of his scrape, but the old man’s eye was upon him and he made blunder after blunder.', '他试了好几次想把事情圆回来，但老人一直盯着他，他反而错上加错。'),
    (30, 1555, 4225, 'Presently the Welshman said:', '接着，那个威尔士人说：'),
    (30, 1556, 4226, '“My boy, don’t be afraid of me.', '“孩子，别怕我。'),
    (30, 1556, 4227, 'I wouldn’t hurt a hair of your head for all the world.', '我绝对不会伤害你一根头发的。'),
    (30, 1556, 4228, 'No—I’d protect you—I’d protect you.', '不—我会保护你—我会保护你。'),
    (30, 1556, 4229, 'This Spaniard is not deaf and dumb; you’ve let that slip without intending it; you can’t cover that up now.', '这个西班牙人不是又聋又哑；你刚才不小心说漏嘴了；现在你藏不住了。'),
    (30, 1556, 4230, 'You know something about that Spaniard that you want to keep dark.', '你知道一些关于那个西班牙人的事，你想藏着不说。'),
    (30, 1556, 4231, 'Now trust me—tell me what it is, and trust me—I won’t betray you.”', '现在，相信我。告诉我那是什么，我不会出卖你。”'),
    (30, 1557, 4232, 'Huck looked into the old man’s honest eyes a moment, then bent over and whispered in his ear:', '哈克看着老爷爷诚实的眼睛，过了一会儿，他凑过去，在老爷爷耳边小声说：'),
    (30, 1558, 4233, '“’Tain’t a Spaniard—it’s Injun Joe!”', '“它不是西班牙人——它是印第安·乔！”'),
    (30, 1559, 4234, 'The Welshman almost jumped out of his chair.', '那个威尔士人差点从椅子上跳起来。'),
    (30, 1559, 4235, 'In a moment he said:', '过了一会儿，他说：'),
    (30, 1560, 4236, '“It’s all plain enough, now.', '“现在，一切都清楚了。'),
    (30, 1560, 4237, 'When you talked about notching ears and slitting noses I judged that that was your own embellishment, because white men don’t take that sort of revenge.', '你说到割耳朵、切鼻子，我以为是你自己编的，因为白人不会那样报复。'),
    (30, 1560, 4238, 'But an Injun!', '但如果是印第安人！'),
    (30, 1560, 4239, 'That’s a different matter altogether.”', '那就完全不一样了。”'),
    (30, 1561, 4240, 'During breakfast the talk went on, and in the course of it the old man said that the last thing which he and his sons had done, before going to bed, was to get a lantern and examine the stile and its vicinity for marks of blood.', '吃早饭的时候，他们还在说话。老爷爷说，他和儿子们睡觉前做的最后一件事，就是拿个灯笼，去栅栏附近看看有没有血迹。'),
    (30, 1561, 4241, 'They found none, but captured a bulky bundle of—', '他们没找到血迹，但抓到了一个大大的包裹——'),
    (30, 1562, 4242, '“Of _what_?”', '“是什么？”'),
    (30, 1563, 4243, 'If the words had been lightning they could not have leaped with a more stunning suddenness from Huck’s blanched lips.', '这些话从哈克发白的嘴唇里突然蹦出来，比闪电还快，让人吃惊。'),
    (30, 1563, 4244, 'His eyes were staring wide, now, and his breath suspended—waiting for the answer.', '他现在眼睛睁得大大的，屏住呼吸——等着答案。'),
    (30, 1563, 4245, 'The Welshman started—stared in return—three seconds—five seconds—ten—then replied:', '威尔士人愣住了——也回看他——三秒——五秒——十秒——然后回答说：'),
    (30, 1564, 4246, '“Of burglar’s tools.', '“是小偷的工具。'),
    (30, 1564, 4247, 'Why, what’s the _matter_ with you?”', '哎，你怎么了？”'),
    (30, 1565, 4248, 'Huck sank back, panting gently, but deeply, unutterably grateful.', '哈克靠了回去，轻轻地、深深地喘着气，心里说不出的感激。'),
    (30, 1565, 4249, 'The Welshman eyed him gravely, curiously—and presently said:', '威尔士人严肃又好奇地看着他——过了一会儿说：'),
    (30, 1566, 4250, '“Yes, burglar’s tools.', '“是的，小偷的工具。'),
    (30, 1566, 4251, 'That appears to relieve you a good deal.', '这好像让你放松了很多。'),
    (30, 1566, 4252, 'But what did give you that turn?', '但什么让你那么吃惊呢？'),
    (30, 1566, 4253, 'What were _you_ expecting we’d found?”', '你以为我们找到了什么？”'),
    (30, 1567, 4254, 'Huck was in a close place—the inquiring eye was upon him—he would have given anything for material for a plausible answer—nothing suggested itself—the inquiring eye was boring deeper and deeper—a senseless reply offered—there was no time to weigh it, so at a venture he uttered it—feebly:', '哈克当时很为难——那好奇的目光一直看着他——他很想给一个说得过去的答案，但什么都没想到——那目光越看越深——一个没用的回答冒了出来——他没时间多想，就冒险说了出来——声音很微弱：'),
    (30, 1568, 4255, '“Sunday-school books, maybe.”', '“主日学校的书，也许吧。”'),
    (30, 1569, 4256, 'Poor Huck was too distressed to smile, but the old man laughed loud and joyously, shook up the details of his anatomy from head to foot, and ended by saying that such a laugh was money in a man’s pocket, because it cut down the doctor’s bill like everything.', '可怜的哈克难过得笑不出来，但老爷爷却大声开心地笑了，他从头到脚都笑得抖动起来，最后他说，这样一笑就像把钱放进了口袋，因为它能省下好多医药费。'),
    (30, 1569, 4257, 'Then he added:', '然后他又说：'),
    (30, 1570, 4258, '“Poor old chap, you’re white and jaded—you ain’t well a bit—no wonder you’re a little flighty and off your balance.', '“可怜的老伙计，你脸色发白，很累——一点都不舒服——怪不得你有点心神不宁，站不稳。'),
    (30, 1570, 4259, 'But you’ll come out of it.', '但你会好起来的。'),
    (30, 1570, 4260, 'Rest and sleep will fetch you out all right, I hope.”', '好好休息和睡觉，你就会没事的，我希望。”'),
    (30, 1571, 4261, 'Huck was irritated to think he had been such a goose and betrayed such a suspicious excitement, for he had dropped the idea that the parcel brought from the tavern was the treasure, as soon as he had heard the talk at the widow’s stile.', '哈克想到自己那么笨，还那么高兴，就有点生气。因为他一听到寡妇家门口的谈话，就不觉得酒馆拿回来的包裹是宝贝了。'),
    (30, 1571, 4262, 'He had only thought it was not the treasure, however—he had not known that it wasn’t—and so the suggestion of a captured bundle was too much for his self-possession.', '他只是觉得那不是宝贝，但并不知道它真的不是。所以，一听说包裹被抓住了，他一下子就紧张起来了。'),
    (30, 1571, 4263, 'But on the whole he felt glad the little episode had happened, for now he knew beyond all question that that bundle was not _the_ bundle, and so his mind was at rest and exceedingly comfortable.', '不过，他总体上还是挺高兴这件事发生了。因为现在他完全确定那个包裹不是他们要找的宝贝，心里就放松多了。'),
    (30, 1571, 4264, 'In fact, everything seemed to be drifting just in the right direction, now; the treasure must be still in No. 2, the men would be captured and jailed that day, and he and Tom could seize the gold that night without any trouble or any fear of interruption.', '看来一切都进展得很顺利。宝贝一定还在2号屋子里。那些坏人今天就会被抓起来。他和汤姆今晚就能轻松拿到金子，不用担心被别人打扰了。'),
    (30, 1572, 4265, 'Just as breakfast was completed there was a knock at the door.', '早餐刚吃完，门就响了。'),
    (30, 1572, 4266, 'Huck jumped for a hiding-place, for he had no mind to be connected even remotely with the late event.', '哈克赶紧藏起来，因为他一点也不想跟昨晚的事有任何关系。'),
    (30, 1572, 4267, 'The Welshman admitted several ladies and gentlemen, among them the Widow Douglas, and noticed that groups of citizens were climbing up the hill—to stare at the stile.', '威尔士人请了几位先生女士进来，道格拉斯寡妇也在。他还看到好多人正爬上山去看那个台阶。'),
    (30, 1572, 4268, 'So the news had spread.', '看来消息已经传开了。'),
    (30, 1572, 4269, 'The Welshman had to tell the story of the night to the visitors.', '威尔士人只好把昨晚发生的事告诉客人们。'),
    (30, 1572, 4270, 'The widow’s gratitude for her preservation was outspoken.', '寡妇很感谢自己得救了，一直说着谢谢。'),
    (30, 1573, 4271, '“Don’t say a word about it, madam.', '“夫人，别再说了。'),
    (30, 1573, 4272, 'There’s another that you’re more beholden to than you are to me and my boys, maybe, but he don’t allow me to tell his name.', '也许你更应该感谢另一个人，而不是我和我的孩子们。但他不让我说他的名字。'),
    (30, 1573, 4273, 'We wouldn’t have been there but for him.”', '要不是他，我们也不会在那里的。”'),
    (30, 1574, 4274, 'Of course this excited a curiosity so vast that it almost belittled the main matter—but the Welshman allowed it to eat into the vitals of his visitors, and through them be transmitted to the whole town, for he refused to part with his secret.', '这让大家非常好奇，都快忘了其他事了。但威尔士人不肯说出秘密，让客人们一直很想知道，还把这份好奇带到了镇上。'),
    (30, 1574, 4275, 'When all else had been learned, the widow said:', '大家知道了所有其他事情后，寡妇说：'),
    (30, 1575, 4276, '“I went to sleep reading in bed and slept straight through all that noise.', '“我在床上看书就睡着了，那些吵闹声我一点都没听到。'),
    (30, 1575, 4277, 'Why didn’t you come and wake me?”', '你们怎么没来叫醒我呀？”'),
    (30, 1576, 4278, '“We judged it warn’t worth while.', '“我们觉得没必要。'),
    (30, 1576, 4279, 'Those fellows warn’t likely to come again—they hadn’t any tools left to work with, and what was the use of waking you up and scaring you to death?', '那些坏人应该不会再来了——他们也没工具了。叫醒你，把你吓坏了又有什么用呢？'),
    (30, 1576, 4280, 'My three negro men stood guard at your house all the rest of the night.', '我的三个朋友在你的屋子外面守了剩下的半夜。'),
    (30, 1576, 4281, 'They’ve just come back.”', '他们刚刚才回来。”'),
    (30, 1577, 4282, 'More visitors came, and the story had to be told and retold for a couple of hours more.', '更多的客人来了，这个故事又被讲了好几个小时，一遍又一遍。'),
    (30, 1578, 4283, 'There was no Sabbath-school during day-school vacation, but everybody was early at church.', '学校放假，所以没有主日学。但每个人都早早地去了教堂。'),
    (30, 1578, 4284, 'The stirring event was well canvassed.', '这件激动人心的事，大家都在议论。'),
    (30, 1578, 4285, 'News came that not a sign of the two villains had been yet discovered.', '有消息说，那两个坏人一点踪影都还没找到。'),
    (30, 1578, 4286, 'When the sermon was finished, Judge Thatcher’s wife dropped alongside of Mrs. Harper as she moved down the aisle with the crowd and said:', '布道结束后，撒切尔法官的妻子跟着人群走下过道，走到哈珀太太旁边，然后说：'),
    (30, 1579, 4287, '“Is my Becky going to sleep all day?', '“我的贝琪要睡一整天吗？'),
    (30, 1579, 4288, 'I just expected she would be tired to death.”', '我还以为她会累坏了呢。”'),
    (30, 1580, 4289, '“Your Becky?”', '“你的贝琪？”'),
    (30, 1581, 4290, '“Yes,” with a startled look—“didn’t she stay with you last night?”', '“是的，”她吃惊地看着说：“她昨晚没跟你在一起吗？”'),
    (30, 1582, 4291, '“Why, no.”', '“哦，没有啊。”'),
    (30, 1583, 4292, 'Mrs. Thatcher turned pale, and sank into a pew, just as Aunt Polly, talking briskly with a friend, passed by.', '撒切尔夫人脸色发白，一屁股坐到椅子上。这时，波莉姨妈正和朋友大声说笑，从旁边走了过去。'),
    (30, 1583, 4293, 'Aunt Polly said:', '波莉姨妈说：'),
    (30, 1584, 4294, '“Goodmorning, Mrs. Thatcher.', '“早上好，撒切尔夫人。'),
    (30, 1584, 4295, 'Goodmorning, Mrs. Harper.', '早上好，哈珀夫人。'),
    (30, 1584, 4296, 'I’ve got a boy that’s turned up missing.', '我的一个孩子不见了。'),
    (30, 1584, 4297, 'I reckon my Tom stayed at your house last night—one of you.', '我想我的汤姆昨晚是住在你们其中一家的吧？'),
    (30, 1584, 4298, 'And now he’s afraid to come to church.', '现在他不敢来教堂了。'),
    (30, 1584, 4299, 'I’ve got to settle with him.”', '我得好好和他算账。”'),
    (30, 1585, 4300, 'Mrs. Thatcher shook her head feebly and turned paler than ever.', '撒切尔夫人虚弱地摇了摇头，脸色比刚才更白了。'),
    (30, 1586, 4301, '“He didn’t stay with us,” said Mrs. Harper, beginning to look uneasy.', '“他没和我们住在一起。”哈珀夫人说，她开始看起来有些不安了。'),
    (30, 1586, 4302, 'A marked anxiety came into Aunt Polly’s face.', '波莉姨妈的脸上露出明显的焦虑。'),
    (30, 1587, 4303, '“Joe Harper, have you seen my Tom this morning?”', '“乔·哈珀，你今天早上看到我的汤姆了吗？”'),
    (30, 1588, 4304, '“No’m.”', '“没有。”'),
    (30, 1589, 4305, '“When did you see him last?”', '“你最后一次见到他是什么时候？”'),
    (30, 1590, 4306, 'Joe tried to remember, but was not sure he could say.', '乔努力想了想，但他不确定自己能说出来。'),
    (30, 1590, 4307, 'The people had stopped moving out of church.', '人们不再走出教堂了。'),
    (30, 1590, 4308, 'Whispers passed along, and a boding uneasiness took possession of every countenance.', '小声的议论传开了，大家的脸上都露出了不安的神色。'),
    (30, 1590, 4309, 'Children were anxiously questioned, and young teachers.', '孩子们和年轻的老师都被着急地问着。'),
    (30, 1590, 4310, 'They all said they had not noticed whether Tom and Becky were on board the ferryboat on the homeward trip; it was dark; no one thought of inquiring if any one was missing.', '他们都说，回家的路上天太黑了，没人注意到汤姆和贝琪是不是在渡船上；也没人想到要问问有没有人不见了。'),
    (30, 1590, 4311, 'One young man finally blurted out his fear that they were still in the cave!', '终于，一个年轻人脱口而出，他担心他们还在山洞里！'),
    (30, 1590, 4312, 'Mrs. Thatcher swooned away.', '撒切尔夫人晕了过去。'),
    (30, 1590, 4313, 'Aunt Polly fell to crying and wringing her hands.', '波莉姨妈哭了起来，急得直搓手。'),
    (30, 1591, 4314, 'The alarm swept from lip to lip, from group to group, from street to street, and within five minutes the bells were wildly clanging and the whole town was up!', '警报声从一个人的嘴传到另一个人的嘴，从一群人传到另一群人，从一条街传到另一条街。不到五分钟，钟声就疯狂地响了起来，整个镇子都沸腾了！'),
    (30, 1591, 4315, 'The Cardiff Hill episode sank into instant insignificance, the burglars were forgotten, horses were saddled, skiffs were manned, the ferryboat ordered out, and before the horror was half an hour old, two hundred men were pouring down highroad and river toward the cave.', '关于卡迪夫山的事立刻变得不重要了，大家也忘了那些小偷。人们给马套上鞍子，划着小船，渡船也被派了出去。恐怖的事情发生不到半小时，两百个男人就沿着大路和河流，向山洞跑去。'),
    (30, 1592, 4316, 'All the long afternoon the village seemed empty and dead.', '整个漫长的下午，村子看起来空荡荡的，死气沉沉。'),
    (30, 1592, 4317, 'Many women visited Aunt Polly and Mrs. Thatcher and tried to comfort them.', '许多女人去看望了波莉姨妈和撒切尔夫人，想安慰她们。'),
    (30, 1592, 4318, 'They cried with them, too, and that was still better than words.', '她们也和她们一起哭了，这比任何言语都更能安慰人。'),
    (30, 1592, 4319, 'All the tedious night the town waited for news; but when the morning dawned at last, all the word that came was, “Send more candles—and send food.”', '整个漫长的夜晚，小镇都在等着消息。但当清晨终于到来时，传回来的消息却是：“多送些蜡烛——还要送吃的！”'),
    (30, 1592, 4320, 'Mrs. Thatcher was almost crazed; and Aunt Polly, also.', '撒切尔夫人几乎要疯了；波莉姨妈也是一样。'),
    (30, 1592, 4321, 'Judge Thatcher sent messages of hope and encouragement from the cave, but they conveyed no real cheer.', '撒切尔法官 从山洞里传来一些充满希望的话，但是听起来一点也不让人高兴。'),
    (30, 1593, 4322, 'The old Welshman came home toward daylight, spattered with candle-grease, smeared with clay, and almost worn out.', '那个老威尔士人天快亮时才回家，他身上沾满了蜡油和泥土，累得筋疲力尽。'),
    (30, 1593, 4323, 'He found Huck still in the bed that had been provided for him, and delirious with fever.', '他发现哈克还在为他准备的床上，发着高烧，神志不清。'),
    (30, 1593, 4324, 'The physicians were all at the cave, so the Widow Douglas came and took charge of the patient.', '医生们都去了山洞，所以道格拉斯寡妇来照顾病人。'),
    (30, 1593, 4325, 'She said she would do her best by him, because, whether he was good, bad, or indifferent, he was the Lord’s, and nothing that was the Lord’s was a thing to be neglected.', '她说她会好好照顾他，因为不管他好不好，都是上帝的孩子，上帝的孩子都不能被忽视。'),
    (30, 1593, 4326, 'The Welshman said Huck had good spots in him, and the widow said:', '那个威尔士人说哈克身上有好的地方，那个寡妇说：'),
    (30, 1594, 4327, '“You can depend on it.', '“你相信我说的没错。'),
    (30, 1594, 4328, 'That’s the Lord’s mark.', '那是上帝的印记。'),
    (30, 1594, 4329, 'He don’t leave it off.', '他不会把它去掉。'),
    (30, 1594, 4330, 'He never does.', '他从来不会。'),
    (30, 1594, 4331, 'Puts it somewhere on every creature that comes from his hands.”', '他会在每一个由他创造的生灵身上留下印记。”'),
    (30, 1595, 4332, 'Early in the forenoon parties of jaded men began to straggle into the village, but the strongest of the citizens continued searching.', '上午很早的时候，一群疲惫的人陆续回到了村子里，但是最强壮的村民们还在继续寻找。'),
    (30, 1595, 4333, 'All the news that could be gained was that remotenesses of the cavern were being ransacked that had never been visited before; that every corner and crevice was going to be thoroughly searched; that wherever one wandered through the maze of passages, lights were to be seen flitting hither and thither in the distance, and shoutings and pistol-shots sent their hollow reverberations to the ear down the sombre aisles.', '得到的消息是：洞穴里从未去过的地方都被仔细搜查了；每一个角落和缝隙都会被彻底搜查；不管你走到迷宫般的通道哪里，都能看到远处有灯光闪烁；喊叫声和枪声在阴暗的过道里回荡着。'),
    (30, 1595, 4334, 'In one place, far from the section usually traversed by tourists, the names “BECKY & TOM” had been found traced upon the rocky wall with candle-smoke, and near at hand a grease-soiled bit of ribbon.', '在一个游客通常不去的地方，人们发现岩石墙上用蜡烛烟熏出了“BECKY & TOM”的名字，旁边还有一小段沾着油污的缎带。'),
    (30, 1595, 4335, 'Mrs. Thatcher recognized the ribbon and cried over it.', '撒切尔夫人认出了那段缎带，伤心地哭了。'),
    (30, 1595, 4336, 'She said it was the last relic she should ever have of her child; and that no other memorial of her could ever be so precious, because this one parted latest from the living body before the awful death came.', '她说这是她孩子留下的最后一样东西了；也没有任何纪念品比这个更珍贵，因为这是孩子可怕的死亡来临前，最后离开孩子身体的东西。'),
    (30, 1595, 4337, 'Some said that now and then, in the cave, a far-away speck of light would glimmer, and then a glorious shout would burst forth and a score of men go trooping down the echoing aisle—and then a sickening disappointment always followed; the children were not there; it was only a searcher’s light.', '有人说，山洞里有时会闪烁着远处的一点亮光，接着就会爆发出一阵欢呼，二十来个人会冲向回荡着声音的通道——接着总是会传来让人难过的失望消息：孩子们不在那里，那只是一束搜寻者的灯光。'),
    (30, 1596, 4338, 'Three dreadful days and nights dragged their tedious hours along, and the village sank into a hopeless stupor.', '可怕的三天三夜过去了，时间过得又慢又长，村子里的人都陷入了绝望的麻木中。'),
    (30, 1596, 4339, 'No one had heart for anything.', '大家都没有心思做任何事情。'),
    (30, 1596, 4340, 'The accidental discovery, just made, that the proprietor of the Temperance Tavern kept liquor on his premises, scarcely fluttered the public pulse, tremendous as the fact was.', '大家发现禁酒旅馆的老板在店里藏酒了，这件事虽然很惊人，但大家已经没什么感觉了。'),
    (30, 1596, 4341, 'In a lucid interval, Huck feebly led up to the subject of taverns, and finally asked—dimly dreading the worst—if anything had been discovered at the Temperance Tavern since he had been ill.', '哈克头脑清醒了一些，他虚弱地提起了旅馆的事情，最终，他有点害怕地问，自从他生病以来，禁酒旅馆有没有发现什么？'),
    (30, 1597, 4342, '“Yes,” said the widow.', '“是的。”寡妇说。'),
    (30, 1598, 4343, 'Huck started up in bed, wild-eyed:', '哈克猛地从床上坐起来，眼睛睁得大大的：'),
    (30, 1599, 4344, '“What?', '“什么？'),
    (30, 1599, 4345, 'What was it?”', '那是什么？”'),
    (30, 1600, 4346, '“Liquor!', '“酒！'),
    (30, 1600, 4347, '—and the place has been shut up.', '——那个地方已经被关了。'),
    (30, 1600, 4348, 'Lie down, child—what a turn you did give me!”', '躺下，孩子——你可把我吓了一跳！”'),
    (30, 1601, 4349, '“Only tell me just one thing—only just one—please!', '“就告诉我一件事——就一件——拜托了！'),
    (30, 1601, 4350, 'Was it Tom Sawyer that found it?”', '是汤姆·索亚发现的吗？”'),
    (30, 1602, 4351, 'The widow burst into tears.', '寡妇突然哭了起来。'),
    (30, 1602, 4352, '“Hush, hush, child, hush!', '“嘘，嘘，孩子，别哭！'),
    (30, 1602, 4353, 'I’ve told you before, you must _not_ talk.', '我以前说过，你_不能_说话。'),
    (30, 1602, 4354, 'You are very, very sick!”', '你病得很重，很重！”'),
    (30, 1603, 4355, 'Then nothing but liquor had been found; there would have been a great powwow if it had been the gold.', '那时候只找到了酒，要是找到的是金子，那可就热闹了。'),
    (30, 1603, 4356, 'So the treasure was gone forever—gone forever!', '宝藏就这样永远不见了——永远不见了！'),
    (30, 1603, 4357, 'But what could she be crying about?', '可是，她为什么哭呢？'),
    (30, 1603, 4358, 'Curious that she should cry.', '她哭，真奇怪。'),
    (30, 1604, 4359, 'These thoughts worked their dim way through Huck’s mind, and under the weariness they gave him he fell asleep.', '这些念头模模糊糊地在哈克的脑海里转，他太累了，就睡着了。'),
    (30, 1604, 4360, 'The widow said to herself:', '寡妇自言自语地说：'),
    (30, 1605, 4361, '“There—he’s asleep, poor wreck.', '“哎呀——他睡着了，真可怜。'),
    (30, 1605, 4362, 'Tom Sawyer find it!', '汤姆·索亚快找到它！'),
    (30, 1605, 4363, 'Pity but somebody could find Tom Sawyer!', '要是有人能找到汤姆·索亚就好了！'),
    (30, 1605, 4364, 'Ah, there ain’t many left, now, that’s got hope enough, or strength enough, either, to go on searching.”', '哎，现在没多少人了，大家都没什么希望，也没力气继续找了。”'),
    (31, 1606, 4365, 'Now to return to Tom and Becky’s share in the picnic.', '现在我们回到汤姆和贝琪参加野餐的事情。'),
    (31, 1606, 4366, 'They tripped along the murky aisles with the rest of the company, visiting the familiar wonders of the cave—wonders dubbed with rather over-descriptive names, such as “The Drawing-Room,” “The Cathedral,” “Aladdin’s Palace,” and so on.', '他们跟着大家，在昏暗的过道里走啊走，参观洞穴里那些熟悉又奇妙的地方——那些地方都有很特别的名字，比如“客厅”、“大教堂”、“阿拉丁的宫殿”等等。'),
    (31, 1606, 4367, 'Presently the hide-and-seek frolicking began, and Tom and Becky engaged in it with zeal until the exertion began to grow a trifle wearisome; then they wandered down a sinuous avenue holding their candles aloft and reading the tangled webwork of names, dates, postoffice addresses, and mottoes with which the rocky walls had been frescoed (in candle-smoke).', '很快，他们开始玩捉迷藏，汤姆和贝琪玩得很起劲，直到有点累了。然后，他们就拿着蜡烛，顺着一条弯弯曲曲的小路走下去，仔细看石头墙上用蜡烛烟熏出来的各种名字、日期、地址和标语。'),
    (31, 1606, 4368, 'Still drifting along and talking, they scarcely noticed that they were now in a part of the cave whose walls were not frescoed.', '他们一边走一边说话，几乎没注意到，他们已经到了洞穴里墙壁上没有画画的地方了。'),
    (31, 1606, 4369, 'They smoked their own names under an overhanging shelf and moved on.', '他们在一个突出的石架下面，用烟熏上自己的名字，然后继续往前走。'),
    (31, 1606, 4370, 'Presently they came to a place where a little stream of water, trickling over a ledge and carrying a limestone sediment with it, had, in the slow-dragging ages, formed a laced and ruffled Niagara in gleaming and imperishable stone.', '很快，他们来到一个地方，那里有一股小水流，它从一个石架上滴下来，带着石灰石的泥沙，经过漫长的时间，形成了一片闪闪发光、像花边一样美丽的石头瀑布。'),
    (31, 1606, 4371, 'Tom squeezed his small body behind it in order to illuminate it for Becky’s gratification.', '汤姆把小小的身子挤到后面，好让贝琪看得更清楚、更开心。'),
    (31, 1606, 4372, 'He found that it curtained a sort of steep natural stairway which was enclosed between narrow walls, and at once the ambition to be a discoverer seized him.', '他发现，那后面藏着一个很陡的天然石阶，两边是窄窄的石墙。他立刻就想成为一个探险家了。'),
    (31, 1607, 4373, 'Becky responded to his call, and they made a smoke-mark for future guidance, and started upon their quest.', '贝琪听到他的叫声，就过来和他们一起，他们做了个烟熏的记号，方便以后认路，然后就开始了他们的探险。'),
    (31, 1607, 4374, 'They wound this way and that, far down into the secret depths of the cave, made another mark, and branched off in search of novelties to tell the upper world about.', '他们弯弯曲曲地往前走，一直走到洞穴深处，又做了个记号，然后就分开了，去寻找新奇的东西，好带回去讲给上面的人听。'),
    (31, 1607, 4375, 'In one place they found a spacious cavern, from whose ceiling depended a multitude of shining stalactites of the length and circumference of a man’s leg; they walked all about it, wondering and admiring, and presently left it by one of the numerous passages that opened into it.', '在一个地方，他们发现了一个宽敞的大洞，洞顶上挂着许多闪闪发光的石钟乳，像人的腿一样粗长。他们绕着洞走了一圈，非常好奇和赞叹，过了一会儿，就从其中一个通向外面的小路离开了。'),
    (31, 1607, 4376, 'This shortly brought them to a bewitching spring, whose basin was incrusted with a frostwork of glittering crystals; it was in the midst of a cavern whose walls were supported by many fantastic pillars which had been formed by the joining of great stalactites and stalagmites together, the result of the ceaseless water-drip of centuries.', '没过多久，他们来到一个迷人的泉水边，泉水池里结满了闪亮的晶体，像冰霜一样。这个泉水在一个大洞的中间，洞的墙壁上有很多奇特的石柱，这些石柱都是由大大的石钟乳和石笋经过几百年水滴不停地滴落，慢慢连接在一起形成的。'),
    (31, 1607, 4377, 'Under the roof vast knots of bats had packed themselves together, thousands in a bunch; the lights disturbed the creatures and they came flocking down by hundreds, squeaking and darting furiously at the candles.', '洞顶下面，密密麻麻地挤满了蝙蝠，成千上万只聚在一起。光线惊动了这些小家伙，它们成群地飞下来，叽叽喳喳地叫着，凶猛地冲向蜡烛。'),
    (31, 1607, 4378, 'Tom knew their ways and the danger of this sort of conduct.', '汤姆知道这些蝙蝠的习性，也知道它们这样做的危险。'),
    (31, 1607, 4379, 'He seized Becky’s hand and hurried her into the first corridor that offered; and none too soon, for a bat struck Becky’s light out with its wing while she was passing out of the cavern.', '他抓住贝琪的手，赶紧把她拉进最近的那个过道里。幸好走得快，因为当她刚走出大洞的时候，一只蝙蝠就用翅膀把贝琪的蜡烛打灭了。'),
    (31, 1607, 4380, 'The bats chased the children a good distance; but the fugitives plunged into every new passage that offered, and at last got rid of the perilous things.', '蝙蝠追了孩子们很长一段路，但是孩子们不断地钻进新的过道里，终于摆脱了这些危险的家伙。'),
    (31, 1607, 4381, 'Tom found a subterranean lake, shortly, which stretched its dim length away until its shape was lost in the shadows.', '汤姆很快就发现了一个地下湖。湖水暗暗的，一眼望不到头，消失在黑影里了。'),
    (31, 1607, 4382, 'He wanted to explore its borders, but concluded that it would be best to sit down and rest awhile, first.', '他想去湖边看看，但觉得还是先坐下来休息一下比较好。'),
    (31, 1607, 4383, 'Now, for the first time, the deep stillness of the place laid a clammy hand upon the spirits of the children.', '现在，这里的寂静第一次让孩子们感到有点害怕。'),
    (31, 1607, 4384, 'Becky said:', '贝琪说：'),
    (31, 1608, 4385, '“Why, I didn’t notice, but it seems ever so long since I heard any of the others.”', '“哎呀，我都没注意到，好像好久没听到其他人的声音了。”'),
    (31, 1609, 4386, '“Come to think, Becky, we are away down below them—and I don’t know how far away north, or south, or east, or whichever it is.', '“仔细想想，贝琪，我们现在比他们低好多，而且我也不知道我们往北、往南、往东，还是往哪个方向走了多远。我们在这里听不到他们的声音的。”'),
    (31, 1609, 4387, 'We couldn’t hear them here.”', '我们在这里听不到他们的声音。'),
    (31, 1610, 4388, 'Becky grew apprehensive.', '贝琪开始担心起来。'),
    (31, 1611, 4389, '“I wonder how long we’ve been down here, Tom?', '“汤姆，我们在这里待了多久了呀？我们最好往回走了。”'),
    (31, 1611, 4390, 'We better start back.”', '我们最好往回走吧。”'),
    (31, 1612, 4391, '“Yes, I reckon we better.', '“是啊，我想我们最好还是走吧。'),
    (31, 1612, 4392, 'P’raps we better.”', '也许，我们还是走吧。”'),
    (31, 1613, 4393, '“Can you find the way, Tom?', '“汤姆，你还找得到路吗？这里对我来说，都是弯弯曲曲、乱七八糟的。”'),
    (31, 1613, 4394, 'It’s all a mixed-up crookedness to me.”', '对我来说，这里弯弯曲曲的，太乱了。”'),
    (31, 1614, 4395, '“I reckon I could find it—but then the bats.', '“我想我能找到路——但那些蝙蝠怎么办？要是它们把我们的蜡烛弄灭了，那就糟透了。我们还是走别的路吧，别去那里了。”'),
    (31, 1614, 4396, 'If they put our candles out it will be an awful fix.', '如果它们把蜡烛弄灭了，那就太糟糕了。”'),
    (31, 1614, 4397, 'Let’s try some other way, so as not to go through there.”', '我们走别的路吧，不要从那里过。”'),
    (31, 1615, 4398, '“Well.', '“好吧。'),
    (31, 1615, 4399, 'But I hope we won’t get lost.', '但我希望我们不会迷路。'),
    (31, 1615, 4400, 'It would be so awful!” and the girl shuddered at the thought of the dreadful possibilities.', '那样就太可怕了！” 女孩想到那些可能发生的坏事，吓得打了个哆嗦。'),
    (31, 1616, 4401, 'They started through a corridor, and traversed it in silence a long way, glancing at each new opening, to see if there was anything familiar about the look of it; but they were all strange.', '他们沿着一条走廊一直往前走，走了好远好远，一路上都没说话。他们会看看每个新的岔路口，想知道有没有熟悉的地方，但所有的路口都很陌生。'),
    (31, 1616, 4402, 'Every time Tom made an examination, Becky would watch his face for an encouraging sign, and he would say cheerily:', '每次汤姆检查时，贝琪都会盯着他的脸，想看到一些让人高兴的信号。汤姆就会开心地说：'),
    (31, 1617, 4403, '“Oh, it’s all right.', '“哦，没事的。'),
    (31, 1617, 4404, 'This ain’t the one, but we’ll come to it right away!”', '这不是那条路，但我们马上就能找到的！”'),
    (31, 1618, 4405, 'But he felt less and less hopeful with each failure, and presently began to turn off into diverging avenues at sheer random, in desperate hope of finding the one that was wanted.', '但每次找不到路，他就越来越不抱希望。后来，他开始随便走进一些岔路，希望能碰巧找到那条他们想走的路。'),
    (31, 1618, 4406, 'He still said it was “all right,” but there was such a leaden dread at his heart that the words had lost their ring and sounded just as if he had said, “All is lost!”', '他嘴上还说着“没事的”，但他心里却充满了沉重的害怕，说出来的话一点力量都没有了，听起来就像在说“一切都完了！”'),
    (31, 1618, 4407, 'Becky clung to his side in an anguish of fear, and tried hard to keep back the tears, but they would come.', '贝琪害怕极了，紧紧地靠在他身边，努力忍住眼泪，可眼泪还是忍不住流了下来。'),
    (31, 1618, 4408, 'At last she said:', '最后，她说：'),
    (31, 1619, 4409, '“Oh, Tom, never mind the bats, let’s go back that way!', '“哦，汤姆，别管蝙蝠了，我们还是走那条路回去吧！我们好像一直走得越来越糟。”'),
    (31, 1619, 4410, 'We seem to get worse and worse off all the time.”', '我们好像一直走得越来越不对劲了。”'),
    (31, 1620, 4411, '“Listen!” said he.', '“听！”他说。'),
    (31, 1621, 4412, 'Profound silence; silence so deep that even their breathings were conspicuous in the hush.', '四周很安静，安静得连他们自己的呼吸声都听得一清二楚。'),
    (31, 1621, 4413, 'Tom shouted.', '汤姆大声喊。'),
    (31, 1621, 4414, 'The call went echoing down the empty aisles and died out in the distance in a faint sound that resembled a ripple of mocking laughter.', '他的声音在空荡荡的通道里回荡，渐渐消失在远处，听起来像是在嘲笑他们。'),
    (31, 1622, 4415, '“Oh, don’t do it again, Tom, it is too horrid,” said Becky.', '“哦，别再这样了，汤姆，太吓人了，”贝琪说。'),
    (31, 1623, 4416, '“It is horrid, but I better, Becky; they might hear us, you know,” and he shouted again.', '“是有点吓人，但我最好还是喊，贝琪；他们可能会听到我们，你知道的，”他又喊了一声。'),
    (31, 1624, 4417, 'The “might” was even a chillier horror than the ghostly laughter, it so confessed a perishing hope.', '“可能”这个词，比那幽灵般的笑声更让他们害怕，这说明他们的希望快要没了。'),
    (31, 1624, 4418, 'The children stood still and listened; but there was no result.', '孩子们一动不动地站着听；但什么也没发生。'),
    (31, 1624, 4419, 'Tom turned upon the back track at once, and hurried his steps.', '汤姆立刻往回走，加快了脚步。'),
    (31, 1624, 4420, 'It was but a little while before a certain indecision in his manner revealed another fearful fact to Becky—he could not find his way back!', '没过多久，他有些犹豫的样子让贝琪发现了一个更可怕的事实——他找不到回去的路了！'),
    (31, 1625, 4421, '“Oh, Tom, you didn’t make any marks!”', '“哦，汤姆，你没有做任何记号！”'),
    (31, 1626, 4422, '“Becky, I was such a fool!', '“贝琪，我真是太笨了！'),
    (31, 1626, 4423, 'Such a fool!', '真是太笨了！'),
    (31, 1626, 4424, 'I never thought we might want to come back!', '我从没想过我们可能要回来！'),
    (31, 1626, 4425, 'No—I can’t find the way.', '不——我找不到路了。'),
    (31, 1626, 4426, 'It’s all mixed up.”', '全都乱了。”'),
    (31, 1627, 4427, '“Tom, Tom, we’re lost! we’re lost!', '“汤姆，汤姆，我们迷路了！我们迷路了！'),
    (31, 1627, 4428, 'We never can get out of this awful place!', '我们永远也出不去这个可怕的地方了！'),
    (31, 1627, 4429, 'Oh, why _did_ we ever leave the others!”', '哦，我们当初为什么要离开其他人！”'),
    (31, 1628, 4430, 'She sank to the ground and burst into such a frenzy of crying that Tom was appalled with the idea that she might die, or lose her reason.', '她瘫坐在地上，大哭起来，哭得汤姆很害怕，他担心她会死掉，或者疯掉。'),
    (31, 1628, 4431, 'He sat down by her and put his arms around her; she buried her face in his bosom, she clung to him, she poured out her terrors, her unavailing regrets, and the far echoes turned them all to jeering laughter.', '他坐在她旁边，抱住她；她把脸埋在他怀里，紧紧抓住他，把她的恐惧和后悔都说了出来，远处的回声却像是在嘲笑他们。'),
    (31, 1628, 4432, 'Tom begged her to pluck up hope again, and she said she could not.', '汤姆求她重新振作起来，她却说她做不到。'),
    (31, 1628, 4433, 'He fell to blaming and abusing himself for getting her into this miserable situation; this had a better effect.', '他开始责怪自己，说他不该把她带到这个糟糕的境地；这样一来，效果反而好了一些。'),
    (31, 1628, 4434, 'She said she would try to hope again, she would get up and follow wherever he might lead if only he would not talk like that any more.', '她说她会再试着抱有希望，她会起来跟着他走，只要他不再说那样的话。'),
    (31, 1628, 4435, 'For he was no more to blame than she, she said.', '她说，他并不比她更该被责怪。'),
    (31, 1629, 4436, 'So they moved on again—aimlessly—simply at random—all they could do was to move, keep moving.', '于是他们又继续往前走——漫无目的地——只是随便走——他们能做的就是不停地走，一直走。'),
    (31, 1629, 4437, 'For a little while, hope made a show of reviving—not with any reason to back it, but only because it is its nature to revive when the spring has not been taken out of it by age and familiarity with failure.', '过了一会儿，希望好像又回来了——不是有什么特别的理由，只是因为希望本来就会这样，只要还没有完全消失。'),
    (31, 1630, 4438, 'By-and-by Tom took Becky’s candle and blew it out.', '过了一会儿，汤姆拿过贝琪的蜡烛，把它吹灭了。'),
    (31, 1630, 4439, 'This economy meant so much!', '这样节省很要紧！'),
    (31, 1630, 4440, 'Words were not needed.', '什么都不用多说。'),
    (31, 1630, 4441, 'Becky understood, and her hope died again.', '贝琪明白了，她的希望又没了。'),
    (31, 1630, 4442, 'She knew that Tom had a whole candle and three or four pieces in his pockets—yet he must economize.', '她知道汤姆口袋里还有一整根蜡烛和三四小块，但他还是要省着用。'),
    (31, 1631, 4443, 'By-and-by, fatigue began to assert its claims; the children tried to pay attention, for it was dreadful to think of sitting down when time was grown to be so precious, moving, in some direction, in any direction, was at least progress and might bear fruit; but to sit down was to invite death and shorten its pursuit.', '慢慢地，他们都累了。孩子们努力打起精神，因为时间很宝贵，如果坐下来，就太可怕了。只要能走一步，就有点希望。但如果坐下，就好像在等死。'),
    (31, 1632, 4444, 'At last Becky’s frail limbs refused to carry her farther.', '最后，贝琪瘦弱的腿再也走不动了。'),
    (31, 1632, 4445, 'She sat down.', '她坐了下来。'),
    (31, 1632, 4446, 'Tom rested with her, and they talked of home, and the friends there, and the comfortable beds and, above all, the light!', '汤姆也和她一起休息。他们聊起了家，聊起那里的朋友，舒服的床，还有最重要的——亮光！'),
    (31, 1632, 4447, 'Becky cried, and Tom tried to think of some way of comforting her, but all his encouragements were grown thread-bare with use, and sounded like sarcasms.', '贝琪哭了。汤姆想办法安慰她，但他那些鼓励的话都说得太多了，听起来像在嘲笑她。'),
    (31, 1632, 4448, 'Fatigue bore so heavily upon Becky that she drowsed off to sleep.', '贝琪太累了，迷迷糊糊地睡着了。'),
    (31, 1632, 4449, 'Tom was grateful.', '汤姆很感激。'),
    (31, 1632, 4450, 'He sat looking into her drawn face and saw it grow smooth and natural under the influence of pleasant dreams; and by-and-by a smile dawned and rested there.', '他坐着，看着她疲惫的脸。在美梦中，她的脸慢慢变得平静又自然，不一会儿，脸上露出了微笑。'),
    (31, 1632, 4451, 'The peaceful face reflected somewhat of peace and healing into his own spirit, and his thoughts wandered away to bygone times and dreamy memories.', '那张平静的脸让他心里也平静下来，感觉好多了。他的思绪飘回了以前，想起了很多美好的旧事。'),
    (31, 1632, 4452, 'While he was deep in his musings, Becky woke up with a breezy little laugh—but it was stricken dead upon her lips, and a groan followed it.', '当他还在想着事情时，贝琪醒了，轻轻地笑了笑。但笑容立刻消失了，她发出了一声呻吟。'),
    (31, 1633, 4453, '“Oh, how _could_ I sleep!', '“哦，我怎么能睡着呢！'),
    (31, 1633, 4454, 'I wish I never, never had waked!', '我真希望我永远不要醒过来！'),
    (31, 1633, 4455, 'No!', '不！'),
    (31, 1633, 4456, 'No, I don’t, Tom!', '不，我不是那个意思，汤姆！'),
    (31, 1633, 4457, 'Don’t look so!', '别那样看我！'),
    (31, 1633, 4458, 'I won’t say it again.”', '我不会再说了。”'),
    (31, 1634, 4459, '“I’m glad you’ve slept, Becky; you’ll feel rested, now, and we’ll find the way out.”', '“你睡了一会儿，真好，贝琪。现在你会觉得好多了，我们会找到出去的路的。”'),
    (31, 1635, 4460, '“We can try, Tom; but I’ve seen such a beautiful country in my dream.', '“我们可以试试，汤姆。可是我在梦里看到了一个好漂亮的地方。'),
    (31, 1635, 4461, 'I reckon we are going there.”', '我想我们就是要去那里。”'),
    (31, 1636, 4462, '“Maybe not, maybe not.', '“也许不会，也许不会。'),
    (31, 1636, 4463, 'Cheer up, Becky, and let’s go on trying.”', '振作起来，贝琪，我们继续努力吧。”'),
    (31, 1637, 4464, 'They rose up and wandered along, hand in hand and hopeless.', '他们站起来，手牵手，漫无目的地走着，心里充满了绝望。'),
    (31, 1637, 4465, 'They tried to estimate how long they had been in the cave, but all they knew was that it seemed days and weeks, and yet it was plain that this could not be, for their candles were not gone yet.', '他们试着算算在山洞里待了多久，但感觉好像好几天甚至好几个星期了。可他们知道不可能这么久，因为蜡烛还没用完呢。'),
    (31, 1637, 4466, 'A long time after this—they could not tell how long—Tom said they must go softly and listen for dripping water—they must find a spring.', '过了好久好久——他们也说不清楚多久——汤姆说他们得轻轻地走，听听有没有水滴声，他们得找到水源。'),
    (31, 1637, 4467, 'They found one presently, and Tom said it was time to rest again.', '很快他们就找到了一个，汤姆说该休息了。'),
    (31, 1637, 4468, 'Both were cruelly tired, yet Becky said she thought she could go a little farther.', '他们两个都累坏了。但贝琪说她觉得还能再走一小段路。'),
    (31, 1637, 4469, 'She was surprised to hear Tom dissent.', '她没想到汤姆不同意。'),
    (31, 1637, 4470, 'She could not understand it.', '她不明白为什么。'),
    (31, 1637, 4471, 'They sat down, and Tom fastened his candle to the wall in front of them with some clay.', '他们坐下了，汤姆 用泥巴把蜡烛粘在他们面前的墙上。'),
    (31, 1637, 4472, 'Thought was soon busy; nothing was said for some time.', '大家都在想事情，一会儿没人说话。'),
    (31, 1637, 4473, 'Then Becky broke the silence:', '然后，贝琪 开口了：'),
    (31, 1638, 4474, '“Tom, I am so hungry!”', '“汤姆，我好饿啊！”'),
    (31, 1639, 4475, 'Tom took something out of his pocket.', '汤姆 从口袋里拿出一个东西。'),
    (31, 1640, 4476, '“Do you remember this?” said he.', '“你还记得这个吗？”他说。'),
    (31, 1641, 4477, 'Becky almost smiled.', '贝琪 差点笑了。'),
    (31, 1642, 4478, '“It’s our wedding-cake, Tom.”', '“这是我们的结婚蛋糕，汤姆。”'),
    (31, 1643, 4479, '“Yes—I wish it was as big as a barrel, for it’s all we’ve got.”', '“是啊——我真希望它能像桶一样大，因为我们就只有这么多了。”'),
    (31, 1644, 4480, '“I saved it from the picnic for us to dream on, Tom, the way grownup people do with wedding-cake—but it’ll be our—”', '“我把它从野餐中留了下来，好让我们做梦用，汤姆。就像大人会用结婚蛋糕做的那样——但它会是我们的——”'),
    (31, 1645, 4481, 'She dropped the sentence where it was.', '她没有说完这句话。'),
    (31, 1645, 4482, 'Tom divided the cake and Becky ate with good appetite, while Tom nibbled at his moiety.', '汤姆 分了蛋糕，贝琪 吃得津津有味，而 汤姆 小口小口地吃着他的那份。'),
    (31, 1645, 4483, 'There was abundance of cold water to finish the feast with.', '还有很多冷水可以喝。'),
    (31, 1645, 4484, 'By-and-by Becky suggested that they move on again.', '过了一会儿，贝琪 建议他们再往前走。'),
    (31, 1645, 4485, 'Tom was silent a moment.', '汤姆 沉默了一会儿。'),
    (31, 1645, 4486, 'Then he said:', '然后他说：'),
    (31, 1646, 4487, '“Becky, can you bear it if I tell you something?”', '“贝琪，如果我告诉你一件事，你能挺住吗？”'),
    (31, 1647, 4488, 'Becky’s face paled, but she thought she could.', '贝琪 的脸变白了，但她觉得她能挺住。'),
    (31, 1648, 4489, '“Well, then, Becky, we must stay here, where there’s water to drink.', '“那么，贝琪，我们必须留在这里，这里有水可以喝。'),
    (31, 1648, 4490, 'That little piece is our last candle!”', '那一小截是我们的最后一根蜡烛了！”'),
    (31, 1649, 4491, 'Becky gave loose to tears and wailings.', '贝琪 大哭起来。'),
    (31, 1649, 4492, 'Tom did what he could to comfort her, but with little effect.', '汤姆 尽力安慰她，但没什么用。'),
    (31, 1649, 4493, 'At length Becky said:', '最后，贝琪 说：'),
    (31, 1650, 4494, '“Tom!”', '“汤姆！”'),
    (31, 1651, 4495, '“Well, Becky?”', '“怎么了，贝琪？”'),
    (31, 1652, 4496, '“They’ll miss us and hunt for us!”', '“他们会想念我们，然后来找我们的！”'),
    (31, 1653, 4497, '“Yes, they will!', '“是的，他们会的！'),
    (31, 1653, 4498, 'Certainly they will!”', '他们一定会来的！”'),
    (31, 1654, 4499, '“Maybe they’re hunting for us now, Tom.”', '“也许他们现在就在找我们，汤姆。”'),
    (31, 1655, 4500, '“Why, I reckon maybe they are.', '“哎呀，我想他们可能正在找呢。'),
    (31, 1655, 4501, 'I hope they are.”', '希望他们会。”'),
    (31, 1656, 4502, '“When would they miss us, Tom?”', '“汤姆，他们什么时候会想我们呢？”'),
    (31, 1657, 4503, '“When they get back to the boat, I reckon.”', '“他们回到船上时，我想。”'),
    (31, 1658, 4504, '“Tom, it might be dark then—would they notice we hadn’t come?”', '“汤姆，那时候天可能黑了——他们会发现我们没来吗？”'),
    (31, 1659, 4505, '“I don’t know.', '“我不知道。'),
    (31, 1659, 4506, 'But anyway, your mother would miss you as soon as they got home.”', '不过啊，他们一到家，你妈妈就会想你的。”'),
    (31, 1660, 4507, 'A frightened look in Becky’s face brought Tom to his senses and he saw that he had made a blunder.', '贝琪的脸上露出害怕的表情，让汤姆回过神来，他发现自己说错了话。'),
    (31, 1660, 4508, 'Becky was not to have gone home that night!', '贝琪那天晚上不应该回家！'),
    (31, 1660, 4509, 'The children became silent and thoughtful.', '孩子们安静下来，开始思考。'),
    (31, 1660, 4510, 'In a moment a new burst of grief from Becky showed Tom that the thing in his mind had struck hers also—that the Sabbath morning might be half spent before Mrs. Thatcher discovered that Becky was not at Mrs. Harper’s.', '很快，贝琪又伤心地哭起来，这让汤姆明白，他心里想的事，她也想到了——可能等到安息日早上过了一半，撒切尔太太才会发现贝琪不在哈珀太太家。'),
    (31, 1661, 4511, 'The children fastened their eyes upon their bit of candle and watched it melt slowly and pitilessly away; saw the half inch of wick stand alone at last; saw the feeble flame rise and fall, climb the thin column of smoke, linger at its top a moment, and then—the horror of utter darkness reigned!', '孩子们盯着那点蜡烛，看着它慢慢地、无情地融化；看到只剩下半英寸的烛芯；看到微弱的火焰忽高忽低，爬上细细的烟柱，在顶端停留片刻，然后——可怕的黑暗彻底降临了！'),
    (31, 1662, 4512, 'How long afterward it was that Becky came to a slow consciousness that she was crying in Tom’s arms, neither could tell.', '过了多久，贝琪才慢慢意识到自己在汤姆怀里哭，他们俩都说不清楚。'),
    (31, 1662, 4513, 'All that they knew was, that after what seemed a mighty stretch of time, both awoke out of a dead stupor of sleep and resumed their miseries once more.', '他们只知道，好像过了很长很长时间，两人都从昏睡中醒来，又开始感到痛苦了。'),
    (31, 1662, 4514, 'Tom said it might be Sunday, now—maybe Monday.', '汤姆说，现在可能已经是星期天了——也许是星期一。'),
    (31, 1662, 4515, 'He tried to get Becky to talk, but her sorrows were too oppressive, all her hopes were gone.', '他想让贝琪说话，但她太伤心了，所有的希望都没了。'),
    (31, 1662, 4516, 'Tom said that they must have been missed long ago, and no doubt the search was going on.', '汤姆说他们肯定早就被发现了，现在一定有人在找他们。'),
    (31, 1662, 4517, 'He would shout and maybe some one would come.', '他大喊一声，也许会有人来。'),
    (31, 1662, 4518, 'He tried it; but in the darkness the distant echoes sounded so hideously that he tried it no more.', '他试了试；但在黑暗中，远处的回声听起来太可怕了，他就不再喊了。'),
    (31, 1663, 4519, 'The hours wasted away, and hunger came to torment the captives again.', '时间一点点过去，饥饿又来折磨这两个被困的孩子了。'),
    (31, 1663, 4520, 'A portion of Tom’s half of the cake was left; they divided and ate it.', '汤姆那半块蛋糕还剩一点；他们分着吃了。'),
    (31, 1663, 4521, 'But they seemed hungrier than before.', '但他们感觉比以前更饿了。'),
    (31, 1663, 4522, 'The poor morsel of food only whetted desire.', '那一小块食物反而让他们更想吃东西了。'),
    (31, 1664, 4523, 'By-and-by Tom said:', '过了一会儿，汤姆说：'),
    (31, 1665, 4524, '“SH!', '“嘘！'),
    (31, 1665, 4525, 'Did you hear that?”', '你听到了吗？”'),
    (31, 1666, 4526, 'Both held their breath and listened.', '两人都屏住呼吸，仔细听。'),
    (31, 1666, 4527, 'There was a sound like the faintest, far-off shout.', '有一种声音，像是很远很远的微弱喊声。'),
    (31, 1666, 4528, 'Instantly Tom answered it, and leading Becky by the hand, started groping down the corridor in its direction.', '汤姆立刻回应，然后牵着贝琪的手，摸索着朝那个方向走廊深处走去。'),
    (31, 1666, 4529, 'Presently he listened again; again the sound was heard, and apparently a little nearer.', '接着他又听了听；声音又出现了，而且好像近了一点。'),
    (31, 1667, 4530, '“It’s them!” said Tom; “they’re coming!', '“是他们！”汤姆说；“他们来了！”'),
    (31, 1667, 4531, 'Come along, Becky—we’re all right now!”', '快来，贝琪——我们现在没事了！'),
    (31, 1668, 4532, 'The joy of the prisoners was almost overwhelming.', '这些被困住的孩子们高兴坏了。'),
    (31, 1668, 4533, 'Their speed was slow, however, because pitfalls were somewhat common, and had to be guarded against.', '不过，他们走得很慢，因为路上有很多陷阱，要小心。'),
    (31, 1668, 4534, 'They shortly came to one and had to stop.', '没多久，他们就走到一个陷阱前，只好停下来。'),
    (31, 1668, 4535, 'It might be three feet deep, it might be a hundred—there was no passing it at any rate.', '这个陷阱可能三英尺深，也可能一百英尺深——反正过不去。'),
    (31, 1668, 4536, 'Tom got down on his breast and reached as far down as he could.', '汤姆趴下来，尽力往下探。'),
    (31, 1668, 4537, 'No bottom.', '摸不到底。'),
    (31, 1668, 4538, 'They must stay there and wait until the searchers came.', '他们只能待在那儿，等找他们的人来。'),
    (31, 1668, 4539, 'They listened; evidently the distant shoutings were growing more distant! a moment or two more and they had gone altogether.', '他们听了听；那些远处的叫声好像越来越远了！过了一会儿，就完全听不到了。'),
    (31, 1668, 4540, 'The heart-sinking misery of it!', '真是太让人伤心了！'),
    (31, 1668, 4541, 'Tom whooped until he was hoarse, but it was of no use.', '汤姆喊得嗓子都哑了，可是一点用也没有。'),
    (31, 1668, 4542, 'He talked hopefully to Becky; but an age of anxious waiting passed and no sounds came again.', '他对着贝琪说着有希望的话；可是等了好久，一点声音都没有再传来。'),
    (31, 1669, 4543, 'The children groped their way back to the spring.', '孩子们摸索着回到了泉水边。'),
    (31, 1669, 4544, 'The weary time dragged on; they slept again, and awoke famished and woe-stricken.', '疲惫的时间慢慢过去；他们又睡了一觉，醒来时又饿又难过。'),
    (31, 1669, 4545, 'Tom believed it must be Tuesday by this time.', '汤姆觉得现在一定是星期二了。'),
    (31, 1670, 4546, 'Now an idea struck him.', '这时，他想到了一个办法。'),
    (31, 1670, 4547, 'There were some side passages near at hand.', '旁边有一些小岔路。'),
    (31, 1670, 4548, 'It would be better to explore some of these than bear the weight of the heavy time in idleness.', '与其什么都不做，不如去这些小路看看。'),
    (31, 1670, 4549, 'He took a kite-line from his pocket, tied it to a projection, and he and Becky started, Tom in the lead, unwinding the line as he groped along.', '他从口袋里拿出一根放风筝的线，把它系在一个突起的地方，然后他和贝琪就出发了。汤姆走在前面，一边摸索着走，一边把线放开。'),
    (31, 1670, 4550, 'At the end of twenty steps the corridor ended in a “jumping-off place.”', '走了二十步，这条小路就到了尽头，是个“跳下去的地方”。'),
    (31, 1670, 4551, 'Tom got down on his knees and felt below, and then as far around the corner as he could reach with his hands conveniently; he made an effort to stretch yet a little farther to the right, and at that moment, not twenty yards away, a human hand, holding a candle, appeared from behind a rock!', '汤姆跪下来往下摸，然后又方便地把手伸到角落能摸到的最远的地方；他努力再往右边伸了一点，就在那时，离他不远的地方，一块岩石后面出现了一只拿着蜡烛的手！'),
    (31, 1670, 4552, 'Tom lifted up a glorious shout, and instantly that hand was followed by the body it belonged to—Injun Joe’s!', '汤姆高兴地大叫起来，那只手的主人马上就出现了——是印第安·乔！'),
    (31, 1670, 4553, 'Tom was paralyzed; he could not move.', '汤姆吓呆了；他一动也不能动。'),
    (31, 1670, 4554, 'He was vastly gratified the next moment, to see the “Spaniard” take to his heels and get himself out of sight.', '下一秒，他看到那个“西班牙人”拔腿就跑，消失不见了，心里非常高兴。'),
    (31, 1670, 4555, 'Tom wondered that Joe had not recognized his voice and come over and killed him for testifying in court.', '汤姆很奇怪，乔为什么没有认出他的声音，过来对付他，因为他曾在法庭上作证过。'),
    (31, 1670, 4556, 'But the echoes must have disguised the voice.', '但回声一定让声音变样了。'),
    (31, 1670, 4557, 'Without doubt, that was it, he reasoned.', '他想，肯定是这样。'),
    (31, 1670, 4558, 'Tom’s fright weakened every muscle in his body.', '汤姆吓得全身都没力气了。'),
    (31, 1670, 4559, 'He said to himself that if he had strength enough to get back to the spring he would stay there, and nothing should tempt him to run the risk of meeting Injun Joe again.', '他对自己说，如果他有足够的力气回到泉水边，他就会待在那里，什么都不能再让他去冒遇到印第安·乔的危险了。'),
    (31, 1670, 4560, 'He was careful to keep from Becky what it was he had seen.', '他小心地不让贝琪知道他看到了什么。'),
    (31, 1670, 4561, 'He told her he had only shouted “for luck.”', '他告诉她，他只是为了“有好运”才大叫的。'),
    (31, 1671, 4562, 'But hunger and wretchedness rise superior to fears in the long run.', '但饿肚子和难受久了，就什么也不怕了。'),
    (31, 1671, 4563, 'Another tedious wait at the spring and another long sleep brought changes.', '又在泉水边等了好久，又睡了一大觉，事情变了。'),
    (31, 1671, 4564, 'The children awoke tortured with a raging hunger.', '孩子们醒来时，饿得肚子好痛好痛。'),
    (31, 1671, 4565, 'Tom believed that it must be Wednesday or Thursday or even Friday or Saturday, now, and that the search had been given over.', '汤姆想，现在一定是星期三、星期四，甚至星期五或星期六了，大家肯定已经不找他们了。'),
    (31, 1671, 4566, 'He proposed to explore another passage.', '他说要去探探别的路。'),
    (31, 1671, 4567, 'He felt willing to risk Injun Joe and all other terrors.', '他觉得就算有印第安·乔和其他吓人的事，他也要去。'),
    (31, 1671, 4568, 'But Becky was very weak.', '但是贝琪已经很没力气了。'),
    (31, 1671, 4569, 'She had sunk into a dreary apathy and would not be roused.', '她变得很没精神，怎么也叫不醒。'),
    (31, 1671, 4570, 'She said she would wait, now, where she was, and die—it would not be long.', '她说她就呆在这儿等死吧，很快就好了。'),
    (31, 1671, 4571, 'She told Tom to go with the kite-line and explore if he chose; but she implored him to come back every little while and speak to her; and she made him promise that when the awful time came, he would stay by her and hold her hand until all was over.', '她让汤姆拿着风筝线去探险，如果他想去的话。但她求他，每隔一会儿就回来跟她说话。她还让他保证，等最可怕的时候到了，他会一直陪着她，牵着她的手，直到一切都过去。'),
    (31, 1672, 4572, 'Tom kissed her, with a choking sensation in his throat, and made a show of being confident of finding the searchers or an escape from the cave; then he took the kite-line in his hand and went groping down one of the passages on his hands and knees, distressed with hunger and sick with bodings of coming doom.', '汤姆亲了她一下，喉咙里很难受，但他还是装作很有信心地说能找到大人或者能逃出山洞。然后他拿着风筝线，手脚并用，摸着黑走进了一条路。他又饿又难受，心里还很担心会发生可怕的事情。'),
    (32, 1673, 4573, 'Tuesday afternoon came, and waned to the twilight.', '星期二下午到了，天色慢慢变暗，成了傍晚。'),
    (32, 1673, 4574, 'The village of St. Petersburg still mourned.', '圣彼得斯堡小村庄还在难过。'),
    (32, 1673, 4575, 'The lost children had not been found.', '那些不见了的孩子，还没找到。'),
    (32, 1673, 4576, 'Public prayers had been offered up for them, and many and many a private prayer that had the petitioner’s whole heart in it; but still no good news came from the cave.', '大家都在为孩子们祈祷，很多人也自己偷偷地真心祈祷；但山洞里还是没有传来好消息。'),
    (32, 1673, 4577, 'The majority of the searchers had given up the quest and gone back to their daily avocations, saying that it was plain the children could never be found.', '大部分找孩子的大人，都放弃了，回家忙自己的事去了。他们说，孩子们肯定找不到了。'),
    (32, 1673, 4578, 'Mrs. Thatcher was very ill, and a great part of the time delirious.', '撒切尔阿姨病得很重，大部分时间都迷迷糊糊的。'),
    (32, 1673, 4579, 'People said it was heartbreaking to hear her call her child, and raise her head and listen a whole minute at a time, then lay it wearily down again with a moan.', '大家说，听到她叫自己的孩子，然后抬起头听一整分钟，接着又累得放下头，还轻轻地叹气，真是太让人难过了。'),
    (32, 1673, 4580, 'Aunt Polly had drooped into a settled melancholy, and her gray hair had grown almost white.', '波莉姨妈变得很忧伤，她的灰头发都快变成白头发了。'),
    (32, 1673, 4581, 'The village went to its rest on Tuesday night, sad and forlorn.', '星期二晚上，村子里的人都睡了，心里很难过。'),
    (32, 1674, 4582, 'Away in the middle of the night a wild peal burst from the village bells, and in a moment the streets were swarming with frantic half-clad people, who shouted, “Turn out! turn out! they’re found! they’re found!”', '半夜里，村子的钟声突然响起来，街上一下子挤满了好多还没穿好衣服的大人，他们又跑又叫：“快出来！快出来！孩子们找到了！找到了！”'),
    (32, 1674, 4583, 'Tin pans and horns were added to the din, the population massed itself and moved toward the river, met the children coming in an open carriage drawn by shouting citizens, thronged around it, joined its homeward march, and swept magnificently up the main street roaring huzzah after huzzah!', '大家又敲盆子又吹号角，所有人都挤在一起，朝着河边走。他们看到孩子们坐着马车回来了，马车是好多大人拉着的，他们一边拉一边喊。大家把马车围起来，跟着它一起回家，然后浩浩荡荡地走过大马路，不停地大声欢呼！'),
    (32, 1675, 4584, 'The village was illuminated; nobody went to bed again; it was the greatest night the little town had ever seen.', '村子里灯都亮着，没有人再去睡觉了。这是这个小镇从来没有过的最开心的夜晚。'),
    (32, 1675, 4585, 'During the first half-hour a procession of villagers filed through Judge Thatcher’s house, seized the saved ones and kissed them, squeezed Mrs. Thatcher’s hand, tried to speak but couldn’t—and drifted out raining tears all over the place.', '最开始的半个小时里，好多村民排着队走进撒切尔法官的家，抱住那些被救回来的孩子亲亲，紧紧握住撒切尔阿姨的手，想说话却说不出来——然后流着眼泪走开了。'),
    (32, 1676, 4586, 'Aunt Polly’s happiness was complete, and Mrs. Thatcher’s nearly so.', '波莉姨妈很高兴，撒切尔阿姨也差不多。'),
    (32, 1676, 4587, 'It would be complete, however, as soon as the messenger dispatched with the great news to the cave should get the word to her husband.', '不过，等把好消息告诉她丈夫的人跑到山洞，她的幸福就更完整了。'),
    (32, 1676, 4588, 'Tom lay upon a sofa with an eager auditory about him and told the history of the wonderful adventure, putting in many striking additions to adorn it withal; and closed with a description of how he left Becky and went on an exploring expedition; how he followed two avenues as far as his kite-line would reach; how he followed a third to the fullest stretch of the kite-line, and was about to turn back when he glimpsed a far-off speck that looked like daylight; dropped the line and groped toward it, pushed his head and shoulders through a small hole, and saw the broad Mississippi rolling by!', '汤姆躺在沙发上，好多人围着他，都想听故事。他讲起了这次奇妙的冒险，还加了很多有意思的细节，让故事更好听。最后，他说他是怎么离开贝琪去探险的：他沿着两条路走，走到风筝线够不到的地方；又沿着第三条路一直走到风筝线最长的地方。他正要回头，突然看到远处有一个小亮点，好像是外面天亮了！他放下线，摸着黑朝亮点走过去，把头和肩膀挤过一个小洞，结果看到了宽阔的密西西比大河！'),
    (32, 1677, 4589, 'And if it had only happened to be night he would not have seen that speck of daylight and would not have explored that passage any more!', '而且如果当时正好是晚上，他就看不到那个亮光，也就不会再往前探索那条路了！'),
    (32, 1677, 4590, 'He told how he went back for Becky and broke the good news and she told him not to fret her with such stuff, for she was tired, and knew she was going to die, and wanted to.', '他说他是怎么回去找贝琪的，还把好消息告诉她。可是贝琪却说不要用这些事来烦她，因为她太累了，知道自己快要死了，也想死掉。'),
    (32, 1677, 4591, 'He described how he labored with her and convinced her; and how she almost died for joy when she had groped to where she actually saw the blue speck of daylight; how he pushed his way out at the hole and then helped her out; how they sat there and cried for gladness; how some men came along in a skiff and Tom hailed them and told them their situation and their famished condition; how the men didn’t believe the wild tale at first, “because,” said they, “you are five miles down the river below the valley the cave is in”—then took them aboard, rowed to a house, gave them supper, made them rest till two or three hours after dark and then brought them home.', '他说了他是怎么和她一起努力，最后说服了她。当她摸到真正能看到一点点蓝色亮光的地方时，她高兴得差点晕过去。他是怎么从洞口挤出去，又把她拉出来的。他们坐在那里，高兴地哭了。一些人划着小船来了，汤姆叫住了他们，问了他们的情况，知道他们很饿。那些人一开始不相信这个离奇的故事，因为他们说：“你们在离山谷五英里远的地方，那里根本没有山洞。”然后，他们把他们带上了船，划到一个房子，给他们吃了晚饭，让他们一直休息到天黑两三个小时以后，才把他们送回家。'),
    (32, 1678, 4592, 'Before day-dawn, Judge Thatcher and the handful of searchers with him were tracked out, in the cave, by the twine clews they had strung behind them, and informed of the great news.', '天亮之前，撒切尔法官和他带着的几个找他们的人，顺着他们之前系在身后的绳子，在山洞里找到了出去的路。他们也知道了这个好消息。'),
    (32, 1679, 4593, 'Three days and nights of toil and hunger in the cave were not to be shaken off at once, as Tom and Becky soon discovered.', '在山洞里累了三天三夜，又饿了三天三夜，这种辛苦不是一下子就能恢复的，汤姆和贝琪很快就发现了这一点。'),
    (32, 1679, 4594, 'They were bedridden all of Wednesday and Thursday, and seemed to grow more and more tired and worn, all the time.', '他们星期三和星期四都躺在床上，感觉越来越累，越来越没精神。'),
    (32, 1679, 4595, 'Tom got about, a little, on Thursday, was downtown Friday, and nearly as whole as ever Saturday; but Becky did not leave her room until Sunday, and then she looked as if she had passed through a wasting illness.', '汤姆星期四能稍微动一动了，星期五去了市中心，星期六就差不多完全好了；但是贝琪一直到星期天都没出门，她看起来就像大病了一场。'),
    (32, 1680, 4596, 'Tom learned of Huck’s sickness and went to see him on Friday, but could not be admitted to the bedroom; neither could he on Saturday or Sunday.', '汤姆知道了哈克生病了，星期五去看了他，但没能进卧室；星期六和星期天也没能进去。'),
    (32, 1680, 4597, 'He was admitted daily after that, but was warned to keep still about his adventure and introduce no exciting topic.', '从那以后，他每天都能进去看他了，但是他被提醒，不能说他冒险的事情，也不能说任何让人兴奋的话题。'),
    (32, 1680, 4598, 'The Widow Douglas stayed by to see that he obeyed.', '道格拉斯寡妇一直在旁边看着，确保他听话。'),
    (32, 1680, 4599, 'At home Tom learned of the Cardiff Hill event; also that the “ragged man’s” body had eventually been found in the river near the ferry-landing; he had been drowned while trying to escape, perhaps.', '在家的时候，汤姆知道了卡迪夫山的事情；也知道了那个“衣衫褴褛的男人”的尸体，最后在渡口附近被人在河里找到了；他可能是在逃跑的时候淹死的。'),
    (32, 1681, 4600, 'About a fortnight after Tom’s rescue from the cave, he started off to visit Huck, who had grown plenty strong enough, now, to hear exciting talk, and Tom had some that would interest him, he thought.', '汤姆从山洞里被救出来大约两周后，他去看哈克。哈克现在已经很强壮了，可以听一些刺激的事情了，汤姆觉得他有一些有趣的事情可以告诉他。'),
    (32, 1681, 4601, 'Judge Thatcher’s house was on Tom’s way, and he stopped to see Becky.', '撒切尔法官的家在汤姆回家的路上，他就停下来去看了贝琪。'),
    (32, 1681, 4602, 'The Judge and some friends set Tom to talking, and some one asked him ironically if he wouldn’t like to go to the cave again.', '法官和一些朋友让汤姆说话，有人开玩笑地问他，是不是还想再去山洞。'),
    (32, 1681, 4603, 'Tom said he thought he wouldn’t mind it.', '汤姆说他觉得他不会介意的。'),
    (32, 1681, 4604, 'The Judge said:', '法官说：'),
    (32, 1682, 4605, '“Well, there are others just like you, Tom, I’ve not the least doubt.', '“嗯，还有别人也和你一样，汤姆，我一点都不怀疑。'),
    (32, 1682, 4606, 'But we have taken care of that.', '不过我们已经处理好了这件事。'),
    (32, 1682, 4607, 'Nobody will get lost in that cave any more.”', '以后再也没有人会在那个山洞里迷路了。”'),
    (32, 1683, 4608, '“Why?”', '“为什么？”'),
    (32, 1684, 4609, '“Because I had its big door sheathed with boiler iron two weeks ago, and triple-locked—and I’ve got the keys.”', '“因为两周前，我让人把山洞的大门用厚厚的铁板包了起来，还上了三把锁——钥匙在我这里。”'),
    (32, 1685, 4610, 'Tom turned as white as a sheet.', '汤姆的脸一下子变得像纸一样白。'),
    (32, 1686, 4611, '“What’s the matter, boy!', '“怎么了，孩子！'),
    (32, 1686, 4612, 'Here, run, somebody!', '快，谁去！'),
    (32, 1686, 4613, 'Fetch a glass of water!”', '拿杯水来！”'),
    (32, 1687, 4614, 'The water was brought and thrown into Tom’s face.', '水被拿来了，泼到了汤姆的脸上。'),
    (32, 1688, 4615, '“Ah, now you’re all right.', '“啊，你现在没事了。'),
    (32, 1688, 4616, 'What was the matter with you, Tom?”', '汤姆，你刚才怎么了？”'),
    (32, 1689, 4617, '“Oh, Judge, Injun Joe’s in the cave!”', '“哦，法官，印第安·乔在山洞里！”'),
    (33, 1690, 4618, 'Within a few minutes the news had spread, and a dozen skiff-loads of men were on their way to McDougal’s cave, and the ferryboat, well filled with passengers, soon followed.', '几分钟之内，这个消息就传开了，几十艘小船上载着男人，正赶往麦克杜格尔山洞，一艘满载乘客的渡船也很快跟了上去。'),
    (33, 1690, 4619, 'Tom Sawyer was in the skiff that bore Judge Thatcher.', '汤姆·索亚就在载着撒切尔法官的那艘小船上。'),
    (33, 1691, 4620, 'When the cave door was unlocked, a sorrowful sight presented itself in the dim twilight of the place.', '山洞的门打开后，在昏暗的光线中，里面出现了一个让人伤心的景象。'),
    (33, 1691, 4621, 'Injun Joe lay stretched upon the ground, dead, with his face close to the crack of the door, as if his longing eyes had been fixed, to the latest moment, upon the light and the cheer of the free world outside.', '印第安·乔 躺在地上，他死了。他的脸贴着门缝，眼睛好像一直看着门外，想看看外面多亮、多开心。'),
    (33, 1691, 4622, 'Tom was touched, for he knew by his own experience how this wretch had suffered.', '汤姆 觉得很难过。因为他知道这个可怜人受了多少苦，他自己也尝过那种滋味。'),
    (33, 1691, 4623, 'His pity was moved, but nevertheless he felt an abounding sense of relief and security, now, which revealed to him in a degree which he had not fully appreciated before how vast a weight of dread had been lying upon him since the day he lifted his voice against this bloody-minded outcast.', '他很同情这个人。但同时，他又觉得轻松和安全了很多。他这才明白，自从他大声反对那个坏人以来，心里一直很害怕。'),
    (33, 1692, 4624, 'Injun Joe’s bowie-knife lay close by, its blade broken in two.', '印第安·乔 的大刀就在旁边，刀片断成了两半。'),
    (33, 1692, 4625, 'The great foundation-beam of the door had been chipped and hacked through, with tedious labor; useless labor, too, it was, for the native rock formed a sill outside it, and upon that stubborn material the knife had wrought no effect; the only damage done was to the knife itself.', '门下面的大木头被一点点凿开、砍开。他费了好大劲，可是没用。因为门外面有块大石头，刀子根本弄不动。结果，刀子反而弄坏了。'),
    (33, 1692, 4626, 'But if there had been no stony obstruction there the labor would have been useless still, for if the beam had been wholly cut away Injun Joe could not have squeezed his body under the door, and he knew it.', '就算没有那块石头，他这样做也没用。因为就算木头完全被砍掉了，印第安·乔 也挤不过门下面，他自己知道的。'),
    (33, 1692, 4627, 'So he had only hacked that place in order to be doing something—in order to pass the weary time—in order to employ his tortured faculties.', '所以他只是砍那里，就为了找点事做——为了打发无聊的时间——为了让痛苦的心情好受一点。'),
    (33, 1692, 4628, 'Ordinarily one could find half a dozen bits of candle stuck around in the crevices of this vestibule, left there by tourists; but there were none now.', '平时，这里（这个门口）的缝隙里能找到好几截蜡烛头，是游客们留下的。但现在，一截都没有了。'),
    (33, 1692, 4629, 'The prisoner had searched them out and eaten them.', '那个被关起来的人把它们都找出来吃掉了。'),
    (33, 1692, 4630, 'He had also contrived to catch a few bats, and these, also, he had eaten, leaving only their claws.', '他还想办法抓了几只蝙蝠，也把它们吃掉了，只剩下了爪子。'),
    (33, 1692, 4631, 'The poor unfortunate had starved to death.', '这个可怜的人饿死了。'),
    (33, 1692, 4632, 'In one place, near at hand, a stalagmite had been slowly growing up from the ground for ages, builded by the water-drip from a stalactite overhead.', '附近有个地方，一根石笋已经从地上慢慢长了几千年。它是上面滴下来的水一点点长成的。'),
    (33, 1692, 4633, 'The captive had broken off the stalagmite, and upon the stump had placed a stone, wherein he had scooped a shallow hollow to catch the precious drop that fell once in every three minutes with the dreary regularity of a clock-tick—a dessertspoonful once in four and twenty hours.', '那个被关起来的人把石笋弄断了。他在剩下的地方放了一块石头，还在石头上挖了个小坑，用来接水。每三分钟才滴一滴水，就像钟表一样准时。二十四个小时，才能接到一小勺水。'),
    (33, 1692, 4634, 'That drop was falling when the Pyramids were new; when Troy fell; when the foundations of Rome were laid; when Christ was crucified; when the Conqueror created the British empire; when Columbus sailed; when the massacre at Lexington was “news.”', '金字塔刚建好时，这滴水就在滴了；特洛伊城塌了时，它还在滴；罗马城刚开始建时，它还在滴；耶稣被钉住时，它还在滴；那个征服者建立了英国时，它还在滴；哥伦布航海时，它还在滴；莱克星顿发生大事时，它还在滴。'),
    (33, 1693, 4635, 'It is falling now; it will still be falling when all these things shall have sunk down the afternoon of history, and the twilight of tradition, and been swallowed up in the thick night of oblivion.', '现在它还在滴。等到所有这些事情都过去了，人们都忘了的时候，它还会一直滴。'),
    (33, 1693, 4636, 'Has everything a purpose and a mission?', '是不是每一样东西都有它要做的事呢？'),
    (33, 1693, 4637, 'Did this drop fall patiently during five thousand years to be ready for this flitting human insect’s need? and has it another important object to accomplish ten thousand years to come?', '这滴水滴了五千年，就是为了等这个人来接吗？它以后一万年，还有别的重要事要做吗？'),
    (33, 1693, 4638, 'No matter.', '算了，别管它了。'),
    (33, 1693, 4639, 'It is many and many a year since the hapless half-breed scooped out the stone to catch the priceless drops, but to this day the tourist stares longest at that pathetic stone and that slow-dropping water when he comes to see the wonders of McDougal’s cave.', '那个可怜的混血儿挖空石头来接这些水滴，已经过去好多年了。但是到现在，游客们来看麦克杜格尔洞穴时，还是会盯着那块石头和那些水滴看最久。'),
    (33, 1693, 4640, 'Injun Joe’s cup stands first in the list of the cavern’s marvels; even “Aladdin’s Palace” cannot rival it.', '印第安·乔 的杯子是洞里最棒的奇观，连“阿拉丁宫殿”都比不上它。'),
    (33, 1694, 4641, 'Injun Joe was buried near the mouth of the cave; and people flocked there in boats and wagons from the towns and from all the farms and hamlets for seven miles around; they brought their children, and all sorts of provisions, and confessed that they had had almost as satisfactory a time at the funeral as they could have had at the hanging.', '印第安·乔 被埋在洞口旁边。城里和附近村子里的人们都坐着船和马车来看。他们带着孩子，还带了好多吃的。他们说，来看这个葬礼，就和去看别的好玩的事情一样开心。'),
    (33, 1695, 4642, 'This funeral stopped the further growth of one thing—the petition to the governor for Injun Joe’s pardon.', '这场葬礼让一件事停了下来——人们不再给州长写信，求他放过印第安·乔 了。'),
    (33, 1695, 4643, 'The petition had been largely signed; many tearful and eloquent meetings had been held, and a committee of sappy women been appointed to go in deep mourning and wail around the governor, and implore him to be a merciful ass and trample his duty under foot.', '很多人在请愿书上签了名。大家还开了好几次会，很多人都哭了，说了好多话。还有一些爱哭的阿姨们被选出来，让她们穿着丧服去州长那里哭着求他，让他心软，不要按规矩办事。'),
    (33, 1695, 4644, 'Injun Joe was believed to have killed five citizens of the village, but what of that?', '大家觉得印第安·乔 杀了村里五个人，可是这又有什么关系呢？'),
    (33, 1695, 4645, 'If he had been Satan himself there would have been plenty of weaklings ready to scribble their names to a pardon-petition, and drip a tear on it from their permanently impaired and leaky water-works.', '就算他真是大魔鬼，也会有好多人愿意在求情信上写上自己的名字，还假装哭几滴眼泪在上面。'),
    (33, 1696, 4646, 'The morning after the funeral Tom took Huck to a private place to have an important talk.', '葬礼结束的第二天早上，汤姆 把哈克 带到一个没人的地方，想好好说说话。'),
    (33, 1696, 4647, 'Huck had learned all about Tom’s adventure from the Welshman and the Widow Douglas, by this time, but Tom said he reckoned there was one thing they had not told him; that thing was what he wanted to talk about now.', '这时候，哈克 已经从那个威尔士人和道格拉斯寡妇 那里，知道了汤姆 的所有冒险故事。但是汤姆 说，他觉得还有一件事他们没告诉他。他现在就想说说这件事。'),
    (33, 1696, 4648, 'Huck’s face saddened.', '哈克 的脸变得有点伤心。'),
    (33, 1696, 4649, 'He said:', '他说：'),
    (33, 1697, 4650, '“I know what it is.', '“我知道是什么事。”'),
    (33, 1697, 4651, 'You got into No. 2 and never found anything but whiskey.', '你去了2号，但只找到了酒。'),
    (33, 1697, 4652, 'Nobody told me it was you; but I just knowed it must ’a’ ben you, soon as I heard ’bout that whiskey business; and I knowed you hadn’t got the money becuz you’d ’a’ got at me some way or other and told me even if you was mum to everybody else.', '没人告诉我那是你，但我一听说是酒的事，就知道肯定是你了。我也知道你没拿到钱，要是你拿到了，你肯定会告诉我，哪怕对别人保密。'),
    (33, 1697, 4653, 'Tom, something’s always told me we’d never get holt of that swag.”', '汤姆，我总觉得我们永远也找不到那笔钱。'),
    (33, 1698, 4654, '“Why, Huck, I never told on that tavern-keeper.', '“哎呀，哈克，我可没告发那个开酒馆的。'),
    (33, 1698, 4655, '_You_ know his tavern was all right the Saturday I went to the picnic.', '你知道的，我那天去野餐，他那个酒馆好好的。'),
    (33, 1698, 4656, 'Don’t you remember you was to watch there that night?”', '你不记得那天晚上你要在那儿守着吗？”'),
    (33, 1699, 4657, '“Oh yes!', '“哦，是啊！'),
    (33, 1699, 4658, 'Why, it seems ’bout a year ago.', '哎，好像是一年前的事了。'),
    (33, 1699, 4659, 'It was that very night that I follered Injun Joe to the widder’s.”', '就是那天晚上，我跟着印第安·乔去了寡妇家。”'),
    (33, 1700, 4660, '“_You_ followed him?”', '“你跟着他？”'),
    (33, 1701, 4661, '“Yes—but you keep mum.', '“是的——但你要保密。'),
    (33, 1701, 4662, 'I reckon Injun Joe’s left friends behind him, and I don’t want ’em souring on me and doing me mean tricks.', '我猜印第安·乔还有朋友，我可不想他们生我的气，欺负我。'),
    (33, 1701, 4663, 'If it hadn’t ben for me he’d be down in Texas now, all right.”', '要不是我，他现在肯定还在德克萨斯州呢。”'),
    (33, 1702, 4664, 'Then Huck told his entire adventure in confidence to Tom, who had only heard of the Welshman’s part of it before.', '接着，哈克偷偷地把他的全部经历告诉了汤姆，之前汤姆只知道那个威尔士人的那部分。'),
    (33, 1703, 4665, '“Well,” said Huck, presently, coming back to the main question, “whoever nipped the whiskey in No. 2, nipped the money, too, I reckon—anyways it’s a goner for us, Tom.”', '“嗯，”哈克接着说，回到了主要的问题上，“我猜，谁拿走了2号房间的酒，谁就也拿走了钱——反正对我们来说，钱是没了，汤姆。”'),
    (33, 1704, 4666, '“Huck, that money wasn’t ever in No. 2!”', '“哈克，那笔钱根本就没在2号房间！”'),
    (33, 1705, 4667, '“What!”', '“什么！”'),
    (33, 1705, 4668, 'Huck searched his comrade’s face keenly.', '哈克仔细地看着他朋友的脸。'),
    (33, 1705, 4669, '“Tom, have you got on the track of that money again?”', '“汤姆，你是不是又找到那笔钱的线索了？”'),
    (33, 1706, 4670, '“Huck, it’s in the cave!”', '“哈克，钱在山洞里！”'),
    (33, 1707, 4671, 'Huck’s eyes blazed.', '哈克的眼睛亮了起来。'),
    (33, 1708, 4672, '“Say it again, Tom.”', '“再告诉我一遍，汤姆。”'),
    (33, 1709, 4673, '“The money’s in the cave!”', '“钱在山洞里！”'),
    (33, 1710, 4674, '“Tom—honest injun, now—is it fun, or earnest?”', '“汤姆——说真的，你是开玩笑，还是认真的？”'),
    (33, 1711, 4675, '“Earnest, Huck—just as earnest as ever I was in my life.', '“认真的，哈克——我这辈子从没这么认真过。'),
    (33, 1711, 4676, 'Will you go in there with me and help get it out?”', '你愿意跟我一起进去把钱拿出来吗？”'),
    (33, 1712, 4677, '“I bet I will!', '“我当然愿意！'),
    (33, 1712, 4678, 'I will if it’s where we can blaze our way to it and not get lost.”', '只要我们能做好记号，不迷路，我就去。”'),
    (33, 1713, 4679, '“Huck, we can do that without the least little bit of trouble in the world.”', '“哈克，我们能做到，一点儿麻烦都没有。”'),
    (33, 1714, 4680, '“Good as wheat!', '“太好了！”'),
    (33, 1714, 4681, 'What makes you think the money’s—”', '你为什么觉得钱会——'),
    (33, 1715, 4682, '“Huck, you just wait till we get in there.', '“哈克，你等我们进去就知道了。'),
    (33, 1715, 4683, 'If we don’t find it I’ll agree to give you my drum and every thing I’ve got in the world.', '要是我们找不到，我把我的鼓和所有东西都给你。'),
    (33, 1715, 4684, 'I will, by jings.”', '我真的会给你，真的！'),
    (33, 1716, 4685, '“All right—it’s a whiz.', '“好吧，这太棒了。'),
    (33, 1716, 4686, 'When do you say?”', '你说什么时候去？'),
    (33, 1717, 4687, '“Right now, if you say it.', '“就现在，如果你说去的话。'),
    (33, 1717, 4688, 'Are you strong enough?”', '你够强壮吗？'),
    (33, 1718, 4689, '“Is it far in the cave?', '“洞里面远吗？'),
    (33, 1718, 4690, 'I ben on my pins a little, three or four days, now, but I can’t walk more’n a mile, Tom—least I don’t think I could.”', '我走了三四天了，有点累，现在走不了超过一英里，汤姆——至少我觉得不行。'),
    (33, 1719, 4691, '“It’s about five mile into there the way anybody but me would go, Huck, but there’s a mighty short cut that they don’t anybody but me know about.', '“别人进去大概要走五英里，哈克，但我知道一条很近的近路，只有我知道。'),
    (33, 1719, 4692, 'Huck, I’ll take you right to it in a skiff.', '哈克，我会用小船直接带你去。'),
    (33, 1719, 4693, 'I’ll float the skiff down there, and I’ll pull it back again all by myself.', '我会把小船划过去，然后我自己再把它拉回来。'),
    (33, 1719, 4694, 'You needn’t ever turn your hand over.”', '你什么都不用做。'),
    (33, 1720, 4695, '“Less start right off, Tom.”', '“我们现在就出发吧，汤姆。”'),
    (33, 1721, 4696, '“All right.', '“好的。'),
    (33, 1721, 4697, 'We want some bread and meat, and our pipes, and a little bag or two, and two or three kite-strings, and some of these new-fangled things they call lucifer matches.', '我们要带些面包和肉，还有我们的烟斗，一两个小包，两三根风筝线，和一些他们叫火柴的新奇东西。'),
    (33, 1721, 4698, 'I tell you, many’s the time I wished I had some when I was in there before.”', '我告诉你，我以前在里面的时候，好多次都希望有这些东西。'),
    (33, 1722, 4699, 'A trifle after noon the boys borrowed a small skiff from a citizen who was absent, and got under way at once.', '刚过中午，孩子们从一个不在家的人那里借了一艘小船，马上就出发了。'),
    (33, 1722, 4700, 'When they were several miles below “Cave Hollow,” Tom said:', '当他们离“山洞谷”几英里远的时候，汤姆说：'),
    (33, 1723, 4701, '“Now you see this bluff here looks all alike all the way down from the cave hollow—no houses, no wood-yards, bushes all alike.', '“你看，从山洞谷下来，这边的峭壁都长得一样——没有房子，没有堆木头的地方，灌木丛也一样。'),
    (33, 1723, 4702, 'But do you see that white place up yonder where there’s been a landslide?', '但你看到那边有个白色的地方吗？那里发生过山体滑坡。'),
    (33, 1723, 4703, 'Well, that’s one of my marks.', '嗯，那就是我的一个标记。'),
    (33, 1723, 4704, 'We’ll get ashore, now.”', '我们现在靠岸吧。'),
    (33, 1724, 4705, 'They landed.', '他们上岸了。'),
    (33, 1725, 4706, '“Now, Huck, where we’re a-standing you could touch that hole I got out of with a fishing-pole.', '“现在，哈克，我们站的地方，用鱼竿就能碰到我爬出来的那个洞。'),
    (33, 1725, 4707, 'See if you can find it.”', '你看看能不能找到它。'),
    (33, 1726, 4708, 'Huck searched all the place about, and found nothing.', '哈克在周围找了找，什么也没找到。'),
    (33, 1726, 4709, 'Tom proudly marched into a thick clump of sumach bushes and said:', '汤姆得意地走进一片浓密的漆树丛，说：'),
    (33, 1727, 4710, '“Here you are!', '“就在这儿！'),
    (33, 1727, 4711, 'Look at it, Huck; it’s the snuggest hole in this country.', '看看，哈克，这是这个地方最舒服的洞了。'),
    (33, 1727, 4712, 'You just keep mum about it.', '你要保密哦。'),
    (33, 1727, 4713, 'All along I’ve been wanting to be a robber, but I knew I’d got to have a thing like this, and where to run across it was the bother.', '我一直想当强盗，可我知道得有这么个地方，找到它可不容易。'),
    (33, 1727, 4714, 'We’ve got it now, and we’ll keep it quiet, only we’ll let Joe Harper and Ben Rogers in—because of course there’s got to be a Gang, or else there wouldn’t be any style about it.', '我们现在有了，要保密。不过我们可以叫上乔·哈珀和本·罗杰斯，因为得有个“团伙”才行，不然就没意思了。'),
    (33, 1727, 4715, 'Tom Sawyer’s Gang—it sounds splendid, don’t it, Huck?”', '“汤姆·索亚的团伙”——听起来真棒，是不是啊，哈克？”'),
    (33, 1728, 4716, '“Well, it just does, Tom.', '“嗯，是啊，汤姆。'),
    (33, 1728, 4717, 'And who’ll we rob?”', '我们去抢谁呢？”'),
    (33, 1729, 4718, '“Oh, most anybody.', '“哦，随便什么人。'),
    (33, 1729, 4719, 'Waylay people—that’s mostly the way.”', '埋伏他们——大多是这样。”'),
    (33, 1730, 4720, '“And kill them?”', '“那要杀了他们吗？”'),
    (33, 1731, 4721, '“No, not always.', '“不，不总是。'),
    (33, 1731, 4722, 'Hive them in the cave till they raise a ransom.”', '把他们藏在山洞里，直到他们交赎金。”'),
    (33, 1732, 4723, '“What’s a ransom?”', '“什么是赎金？”'),
    (33, 1733, 4724, '“Money.', '“钱。'),
    (33, 1733, 4725, 'You make them raise all they can, off’n their friends; and after you’ve kept them a year, if it ain’t raised then you kill them.', '你让他们从朋友那儿弄到所有能弄到的钱；如果你把他们关了一年，还没弄到，那就杀了他们。'),
    (33, 1733, 4726, 'That’s the general way.', '一般都这样。'),
    (33, 1733, 4727, 'Only you don’t kill the women.', '不过女人不能杀。'),
    (33, 1733, 4728, 'You shut up the women, but you don’t kill them.', '你把女人关起来，但不能杀她们。'),
    (33, 1733, 4729, 'They’re always beautiful and rich, and awfully scared.', '她们总是又漂亮又有钱，而且特别害怕。'),
    (33, 1733, 4730, 'You take their watches and things, but you always take your hat off and talk polite.', '你拿走她们的手表和东西，但你总是要脱帽，说话要客气。'),
    (33, 1733, 4731, 'They ain’t anybody as polite as robbers—you’ll see that in any book.', '没有人比强盗更客气了——你会在任何书里看到。'),
    (33, 1733, 4732, 'Well, the women get to loving you, and after they’ve been in the cave a week or two weeks they stop crying and after that you couldn’t get them to leave.', '呃，女人们会爱上你，在山洞里待了一两周后，她们就不哭了，然后你再也赶不走她们了。'),
    (33, 1733, 4733, 'If you drove them out they’d turn right around and come back.', '如果你把她们赶出去，她们会立刻回来。'),
    (33, 1733, 4734, 'It’s so in all the books.”', '所有的书里都是这么写的。”'),
    (33, 1734, 4735, '“Why, it’s real bully, Tom.', '“哇，这真是太棒了，汤姆。'),
    (33, 1734, 4736, 'I believe it’s better’n to be a pirate.”', '我觉得这比当海盗还好玩。”'),
    (33, 1735, 4737, '“Yes, it’s better in some ways, because it’s close to home and circuses and all that.”', '“是啊，在某些方面是更好，因为它离家近，能看马戏团什么的。”'),
    (33, 1736, 4738, 'By this time everything was ready and the boys entered the hole, Tom in the lead.', '这时一切都准备好了，孩子们进了洞，汤姆走在最前面。'),
    (33, 1736, 4739, 'They toiled their way to the farther end of the tunnel, then made their spliced kite-strings fast and moved on.', '他们费力地走到隧道的尽头，然后系好接好的风筝线，继续往前走。'),
    (33, 1736, 4740, 'A few steps brought them to the spring, and Tom felt a shudder quiver all through him.', '走了几步，他们来到了泉水边，汤姆全身都颤抖起来。'),
    (33, 1736, 4741, 'He showed Huck the fragment of candle-wick perched on a lump of clay against the wall, and described how he and Becky had watched the flame struggle and expire.', '他给哈克看了一小截蜡烛芯，它粘在墙边一块泥土上。他还讲了自己和贝琪怎么看着火苗挣扎，然后灭了。'),
    (33, 1737, 4742, 'The boys began to quiet down to whispers, now, for the stillness and gloom of the place oppressed their spirits.', '男孩们现在小声说话了，因为这里又安静又黑，让他们心里不舒服。'),
    (33, 1737, 4743, 'They went on, and presently entered and followed Tom’s other corridor until they reached the “jumping-off place.”', '他们继续往前走，很快就进了汤姆的另一条走廊，一直走到那个“跳崖的地方”。'),
    (33, 1737, 4744, 'The candles revealed the fact that it was not really a precipice, but only a steep clay hill twenty or thirty feet high.', '蜡烛照亮后，他们发现那不是真的悬崖，只是一座二十或三十英尺高的陡峭泥土山。'),
    (33, 1737, 4745, 'Tom whispered:', '汤姆小声说：'),
    (33, 1738, 4746, '“Now I’ll show you something, Huck.”', '“现在我给哈克看个东西。”'),
    (33, 1739, 4747, 'He held his candle aloft and said:', '他把蜡烛举高，说：'),
    (33, 1740, 4748, '“Look as far around the corner as you can.', '“你往拐角那边，能看多远就看多远。”'),
    (33, 1740, 4749, 'Do you see that?', '“你看到那个了吗？”'),
    (33, 1740, 4750, 'There—on the big rock over yonder—done with candle-smoke.”', '“在那里——那边的大石头上——是用蜡烛烟熏出来的。”'),
    (33, 1741, 4751, '“Tom, it’s a _cross_!”', '“汤姆，那是个_十字架_！”'),
    (33, 1742, 4752, '“_Now_ where’s your Number Two?', '“_现在_你的二号在哪儿？”'),
    (33, 1742, 4753, '‘_under the cross_,’ hey?', '“‘_在十字架下面_’，是吗？”'),
    (33, 1742, 4754, 'Right yonder’s where I saw Injun Joe poke up his candle, Huck!”', '“就在那里，我看到印第安·乔把他的蜡烛举起来了，哈克！”'),
    (33, 1743, 4755, 'Huck stared at the mystic sign awhile, and then said with a shaky voice:', '哈克盯着那个神秘的记号看了一会儿，然后用颤抖的声音说：'),
    (33, 1744, 4756, '“Tom, less git out of here!”', '“汤姆，我们快离开这里吧！”'),
    (33, 1745, 4757, '“What! and leave the treasure?”', '“什么！把宝藏留下？”'),
    (33, 1746, 4758, '“Yes—leave it.', '“是的——留下它。”'),
    (33, 1746, 4759, 'Injun Joe’s ghost is round about there, certain.”', '“印第安·乔的鬼魂肯定就在那附近。”'),
    (33, 1747, 4760, '“No it ain’t, Huck, no it ain’t.', '“不，不是的，哈克，不是的。”'),
    (33, 1747, 4761, 'It would ha’nt the place where he died—away out at the mouth of the cave—five mile from here.”', '“它会缠着他死去的地方——在洞口外面——离这里五英里呢。”'),
    (33, 1748, 4762, '“No, Tom, it wouldn’t.', '“不，汤姆，它不会的。”'),
    (33, 1748, 4763, 'It would hang round the money.', '“它会围着钱转的。”'),
    (33, 1748, 4764, 'I know the ways of ghosts, and so do you.”', '“我知道鬼魂是怎么样的，你也知道的。”'),
    (33, 1749, 4765, 'Tom began to fear that Huck was right.', '汤姆开始害怕哈克说得对。'),
    (33, 1749, 4766, 'Misgivings gathered in his mind.', '他心里充满了疑虑。'),
    (33, 1749, 4767, 'But presently an idea occurred to him—', '但很快他想到了一个主意——'),
    (33, 1750, 4768, '“Lookyhere, Huck, what fools we’re making of ourselves!', '“看这里，哈克，我们真是太傻了！”'),
    (33, 1750, 4769, 'Injun Joe’s ghost ain’t a going to come around where there’s a cross!”', '“印第安·乔的鬼魂才不会来有十字架的地方呢！”'),
    (33, 1751, 4770, 'The point was well taken.', '这个理由很有道理。'),
    (33, 1751, 4771, 'It had its effect.', '它果然有用了。'),
    (33, 1752, 4772, '“Tom, I didn’t think of that.', '“汤姆，我没想到这个。'),
    (33, 1752, 4773, 'But that’s so.', '但就是这样！'),
    (33, 1752, 4774, 'It’s luck for us, that cross is.', '那个十字架真是我们的运气。'),
    (33, 1752, 4775, 'I reckon we’ll climb down there and have a hunt for that box.”', '我想我们下去那里找找那个箱子吧。”'),
    (33, 1753, 4776, 'Tom went first, cutting rude steps in the clay hill as he descended.', '汤姆先下去，他在泥土坡上踩出粗糙的台阶。'),
    (33, 1753, 4777, 'Huck followed.', '哈克跟着他。'),
    (33, 1753, 4778, 'Four avenues opened out of the small cavern which the great rock stood in.', '大石头旁边的小洞里，有四条路通向外面。'),
    (33, 1753, 4779, 'The boys examined three of them with no result.', '孩子们查了三条路，什么也没找到。'),
    (33, 1753, 4780, 'They found a small recess in the one nearest the base of the rock, with a pallet of blankets spread down in it; also an old suspender, some bacon rind, and the well-gnawed bones of two or three fowls.', '在离石头底部最近的那条路，他们发现了一个小凹进去的地方。里面铺着毯子，还有一条旧背带，一些培根皮，和两三只鸡被啃光了的骨头。'),
    (33, 1753, 4781, 'But there was no moneybox.', '但没有钱箱。'),
    (33, 1753, 4782, 'The lads searched and researched this place, but in vain.', '孩子们反复找了这个地方，但没用。'),
    (33, 1753, 4783, 'Tom said:', '汤姆说：'),
    (33, 1754, 4784, '“He said _under_ the cross.', '“他说在十字架下面。'),
    (33, 1754, 4785, 'Well, this comes nearest to being under the cross.', '嗯，这里离十字架下面最近了。'),
    (33, 1754, 4786, 'It can’t be under the rock itself, because that sets solid on the ground.”', '不可能在石头下面，因为它紧紧地贴着地面。”'),
    (33, 1755, 4787, 'They searched everywhere once more, and then sat down discouraged.', '他们又到处找了一遍，然后失望地坐了下来。'),
    (33, 1755, 4788, 'Huck could suggest nothing.', '哈克想不出任何办法。'),
    (33, 1755, 4789, 'By-and-by Tom said:', '过了一会儿，汤姆说：'),
    (33, 1756, 4790, '“Lookyhere, Huck, there’s footprints and some candle-grease on the clay about one side of this rock, but not on the other sides.', '“你看，哈克，这块石头的一边泥土上有脚印和一些蜡烛油，但其他几边没有。'),
    (33, 1756, 4791, 'Now, what’s that for?', '这是为什么呢？'),
    (33, 1756, 4792, 'I bet you the money _is_ under the rock.', '我敢打赌钱就在石头下面。'),
    (33, 1756, 4793, 'I’m going to dig in the clay.”', '我要挖一下泥土。”'),
    (33, 1757, 4794, '“That ain’t no bad notion, Tom!” said Huck with animation.', '“这个主意不错，汤姆！”哈克兴奋地说。'),
    (33, 1758, 4795, 'Tom’s “real Barlow” was out at once, and he had not dug four inches before he struck wood.', '汤姆立刻拿出他的“真巴洛小刀”，他还没挖四英寸就碰到了木头。'),
    (33, 1759, 4796, '“Hey, Huck!', '“嘿，哈克！'),
    (33, 1759, 4797, '—you hear that?”', '—你听到了吗？”'),
    (33, 1760, 4798, 'Huck began to dig and scratch now.', '哈克也开始挖和扒。'),
    (33, 1760, 4799, 'Some boards were soon uncovered and removed.', '很快，几块木板被挖开，拿走了。'),
    (33, 1760, 4800, 'They had concealed a natural chasm which led under the rock.', '它们藏着一条天然的裂缝，裂缝通向石头下面。'),
    (33, 1760, 4801, 'Tom got into this and held his candle as far under the rock as he could, but said he could not see to the end of the rift.', '汤姆 钻了进去，他把蜡烛伸到石头下面，尽量往深处照。他说：“我看不到这条缝的尽头。”'),
    (33, 1760, 4802, 'He proposed to explore.', '他想进去看看。'),
    (33, 1760, 4803, 'He stooped and passed under; the narrow way descended gradually.', '他弯腰钻了进去。这条窄窄的路，慢慢地往下走。'),
    (33, 1760, 4804, 'He followed its winding course, first to the right, then to the left, Huck at his heels.', '他跟着弯弯的路走，一会儿往右，一会儿往左。哈克 紧紧跟在他身后。'),
    (33, 1760, 4805, 'Tom turned a short curve, by-and-by, and exclaimed:', '过了一会儿，汤姆 转过了一个弯，大叫起来：'),
    (33, 1761, 4806, '“My goodness, Huck, lookyhere!”', '“天哪，哈克，快看！”'),
    (33, 1762, 4807, 'It was the treasure-box, sure enough, occupying a snug little cavern, along with an empty powder-keg, a couple of guns in leather cases, two or three pairs of old moccasins, a leather belt, and some other rubbish well soaked with the water-drip.', '果然是宝箱！它在一个舒服的小洞里，旁边还有个空火药桶、两把装在皮套里的枪、几双旧鞋子、一条皮带，还有一些被水滴弄湿的旧东西。'),
    (33, 1763, 4808, '“Got it at last!” said Huck, ploughing among the tarnished coins with his hand. “My, but we’re rich, Tom!”', '“我们终于找到了！”哈克 用手拨弄着那些旧旧的硬币。他大声说：“哇，汤姆，我们发大财了！”'),
    (33, 1764, 4809, '“Huck, I always reckoned we’d get it.', '“哈克，我一直都觉得我们能找到它。'),
    (33, 1764, 4810, 'It’s just too good to believe, but we _have_ got it, sure!', '这太好了，好得我都不敢相信了，但我们真的找到了！'),
    (33, 1764, 4811, 'Say—let’s not fool around here.', '喂——我们别在这里玩了。'),
    (33, 1764, 4812, 'Let’s snake it out.', '我们把它弄出去吧。'),
    (33, 1764, 4813, 'Lemme see if I can lift the box.”', '我来试试能不能把箱子抬起来。”'),
    (33, 1765, 4814, 'It weighed about fifty pounds.', '它大约有五十磅重。'),
    (33, 1765, 4815, 'Tom could lift it, after an awkward fashion, but could not carry it conveniently.', '汤姆 可以笨手笨脚地把它抬起来，但不太好搬走。'),
    (33, 1766, 4816, '“I thought so,” he said; “_They_ carried it like it was heavy, that day at the ha’nted house.', '“我就知道是这样。”他说：“那天在鬼屋里，_他们_搬的时候，这个箱子就很重。”'),
    (33, 1766, 4817, 'I noticed that.', '我注意到了。'),
    (33, 1766, 4818, 'I reckon I was right to think of fetching the little bags along.”', '看来我带着这些小袋子是对的。”'),
    (33, 1767, 4819, 'The money was soon in the bags and the boys took it up to the cross rock.', '钱很快就装进了袋子，他们把钱带到了那块交叉的石头那里。'),
    (33, 1768, 4820, '“Now less fetch the guns and things,” said Huck.', '“现在我们去把枪和那些东西拿过来吧。”哈克 说。'),
    (33, 1769, 4821, '“No, Huck—leave them there.', '“不，哈克——把它们留在那里。'),
    (33, 1769, 4822, 'They’re just the tricks to have when we go to robbing.', '我们去抢东西的时候，它们可正好派上用场。'),
    (33, 1769, 4823, 'We’ll keep them there all the time, and we’ll hold our orgies there, too.', '我们一直把它们放在那儿，我们也要在那儿开派对。'),
    (33, 1769, 4824, 'It’s an awful snug place for orgies.”', '那是个开派对的好地方。”'),
    (33, 1770, 4825, '“What orgies?”', '“什么派对？”'),
    (33, 1771, 4826, '“I dono.', '“我不知道呀。'),
    (33, 1771, 4827, 'But robbers always have orgies, and of course we’ve got to have them, too.', '但是坏蛋们总会开派对的，我们当然也要开呀。'),
    (33, 1771, 4828, 'Come along, Huck, we’ve been in here a long time.', '快走吧，哈克，我们在这里待了好久了。'),
    (33, 1771, 4829, 'It’s getting late, I reckon.', '我想，天快黑了。'),
    (33, 1771, 4830, 'I’m hungry, too.', '我也饿了。'),
    (33, 1771, 4831, 'We’ll eat and smoke when we get to the skiff.”', '我们到了小船那儿，就可以吃东西了。'),
    (33, 1772, 4832, 'They presently emerged into the clump of sumach bushes, looked warily out, found the coast clear, and were soon lunching and smoking in the skiff.', '他们很快从漆树丛里出来，小心地往外瞧了瞧，没人！他们就赶紧跑到小船上，吃午饭，还抽了烟。'),
    (33, 1772, 4833, 'As the sun dipped toward the horizon they pushed out and got under way.', '太阳快要下山了，他们就划着小船走了。'),
    (33, 1772, 4834, 'Tom skimmed up the shore through the long twilight, chatting cheerily with Huck, and landed shortly after dark.', '汤姆和哈克在傍晚时分沿着岸边走，开心地聊天。天一黑，他们就上岸了。'),
    (33, 1773, 4835, '“Now, Huck,” said Tom, “we’ll hide the money in the loft of the widow’s woodshed, and I’ll come up in the morning and we’ll count it and divide, and then we’ll hunt up a place out in the woods for it where it will be safe.', '“好了，哈克，”汤姆说，“我们把钱藏在寡妇家柴棚的楼上。明天早上我过来，我们把钱数清楚，然后分好。再到树林里找个安全的地方藏起来。'),
    (33, 1773, 4836, 'Just you lay quiet here and watch the stuff till I run and hook Benny Taylor’s little wagon; I won’t be gone a minute.”', '你就安静地在这儿，看着这些东西，我去借一下本尼·泰勒的小推车。我很快就回来，一分钟都不耽误！”'),
    (33, 1774, 4837, 'He disappeared, and presently returned with the wagon, put the two small sacks into it, threw some old rags on top of them, and started off, dragging his cargo behind him.', '他走了，一会儿就推着小推车回来了。他把两个小袋子放进车里，上面盖了些旧布，然后拉着小推车走了。'),
    (33, 1774, 4838, 'When the boys reached the Welshman’s house, they stopped to rest.', '孩子们走到威尔士叔叔家时，停下来歇了歇。'),
    (33, 1774, 4839, 'Just as they were about to move on, the Welshman stepped out and said:', '他们刚要继续走，威尔士叔叔就走了出来，说：'),
    (33, 1775, 4840, '“Hallo, who’s that?”', '“喂，是谁啊？”'),
    (33, 1776, 4841, '“Huck and Tom Sawyer.”', '“是哈克和汤姆·索亚。”'),
    (33, 1777, 4842, '“Good!', '“好啊！'),
    (33, 1777, 4843, 'Come along with me, boys, you are keeping everybody waiting.', '跟我来吧，孩子们，大家都在等你们呢。'),
    (33, 1777, 4844, 'Here—hurry up, trot ahead—I’ll haul the wagon for you.', '快点——跑前面去——我帮你拉车。'),
    (33, 1777, 4845, 'Why, it’s not as light as it might be.', '哎呀，这车可不轻呀。'),
    (33, 1777, 4846, 'Got bricks in it?', '里面装的是砖头吗？'),
    (33, 1777, 4847, '—or old metal?”', '还是旧金属？”'),
    (33, 1778, 4848, '“Old metal,” said Tom.', '“旧金属，”汤姆说。'),
    (33, 1779, 4849, '“I judged so; the boys in this town will take more trouble and fool away more time hunting up six bits’ worth of old iron to sell to the foundry than they would to make twice the money at regular work.', '“我就猜是这样！这镇上的男孩子们啊，宁愿花很多力气和时间去找一点点旧铁去卖钱，也不愿好好工作去挣更多的钱。'),
    (33, 1779, 4850, 'But that’s human nature—hurry along, hurry along!”', '但人就是这样嘛——快走吧，快走吧！”'),
    (33, 1780, 4851, 'The boys wanted to know what the hurry was about.', '孩子们想知道为什么这么着急。'),
    (33, 1781, 4852, '“Never mind; you’ll see, when we get to the Widow Douglas’.”', '“没关系，到了道格拉斯寡妇’那里你们就知道了。”'),
    (33, 1782, 4853, 'Huck said with some apprehension—for he was long used to being falsely accused:', '哈克有点担心地说，因为他老是被冤枉：'),
    (33, 1783, 4854, '“Mr. Jones, we haven’t been doing nothing.”', '“琼斯先生，我们什么都没做。”'),
    (33, 1784, 4855, 'The Welshman laughed.', '威尔士叔叔笑了。'),
    (33, 1785, 4856, '“Well, I don’t know, Huck, my boy.', '“嗯，哈克，我的孩子，我不知道。'),
    (33, 1785, 4857, 'I don’t know about that.', '这事儿我可不知道。'),
    (33, 1785, 4858, 'Ain’t you and the widow good friends?”', '你不是和那位寡妇阿姨是好朋友吗？”'),
    (33, 1786, 4859, '“Yes.', '“是的。'),
    (33, 1786, 4860, 'Well, she’s ben good friends to me, anyway.”', '嗯，反正她一直对我都很好。”'),
    (33, 1787, 4861, '“All right, then.', '“好吧，那。'),
    (33, 1787, 4862, 'What do you want to be afraid for?”', '你为什么要害怕呢？”'),
    (33, 1788, 4863, 'This question was not entirely answered in Huck’s slow mind before he found himself pushed, along with Tom, into Mrs. Douglas’ drawing-room.', '哈克还没完全想明白这个问题，他就和汤姆一起被推进了道格拉斯太太的客厅。'),
    (33, 1788, 4864, 'Mr. Jones left the wagon near the door and followed.', '琼斯先生把车停在门口，也跟着进去了。'),
    (33, 1789, 4865, 'The place was grandly lighted, and everybody that was of any consequence in the village was there.', '屋子里灯很亮，村里重要的人都来了。'),
    (33, 1789, 4866, 'The Thatchers were there, the Harpers, the Rogerses, Aunt Polly, Sid, Mary, the minister, the editor, and a great many more, and all dressed in their best.', '撒切尔一家、哈珀一家、罗杰斯一家、波莉姨妈、希德、玛丽、牧师、编辑，还有好多好多人都在那里，大家都穿着最好的衣服。'),
    (33, 1789, 4867, 'The widow received the boys as heartily as any one could well receive two such looking beings.', '寡妇非常热情地招待了两个男孩，就像她会招待所有客人一样。'),
    (33, 1789, 4868, 'They were covered with clay and candle-grease.', '他们身上沾满了泥巴和蜡油。'),
    (33, 1789, 4869, 'Aunt Polly blushed crimson with humiliation, and frowned and shook her head at Tom.', '波莉姨妈觉得很丢脸，脸都红了，还皱着眉冲汤姆摇头。'),
    (33, 1789, 4870, 'Nobody suffered half as much as the two boys did, however.', '不过，没人比这两个男孩更难受了。'),
    (33, 1789, 4871, 'Mr. Jones said:', '琼斯先生说：'),
    (33, 1790, 4872, '“Tom wasn’t at home, yet, so I gave him up; but I stumbled on him and Huck right at my door, and so I just brought them along in a hurry.”', '“汤姆还没回家，我本来想放弃了；可我在我家门口碰到了他和哈克，所以我就赶紧把他们带来了。”'),
    (33, 1791, 4873, '“And you did just right,” said the widow.', '“你做得太对了！”寡妇说。'),
    (33, 1791, 4874, '“Come with me, boys.”', '“跟我来，孩子们。”'),
    (33, 1792, 4875, 'She took them to a bedchamber and said:', '她把他们带到一个卧室，说：'),
    (33, 1793, 4876, '“Now wash and dress yourselves.', '“现在，洗洗澡，穿上衣服吧。'),
    (33, 1793, 4877, 'Here are two new suits of clothes—shirts, socks, everything complete.', '这里有两套新衣服——衬衫、袜子，什么都有，很齐全。'),
    (33, 1793, 4878, 'They’re Huck’s—no, no thanks, Huck—Mr. Jones bought one and I the other.', '这些是哈克的——哦，不用谢，哈克——琼斯先生买了一套，我买了另一套。'),
    (33, 1793, 4879, 'But they’ll fit both of you.', '不过，它们俩都适合你们。'),
    (33, 1793, 4880, 'Get into them.', '快穿上吧。'),
    (33, 1793, 4881, 'We’ll wait—come down when you are slicked up enough.”', '我们会在外面等——等你们收拾好了就下来吧。”'),
    (33, 1794, 4882, 'Then she left.', '然后她就走了。'),
    (34, 1795, 4883, 'Huck said: “Tom, we can slope, if we can find a rope.', '哈克说：“汤姆，要是我们能找到绳子，就能溜走了。窗户离地面不远。”'),
    (34, 1795, 4884, 'The window ain’t high from the ground.”', '窗户离地面不高。'),
    (34, 1796, 4885, '“Shucks! what do you want to slope for?”', '“哎呀！你为什么要溜走啊？”'),
    (34, 1797, 4886, '“Well, I ain’t used to that kind of a crowd.', '“嗯，我不习惯那么多人。'),
    (34, 1797, 4887, 'I can’t stand it.', '我受不了。'),
    (34, 1797, 4888, 'I ain’t going down there, Tom.”', '我不会去那里的，汤姆。”'),
    (34, 1798, 4889, '“Oh, bother!', '“哎呀，真麻烦！'),
    (34, 1798, 4890, 'It ain’t anything.', '没什么大不了的。'),
    (34, 1798, 4891, 'I don’t mind it a bit.', '我一点都不介意。'),
    (34, 1798, 4892, 'I’ll take care of you.”', '我会照顾你的。”'),
    (34, 1799, 4893, 'Sid appeared.', '希德 出现了。'),
    (34, 1800, 4894, '“Tom,” said he, “auntie has been waiting for you all the afternoon.', '“汤姆，”他说，“阿姨下午一直在等你呢。'),
    (34, 1800, 4895, 'Mary got your Sunday clothes ready, and everybody’s been fretting about you.', '玛丽 把你星期天穿的衣服都准备好了，大家都在为你着急呢。'),
    (34, 1800, 4896, 'Say—ain’t this grease and clay, on your clothes?”', '喂——你衣服上是不是有油泥和黏土啊？”'),
    (34, 1801, 4897, '“Now, Mr. Siddy, you jist ’tend to your own business.', '“哎，西迪先生，你管好你自己的事就行了。'),
    (34, 1801, 4898, 'What’s all this blowout about, anyway?”', '这到底是怎么回事啊？”'),
    (34, 1802, 4899, '“It’s one of the widow’s parties that she’s always having.', '“这是寡妇经常办的那种派对。'),
    (34, 1802, 4900, 'This time it’s for the Welshman and his sons, on account of that scrape they helped her out of the other night.', '这次是为了感谢那个威尔士人和他的儿子们，因为他们前几天晚上帮了她一个大忙。'),
    (34, 1802, 4901, 'And say—I can tell you something, if you want to know.”', '喂——如果你想知道，我可以告诉你一个秘密哦。”'),
    (34, 1803, 4902, '“Well, what?”', '“嗯，什么事？”'),
    (34, 1804, 4903, '“Why, old Mr. Jones is going to try to spring something on the people here tonight, but I overheard him tell auntie today about it, as a secret, but I reckon it’s not much of a secret now.', '“哦，琼斯老先生今晚想给大家一个惊喜，但我今天偷听到他跟阿姨说，这是个秘密，可我觉得现在这已经不是什么秘密了。'),
    (34, 1804, 4904, 'Everybody knows—the widow, too, for all she tries to let on she don’t.', '大家都知道了——连寡妇也知道了，虽然她假装不知道。'),
    (34, 1804, 4905, 'Mr. Jones was bound Huck should be here—couldn’t get along with his grand secret without Huck, you know!”', '琼斯先生非要 哈克 在场——没有 哈克，他的大秘密就没法进行下去，你知道的！”'),
    (34, 1805, 4906, '“Secret about what, Sid?”', '“什么秘密啊，希德？”'),
    (34, 1806, 4907, '“About Huck tracking the robbers to the widow’s.', '“就是 哈克 跟着那些强盗到了寡妇家这件事。'),
    (34, 1806, 4908, 'I reckon Mr. Jones was going to make a grand time over his surprise, but I bet you it will drop pretty flat.”', '我猜琼斯先生本来想让他的惊喜很轰动，但我敢打赌，那肯定会变得一点也不好玩。”'),
    (34, 1807, 4909, 'Sid chuckled in a very contented and satisfied way.', '希德 心满意足地笑了笑。'),
    (34, 1808, 4910, '“Sid, was it you that told?”', '“希德，是你告诉的吗？”'),
    (34, 1809, 4911, '“Oh, never mind who it was.', '“哎呀，别管是谁说的了。'),
    (34, 1809, 4912, '_Somebody_ told—that’s enough.”', '有人 告诉了——这就够了。”'),
    (34, 1810, 4913, '“Sid, there’s only one person in this town mean enough to do that, and that’s you.', '“希德，这个镇上只有一个人会做那么坏的事，那就是你。'),
    (34, 1810, 4914, 'If you had been in Huck’s place you’d ’a’ sneaked down the hill and never told anybody on the robbers.', '如果你处在 哈克 的位置，你肯定会偷偷溜下山，然后一个字也不告诉别人关于那些强盗的事。'),
    (34, 1810, 4915, 'You can’t do any but mean things, and you can’t bear to see anybody praised for doing good ones.', '你只会做坏事，而且你见不得别人因为做好事而受到表扬。'),
    (34, 1810, 4916, 'There—no thanks, as the widow says”—and Tom cuffed Sid’s ears and helped him to the door with several kicks.', '好了——不用谢了，就像寡妇说的。”——然后 汤姆 掴了 希德 的耳朵几下，又踢了他几脚，把他赶到了门口。'),
    (34, 1810, 4917, '“Now go and tell auntie if you dare—and tomorrow you’ll catch it!”', '“现在你敢去告诉阿姨，明天你就惨了！”'),
    (34, 1811, 4918, 'Some minutes later the widow’s guests were at the supper-table, and a dozen children were propped up at little side-tables in the same room, after the fashion of that country and that day.', '几分钟后，寡妇家的客人们都坐在了餐桌旁，十几个孩子则像当时那个地方的习俗一样，在同一个房间里的小边桌旁坐着。'),
    (34, 1811, 4919, 'At the proper time Mr. Jones made his little speech, in which he thanked the widow for the honor she was doing himself and his sons, but said that there was another person whose modesty—', '到了合适的时候，琼斯先生发表了一个简短的讲话，他感谢寡妇给他和他的儿子们带来的荣誉，但他说还有另一个人，他的谦虚——'),
    (34, 1812, 4920, 'And so forth and so on.', '等等，等等。'),
    (34, 1812, 4921, 'He sprung his secret about Huck’s share in the adventure in the finest dramatic manner he was master of, but the surprise it occasioned was largely counterfeit and not as clamorous and effusive as it might have been under happier circumstances.', '他用最棒的办法，告诉了大家一个秘密，说哈克也参与了那场冒险。大家假装很惊讶，但其实没那么高兴。'),
    (34, 1812, 4922, 'However, the widow made a pretty fair show of astonishment, and heaped so many compliments and so much gratitude upon Huck that he almost forgot the nearly intolerable discomfort of his new clothes in the entirely intolerable discomfort of being set up as a target for everybody’s gaze and everybody’s laudations.', '不过，寡妇表现得很惊讶，还夸了哈克好多，非常感谢他。哈克觉得被大家盯着看、被夸奖比穿新衣服还不舒服。'),
    (34, 1813, 4923, 'The widow said she meant to give Huck a home under her roof and have him educated; and that when she could spare the money she would start him in business in a modest way.', '寡妇说她想让哈克住在她家，送他去读书。等她有钱了，还会帮他开个小店。'),
    (34, 1813, 4924, 'Tom’s chance was come.', '汤姆的机会来了。'),
    (34, 1813, 4925, 'He said:', '他说：'),
    (34, 1814, 4926, '“Huck don’t need it.', '“哈克不需要。'),
    (34, 1814, 4927, 'Huck’s rich.”', '哈克很有钱。”'),
    (34, 1815, 4928, 'Nothing but a heavy strain upon the good manners of the company kept back the due and proper complimentary laugh at this pleasant joke.', '大家很想笑这个有趣的玩笑，但为了礼貌，都忍住了没笑。'),
    (34, 1815, 4929, 'But the silence was a little awkward.', '但屋子里有点安静，怪怪的。'),
    (34, 1815, 4930, 'Tom broke it:', '汤姆打破了这份安静：'),
    (34, 1816, 4931, '“Huck’s got money.', '“哈克有钱。'),
    (34, 1816, 4932, 'Maybe you don’t believe it, but he’s got lots of it.', '也许你们不相信，但他真的有很多钱。'),
    (34, 1816, 4933, 'Oh, you needn’t smile—I reckon I can show you.', '噢，你们别笑——我想我可以给你们看。'),
    (34, 1816, 4934, 'You just wait a minute.”', '你们等等。”'),
    (34, 1817, 4935, 'Tom ran out of doors.', '汤姆跑出门去了。'),
    (34, 1817, 4936, 'The company looked at each other with a perplexed interest—and inquiringly at Huck, who was tongue-tied.', '大家你看看我，我看看你，都很好奇，又都看着不知道说什么的哈克。'),
    (34, 1818, 4937, '“Sid, what ails Tom?” said Aunt Polly.', '“希德，汤姆怎么了？”波莉姨妈问。'),
    (34, 1818, 4938, '“He—well, there ain’t ever any making of that boy out.', '“他——哎，这个孩子真是让人摸不透。'),
    (34, 1818, 4939, 'I never—”', '我从没——”'),
    (34, 1819, 4940, 'Tom entered, struggling with the weight of his sacks, and Aunt Polly did not finish her sentence.', '汤姆进来了，他吃力地背着几个袋子。波莉姨妈没有说完她的话。'),
    (34, 1819, 4941, 'Tom poured the mass of yellow coin upon the table and said:', '汤姆把一大堆黄色的金币倒在桌子上，说：'),
    (34, 1820, 4942, '“There—what did I tell you?', '“看——我说了什么？'),
    (34, 1820, 4943, 'Half of it’s Huck’s and half of it’s mine!”', '一半是哈克的，一半是我的！”'),
    (34, 1821, 4944, 'The spectacle took the general breath away.', '眼前这一幕让大家都很吃惊。'),
    (34, 1821, 4945, 'All gazed, nobody spoke for a moment.', '大家盯着看，一时都没说话。'),
    (34, 1821, 4946, 'Then there was a unanimous call for an explanation.', '接着，大家异口同声地要他解释。'),
    (34, 1821, 4947, 'Tom said he could furnish it, and he did.', '汤姆说他可以解释，然后他就解释了。'),
    (34, 1821, 4948, 'The tale was long, but brimful of interest.', '故事很长，但特别有趣。'),
    (34, 1821, 4949, 'There was scarcely an interruption from any one to break the charm of its flow.', '几乎没有人打断他，故事讲得太吸引人了。'),
    (34, 1821, 4950, 'When he had finished, Mr. Jones said:', '他讲完后，琼斯先生说：'),
    (34, 1822, 4951, '“I thought I had fixed up a little surprise for this occasion, but it don’t amount to anything now.', '“我本想给大家一个小惊喜，但现在看来，这算不上什么了。'),
    (34, 1822, 4952, 'This one makes it sing mighty small, I’m willing to allow.”', '“和这个比起来，我的惊喜简直微不足道，我承认。”'),
    (34, 1823, 4953, 'The money was counted.', '钱被数完了。'),
    (34, 1823, 4954, 'The sum amounted to a little over twelve thousand dollars.', '总共有超过一万两千美元。'),
    (34, 1823, 4955, 'It was more than any one present had ever seen at one time before, though several persons were there who were worth considerably more than that in property.', '这是在场所有人一次性见过最多钱。虽然有些人财产更多，但他们也没见过这么多现金。'),
    (35, 1824, 4956, 'The reader may rest satisfied that Tom’s and Huck’s windfall made a mighty stir in the poor little village of St. Petersburg.', '你们要知道，汤姆和哈克突然得了这么多钱，让圣彼得斯堡这个小村子热闹极了。'),
    (35, 1824, 4957, 'So vast a sum, all in actual cash, seemed next to incredible.', '这么多现金，简直让人不敢相信。'),
    (35, 1824, 4958, 'It was talked about, gloated over, glorified, until the reason of many of the citizens tottered under the strain of the unhealthy excitement.', '大家都在谈论它，炫耀它，把它说得神乎其神，很多人兴奋得都快失去理智了。'),
    (35, 1824, 4959, 'Every “haunted” house in St. Petersburg and the neighboring villages was dissected, plank by plank, and its foundations dug up and ransacked for hidden treasure—and not by boys, but men—pretty grave, unromantic men, too, some of them.', '圣彼得斯堡和附近村子的所有“鬼屋”都被拆开，一块木板一块木板地检查。地基也被挖开，到处找藏起来的宝藏——不是小孩子做的，而是大人，有些还是很严肃、不爱幻想的大人。'),
    (35, 1824, 4960, 'Wherever Tom and Huck appeared they were courted, admired, stared at.', '汤姆和哈克走到哪里，大家就都想和他们亲近，羡慕他们，盯着他们看。'),
    (35, 1824, 4961, 'The boys were not able to remember that their remarks had possessed weight before; but now their sayings were treasured and repeated; everything they did seemed somehow to be regarded as remarkable; they had evidently lost the power of doing and saying commonplace things; moreover, their past history was raked up and discovered to bear marks of conspicuous originality.', '孩子们都不记得以前说过的话有人听。但现在，他们说的话都被当成宝贝，反复传颂。他们做的每件事都变得很特别。他们好像都不会做或说普通的事了。甚至他们以前的事也被挖出来，发现他们从小就很不一般。'),
    (35, 1824, 4962, 'The village paper published biographical sketches of the boys.', '村里的报纸还写了关于这些孩子的故事。'),
    (35, 1825, 4963, 'The Widow Douglas put Huck’s money out at six per cent.', '道格拉斯寡妇把哈克的钱拿去投资，每年有百分之六的利息。'),
    (35, 1825, 4964, ', and Judge Thatcher did the same with Tom’s at Aunt Polly’s request.', '并且，应波莉姨妈的要求，撒切尔法官也把汤姆的钱照样投资了。'),
    (35, 1825, 4965, 'Each lad had an income, now, that was simply prodigious—a dollar for every weekday in the year and half of the Sundays.', '两个孩子现在都有一大笔收入了——一年里每个工作日都有一美元，星期天也能拿到一半的钱。'),
    (35, 1825, 4966, 'It was just what the minister got—no, it was what he was promised—he generally couldn’t collect it.', '这和牧师挣得一样多——不，是牧师被承诺的那么多——但他通常都收不到。'),
    (35, 1825, 4967, 'A dollar and a quarter a week would board, lodge, and school a boy in those old simple days—and clothe him and wash him, too, for that matter.', '在过去那些简单的日子里，一周一美元零二十五美分，就够一个孩子吃住、上学了——甚至连衣服和洗澡的钱都够了。'),
    (35, 1826, 4968, 'Judge Thatcher had conceived a great opinion of Tom.', '撒切尔法官对汤姆评价很高。'),
    (35, 1826, 4969, 'He said that no commonplace boy would ever have got his daughter out of the cave.', '他说，一个普通的孩子是绝对不可能把他的女儿从山洞里救出来的。'),
    (35, 1826, 4970, 'When Becky told her father, in strict confidence, how Tom had taken her whipping at school, the Judge was visibly moved; and when she pleaded grace for the mighty lie which Tom had told in order to shift that whipping from her shoulders to his own, the Judge said with a fine outburst that it was a noble, a generous, a magnanimous lie—a lie that was worthy to hold up its head and march down through history breast to breast with George Washington’s lauded Truth about the hatchet!', '当贝琪悄悄告诉爸爸，汤姆如何在学校替她挨打时，法官非常感动。当她请求爸爸原谅汤姆为了替她挨打而说的那个大谎话时，法官激动地大声说，那是一个多么高尚、多么大方、多么了不起的谎话啊——这个谎话值得昂首挺胸地载入史册，和乔治·华盛顿关于斧头的故事一样有名！'),
    (35, 1826, 4971, 'Becky thought her father had never looked so tall and so superb as when he walked the floor and stamped his foot and said that.', '贝琪觉得爸爸从来没有像这样高大威武过，当他踱步、跺脚说出那些话的时候。'),
    (35, 1826, 4972, 'She went straight off and told Tom about it.', '她立刻跑去告诉了汤姆。'),
    (35, 1827, 4973, 'Judge Thatcher hoped to see Tom a great lawyer or a great soldier some day.', '撒切尔法官希望汤姆将来能成为一名大律师或一名大将军。'),
    (35, 1827, 4974, 'He said he meant to look to it that Tom should be admitted to the National Military Academy and afterward trained in the best law school in the country, in order that he might be ready for either career or both.', '他说他会确保让汤姆进入国家军事学院，然后去全国最好的法学院学习，这样他就可以选择做军人、律师，或者两者都做。'),
    (35, 1828, 4975, 'Huck Finn’s wealth and the fact that he was now under the Widow Douglas’ protection introduced him into society—no, dragged him into it, hurled him into it—and his sufferings were almost more than he could bear.', '芬恩哈克有钱了，而且现在又有道格拉斯寡妇的保护，这让他不得不进入“上流社会”——不，是被人硬拉进去，硬推进去——他痛苦得都快受不了了。'),
    (35, 1828, 4976, 'The widow’s servants kept him clean and neat, combed and brushed, and they bedded him nightly in unsympathetic sheets that had not one little spot or stain which he could press to his heart and know for a friend.', '寡妇家的仆人把他洗得干干净净，头发梳得整整齐齐。晚上，他们让他睡在没有一点点污渍的干净床单上，他觉得这些床单一点也不亲切，没有一处能让他感到熟悉和安慰。'),
    (35, 1828, 4977, 'He had to eat with a knife and fork; he had to use napkin, cup, and plate; he had to learn his book, he had to go to church; he had to talk so properly that speech was become insipid in his mouth; whithersoever he turned, the bars and shackles of civilization shut him in and bound him hand and foot.', '他必须用刀叉吃饭；必须用手帕、杯子和盘子；必须学习课本，必须去教堂；他说话必须非常得体，以至于在他嘴里，说话都变得索然无味了；无论他走到哪里，文明的规矩都像枷锁一样把他牢牢地困住，让他动弹不得。'),
    (35, 1829, 4978, 'He bravely bore his miseries three weeks, and then one day turned up missing.', '他勇敢地忍受了三个星期的痛苦，然后有一天，他不见了。'),
    (35, 1829, 4979, 'For forty-eight hours the widow hunted for him everywhere in great distress.', '整整四十八小时，寡妇到处找他，非常着急。'),
    (35, 1829, 4980, 'The public were profoundly concerned; they searched high and low, they dragged the river for his body.', '大家都很担心；他们到处寻找，甚至还打捞了河里，想找到他的尸体。'),
    (35, 1829, 4981, 'Early the third morning Tom Sawyer wisely went poking among some old empty hogsheads down behind the abandoned slaughter-house, and in one of them he found the refugee.', '第三天早上很早，汤姆·索亚很聪明，他去废弃屠宰场后面那些空木桶里找。在一个木桶里，他找到了那个躲起来的人。'),
    (35, 1829, 4982, 'Huck had slept there; he had just breakfasted upon some stolen odds and ends of food, and was lying off, now, in comfort, with his pipe.', '哈克睡在那儿。他刚刚吃了些偷来的零碎食物当早餐。现在他舒服地躺着，抽着烟。'),
    (35, 1829, 4983, 'He was unkempt, uncombed, and clad in the same old ruin of rags that had made him picturesque in the days when he was free and happy.', '他衣服脏乱，头发没梳。身上穿着和以前一样的破烂衣服。以前他自由开心的时候，这些衣服让他看起来很特别。'),
    (35, 1829, 4984, 'Tom routed him out, told him the trouble he had been causing, and urged him to go home.', '汤姆把他叫起来，告诉他惹了什么麻烦，然后让他回家。'),
    (35, 1829, 4985, 'Huck’s face lost its tranquil content, and took a melancholy cast.', '哈克的脸上没有了平静开心的表情，变得有些伤心。'),
    (35, 1829, 4986, 'He said:', '他说：'),
    (35, 1830, 4987, '“Don’t talk about it, Tom.', '“别说了，汤姆。'),
    (35, 1830, 4988, 'I’ve tried it, and it don’t work; it don’t work, Tom.', '我试过了，不行；不行啊，汤姆。'),
    (35, 1830, 4989, 'It ain’t for me; I ain’t used to it.', '那不适合我；我不习惯。'),
    (35, 1830, 4990, 'The widder’s good to me, and friendly; but I can’t stand them ways.', '寡妇对我很好，很友善；但我受不了那些规矩。'),
    (35, 1830, 4991, 'She makes me get up just at the same time every morning; she makes me wash, they comb me all to thunder; she won’t let me sleep in the woodshed; I got to wear them blamed clothes that just smothers me, Tom; they don’t seem to any air git through ’em, somehow; and they’re so rotten nice that I can’t set down, nor lay down, nor roll around anywher’s; I hain’t slid on a cellar-door for—well, it ’pears to be years; I got to go to church and sweat and sweat—I hate them ornery sermons!', '她让我每天早上都准时起床；她让我洗漱，他们给我梳头梳得要命；她不让我睡在柴棚里；我得穿那些烦人的衣服，闷死我了，汤姆；它们好像一点都不透气；而且那些衣服太‘好’了，我不能坐着、躺着，也不能随便打滚；我好多年没在地下室门上滑下来玩了——好像好多年了；我必须去教堂，热得要命——我讨厌那些无聊的布道！'),
    (35, 1830, 4992, 'I can’t ketch a fly in there, I can’t chaw.', '我在那里面不能抓苍蝇，也不能嚼东西。'),
    (35, 1830, 4993, 'I got to wear shoes all Sunday.', '我整个星期天都得穿鞋。'),
    (35, 1830, 4994, 'The widder eats by a bell; she goes to bed by a bell; she gits up by a bell—everything’s so awful reg’lar a body can’t stand it.”', '寡妇吃饭听铃声；睡觉听铃声；起床也听铃声——所有事情都太有规矩了，我受不了。”'),
    (35, 1831, 4995, '“Well, everybody does that way, Huck.”', '“嗯，大家都是那样的，哈克。”'),
    (35, 1832, 4996, '“Tom, it don’t make no difference.', '“汤姆，那没用。'),
    (35, 1832, 4997, 'I ain’t everybody, and I can’t _stand_ it.', '我不是大家，我受不了。'),
    (35, 1832, 4998, 'It’s awful to be tied up so.', '这样被绑着太可怕了。'),
    (35, 1832, 4999, 'And grub comes too easy—I don’t take no interest in vittles, that way.', '而且食物来得太容易了——那样一来，我对吃的就没兴趣了。'),
    (35, 1832, 5000, 'I got to ask to go a-fishing; I got to ask to go in a-swimming—dern’d if I hain’t got to ask to do everything.', '我想去钓鱼得先问；我想去游泳也得问——天哪，我做什么都得问！'),
    (35, 1832, 5001, 'Well, I’d got to talk so nice it wasn’t no comfort—I’d got to go up in the attic and rip out awhile, every day, to git a taste in my mouth, or I’d a died, Tom.', '唉，我得说得那么礼貌，一点都不舒服——我每天都得去阁楼上，大声抱怨一会儿，才能让我心里好受点，不然我非死不可，汤姆。'),
    (35, 1832, 5002, 'The widder wouldn’t let me smoke; she wouldn’t let me yell, she wouldn’t let me gape, nor stretch, nor scratch, before folks—” [Then with a spasm of special irritation and injury]—“And dad fetch it, she prayed all the time!', '寡妇不让我抽烟；不让我大叫；不让我在人前打哈欠、伸懒腰、挠痒痒——” “——而且她老是祷告！'),
    (35, 1832, 5003, 'I never see such a woman!', '我从没见过这样的女人！'),
    (35, 1832, 5004, 'I _had_ to shove, Tom—I just had to.', '我_必须_逃走，汤姆——我就是必须逃。'),
    (35, 1832, 5005, 'And besides, that school’s going to open, and I’d a had to go to it—well, I wouldn’t stand _that_, Tom.', '而且，学校要开学了，我非得去上学——嗯，我才受不了_那个_呢，汤姆。'),
    (35, 1832, 5006, 'Looky-here, Tom, being rich ain’t what it’s cracked up to be.', '听着，汤姆，有钱根本不像大家说得那么好。'),
    (35, 1832, 5007, 'It’s just worry and worry, and sweat and sweat, and a-wishing you was dead all the time.', '只会一直担心，一直辛苦，一直希望自己死了算了。'),
    (35, 1832, 5008, 'Now these clothes suits me, and this bar’l suits me, and I ain’t ever going to shake ’em any more.', '现在这些衣服适合我，这个木桶也适合我，我再也不想换了。'),
    (35, 1832, 5009, 'Tom, I wouldn’t ever got into all this trouble if it hadn’t ’a’ been for that money; now you just take my sheer of it along with your’n, and gimme a ten-center sometimes—not many times, becuz I don’t give a dern for a thing ’thout it’s tollable hard to git—and you go and beg off for me with the widder.”', '汤姆，要不是因为那些钱，我根本不会惹上这么多麻烦；现在你把我的那份钱和你的一起拿走吧，偶尔给我一毛钱就行——别太多次，因为太容易得到的东西我才不在乎——然后你去跟寡妇说说，让她别再管我了。”'),
    (35, 1833, 5010, '“Oh, Huck, you know I can’t do that.', '“哦，哈克，你知道我不能那么做。”'),
    (35, 1833, 5011, '’Tain’t fair; and besides if you’ll try this thing just a while longer you’ll come to like it.”', '“这不公平！你再玩一会儿这个，就会喜欢的。”'),
    (35, 1834, 5012, '“Like it!', '“喜欢它？！'),
    (35, 1834, 5013, 'Yes—the way I’d like a hot stove if I was to set on it long enough.', '是啊——如果我一直坐在一个热炉子上，我也会‘喜欢’它的。'),
    (35, 1834, 5014, 'No, Tom, I won’t be rich, and I won’t live in them cussed smothery houses.', '不，汤姆，我才不要变有钱呢，我也不要住那些闷闷的房子。'),
    (35, 1834, 5015, 'I like the woods, and the river, and hogsheads, and I’ll stick to ’em, too.', '我喜欢树林、小河和那些大木桶，我还要一直待在它们身边。'),
    (35, 1834, 5016, 'Blame it all! just as we’d got guns, and a cave, and all just fixed to rob, here this dern foolishness has got to come up and spile it all!”', '真是的！我们刚弄好枪，找到一个山洞，准备去‘打劫’了，结果这件傻事就来了，把一切都搞砸了！”'),
    (35, 1835, 5017, 'Tom saw his opportunity—', '汤姆看到了机会——'),
    (35, 1836, 5018, '“Lookyhere, Huck, being rich ain’t going to keep me back from turning robber.”', '“看这里，哈克，有钱可不会让我不做‘强盗’的。”'),
    (35, 1837, 5019, '“No!', '“真的吗？！'),
    (35, 1837, 5020, 'Oh, good-licks; are you in real dead-wood earnest, Tom?”', '哦，太棒了！汤姆，你真是认真的吗？”'),
    (35, 1838, 5021, '“Just as dead earnest as I’m sitting here.', '“我像坐在这里一样认真。'),
    (35, 1838, 5022, 'But Huck, we can’t let you into the gang if you ain’t respectable, you know.”', '但是哈克，如果你不是个‘好孩子’，我们就不能让你加入我们的队伍哦。”'),
    (35, 1839, 5023, 'Huck’s joy was quenched.', '哈克的开心劲儿一下就没了。'),
    (35, 1840, 5024, '“Can’t let me in, Tom?', '“不让我加入吗，汤姆？'),
    (35, 1840, 5025, 'Didn’t you let me go for a pirate?”', '你不是让我去做海盗了吗？”'),
    (35, 1841, 5026, '“Yes, but that’s different.', '“是啊，但是那不一样。'),
    (35, 1841, 5027, 'A robber is more high-toned than what a pirate is—as a general thing.', '‘强盗’一般比‘海盗’更厉害一些。'),
    (35, 1841, 5028, 'In most countries they’re awful high up in the nobility—dukes and such.”', '在很多国家，他们都是很高的贵族——比如公爵什么的。”'),
    (35, 1842, 5029, '“Now, Tom, hain’t you always ben friendly to me?', '“汤姆，你不是一直都是我的好朋友吗？'),
    (35, 1842, 5030, 'You wouldn’t shet me out, would you, Tom?', '你不会把我赶出去的，对不对，汤姆？'),
    (35, 1842, 5031, 'You wouldn’t do that, now, _would_ you, Tom?”', '你现在不会那么做的，是吗，汤姆？”'),
    (35, 1843, 5032, '“Huck, I wouldn’t want to, and I _don’t_ want to—but what would people say?', '“哈克，我也不想那样做，我真的不想——但是别人会怎么说呢？'),
    (35, 1843, 5033, 'Why, they’d say, ‘Mph!', '他们会说，‘哼！'),
    (35, 1843, 5034, 'Tom Sawyer’s Gang! pretty low characters in it!’', '汤姆·索亚的队伍里都是些不好的家伙！’'),
    (35, 1843, 5035, 'They’d mean you, Huck.', '他们说的就是你，哈克。'),
    (35, 1843, 5036, 'You wouldn’t like that, and I wouldn’t.”', '你不会喜欢那样，我也不会。”'),
    (35, 1844, 5037, 'Huck was silent for some time, engaged in a mental struggle.', '哈克安静了一会儿，心里在想事情。'),
    (35, 1844, 5038, 'Finally he said:', '最后他说：'),
    (35, 1845, 5039, '“Well, I’ll go back to the widder for a month and tackle it and see if I can come to stand it, if you’ll let me b’long to the gang, Tom.”', '“好吧，我回寡妇那里住一个月，试着看看我能不能习惯。如果你让我加入你们的队伍，汤姆。”'),
    (35, 1846, 5040, '“All right, Huck, it’s a whiz!', '“太好了，哈克，真是太棒了！”'),
    (35, 1846, 5041, 'Come along, old chap, and I’ll ask the widow to let up on you a little, Huck.”', '来吧，老伙计，我会叫寡妇对你松一点的，哈克。'),
    (35, 1847, 5042, '“Will you, Tom—now will you?', '你会吗，汤姆——你真的会吗？'),
    (35, 1847, 5043, 'That’s good.', '那太好了。'),
    (35, 1847, 5044, 'If she’ll let up on some of the roughest things, I’ll smoke private and cuss private, and crowd through or bust.', '要是她能少管那些最烦人的事，我就偷偷抽烟，偷偷骂人，我一定要挺过去，不然就完蛋。'),
    (35, 1847, 5045, 'When you going to start the gang and turn robbers?”', '你什么时候组个帮派，去当强盗啊？'),
    (35, 1848, 5046, '“Oh, right off.', '哦，马上就去。'),
    (35, 1848, 5047, 'We’ll get the boys together and have the initiation tonight, maybe.”', '我们会把伙伴们召集起来，可能今晚就搞入伙仪式。'),
    (35, 1849, 5048, '“Have the which?”', '搞什么？'),
    (35, 1850, 5049, '“Have the initiation.”', '搞入伙仪式啊。'),
    (35, 1851, 5050, '“What’s that?”', '那是什么？'),
    (35, 1852, 5051, '“It’s to swear to stand by one another, and never tell the gang’s secrets, even if you’re chopped all to flinders, and kill anybody and all his family that hurts one of the gang.”', '就是要发誓大家互相帮助，绝不告诉帮派的秘密，就算被砍成碎片也不说，还要杀了所有伤害我们帮派的人和他们的家人。'),
    (35, 1853, 5052, '“That’s gay—that’s mighty gay, Tom, I tell you.”', '那太棒了——那真是超级棒啊，汤姆，我告诉你。'),
    (35, 1854, 5053, '“Well, I bet it is.', '嗯，那当然了。'),
    (35, 1854, 5054, 'And all that swearing’s got to be done at midnight, in the lonesomest, awfulest place you can find—a ha’nted house is the best, but they’re all ripped up now.”', '而且所有的发誓都得在半夜，在你能找到的最孤独、最可怕的地方进行——鬼屋是最好的，但是现在都被拆掉了。'),
    (35, 1855, 5055, '“Well, midnight’s good, anyway, Tom.”', '嗯，半夜也挺好的，汤姆。'),
    (35, 1856, 5056, '“Yes, so it is.', '是啊，就是这样。'),
    (35, 1856, 5057, 'And you’ve got to swear on a coffin, and sign it with blood.”', '而且你还得对着棺材发誓，用血来签名。'),
    (35, 1857, 5058, '“Now, that’s something _like_!', '这才有意思！'),
    (35, 1857, 5059, 'Why, it’s a million times bullier than pirating.', '哎呀，这可比当海盗好玩一百万倍！'),
    (35, 1857, 5060, 'I’ll stick to the widder till I rot, Tom; and if I git to be a reg’lar ripper of a robber, and everybody talking ’bout it, I reckon she’ll be proud she snaked me in out of the wet.”', '我会一直跟着寡妇，不会离开的，汤姆；如果我变成一个真正厉害的强盗，人人都谈论我，我想她会为收留我而骄傲的。'),
    (35, 1858, 5061, 'CONCLUSION', '结局'),
    (35, 1859, 5062, 'So endeth this chronicle.', '这个故事就到这里了。'),
    (35, 1859, 5063, 'It being strictly a history of a _boy_, it must stop here; the story could not go much further without becoming the history of a _man_.', '它只是一个关于_男孩_的故事，所以必须在这里停下来；如果继续下去，就会变成一个关于_大人_的故事了。'),
    (35, 1859, 5064, 'When one writes a novel about grown people, he knows exactly where to stop—that is, with a marriage; but when he writes of juveniles, he must stop where he best can.', '当一个人写关于大人的故事时，他知道在哪里停下——那就是结婚的时候；但是当他写关于小孩的故事时，就必须在能停下的地方停下来。'),
    (35, 1860, 5065, 'Most of the characters that perform in this book still live, and are prosperous and happy.', '这本书里的大多数人物都还活着，过得很好，也很开心。'),
    (35, 1860, 5066, 'Some day it may seem worth while to take up the story of the younger ones again and see what sort of men and women they turned out to be; therefore it will be wisest not to reveal any of that part of their lives at present.', '也许有一天，会觉得值得再写写那些小家伙们的故事，看看他们都变成了什么样的大人；所以现在最好不要透露他们生活中那一部分的事情。')
) AS v(chapter_idx, para_idx, seq, text_en, text_cn)
WHERE b.book_key = 'tom-sawyer';

SELECT 'after' AS phase,
       (SELECT sentence_count FROM public.library_books WHERE book_key = 'tom-sawyer') AS book_sentence_count,
       (SELECT count(*) FROM public.library_sentences s
          JOIN public.library_books b ON b.id = s.book_id
         WHERE b.book_key = 'tom-sawyer') AS sentence_rows;

COMMIT;

-- 审核通过后,单独跑这一行让样书对用户可见(软上线):
-- UPDATE public.library_books SET is_published = true WHERE book_key = 'tom-sawyer';
